        private static void AddInfo(UnityEngine.UIElements.VisualElement parent, string text)
        {
            var box = new UnityEngine.UIElements.Label(text);
            box.style.whiteSpace = UnityEngine.UIElements.WhiteSpace.Normal;
            box.style.backgroundColor = new Color(0.18f, 0.20f, 0.23f, 0.35f);
            box.style.borderTopWidth = 1; box.style.borderBottomWidth = 1;
            box.style.borderLeftWidth = 1; box.style.borderRightWidth = 1;
            box.style.borderTopColor = new Color(0.35f, 0.38f, 0.44f, 0.8f);
            box.style.borderBottomColor = new Color(0.35f, 0.38f, 0.44f, 0.8f);
            box.style.borderLeftColor = new Color(0.35f, 0.38f, 0.44f, 0.8f);
            box.style.borderRightColor = new Color(0.35f, 0.38f, 0.44f, 0.8f);
            box.style.paddingTop = 6; box.style.paddingBottom = 6;
            box.style.paddingLeft = 8; box.style.paddingRight = 8;
            box.style.marginBottom = 6;
            parent.Add(box);
        }

        private static void AddSpacer(UnityEngine.UIElements.VisualElement parent, float height)
        {
            var spacer = new UnityEngine.UIElements.VisualElement();
            spacer.style.height = height;
            parent.Add(spacer);
        }

        private static void AddWizardButton(UnityEngine.UIElements.VisualElement parent, string text, System.Action action, float height)
        {
            var button = new UnityEngine.UIElements.Button(() => QueueWizardAction(action)) { text = text };
            button.style.height = height;
            button.style.marginBottom = 4;
            button.style.unityFontStyleAndWeight = FontStyle.Bold;
            parent.Add(button);
        }

        private static void QueueWizardAction(System.Action action)
        {
            if (action == null) return;
            EditorApplication.delayCall += () =>
            {
                try { action.Invoke(); }
                catch (System.Exception ex) { Debug.LogException(ex); }
            };
        }

        // ===== Asset creation =====
        private void CreateAllAssets()
        {
            EnsureFolders();

            // --- Items first (materials reference them) ---
            var itemMap = new System.Collections.Generic.Dictionary<MaterialId, ItemDefinition>();
            void MakeItem(MaterialId id, string display)
            {
                string path = $"{ITEM_FOLDER}/Item_{id}.asset";

                // Special-case Coal: it must be a ResourceItem so it works as fuel in the
                // Solid Fuel Furnace and the Coal Generator. Delete any stale plain
                // ItemDefinition asset at the same path first.
                if (id == MaterialId.Coal)
                {
                    var existing = AssetDatabase.LoadAssetAtPath<UnityEngine.Object>(path);
                    if (existing != null && !(existing is VoxelEngine.Items.ResourceItem))
                        AssetDatabase.DeleteAsset(path);

                    var coalRes = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>(path);
                    if (coalRes == null)
                    {
                        coalRes = ScriptableObject.CreateInstance<VoxelEngine.Items.ResourceItem>();

                    }
                    coalRes.itemId        = "coal";
                    coalRes.displayName   = "Coal";
                    coalRes.description   = "Burns for 8 seconds in a Solid Fuel Furnace or fuels a Coal Generator.";
                    coalRes.iconTint      = new Color(0.12f, 0.12f, 0.13f);
                    coalRes.maxStack      = 999;
                    coalRes.massPerUnit   = 1f;
                    coalRes.category      = "Resources";
                    coalRes.subcategory   = VoxelEngine.Items.ResourceCategory.Fuel;
                    coalRes.fuelSeconds   = 8f;
                    EditorUtility.SetDirty(coalRes);
                    itemMap[id] = coalRes;
                    return;
                }

                var item = AssetDatabase.LoadAssetAtPath<ItemDefinition>(path);
                if (item == null)
                {
                    item = ScriptableObject.CreateInstance<ItemDefinition>();
                    AssetDatabase.CreateAsset(item, path);
                }
                item.itemId = id == MaterialId.Clay ? "dirt" : id.ToString().ToLower();
                item.displayName = display;
                item.maxStack = 999;
                item.massPerUnit = 1f;
                EditorUtility.SetDirty(item);
                itemMap[id] = item;
            }
            MakeItem(MaterialId.Stone,     "Stone");
            MakeItem(MaterialId.Sand,      "Sand");
            MakeItem(MaterialId.Clay,      "Dirt");
            MakeItem(MaterialId.Ice,       "Ice");
            MakeItem(MaterialId.Iron,      "Iron Ore");
            MakeItem(MaterialId.Copper,    "Copper Ore");
            MakeItem(MaterialId.Coal,      "Coal");
            MakeItem(MaterialId.Nickel,    "Nickel Ore");
            MakeItem(MaterialId.Silicon,   "Silicon Wafers");
            MakeItem(MaterialId.Cobalt,    "Cobalt Ore");
            MakeItem(MaterialId.Silver,    "Silver Ore");
            MakeItem(MaterialId.Gold,      "Gold Ore");
            MakeItem(MaterialId.Magnesium, "Magnesium Ore");
            MakeItem(MaterialId.Platinum,  "Platinum Ore");
            MakeItem(MaterialId.Uranium,   "Uranium Ore");
            MakeItem(MaterialId.CrudeOil,  "Crude Oil");

            // --- Materials ---
            string registryPath = $"{ASSET_ROOT}/MaterialRegistry.asset";
            var registry = AssetDatabase.LoadAssetAtPath<MaterialRegistry>(registryPath);
            if (registry == null)
            {
                registry = ScriptableObject.CreateInstance<MaterialRegistry>();
                AssetDatabase.CreateAsset(registry, registryPath);
            }
            registry.definitions.Clear();

            VoxelMaterialDefinition Make(MaterialId id, string name, Color color, float hardness,
                                         ItemDefinition drop, bool fluid = false, bool mineable = true)
            {
                string path = $"{MAT_FOLDER}/Mat_{id}.asset";
                var def = AssetDatabase.LoadAssetAtPath<VoxelMaterialDefinition>(path);
                if (def == null)
                {
                    def = ScriptableObject.CreateInstance<VoxelMaterialDefinition>();
                    AssetDatabase.CreateAsset(def, path);
                }
                def.id = id;
                def.displayName = name;
                def.color = color;
                def.hardness = hardness;
                def.dropItem = drop;
                def.dropAmount = 1;
                def.isFluid = fluid;
                def.isMineable = mineable;
                EditorUtility.SetDirty(def);
                registry.definitions.Add(def);
                return def;
            }

            Make(MaterialId.Air,        "Air",         new Color(0,0,0,0), 0f, null, fluid:false, mineable:false);
            Make(MaterialId.Stone,      "Stone",       new Color(0.45f,0.42f,0.40f), 1.0f, itemMap[MaterialId.Stone]);
            Make(MaterialId.Sand,       "Sand",        new Color(0.92f,0.84f,0.55f), 0.4f, itemMap[MaterialId.Sand]);
            Make(MaterialId.Clay,       "Clay/Dirt",   new Color(0.40f,0.27f,0.16f), 0.6f, itemMap[MaterialId.Clay]);
            Make(MaterialId.Grass,      "Grass/Dirt",  new Color(0.24f,0.52f,0.18f), 0.4f, itemMap[MaterialId.Clay]);
            Make(MaterialId.Ice,        "Ice",         new Color(0.78f,0.92f,0.98f), 0.7f, itemMap[MaterialId.Ice]);
            Make(MaterialId.WaterVoxel, "Water (Voxel)", new Color(0.15f,0.35f,0.7f,0.85f), 0.1f, null, fluid:true, mineable:false);
            Make(MaterialId.WaterLiquid,"Water (Liquid)",new Color(0.15f,0.35f,0.7f,0.85f), 0.1f, null, fluid:true, mineable:false);
            Make(MaterialId.Iron,       "Iron Ore",    new Color(0.55f,0.40f,0.35f), 1.5f, itemMap[MaterialId.Iron]);
            Make(MaterialId.Copper,     "Copper Ore",  new Color(0.72f,0.45f,0.20f), 1.6f, itemMap[MaterialId.Copper]);
            Make(MaterialId.Coal,       "Coal",        new Color(0.12f,0.12f,0.13f), 1.2f, itemMap[MaterialId.Coal]);
            Make(MaterialId.Nickel,     "Nickel Ore",  new Color(0.70f,0.72f,0.65f), 2.0f, itemMap[MaterialId.Nickel]);
            Make(MaterialId.Silicon,    "Silicon Ore", new Color(0.60f,0.60f,0.70f), 1.4f, itemMap[MaterialId.Silicon]);
            Make(MaterialId.Cobalt,     "Cobalt Ore",  new Color(0.20f,0.35f,0.65f), 2.5f, itemMap[MaterialId.Cobalt]);
            Make(MaterialId.Silver,     "Silver Ore",  new Color(0.85f,0.86f,0.88f), 2.8f, itemMap[MaterialId.Silver]);
            Make(MaterialId.Gold,       "Gold Ore",    new Color(0.95f,0.78f,0.20f), 3.0f, itemMap[MaterialId.Gold]);
            Make(MaterialId.Magnesium,  "Magnesium",   new Color(0.85f,0.84f,0.78f), 1.8f, itemMap[MaterialId.Magnesium]);
            Make(MaterialId.Platinum,   "Platinum Ore",new Color(0.78f,0.80f,0.82f), 3.5f, itemMap[MaterialId.Platinum]);
            Make(MaterialId.Uranium,    "Uranium Ore", new Color(0.30f,0.55f,0.20f), 4.0f, itemMap[MaterialId.Uranium]);
            Make(MaterialId.CrudeOil,   "Crude Oil",   new Color(0.05f,0.04f,0.03f), 0.8f, itemMap[MaterialId.CrudeOil], fluid:true);

            // ── Celestial world surface materials (Phase 2) — mine → Stone
            Make(MaterialId.MartianDust,    "Martian Dust",    new Color(0.62f,0.34f,0.20f), 0.5f, itemMap[MaterialId.Stone]);
            Make(MaterialId.VenusAsh,       "Venus Ash",       new Color(0.72f,0.62f,0.26f), 0.5f, itemMap[MaterialId.Stone]);
            Make(MaterialId.AcidBog,        "Acid Bog",        new Color(0.40f,0.52f,0.24f), 0.5f, itemMap[MaterialId.Stone]);
            Make(MaterialId.VolcanicBasalt, "Volcanic Basalt", new Color(0.14f,0.12f,0.13f), 1.2f, itemMap[MaterialId.Stone]);
            Make(MaterialId.CrystalGeode,   "Crystal Geode",   new Color(0.56f,0.48f,0.84f), 0.9f, itemMap[MaterialId.Stone]);

            EditorUtility.SetDirty(registry);

            // --- Biomes ---
            string biomeRegistryPath = $"{ASSET_ROOT}/BiomeRegistry.asset";
            var biomeRegistry = AssetDatabase.LoadAssetAtPath<BiomeRegistry>(biomeRegistryPath);
            if (biomeRegistry == null)
            {
                biomeRegistry = ScriptableObject.CreateInstance<BiomeRegistry>();
                AssetDatabase.CreateAsset(biomeRegistry, biomeRegistryPath);
            }
            biomeRegistry.biomes.Clear();

            BiomeDefinition MakeBiome(string name, Color dbg,
                float tMin, float tMax, float hMin, float hMax,
                int prio,
                float hOff, float hAmp, float hFreq, float ridge,
                MaterialId surf, int surfDepth,
                MaterialId sub,  int subDepth,
                bool beach, bool ocean)
            {
                string path = $"{BIOME_FOLDER}/Biome_{name}.asset";
                var b = AssetDatabase.LoadAssetAtPath<BiomeDefinition>(path);
                if (b == null)
                {
                    b = ScriptableObject.CreateInstance<BiomeDefinition>();
                    AssetDatabase.CreateAsset(b, path);
                }
                b.biomeName = name;
                b.debugColor = dbg;
                b.minTemperature = tMin; b.maxTemperature = tMax;
                b.minHumidity    = hMin; b.maxHumidity    = hMax;
                b.priority = prio;
                b.heightOffset = hOff; b.heightAmplitude = hAmp;
                b.heightFrequency = hFreq; b.ridgedness = ridge;
                b.surfaceMaterial = surf;     b.surfaceDepth = surfDepth;
                b.subsurfaceMaterial = sub;   b.subsurfaceDepth = subDepth;
                b.allowBeach = beach;         b.isOceanic = ocean;
                EditorUtility.SetDirty(b);
                biomeRegistry.biomes.Add(b);
                return b;
            }

            //          name        debug-color           T-range     H-range    prio  hOff  hAmp  hFreq   ridge  surf            sd  sub             sd2  beach ocean
            MakeBiome("Ocean",      new Color(0.10f,0.30f,0.55f),  0.00f,1.00f, 0.00f,1.00f,  0, -25f,  6f, 0.020f, 0.0f, MaterialId.Sand,    1, MaterialId.Sand,    3, false, true);
            MakeBiome("Beach",      new Color(0.95f,0.88f,0.60f),  0.30f,0.80f, 0.00f,1.00f,  3,   0f,  3f, 0.040f, 0.0f, MaterialId.Sand,    2, MaterialId.Sand,    4, true,  false);
            MakeBiome("Plains",     new Color(0.40f,0.75f,0.35f),  0.30f,0.70f, 0.30f,0.65f,  1,   2f, 10f, 0.020f, 0.0f, MaterialId.Clay,    1, MaterialId.Clay,    5, true,  false);
            // Steppes: dead-flat grassland with almost no vegetation. Player-friendly base-building biome.
            MakeBiome("Steppes",    new Color(0.70f,0.75f,0.50f),  0.45f,0.75f, 0.25f,0.55f,  2,   1f,  2f, 0.012f, 0.0f, MaterialId.Clay,    1, MaterialId.Clay,    4, true,  false);
            MakeBiome("Forest",     new Color(0.18f,0.45f,0.20f),  0.30f,0.65f, 0.55f,0.95f,  2,   6f, 18f, 0.018f, 0.2f, MaterialId.Clay,    1, MaterialId.Clay,    5, true,  false);
            MakeBiome("Desert",     new Color(0.93f,0.83f,0.45f),  0.65f,1.00f, 0.00f,0.30f,  2,   3f, 14f, 0.025f, 0.1f, MaterialId.Sand,    2, MaterialId.Sand,    6, true,  false);
            MakeBiome("Wasteland",  new Color(0.55f,0.45f,0.35f),  0.55f,0.80f, 0.20f,0.45f,  1,   4f, 20f, 0.030f, 0.4f, MaterialId.Clay,    1, MaterialId.Stone,   3, true,  false);
            MakeBiome("Tundra",     new Color(0.85f,0.92f,0.95f),  0.00f,0.30f, 0.30f,0.85f,  2,   1f,  8f, 0.020f, 0.1f, MaterialId.Ice,     1, MaterialId.Clay,    4, true,  false);
            MakeBiome("Mountains",  new Color(0.55f,0.55f,0.60f),  0.20f,0.70f, 0.20f,0.85f,  4,  35f, 60f, 0.015f, 0.85f,MaterialId.Stone,   1, MaterialId.Stone,   8, false, false);
            MakeBiome("SnowyPeaks", new Color(0.95f,0.97f,1.00f),  0.00f,0.25f, 0.30f,0.85f,  5,  45f, 65f, 0.014f, 0.90f,MaterialId.Ice,     2, MaterialId.Stone,   8, false, false);

            // --- Scatter prefabs (procedural, share materials so GPU Resident Drawer batches them) ---
            string scatterFolder = ASSET_ROOT + "/Scatter";
            if (!AssetDatabase.IsValidFolder(scatterFolder))
                AssetDatabase.CreateFolder(ASSET_ROOT, "Scatter");

            Material trunkMat   = MakeColoredMat(scatterFolder, "Mat_Trunk",   new Color(0.30f,0.20f,0.10f));
            Material leafMatA   = MakeColoredMat(scatterFolder, "Mat_LeafOak", new Color(0.18f,0.45f,0.20f));
            Material leafMatB   = MakeColoredMat(scatterFolder, "Mat_LeafPine",new Color(0.10f,0.32f,0.18f));
            Material rockMat    = MakeColoredMat(scatterFolder, "Mat_Rock",    new Color(0.50f,0.48f,0.46f));
            Material cactusMat  = MakeColoredMat(scatterFolder, "Mat_Cactus",  new Color(0.30f,0.55f,0.32f));
            Material deadMat    = MakeColoredMat(scatterFolder, "Mat_DeadWood",new Color(0.42f,0.30f,0.22f));
            Material snowRock   = MakeColoredMat(scatterFolder, "Mat_SnowRock",new Color(0.85f,0.88f,0.92f));

            GameObject treeOak    = MakeTreePrefab(scatterFolder, "Tree_Oak",    trunkMat,  leafMatA, 1.0f, 1.6f, false);
            GameObject treePine   = MakeTreePrefab(scatterFolder, "Tree_Pine",   trunkMat,  leafMatB, 1.4f, 1.0f, true);
            GameObject treeDead   = MakeTreePrefab(scatterFolder, "Tree_Dead",   deadMat,   deadMat,  1.1f, 0.4f, false);
            GameObject rockSmall  = MakeRockPrefab(scatterFolder, "Rock_Small",  rockMat,   0.6f);
            GameObject rockLarge  = MakeRockPrefab(scatterFolder, "Rock_Large",  rockMat,   1.6f);
            GameObject cactus     = MakeCactusPrefab(scatterFolder, "Cactus",    cactusMat);
            GameObject snowRockGo = MakeRockPrefab(scatterFolder, "Rock_Snow",   snowRock, 1.0f);

            // Helper to apply scatter entries to a named biome.
            void Apply(string biomeName, params BiomeDefinition.ScatterEntry[] entries)
            {
                foreach (var b in biomeRegistry.biomes)
                    if (b.biomeName == biomeName) { b.scatter = entries; EditorUtility.SetDirty(b); break; }
            }

            Apply("Forest",
                new BiomeDefinition.ScatterEntry { prefab = treeOak,   density = 0.10f, minScale = 0.9f, maxScale = 1.5f, minHeight = 0,   maxHeight = 9999 },
                new BiomeDefinition.ScatterEntry { prefab = treePine,  density = 0.04f, minScale = 1.0f, maxScale = 1.8f, minHeight = 0,   maxHeight = 9999 },
                new BiomeDefinition.ScatterEntry { prefab = rockSmall, density = 0.02f, minScale = 0.5f, maxScale = 1.2f, minHeight = 0,   maxHeight = 9999 });

            Apply("Plains",
                new BiomeDefinition.ScatterEntry { prefab = treeOak,   density = 0.012f,minScale = 0.8f, maxScale = 1.3f, minHeight = 0,   maxHeight = 9999 },
                new BiomeDefinition.ScatterEntry { prefab = rockSmall, density = 0.006f,minScale = 0.4f, maxScale = 1.0f, minHeight = 0,   maxHeight = 9999 });

            Apply("Wasteland",
                new BiomeDefinition.ScatterEntry { prefab = treeDead,  density = 0.03f, minScale = 0.8f, maxScale = 1.4f, minHeight = 0,   maxHeight = 9999 },
                new BiomeDefinition.ScatterEntry { prefab = rockLarge, density = 0.02f, minScale = 0.7f, maxScale = 1.6f, minHeight = 0,   maxHeight = 9999 },
                new BiomeDefinition.ScatterEntry { prefab = rockSmall, density = 0.04f, minScale = 0.4f, maxScale = 1.1f, minHeight = 0,   maxHeight = 9999 });

            Apply("Desert",
                new BiomeDefinition.ScatterEntry { prefab = cactus,    density = 0.02f, minScale = 0.8f, maxScale = 1.5f, minHeight = 0,   maxHeight = 9999 },
                new BiomeDefinition.ScatterEntry { prefab = rockSmall, density = 0.01f, minScale = 0.4f, maxScale = 0.9f, minHeight = 0,   maxHeight = 9999 });

            Apply("Tundra",
                new BiomeDefinition.ScatterEntry { prefab = treePine,  density = 0.015f,minScale = 0.7f, maxScale = 1.2f, minHeight = 0,   maxHeight = 9999 },
                new BiomeDefinition.ScatterEntry { prefab = snowRockGo,density = 0.03f, minScale = 0.5f, maxScale = 1.4f, minHeight = 0,   maxHeight = 9999 });

            Apply("Mountains",
                new BiomeDefinition.ScatterEntry { prefab = rockLarge, density = 0.04f, minScale = 0.8f, maxScale = 2.0f, minHeight = 0,   maxHeight = 9999 },
                new BiomeDefinition.ScatterEntry { prefab = treePine,  density = 0.01f, minScale = 0.7f, maxScale = 1.2f, minHeight = 0,   maxHeight = 200  });

            Apply("SnowyPeaks",
                new BiomeDefinition.ScatterEntry { prefab = snowRockGo,density = 0.05f, minScale = 0.7f, maxScale = 1.8f, minHeight = 0,   maxHeight = 9999 });

            EditorUtility.SetDirty(biomeRegistry);

            // --- Planet ---
            // PlanetSettings is deprecated — flat world uses inline fields now.
            // (Planet asset creation removed.)

            // --- Terrain material (URP Lit, vertex-colour driven if URP installed) ---
            string terrainMatPath = $"{ASSET_ROOT}/VoxelTerrain.mat";
            Material terrainMat = AssetDatabase.LoadAssetAtPath<Material>(terrainMatPath);
            if (terrainMat == null)
            {
                var litShader = Shader.Find("VoxelEngine/VoxelTerrainURP");
                if (litShader == null) litShader = Shader.Find("Standard");
                terrainMat = new Material(litShader) { name = "VoxelTerrain" };
                terrainMat.color = Color.white;
                AssetDatabase.CreateAsset(terrainMat, terrainMatPath);
            }
            EditorUtility.SetDirty(terrainMat);

            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();
            EditorUtility.DisplayDialog("Voxel Engine",
                "Assets created in Assets/VoxelEngineAssets.\n\n" +
                "NOTE: For vertex-colour-driven terrain, assign a Shader Graph that multiplies BaseColor by VertexColor.\n" +
                "A starter shader graph 'VoxelTerrain.shadergraph' can be created in 4 nodes (see README).",
                "OK");
            Selection.activeObject = registry;
        }

        // ===== Player / UI spawning =====
        private void SpawnManagerAndPlayer()
        {
            var registry = AssetDatabase.LoadAssetAtPath<MaterialRegistry>($"{ASSET_ROOT}/MaterialRegistry.asset");

            // Step 2 no longer creates a world manager. The current game scene is
            // expected to own its world through CosmosBootstrap/SphereWorld or an
            // existing VoxelWorld. We only link the player to whatever world already exists.
            VoxelEngine.Core.IVoxelWorld activeWorld = VoxelEngine.Core.ActiveWorld.Current;
            var flatWorld = Object.FindAnyObjectByType<VoxelEngine.Core.VoxelWorld>();
            var sphereWorld = Object.FindAnyObjectByType<VoxelEngine.Cosmos.SphereWorld>();
            if (activeWorld == null)
            {
                if (flatWorld != null) activeWorld = flatWorld;
                else if (sphereWorld != null) activeWorld = sphereWorld;
                if (activeWorld != null) VoxelEngine.Core.ActiveWorld.Current = activeWorld;
            }

            // ----- Player -----
            var playerGo = new GameObject("Player");
            playerGo.tag = "Player";
            playerGo.transform.position = new Vector3(0, 150, 0);

            // CharacterController for collisions with the voxel mesh.
            var ccp = playerGo.AddComponent<CharacterController>();
            ccp.height = 1.85f;
            ccp.radius = 0.4f;
            ccp.center = new Vector3(0, 0.925f, 0);
            ccp.slopeLimit = 85f;
            ccp.stepOffset = 0.6f;
            ccp.skinWidth = 0.05f;
            ccp.minMoveDistance = 0f;

            var pivotGo = new GameObject("CameraPivot");
            pivotGo.transform.SetParent(playerGo.transform, false);
            pivotGo.transform.localPosition = new Vector3(0, 1.65f, 0);

            var camGo = new GameObject("PlayerCamera");
            camGo.transform.SetParent(pivotGo.transform, false);
            var cam = camGo.AddComponent<Camera>();
            cam.tag = "MainCamera";
            cam.farClipPlane = 1500f;
            camGo.AddComponent<AudioListener>();

            var pc = playerGo.AddComponent<VoxelEngine.Player.PlayerController>();
            playerGo.AddComponent<VoxelEngine.Player.PlayerStats>();
            playerGo.AddComponent<VoxelEngine.Player.PlayerWaterState>();
            playerGo.AddComponent<VoxelEngine.Player.PlayerSpawner>();
            pc.cameraPivot = pivotGo.transform;
            pc.playerCamera = cam;

            var inv = playerGo.AddComponent<VoxelEngine.Items.Inventory>();
            playerGo.AddComponent<VoxelEngine.Player.PlayerEquipment>();
            var pick = camGo.AddComponent<VoxelEngine.Player.PlayerInteractionTool>();
            pick.world = activeWorld;
            pick.registry = registry;
            pick.shootCamera = cam;
            pick.inventory = inv;

            // Held-tool viewmodel + camera-punch feedback on the camera.
            var held = camGo.AddComponent<VoxelEngine.Player.HeldToolView>();
            held.inventory = inv;
            camGo.AddComponent<VoxelEngine.Player.ToolFeedback>();
            var hvTool = camGo.AddComponent<VoxelEngine.Simulation.HighVoltageWireTool>();
            hvTool.playerCamera = cam;
            hvTool.inventory = inv;
            hvTool.stationLayer = 1 << 0;

            // BuildSystem on the player (single-block/static placement system).
            var build = playerGo.AddComponent<VoxelEngine.Building.BuildSystem>();
            build.shootCamera = cam;
            build.inventory = inv;

            // BuildSystemV2 on the player (tiered construction workflow).
            var buildV2 = playerGo.AddComponent<VoxelEngine.Building.Tiered.BuildSystemV2>();
            buildV2.shootCamera = cam;
            buildV2.inventory = inv;
            buildV2.registry = AssetDatabase.LoadAssetAtPath<VoxelEngine.Building.Tiered.TieredBlockRegistry>(
                $"{ASSET_ROOT}/Tiered/TieredBlockRegistry.asset");

            // In-game HUD/UI (inventory + crafting + container panels + hotbar).
            var uiGo = new GameObject("GameUI");
            uiGo.transform.SetParent(playerGo.transform, false);
            var doc = uiGo.AddComponent<UnityEngine.UIElements.UIDocument>();
            doc.sortingOrder = 500;
            var panelSettings = AssetDatabase.LoadAssetAtPath<UnityEngine.UIElements.PanelSettings>(
                "Assets/Resources/MenuPanelSettings.asset");
            if (panelSettings == null)
            {
                EnsureFolder("Assets/Resources");
                panelSettings = ScriptableObject.CreateInstance<UnityEngine.UIElements.PanelSettings>();
                panelSettings.name = "MenuPanelSettings";
                AssetDatabase.CreateAsset(panelSettings, "Assets/Resources/MenuPanelSettings.asset");
            }
            VoxelEngine.Settings.GameSettings.ApplyUiScaleAndFit(panelSettings);
            EditorUtility.SetDirty(panelSettings);
            doc.panelSettings = panelSettings;

            var ui = uiGo.AddComponent<VoxelEngine.UI.GameUIController>();
            ui.inventory = inv;
            ui.recipeRegistry = AssetDatabase.LoadAssetAtPath<VoxelEngine.Crafting.RecipeRegistry>(
                $"{ASSET_ROOT}/RecipeRegistry.asset");

            // Hammer build wheel (radial selector for tiered families).
            var wheelGo = new GameObject("HammerBuildWheel");
            wheelGo.transform.SetParent(playerGo.transform, false);
            var wheelDoc = wheelGo.AddComponent<UnityEngine.UIElements.UIDocument>();
            wheelDoc.sortingOrder = 600;
            wheelDoc.panelSettings = panelSettings;
            var wheel = wheelGo.AddComponent<VoxelEngine.Building.Tiered.HammerBuildWheel>();
            wheel.inventory = inv;
            wheel.registry = AssetDatabase.LoadAssetAtPath<VoxelEngine.Building.Tiered.TieredBlockRegistry>(
                $"{ASSET_ROOT}/Tiered/TieredBlockRegistry.asset");

            // Grid Shape Variant wheel (premium radial selector for armor/grid blocks).
            // Non-destructive: only added if missing.
            var shapeWheelGo = playerGo.transform.Find("GridShapeWheel");
            if (shapeWheelGo == null)
            {
                shapeWheelGo = new GameObject("GridShapeWheel").transform;
                shapeWheelGo.SetParent(playerGo.transform, false);
            }
            var shapeDoc = shapeWheelGo.GetComponent<UnityEngine.UIElements.UIDocument>();
            if (shapeDoc == null) shapeDoc = shapeWheelGo.gameObject.AddComponent<UnityEngine.UIElements.UIDocument>();
            shapeDoc.sortingOrder = 610;
            shapeDoc.panelSettings = panelSettings;
            if (shapeWheelGo.GetComponent<VoxelEngine.UI.GridShapeWheel>() == null)
                shapeWheelGo.gameObject.AddComponent<VoxelEngine.UI.GridShapeWheel>();

            // Grid Screen Config UI (right-click panel for configuring screen data sources).
            var screenConfigGo = playerGo.transform.Find("GridScreenConfigUI");
            if (screenConfigGo == null)
            {
                screenConfigGo = new GameObject("GridScreenConfigUI").transform;
                screenConfigGo.SetParent(playerGo.transform, false);
            }
            var screenConfigDoc = screenConfigGo.GetComponent<UnityEngine.UIElements.UIDocument>();
            if (screenConfigDoc == null) screenConfigDoc = screenConfigGo.gameObject.AddComponent<UnityEngine.UIElements.UIDocument>();
            screenConfigDoc.sortingOrder = 620;
            screenConfigDoc.panelSettings = panelSettings;
            if (screenConfigGo.GetComponent<VoxelEngine.GridSystem.UI.GridScreenConfigUI>() == null)
                screenConfigGo.gameObject.AddComponent<VoxelEngine.GridSystem.UI.GridScreenConfigUI>();

            // Link viewer on whichever world exists. No manager is created here.
            if (flatWorld != null) flatWorld.viewer = playerGo.transform;
            if (sphereWorld != null) sphereWorld.viewer = playerGo.transform;

            // World-state persistence (player position, inventory, placed blocks).
            if (Object.FindAnyObjectByType<VoxelEngine.Persistence.WorldStatePersistence>() == null)
            {
                var stateGo = new GameObject("WorldStatePersistence");
                stateGo.AddComponent<VoxelEngine.Persistence.WorldStatePersistence>();
            }

            // Light
            if (Object.FindAnyObjectByType<Light>() == null)
            {
                var lightGo = new GameObject("Sun");
                lightGo.transform.rotation = Quaternion.Euler(50, -30, 0);
                var lt = lightGo.AddComponent<Light>();
                lt.type = LightType.Directional;
                lt.intensity = 1.2f;
            }

            Selection.activeObject = playerGo;
            EditorUtility.DisplayDialog("Voxel Engine",
                activeWorld != null
                    ? "Player + UI spawned and linked to the existing world. Press Play!"
                    : "Player + UI spawned. No active world was found, so terrain mining/building will link when a world bootstrap sets ActiveWorld.Current.",
                "OK");
        }

        private void BuildMainMenuScene()
        {
            const string menuScenePath = "Assets/MainMenu.unity";
            const string gameScenePath = "Assets/Game.unity";

            // ===== STEP A: ensure the current gameplay scene is saved as Game.unity =====
            var currentScene = UnityEditor.SceneManagement.EditorSceneManager.GetActiveScene();
            bool hasGameplayRoot = false;
            foreach (var go in currentScene.GetRootGameObjects())
            {
                if (go.GetComponentInChildren<VoxelEngine.Player.PlayerController>(true) != null ||
                    go.GetComponentInChildren<VoxelEngine.Cosmos.CosmosBootstrap>(true) != null ||
                    go.GetComponentInChildren<VoxelEngine.Cosmos.SphereWorld>(true) != null ||
                    go.GetComponentInChildren<VoxelEngine.Core.VoxelWorld>(true) != null)
                {
                    hasGameplayRoot = true;
                    break;
                }
            }

            if (!hasGameplayRoot)
            {
                EditorUtility.DisplayDialog("Voxel Engine",
                    "The active scene does not look like a gameplay scene yet.\n\n" +
                    "Run Step 2 to spawn the Player + UI, or open your existing game scene before running this step.", "OK");
                return;
            }

            // Save it as Assets/Game.unity (overwriting if needed).
            UnityEditor.SceneManagement.EditorSceneManager.SaveScene(currentScene, gameScenePath);
            Debug.Log("[Wizard] Saved game scene to " + gameScenePath);

            // Add the pause menu GameObject to the game scene if absent.
            bool hasPauseMenu = false;
            foreach (var go in currentScene.GetRootGameObjects())
                if (go.GetComponent<VoxelEngine.Menu.InGamePauseMenu>() != null) { hasPauseMenu = true; break; }
            if (!hasPauseMenu)
            {
                var pauseGo = new GameObject("PauseMenu");
                pauseGo.AddComponent<UnityEngine.UIElements.UIDocument>();
                pauseGo.AddComponent<VoxelEngine.Menu.InGamePauseMenu>();
                UnityEditor.SceneManagement.EditorSceneManager.SaveScene(currentScene, gameScenePath);
                Debug.Log("[Wizard] Added InGamePauseMenu to Game scene.");
            }

            // ===== STEP B: bake PanelSettings + theme into Resources/ =====
            const string resourcesFolder = "Assets/Resources";
            if (!AssetDatabase.IsValidFolder(resourcesFolder))
                AssetDatabase.CreateFolder("Assets", "Resources");
            const string panelSettingsPath = "Assets/Resources/MenuPanelSettings.asset";

            var panelSettings = AssetDatabase.LoadAssetAtPath<UnityEngine.UIElements.PanelSettings>(panelSettingsPath);
            if (panelSettings == null)
            {
                panelSettings = ScriptableObject.CreateInstance<UnityEngine.UIElements.PanelSettings>();
                panelSettings.name      = "MenuPanelSettings";
                panelSettings.scaleMode = UnityEngine.UIElements.PanelScaleMode.ScaleWithScreenSize;
                panelSettings.referenceResolution = new Vector2Int(1920, 1080);
                panelSettings.match = 0.5f;
                AssetDatabase.CreateAsset(panelSettings, panelSettingsPath);
            }
            // Step 3 is the explicit authoring point for shared UI scaling. Runtime
            // controllers no longer overwrite these values, so Inspector edits made
            // after this step remain under developer control.
            // ScaleWithScreenSize (not ConstantPixelSize): the HUD must fit ANY window —
            // a constant-pixel panel is anchored bottom-left and pushed off-screen on
            // smaller/non-1080p views. Width-priority keeps the HUD large on wide windows.
            panelSettings.scaleMode = UnityEngine.UIElements.PanelScaleMode.ScaleWithScreenSize;
            panelSettings.referenceResolution = new Vector2Int(1920, 1080);
            panelSettings.screenMatchMode = UnityEngine.UIElements.PanelScreenMatchMode.MatchWidthOrHeight;
            panelSettings.match = 0f;
            panelSettings.scale = 1f;
            panelSettings.referenceDpi = 96f;
            panelSettings.fallbackDpi = 96f;
            EditorUtility.SetDirty(panelSettings);

            var serializedPanelSettings = new SerializedObject(panelSettings);
            var maxSubTexture = serializedPanelSettings.FindProperty("m_DynamicAtlasSettings.m_MaxSubTextureSize");
            if (maxSubTexture != null) maxSubTexture.intValue = 256;
            serializedPanelSettings.ApplyModifiedPropertiesWithoutUndo();

            string[] themeCandidates =
            {
                "Assets/UI Toolkit/UnityThemes/UnityDefaultRuntimeTheme.tss",
                "Assets/Resources/UnityDefaultRuntimeTheme.tss",
                "Packages/com.unity.ui/PackageResources/StyleSheets/Generated/Default/UnityDefaultRuntimeTheme.tss",
                "Packages/com.unity.modules.uielements/PackageResources/StyleSheets/Generated/Default/UnityDefaultRuntimeTheme.tss"
            };
            UnityEngine.UIElements.ThemeStyleSheet theme = null;
            foreach (var path in themeCandidates)
            {
                theme = AssetDatabase.LoadAssetAtPath<UnityEngine.UIElements.ThemeStyleSheet>(path);
                if (theme != null) break;
            }
            if (theme == null)
            {
                string[] themeGuids = AssetDatabase.FindAssets("UnityDefaultRuntimeTheme t:ThemeStyleSheet");
                foreach (var guid in themeGuids)
                {
                    string path = AssetDatabase.GUIDToAssetPath(guid);
                    theme = AssetDatabase.LoadAssetAtPath<UnityEngine.UIElements.ThemeStyleSheet>(path);
                    if (theme != null) break;
                }
            }
            if (theme != null)
            {
                panelSettings.themeStyleSheet = theme;
                EditorUtility.SetDirty(panelSettings);
            }
            else
            {
                Debug.LogWarning("[Wizard] UnityDefaultRuntimeTheme.tss not found - menu will be unstyled.");
            }
            const string themeFolder = ASSET_ROOT + "/UI/Themes";
            EnsureFolder(themeFolder);
            const string themeDbFolder = ASSET_ROOT + "/UI";
            EnsureFolder(themeDbFolder);

            void EnsureBuiltInTheme(string assetName, VoxelEngine.UI.BuiltInUITheme themeId, string display, Color accent, Color panel, Color text)
            {
                string path = $"{themeFolder}/{assetName}.asset";
                bool created = AssetDatabase.LoadMainAssetAtPath(path) == null;
                var themeDef = AssetDatabase.LoadAssetAtPath<VoxelEngine.UI.UIThemeDefinition>(path);
                if (themeDef == null)
                {
                    themeDef = ScriptableObject.CreateInstance<VoxelEngine.UI.UIThemeDefinition>();
                    AssetDatabase.CreateAsset(themeDef, path);
                    created = true;
                }

                if (created || string.IsNullOrWhiteSpace(themeDef.displayName)) themeDef.displayName = display;
                if (created) themeDef.builtInTheme = themeId;
                if (created) themeDef.accent = accent;
                if (created) themeDef.panel = panel;
                if (created) themeDef.text = text;
                if (created) themeDef.panelOpacity = panel.a;
                if (created) themeDef.cornerRadius = 12f;
                // New fields — non-destructive: only set when default/zero
                if (themeDef.border == default) themeDef.border = new Color(accent.r, accent.g, accent.b, 0.55f);
                if (themeDef.background == default) themeDef.background = new Color(0.04f, 0.045f, 0.06f, 1f);
                if (themeDef.borderThickness <= 0.01f) themeDef.borderThickness = 1f;
                if (themeDef.accentGlow <= 0.001f) themeDef.accentGlow = 0.28f;
                if (themeDef.backgroundDim <= 0.001f) themeDef.backgroundDim = 0.55f;
                if (themeDef.animationSpeed <= 0.01f) themeDef.animationSpeed = 1f;
                if (themeDef.baseFontSize <= 0.1f) themeDef.baseFontSize = 12f;
                if (string.IsNullOrWhiteSpace(themeDef.description))
                    themeDef.description = VoxelEngine.UI.UIThemeManager.DescriptionFor(themeId);
                if (themeDef.transitionCurve == null || themeDef.transitionCurve.keys.Length == 0)
                    themeDef.transitionCurve = AnimationCurve.EaseInOut(0, 0, 1, 1);
                EditorUtility.SetDirty(themeDef);
            }

            EnsureBuiltInTheme("Theme_IndustrialSteel", VoxelEngine.UI.BuiltInUITheme.IndustrialSteel, "Industrial Steel", new Color(0.18f, 0.72f, 0.88f), new Color(0.08f, 0.088f, 0.12f, 0.97f), new Color(0.92f, 0.94f, 0.97f));
            EnsureBuiltInTheme("Theme_MidnightOperator", VoxelEngine.UI.BuiltInUITheme.MidnightOperator, "Midnight Operator", new Color(0.40f, 0.52f, 0.92f), new Color(0.035f, 0.040f, 0.060f, 0.98f), new Color(0.90f, 0.92f, 0.98f));
            EnsureBuiltInTheme("Theme_HazardAmber", VoxelEngine.UI.BuiltInUITheme.HazardAmber, "Hazard Amber", new Color(0.88f, 0.72f, 0.22f), new Color(0.10f, 0.085f, 0.045f, 0.97f), new Color(0.98f, 0.94f, 0.82f));
            EnsureBuiltInTheme("Theme_ArcticFrost", VoxelEngine.UI.BuiltInUITheme.ArcticFrost, "Arctic Frost", new Color(0.50f, 0.82f, 1.00f), new Color(0.07f, 0.10f, 0.13f, 0.96f), new Color(0.90f, 0.97f, 1.00f));
            EnsureBuiltInTheme("Theme_BioLuminescent", VoxelEngine.UI.BuiltInUITheme.BioLuminescent, "Bio-Luminescent", new Color(0.22f, 0.95f, 0.62f), new Color(0.035f, 0.070f, 0.055f, 0.97f), new Color(0.86f, 1.00f, 0.92f));
            EnsureBuiltInTheme("Theme_MilitaryOlive", VoxelEngine.UI.BuiltInUITheme.MilitaryOlive, "Military Olive", new Color(0.58f, 0.68f, 0.36f), new Color(0.07f, 0.085f, 0.065f, 0.97f), new Color(0.88f, 0.92f, 0.78f));
            EnsureBuiltInTheme("Theme_NeonCyber", VoxelEngine.UI.BuiltInUITheme.NeonCyber, "Neon Cyber", new Color(0.95f, 0.24f, 0.85f), new Color(0.055f, 0.035f, 0.075f, 0.97f), new Color(0.96f, 0.90f, 1.00f));
            EnsureBuiltInTheme("Theme_CorporateClean", VoxelEngine.UI.BuiltInUITheme.CorporateClean, "Corporate Clean", new Color(0.28f, 0.52f, 0.88f), new Color(0.86f, 0.88f, 0.92f, 0.96f), new Color(0.08f, 0.10f, 0.14f));
            EnsureBuiltInTheme("Theme_RustBelt", VoxelEngine.UI.BuiltInUITheme.RustBelt, "Rust Belt", new Color(0.88f, 0.42f, 0.18f), new Color(0.11f, 0.075f, 0.055f, 0.97f), new Color(0.98f, 0.86f, 0.74f));
            EnsureBuiltInTheme("Theme_VoidBlack", VoxelEngine.UI.BuiltInUITheme.VoidBlack, "Void Black", new Color(0.62f, 0.42f, 1.00f), new Color(0.015f, 0.016f, 0.024f, 0.98f), new Color(0.92f, 0.90f, 1.00f));

            // Ensure UIThemeDatabase asset exists (non-destructive)
            string dbPath = $"{ASSET_ROOT}/UI/UIThemeDatabase.asset";
            var db = AssetDatabase.LoadAssetAtPath<VoxelEngine.UI.UIThemeDatabase>(dbPath);
            bool dbCreated = db == null;
            if (dbCreated)
            {
                db = ScriptableObject.CreateInstance<VoxelEngine.UI.UIThemeDatabase>();
                AssetDatabase.CreateAsset(db, dbPath);
                Debug.Log($"[Wizard] Step 3 created theme database: {dbPath}");
            }
            db.themes.Clear();
            foreach (var guid in AssetDatabase.FindAssets("t:UIThemeDefinition", new[] { themeFolder }))
            {
                var p = AssetDatabase.GUIDToAssetPath(guid);
                var d = AssetDatabase.LoadAssetAtPath<VoxelEngine.UI.UIThemeDefinition>(p);
                if (d != null && !db.themes.Contains(d)) db.themes.Add(d);
            }
            // Sort by enum order for consistency
            db.themes.Sort((a, b) => ((int)a.builtInTheme).CompareTo((int)b.builtInTheme));
            EditorUtility.SetDirty(db);
            Debug.Log($"[Wizard] Step 3 updated theme database with {db.themes.Count} themes ({(dbCreated ? "created" : "updated")}).");
            AssetDatabase.SaveAssets();

            foreach (var sceneRoot in currentScene.GetRootGameObjects())
            {
                foreach (var sceneDocument in sceneRoot.GetComponentsInChildren<UnityEngine.UIElements.UIDocument>(true))
                {
                    sceneDocument.panelSettings = panelSettings;
                    EditorUtility.SetDirty(sceneDocument);
                }
            }
            UnityEditor.SceneManagement.EditorSceneManager.SaveScene(currentScene, gameScenePath);
            Debug.Log("[Wizard] Step 3 assigned MenuPanelSettings to every UIDocument in the Game scene.");

            // ===== STEP C: create the MainMenu scene =====
            var menuScene = UnityEditor.SceneManagement.EditorSceneManager.NewScene(
                UnityEditor.SceneManagement.NewSceneSetup.EmptyScene,
                UnityEditor.SceneManagement.NewSceneMode.Single);

            var camGo = new GameObject("UICamera");
            var cam = camGo.AddComponent<Camera>();
            cam.clearFlags = CameraClearFlags.SolidColor;
            cam.backgroundColor = new Color(0.06f, 0.07f, 0.09f, 1f);
            cam.orthographic = true;

            var menuGo = new GameObject("MainMenuController");
            var doc = menuGo.AddComponent<UnityEngine.UIElements.UIDocument>();
            doc.panelSettings = panelSettings;
            var ctrl = menuGo.AddComponent<VoxelEngine.Menu.MainMenuController>();
            ctrl.gameSceneName = "Game";

            UnityEditor.SceneManagement.EditorSceneManager.SaveScene(menuScene, menuScenePath);
            Debug.Log("[Wizard] Saved main menu scene to " + menuScenePath);

            // ===== STEP D: ensure BOTH scenes are in Build Settings, with MainMenu first =====
            var existing = new System.Collections.Generic.List<EditorBuildSettingsScene>(EditorBuildSettings.scenes);
            existing.RemoveAll(s => s.path == menuScenePath || s.path == gameScenePath);
            existing.Insert(0, new EditorBuildSettingsScene(menuScenePath, true));
            existing.Insert(1, new EditorBuildSettingsScene(gameScenePath, true));
            EditorBuildSettings.scenes = existing.ToArray();
            Debug.Log("[Wizard] Build Settings scene list: MainMenu @ index 0, Game @ index 1");

            EditorUtility.DisplayDialog("Voxel Engine",
                "✅ Setup complete!\n\n" +
                "• Game scene saved to " + gameScenePath + "\n" +
                "• Pause menu attached to Game scene\n" +
                "• Main menu scene created at " + menuScenePath + "\n" +
                "• Both scenes added to Build Settings\n\n" +
                "MainMenu is now open. Press Play.", "OK");
        }

        // ============================================================
        //                   STEP 4 - CRAFTING CONTENT
        // ============================================================
        private void BuildBaseCraftingContent()
        {
            const string itemsFolder    = ASSET_ROOT + "/Items";
            const string toolsFolder    = ASSET_ROOT + "/Tools";
            const string blocksFolder   = ASSET_ROOT + "/Blocks";
            const string recipesFolder  = ASSET_ROOT + "/Recipes";
            const string stationsFolder = ASSET_ROOT + "/StationPrefabs";

            // Cleanup of legacy single-tier blocks (replaced by tiered build system).
            string[] legacyAssets =
            {
                ASSET_ROOT + "/Blocks/Block_Foundation.asset",
                ASSET_ROOT + "/Blocks/Block_Wall.asset",
                ASSET_ROOT + "/Recipes/Recipe_Foundation.asset",
                ASSET_ROOT + "/Recipes/Recipe_Wall.asset",
                ASSET_ROOT + "/StationPrefabs/Foundation.prefab",
                ASSET_ROOT + "/StationPrefabs/Wall.prefab"
            };
            foreach (var path in legacyAssets)
                if (AssetDatabase.LoadAssetAtPath<Object>(path) != null)
                    AssetDatabase.DeleteAsset(path);

            EnsureFolder(itemsFolder);
            EnsureFolder(toolsFolder);
            EnsureFolder(blocksFolder);
            EnsureFolder(recipesFolder);
            EnsureFolder(stationsFolder);

            // ----- Resource items (raw / ingots / fuel) -----
            var woodLog       = MakeResource(itemsFolder, "Wood Log",         new Color(0.40f,0.27f,0.16f), 999, VoxelEngine.Items.ResourceCategory.Raw,       fuelSeconds: 4f, uiCategory: "Resources");
            woodLog.description = "Burns for 4 seconds as fuel. Dropped by chopping trees.";
            var plank         = MakeResource(itemsFolder, "Wooden Plank",     new Color(0.55f,0.40f,0.25f), 999, VoxelEngine.Items.ResourceCategory.Component, fuelSeconds: 3f, uiCategory: "Resources");
            plank.description = "Burns for 3 seconds as fuel. Crafted from wood logs (2 planks per log).";
            var coalItem      = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{ITEM_FOLDER}/Item_Coal.asset"); // already exists

            // Coal MUST be a ResourceItem so the furnace fuel-check accepts it. Force-upgrade
            // every time Step 4 runs (idempotent — preserves the path and ID).
            string coalPath = $"{ITEM_FOLDER}/Item_Coal.asset";
            if (coalItem != null && !(coalItem is VoxelEngine.Items.ResourceItem))
            {
                AssetDatabase.DeleteAsset(coalPath);
                coalItem = null;
            }
            var coalRes = coalItem as VoxelEngine.Items.ResourceItem;
            if (coalRes == null)
            {
                coalRes = ScriptableObject.CreateInstance<VoxelEngine.Items.ResourceItem>();
                AssetDatabase.CreateAsset(coalRes, coalPath);
            }
            coalRes.itemId        = "coal";
            coalRes.displayName   = "Coal";
            coalRes.description   = "Burns for 8 seconds in a Solid Fuel Furnace or fuels a Coal Generator.";
            coalRes.iconTint      = new Color(0.12f, 0.12f, 0.13f);
            coalRes.maxStack      = 999;
            coalRes.massPerUnit   = 1f;
            coalRes.category      = "Resources";
            coalRes.subcategory   = VoxelEngine.Items.ResourceCategory.Fuel;
            coalRes.fuelSeconds   = 8f;
            EditorUtility.SetDirty(coalRes);
            coalItem = coalRes;
            // Stone/iron/copper/etc. ItemDefinitions exist in ITEM_FOLDER from step 1.
            var stone = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{ITEM_FOLDER}/Item_Stone.asset");
            var iron  = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{ITEM_FOLDER}/Item_Iron.asset");
            var copper= AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{ITEM_FOLDER}/Item_Copper.asset");
            var nickel= AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{ITEM_FOLDER}/Item_Nickel.asset");

            var ironIngot   = MakeResource(itemsFolder, "Iron Ingot",   new Color(0.78f,0.78f,0.82f), 999, VoxelEngine.Items.ResourceCategory.Ingot, uiCategory: "Ingots");
            var copperIngot = MakeResource(itemsFolder, "Copper Ingot", new Color(0.85f,0.55f,0.30f), 999, VoxelEngine.Items.ResourceCategory.Ingot, uiCategory: "Ingots");
            var steelIngot  = MakeResource(itemsFolder, "Steel Ingot",  new Color(0.55f,0.58f,0.65f), 999, VoxelEngine.Items.ResourceCategory.Ingot, uiCategory: "Ingots");

            // ----- Tool items (pickaxes + axe) -----
            var pickWood  = MakeTool(toolsFolder, "Wooden Pickaxe", VoxelEngine.Items.ToolType.Pickaxe, tier: 1, dur: 60,  strength: 50f, brushRadius: 1.2f);
            var pickStone = MakeTool(toolsFolder, "Stone Pickaxe",  VoxelEngine.Items.ToolType.Pickaxe, tier: 2, dur: 150, strength: 70f, brushRadius: 1.4f);
            var pickIron  = MakeTool(toolsFolder, "Iron Pickaxe",   VoxelEngine.Items.ToolType.Pickaxe, tier: 3, dur: 400, strength: 95f, brushRadius: 1.6f);
            var pickSteel = MakeTool(toolsFolder, "Steel Pickaxe",  VoxelEngine.Items.ToolType.Pickaxe, tier: 4, dur: 900, strength: 130f, brushRadius: 1.8f);
            var axeWood   = MakeTool(toolsFolder, "Wooden Axe",     VoxelEngine.Items.ToolType.Axe,     tier: 1, dur: 60,  strength: 60f, brushRadius: 1.0f);
            var axeIron   = MakeTool(toolsFolder, "Iron Axe",       VoxelEngine.Items.ToolType.Axe,     tier: 3, dur: 400, strength: 110f, brushRadius: 1.0f);

            // Grinder Tool — hand tool that grinds DOWN grid blocks back into items.
            string grinderToolPath = $"{toolsFolder}/Tool_Grinder.asset";
            var grinderTool = AssetDatabase.LoadAssetAtPath<VoxelEngine.GridSystem.GrinderTool>(grinderToolPath);
            if (grinderTool == null) { grinderTool = ScriptableObject.CreateInstance<VoxelEngine.GridSystem.GrinderTool>(); AssetDatabase.CreateAsset(grinderTool, grinderToolPath); }
            grinderTool.itemId       = "grinder_tool";
            grinderTool.displayName  = "Grinder";
            grinderTool.description  = "Grinds down grid (ship/vehicle) blocks, returning them as items.";
            grinderTool.maxStack     = 1;
            grinderTool.toolType     = VoxelEngine.Items.ToolType.Other;
            grinderTool.miningTier   = 3;
            grinderTool.maxDurability = 600;
            grinderTool.iconTint     = new Color(0.85f, 0.55f, 0.15f);
            grinderTool.category     = "Tools";
            grinderTool.baseGrindTime = 3f;
            grinderTool.minGrindTime  = 1.2f;
            EditorUtility.SetDirty(grinderTool);

            // Leveling Tool — a special tool that flattens terrain to a target Y level (custom class).
            string levelToolPath = $"{toolsFolder}/Tool_LevelingTool.asset";
            var lvTool = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.LevelingTool>(levelToolPath);
            if (lvTool == null)
            {
                lvTool = ScriptableObject.CreateInstance<VoxelEngine.Items.LevelingTool>();
                AssetDatabase.CreateAsset(lvTool, levelToolPath);
            }
            lvTool.itemId        = "leveling_tool";
            lvTool.displayName   = "Leveling Tool";
            lvTool.description   = "FIRST left-click: anchors the target height (the surface you look at). " +
                                    "Next left-clicks flatten terrain to that height in a 3m brush radius — " +
                                    "fills low spots with stone, carves out high spots. Perfect for building plots.";
            lvTool.toolType      = VoxelEngine.Items.ToolType.Other;
            lvTool.miningTier    = 2;
            lvTool.maxDurability = 500;
            lvTool.strength      = 1f;
            lvTool.fireRate      = 3f;
            lvTool.brushRadius   = 3f;
            lvTool.iconTint      = new Color(0.85f, 0.80f, 0.30f);
            lvTool.maxStack      = 1;
            lvTool.category      = "Tools";
            EditorUtility.SetDirty(lvTool);

            // ----- Station block prefabs (procedural cube placeholders) -----
            var benchPrefab    = MakeStationPrefab(stationsFolder, "CraftingBench", new Color(0.50f,0.34f,0.20f),  VoxelEngine.Crafting.StationTier.CraftingBench, "Crafting Bench");
            var furnacePrefab  = MakeStationPrefab(stationsFolder, "Furnace",       new Color(0.30f,0.30f,0.32f),  VoxelEngine.Crafting.StationTier.Furnace,        "Furnace", isFurnace:true);
            var assemblerPrefab= MakeStationPrefab(stationsFolder, "Assembler",     new Color(0.20f,0.50f,0.85f),  VoxelEngine.Crafting.StationTier.Assembler,      "Assembler");
            var chestPrefab    = MakeChestPrefab(stationsFolder, "Chest",           new Color(0.55f,0.40f,0.20f), 30);

            // ----- BlockItems for each placeable -----
            var blockBench      = MakeBlock(blocksFolder, "Block_CraftingBench", "Crafting Bench", new Color(0.50f,0.34f,0.20f), benchPrefab, "Stations");
            blockBench.description    = "Tier-1 workstation. Place near the player to unlock stone/foundation/wall recipes.";
            var blockFurnace    = MakeBlock(blocksFolder, "Block_Furnace",       "Solid Fuel Furnace",  new Color(0.30f,0.30f,0.32f), furnacePrefab, "Stations");
            blockFurnace.description  = "Burns wood logs / planks / coal as fuel to smelt iron and copper ingots. Slow but no power required.";
            var blockAssembler  = MakeBlock(blocksFolder, "Block_Assembler",     "Assembler",      new Color(0.20f,0.50f,0.85f), assemblerPrefab, "Stations");
            blockAssembler.description= "Tier-3 workstation. Required to craft iron / steel pickaxes, batteries, and high-tier wires.";
            var blockChest      = MakeBlock(blocksFolder, "Block_Chest",         "Chest",          new Color(0.55f,0.40f,0.20f), chestPrefab, "Storage");
            blockChest.description    = "30-slot storage container. Right-click while looking at it to open.";

            // Bed prefab + BlockItem. Right-click sets the player's spawn point.
            string bedPath = $"{stationsFolder}/Bed.prefab";
            var bedRoot = new GameObject("Bed");
            var bedBase = GameObject.CreatePrimitive(PrimitiveType.Cube);
            bedBase.transform.SetParent(bedRoot.transform, false);
            bedBase.transform.localScale = new Vector3(2f, 0.4f, 1f);
            bedBase.transform.localPosition = new Vector3(0, 0.2f, 0);
            bedBase.GetComponent<Renderer>().sharedMaterial = MakeColoredMat(stationsFolder, "Mat_Bed", new Color(0.55f, 0.30f, 0.40f));
            // Headboard
            var bedHead = GameObject.CreatePrimitive(PrimitiveType.Cube);
            bedHead.transform.SetParent(bedRoot.transform, false);
            bedHead.transform.localScale = new Vector3(0.4f, 0.6f, 1f);
            bedHead.transform.localPosition = new Vector3(0.8f, 0.5f, 0);
            bedHead.GetComponent<Renderer>().sharedMaterial = MakeColoredMat(stationsFolder, "Mat_BedHead", new Color(0.40f, 0.25f, 0.20f));
            bedRoot.AddComponent<VoxelEngine.Building.Bed>();
            var bedPrefab = PrefabUtility.SaveAsPrefabAsset(bedRoot, bedPath);
            Object.DestroyImmediate(bedRoot);

            var blockBed = MakeBlock(blocksFolder, "Block_Bed", "Bed", new Color(0.55f,0.30f,0.40f), bedPrefab, "Stations");
            blockBed.description = "Right-click to set your respawn point here. If you die without a bed, you'll respawn at the world spawn.";

            // ----- Recipes -----
            var registry = ScriptableObject.CreateInstance<VoxelEngine.Crafting.RecipeRegistry>();

            // Tier 0 (player inventory)
            registry.recipes.Add(MakeRecipe(recipesFolder, "Recipe_Plank",         "Wooden Plank",       plank,        2, VoxelEngine.Crafting.StationTier.None, (woodLog, 1)));
            registry.recipes.Add(MakeRecipe(recipesFolder, "Recipe_PickWood",      "Wooden Pickaxe",     pickWood,     1, VoxelEngine.Crafting.StationTier.None, (woodLog, 3), (plank, 2)));
            registry.recipes.Add(MakeRecipe(recipesFolder, "Recipe_AxeWood",       "Wooden Axe",         axeWood,      1, VoxelEngine.Crafting.StationTier.None, (woodLog, 3), (plank, 2)));
            registry.recipes.Add(MakeRecipe(recipesFolder, "Recipe_CraftingBench", "Crafting Bench",     blockBench,   1, VoxelEngine.Crafting.StationTier.None, (woodLog, 4), (plank, 4)));

            // Tier 1 (Crafting Bench)
            registry.recipes.Add(MakeRecipe(recipesFolder, "Recipe_PickStone",     "Stone Pickaxe",      pickStone,    1, VoxelEngine.Crafting.StationTier.CraftingBench, (stone, 5), (plank, 2)));
            registry.recipes.Add(MakeRecipe(recipesFolder, "Recipe_LevelingTool",  "Leveling Tool",      lvTool,       1, VoxelEngine.Crafting.StationTier.CraftingBench, (ironIngot, 2), (plank, 4)));
            registry.recipes.Add(MakeRecipe(recipesFolder, "Recipe_Furnace",       "Furnace",            blockFurnace, 1, VoxelEngine.Crafting.StationTier.CraftingBench, (stone, 8)));
            registry.recipes.Add(MakeRecipe(recipesFolder, "Recipe_Chest",         "Chest",              blockChest,   1, VoxelEngine.Crafting.StationTier.CraftingBench, (plank, 8)));
            registry.recipes.Add(MakeRecipe(recipesFolder, "Recipe_Bed",           "Bed",                blockBed,     1, VoxelEngine.Crafting.StationTier.CraftingBench, (plank, 6), (woodLog, 2)));

            // Tier 2 (Furnace) - smelting recipes are separate
            // Tier 3 (Assembler)
            registry.recipes.Add(MakeRecipe(recipesFolder, "Recipe_PickIron",      "Iron Pickaxe",       pickIron,     1, VoxelEngine.Crafting.StationTier.Assembler, (ironIngot, 3), (plank, 2)));
            registry.recipes.Add(MakeRecipe(recipesFolder, "Recipe_AxeIron",       "Iron Axe",           axeIron,      1, VoxelEngine.Crafting.StationTier.Assembler, (ironIngot, 3), (plank, 2)));
            registry.recipes.Add(MakeRecipe(recipesFolder, "Recipe_GrinderTool",   "Grinder",            grinderTool,  1, VoxelEngine.Crafting.StationTier.Assembler, (ironIngot, 4), (plank, 1)));
            registry.recipes.Add(MakeRecipe(recipesFolder, "Recipe_PickSteel",     "Steel Pickaxe",      pickSteel,    1, VoxelEngine.Crafting.StationTier.Assembler, (steelIngot, 3), (plank, 1)));
            registry.recipes.Add(MakeRecipe(recipesFolder, "Recipe_Assembler",     "Assembler",          blockAssembler,1,VoxelEngine.Crafting.StationTier.CraftingBench, (ironIngot, 6), (plank, 4), (stone, 8)));

            AssetDatabase.CreateAsset(registry, $"{ASSET_ROOT}/RecipeRegistry.asset");

            // Also wire it into any existing GameUIController in the currently-open scene
            // so the player doesn't have to re-run step 2.
            var existingUis = Object.FindObjectsByType<VoxelEngine.UI.GameUIController>(FindObjectsInactive.Include);
            foreach (var ui in existingUis)
            {
                ui.recipeRegistry = registry;
                EditorUtility.SetDirty(ui);
            }

            // ----- Smelting recipes attached to the Furnace prefab -----
            var smIron   = MakeSmelt(recipesFolder, "Smelt_Iron",   iron,   1, ironIngot,   1, 4f);
            var smCopper = MakeSmelt(recipesFolder, "Smelt_Copper", copper, 1, copperIngot, 1, 4f);
            var smSteel  = MakeSmelt(recipesFolder, "Smelt_Steel",  iron,   1, steelIngot,  1, 8f); // simplistic — needs coal as fuel
            // Modifying components on a saved prefab requires opening it via the prefab API
            // and re-saving — EditorUtility.SetDirty alone doesn't persist.
            var smList = new System.Collections.Generic.List<VoxelEngine.Crafting.SmeltingRecipe> { smIron, smCopper, smSteel };
            AssignFurnaceRecipes(furnacePrefab, smList);

            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();

            // Configure tree scatter prefabs to drop wood logs on chop.
            ConfigureTreeChopping(woodLog);

            EditorUtility.DisplayDialog("Voxel Engine",
                "Crafting content created!\n\n" +
                "* 6 placeable blocks (Bench, Furnace, Assembler, Chest, Foundation, Wall)\n" +
                "* 6 tools (4 pickaxes + 2 axes) with mining tiers\n" +
                "* 16 recipes across all 3 station tiers\n" +
                "* 3 smelting recipes (auto-loaded into Furnace)\n\n" +
                "Trees now drop Wood Logs when chopped.\n" +
                "RecipeRegistry asset is wired into the GameUI automatically when you re-run Step 2.", "OK");
        }

        // ============================================================
        //                STEP 4 helper builders
        // ============================================================
        // Map a grid-block prefab name to its visual style.
        private static VoxelEngine.GridSystem.GridBlockMeshBuilder.Style GridStyleFor(string name)
        {
            string n = name.ToLower();
            if (n.Contains("cockpit"))    return VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.Cockpit;
            if (n.Contains("thruster"))   return VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.Thruster;
            if (n.Contains("battery"))    return VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.Battery;
            if (n.Contains("armor"))      return VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.Armor;
            if (n.Contains("glass"))      return VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.Glass;
            if (n.Contains("cargo"))      return VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.Cargo;
            if (n.Contains("liquidtank")) return VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.LiquidTank;
            if (n.Contains("gastank"))    return VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.GasTank;
            if (n.Contains("drill"))      return VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.Drill;
            if (n.Contains("grinder"))    return VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.Grinder;
            if (n.Contains("weapon"))     return VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.Weapon;
            if (n.Contains("docking"))    return VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.DockingPort;
            if (n.Contains("wheel"))      return VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.Wheel;
            if (n.Contains("landing"))    return VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.LandingGear;
            if (n.Contains("solar"))      return VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.SolarPanel;
            if (n.Contains("hydrogenengine")) return VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.HydrogenEngine;
            if (n.Contains("reactor"))    return VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.Reactor;
            if (n.Contains("gyroscope"))  return VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.Gyroscope;
            if (n.Contains("beacon"))     return VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.Beacon;
            if (n.Contains("oredetector"))return VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.OreDetector;
            if (n.Contains("refinery"))   return VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.Refinery;
            if (n.Contains("chemical"))   return VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.ChemicalPlant;
            if (n.Contains("furnace"))    return VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.Refinery;
            if (n.Contains("h2o2"))       return VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.H2O2;
            if (n.Contains("demolisher")) return VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.Demolisher;
            if (n.Contains("itempipe"))   return VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.ItemPipe;
            if (n.Contains("gaspipe"))    return VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.GasPipe;
            if (n.Contains("liquidpipe")) return VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.LiquidPipe;
            // ── Maritime propulsion styles ───────────────────────────────
            if (n.Contains("engine_giant") || n.Contains("giantdiesel")) return VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.Reactor;
            if (n.Contains("engine_medium")) return VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.HydrogenEngine;
            if (n.Contains("engine_small")) return VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.HydrogenEngine;
            if (n.Contains("turbocharger")) return VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.Gyroscope;
            if (n.Contains("gearbox")) return VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.Refinery;
            if (n.Contains("maritimegenerator")) return VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.Reactor;
            if (n.Contains("epropeller") || n.Contains("propeller")) return VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.Thruster;
            if (n.Contains("exhaust")) return VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.GasPipe;
            if (n.Contains("driveshaft")) return VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.ItemPipe;
            if (n.Contains("waterwheel")) return VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.Refinery;
            if (n.Contains("bilgepump")) return VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.ChemicalPlant;
            if (n.Contains("helm")) return VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.Cockpit;
            if (n.Contains("hull_")) return VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.Armor;
            return VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.Generic;
        }

        private static void EnsureFolder(string path)
        {
            if (AssetDatabase.IsValidFolder(path)) return;
            var parent = System.IO.Path.GetDirectoryName(path).Replace("\\", "/");
            var leaf   = System.IO.Path.GetFileName(path);
            if (string.IsNullOrEmpty(parent) || string.IsNullOrEmpty(leaf)) return;
            EnsureFolder(parent); // recurse up — ensure parent exists first
            AssetDatabase.CreateFolder(parent, leaf);
        }

        private static VoxelEngine.Items.ResourceItem MakeResource(string folder, string display, Color tint, int maxStack,
            VoxelEngine.Items.ResourceCategory cat, float fuelSeconds = 0f, string uiCategory = null)
        {
            string id = display.ToLower().Replace(" ", "_");
            string path = $"{folder}/Item_{display.Replace(" ", "")}.asset";
            var item = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>(path);
            if (item == null) item = ScriptableObject.CreateInstance<VoxelEngine.Items.ResourceItem>();
            item.itemId = id; item.displayName = display; item.iconTint = tint;
            item.maxStack = maxStack; item.massPerUnit = 1f;
            item.subcategory = cat;
            item.fuelSeconds = fuelSeconds;
            // UI grouping: default to "Resources" but allow override (e.g. "Power", "Building").
            item.category = uiCategory ?? (cat == VoxelEngine.Items.ResourceCategory.Ingot ? "Ingots" : "Resources");
            if (!AssetDatabase.Contains(item)) AssetDatabase.CreateAsset(item, path);
            else EditorUtility.SetDirty(item);
            return item;
        }

        private static VoxelEngine.Items.ToolItem MakeTool(string folder, string display, VoxelEngine.Items.ToolType type,
            int tier, int dur, float strength, float brushRadius, GameObject customPrefab = null)
        {
            string id = display.ToLower().Replace(" ", "_");
            string path = $"{folder}/Tool_{display.Replace(" ", "")}.asset";
            var t = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ToolItem>(path);
            if (t == null)
            {
                if (AssetDatabase.LoadMainAssetAtPath(path) != null) AssetDatabase.DeleteAsset(path);
                t = ScriptableObject.CreateInstance<VoxelEngine.Items.ToolItem>();
                AssetDatabase.CreateAsset(t, path);
            }
            t.itemId = id; t.displayName = display; t.maxStack = 1;
            t.toolType = type; t.miningTier = tier;
            t.maxDurability = dur; t.strength = strength; t.brushRadius = brushRadius; t.fireRate = 5f;
            if (customPrefab != null) t.viewmodelPrefab = customPrefab;

            t.iconTint = type == VoxelEngine.Items.ToolType.Pickaxe ? new Color(0.7f,0.7f,0.78f) : new Color(0.6f,0.45f,0.30f);
            t.category = "Tools";

            EditorUtility.SetDirty(t);
            return t;
        }

        private static VoxelEngine.Items.BlockItem MakeBlock(string folder, string assetName, string display, Color tint, GameObject prefab, string uiCategory = "Stations")
        {
            string path = $"{folder}/{assetName}.asset";
            var b = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.BlockItem>(path);
            if (b == null) b = ScriptableObject.CreateInstance<VoxelEngine.Items.BlockItem>();
            b.itemId = assetName.ToLower(); b.displayName = display;
            b.iconTint = tint; b.maxStack = 99; b.massPerUnit = 4f;
            b.placedPrefab = prefab; b.gridSize = Vector3Int.one;
            b.allowStacking = true; b.blockHealth = 200; b.miningTier = 1;
            b.category = uiCategory;
            if (!AssetDatabase.Contains(b)) AssetDatabase.CreateAsset(b, path);
            else EditorUtility.SetDirty(b);
            return b;
        }

        private static VoxelEngine.Crafting.RecipeDefinition MakeRecipe(string folder, string assetName, string display,
            VoxelEngine.Items.ItemDefinition output, int outputCount,
            VoxelEngine.Crafting.StationTier station, params (VoxelEngine.Items.ItemDefinition item, int count)[] inputs)
        {
            string path = $"{folder}/{assetName}.asset";
            var r = GetOrCreateAsset<VoxelEngine.Crafting.RecipeDefinition>(path);

            r.displayName = display; r.outputItem = output; r.outputCount = outputCount;
            // Set a default craft time based on station tier; users can override later via the inspector.
            float defaultSeconds = station switch
            {
                VoxelEngine.Crafting.StationTier.None          => 0f,
                VoxelEngine.Crafting.StationTier.CraftingBench => 2f,
                VoxelEngine.Crafting.StationTier.Furnace       => 0f,
                VoxelEngine.Crafting.StationTier.Assembler     => 4f,
                _ => 0f
            };
            r.requiredStation = station; r.craftSeconds = defaultSeconds; r.unlockedByDefault = true;
            r.inputs = new VoxelEngine.Crafting.RecipeIngredient[inputs.Length];
            for (int i = 0; i < inputs.Length; i++)
                r.inputs[i] = new VoxelEngine.Crafting.RecipeIngredient { item = inputs[i].item, count = inputs[i].count };

            return r;
        }

        private static VoxelEngine.Crafting.SmeltingRecipe MakeSmelt(string folder, string assetName,
            VoxelEngine.Items.ItemDefinition input, int inputCount,
            VoxelEngine.Items.ItemDefinition output, int outputCount, float seconds)
        {
            string path = $"{folder}/{assetName}.asset";
            var r = GetOrCreateAsset<VoxelEngine.Crafting.SmeltingRecipe>(path);
            r.input = input; r.inputCount = inputCount;
            r.output = output; r.outputCount = outputCount; r.smeltSeconds = seconds;

            return r;
        }

        private static void AssignFurnaceRecipes(GameObject prefab, System.Collections.Generic.List<VoxelEngine.Crafting.SmeltingRecipe> recipes)
        {
            if (prefab == null) return;
            string path = AssetDatabase.GetAssetPath(prefab);
            // Load the prefab content into an editable scene-instance, edit it, save back.
            var contents = PrefabUtility.LoadPrefabContents(path);
            var furn = contents.GetComponent<VoxelEngine.Crafting.Furnace>();
            if (furn != null) furn.knownRecipes = new System.Collections.Generic.List<VoxelEngine.Crafting.SmeltingRecipe>(recipes);
            PrefabUtility.SaveAsPrefabAsset(contents, path);
            PrefabUtility.UnloadPrefabContents(contents);
        }

        private static void AssignElectricFurnaceRecipes(GameObject prefab, System.Collections.Generic.List<VoxelEngine.Crafting.SmeltingRecipe> recipes)
        {
            if (prefab == null) return;
            string path = AssetDatabase.GetAssetPath(prefab);
            var contents = PrefabUtility.LoadPrefabContents(path);
            var furn = contents.GetComponent<VoxelEngine.Crafting.ElectricFurnace>();
            if (furn != null) furn.knownRecipes = new System.Collections.Generic.List<VoxelEngine.Crafting.SmeltingRecipe>(recipes);
            PrefabUtility.SaveAsPrefabAsset(contents, path);
            PrefabUtility.UnloadPrefabContents(contents);
        }

        private static GameObject MakeStationPrefab(string folder, string name, Color color,
            VoxelEngine.Crafting.StationTier tier, string display, bool isFurnace = false)
        {
            string path = $"{folder}/{name}.prefab";
            var root = new GameObject(name);
            var cube = GameObject.CreatePrimitive(PrimitiveType.Cube);
            cube.name = "Mesh";
            cube.transform.SetParent(root.transform, false);
            var mat = MakeColoredMat(folder, $"Mat_{name}", color);
            cube.GetComponent<Renderer>().sharedMaterial = mat;
            // Keep the box collider for raycast hits.
            var st = root.AddComponent<VoxelEngine.Crafting.CraftingStation>();
            st.tier = tier; st.displayName = display;
            if (isFurnace) root.AddComponent<VoxelEngine.Crafting.Furnace>();
            var prefab = PrefabUtility.SaveAsPrefabAsset(root, path);
            Object.DestroyImmediate(root);
            return prefab;
        }
        private static GameObject MakeChestPrefab(string folder, string name, Color color, int size)
        {
            string path = $"{folder}/{name}.prefab";
            var root = new GameObject(name);
            var cube = GameObject.CreatePrimitive(PrimitiveType.Cube);
            cube.name = "Mesh";
            cube.transform.SetParent(root.transform, false);
            cube.transform.localScale = new Vector3(1f, 0.7f, 0.7f);
            var mat = MakeColoredMat(folder, $"Mat_{name}", color);
            cube.GetComponent<Renderer>().sharedMaterial = mat;
            var c = root.AddComponent<VoxelEngine.Building.Chest>();
            c.size = size;
            var prefab = PrefabUtility.SaveAsPrefabAsset(root, path);
            Object.DestroyImmediate(root);
            return prefab;
        }
        private static GameObject MakeBuildingPrefab(string folder, string name, Color color, Vector3 scale)
        {
            string path = $"{folder}/{name}.prefab";
            var root = new GameObject(name);
            var cube = GameObject.CreatePrimitive(PrimitiveType.Cube);
            cube.name = "Mesh";
            cube.transform.SetParent(root.transform, false);
            cube.transform.localScale = scale;
            var mat = MakeColoredMat(folder, $"Mat_{name}", color);
            cube.GetComponent<Renderer>().sharedMaterial = mat;
            var prefab = PrefabUtility.SaveAsPrefabAsset(root, path);
            Object.DestroyImmediate(root);
            return prefab;
        }

        private static void ConfigureTreeChopping(VoxelEngine.Items.ItemDefinition logItem)
        {
            // Add the Tree component to the existing scatter tree prefabs created earlier.
            string[] treeNames = { "Tree_Oak", "Tree_Pine", "Tree_Dead" };
            string scatterFolder = ASSET_ROOT + "/Scatter";
            foreach (var n in treeNames)
            {
                string path = $"{scatterFolder}/{n}.prefab";
                var prefab = AssetDatabase.LoadAssetAtPath<GameObject>(path);
                if (prefab == null) continue;
                var go = (GameObject)PrefabUtility.InstantiatePrefab(prefab);
                if (go.GetComponent<VoxelEngine.Trees.Tree>() == null)
                {
                    var t = go.AddComponent<VoxelEngine.Trees.Tree>();
                    t.maxHp = 80; t.minLogs = 2; t.maxLogs = 4;
                    t.logItem = logItem;
                    t.preferredTool = VoxelEngine.Items.ToolType.Axe;
                }
                PrefabUtility.SaveAsPrefabAsset(go, path);
                Object.DestroyImmediate(go);
            }
        }

        // ============================================================
        //         STEP 5 - TIERED BUILDING CONTENT (RUST-STYLE)
        // ============================================================
        private void BuildTieredContent()
        {
            const string tieredFolder    = ASSET_ROOT + "/Tiered";
            const string tieredPrefabs   = tieredFolder + "/Prefabs";
            const string tieredDefs      = tieredFolder + "/Definitions";
            const string tieredTokens    = tieredFolder + "/Tokens";
            const string tieredMats      = tieredFolder + "/Materials";
            const string tieredRecipes   = tieredFolder + "/Recipes";

            EnsureFolder(tieredFolder);
            EnsureFolder(tieredPrefabs);
            EnsureFolder(tieredDefs);
            EnsureFolder(tieredTokens);
            EnsureFolder(tieredMats);
            EnsureFolder(tieredRecipes);

            // ---------- Resolve or repair common Step 1 / Step 4 item references ----------
            string itemsFolder = ASSET_ROOT + "/Items";

            T ResolveOrCreateTieredItem<T>(
                string canonicalPath,
                string itemId,
                string displayName,
                Color tint,
                VoxelEngine.Items.ResourceCategory resourceCategory = VoxelEngine.Items.ResourceCategory.Raw,
                float fuelSeconds = 0f)
                where T : VoxelEngine.Items.ItemDefinition
            {
                var canonical = AssetDatabase.LoadAssetAtPath<T>(canonicalPath);
                if (canonical != null) return canonical;

                foreach (string guid in AssetDatabase.FindAssets("t:ItemDefinition", new[] { ASSET_ROOT }))
                {
                    string candidatePath = AssetDatabase.GUIDToAssetPath(guid);
                    var candidate = AssetDatabase.LoadAssetAtPath<T>(candidatePath);
                    if (candidate != null && candidate.itemId == itemId) return candidate;
                }

                var occupied = AssetDatabase.LoadMainAssetAtPath(canonicalPath);
                if (occupied != null)
                {
                    Debug.LogError($"[VoxelEngineSetupWindow] Step 5 preserved '{canonicalPath}' because its type does not match {typeof(T).Name}.");
                    return null;
                }

                var created = ScriptableObject.CreateInstance<T>();
                created.itemId = itemId;
                created.displayName = displayName;
                created.description = $"Core {displayName.ToLowerInvariant()} resource used by tiered construction.";
                created.iconTint = tint;
                created.maxStack = 999;
                created.massPerUnit = 1f;
                created.category = "Resources";
                if (created is VoxelEngine.Items.ResourceItem resource)
                {
                    resource.subcategory = resourceCategory;
                    resource.fuelSeconds = fuelSeconds;
                }
                AssetDatabase.CreateAsset(created, canonicalPath);
                Debug.Log($"[VoxelEngineSetupWindow] Step 5 repaired missing prerequisite item: {canonicalPath}");
                return created;
            }

            var stone = ResolveOrCreateTieredItem<VoxelEngine.Items.ItemDefinition>(
                $"{itemsFolder}/Item_Stone.asset", "stone", "Stone", new Color(0.55f, 0.55f, 0.58f));
            var woodLog = ResolveOrCreateTieredItem<VoxelEngine.Items.ResourceItem>(
                $"{itemsFolder}/Item_WoodLog.asset", "wood_log", "Wood Log", new Color(0.45f, 0.30f, 0.16f),
                VoxelEngine.Items.ResourceCategory.Fuel, 4f);
            var plank = ResolveOrCreateTieredItem<VoxelEngine.Items.ResourceItem>(
                $"{itemsFolder}/Item_WoodenPlank.asset", "wooden_plank", "Wooden Plank", new Color(0.55f, 0.40f, 0.25f),
                VoxelEngine.Items.ResourceCategory.Fuel, 3f);
            var ironIngot = ResolveOrCreateTieredItem<VoxelEngine.Items.ResourceItem>(
                $"{itemsFolder}/Item_IronIngot.asset", "iron_ingot", "Iron Ingot", new Color(0.78f, 0.78f, 0.82f),
                VoxelEngine.Items.ResourceCategory.Ingot);
            var steelIngot = ResolveOrCreateTieredItem<VoxelEngine.Items.ResourceItem>(
                $"{itemsFolder}/Item_SteelIngot.asset", "steel_ingot", "Steel Ingot", new Color(0.55f, 0.58f, 0.65f),
                VoxelEngine.Items.ResourceCategory.Ingot);

            if (woodLog == null || plank == null || stone == null || ironIngot == null || steelIngot == null)
            {
                EditorUtility.DisplayDialog("Voxel Engine — Step 5",
                    "Step 5 found an asset-type conflict while repairing its prerequisites. No existing asset was deleted. Check the Console for the exact path.",
                    "OK");
                return;
            }

            // ---------- Premium procedural tier surfaces (created once, user edits preserved) ----------
            Texture2D GetOrCreateTierTexture(string assetName, Color baseColor, int style)
            {
                string path = $"{tieredMats}/{assetName}.asset";
                var existing = AssetDatabase.LoadAssetAtPath<Texture2D>(path);
                if (existing != null) return existing;
                if (AssetDatabase.LoadMainAssetAtPath(path) != null) return null;

                const int size = 128;
                var texture = new Texture2D(size, size, TextureFormat.RGBA32, false)
                {
                    name = assetName,
                    wrapMode = TextureWrapMode.Repeat,
                    filterMode = FilterMode.Bilinear
                };
                var pixels = new Color[size * size];
                for (int y = 0; y < size; y++)
                {
                    for (int x = 0; x < size; x++)
                    {
                        float nx = x / (float)size;
                        float ny = y / (float)size;
                        float noise = Mathf.PerlinNoise(nx * 8f + style * 3.17f, ny * 8f + style * 5.31f) - 0.5f;
                        float pattern = noise;
                        switch (style)
                        {
                            case 0: // layered wood grain
                                pattern += Mathf.Sin((ny * 24f + noise * 2f) * Mathf.PI) * 0.12f;
                                break;
                            case 1: // chipped stone aggregate
                                pattern += Mathf.PerlinNoise(nx * 28f, ny * 28f) * 0.18f - 0.09f;
                                break;
                            case 2: // brushed iron
                                pattern = noise * 0.20f + Mathf.Sin(ny * 180f) * 0.035f;
                                if (x % 32 == 2 || y % 32 == 2) pattern -= 0.10f;
                                break;
                            default: // plated steel seams and rivets
                                pattern = noise * 0.14f;
                                if (x % 64 < 2 || y % 64 < 2) pattern -= 0.14f;
                                int rx = x % 64, ry = y % 64;
                                if ((rx < 5 && ry < 5) || (rx > 59 && ry > 59)) pattern += 0.18f;
                                break;
                        }
                        Color color = baseColor * (1f + pattern * 0.55f);
                        color.a = 1f;
                        pixels[y * size + x] = color;
                    }
                }
                texture.SetPixels(pixels);
                texture.Apply(false, false);
                AssetDatabase.CreateAsset(texture, path);
                return texture;
            }

            Material GetOrCreateTierMaterial(string materialName, Color baseColor, int style, float metallic, float smoothness)
            {
                string path = $"{tieredMats}/{materialName}.mat";
                var existing = AssetDatabase.LoadAssetAtPath<Material>(path);
                if (existing != null) return existing;
                if (AssetDatabase.LoadMainAssetAtPath(path) != null) return null;

                var shader = Shader.Find("Universal Render Pipeline/Lit") ?? Shader.Find("Standard");
                var material = new Material(shader) { name = materialName, color = baseColor, enableInstancing = true };
                var texture = GetOrCreateTierTexture($"Tex_{materialName}", baseColor, style);
                if (material.HasProperty("_BaseColor")) material.SetColor("_BaseColor", Color.white);
                if (material.HasProperty("_BaseMap")) material.SetTexture("_BaseMap", texture);
                if (material.HasProperty("_MainTex")) material.SetTexture("_MainTex", texture);
                if (material.HasProperty("_Metallic")) material.SetFloat("_Metallic", metallic);
                if (material.HasProperty("_Smoothness")) material.SetFloat("_Smoothness", smoothness);
                AssetDatabase.CreateAsset(material, path);
                return material;
            }

            var matWood  = GetOrCreateTierMaterial("Mat_Wood_Premium",  new Color(0.55f, 0.40f, 0.25f), 0, 0.02f, 0.22f);
            var matStone = GetOrCreateTierMaterial("Mat_Stone_Premium", new Color(0.55f, 0.55f, 0.58f), 1, 0.00f, 0.16f);
            var matIron  = GetOrCreateTierMaterial("Mat_Iron_Premium",  new Color(0.68f, 0.70f, 0.74f), 2, 0.72f, 0.34f);
            var matSteel = GetOrCreateTierMaterial("Mat_Steel_Premium", new Color(0.34f, 0.39f, 0.48f), 3, 0.86f, 0.48f);
            var tierMats = new[] { matWood, matStone, matIron, matSteel };

            // Size-V5 keeps the exact Size-V4 dimensions while closing the
            // Foundation deck seams and adding bidirectional stair anchors.
            // Costs and tier balance remain untouched.
            const float constructionScale = 1.25f;
            const float constructionModuleSize = 3.75f;
            int migratedSizeV5PrefabCount = 0;
            Vector3 ScaleConstruction(Vector3 value) => value * constructionScale;

            // ---------- Build the 10 families, each with 4 tier prefabs ----------
            string registryPath = $"{tieredFolder}/TieredBlockRegistry.asset";
            var registry = AssetDatabase.LoadAssetAtPath<VoxelEngine.Building.Tiered.TieredBlockRegistry>(registryPath);
            if (registry == null) { registry = ScriptableObject.CreateInstance<VoxelEngine.Building.Tiered.TieredBlockRegistry>(); AssetDatabase.CreateAsset(registry, registryPath); }
            registry.definitions.RemoveAll(definition => definition == null);

            void BuildPremiumFoundation(GameObject root, Material material)
            {
                if (root.transform.Find("Generated_FoundationDeck_0") != null) return;

                for (int i = 0; i < 5; i++)
                {
                    var plank = AddBox(root, material,
                        ScaleConstruction(new Vector3(-1.20f + i * 0.60f, 0.52f, 0f)),
                        // Slight plank overlap removes light-leaking seams, while
                        // the full depth exactly covers the perimeter structure.
                        ScaleConstruction(new Vector3(0.62f, 0.15f, 3.02f)));
                    plank.name = $"Generated_FoundationDeck_{i}";
                }

                AddBox(root, material, ScaleConstruction(new Vector3(0f, 0.35f, 1.43f)), ScaleConstruction(new Vector3(3.02f, 0.24f, 0.16f))).name = "Generated_FoundationBeamFront";
                AddBox(root, material, ScaleConstruction(new Vector3(0f, 0.35f, -1.43f)), ScaleConstruction(new Vector3(3.02f, 0.24f, 0.16f))).name = "Generated_FoundationBeamBack";
                AddBox(root, material, ScaleConstruction(new Vector3(1.43f, 0.35f, 0f)), ScaleConstruction(new Vector3(0.16f, 0.24f, 2.72f))).name = "Generated_FoundationBeamRight";
                AddBox(root, material, ScaleConstruction(new Vector3(-1.43f, 0.35f, 0f)), ScaleConstruction(new Vector3(0.16f, 0.24f, 2.72f))).name = "Generated_FoundationBeamLeft";

                foreach (var x in new[] { -1.25f, 1.25f })
                foreach (var z in new[] { -1.25f, 1.25f })
                {
                    var leg = AddBox(root, material,
                        ScaleConstruction(new Vector3(x, -0.02f, z)),
                        ScaleConstruction(new Vector3(0.24f, 0.86f, 0.24f)));
                    leg.name = $"Generated_FoundationLeg_{(x < 0 ? "L" : "R")}_{(z < 0 ? "B" : "F")}";
                }

                var braceA = AddBox(root, material,
                    ScaleConstruction(new Vector3(-0.68f, 0.12f, 1.42f)),
                    ScaleConstruction(new Vector3(0.11f, 1.50f, 0.10f)));
                braceA.name = "Generated_FoundationBraceA";
                braceA.transform.localRotation = Quaternion.Euler(0f, 0f, -55f);
                var braceB = AddBox(root, material,
                    ScaleConstruction(new Vector3(0.68f, 0.12f, 1.42f)),
                    ScaleConstruction(new Vector3(0.11f, 1.50f, 0.10f)));
                braceB.name = "Generated_FoundationBraceB";
                braceB.transform.localRotation = Quaternion.Euler(0f, 0f, 55f);
            }

            void BuildPremiumWall(GameObject root, Material material)
            {
                AddBox(root, material, ScaleConstruction(new Vector3(0f, 1.5f, 0f)), ScaleConstruction(new Vector3(3.0f, 3.0f, 0.16f))).name = "Generated_WallPanel";
                AddBox(root, material, ScaleConstruction(new Vector3(-1.42f, 1.5f, 0f)), ScaleConstruction(new Vector3(0.16f, 3.0f, 0.30f))).name = "Generated_WallPostLeft";
                AddBox(root, material, ScaleConstruction(new Vector3(1.42f, 1.5f, 0f)), ScaleConstruction(new Vector3(0.16f, 3.0f, 0.30f))).name = "Generated_WallPostRight";
                AddBox(root, material, ScaleConstruction(new Vector3(0f, 0.08f, 0f)), ScaleConstruction(new Vector3(2.84f, 0.16f, 0.28f))).name = "Generated_WallBeamBottom";
                AddBox(root, material, ScaleConstruction(new Vector3(0f, 2.92f, 0f)), ScaleConstruction(new Vector3(2.84f, 0.16f, 0.28f))).name = "Generated_WallBeamTop";
                AddBox(root, material, ScaleConstruction(new Vector3(0f, 1.5f, -0.11f)), ScaleConstruction(new Vector3(0.10f, 2.72f, 0.05f))).name = "Generated_WallCenterSeam";
            }

            void EnsureTieredDoor(GameObject root, Material material)
            {
                var hinge = root.transform.Find("Generated_DoorHinge");
                if (hinge == null)
                {
                    var hingeObject = new GameObject("Generated_DoorHinge");
                    hingeObject.transform.SetParent(root.transform, false);
                    hingeObject.transform.localPosition = ScaleConstruction(new Vector3(-0.88f, 0f, 0f));
                    hinge = hingeObject.transform;

                    var panel = GameObject.CreatePrimitive(PrimitiveType.Cube);
                    panel.name = "Generated_DoorPanel";
                    panel.transform.SetParent(hinge, false);
                    panel.transform.localPosition = ScaleConstruction(new Vector3(0.87f, 1.32f, 0f));
                    panel.transform.localScale = ScaleConstruction(new Vector3(1.74f, 2.60f, 0.12f));
                    panel.GetComponent<Renderer>().sharedMaterial = material;

                    AddBox(hingeObject, material, ScaleConstruction(new Vector3(0.87f, 2.48f, -0.08f)), ScaleConstruction(new Vector3(1.58f, 0.10f, 0.05f))).name = "Generated_DoorRailTop";
                    AddBox(hingeObject, material, ScaleConstruction(new Vector3(0.87f, 0.14f, -0.08f)), ScaleConstruction(new Vector3(1.58f, 0.10f, 0.05f))).name = "Generated_DoorRailBottom";
                    AddBox(hingeObject, material, ScaleConstruction(new Vector3(0.10f, 1.31f, -0.08f)), ScaleConstruction(new Vector3(0.10f, 2.24f, 0.05f))).name = "Generated_DoorRailHinge";
                    AddBox(hingeObject, material, ScaleConstruction(new Vector3(1.64f, 1.31f, -0.08f)), ScaleConstruction(new Vector3(0.10f, 2.24f, 0.05f))).name = "Generated_DoorRailLatch";
                    AddBox(hingeObject, material, ScaleConstruction(new Vector3(0.87f, 1.31f, -0.08f)), ScaleConstruction(new Vector3(1.48f, 0.09f, 0.05f))).name = "Generated_DoorRailCenter";

                    var handle = GameObject.CreatePrimitive(PrimitiveType.Sphere);
                    handle.name = "Generated_DoorHandle";
                    handle.transform.SetParent(panel.transform, false);
                    // These values are panel-local; the panel's 25% scale carries
                    // the handle proportionally without applying the factor twice.
                    handle.transform.localPosition = new Vector3(0.36f, 0f, -0.62f);
                    handle.transform.localScale = Vector3.one * 0.10f;
                    handle.GetComponent<Renderer>().sharedMaterial = material;
                    Object.DestroyImmediate(handle.GetComponent<Collider>());
                }

                var door = root.GetComponent<VoxelEngine.Building.Tiered.TieredDoor>();
                if (door == null) door = root.AddComponent<VoxelEngine.Building.Tiered.TieredDoor>();
                door.doorPivot = hinge;
            }

            VoxelEngine.Building.Tiered.TieredBlockDefinition MakeFamily(
                VoxelEngine.Building.Tiered.BuildFamily fam,
                string display,
                System.Action<GameObject, Material> meshBuilder,
                System.Action<GameObject> socketBuilder,
                VoxelEngine.Building.Tiered.TierCost placeCost,
                VoxelEngine.Building.Tiered.TierCost upWoodToStone,
                VoxelEngine.Building.Tiered.TierCost upStoneToIron,
                VoxelEngine.Building.Tiered.TierCost upIronToSteel)
            {
                string path = $"{tieredDefs}/TBlock_{display}.asset";
                bool definitionCreated = AssetDatabase.LoadMainAssetAtPath(path) == null;
                var def = GetOrCreateAsset<VoxelEngine.Building.Tiered.TieredBlockDefinition>(path);

                if (definitionCreated)
                {
                    def.family = fam;
                    def.displayName = display;
                    def.placeCost     = placeCost;
                    def.woodToStone   = upWoodToStone;
                    def.stoneToIron   = upStoneToIron;
                    def.ironToSteel   = upIronToSteel;
                }

                for (int t = 0; t < 4; t++)
                {
                    var tier = (VoxelEngine.Building.Tiered.BuildTier)t;
                    string name = $"{display}_{tier}";
                    string prefabPath = $"{tieredPrefabs}/{name}.prefab";

                    // Robust Prefab Handling: Load existing or create new
                    var prefab = GetOrCreatePrefab(prefabPath, name, (root) =>
                    {
                        string legacyMaterialName = t switch
                        {
                            0 => "Mat_Wood",
                            1 => "Mat_Stone",
                            2 => "Mat_Iron",
                            _ => "Mat_Steel"
                        };

                        bool emptyPrefab = root.transform.childCount == 0
                            && root.GetComponent<MeshFilter>() == null
                            && root.GetComponentInChildren<MeshRenderer>() == null;
                        bool hasCurrentGeneratedSize = root.transform.Find("Generated_SizeV5") != null;
                        var sizeV4Marker = root.transform.Find("Generated_SizeV4");
                        bool requiresSizeV5Geometry = fam == VoxelEngine.Building.Tiered.BuildFamily.Foundation
                            || fam == VoxelEngine.Building.Tiered.BuildFamily.Doorway
                            || fam == VoxelEngine.Building.Tiered.BuildFamily.Floor;
                        if (!hasCurrentGeneratedSize && sizeV4Marker != null && !requiresSizeV5Geometry)
                        {
                            // No geometry/socket change is required for this family.
                            // Advance only the generated marker so authored transforms
                            // are not needlessly rebuilt during the migration.
                            sizeV4Marker.name = "Generated_SizeV5";
                            hasCurrentGeneratedSize = true;
                            migratedSizeV5PrefabCount++;
                            Debug.Log($"[VoxelEngineSetupWindow] Step 5 verified unchanged Size-V5 geometry for '{name}' without rebuilding its children.");
                        }

                        bool setupGenerated = false;
                        var renderersBefore = root.GetComponentsInChildren<Renderer>(true);
                        if (!emptyPrefab && !hasCurrentGeneratedSize && renderersBefore.Length > 0)
                        {
                            setupGenerated = true;
                            foreach (var renderer in renderersBefore)
                            {
                                string objectName = renderer.gameObject.name;
                                var current = renderer.sharedMaterial;
                                bool knownMaterial = current == null
                                    || current.name == legacyMaterialName
                                    || (tierMats[t] != null && current.name == tierMats[t].name);
                                if ((!objectName.StartsWith("Generated_", System.StringComparison.Ordinal)
                                     && objectName != "Box") || !knownMaterial)
                                {
                                    setupGenerated = false;
                                    break;
                                }
                            }
                        }

                        if (setupGenerated)
                        {
                            for (int childIndex = root.transform.childCount - 1; childIndex >= 0; childIndex--)
                                Object.DestroyImmediate(root.transform.GetChild(childIndex).gameObject);
                            migratedSizeV5PrefabCount++;
                            Debug.Log($"[VoxelEngineSetupWindow] Step 5 migrated Setup-generated prefab '{name}' to Size-V5 deck/stair geometry. Custom prefab geometry and balance values were not changed.");
                        }

                        if (emptyPrefab || setupGenerated)
                        {
                            meshBuilder(root, tierMats[t]);
                            socketBuilder(root);
                            var marker = new GameObject("Generated_SizeV5");
                            marker.transform.SetParent(root.transform, false);
                        }

                        if (fam == VoxelEngine.Building.Tiered.BuildFamily.Doorway)
                        {
                            var embeddedDoor = root.transform.Find("Generated_DoorHinge");
                            if (embeddedDoor != null) Object.DestroyImmediate(embeddedDoor.gameObject);
                            var embeddedDoorLogic = root.GetComponent<VoxelEngine.Building.Tiered.TieredDoor>();
                            if (embeddedDoorLogic != null) Object.DestroyImmediate(embeddedDoorLogic);
                        }
                        if (fam == VoxelEngine.Building.Tiered.BuildFamily.Door)
                            EnsureTieredDoor(root, tierMats[t]);

                        // Upgrade only known setup-generated flat materials. Custom
                        // materials and imported meshes remain untouched.
                        foreach (var renderer in root.GetComponentsInChildren<Renderer>(true))
                        {
                            var current = renderer.sharedMaterial;
                            if (current == null || current.name == legacyMaterialName)
                                renderer.sharedMaterial = tierMats[t];
                        }

                        // ALWAYS ensure required components exist
                        if (!root.TryGetComponent<VoxelEngine.Building.Tiered.PlacedTieredBlock>(out var ptb))
                            ptb = root.AddComponent<VoxelEngine.Building.Tiered.PlacedTieredBlock>();
                    });

                    if (tier == VoxelEngine.Building.Tiered.BuildTier.Wood)  def.woodPrefab  = prefab;
                    if (tier == VoxelEngine.Building.Tiered.BuildTier.Stone) def.stonePrefab = prefab;
                    if (tier == VoxelEngine.Building.Tiered.BuildTier.Iron)  def.ironPrefab  = prefab;
                    if (tier == VoxelEngine.Building.Tiered.BuildTier.Steel) def.steelPrefab = prefab;
                }
                EditorUtility.SetDirty(def);
                if (!registry.definitions.Contains(def)) registry.definitions.Add(def);
                return def;
            }

            // Helper: a TierCost from a list of (item, count) tuples.
            VoxelEngine.Building.Tiered.TierCost Cost(params (VoxelEngine.Items.ItemDefinition item, int n)[] items)
            {
                var c = new VoxelEngine.Building.Tiered.TierCost();
                c.items = new VoxelEngine.Building.Tiered.Ingredient[items.Length];
                for (int i = 0; i < items.Length; i++)
                    c.items[i] = new VoxelEngine.Building.Tiered.Ingredient { item = items[i].item, count = items[i].n };
                return c;
            }

            // ---------- Family-by-family meshes + sockets ----------
            // Every generated visual is 25% larger than Size-V3. Socket positions
            // describe the incoming piece root, not merely the host mesh edge.

            // FOUNDATION — raised 3.75 m deck with exact center-to-center neighbors.
            MakeFamily(VoxelEngine.Building.Tiered.BuildFamily.Foundation, "Foundation",
                (root, mat) => { BuildPremiumFoundation(root, mat); },
                (root) => {
                    float halfModule = constructionModuleSize * 0.5f;
                    AddSocket(root, VoxelEngine.Building.Tiered.SocketSide.Top, new Vector3(0f, 0.75f, 0f), VoxelEngine.Building.Tiered.BuildFamily.Foundation);

                    // An incoming Foundation root must be a complete module away.
                    // The previous half-module positions placed half of the new deck
                    // inside the host Foundation.
                    AddSocket(root, VoxelEngine.Building.Tiered.SocketSide.North, new Vector3(0f, 0f, constructionModuleSize), VoxelEngine.Building.Tiered.BuildFamily.Foundation);
                    AddSocket(root, VoxelEngine.Building.Tiered.SocketSide.South, new Vector3(0f, 0f, -constructionModuleSize), VoxelEngine.Building.Tiered.BuildFamily.Foundation);
                    AddSocket(root, VoxelEngine.Building.Tiered.SocketSide.East, new Vector3(constructionModuleSize, 0f, 0f), VoxelEngine.Building.Tiered.BuildFamily.Foundation);
                    AddSocket(root, VoxelEngine.Building.Tiered.SocketSide.West, new Vector3(-constructionModuleSize, 0f, 0f), VoxelEngine.Building.Tiered.BuildFamily.Foundation);

                    // Wall-like roots sit on the true upper perimeter edge.
                    AddSocket(root, VoxelEngine.Building.Tiered.SocketSide.TopNorth, new Vector3(0f, 0.75f, halfModule), VoxelEngine.Building.Tiered.BuildFamily.Foundation, 0f);
                    AddSocket(root, VoxelEngine.Building.Tiered.SocketSide.TopSouth, new Vector3(0f, 0.75f, -halfModule), VoxelEngine.Building.Tiered.BuildFamily.Foundation, 180f);
                    AddSocket(root, VoxelEngine.Building.Tiered.SocketSide.TopEast, new Vector3(halfModule, 0.75f, 0f), VoxelEngine.Building.Tiered.BuildFamily.Foundation, 90f);
                    AddSocket(root, VoxelEngine.Building.Tiered.SocketSide.TopWest, new Vector3(-halfModule, 0.75f, 0f), VoxelEngine.Building.Tiered.BuildFamily.Foundation, -90f);
                },
                Cost((woodLog, 4)),
                Cost((stone, 8)),
                Cost((ironIngot, 4)),
                Cost((steelIngot, 4))
            );

            // WALL — 3.75 x 3.75 m detailed panel.
            MakeFamily(VoxelEngine.Building.Tiered.BuildFamily.Wall, "Wall",
                (root, mat) => { BuildPremiumWall(root, mat); },
                (root) => {
                    AddSocket(root, VoxelEngine.Building.Tiered.SocketSide.Top, new Vector3(0f, constructionModuleSize, 0f), VoxelEngine.Building.Tiered.BuildFamily.Wall);
                    AddSocket(root, VoxelEngine.Building.Tiered.SocketSide.East, new Vector3(constructionModuleSize, 0f, 0f), VoxelEngine.Building.Tiered.BuildFamily.Wall);
                    AddSocket(root, VoxelEngine.Building.Tiered.SocketSide.West, new Vector3(-constructionModuleSize, 0f, 0f), VoxelEngine.Building.Tiered.BuildFamily.Wall);
                },
                Cost((woodLog, 2), (plank, 2)),
                Cost((stone, 4)),
                Cost((ironIngot, 2)),
                Cost((steelIngot, 2))
            );

            // DOORWAY — 25%-larger structural frame with a separate Door socket.
            MakeFamily(VoxelEngine.Building.Tiered.BuildFamily.Doorway, "Doorway",
                (root, mat) => {
                    AddBox(root, mat, ScaleConstruction(new Vector3(-1.2f, 1.5f, 0f)), ScaleConstruction(new Vector3(0.60f, 3.0f, 0.24f)));
                    AddBox(root, mat, ScaleConstruction(new Vector3(1.2f, 1.5f, 0f)), ScaleConstruction(new Vector3(0.60f, 3.0f, 0.24f)));
                    AddBox(root, mat, ScaleConstruction(new Vector3(0f, 2.82f, 0f)), ScaleConstruction(new Vector3(1.80f, 0.36f, 0.24f)));
                },
                (root) => {
                    AddSocket(root, VoxelEngine.Building.Tiered.SocketSide.Top, new Vector3(0f, constructionModuleSize, 0f), VoxelEngine.Building.Tiered.BuildFamily.Doorway);
                    AddSocket(root, VoxelEngine.Building.Tiered.SocketSide.East, new Vector3(constructionModuleSize, 0f, 0f), VoxelEngine.Building.Tiered.BuildFamily.Doorway);
                    AddSocket(root, VoxelEngine.Building.Tiered.SocketSide.West, new Vector3(-constructionModuleSize, 0f, 0f), VoxelEngine.Building.Tiered.BuildFamily.Doorway);
                    AddSocket(root, VoxelEngine.Building.Tiered.SocketSide.Center, Vector3.zero, VoxelEngine.Building.Tiered.BuildFamily.Doorway);
                    // Exterior threshold anchor: stairs snap with their high tread
                    // at the doorway and descend one complete storey outward.
                    AddSocket(root, VoxelEngine.Building.Tiered.SocketSide.Bottom, Vector3.zero, VoxelEngine.Building.Tiered.BuildFamily.Doorway);
                },
                Cost((woodLog, 3), (plank, 2)),
                Cost((stone, 5)),
                Cost((ironIngot, 3)),
                Cost((steelIngot, 3))
            );

            // WINDOW — enlarged frame with a proportional mid-height opening.
            MakeFamily(VoxelEngine.Building.Tiered.BuildFamily.Window, "Window",
                (root, mat) => {
                    AddBox(root, mat, ScaleConstruction(new Vector3(-1.24f, 1.5f, 0f)), ScaleConstruction(new Vector3(0.52f, 3.0f, 0.24f)));
                    AddBox(root, mat, ScaleConstruction(new Vector3(1.24f, 1.5f, 0f)), ScaleConstruction(new Vector3(0.52f, 3.0f, 0.24f)));
                    AddBox(root, mat, ScaleConstruction(new Vector3(0f, 2.66f, 0f)), ScaleConstruction(new Vector3(1.96f, 0.68f, 0.24f)));
                    AddBox(root, mat, ScaleConstruction(new Vector3(0f, 0.34f, 0f)), ScaleConstruction(new Vector3(1.96f, 0.68f, 0.24f)));
                },
                (root) => {
                    AddSocket(root, VoxelEngine.Building.Tiered.SocketSide.Top, new Vector3(0f, constructionModuleSize, 0f), VoxelEngine.Building.Tiered.BuildFamily.Window);
                    AddSocket(root, VoxelEngine.Building.Tiered.SocketSide.East, new Vector3(constructionModuleSize, 0f, 0f), VoxelEngine.Building.Tiered.BuildFamily.Window);
                    AddSocket(root, VoxelEngine.Building.Tiered.SocketSide.West, new Vector3(-constructionModuleSize, 0f, 0f), VoxelEngine.Building.Tiered.BuildFamily.Window);
                },
                Cost((woodLog, 2), (plank, 3)),
                Cost((stone, 4)),
                Cost((ironIngot, 2)),
                Cost((steelIngot, 2))
            );

            // FLOOR — 3.75 m square slab.
            MakeFamily(VoxelEngine.Building.Tiered.BuildFamily.Floor, "Floor",
                (root, mat) => { AddBox(root, mat, ScaleConstruction(new Vector3(0f, 0.10f, 0f)), ScaleConstruction(new Vector3(3.0f, 0.20f, 3.0f))); },
                (root) => {
                    AddSocket(root, VoxelEngine.Building.Tiered.SocketSide.Top, ScaleConstruction(new Vector3(0f, 0.20f, 0f)), VoxelEngine.Building.Tiered.BuildFamily.Floor);
                    AddSocket(root, VoxelEngine.Building.Tiered.SocketSide.North, new Vector3(0f, 0f, constructionModuleSize), VoxelEngine.Building.Tiered.BuildFamily.Floor);
                    AddSocket(root, VoxelEngine.Building.Tiered.SocketSide.South, new Vector3(0f, 0f, -constructionModuleSize), VoxelEngine.Building.Tiered.BuildFamily.Floor);
                    AddSocket(root, VoxelEngine.Building.Tiered.SocketSide.East, new Vector3(constructionModuleSize, 0f, 0f), VoxelEngine.Building.Tiered.BuildFamily.Floor);
                    AddSocket(root, VoxelEngine.Building.Tiered.SocketSide.West, new Vector3(-constructionModuleSize, 0f, 0f), VoxelEngine.Building.Tiered.BuildFamily.Floor);
                    float halfModule = constructionModuleSize * 0.5f;
                    float topSurface = 0.25f;
                    AddSocket(root, VoxelEngine.Building.Tiered.SocketSide.TopNorth, new Vector3(0f, topSurface, halfModule), VoxelEngine.Building.Tiered.BuildFamily.Floor, 0f);
                    AddSocket(root, VoxelEngine.Building.Tiered.SocketSide.TopSouth, new Vector3(0f, topSurface, -halfModule), VoxelEngine.Building.Tiered.BuildFamily.Floor, 180f);
                    AddSocket(root, VoxelEngine.Building.Tiered.SocketSide.TopEast, new Vector3(halfModule, topSurface, 0f), VoxelEngine.Building.Tiered.BuildFamily.Floor, 90f);
                    AddSocket(root, VoxelEngine.Building.Tiered.SocketSide.TopWest, new Vector3(-halfModule, topSurface, 0f), VoxelEngine.Building.Tiered.BuildFamily.Floor, -90f);
                },
                Cost((woodLog, 2), (plank, 2)),
                Cost((stone, 5)),
                Cost((ironIngot, 2)),
                Cost((steelIngot, 2))
            );

            // STAIRS — twelve proportional steps across one complete module.
            MakeFamily(VoxelEngine.Building.Tiered.BuildFamily.Stairs, "Stairs",
                (root, mat) => {
                    for (int i = 0; i < 12; i++)
                    {
                        AddBox(root, mat,
                            ScaleConstruction(new Vector3(0f, 0.125f + i * 0.25f, -1.375f + i * 0.25f)),
                            ScaleConstruction(new Vector3(3.0f, 0.25f, 0.25f)));
                    }
                },
                (root) => { /* stairs don't typically host other pieces */ },
                Cost((woodLog, 3), (plank, 3)),
                Cost((stone, 6)),
                Cost((ironIngot, 3)),
                Cost((steelIngot, 3))
            );

            // ROOF — enlarged sloped slab.
            MakeFamily(VoxelEngine.Building.Tiered.BuildFamily.Roof, "Roof",
                (root, mat) => {
                    var go = AddBox(root, mat, ScaleConstruction(new Vector3(0f, 0.65f, 0f)), ScaleConstruction(new Vector3(3.0f, 0.24f, 3.18f)));
                    go.transform.localEulerAngles = new Vector3(24f, 0f, 0f);
                },
                (root) => { /* peak */ },
                Cost((woodLog, 3), (plank, 2)),
                Cost((stone, 5)),
                Cost((ironIngot, 2)),
                Cost((steelIngot, 2))
            );

            // PILLAR — full-height 3.75 m column.
            MakeFamily(VoxelEngine.Building.Tiered.BuildFamily.Pillar, "Pillar",
                (root, mat) => { AddBox(root, mat, ScaleConstruction(new Vector3(0f, 1.5f, 0f)), ScaleConstruction(new Vector3(0.44f, 3.0f, 0.44f))); },
                (root) => {
                    float halfModule = constructionModuleSize * 0.5f;
                    AddSocket(root, VoxelEngine.Building.Tiered.SocketSide.Top, new Vector3(0f, constructionModuleSize, 0f), VoxelEngine.Building.Tiered.BuildFamily.Pillar);
                    AddSocket(root, VoxelEngine.Building.Tiered.SocketSide.North, new Vector3(0f, 0f, halfModule), VoxelEngine.Building.Tiered.BuildFamily.Pillar);
                    AddSocket(root, VoxelEngine.Building.Tiered.SocketSide.South, new Vector3(0f, 0f, -halfModule), VoxelEngine.Building.Tiered.BuildFamily.Pillar);
                    AddSocket(root, VoxelEngine.Building.Tiered.SocketSide.East, new Vector3(halfModule, 0f, 0f), VoxelEngine.Building.Tiered.BuildFamily.Pillar);
                    AddSocket(root, VoxelEngine.Building.Tiered.SocketSide.West, new Vector3(-halfModule, 0f, 0f), VoxelEngine.Building.Tiered.BuildFamily.Pillar);
                },
                Cost((woodLog, 1), (plank, 1)),
                Cost((stone, 3)),
                Cost((ironIngot, 1)),
                Cost((steelIngot, 1))
            );

            // HALF WALL — 3.75 m wide and 1.875 m tall.
            MakeFamily(VoxelEngine.Building.Tiered.BuildFamily.HalfWall, "HalfWall",
                (root, mat) => { AddBox(root, mat, ScaleConstruction(new Vector3(0f, 0.75f, 0f)), ScaleConstruction(new Vector3(3.0f, 1.5f, 0.24f))); },
                (root) => {
                    AddSocket(root, VoxelEngine.Building.Tiered.SocketSide.Top, new Vector3(0f, constructionModuleSize * 0.5f, 0f), VoxelEngine.Building.Tiered.BuildFamily.HalfWall);
                    AddSocket(root, VoxelEngine.Building.Tiered.SocketSide.East, new Vector3(constructionModuleSize, 0f, 0f), VoxelEngine.Building.Tiered.BuildFamily.HalfWall);
                    AddSocket(root, VoxelEngine.Building.Tiered.SocketSide.West, new Vector3(-constructionModuleSize, 0f, 0f), VoxelEngine.Building.Tiered.BuildFamily.HalfWall);
                },
                Cost((woodLog, 1), (plank, 1)),
                Cost((stone, 2)),
                Cost((ironIngot, 1)),
                Cost((steelIngot, 1))
            );

            MakeFamily(VoxelEngine.Building.Tiered.BuildFamily.Door, "Door",
                (root, mat) => { EnsureTieredDoor(root, mat); },
                (root) => { },
                Cost((plank, 4), (woodLog, 1)),
                Cost((stone, 4)),
                Cost((ironIngot, 3)),
                Cost((steelIngot, 3))
            );

            EditorUtility.SetDirty(registry);
            AssetDatabase.SaveAssets();

            // ---------- Build Tokens (one per family) ----------
            VoxelEngine.Building.Tiered.BuildToken MakeToken(
                VoxelEngine.Building.Tiered.BuildFamily fam, string display, Color tint, string description)
            {
                string path = $"{tieredTokens}/Token_{display}.asset";
                bool tokenCreated = AssetDatabase.LoadMainAssetAtPath(path) == null;
                var tok = GetOrCreateAsset<VoxelEngine.Building.Tiered.BuildToken>(path);

                tok.family = fam;
                if (tokenCreated)
                {
                    tok.itemId      = "build_" + display.ToLowerInvariant();
                    tok.displayName = display + " (Build)";
                    tok.description = description;
                    tok.iconTint    = tint;
                    tok.maxStack    = 99;
                }
                EditorUtility.SetDirty(tok);
                return tok;
            }
            var tokFoundation = MakeToken(VoxelEngine.Building.Tiered.BuildFamily.Foundation, "Foundation", new Color(0.55f, 0.40f, 0.25f), "The base of every building. Place on flat ground first; everything else snaps to its top and edges. Hold in active hotbar slot to enter build mode. RMB places at Wood tier (consumes resources). Use the Hammer to upgrade placed pieces. Toggle grid-snap with G. Press R (or Ctrl+Wheel) to rotate the ghost 90 degrees.");
            var tokWall       = MakeToken(VoxelEngine.Building.Tiered.BuildFamily.Wall,       "Wall",       new Color(0.55f, 0.40f, 0.25f), "A solid 3.75 m wall panel. Snaps to foundation top edges. Hold in active hotbar slot to enter build mode. RMB places at Wood tier (consumes resources). Use the Hammer to upgrade placed pieces. Toggle grid-snap with G. Press R (or Ctrl+Wheel) to rotate the ghost 90 degrees.");
            var tokDoorway    = MakeToken(VoxelEngine.Building.Tiered.BuildFamily.Doorway,    "Doorway",    new Color(0.55f, 0.40f, 0.25f), "A player-sized structural opening with a center socket for a separately placed Door. Select with the Hammer and place with RMB.");
            var tokWindow     = MakeToken(VoxelEngine.Building.Tiered.BuildFamily.Window,     "Window",     new Color(0.55f, 0.40f, 0.25f), "A wall with a window opening. Lets light through and lets you peek out. Hold in active hotbar slot to enter build mode. RMB places at Wood tier (consumes resources). Use the Hammer to upgrade placed pieces. Toggle grid-snap with G. Press R (or Ctrl+Wheel) to rotate the ghost 90 degrees.");
            var tokFloor      = MakeToken(VoxelEngine.Building.Tiered.BuildFamily.Floor,      "Floor",      new Color(0.55f, 0.40f, 0.25f), "A 3.75 m floor slab. Place on top of walls/pillars to make second stories. Hold in active hotbar slot to enter build mode. RMB places at Wood tier (consumes resources). Use the Hammer to upgrade placed pieces. Toggle grid-snap with G. Press R (or Ctrl+Wheel) to rotate the ghost 90 degrees.");
            var tokStairs     = MakeToken(VoxelEngine.Building.Tiered.BuildFamily.Stairs,     "Stairs",     new Color(0.55f, 0.40f, 0.25f), "A full-storey staircase. Aim at a Foundation/Floor side or Doorway threshold to snap downward; aim at a top perimeter edge to build upward. RMB places at Wood tier. Press R (or Ctrl+Wheel) to rotate around the anchored tread.");
            var tokRoof       = MakeToken(VoxelEngine.Building.Tiered.BuildFamily.Roof,       "Roof",       new Color(0.55f, 0.40f, 0.25f), "A sloped roof slab. Place on top of walls to seal the room. Hold in active hotbar slot to enter build mode. RMB places at Wood tier (consumes resources). Use the Hammer to upgrade placed pieces. Toggle grid-snap with G. Press R (or Ctrl+Wheel) to rotate the ghost 90 degrees.");
            var tokPillar     = MakeToken(VoxelEngine.Building.Tiered.BuildFamily.Pillar,     "Pillar",     new Color(0.55f, 0.40f, 0.25f), "A vertical column. Hosts walls on its sides and floors/roofs on its top. Hold in active hotbar slot to enter build mode. RMB places at Wood tier (consumes resources). Use the Hammer to upgrade placed pieces. Toggle grid-snap with G. Press R (or Ctrl+Wheel) to rotate the ghost 90 degrees.");
            var tokHalfWall   = MakeToken(VoxelEngine.Building.Tiered.BuildFamily.HalfWall,   "HalfWall",   new Color(0.55f, 0.40f, 0.25f), "A half-height wall for railings and counters. Select with the Hammer and place with RMB.");
            var tokDoor       = MakeToken(VoxelEngine.Building.Tiered.BuildFamily.Door,       "Door",       new Color(0.48f, 0.34f, 0.22f), "A separate hinged door that snaps into a Doorway center socket and opens away from whichever side the player approaches. Place with RMB and toggle with RMB when not building.");
            tokDoorway.description = "A player-sized structural opening with a center socket for a separately placed Door. Select with the Hammer and place with RMB.";
            EditorUtility.SetDirty(tokDoorway);

            // ---------- Hammer tool ----------
            string hammerPath = $"{itemsFolder}/Tool_Hammer.asset";
            var hammer = AssetDatabase.LoadAssetAtPath<VoxelEngine.Building.Tiered.Hammer>(hammerPath);
            bool hammerCreated = hammer == null;
            if (hammerCreated)
            {
                hammer = ScriptableObject.CreateInstance<VoxelEngine.Building.Tiered.Hammer>();
                AssetDatabase.CreateAsset(hammer, hammerPath);
                hammer.itemId        = "hammer";
                hammer.displayName   = "Hammer";
                hammer.toolType      = VoxelEngine.Items.ToolType.Other;
                hammer.miningTier    = 0;
                hammer.maxDurability = 500;
                hammer.strength      = 1f;
                hammer.fireRate      = 4f;
                hammer.brushRadius   = 0.1f;
                hammer.iconTint      = new Color(0.85f, 0.55f, 0.20f);
                hammer.description   = "Used to upgrade placed buildings to their next tier. " +
                    "Hold in active hotbar slot, look at a placed wood/stone/iron building, then LMB. " +
                    "Each upgrade consumes the cost shown on the block. Wood -> Stone -> Iron -> Steel.";
                EditorUtility.SetDirty(hammer);
            }

            // ---------- Add recipes for all 9 build tokens + the hammer (Crafting Bench tier) ----------
            var recipeRegistry = AssetDatabase.LoadAssetAtPath<VoxelEngine.Crafting.RecipeRegistry>($"{ASSET_ROOT}/RecipeRegistry.asset");
            if (recipeRegistry == null)
            {
                EditorUtility.DisplayDialog("Voxel Engine",
                    "Run Step 4 first — RecipeRegistry.asset doesn\'t exist yet.", "OK");
                return;
            }

            VoxelEngine.Crafting.RecipeDefinition EnsureTieredRecipe(
                string assetName,
                string displayName,
                VoxelEngine.Items.ItemDefinition output,
                int outputCount,
                VoxelEngine.Crafting.StationTier station,
                params (VoxelEngine.Items.ItemDefinition item, int n)[] inputs)
            {
                var existing = FindRecipeByName(assetName);
                if (existing != null)
                {
                    if (!recipeRegistry.recipes.Contains(existing)) recipeRegistry.recipes.Add(existing);
                    return existing;
                }
                return AddRecipe(assetName, displayName, output, outputCount, station, inputs);
            }

            // Hammer is craftable in inventory (you need it to upgrade anything).
            EnsureTieredRecipe("Recipe_Hammer", "Hammer", hammer, 1, VoxelEngine.Crafting.StationTier.None, ((VoxelEngine.Items.ItemDefinition)woodLog, 2), ((VoxelEngine.Items.ItemDefinition)plank, 2));

            // Build tokens — all from the Crafting Bench so the player has a small barrier.
            EnsureTieredRecipe("Recipe_Tok_Foundation", "Foundation Token", tokFoundation, 1, VoxelEngine.Crafting.StationTier.CraftingBench, ((VoxelEngine.Items.ItemDefinition)plank, 2));
            EnsureTieredRecipe("Recipe_Tok_Wall", "Wall Token", tokWall, 1, VoxelEngine.Crafting.StationTier.CraftingBench, ((VoxelEngine.Items.ItemDefinition)plank, 2));
            EnsureTieredRecipe("Recipe_Tok_Doorway", "Doorway Token", tokDoorway, 1, VoxelEngine.Crafting.StationTier.CraftingBench, ((VoxelEngine.Items.ItemDefinition)plank, 2));
            EnsureTieredRecipe("Recipe_Tok_Window", "Window Token", tokWindow, 1, VoxelEngine.Crafting.StationTier.CraftingBench, ((VoxelEngine.Items.ItemDefinition)plank, 2));
            EnsureTieredRecipe("Recipe_Tok_Floor", "Floor Token", tokFloor, 1, VoxelEngine.Crafting.StationTier.CraftingBench, ((VoxelEngine.Items.ItemDefinition)plank, 2));
            EnsureTieredRecipe("Recipe_Tok_Stairs", "Stairs Token", tokStairs, 1, VoxelEngine.Crafting.StationTier.CraftingBench, ((VoxelEngine.Items.ItemDefinition)plank, 2));
            EnsureTieredRecipe("Recipe_Tok_Roof", "Roof Token", tokRoof, 1, VoxelEngine.Crafting.StationTier.CraftingBench, ((VoxelEngine.Items.ItemDefinition)plank, 2));
            EnsureTieredRecipe("Recipe_Tok_Pillar", "Pillar Token", tokPillar, 1, VoxelEngine.Crafting.StationTier.CraftingBench, ((VoxelEngine.Items.ItemDefinition)plank, 2));
            EnsureTieredRecipe("Recipe_Tok_HalfWall", "Half Wall Token", tokHalfWall, 1, VoxelEngine.Crafting.StationTier.CraftingBench, ((VoxelEngine.Items.ItemDefinition)plank, 2));
            EnsureTieredRecipe("Recipe_Tok_Door", "Door Token", tokDoor, 1, VoxelEngine.Crafting.StationTier.CraftingBench, ((VoxelEngine.Items.ItemDefinition)plank, 4), ((VoxelEngine.Items.ItemDefinition)woodLog, 1));

            // Apply the finite, late-game Quarry migration through the same tool run.
            // Only the explicitly requested depth/progression fields are changed.
            string survivalRoot = ASSET_ROOT + "/Survival";
            var quarryPrefabAsset = AssetDatabase.LoadAssetAtPath<GameObject>($"{survivalRoot}/MiscPrefabs/Quarry.prefab");
            if (quarryPrefabAsset != null)
            {
                string quarryPrefabPath = AssetDatabase.GetAssetPath(quarryPrefabAsset);
                var quarryRoot = PrefabUtility.LoadPrefabContents(quarryPrefabPath);
                var quarryComponent = quarryRoot.GetComponent<VoxelEngine.Transport.Quarry>();
                if (quarryComponent != null) quarryComponent.maximumMiningDepth = 64;
                PrefabUtility.SaveAsPrefabAsset(quarryRoot, quarryPrefabPath);
                PrefabUtility.UnloadPrefabContents(quarryRoot);
            }

            var quarryBlock = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.BlockItem>($"{survivalRoot}/MiscBlocks/Block_Quarry.asset");
            if (quarryBlock != null)
            {
                quarryBlock.description = "Late-game automated strip-miner. Excavates a 16×16 area to a finite 64-layer maximum depth. Accepts Range, Speed and Efficiency upgrades. Powered, Tier-3 mining.";
                EditorUtility.SetDirty(quarryBlock);
            }

            var quarryRecipe = AssetDatabase.LoadAssetAtPath<VoxelEngine.Crafting.RecipeDefinition>($"{survivalRoot}/MiscRecipes/Recipe_Quarry.asset");
            var quarrySteelPlate = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{ASSET_ROOT}/Industrial/Items/Item_SteelPlate.asset");
            var quarryGear = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{ASSET_ROOT}/Industrial/Items/Item_IronGear.asset");
            var quarryCircuit = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{ASSET_ROOT}/Industrial/Items/Item_Circuit.asset");
            var quarryAdvancedCircuit = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{ASSET_ROOT}/Industrial/Items/Item_AdvCircuit.asset");
            var quarryWire = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{ASSET_ROOT}/Industrial/Items/Item_CopperWire.asset");
            if (quarryRecipe != null && quarrySteelPlate != null && quarryGear != null
                && quarryCircuit != null && quarryAdvancedCircuit != null && quarryWire != null)
            {
                quarryRecipe.requiredStation = VoxelEngine.Crafting.StationTier.Assembler;
                quarryRecipe.inputs = new[]
                {
                    new VoxelEngine.Crafting.RecipeIngredient { item = quarrySteelPlate, count = 30 },
                    new VoxelEngine.Crafting.RecipeIngredient { item = quarryGear, count = 16 },
                    new VoxelEngine.Crafting.RecipeIngredient { item = quarryCircuit, count = 12 },
                    new VoxelEngine.Crafting.RecipeIngredient { item = quarryAdvancedCircuit, count = 4 },
                    new VoxelEngine.Crafting.RecipeIngredient { item = quarryWire, count = 20 }
                };
                EditorUtility.SetDirty(quarryRecipe);
            }

            var quarryResearch = AssetDatabase.LoadAssetAtPath<VoxelEngine.Research.ResearchNode>($"{ASSET_ROOT}/Research/Nodes/res_quarrying.asset");
            var quarrySciT2 = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ScienceItem>($"{itemsFolder}/Item_ScienceT2.asset");
            var quarrySciT3 = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ScienceItem>($"{itemsFolder}/Item_ScienceT3.asset");
            if (quarryResearch != null)
            {
                quarryResearch.displayName = "Advanced Quarrying";
                quarryResearch.description = "Late industrial automated mining with a configurable finite excavation depth and Range, Speed, and Efficiency upgrades.";
                quarryResearch.tier = 5;
                quarryResearch.researchSeconds = 180f;
                if (quarrySciT2 != null && quarrySciT3 != null)
                {
                    quarryResearch.cost = new[]
                    {
                        new VoxelEngine.Research.ResearchNode.ScienceCost { pack = quarrySciT2, count = 60 },
                        new VoxelEngine.Research.ResearchNode.ScienceCost { pack = quarrySciT3, count = 40 }
                    };
                }
                EditorUtility.SetDirty(quarryResearch);
            }
            Debug.Log("[VoxelEngineSetupWindow] Step 5 verified finite Quarry depth and late-game progression without changing power tuning.");

            EditorUtility.SetDirty(recipeRegistry);
            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();

            // ---------- Wire registry into any existing BuildSystemV2 in the scene ----------
            var systems = Object.FindObjectsByType<VoxelEngine.Building.Tiered.BuildSystemV2>(FindObjectsInactive.Include);
            foreach (var sys in systems)
            {
                sys.registry = registry;
                sys.gridSize = constructionModuleSize;
                sys.socketSnapRadius = 3.25f;
                EditorUtility.SetDirty(sys);
            }

            Debug.Log($"[VoxelEngineSetupWindow] Step 5 complete. Size-V5 prefabs migrated={migratedSizeV5PrefabCount}. Existing custom geometry, materials, costs, health, and other balance values were preserved.");
            EditorUtility.DisplayDialog("Voxel Engine",
                "Tiered building content created!\n\n" +
                "* 40 prefabs (10 families x 4 tiers) in " + tieredPrefabs + "\n" +
                "* 10 build tokens + Hammer\n" +
                "* 11 recipes created or connected in RecipeRegistry\n" +
                "* TieredBlockRegistry asset created\n" +
                $"* Size-V5 prefabs migrated this run: {migratedSizeV5PrefabCount}\n" +
                "* Seamless Foundation deck, bidirectional edge/doorway stairs, player-away Doors, and finite late-game Quarry migration verified\n\n" +
                "Re-run Step 2 to spawn a player with BuildSystemV2 wired up,\n" +
                "or manually add the BuildSystemV2 component and assign the registry.",
                "OK");
        }

        // ---------- Tiered prefab building helpers (used by BuildTieredContent) ----------
        private static GameObject AddBox(GameObject parent, Material mat, Vector3 localPos, Vector3 localScale)
        {
            var go = GameObject.CreatePrimitive(PrimitiveType.Cube);
            go.name = "Box";
            go.transform.SetParent(parent.transform, false);
            go.transform.localPosition = localPos;
            go.transform.localScale    = localScale;
            go.GetComponent<Renderer>().sharedMaterial = mat;
            // Keep collider on for raycasts to find the placed block.
            return go;
        }

        private static void AddSocket(GameObject parent,
            VoxelEngine.Building.Tiered.SocketSide side, Vector3 localPos,
            VoxelEngine.Building.Tiered.BuildFamily family, float localYaw = 0f)
        {
            var go = new GameObject($"Socket_{side}");
            go.transform.SetParent(parent.transform, false);
            go.transform.localPosition = localPos;
            go.transform.localRotation = Quaternion.Euler(0f, localYaw, 0f);
            var sock = go.AddComponent<VoxelEngine.Building.Tiered.BuildSocket>();
            sock.side   = side;
            sock.family = family;
        }

        // ============================================================
        //              STEP 6 - POWER STARTER CONTENT
        // ============================================================
        private void BuildPowerContent()
        {
            const string powerFolder    = ASSET_ROOT + "/Power";
            const string pipesFolder    = powerFolder + "/ElectricalPipes";
            const string prefabsFolder  = powerFolder + "/Prefabs";
            const string blocksFolder   = powerFolder + "/Blocks";
            const string recipesFolder  = powerFolder + "/Recipes";

            EnsureFolder(powerFolder);
            EnsureFolder(pipesFolder);
            EnsureFolder(prefabsFolder);
            EnsureFolder(blocksFolder);
            EnsureFolder(recipesFolder);

            string itemsFolder = ASSET_ROOT + "/Items";
            string indItems    = ASSET_ROOT + "/Industrial/Items";
            var copperIngot = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{itemsFolder}/Item_CopperIngot.asset");
            var ironIngot   = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{itemsFolder}/Item_IronIngot.asset");
            var steelIngot  = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{itemsFolder}/Item_SteelIngot.asset");
            var graphite    = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{indItems}/Item_Graphite.asset");
            var stone       = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{ITEM_FOLDER}/Item_Stone.asset");
            var coal        = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{ITEM_FOLDER}/Item_Coal.asset");
            var goldOre     = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{ITEM_FOLDER}/Item_Gold.asset");
            var copperWire  = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{indItems}/Item_CopperWire.asset");

            var lithium     = EnsureLithiumResource();
            if (copperIngot == null || ironIngot == null || steelIngot == null)
            {
                EditorUtility.DisplayDialog("Voxel Engine",
                    "Run Step 4 (Build Crafting Content) first - it creates Iron / Copper / Steel ingots which the power system needs.", "OK");
                return;
            }

            var registrySO = AssetDatabase.LoadAssetAtPath<VoxelEngine.Crafting.RecipeRegistry>($"{ASSET_ROOT}/RecipeRegistry.asset");

            // ── Electrical Pipe Definitions ──
            VoxelEngine.Power.ElectricalPipeDefinition MakePipeDef(string name, float cap, Color tint)
            {
                string path = $"{pipesFolder}/Pipe_{name.Replace(" ", "")}.asset";
                var w = GetOrCreateAsset<VoxelEngine.Power.ElectricalPipeDefinition>(path);
                w.displayName   = name + " Electrical Pipe";
                w.capacityWatts = cap;
                w.tint          = tint;
                w.connectRadius = 1.6f;
                EditorUtility.SetDirty(w);
                return w;
            }
            var pipeCopper = MakePipeDef("Copper",         10000f, new Color(0.85f, 0.45f, 0.20f));
            var pipeIron   = MakePipeDef("Iron",           30000f, new Color(0.78f, 0.78f, 0.85f));
            var pipeGold   = MakePipeDef("Gold",           50000f, new Color(0.95f, 0.78f, 0.20f));
            var pipeSuper  = MakePipeDef("Superconductor", 1000000000f, new Color(0.45f, 0.85f, 1.00f));

            // ── Prefab Helper ──
            GameObject MakePowerPrefabInternal<T>(string assetName, Color color, Vector3 scale, System.Action<T> configure) where T : VoxelEngine.Power.PowerNode
            {
                string path = $"{prefabsFolder}/{assetName}.prefab";
                return GetOrCreatePrefab(path, assetName, (root) =>
                {
                    if (root.transform.childCount == 0)
                    {
                        var cube = GameObject.CreatePrimitive(PrimitiveType.Cube);
                        cube.transform.SetParent(root.transform, false);
                        cube.transform.localScale = scale;
                        var mat = MakeColoredMat(prefabsFolder, $"Mat_{assetName}", color);
                        cube.GetComponent<Renderer>().sharedMaterial = mat;
                        if (cube.TryGetComponent<Collider>(out var col)) Object.DestroyImmediate(col);
                    }
                    var node = EnsureComponent<T>(root);
                    configure?.Invoke(node);
                    if (assetName == "Generator_Coal")
                    {
                        var fuel = root.GetComponent<VoxelEngine.Power.CoalGeneratorFuel>();
                        if (fuel == null) fuel = root.AddComponent<VoxelEngine.Power.CoalGeneratorFuel>();
                        var ports = root.GetComponent<VoxelEngine.Transport.PortConfig>();
                        if (ports != null) ports.showPortIndicators = false;
                    }
                    if (root.GetComponent<Collider>() == null) root.AddComponent<BoxCollider>();
                });
            }

            var prefabPipeCu = MakePowerPrefabInternal<VoxelEngine.Power.PowerCable>("EnergyPipe_Copper", pipeCopper.tint, new Vector3(0.25f, 0.25f, 1f), c => { c.wire = pipeCopper; });
            var prefabPipeFe = MakePowerPrefabInternal<VoxelEngine.Power.PowerCable>("EnergyPipe_Iron", pipeIron.tint, new Vector3(0.25f, 0.25f, 1f), c => { c.wire = pipeIron; });
            var prefabPipeAu = MakePowerPrefabInternal<VoxelEngine.Power.PowerCable>("EnergyPipe_Gold", pipeGold.tint, new Vector3(0.25f, 0.25f, 1f), c => { c.wire = pipeGold; });
            var prefabPipeSc = MakePowerPrefabInternal<VoxelEngine.Power.PowerCable>("EnergyPipe_Superconductor", pipeSuper.tint, new Vector3(0.25f, 0.25f, 1f), c => { c.wire = pipeSuper; });

            var genPrefab = MakePowerPrefabInternal<VoxelEngine.Power.PowerGenerator>("Generator_Coal", new Color(0.30f, 0.30f, 0.32f), new Vector3(1.5f, 1.5f, 1.5f), g => { g.wattsPerSecond = 800f; g.isOn = false; g.connectRadius = 1.8f; });
            var batPrefab = MakePowerPrefabInternal<VoxelEngine.Power.PowerBattery>("Battery_Basic", new Color(0.20f, 0.50f, 0.85f), new Vector3(0.8f, 1.2f, 0.8f), b =>
            {
                b.capacityWattHours = 10000f; b.ioRate = 200f; b.connectRadius = 1.5f;
                // Device charger (6.77): only seed a default — never overwrite a tuned value.
                if (b.itemChargeRateWatts <= 0f) b.itemChargeRateWatts = 500f;
            });
            var lightPrefab = MakePowerPrefabInternal<VoxelEngine.Power.PowerConsumer>("Light_Basic", new Color(1f, 0.95f, 0.6f), new Vector3(0.3f, 0.3f, 0.3f), c => { c.wattsPerSecond = 10f; c.connectRadius = 1.5f; });

            // ── Block Item Helper ──
            VoxelEngine.Items.BlockItem MakePowerBlockInternal(string assetName, string display, Color tint, GameObject prefab, string desc, int hp = 200)
            {
                string path = $"{blocksFolder}/{assetName}.asset";
                var b = GetOrCreateAsset<VoxelEngine.Items.BlockItem>(path);
                b.itemId       = assetName.ToLower();
                b.displayName  = display;
                b.description  = desc;
                b.iconTint     = tint;
                b.maxStack     = 99;
                b.massPerUnit  = 3f;
                b.placedPrefab = prefab;
                b.gridSize     = Vector3Int.one;
                b.allowStacking= prefab != null && prefab.GetComponent<VoxelEngine.Power.PowerCable>() != null;
                b.blockHealth  = hp;
                b.miningTier   = 1;
                b.category     = "Power";
                EditorUtility.SetDirty(b);
                return b;
            }

            var blockPipeCu = MakePowerBlockInternal("Block_EnergyPipe_Copper", "Copper Energy Pipe", pipeCopper.tint, prefabPipeCu, "High-capacity energy pipe. Carries up to 10,000 W.");
            var blockPipeFe = MakePowerBlockInternal("Block_EnergyPipe_Iron", "Iron Energy Pipe", pipeIron.tint, prefabPipeFe, "Reinforced energy pipe. Carries up to 30,000 W.");
            var blockPipeAu = MakePowerBlockInternal("Block_EnergyPipe_Gold", "Gold Energy Pipe", pipeGold.tint, prefabPipeAu, "Premium energy pipe. Carries up to 50,000 W.");
            var blockPipeSc = MakePowerBlockInternal("Block_EnergyPipe_Superconductor", "Superconductor Energy Pipe", pipeSuper.tint, prefabPipeSc, "Near-zero resistance energy pipe. Unlimited power transfer.");

            void MigrateLegacyEnergyPipeBlock(string oldAssetName, string display, string description, Color tint, GameObject prefab)
            {
                var legacy = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.BlockItem>($"{blocksFolder}/{oldAssetName}.asset");
                if (legacy == null) return;
                legacy.displayName = display;
                legacy.description = description;
                legacy.iconTint = tint;
                legacy.category = "Power";
                legacy.allowStacking = true;
                if (prefab != null) legacy.placedPrefab = prefab;
                EditorUtility.SetDirty(legacy);
            }
            MigrateLegacyEnergyPipeBlock("Block_Pipe_Copper", "Copper Energy Pipe", "High-capacity energy pipe. Carries up to 10,000 W.", pipeCopper.tint, prefabPipeCu);
            MigrateLegacyEnergyPipeBlock("Block_Pipe_Iron", "Iron Energy Pipe", "Reinforced energy pipe. Carries up to 30,000 W.", pipeIron.tint, prefabPipeFe);
            MigrateLegacyEnergyPipeBlock("Block_Pipe_Gold", "Gold Energy Pipe", "Premium energy pipe. Carries up to 50,000 W.", pipeGold.tint, prefabPipeAu);
            MigrateLegacyEnergyPipeBlock("Block_Pipe_Super", "Superconductor Energy Pipe", "Near-zero resistance energy pipe. Unlimited power transfer.", pipeSuper.tint, prefabPipeSc);

            var blockGen   = MakePowerBlockInternal("Block_Gen_Coal", "Coal Generator", new Color(0.30f,0.30f,0.32f), genPrefab, "Burns coal to produce 800 W of electricity.", hp: 600);
            var blockBat   = MakePowerBlockInternal("Block_Battery", "Battery", new Color(0.20f,0.50f,0.85f), batPrefab, "Stores up to 10000 Wh.", hp: 400);
            var blockLight = MakePowerBlockInternal("Block_Light", "Power Light", new Color(1f,0.95f,0.6f), lightPrefab, "Consumes 10 W.", hp: 80);

            // ── LV Manual Wires ──
            var lvWireCu = MakeResource(itemsFolder, "Copper LV Wire", new Color(0.85f, 0.45f, 0.20f), 100, VoxelEngine.Items.ResourceCategory.Component, uiCategory: "Wire");
            lvWireCu.itemId = "copper_lv_wire";
            lvWireCu.description = "Manual low-voltage wire item. Hold it and left-click two LV stations/connectors to link them; it is not an energy pipe block.";
            var lvWireAu = MakeResource(itemsFolder, "Gold LV Wire", new Color(0.95f, 0.85f, 0.20f), 100, VoxelEngine.Items.ResourceCategory.Component, uiCategory: "Wire");
            lvWireAu.itemId = "gold_lv_wire";
            lvWireAu.description = "Manual low-voltage wire item. Hold it and left-click two LV stations/connectors to link them; it is not an energy pipe block.";
            var lvWireGr = MakeResource(itemsFolder, "Graphite LV Wire", new Color(0.20f, 0.20f, 0.20f), 100, VoxelEngine.Items.ResourceCategory.Component, uiCategory: "Wire");
            lvWireGr.itemId = "graphite_lv_wire";
            lvWireGr.description = "Manual low-voltage wire item. Hold it and left-click two LV stations/connectors to link them; it is not an energy pipe block.";


            if (registrySO != null)
            {
                AddRecipe(registrySO, recipesFolder, "Recipe_EnergyPipe_Copper", "Copper Energy Pipe", blockPipeCu, 4, VoxelEngine.Crafting.StationTier.CraftingBench, true, ((VoxelEngine.Items.ItemDefinition)copperIngot, 2), ((VoxelEngine.Items.ItemDefinition)ironIngot, 1));
                AddRecipe(registrySO, recipesFolder, "Recipe_EnergyPipe_Iron", "Iron Energy Pipe", blockPipeFe, 4, VoxelEngine.Crafting.StationTier.CraftingBench, true, ((VoxelEngine.Items.ItemDefinition)ironIngot, 4));
                AddRecipe(registrySO, recipesFolder, "Recipe_EnergyPipe_Gold", "Gold Energy Pipe", blockPipeAu, 4, VoxelEngine.Crafting.StationTier.Assembler, true, ((VoxelEngine.Items.ItemDefinition)goldOre != null ? goldOre : ironIngot, 2), ((VoxelEngine.Items.ItemDefinition)ironIngot, 2));
                AddRecipe(registrySO, recipesFolder, "Recipe_EnergyPipe_Super", "Superconductor Energy Pipe", blockPipeSc, 4, VoxelEngine.Crafting.StationTier.Assembler, true, ((VoxelEngine.Items.ItemDefinition)steelIngot, 4), ((VoxelEngine.Items.ItemDefinition)goldOre != null ? goldOre : ironIngot, 2));

                AddRecipe(registrySO, recipesFolder, "Recipe_Generator", "Coal Generator", blockGen, 1, VoxelEngine.Crafting.StationTier.CraftingBench, true, ((VoxelEngine.Items.ItemDefinition)ironIngot, 4), ((VoxelEngine.Items.ItemDefinition)stone, 4));
                AddRecipe(registrySO, recipesFolder, "Recipe_Battery", "Battery", blockBat, 1, VoxelEngine.Crafting.StationTier.Assembler, true, ((VoxelEngine.Items.ItemDefinition)copperIngot, 4), ((VoxelEngine.Items.ItemDefinition)ironIngot, 2), ((VoxelEngine.Items.ItemDefinition)lithium, 2));
                AddRecipe(registrySO, recipesFolder, "Recipe_Light", "Power Light", blockLight, 1, VoxelEngine.Crafting.StationTier.CraftingBench, true, ((VoxelEngine.Items.ItemDefinition)copperIngot, 1));

                AddRecipe(registrySO, recipesFolder, "Recipe_Wire_Cu_LV", "Copper LV Wire", lvWireCu, 5, VoxelEngine.Crafting.StationTier.None, true, ((VoxelEngine.Items.ItemDefinition)copperWire, 1));
                AddRecipe(registrySO, recipesFolder, "Recipe_Wire_Au_LV", "Gold LV Wire", lvWireAu, 5, VoxelEngine.Crafting.StationTier.Assembler, true, ((VoxelEngine.Items.ItemDefinition)goldOre != null ? goldOre : ironIngot, 1), ((VoxelEngine.Items.ItemDefinition)copperWire, 2));
                AddRecipe(registrySO, recipesFolder, "Recipe_Wire_Gr_LV", "Graphite LV Wire", lvWireGr, 5, VoxelEngine.Crafting.StationTier.Assembler, true, ((VoxelEngine.Items.ItemDefinition)graphite != null ? graphite : coal, 2), ((VoxelEngine.Items.ItemDefinition)copperWire, 2));
            }

        }
        private void BuildResearchContent()
        {
            const string researchFolder = ASSET_ROOT + "/Research";
            const string nodesFolder    = researchFolder + "/Nodes";
            const string itemsFolder    = ASSET_ROOT + "/Items";
            const string recipesFolder  = researchFolder + "/Recipes";
            const string prefabsFolder  = researchFolder + "/Prefabs";

            EnsureFolder(researchFolder);
            EnsureFolder(nodesFolder);
            EnsureFolder(recipesFolder);
            EnsureFolder(prefabsFolder);

            // ---- Pull existing items needed for science pack recipes ----
            var woodLog     = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{itemsFolder}/Item_WoodLog.asset");
            var plank       = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{itemsFolder}/Item_WoodenPlank.asset");
            var stone       = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{ITEM_FOLDER}/Item_Stone.asset");
            var coal        = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{ITEM_FOLDER}/Item_Coal.asset");
            var ironIngot   = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{itemsFolder}/Item_IronIngot.asset");
            var copperIngot = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{itemsFolder}/Item_CopperIngot.asset");
            var steelIngot  = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{itemsFolder}/Item_SteelIngot.asset");
            if (woodLog == null || ironIngot == null)
            {
                EditorUtility.DisplayDialog("Voxel Engine",
                    "Run Step 4 (Build Crafting Content) first - it creates wood/iron items the research tree needs.", "OK");
                return;
            }

            // ---- 1) Science pack items ----
            VoxelEngine.Items.ScienceItem MakeScience(string assetName, string display, Color tint, int tier, string desc)
            {
                string path = $"{itemsFolder}/{assetName}.asset";
                var sci = ScriptableObject.CreateInstance<VoxelEngine.Items.ScienceItem>();
                sci.itemId      = assetName.ToLower();
                sci.displayName = display;
                sci.description = desc;
                sci.iconTint    = tint;
                sci.maxStack    = 999;
                sci.massPerUnit = 0.5f;
                sci.category    = "Science";
                sci.subcategory = VoxelEngine.Items.ResourceCategory.Misc;
                sci.tier        = tier;
                AssetDatabase.CreateAsset(sci, path);
                return sci;
            }
            var sciT1 = MakeScience("Item_ScienceT1", "Science Pack I",   new Color(0.85f, 0.30f, 0.30f), 1,
                "Tier 1 research input. Crafted in your inventory from wood + stone.");
            var sciT2 = MakeScience("Item_ScienceT2", "Science Pack II",  new Color(0.30f, 0.75f, 0.40f), 2,
                "Tier 2 research input. Crafted at a Crafting Bench from iron + copper ingots.");
            var sciT3 = MakeScience("Item_ScienceT3", "Science Pack III", new Color(0.30f, 0.60f, 0.95f), 3,
                "Tier 3 research input. Crafted at an Assembler from steel + circuitry.");

            // ---- 2) Research Lab prefab ----
            string labPath = $"{prefabsFolder}/ResearchLab.prefab";
            var labRoot = new GameObject("ResearchLab");
            var cube = GameObject.CreatePrimitive(PrimitiveType.Cube);
            cube.transform.SetParent(labRoot.transform, false);
            cube.transform.localScale = new Vector3(1.6f, 1.4f, 1.2f);
            var mat = MakeColoredMat(prefabsFolder, "Mat_ResearchLab", new Color(0.50f, 0.30f, 0.70f));
            cube.GetComponent<Renderer>().sharedMaterial = mat;
            var stat = labRoot.AddComponent<VoxelEngine.Crafting.CraftingStation>();
            stat.tier        = VoxelEngine.Crafting.StationTier.Assembler;
            stat.displayName = "Research Lab";
            labRoot.AddComponent<VoxelEngine.Research.ResearchLab>();
            var labPrefab = PrefabUtility.SaveAsPrefabAsset(labRoot, labPath);
            Object.DestroyImmediate(labRoot);

            string labBlockPath = $"{researchFolder}/Block_ResearchLab.asset";
            var blockLab = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.BlockItem>(labBlockPath);
            if (blockLab == null)
            {
                blockLab = ScriptableObject.CreateInstance<VoxelEngine.Items.BlockItem>();
                AssetDatabase.CreateAsset(blockLab, labBlockPath);
            }
            blockLab.itemId       = "block_researchlab";
            blockLab.displayName  = "Research Lab";
            blockLab.description  = "Place to research new technologies. Drop science packs in its slots, then start a research from the Research menu (Y).";
            blockLab.iconTint     = new Color(0.50f, 0.30f, 0.70f);
            blockLab.maxStack     = 99;
            blockLab.placedPrefab = labPrefab;
            blockLab.gridSize     = Vector3Int.one;
            blockLab.blockHealth  = 600;
            blockLab.miningTier   = 1;
            blockLab.category     = "Stations";
            EditorUtility.SetDirty(blockLab);

            // ---- 3) Recipes for science packs + lab ----
            var recipeRegistry = AssetDatabase.LoadAssetAtPath<VoxelEngine.Crafting.RecipeRegistry>($"{ASSET_ROOT}/RecipeRegistry.asset");
            if (recipeRegistry == null)
            {
                EditorUtility.DisplayDialog("Voxel Engine",
                    "Run Step 4 first - RecipeRegistry.asset doesn\'t exist.", "OK");
                return;
            }
            // Science pack recipes (always unlocked).
            var recSci1 = AddRecipe("Recipe_ScienceT1", "Science Pack I", sciT1, 1, VoxelEngine.Crafting.StationTier.None, true, ((VoxelEngine.Items.ItemDefinition)woodLog, 1), ((VoxelEngine.Items.ItemDefinition)stone, 1));
            var recSci2 = AddRecipe("Recipe_ScienceT2", "Science Pack II", sciT2, 1, VoxelEngine.Crafting.StationTier.CraftingBench, true, ((VoxelEngine.Items.ItemDefinition)ironIngot, 1), ((VoxelEngine.Items.ItemDefinition)copperIngot, 1));
            var recSci3 = AddRecipe("Recipe_ScienceT3", "Science Pack III", sciT3, 1, VoxelEngine.Crafting.StationTier.Assembler, true, ((VoxelEngine.Items.ItemDefinition)steelIngot, 1), ((VoxelEngine.Items.ItemDefinition)copperIngot, 2));
            var recLab  = AddRecipe("Recipe_ResearchLab", "Research Lab", blockLab, 1, VoxelEngine.Crafting.StationTier.CraftingBench, true, ((VoxelEngine.Items.ItemDefinition)plank, 4), ((VoxelEngine.Items.ItemDefinition)copperIngot, 2));

            // ---- 4) Find some existing recipes we'll gate behind research ----
            // We re-gate a few recipes that were previously unlockedByDefault. Players will need
            // to research them via the new nodes.
            VoxelEngine.Crafting.RecipeDefinition FindRecipe(string assetName)
            {
                var guids = AssetDatabase.FindAssets($"{assetName} t:RecipeDefinition");
                foreach (var g in guids)
                {
                    var p2 = AssetDatabase.GUIDToAssetPath(g);
                    if (System.IO.Path.GetFileNameWithoutExtension(p2) == assetName)
                        return AssetDatabase.LoadAssetAtPath<VoxelEngine.Crafting.RecipeDefinition>(p2);
                }
                return null;
            }
            var recPickStone = FindRecipe("Recipe_PickStone");
            var recPickIron  = FindRecipe("Recipe_PickIron");
            var recPickSteel = FindRecipe("Recipe_PickSteel");
            var recFurnace   = FindRecipe("Recipe_Furnace");
            var recElectric  = FindRecipe("Recipe_ElectricFurnace");
            var recGenerator = FindRecipe("Recipe_Generator");
            var recBattery   = FindRecipe("Recipe_Battery");
            var recAssembler = FindRecipe("Recipe_Assembler");
            var recPipeCu   = FindRecipe("Recipe_EnergyPipe_Copper");
            var recPipeFe   = FindRecipe("Recipe_EnergyPipe_Iron");
            var recPipeAu   = FindRecipe("Recipe_EnergyPipe_Gold");
            var recPipeSc   = FindRecipe("Recipe_EnergyPipe_Super");
            var recWireLV    = FindRecipe("Recipe_Wire_Cu_LV");
            var recWireAuLV  = FindRecipe("Recipe_Wire_Au_LV");
            var recWireGrLV  = FindRecipe("Recipe_Wire_Gr_LV");

            // Lock recipes that will require research. (Players who don't unlock these
            // can still play, but with reduced options.)
            void Lock(VoxelEngine.Crafting.RecipeDefinition r) { if (r != null) { r.unlockedByDefault = false; EditorUtility.SetDirty(r); } }
            Lock(recPickStone); Lock(recPickIron); Lock(recPickSteel);
            Lock(recFurnace);   Lock(recElectric);
            Lock(recGenerator); Lock(recBattery);  Lock(recAssembler);
            Lock(recPipeCu);   Lock(recPipeFe);  Lock(recPipeAu);  Lock(recPipeSc);
            Lock(recWireAuLV); Lock(recWireGrLV);

            // ---- 5) Research nodes (the tree) ----
            VoxelEngine.Research.ResearchNode MakeNode(
                string id, string display, string desc, int tier, int col,
                float seconds, (VoxelEngine.Items.ScienceItem p, int n)[] cost,
                VoxelEngine.Crafting.RecipeDefinition[] unlocks,
                VoxelEngine.Research.ResearchNode[] prereqs = null)
            {
                string path = $"{nodesFolder}/{id}.asset";
                var n = AssetDatabase.LoadAssetAtPath<VoxelEngine.Research.ResearchNode>(path); if (n == null) { n = ScriptableObject.CreateInstance<VoxelEngine.Research.ResearchNode>();  }
                n.nodeId      = id;
                n.displayName = display;
                n.description = desc;
                n.tier = tier; n.column = col;
                n.researchSeconds = seconds;
                n.cost = new VoxelEngine.Research.ResearchNode.ScienceCost[cost.Length];
                for (int i = 0; i < cost.Length; i++)
                    n.cost[i] = new VoxelEngine.Research.ResearchNode.ScienceCost { pack = cost[i].p, count = cost[i].n };
                n.unlocksRecipes = unlocks ?? new VoxelEngine.Crafting.RecipeDefinition[0];
                n.prerequisites = prereqs ?? new VoxelEngine.Research.ResearchNode[0];

                if (!AssetDatabase.Contains(n)) AssetDatabase.CreateAsset(n, path);
                else EditorUtility.SetDirty(n);

                return n;
            }

            var tree = ScriptableObject.CreateInstance<VoxelEngine.Research.ResearchTree>();

            // Tier 1 - basic survival
            var nStoneWorking = MakeNode("res_stone_working", "Stone Working",
                "Learn to shape stone tools. Unlocks the Stone Pickaxe and the Solid Fuel Furnace. " +
                "Tier 1: can be researched instantly from the menu (no Lab required).",
                1, 0, 0f, new[] { (sciT1, 5) },
                new[] { recPickStone, recFurnace });

            // Tier 2 - smelting / iron
            var nSmelting = MakeNode("res_smelting", "Smelting",
                "Refining ores into ingots opens metal-tier tools and machines.",
                2, 0, 40f, new[] { (sciT1, 10), (sciT2, 5) },
                new[] { recPickIron },
                new[] { nStoneWorking });

            var nElectricity = MakeNode("res_electricity", "Electricity",
                "Generate and store electric power. Unlocks the Coal Generator, Copper LV Wire, and early Energy Pipes.",
                2, 1, 40f, new[] { (sciT1, 10), (sciT2, 5) },
                new[] { recGenerator, recWireLV, recPipeCu, recPipeFe },
                new[] { nStoneWorking });

            // Tier 3 - advanced machines
            var nAdvManufacturing = MakeNode("res_adv_manufacturing", "Advanced Manufacturing",
                "Industrial-tier production unlocks the Assembler, Electric Furnace, Battery, and mid-tier wiring.",
                3, 0, 60f, new[] { (sciT2, 15), (sciT3, 5) },
                new[] { recAssembler, recElectric, recBattery, recWireAuLV, recPipeAu },
                new[] { nSmelting, nElectricity });

            var nSteelAlloy = MakeNode("res_steel_alloy", "Steel Alloy",
                "Combining iron and carbon yields steel - the strongest tool tier.",
                3, 1, 60f, new[] { (sciT2, 15), (sciT3, 5) },
                new[] { recPickSteel },
                new[] { nSmelting });

            // Look up wireless recipes (added in Step 6); include them in HV unlocks if found.
            var recWirelessTx = FindRecipe("Recipe_Wireless_Tx");
            var recWirelessRx = FindRecipe("Recipe_Wireless_Rx");
            var hvUnlocks = new System.Collections.Generic.List<VoxelEngine.Crafting.RecipeDefinition>
                            { recPipeAu, recPipeSc };
            if (recWirelessTx != null) hvUnlocks.Add(recWirelessTx);
            if (recWirelessRx != null) hvUnlocks.Add(recWirelessRx);

            var nHighVoltage = MakeNode("res_high_voltage", "High-Voltage Transmission",
                "Premium wire tiers carry more wattage between machines. Also unlocks Wireless Transmitter and Receiver.",
                3, 2, 60f, new[] { (sciT2, 10), (sciT3, 5) },
                hvUnlocks.ToArray(),
                new[] { nElectricity });

            tree.nodes.Add(nStoneWorking);
            tree.nodes.Add(nSmelting);
            tree.nodes.Add(nElectricity);
            tree.nodes.Add(nAdvManufacturing);
            tree.nodes.Add(nSteelAlloy);
            tree.nodes.Add(nHighVoltage);

            // ===== PLAYER UPGRADES =====
            // All player upgrades are instant (researchSeconds=0) and paid from inventory.
            // Most are REPEATABLE: each rank costs (rank+1) * baseCost when costScalesWithRank is true.
            VoxelEngine.Research.ResearchNode MakePlayerNode(
                string id, string display, string desc, int tier, int col,
                (VoxelEngine.Items.ScienceItem p, int n)[] cost,
                VoxelEngine.Research.PlayerUpgradeKind kind, float perRank, int maxRanks)
            {
                string path = $"{nodesFolder}/{id}.asset";
                var n = AssetDatabase.LoadAssetAtPath<VoxelEngine.Research.ResearchNode>(path); if (n == null) { n = ScriptableObject.CreateInstance<VoxelEngine.Research.ResearchNode>();  }
                n.nodeId = id;
                n.displayName = display;
                n.description = desc;
                n.category = VoxelEngine.Research.ResearchCategory.PlayerUpgrades;
                n.tier = tier; n.column = col;
                n.researchSeconds = 0f;
                n.upgradeKind = kind;
                n.upgradePerRankAmount = perRank;
                n.maxRanks = maxRanks;
                n.costScalesWithRank = (maxRanks > 1);
                n.cost = new VoxelEngine.Research.ResearchNode.ScienceCost[cost.Length];
                for (int i = 0; i < cost.Length; i++)
                    n.cost[i] = new VoxelEngine.Research.ResearchNode.ScienceCost { pack = cost[i].p, count = cost[i].n };

                if (!AssetDatabase.Contains(n)) AssetDatabase.CreateAsset(n, path);
                else EditorUtility.SetDirty(n);

                tree.nodes.Add(n);
                return n;
            }

            // Tier 1 — cheap, T1 science only.
            MakePlayerNode("up_hp",    "Vitality",
                "+20 max HP per rank. The body adapts to harsh environments.",
                1, 0, new[] { (sciT1, 3) },
                VoxelEngine.Research.PlayerUpgradeKind.BonusMaxHealth, 20f, 10);
            MakePlayerNode("up_stam",  "Endurance",
                "+15 max stamina per rank. Sprint and jump longer without resting.",
                1, 1, new[] { (sciT1, 3) },
                VoxelEngine.Research.PlayerUpgradeKind.BonusMaxStamina, 15f, 10);
            MakePlayerNode("up_dmg",   "Strength",
                "+2 flat damage per rank. Hit harder with any tool.",
                1, 2, new[] { (sciT1, 4) },
                VoxelEngine.Research.PlayerUpgradeKind.BonusDamage, 2f, 10);
            MakePlayerNode("up_inv",   "Pack Mule",
                "+5 backpack slots per rank. Carry more stuff back to base.",
                1, 3, new[] { (sciT1, 5) },
                VoxelEngine.Research.PlayerUpgradeKind.BonusInventorySlots, 5f, 6);

            // Tier 2 — requires T2 science as well.
            MakePlayerNode("up_sprint","Wind Sprinter",
                "+0.25 sprint speed multiplier per rank. CAPPED at 5x base speed.",
                2, 0, new[] { (sciT1, 5), (sciT2, 3) },
                VoxelEngine.Research.PlayerUpgradeKind.BonusSprintMultiplier, 0.25f, 10);

            // Tier 3 — Flight. Single-rank, ultra-expensive, requires a special artifact (TODO: artifact item).
            MakePlayerNode("up_flight","Flight",
                "Unlocks permanent flight (toggle with F or via Settings). " +
                "Requires a Mysterious Artifact (not yet implemented) plus a stack of Tier-3 science.",
                3, 0, new[] { (sciT3, 50) },
                VoxelEngine.Research.PlayerUpgradeKind.UnlockFlight, 1f, 1);

            string treePath = $"{researchFolder}/ResearchTree.asset";
            var existingTree = AssetDatabase.LoadAssetAtPath<VoxelEngine.Research.ResearchTree>(treePath);
            if (existingTree != null)
            {
                // Sync the existing tree instead of replacing it
                existingTree.nodes = tree.nodes;
                tree = existingTree;
            }
            else
            {
                AssetDatabase.CreateAsset(tree, treePath);
            }
            EditorUtility.SetDirty(tree);

            EditorUtility.SetDirty(recipeRegistry);
            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();

            // ---- 6) Ensure ResearchManager + ResearchUI exist in the scene ----
            var rm = Object.FindAnyObjectByType<VoxelEngine.Research.ResearchManager>();
            if (rm == null)
            {
                var rmGo = new GameObject("ResearchManager");
                rm = rmGo.AddComponent<VoxelEngine.Research.ResearchManager>();
            }
            rm.tree = tree;
            EditorUtility.SetDirty(rm);

            var ui = Object.FindAnyObjectByType<VoxelEngine.Research.ResearchUI>();
            if (ui == null)
            {
                var uiGo = new GameObject("ResearchUI");
                uiGo.AddComponent<UnityEngine.UIElements.UIDocument>();
                var panelSettings = AssetDatabase.LoadAssetAtPath<UnityEngine.UIElements.PanelSettings>(
                    "Assets/Resources/MenuPanelSettings.asset");
                if (panelSettings != null) uiGo.GetComponent<UnityEngine.UIElements.UIDocument>().panelSettings = panelSettings;
                uiGo.AddComponent<VoxelEngine.Research.ResearchUI>();
            }

            EditorUtility.DisplayDialog("Voxel Engine",
                "Research content created!\n\n" +
                "* 3 Science Packs (T1, T2, T3)\n" +
                "* Research Lab (placeable + crafted at Crafting Bench)\n" +
                "* 6 tech tree nodes (Stone Working -> Smelting/Electricity -> Adv Mfg / Steel / HV)\n" +
                "* 12 existing recipes are now gated behind research\n" +
                "* ResearchManager + ResearchUI spawned in the scene\n\n" +
                "Press Y in-game to open the research tree.",
                "OK");
        }

        // ============================================================
        //          STEP 8 - FLUID CONTENT (water bucket, tank, pump, pipes)
        // ============================================================
        private void BuildFluidContent()
        {
            const string fluidFolder    = ASSET_ROOT + "/Fluids";
            const string prefabsFolder  = fluidFolder + "/Prefabs";
            const string blocksFolder   = fluidFolder + "/Blocks";
            const string recipesFolder  = fluidFolder + "/Recipes";
            const string itemsFolder    = ASSET_ROOT + "/Items";

            int removedLegacyCrestObjects = RemoveLegacyCrestWaterContent();
            EnsureFolder(fluidFolder);
            EnsureFolder(prefabsFolder);
            EnsureFolder(blocksFolder);
            EnsureFolder(recipesFolder);
            EnsureSurfaceMiningDrops();

            // ---- Pull common items ----
            var ironIngot   = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{itemsFolder}/Item_IronIngot.asset");
            var copperIngot = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{itemsFolder}/Item_CopperIngot.asset");
            if (ironIngot == null || copperIngot == null)
            {
                EditorUtility.DisplayDialog("Voxel Engine",
                    "Run Step 4 first (need iron+copper ingots).", "OK");
                return;
            }

            // ---- 1) Water Bucket item ----
            string bucketPath = $"{itemsFolder}/Tool_WaterBucket.asset";
            var bucket = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.WaterBucket>(bucketPath);
            if (bucket == null)
            {
                bucket = ScriptableObject.CreateInstance<VoxelEngine.Items.WaterBucket>();
                AssetDatabase.CreateAsset(bucket, bucketPath);
            }
            bucket.itemId       = "water_bucket";
            bucket.displayName  = "Water Bucket";
            bucket.description  = "LMB scoops water or crude oil into the bucket. RMB places the carried liquid into the native voxel simulation. Durability tracks filled state (1 = full, 0 = empty).";
            bucket.iconTint     = new Color(0.20f, 0.50f, 0.85f);
            bucket.maxStack     = 1;
            bucket.maxDurability= 1;
            bucket.toolType     = VoxelEngine.Items.ToolType.Other;
            bucket.category     = "Fluids";
            EditorUtility.SetDirty(bucket);

            // ---- 2) Tank prefab(s) ----
            GameObject MakeTankPrefab(string name, Color color, bool isGlass)
            {
                string path = $"{prefabsFolder}/{name}.prefab";
                var root = new GameObject(name);
                // Solid hull cube.
                var hull = GameObject.CreatePrimitive(PrimitiveType.Cube);
                hull.transform.SetParent(root.transform, false);
                hull.transform.localScale = new Vector3(1f, 1.4f, 1f);
                hull.transform.localPosition = new Vector3(0, 0.7f, 0);
                var mat = MakeColoredMat(prefabsFolder, $"Mat_{name}",
                    isGlass ? new Color(color.r, color.g, color.b, 0.5f) : color);
                hull.GetComponent<Renderer>().sharedMaterial = mat;
                if (isGlass)
                {
                    // Inner WaterFill cube — scaled by Tank script. Cyan tint.
                    var fill = GameObject.CreatePrimitive(PrimitiveType.Cube);
                    fill.name = "WaterFill";
                    fill.transform.SetParent(root.transform, false);
                    fill.transform.localScale = new Vector3(0.85f, 0.001f, 0.85f);
                    fill.transform.localPosition = new Vector3(0, 0.05f, 0);
                    fill.GetComponent<Renderer>().sharedMaterial = MakeColoredMat(prefabsFolder, $"Mat_{name}_Fill",
                        new Color(0.15f, 0.45f, 0.85f, 1f));
                    // Disable collider on inner fill so raycasts hit the hull.
                    var col = fill.GetComponent<Collider>(); if (col != null) Object.DestroyImmediate(col);
                }
                var t = root.AddComponent<VoxelEngine.Fluids.WaterTank>();
                t.capacityLitres = 10000f;
                t.isGlass = isGlass;
                var prefab = PrefabUtility.SaveAsPrefabAsset(root, path);
                Object.DestroyImmediate(root);
                return prefab;
            }
            var tankSolid = MakeTankPrefab("Tank_Solid", new Color(0.45f, 0.45f, 0.50f), false);
            var tankGlass = MakeTankPrefab("Tank_Glass", new Color(0.55f, 0.75f, 0.95f), true);

            // ---- 3) Pump prefab ----
            GameObject MakePumpPrefab(string name, Color color)
            {
                string path = $"{prefabsFolder}/{name}.prefab";
                var root = new GameObject(name);
                var cube = GameObject.CreatePrimitive(PrimitiveType.Cube);
                cube.transform.SetParent(root.transform, false);
                cube.transform.localScale = new Vector3(1f, 0.8f, 1f);
                cube.transform.localPosition = new Vector3(0, 0.4f, 0);
                cube.GetComponent<Renderer>().sharedMaterial = MakeColoredMat(prefabsFolder, $"Mat_{name}", color);
                // Power consumer + pump.
                var pc = root.AddComponent<VoxelEngine.Power.PowerConsumer>();
                pc.connectRadius = 1.6f; pc.wattsPerSecond = 30f;
                var pump = root.AddComponent<VoxelEngine.Fluids.WaterPump>();
                pump.pumpLps = 20f;
                var prefab = PrefabUtility.SaveAsPrefabAsset(root, path);
                Object.DestroyImmediate(root);
                return prefab;
            }
            var pumpPrefab = MakePumpPrefab("WaterPump", new Color(0.55f, 0.30f, 0.20f));

            // ---- 4) Pipe prefab(s) ----
            // Pipes use the shared PipeVisualBuilder so they render the same chunky
            // core+arms style as Power / Data cables. The stretched cube is removed
            // here so the runtime visual is the only one shown.
            GameObject MakePipePrefab(string name, Color shellColor, Color innerColor, bool isGlass)
            {
                string path = $"{prefabsFolder}/{name}.prefab";
                var root = new GameObject(name);

                // Tiny invisible collider so raycasts (wrench, build-system) still register.
                var col = root.AddComponent<BoxCollider>();
                col.size = new Vector3(0.50f, 0.50f, 0.50f);

                var pipe = root.AddComponent<VoxelEngine.Fluids.WaterPipe>();
                pipe.maxFlowLps    = 50f;
                pipe.isGlass       = isGlass;
                pipe.connectRadius = 1.4f;

                var vb = root.AddComponent<VoxelEngine.Networks.PipeVisualBuilder>();
                vb.shellTint        = shellColor;
                vb.accentTint       = new Color(
                    Mathf.Clamp01(shellColor.r * 0.7f + 0.30f),
                    Mathf.Clamp01(shellColor.g * 0.7f + 0.30f),
                    Mathf.Clamp01(shellColor.b * 0.7f + 0.30f), 1f);
                vb.innerMediumTint  = innerColor;
                vb.isGlass          = isGlass;
                vb.style            = VoxelEngine.Networks.PipeStyle.Copper;
                vb.gridSize         = 1f;

                var prefab = PrefabUtility.SaveAsPrefabAsset(root, path);
                Object.DestroyImmediate(root);
                return prefab;
            }
            // Universal liquid pipe — warm burnished copper. Glass variant stays translucent
            // so players can still preview a flowing liquid line at a glance.
            var pipeSolid = MakePipePrefab("Pipe_Solid",
                new Color(0.78f, 0.45f, 0.20f),
                new Color(0.25f, 0.55f, 0.90f), false);
            var pipeGlass = MakePipePrefab("Pipe_Glass",
                new Color(0.90f, 0.70f, 0.55f),
                new Color(0.25f, 0.65f, 0.95f), true);

            // ---- 5) BlockItems for the placeables ----
            VoxelEngine.Items.BlockItem MakeFluidBlock(string assetName, string display, Color tint, GameObject prefab, string desc, int hp = 200)
            {
                string path = $"{blocksFolder}/{assetName}.asset";
                var b = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.BlockItem>(path);
                if (b == null)
                {
                    b = ScriptableObject.CreateInstance<VoxelEngine.Items.BlockItem>();
                    AssetDatabase.CreateAsset(b, path);
                }
                b.itemId       = assetName.ToLower();
                b.displayName  = display;
                b.description  = desc;
                b.iconTint     = tint;
                b.maxStack     = 99;
                b.placedPrefab = prefab;
                b.gridSize     = Vector3Int.one;
                b.blockHealth  = hp; b.miningTier = 1;
                b.category     = "Fluids";
                EditorUtility.SetDirty(b);
                return b;
            }
            var bTankSolid = MakeFluidBlock("Block_TankSolid", "Water Tank (Solid)", new Color(0.45f,0.45f,0.50f), tankSolid,
                "Stores 1000 L of water. Connect to pipes and pumps.");
            var bTankGlass = MakeFluidBlock("Block_TankGlass", "Water Tank (Glass)", new Color(0.55f,0.75f,0.95f), tankGlass,
                "Same as the solid tank but the water level is visible through the glass.");
            var bPump      = MakeFluidBlock("Block_WaterPump", "Water Pump",         new Color(0.55f,0.30f,0.20f), pumpPrefab,
                "Scans a nearby water or crude-oil pool, shows finite litres or ∞ source status, buffers liquid internally, then sends it through connected pipes and tanks while powered (~30 W).");
            var bPipeSolid = MakeFluidBlock("Block_PipeSolid", "Liquid Pipe (Solid) · 0.5 m", new Color(0.55f,0.30f,0.20f), pipeSolid,
                "Carries up to 50 L/s of any supported liquid. Place between tanks, pumps, and liquid-fed machines to connect them.");
            var bPipeGlass = MakeFluidBlock("Block_PipeGlass", "Liquid Pipe (Glass) · 0.5 m", new Color(0.55f,0.75f,0.95f), pipeGlass,
                "Glass variant of the universal liquid pipe — same capacity, but transparent.");

            // ---- 6) Recipes ----
            var recipeRegistry = AssetDatabase.LoadAssetAtPath<VoxelEngine.Crafting.RecipeRegistry>($"{ASSET_ROOT}/RecipeRegistry.asset");
            if (recipeRegistry == null) { EditorUtility.DisplayDialog("Voxel Engine", "Run Step 4 first.", "OK"); return; }

            AddRecipe("Recipe_WaterBucket", "Water Bucket", bucket, 1, VoxelEngine.Crafting.StationTier.CraftingBench, ((VoxelEngine.Items.ItemDefinition)ironIngot, 3));
            AddRecipe("Recipe_TankSolid", "Water Tank (Solid)", bTankSolid, 1, VoxelEngine.Crafting.StationTier.CraftingBench, ((VoxelEngine.Items.ItemDefinition)ironIngot, 6));
            AddRecipe("Recipe_TankGlass", "Water Tank (Glass)", bTankGlass, 1, VoxelEngine.Crafting.StationTier.CraftingBench, ((VoxelEngine.Items.ItemDefinition)ironIngot, 4), ((VoxelEngine.Items.ItemDefinition)copperIngot, 4));
            AddRecipe("Recipe_PipeSolid", "Liquid Pipe (Solid) x4 · 0.5 m", bPipeSolid, 4, VoxelEngine.Crafting.StationTier.CraftingBench, ((VoxelEngine.Items.ItemDefinition)copperIngot, 1));
            AddRecipe("Recipe_PipeGlass", "Liquid Pipe (Glass) x4 · 0.5 m", bPipeGlass, 4, VoxelEngine.Crafting.StationTier.CraftingBench, ((VoxelEngine.Items.ItemDefinition)copperIngot, 2));
            AddRecipe("Recipe_WaterPump", "Water Pump", bPump, 1, VoxelEngine.Crafting.StationTier.Assembler, ((VoxelEngine.Items.ItemDefinition)ironIngot, 4), ((VoxelEngine.Items.ItemDefinition)copperIngot, 6));

            EditorUtility.SetDirty(recipeRegistry);
            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();

            // Spawn the FluidNetworkManager + FluidPhysics in the open scene.
            if (Object.FindAnyObjectByType<VoxelEngine.Fluids.FluidNetworkManager>() == null)
                new GameObject("FluidNetworkManager").AddComponent<VoxelEngine.Fluids.FluidNetworkManager>();
            if (Object.FindAnyObjectByType<VoxelEngine.Fluids.FluidSimManager>() == null)
                new GameObject("FluidSimManager").AddComponent<VoxelEngine.Fluids.FluidSimManager>();

            ConfigureNativeSphericalWaterRuntime(prefabsFolder);
            UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(UnityEngine.SceneManagement.SceneManager.GetActiveScene());
            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();

            EditorUtility.DisplayDialog("Voxel Engine",
                "Native spherical fluid content created!\n\n" +
                "* Buckets preserve water or crude oil as real voxel liquid\n" +
                "* Water Tank (Solid + Glass variants, 10,000 L each)\n" +
                "* Pool Pump: finite volume / ∞ source UI + internal tank + pipe output\n" +
                "* Real voxel ocean basins, lakes/pools, grounded crude, and ship wakes\n" +
                "* Dirt mining-drop repair plus Liquid Pipes (Solid + Glass, 50 L/s capacity)\n" +
                "* Legacy Crest content removed: " + removedLegacyCrestObjects + " scene components/objects\n" +
                "* FluidNetworkManager + FluidSimManager + NativeWaterWakeSystem ready",
                "OK");
        }

        /// <summary>
        /// Repairs the hand-mineable dirt chain through setup. Historic projects could have a
        /// Clay/Dirt material with a null drop because its ItemDefinition was instantiated but
        /// never written as an asset. This creates the missing Dirt item and only fills absent
        /// drop links, preserving any custom authored material rewards.
        /// </summary>
        private static void EnsureSurfaceMiningDrops()
        {
            string itemsFolder = ASSET_ROOT + "/Items";
            EnsureFolder(itemsFolder);
            string dirtPath = itemsFolder + "/Item_Clay.asset";
            var dirt = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>(dirtPath);
            if (dirt == null)
            {
                dirt = ScriptableObject.CreateInstance<VoxelEngine.Items.ItemDefinition>();
                AssetDatabase.CreateAsset(dirt, dirtPath);
            }
            dirt.itemId = "dirt";
            dirt.displayName = "Dirt";
            dirt.description = "Hand-mined soil from grassy and clay terrain.";
            dirt.iconTint = new Color(0.40f, 0.27f, 0.16f);
            dirt.maxStack = Mathf.Max(999, dirt.maxStack);
            dirt.massPerUnit = Mathf.Max(0.1f, dirt.massPerUnit);
            dirt.category = "Resources";
            EditorUtility.SetDirty(dirt);

            var registry = AssetDatabase.LoadAssetAtPath<VoxelEngine.Materials.MaterialRegistry>(ASSET_ROOT + "/MaterialRegistry.asset");
            if (registry == null) return;
            registry.definitions ??= new List<VoxelEngine.Materials.VoxelMaterialDefinition>();

            // Sand may already live in the industrial content folder. Reuse it by itemId so
            // this setup repair never creates a duplicate custom item.
            var sand = FindOrCreateSurfaceItem("sand", "Sand", new Color(0.92f, 0.84f, 0.55f));
            EnsureSurfaceDrop(VoxelEngine.Materials.MaterialId.Sand, "Sand", new Color(0.92f, 0.84f, 0.55f), sand);
            EnsureSurfaceDrop(VoxelEngine.Materials.MaterialId.Clay, "Clay/Dirt", new Color(0.40f, 0.27f, 0.16f), dirt);
            EnsureSurfaceDrop(VoxelEngine.Materials.MaterialId.Grass, "Grass/Dirt", new Color(0.24f, 0.52f, 0.18f), dirt);
            registry.Build();
            EditorUtility.SetDirty(registry);

            VoxelEngine.Items.ItemDefinition FindOrCreateSurfaceItem(string itemId, string display, Color tint)
            {
                foreach (string guid in AssetDatabase.FindAssets("t:ItemDefinition", new[] { ASSET_ROOT }))
                {
                    var existing = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>(AssetDatabase.GUIDToAssetPath(guid));
                    if (existing != null && string.Equals(existing.itemId, itemId, System.StringComparison.OrdinalIgnoreCase)) return existing;
                }

                string path = itemsFolder + "/Item_" + char.ToUpperInvariant(itemId[0]) + itemId.Substring(1) + ".asset";
                var created = ScriptableObject.CreateInstance<VoxelEngine.Items.ItemDefinition>();
                created.itemId = itemId;
                created.displayName = display;
                created.description = "Hand-mined " + display.ToLowerInvariant() + " resource.";
                created.iconTint = tint;
                created.maxStack = 999;
                created.massPerUnit = 1f;
                created.category = "Resources";
                AssetDatabase.CreateAsset(created, path);
                return created;
            }

            void EnsureSurfaceDrop(VoxelEngine.Materials.MaterialId id, string display, Color color, VoxelEngine.Items.ItemDefinition fallbackDrop)
            {
                var definition = AssetDatabase.LoadAssetAtPath<VoxelEngine.Materials.VoxelMaterialDefinition>($"{ASSET_ROOT}/Materials/Mat_{id}.asset");
                if (definition == null)
                {
                    definition = ScriptableObject.CreateInstance<VoxelEngine.Materials.VoxelMaterialDefinition>();
                    AssetDatabase.CreateAsset(definition, $"{ASSET_ROOT}/Materials/Mat_{id}.asset");
                }
                definition.id = id;
                if (string.IsNullOrEmpty(definition.displayName) || definition.displayName == "Stone") definition.displayName = display;
                if (definition.color == Color.clear || definition.color == Color.gray) definition.color = color;
                definition.hardness = Mathf.Max(0.2f, definition.hardness);
                definition.miningTier = 0;
                definition.isMineable = true;
                if (definition.dropItem == null) definition.dropItem = fallbackDrop;
                definition.dropAmount = Mathf.Max(1, definition.dropAmount);
                if (!registry.definitions.Contains(definition)) registry.definitions.Add(definition);
                EditorUtility.SetDirty(definition);
            }
        }

        // ────────────────────────────────────────────────────────────
        //  Native spherical water helpers (Step 8)
        // ────────────────────────────────────────────────────────────
        private static void ConfigureNativeSphericalWaterRuntime(string prefabsFolder)
        {
            var water = EnsureNativeWaterMaterial(
                $"{prefabsFolder}/Mat_NativeSphericalWater.mat",
                "Mat_NativeSphericalWater",
                new Color(0.08f, 0.52f, 0.82f, 0.94f),
                new Color(0.01f, 0.06f, 0.22f, 0.98f),
                deepWaveAmplitude: 0.85f,
                waveSpeed: 0.55f);
            var oil = EnsureNativeWaterMaterial(
                $"{prefabsFolder}/Mat_NativeCrudeOil.mat",
                "Mat_NativeCrudeOil",
                new Color(0.12f, 0.085f, 0.05f, 0.92f),
                new Color(0.02f, 0.015f, 0.01f, 0.98f),
                deepWaveAmplitude: 0.04f,
                waveSpeed: 0.12f);

            var bootstrap = Object.FindAnyObjectByType<VoxelEngine.WaterSim.PlanetWaterRendererBootstrap>(FindObjectsInactive.Include);
            if (bootstrap == null)
            {
                var root = new GameObject("NativeSphericalWater");
                bootstrap = root.AddComponent<VoxelEngine.WaterSim.PlanetWaterRendererBootstrap>();
            }
            bootstrap.renderVoxelLiquidSurfaces = true;
            bootstrap.renderNativeSphericalOceanPatch = false;
            // Migrate only the known old default (4) to the bounded local-water budget;
            // any other designer-authored number remains untouched.
            if (bootstrap.meshBuildBudgetPerFrame == 4) bootstrap.meshBuildBudgetPerFrame = 1;
            else if (bootstrap.meshBuildBudgetPerFrame <= 0) bootstrap.meshBuildBudgetPerFrame = 1;
            // The old recovery scan repeatedly rebuilt every nearby ocean surface. SphereWorld
            // now schedules real liquid changes directly, so disable only the recognizable old
            // default configuration while preserving intentional custom recovery tuning.
            if (bootstrap.rescheduleVisibleLiquidSurfaces &&
                bootstrap.liquidRescheduleChunkRadius >= 3 && bootstrap.liquidRescheduleInterval <= 1.01f)
                bootstrap.rescheduleVisibleLiquidSurfaces = false;
            bootstrap.nativeOceanSearchRadius = Mathf.Clamp(bootstrap.nativeOceanSearchRadius, 192f, 512f);
            bootstrap.nativeOceanTileSize = Mathf.Clamp(bootstrap.nativeOceanTileSize, 8f, 16f);
            bootstrap.waterMaterialOverride = water;
            bootstrap.oilMaterialOverride = oil;
            foreach (var legacyWrappedWater in Object.FindObjectsByType<VoxelEngine.WaterSim.ProceduralWaterPatchRenderer>(FindObjectsInactive.Include))
            {
                if (legacyWrappedWater != null) Object.DestroyImmediate(legacyWrappedWater);
            }

            var performance = bootstrap.GetComponent<VoxelEngine.WaterSim.FluidPerformanceBootstrap>();
            if (performance == null) performance = bootstrap.gameObject.AddComponent<VoxelEngine.WaterSim.FluidPerformanceBootstrap>();
            performance.renderNativeWater = true;
            performance.useNativeVolumetricAssist = false;
            if (Mathf.Approximately(performance.tickRate, 8f) && performance.maxChunksPerTick == 6)
            {
                performance.tickRate = 4f;
                performance.maxChunksPerTick = 2;
            }

            if (Object.FindAnyObjectByType<VoxelEngine.WaterSim.NativeWaterWakeSystem>(FindObjectsInactive.Include) == null)
                new GameObject("NativeWaterWakeSystem").AddComponent<VoxelEngine.WaterSim.NativeWaterWakeSystem>();

            EditorUtility.SetDirty(bootstrap);
            EditorUtility.SetDirty(performance);
            EditorUtility.SetDirty(water);
            EditorUtility.SetDirty(oil);
        }

        private static Material EnsureNativeWaterMaterial(string path, string materialName, Color shallow, Color deep,
            float deepWaveAmplitude, float waveSpeed)
        {
            var shader = Shader.Find("VoxelEngine/VoxelWaterURP")
                ?? Shader.Find("Universal Render Pipeline/Lit")
                ?? Shader.Find("Standard");
            var material = AssetDatabase.LoadAssetAtPath<Material>(path);
            bool created = material == null;
            if (created)
            {
                material = new Material(shader) { name = materialName };
                AssetDatabase.CreateAsset(material, path);
            }

            // Setup owns the native conversion, but once a non-Crest native material exists,
            // preserve hand-tuned properties on subsequent runs.
            bool legacyExternal = material.shader == null || material.shader.name.StartsWith("Crest/");
            if (created || legacyExternal)
            {
                material.shader = shader;
                material.name = materialName;
                material.SetOverrideTag("RenderType", "Transparent");
                material.SetInt("_SrcBlend", (int)UnityEngine.Rendering.BlendMode.SrcAlpha);
                material.SetInt("_DstBlend", (int)UnityEngine.Rendering.BlendMode.OneMinusSrcAlpha);
                material.SetInt("_ZWrite", 0);
                material.SetInt("_Cull", (int)UnityEngine.Rendering.CullMode.Off);
                material.renderQueue = 3000;
                if (material.HasProperty("_Surface")) material.SetFloat("_Surface", 1f);
                if (material.HasProperty("_ShallowColor")) material.SetColor("_ShallowColor", shallow);
                if (material.HasProperty("_DeepColor")) material.SetColor("_DeepColor", deep);
                if (material.HasProperty("_FoamColor")) material.SetColor("_FoamColor", Color.white);
                if (material.HasProperty("_DeepWaveAmplitude")) material.SetFloat("_DeepWaveAmplitude", deepWaveAmplitude);
                if (material.HasProperty("_DeepWaveSpeed")) material.SetFloat("_DeepWaveSpeed", waveSpeed);
                if (material.HasProperty("_SecondaryWaveAmplitude")) material.SetFloat("_SecondaryWaveAmplitude", deepWaveAmplitude * 0.42f);
                if (material.HasProperty("_SecondaryWaveSpeed")) material.SetFloat("_SecondaryWaveSpeed", waveSpeed * 1.65f);
                if (material.HasProperty("_NormalScale")) material.SetFloat("_NormalScale", deepWaveAmplitude < 0.1f ? 0.45f : 2.2f);
                if (material.HasProperty("_Gloss")) material.SetFloat("_Gloss", deepWaveAmplitude < 0.1f ? 1f : 0.94f);
                if (material.HasProperty("_PlanetWaveBlend")) material.SetFloat("_PlanetWaveBlend", 1f);
            }
            return material;
        }

        /// <summary>
        /// Removes old external-ocean scene/prefab components, bridge material, and the
        /// previous Assets/Liquid package path when it exists. This never
        /// touches VoxelEngineAssets/Fluids, which owns our buckets, pumps, tanks, and pipes.
        /// </summary>
        private static int RemoveLegacyCrestWaterContent()
        {
            int removed = 0;
            var transforms = Object.FindObjectsByType<Transform>(FindObjectsInactive.Include);
            foreach (var transform in transforms)
            {
                if (transform == null || !transform.gameObject.scene.IsValid()) continue;
                removed += RemoveLegacyCrestComponents(transform.gameObject);
            }

            // Existing authored prefabs may have received a legacy wake/binder component in a
            // prior setup pass. Remove only those identified external-water components; leave all
            // custom meshes, materials, colliders, and gameplay components untouched.
            foreach (var guid in AssetDatabase.FindAssets("t:Prefab"))
            {
                string path = AssetDatabase.GUIDToAssetPath(guid);
                if (string.IsNullOrEmpty(path) || path.StartsWith("Assets/Liquid/", System.StringComparison.Ordinal)) continue;
                GameObject root = null;
                try
                {
                    root = PrefabUtility.LoadPrefabContents(path);
                    int prefabRemoved = 0;
                    foreach (var transform in root.GetComponentsInChildren<Transform>(true))
                        prefabRemoved += RemoveLegacyCrestComponents(transform.gameObject);
                    if (prefabRemoved > 0)
                    {
                        PrefabUtility.SaveAsPrefabAsset(root, path);
                        removed += prefabRemoved;
                    }
                }
                catch (System.Exception ex)
                {
                    Debug.LogWarning($"[NativeWaterSetup] Could not inspect legacy-water prefab '{path}': {ex.Message}");
                }
                finally
                {
                    if (root != null) PrefabUtility.UnloadPrefabContents(root);
                }
            }

            foreach (var rootName in new[] { "Crest Ocean", "Crest Oil Ocean", "CrestVoxelBridge", "Crest Wake Probes" })
            {
                var root = GameObject.Find(rootName);
                if (root == null) continue;
                Object.DestroyImmediate(root);
                removed++;
            }

            const string oldBridge = "Assets/Resources/CrestOcean_VoxelBridge.mat";
            if (AssetDatabase.LoadAssetAtPath<Material>(oldBridge) != null && AssetDatabase.DeleteAsset(oldBridge)) removed++;
            if (AssetDatabase.IsValidFolder("Assets/Liquid") && AssetDatabase.DeleteAsset("Assets/Liquid")) removed++;
            return removed;
        }

        private static int RemoveLegacyCrestComponents(GameObject go)
        {
            if (go == null) return 0;
            int removed = 0;
            foreach (var component in go.GetComponents<Component>())
            {
                if (component == null) continue;
                string typeName = component.GetType().FullName ?? string.Empty;
                if (!typeName.StartsWith("Crest.", System.StringComparison.Ordinal)
                    && !typeName.StartsWith("VoxelEngine.WaterSim.Crest", System.StringComparison.Ordinal)
                    && !typeName.StartsWith("VoxelEngine.Maritime.Crest", System.StringComparison.Ordinal))
                    continue;
                Object.DestroyImmediate(component);
                removed++;
            }
            return removed;
        }

        // ============================================================
        //  STEP 10 - INDUSTRIAL CONTENT PACK
        //  (plates, oil chain, plastic, electronics, expanded research)
        // ============================================================
        private void BuildIndustrialContent()
        {
            const string industrialFolder = ASSET_ROOT + "/Industrial";
            const string itemsFolder      = industrialFolder + "/Items";
            const string prefabsFolder    = industrialFolder + "/Prefabs";
            const string blocksFolder     = industrialFolder + "/Blocks";
            const string recipesFolder    = industrialFolder + "/Recipes";
            const string procRecFolder    = industrialFolder + "/ProcessingRecipes";
            const string researchFolder   = ASSET_ROOT + "/Research";
            const string nodesFolder      = researchFolder + "/Nodes";

            EnsureFolder(industrialFolder);
            EnsureFolder(itemsFolder);
            EnsureFolder(prefabsFolder);
            EnsureFolder(blocksFolder);
            EnsureFolder(recipesFolder);
            EnsureFolder(procRecFolder);
            EnsureFolder(researchFolder);
            EnsureFolder(nodesFolder);

            string craftItemsFolder = ASSET_ROOT + "/Items";

            // -------- Load all pre-existing items (from steps 1, 4, 6, 7, 8) --------
            var stone       = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{craftItemsFolder}/Item_Stone.asset");
            var sand        = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{craftItemsFolder}/Item_Sand.asset");
            var clay        = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{craftItemsFolder}/Item_Clay.asset");
            var ice         = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{craftItemsFolder}/Item_Ice.asset");
            var ironOre     = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{craftItemsFolder}/Item_Iron.asset");
            var copperOre   = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{craftItemsFolder}/Item_Copper.asset");
            var coal        = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{craftItemsFolder}/Item_Coal.asset");
            var nickelOre   = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{craftItemsFolder}/Item_Nickel.asset");
            var siliconOre  = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{craftItemsFolder}/Item_Silicon.asset");
            var goldOre     = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{craftItemsFolder}/Item_Gold.asset");
            var silverOre   = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{craftItemsFolder}/Item_Silver.asset");
            var uraniumOre  = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{craftItemsFolder}/Item_Uranium.asset");
            var crudeOilRaw = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{craftItemsFolder}/Item_CrudeOil.asset");

            // Wood logs / planks / ingots are written into ASSET_ROOT/Items by Step 4
            // (via MakeResource → Item_WoodLog.asset etc.). Earlier versions of Step 10
            // looked in /Recipes here by mistake — fixed to use craftItemsFolder.
            var woodLog     = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{craftItemsFolder}/Item_WoodLog.asset");
            var plank       = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{craftItemsFolder}/Item_WoodenPlank.asset");
            var ironIngot   = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{craftItemsFolder}/Item_IronIngot.asset");
            var copperIngot = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{craftItemsFolder}/Item_CopperIngot.asset");
            var steelIngot  = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{craftItemsFolder}/Item_SteelIngot.asset");

            if (ironIngot == null || copperIngot == null || steelIngot == null || woodLog == null)
            {
                EditorUtility.DisplayDialog("Voxel Engine",
                    "Run Step 4 (Build Crafting Content) first — it creates the ingot/wood items the industrial pack depends on.", "OK");
                return;
            }

            // Science packs come from Step 7.
            var sciT1 = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ScienceItem>($"{craftItemsFolder}/Item_ScienceT1.asset");
            var sciT2 = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ScienceItem>($"{craftItemsFolder}/Item_ScienceT2.asset");
            var sciT3 = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ScienceItem>($"{craftItemsFolder}/Item_ScienceT3.asset");
            if (sciT1 == null || sciT2 == null || sciT3 == null)
            {
                EditorUtility.DisplayDialog("Voxel Engine",
                    "Run Step 7 (Build Research Content) first — it creates the Science Pack items the industrial pack depends on.", "OK");
                return;
            }

            // Recipe registry (created by Step 4).
            var registry = AssetDatabase.LoadAssetAtPath<VoxelEngine.Crafting.RecipeRegistry>($"{ASSET_ROOT}/RecipeRegistry.asset");
            if (registry == null) { EditorUtility.DisplayDialog("Voxel Engine", "Run Step 4 first.", "OK"); return; }

            // ====================================================================
            //  1) NEW RESOURCE ITEMS — plates, gears, wires, circuits, oil chain
            // ====================================================================

            VoxelEngine.Items.ResourceItem MakeIndustrialResource(string assetName, string display, string desc,
                Color tint, VoxelEngine.Items.ResourceCategory cat, string uiCategory, int maxStack = 999)
            {
                string path = $"{itemsFolder}/{assetName}.asset";
                var r = GetOrCreateAsset<VoxelEngine.Items.ResourceItem>(path);

                r.itemId      = assetName.ToLower();
                r.displayName = display;
                r.description = desc;
                r.iconTint    = tint;
                r.maxStack    = maxStack;
                r.massPerUnit = 1f;
                r.category    = uiCategory;
                r.subcategory = cat;
                r.fuelSeconds = 0f;
                EditorUtility.SetDirty(r);
                return r;
            }

            // ─ Plates ─
            var ironPlate   = MakeIndustrialResource("Item_IronPlate",   "Iron Plate",   "Pressed iron sheet. Core building block for machines, hulls, and circuits.",                       new Color(0.78f, 0.80f, 0.85f), VoxelEngine.Items.ResourceCategory.Component, "Plates");
            var copperPlate = MakeIndustrialResource("Item_CopperPlate", "Copper Plate", "Pressed copper sheet. Used for electrical components.",                                          new Color(0.85f, 0.55f, 0.30f), VoxelEngine.Items.ResourceCategory.Component, "Plates");
            var steelPlate  = MakeIndustrialResource("Item_SteelPlate",  "Steel Plate",  "Pressed steel sheet. Required for high-tier machines, armoured structures, and nuclear gear.",   new Color(0.60f, 0.62f, 0.68f), VoxelEngine.Items.ResourceCategory.Component, "Plates");

            // ─ Mechanical / electrical intermediates ─
            var ironGear    = MakeIndustrialResource("Item_IronGear",   "Iron Gear",     "Toothed iron cog. Used in any rotating machinery.",                           new Color(0.65f, 0.68f, 0.72f), VoxelEngine.Items.ResourceCategory.Component, "Mechanical");
            var copperWire  = MakeIndustrialResource("Item_CopperWire", "Copper LV Wire",   "Drawn copper conductor. The basic ingredient of all electronics.",            new Color(0.92f, 0.58f, 0.30f), VoxelEngine.Items.ResourceCategory.Component, "Electronics");
            var circuitBasic= MakeIndustrialResource("Item_Circuit",    "Electronic Circuit", "PCB with copper traces on an iron substrate. Brain of every machine.", new Color(0.30f, 0.65f, 0.40f), VoxelEngine.Items.ResourceCategory.Component, "Electronics");
            var circuitAdv  = MakeIndustrialResource("Item_AdvCircuit", "Advanced Circuit",  "Layered logic board. Powers high-tier automation and digital storage.",   new Color(0.30f, 0.55f, 0.95f), VoxelEngine.Items.ResourceCategory.Component, "Electronics");

            // ─ Glass (smelted from sand) ─
            var glass       = MakeIndustrialResource("Item_Glass",      "Glass",          "Clear pane fused from sand. Used in lab equipment and storage windows.",   new Color(0.70f, 0.88f, 0.95f), VoxelEngine.Items.ResourceCategory.Component, "Materials");

            // ─ Oil chain ─
            var emptyBarrel = MakeIndustrialResource("Item_EmptyBarrel","Empty Barrel",    "Pressed-steel drum. Fill it with crude oil at a Pumpjack.",               new Color(0.45f, 0.45f, 0.50f), VoxelEngine.Items.ResourceCategory.Component, "Oil", maxStack: 50);
            var crudeBarrel = MakeIndustrialResource("Item_CrudeOilBarrel","Crude Oil Barrel","Black gold. Feed it to an Oil Refinery to produce Refined Oil.",       new Color(0.10f, 0.08f, 0.06f), VoxelEngine.Items.ResourceCategory.Raw,       "Oil", maxStack: 50);
            var refinedBarrel = MakeIndustrialResource("Item_RefinedOilBarrel","Refined Oil Barrel","Cracked & distilled oil. Burns clean and feeds plastic synthesis.", new Color(0.50f, 0.30f, 0.10f), VoxelEngine.Items.ResourceCategory.Component, "Oil", maxStack: 50);
            // Refined oil is also a fuel (long burn time): useful in furnaces.
            refinedBarrel.fuelSeconds = 60f; EditorUtility.SetDirty(refinedBarrel);
            var plastic     = MakeIndustrialResource("Item_Plastic",    "Plastic Bar",     "Polymerised hydrocarbon block. Required for advanced circuits & insulation.", new Color(0.92f, 0.92f, 0.96f), VoxelEngine.Items.ResourceCategory.Component, "Oil");
            // Rare relic component: never receives a crafting recipe. Setup adds it
            // exclusively to Pirate ruin rare-loot pools below.
            var pirateJackPumpHead = MakeIndustrialResource("Item_PirateJackPumpHead", "Pirate Jack Pump Head",
                "A heavy forged pump head stripped from a Pirate ruin. Required to assemble a Jack Pump; it cannot be crafted.",
                new Color(0.30f, 0.26f, 0.20f), VoxelEngine.Items.ResourceCategory.Component, "Pirate Relics", maxStack: 1);

            // ====================================================================
            //  2) FACTORY MACHINES — Pumpjack, Oil Refinery, Wireless Storage Term
            // ====================================================================

            GameObject MakeIndustrialPrefab(string name, Color color, Vector3 scale,
                System.Action<GameObject> configure)
            {
                string path = $"{prefabsFolder}/{name}.prefab";
                var root = new GameObject(name);

                var cube = GameObject.CreatePrimitive(PrimitiveType.Cube);
                cube.name = "Mesh";
                cube.transform.SetParent(root.transform, false);
                cube.transform.localScale = scale;
                var mat = MakeColoredMat(prefabsFolder, $"Mat_{name}", color);
                cube.GetComponent<Renderer>().sharedMaterial = mat;

                configure?.Invoke(root);

                var prefab = PrefabUtility.SaveAsPrefabAsset(root, path);
                Object.DestroyImmediate(root);
                return prefab;
            }

            // ─ Jack Pump ─
            // Kept at the existing Pumpjack asset path so old placed blocks repair
            // cleanly, while the authored visual becomes a real walking-beam unit.
            var jackPumpDark = MakeColoredMat(prefabsFolder, "Mat_JackPumpDark", new Color(0.085f, 0.09f, 0.095f));
            var jackPumpSteel = MakeColoredMat(prefabsFolder, "Mat_JackPumpSteel", new Color(0.32f, 0.34f, 0.36f));
            var jackPumpBrass = MakeColoredMat(prefabsFolder, "Mat_JackPumpBrass", new Color(0.62f, 0.42f, 0.16f));
            var jackPumpOil = MakeColoredMat(prefabsFolder, "Mat_JackPumpOil", new Color(0.055f, 0.045f, 0.035f));
            var pumpjackPrefab = GetOrCreatePrefab($"{prefabsFolder}/Pumpjack.prefab", "JackPump", root =>
            {
                var pump = EnsureComponent<VoxelEngine.Crafting.Pumpjack>(root);
                pump.emptyBarrel = emptyBarrel;
                pump.crudeOilBarrel = crudeBarrel;
                pump.secondsPerCycle = 14f;
                pump.baseWattsPerSecond = 4000f;
                pump.idleWattsPerSecond = 120f;
                pump.scanDepth = 120;
                pump.scanRadius = 3;

                var power = EnsureComponent<VoxelEngine.Power.PowerConsumer>(root);
                power.connectRadius = 2.2f;
                power.wattsPerSecond = pump.idleWattsPerSecond;
                EnsureJackPumpVisuals(root.transform, jackPumpDark, jackPumpSteel, jackPumpBrass, jackPumpOil);
            });

            // ─ Oil Refinery (CraftingStation + OilRefinery + processing recipes) ─
            string refineryPath = $"{prefabsFolder}/OilRefinery.prefab";
            GameObject refineryPrefab;
            {
                var root = new GameObject("OilRefinery");
                var cube = GameObject.CreatePrimitive(PrimitiveType.Cube);
                cube.transform.SetParent(root.transform, false);
                cube.transform.localScale = new Vector3(2.0f, 2.4f, 2.0f);
                cube.GetComponent<Renderer>().sharedMaterial = MakeColoredMat(prefabsFolder, "Mat_OilRefinery", new Color(0.30f, 0.20f, 0.10f));
                var st = root.AddComponent<VoxelEngine.Crafting.CraftingStation>();
                st.tier = VoxelEngine.Crafting.StationTier.Assembler;
                st.displayName = "Oil Refinery";
                root.AddComponent<VoxelEngine.Crafting.OilRefinery>();
                refineryPrefab = PrefabUtility.SaveAsPrefabAsset(root, refineryPath);
                Object.DestroyImmediate(root);
            }

            // ─ Stationary Chemical Plant (world equivalent of the grid Chemical Plant) ─
            string chemPlantPath = $"{prefabsFolder}/StationaryChemicalPlant.prefab";
            GameObject chemPlantPrefab;
            {
                var root = new GameObject("StationaryChemicalPlant");
                var cube = GameObject.CreatePrimitive(PrimitiveType.Cube);
                cube.transform.SetParent(root.transform, false);
                cube.transform.localScale = new Vector3(2.2f, 2.4f, 2.2f);
                cube.GetComponent<Renderer>().sharedMaterial = MakeColoredMat(prefabsFolder, "Mat_ChemicalPlant", new Color(0.40f, 0.55f, 0.35f));
                var st = root.AddComponent<VoxelEngine.Crafting.CraftingStation>();
                st.tier = VoxelEngine.Crafting.StationTier.Assembler;
                st.displayName = "Chemical Plant";
                root.AddComponent<VoxelEngine.Industrial.StationaryChemicalPlant>();
                chemPlantPrefab = PrefabUtility.SaveAsPrefabAsset(root, chemPlantPath);
                Object.DestroyImmediate(root);
            }

            // ─ Stationary Docking Port (landing pad) — ships lock to it ─
            string dockPath = $"{prefabsFolder}/StationaryDockingPort.prefab";
            GameObject stationaryDockPrefab;
            {
                var root = new GameObject("StationaryDockingPort");
                var pad = GameObject.CreatePrimitive(PrimitiveType.Cube);
                pad.transform.SetParent(root.transform, false);
                pad.transform.localScale = new Vector3(3f, 0.4f, 3f);
                pad.GetComponent<Renderer>().sharedMaterial = MakeColoredMat(prefabsFolder, "Mat_DockPad", new Color(0.55f, 0.55f, 0.20f));
                var ring = GameObject.CreatePrimitive(PrimitiveType.Cylinder);
                ring.transform.SetParent(root.transform, false);
                ring.transform.localScale = new Vector3(1.6f, 0.1f, 1.6f);
                ring.transform.localPosition = new Vector3(0, 0.25f, 0);
                ring.GetComponent<Renderer>().sharedMaterial = MakeColoredMat(prefabsFolder, "Mat_DockRing", new Color(0.2f, 0.7f, 0.9f));
                root.AddComponent<VoxelEngine.GridSystem.BaseDock>();   // auto-adds PlacedBlock
                stationaryDockPrefab = PrefabUtility.SaveAsPrefabAsset(root, dockPath);
                Object.DestroyImmediate(root);
            }

            // ─ Wireless Storage Terminal (uses existing StorageTerminal with isWireless=true) ─
            string wstPath = $"{prefabsFolder}/WirelessStorageTerminal.prefab";
            GameObject wstPrefab;
            {
                var root = new GameObject("WirelessStorageTerminal");
                var cube = GameObject.CreatePrimitive(PrimitiveType.Cube);
                cube.transform.SetParent(root.transform, false);
                cube.transform.localScale = new Vector3(0.9f, 1.4f, 0.4f);
                cube.GetComponent<Renderer>().sharedMaterial = MakeColoredMat(prefabsFolder, "Mat_WST", new Color(0.55f, 0.30f, 0.85f));
                var pc = root.AddComponent<VoxelEngine.Power.PowerConsumer>();
                pc.connectRadius = 1.6f; pc.wattsPerSecond = 60f;
                var term = root.AddComponent<VoxelEngine.Storage.StorageTerminal>();
                term.isWireless    = true;
                term.wirelessRange = 60f;
                term.searchRadius  = 12f;
                wstPrefab = PrefabUtility.SaveAsPrefabAsset(root, wstPath);
                Object.DestroyImmediate(root);
            }

            // ─ BlockItems for the new placeables ─
            VoxelEngine.Items.BlockItem MakeIndustrialBlock(string assetName, string display, Color tint, GameObject prefab,
                string desc, string uiCategory = "Industrial", int hp = 600)
            {
                string path = $"{blocksFolder}/{assetName}.asset";
                var b = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.BlockItem>(path);
                if (b == null)
                {
                    b = ScriptableObject.CreateInstance<VoxelEngine.Items.BlockItem>();
                    AssetDatabase.CreateAsset(b, path);
                }
                b.itemId       = assetName.ToLower();
                b.displayName  = display;
                b.description  = desc;
                b.iconTint     = tint;
                b.maxStack     = 50;
                b.massPerUnit  = 8f;
                b.placedPrefab = prefab;
                b.gridSize     = Vector3Int.one;
                b.allowStacking= prefab != null && prefab.GetComponent<VoxelEngine.Power.PowerCable>() != null;
                b.blockHealth  = hp;
                b.miningTier   = 2;
                b.category     = uiCategory;
                EditorUtility.SetDirty(b);
                return b;
            }

            var blockPumpjack = MakeIndustrialBlock("Block_Pumpjack", "Jack Pump", new Color(0.20f, 0.20f, 0.22f), pumpjackPrefab,
                "Heavy walking-beam oil extractor. Runs only on a rare infinite Pirate World oil node; consumes Empty Barrels and draws 4 kW while pumping.", hp: 1400);
            blockPumpjack.maxStack = 5;
            blockPumpjack.massPerUnit = 35f;
            blockPumpjack.miningTier = 3;
            EditorUtility.SetDirty(blockPumpjack);
            ConfigureCrudeOilWorlds();
            EnsurePirateJackPumpHeadRuinLoot(pirateJackPumpHead);
            var blockRefinery   = MakeIndustrialBlock("Block_OilRefinery", "Oil Refinery",      new Color(0.30f,0.20f,0.10f), refineryPrefab,
                "Industrial multi-recipe processor. Crude Oil Barrel → Refined Oil Barrel + Empty Barrel, and Refined Oil + Coal → Plastic Bar + Empty Barrel. 2 input / 4 output / 2 upgrade slots. 400 W base draw.");
            var blockChemPlant  = MakeIndustrialBlock("Block_ChemicalPlant", "Chemical Plant",  new Color(0.40f,0.55f,0.35f), chemPlantPrefab,
                "Industrial chemistry processor. Refined Oil + Plastic → Liquid Fuel + Empty Barrel. 3 input / 3 output slots. 720 W base draw. Shares recipes with the grid Chemical Plant.");
            var blockDock       = MakeIndustrialBlock("Block_StationaryDockingPort", "Docking Pad", new Color(0.55f,0.55f,0.20f), stationaryDockPrefab,
                "Base-side landing pad. Ships with a Docking Port magnetically lock to it for cargo transfer.");
            var blockWirelessST = MakeIndustrialBlock("Block_WirelessStorageTerminal", "Wireless Storage Terminal", new Color(0.55f,0.30f,0.85f), wstPrefab,
                "Access the storage network from up to 60 m away. Requires power and a connected Server Rack. Unlocks with Wireless Access research.");

            // ====================================================================
            //  3) NEW SMELTING RECIPES — Glass
            // ====================================================================
            var smGlass = AssetDatabase.LoadAssetAtPath<VoxelEngine.Crafting.SmeltingRecipe>($"{recipesFolder}/Smelt_Glass.asset");
            if (smGlass == null)
            {
                smGlass = ScriptableObject.CreateInstance<VoxelEngine.Crafting.SmeltingRecipe>();
                AssetDatabase.CreateAsset(smGlass, $"{recipesFolder}/Smelt_Glass.asset");
            }
            smGlass.input = sand; smGlass.inputCount = 1;
            smGlass.output = glass; smGlass.outputCount = 1;
            smGlass.smeltSeconds = 4f;
            EditorUtility.SetDirty(smGlass);

            // Append glass smelting to the existing Furnace + Electric Furnace prefabs.
            AppendSmeltingRecipe($"{ASSET_ROOT}/StationPrefabs/Furnace.prefab",  smGlass);
            AppendSmeltingRecipe($"{ASSET_ROOT}/Power/Prefabs/ElectricFurnace.prefab", smGlass, electric: true);

            // ====================================================================
            //  4) NEW PROCESSING RECIPES — for the Oil Refinery
            // ====================================================================
            VoxelEngine.Crafting.ProcessingRecipe MakeProc(string assetName, string display, string category,
                (VoxelEngine.Items.ItemDefinition item, int n)[] inputs,
                (VoxelEngine.Items.ItemDefinition item, int n)[] outputs,
                float seconds, float powerMul = 1f,
                (VoxelEngine.Items.LiquidType liquid, float litres)[] fluidIn = null,
                (VoxelEngine.Items.LiquidType liquid, float litres)[] fluidOut = null)
            {
                string path = $"{procRecFolder}/{assetName}.asset";
                bool existed = AssetDatabase.LoadAssetAtPath<VoxelEngine.Crafting.ProcessingRecipe>(path) != null;
                var r = GetOrCreateAsset<VoxelEngine.Crafting.ProcessingRecipe>(path);

                // Only populate fields on freshly-created recipes — never overwrite user edits.
                if (existed) return r;

                r.displayName = display;
                r.category    = category;
                r.secondsPerBatch     = seconds;
                r.powerDrawMultiplier = powerMul;
                r.inputs  = new VoxelEngine.Crafting.ProcessingIO[inputs.Length];
                for (int i = 0; i < inputs.Length; i++)
                    r.inputs[i]  = new VoxelEngine.Crafting.ProcessingIO { item = inputs[i].item,  count = inputs[i].n };
                r.outputs = new VoxelEngine.Crafting.ProcessingIO[outputs.Length];
                for (int i = 0; i < outputs.Length; i++)
                    r.outputs[i] = new VoxelEngine.Crafting.ProcessingIO { item = outputs[i].item, count = outputs[i].n };
                fluidIn  ??= System.Array.Empty<(VoxelEngine.Items.LiquidType, float)>();
                fluidOut ??= System.Array.Empty<(VoxelEngine.Items.LiquidType, float)>();
                r.fluidInputs  = new VoxelEngine.Crafting.FluidIO[fluidIn.Length];
                for (int i = 0; i < fluidIn.Length; i++)
                    r.fluidInputs[i]  = new VoxelEngine.Crafting.FluidIO { liquid = fluidIn[i].liquid,  litres = fluidIn[i].litres };
                r.fluidOutputs = new VoxelEngine.Crafting.FluidIO[fluidOut.Length];
                for (int i = 0; i < fluidOut.Length; i++)
                    r.fluidOutputs[i] = new VoxelEngine.Crafting.FluidIO { liquid = fluidOut[i].liquid, litres = fluidOut[i].litres };

                return r;
            }

            var noItems = System.Array.Empty<(VoxelEngine.Items.ItemDefinition, int)>();

            // Crude → Refined: 100 L crude oil (liquid) → 80 L refined oil (liquid).
            var procRefine  = MakeProc("Proc_RefineOil", "Refine Crude Oil", "Refinery",
                noItems, noItems, seconds: 12f, powerMul: 1f,
                fluidIn:  new[] { (VoxelEngine.Items.LiquidType.CrudeOil,   100f) },
                fluidOut: new[] { (VoxelEngine.Items.LiquidType.RefinedOil,  80f) });

            // Refined oil (liquid) + coal → 2 plastic.  (No more barrels.)
            var procPlastic = MakeProc("Proc_MakePlastic", "Synthesise Plastic", "Plastics",
                new[] { (coal, 1) },
                new[] { ((VoxelEngine.Items.ItemDefinition)plastic, 2) },
                seconds: 14f, powerMul: 1.25f,
                fluidIn: new[] { (VoxelEngine.Items.LiquidType.RefinedOil, 50f) });

            // Liquid Fuel item — kept as the bottled/transportable product.
            var liquidFuel  = MakeIndustrialResource("Item_LiquidFuel", "Liquid Fuel",
                "High-performance synthesised fuel. Powers advanced thrusters and engines.",
                new Color(0.95f, 0.65f, 0.15f), VoxelEngine.Items.ResourceCategory.Component, "Oil", maxStack: 50);
            liquidFuel.fuelSeconds = 180f; EditorUtility.SetDirty(liquidFuel);

            // Chemistry: 60 L refined oil + 1 plastic → 100 L Liquid Fuel (tank) + 2 Liquid Fuel (item).
            var procLiquidFuel = MakeProc("Proc_MakeLiquidFuel", "Synthesise Liquid Fuel", "Chemistry",
                new[] { ((VoxelEngine.Items.ItemDefinition)plastic, 1) },
                new[] { ((VoxelEngine.Items.ItemDefinition)liquidFuel, 2) },
                seconds: 16f, powerMul: 1.3f,
                fluidIn:  new[] { (VoxelEngine.Items.LiquidType.RefinedOil, 60f) },
                fluidOut: new[] { (VoxelEngine.Items.LiquidType.LiquidFuel, 100f) });

            // ════════════════════════════════════════════════════════════
            //  MARITIME FUEL CHAIN — Heavy Fuel Oil + Marine Gas Oil
            // ════════════════════════════════════════════════════════════
            // Refinery: Refined Oil → Heavy Fuel Oil (thick bunker fuel for Medium Engines).
            var procHeavyFuel = MakeProc("Proc_RefineHeavyFuelOil", "Distil Heavy Fuel Oil", "Refinery",
                noItems, noItems, seconds: 14f, powerMul: 1.15f,
                fluidIn:  new[] { (VoxelEngine.Items.LiquidType.RefinedOil,    80f) },
                fluidOut: new[] { (VoxelEngine.Items.LiquidType.HeavyFuelOil,  55f) });

            // Refinery: Heavy Fuel Oil → Marine Gas Oil (clean high-grade distillate for Giant Diesel).
            var procMGO = MakeProc("Proc_RefineMGO", "Distil Marine Gas Oil", "Refinery",
                noItems, noItems, seconds: 18f, powerMul: 1.3f,
                fluidIn:  new[] { (VoxelEngine.Items.LiquidType.HeavyFuelOil,   60f) },
                fluidOut: new[] { (VoxelEngine.Items.LiquidType.MarineGasOil,   45f) });

            // Chemistry: Refined Oil → Marine Gas Oil via catalytic cracking (shortcut, no HFO step).
            var procSynthMGO = MakeProc("Proc_SynthesiseMGO", "Cracked Marine Gas Oil", "Chemistry",
                noItems, noItems, seconds: 20f, powerMul: 1.5f,
                fluidIn:  new[] { (VoxelEngine.Items.LiquidType.RefinedOil,    50f) },
                fluidOut: new[] { (VoxelEngine.Items.LiquidType.MarineGasOil,  30f) });

            // Marine Engine Coolant — synthesised in the chemical plant.
            var procCoolant = MakeProc("Proc_MarineCoolant", "Synthesise Marine Engine Coolant", "Chemistry",
                noItems, noItems, seconds: 10f, powerMul: 1.2f,
                fluidIn:  new[] { (VoxelEngine.Items.LiquidType.Water,         100f) },
                fluidOut: new[] { (VoxelEngine.Items.LiquidType.MarineEngineCoolant, 60f) });

            // Attach those recipes to the OilRefinery prefab.
            AppendOilRefineryRecipes(refineryPrefab, new List<VoxelEngine.Crafting.ProcessingRecipe> { procRefine, procPlastic, procHeavyFuel, procMGO });

            // Attach the Chemistry recipe to the Stationary Chemical Plant prefab.
            AppendChemicalPlantRecipes(chemPlantPrefab, new List<VoxelEngine.Crafting.ProcessingRecipe> { procLiquidFuel, procSynthMGO, procCoolant });

            // ====================================================================
            //  5) NEW CRAFTING RECIPES — registered into the global RecipeRegistry
            // ====================================================================
            // Remove any old duplicates of recipes we are about to (re)create so the
            // registry doesn't grow stale entries on every re-run.
            string[] toReplace =
            {
                "Recipe_IronPlate","Recipe_CopperPlate","Recipe_SteelPlate",
                "Recipe_IronGear","Recipe_CopperWire","Recipe_Circuit","Recipe_AdvCircuit",
                "Recipe_EmptyBarrel","Recipe_Pumpjack","Recipe_OilRefinery",
                "Recipe_Plastic_PlayerHint",
                "Recipe_WirelessStorageTerminal",
            };
            registry.recipes.RemoveAll(r => r != null && System.Array.IndexOf(toReplace, r.name) >= 0);

            // ── Plating tier (gated by "Plating" research) ──
            var recIronPlate   = AddRecipe("Recipe_IronPlate", "Iron Plate", ironPlate, 1, VoxelEngine.Crafting.StationTier.Assembler, false, ((VoxelEngine.Items.ItemDefinition)ironIngot, 2));
            var recCopperPlate = AddRecipe("Recipe_CopperPlate", "Copper Plate", copperPlate, 1, VoxelEngine.Crafting.StationTier.Assembler, false, ((VoxelEngine.Items.ItemDefinition)copperIngot, 2));
            var recSteelPlate  = AddRecipe("Recipe_SteelPlate", "Steel Plate", steelPlate, 1, VoxelEngine.Crafting.StationTier.Assembler, false, ((VoxelEngine.Items.ItemDefinition)steelIngot, 2));
            var recIronGear    = AddRecipe("Recipe_IronGear", "Iron Gear", ironGear, 1, VoxelEngine.Crafting.StationTier.Assembler, false, ((VoxelEngine.Items.ItemDefinition)ironPlate, 2));

            // ── Wires & circuits (gated by Electronics / Adv Electronics) ──
            var recCopperWire  = AddRecipe("Recipe_CopperWire", "Copper Wire x2", copperWire, 2, VoxelEngine.Crafting.StationTier.CraftingBench, false, ((VoxelEngine.Items.ItemDefinition)copperIngot, 1));
            var recCircuit     = AddRecipe("Recipe_Circuit", "Electronic Circuit", circuitBasic, 1, VoxelEngine.Crafting.StationTier.Assembler, false, ((VoxelEngine.Items.ItemDefinition)ironPlate, 1), ((VoxelEngine.Items.ItemDefinition)copperWire, 3));
            var recAdvCircuit  = AddRecipe("Recipe_AdvCircuit", "Advanced Circuit", circuitAdv, 1, VoxelEngine.Crafting.StationTier.Assembler, false, ((VoxelEngine.Items.ItemDefinition)circuitBasic, 2), ((VoxelEngine.Items.ItemDefinition)plastic, 2), ((VoxelEngine.Items.ItemDefinition)copperWire, 4));

            // ── Oil chain (gated by Oil Extraction / Refining / Plastics) ──
            var recEmptyBarrel = AddRecipe("Recipe_EmptyBarrel", "Empty Barrel", emptyBarrel, 1, VoxelEngine.Crafting.StationTier.Assembler, false, ((VoxelEngine.Items.ItemDefinition)steelPlate, 1), ((VoxelEngine.Items.ItemDefinition)ironPlate, 2));
            var recPumpjack = EnsureJackPumpRecipe(registry, blockPumpjack, pirateJackPumpHead,
                steelPlate, ironGear, circuitBasic, circuitAdv, copperPlate);
            var recRefinery    = AddRecipe("Recipe_OilRefinery", "Oil Refinery", blockRefinery, 1, VoxelEngine.Crafting.StationTier.Assembler, false, ((VoxelEngine.Items.ItemDefinition)steelPlate, 12), ((VoxelEngine.Items.ItemDefinition)ironGear, 8), ((VoxelEngine.Items.ItemDefinition)circuitBasic, 4), ((VoxelEngine.Items.ItemDefinition)copperPlate, 4));
            var recChemPlant   = AddRecipe("Recipe_ChemicalPlant", "Chemical Plant", blockChemPlant, 1, VoxelEngine.Crafting.StationTier.Assembler, false, ((VoxelEngine.Items.ItemDefinition)steelPlate, 12), ((VoxelEngine.Items.ItemDefinition)circuitAdv, 4), ((VoxelEngine.Items.ItemDefinition)copperWire, 8), ((VoxelEngine.Items.ItemDefinition)glass, 4));
            var recDock        = AddRecipe("Recipe_StationaryDockingPort", "Docking Pad", blockDock, 1, VoxelEngine.Crafting.StationTier.Assembler, true, ((VoxelEngine.Items.ItemDefinition)steelPlate, 10), ((VoxelEngine.Items.ItemDefinition)copperWire, 6));

            // ── Wireless Storage Terminal (gated by Wireless Access) ──
            var recWST = AddRecipe("Recipe_WirelessStorageTerminal", "Wireless Storage Terminal", blockWirelessST, 1, VoxelEngine.Crafting.StationTier.Assembler, false, ((VoxelEngine.Items.ItemDefinition)steelPlate, 4), (advCircuitOrFallback(circuitAdv, circuitBasic), 3), ((VoxelEngine.Items.ItemDefinition)copperWire, 8), ((VoxelEngine.Items.ItemDefinition)glass, 2));

            // ── Re-cost existing storage / power / quarry recipes to use plates+circuits ──
            // We REPLACE the inputs of these recipes in-place so they "make sense" in the new economy.
            // NOTE: the explicit (ItemDefinition) cast on the FIRST tuple element of
            // each array widens the inferred type from ResourceItem → ItemDefinition,
            // matching the helper's param signature. (C# does not apply tuple
            // covariance inside array literals.)
            RewireExistingRecipe("Recipe_Generator",      new[] { ((VoxelEngine.Items.ItemDefinition)ironPlate, 4), (ironGear, 2), (stone, 4) });
            RewireExistingRecipe("Recipe_Battery",        new[] { ((VoxelEngine.Items.ItemDefinition)ironPlate, 2), (copperWire, 6), (copperPlate, 2), (EnsureLithiumResource(), 2) });
            RewireExistingRecipe("Recipe_Cable_Copper",   new[] { ((VoxelEngine.Items.ItemDefinition)copperIngot, 1) });   // unchanged: 1 ingot → 4 cables
            RewireExistingRecipe("Recipe_Cable_Iron",     new[] { ((VoxelEngine.Items.ItemDefinition)ironPlate,   1) });   // now uses plates instead of ingots
            RewireExistingRecipe("Recipe_Cable_Gold",     new[] { (goldOreOrFallback(goldOre, ironIngot), 1), ((VoxelEngine.Items.ItemDefinition)copperWire, 2) });
            RewireExistingRecipe("Recipe_Cable_Super",    new[] { ((VoxelEngine.Items.ItemDefinition)steelPlate, 1), (goldOreOrFallback(goldOre, ironIngot), 1), (copperWire, 2) });
            RewireExistingRecipe("Recipe_ElectricFurnace",new[] { ((VoxelEngine.Items.ItemDefinition)steelPlate, 4), (circuitBasic, 2), (copperPlate, 2) });
            RewireExistingRecipe("Recipe_Assembler",      new[] { ((VoxelEngine.Items.ItemDefinition)ironPlate, 6), (ironGear, 4), (circuitBasic, 1), (stone, 8) });
            RewireExistingRecipe("Recipe_Wireless_Tx",    new[] { ((VoxelEngine.Items.ItemDefinition)steelPlate, 4), (advCircuitOrFallback(circuitAdv, circuitBasic), 2), (copperWire, 8) });
            RewireExistingRecipe("Recipe_Wireless_Rx",    new[] { ((VoxelEngine.Items.ItemDefinition)steelPlate, 2), (advCircuitOrFallback(circuitAdv, circuitBasic), 1), (copperWire, 6) });

            // ====================================================================
            //  6) RESEARCH NODES — expansion of the existing tree
            // ====================================================================
            const string treePath = researchFolder + "/ResearchTree.asset";
            var tree = AssetDatabase.LoadAssetAtPath<VoxelEngine.Research.ResearchTree>(treePath);
            if (tree == null)
            {
                EditorUtility.DisplayDialog("Voxel Engine", "Run Step 7 (Build Research Content) first — the ResearchTree asset doesn't exist yet.", "OK");
                return;
            }

            // Helper: find an already-existing node by id (so we can use it as a prerequisite).
            VoxelEngine.Research.ResearchNode FindNode(string id)
            {
                foreach (var nd in tree.nodes)
                    if (nd != null && nd.nodeId == id) return nd;
                return null;
            }

            var nStoneWorking      = FindNode("res_stone_working");
            var nSmelting          = FindNode("res_smelting");
            var nElectricity       = FindNode("res_electricity");
            var nAdvMfg            = FindNode("res_adv_manufacturing");
            var nSteelAlloy        = FindNode("res_steel_alloy");
            var nHighVoltage       = FindNode("res_high_voltage");

            VoxelEngine.Research.ResearchNode MakeOrUpdateEnvNode(
                string id, string display, string desc,
                int tier, int col, VoxelEngine.Research.ResearchSubCategory sub,
                Color tint, float seconds,
                (VoxelEngine.Items.ScienceItem p, int n)[] cost,
                VoxelEngine.Crafting.RecipeDefinition[] unlocks,
                VoxelEngine.Research.ResearchNode[] prereqs = null)
            {
                string path = $"{nodesFolder}/{id}.asset";
                var n = AssetDatabase.LoadAssetAtPath<VoxelEngine.Research.ResearchNode>(path);
                if (n == null)
                {
                    n = ScriptableObject.CreateInstance<VoxelEngine.Research.ResearchNode>();

                }
                n.nodeId         = id;
                n.displayName    = display;
                n.description    = desc;
                n.category       = VoxelEngine.Research.ResearchCategory.Environment;
                n.subCategory    = sub;
                n.tier           = tier;
                n.column         = col;
                n.iconTint       = tint;
                n.researchSeconds= seconds;
                n.cost = new VoxelEngine.Research.ResearchNode.ScienceCost[cost.Length];
                for (int i = 0; i < cost.Length; i++)
                    n.cost[i] = new VoxelEngine.Research.ResearchNode.ScienceCost { pack = cost[i].p, count = cost[i].n };
                var unl = new List<VoxelEngine.Crafting.RecipeDefinition>();
                foreach (var u in unlocks ?? new VoxelEngine.Crafting.RecipeDefinition[0])
                    if (u != null) unl.Add(u);
                n.unlocksRecipes = unl.ToArray();
                n.prerequisites  = prereqs ?? new VoxelEngine.Research.ResearchNode[0];
                n.upgradeKind    = VoxelEngine.Research.PlayerUpgradeKind.None;
                n.maxRanks       = 1;

                if (!AssetDatabase.Contains(n)) AssetDatabase.CreateAsset(n, path);
                else EditorUtility.SetDirty(n);

                if (!tree.nodes.Contains(n)) tree.nodes.Add(n);
                return n;
            }

            // Re-tag existing nodes with sub-categories so they show up in the new tabs.
            void Retag(VoxelEngine.Research.ResearchNode n, VoxelEngine.Research.ResearchSubCategory sub, Color tint)
            {
                if (n == null) return;
                n.subCategory = sub;
                n.iconTint    = tint;
                EditorUtility.SetDirty(n);
            }
            Retag(nStoneWorking, VoxelEngine.Research.ResearchSubCategory.Production, new Color(0.55f, 0.50f, 0.45f));
            Retag(nSmelting,     VoxelEngine.Research.ResearchSubCategory.Production, new Color(0.85f, 0.55f, 0.30f));
            Retag(nElectricity,  VoxelEngine.Research.ResearchSubCategory.Power,      new Color(0.95f, 0.85f, 0.30f));
            Retag(nAdvMfg,       VoxelEngine.Research.ResearchSubCategory.Production, new Color(0.30f, 0.65f, 0.95f));
            Retag(nSteelAlloy,   VoxelEngine.Research.ResearchSubCategory.Production, new Color(0.60f, 0.62f, 0.68f));
            Retag(nHighVoltage,  VoxelEngine.Research.ResearchSubCategory.Power,      new Color(0.45f, 0.85f, 1.00f));

            // ── New nodes ──

            // T2 — Plating: unlocks iron / copper / steel plates and iron gear.
            var nPlating = MakeOrUpdateEnvNode("res_plating", "Plating",
                "Stamp ingots into plates and cut them into gears. Plates are the structural backbone of every advanced machine.",
                tier: 2, col: 2, sub: VoxelEngine.Research.ResearchSubCategory.Production,
                tint: new Color(0.78f, 0.80f, 0.85f), seconds: 35f,
                cost: new[] { (sciT1, 15), (sciT2, 8) },
                unlocks: new[] { recIronPlate, recCopperPlate, recSteelPlate, recIronGear },
                prereqs: new[] { nSmelting });

            // T2 — Glassworking: unlocks glass smelting (already gates Glass tank/pipe recipes if present).
            var recPipeGlass = FindRecipeByName("Recipe_PipeGlass");
            var recTankGlass = FindRecipeByName("Recipe_TankGlass");
            var nGlasswork = MakeOrUpdateEnvNode("res_glassworking", "Glassworking",
                "Smelt sand into glass. Required for lab equipment, decorative pipes, and observation tanks.",
                tier: 2, col: 3, sub: VoxelEngine.Research.ResearchSubCategory.Chemistry,
                tint: new Color(0.70f, 0.88f, 0.95f), seconds: 30f,
                cost: new[] { (sciT1, 10), (sciT2, 5) },
                unlocks: new[] { recPipeGlass, recTankGlass },
                prereqs: new[] { nSmelting });
            // Lock the glass-tank / glass-pipe recipes so the node actually gates them.
            LockRecipe(recPipeGlass); LockRecipe(recTankGlass);

            // T2 — Fluid Handling: gates the existing water bucket / pump / pipes / tanks.
            var recWaterBucket = FindRecipeByName("Recipe_WaterBucket");
            var recPipeSolid   = FindRecipeByName("Recipe_PipeSolid");
            var recTankSolid   = FindRecipeByName("Recipe_TankSolid");
            var recWaterPump   = FindRecipeByName("Recipe_WaterPump");
            var nFluidHandling = MakeOrUpdateEnvNode("res_fluid_handling", "Fluid Handling",
                "Move water with pumps and pipes. Foundational for refining, cooling, and farming.",
                tier: 2, col: 4, sub: VoxelEngine.Research.ResearchSubCategory.Logistics,
                tint: new Color(0.40f, 0.85f, 0.95f), seconds: 40f,
                cost: new[] { (sciT1, 12), (sciT2, 6) },
                unlocks: new[] { recWaterBucket, recPipeSolid, recTankSolid, recWaterPump },
                prereqs: new[] { nSmelting });
            LockRecipe(recWaterBucket); LockRecipe(recPipeSolid); LockRecipe(recTankSolid); LockRecipe(recWaterPump);

            // T3 — Electronics: unlocks Copper Wire + Electronic Circuit. Prereqs: Plating + Electricity.
            var nElectronics = MakeOrUpdateEnvNode("res_electronics", "Electronics",
                "Draw copper into wire and laminate it onto iron substrate to make Electronic Circuits — the prerequisite for nearly every advanced machine.",
                tier: 3, col: 3, sub: VoxelEngine.Research.ResearchSubCategory.Production,
                tint: new Color(0.30f, 0.65f, 0.40f), seconds: 60f,
                cost: new[] { (sciT2, 20), (sciT3, 8) },
                unlocks: new[] { recCopperWire, recCircuit },
                prereqs: new[] { nPlating, nElectricity });

            // T4 — Advanced Electronics: unlocks Adv Circuit. Needs Electronics + Adv Mfg + Plastics (chain).
            // Adv-Circuit recipe also requires plastic — players must complete Plastics first to truly use it.
            var nAdvElectronics = MakeOrUpdateEnvNode("res_adv_electronics", "Advanced Electronics",
                "Multi-layer logic boards built from plastic, copper wire, and basic circuits. Powers wireless access, mass storage, and nuclear control.",
                tier: 4, col: 3, sub: VoxelEngine.Research.ResearchSubCategory.Production,
                tint: new Color(0.30f, 0.55f, 0.95f), seconds: 90f,
                cost: new[] { (sciT2, 30), (sciT3, 15) },
                unlocks: new[] { recAdvCircuit },
                prereqs: new[] { nElectronics, nAdvMfg });

            // T3 — Oil Logistics: creates Empty Barrels, but not the relic-gated Jack Pump.
            var nOilExtraction = MakeOrUpdateEnvNode("res_oil_extraction", "Oil Logistics",
                "Press steel into Empty Barrels and establish the logistics needed to handle crude oil. Rare Pirate technology is required for a Jack Pump.",
                tier: 3, col: 4, sub: VoxelEngine.Research.ResearchSubCategory.Chemistry,
                tint: new Color(0.10f, 0.08f, 0.06f), seconds: 70f,
                cost: new[] { (sciT2, 20), (sciT3, 10) },
                unlocks: new[] { recEmptyBarrel },
                prereqs: new[] { nSteelAlloy });

            // T4 — Pirate Oil Recovery: the recipe is deliberately impossible to
            // complete without the uncraftable Jack Pump Head recovered in Pirate ruins.
            var nPirateJackPump = MakeOrUpdateEnvNode("res_pirate_jack_pump", "Pirate Oil Recovery",
                "Reverse-engineer a recovered Pirate Jack Pump Head into a high-draw walking-beam extractor for the Pirate World's rare infinite oil nodes.",
                tier: 4, col: 4, sub: VoxelEngine.Research.ResearchSubCategory.Chemistry,
                tint: new Color(0.32f, 0.26f, 0.18f), seconds: 150f,
                cost: new[] { (sciT2, 45), (sciT3, 25) },
                unlocks: new[] { recPumpjack },
                prereqs: new[] { nOilExtraction, nAdvMfg });
            LockRecipe(recPumpjack);

            // T4 — Oil Refining: unlocks Oil Refinery. Prereqs: Oil Extraction + Electronics.
            var nOilRefining = MakeOrUpdateEnvNode("res_oil_refining", "Oil Refining",
                "Crack and distil crude oil into Refined Oil — a high-energy industrial feedstock.",
                tier: 4, col: 4, sub: VoxelEngine.Research.ResearchSubCategory.Chemistry,
                tint: new Color(0.50f, 0.30f, 0.10f), seconds: 90f,
                cost: new[] { (sciT2, 25), (sciT3, 15) },
                unlocks: new[] { recRefinery, recChemPlant },
                prereqs: new[] { nOilExtraction, nElectronics });

            // T4 — Plastics: enables the plastic processing recipe (already loaded into refinery prefab).
            // No separate "recipe" item to unlock for plastic — it's automatic in the refinery — but
            // we keep the node so the player knows when plastic synthesis is possible (and the refinery
            // simply ignores recipes it doesn't yet "know about" via this node-driven flag in the future).
            var nPlastics = MakeOrUpdateEnvNode("res_plastics", "Plastics",
                "Polymerise refined oil and coal into Plastic Bars. Required for advanced circuits, durable insulation, and end-game logistics.",
                tier: 4, col: 5, sub: VoxelEngine.Research.ResearchSubCategory.Chemistry,
                tint: new Color(0.92f, 0.92f, 0.96f), seconds: 80f,
                cost: new[] { (sciT2, 20), (sciT3, 15) },
                unlocks: new VoxelEngine.Crafting.RecipeDefinition[0],
                prereqs: new[] { nOilRefining });

            // ─ Logistics Network (storage system) ─
            // We don't have the storage recipes auto-built in any earlier step, so this node simply
            // *unlocks* any recipe we can find by name. Authoring the storage recipes themselves is
            // delegated to a future step (or manual ScriptableObject creation). We still lock anything
            // we DO find so progression remains gated.
            VoxelEngine.Crafting.RecipeDefinition[] StorageRecipes(params string[] names)
            {
                var list = new List<VoxelEngine.Crafting.RecipeDefinition>();
                foreach (var nm in names)
                {
                    var r = FindRecipeByName(nm);
                    if (r != null) { LockRecipe(r); list.Add(r); }
                }
                return list.ToArray();
            }

            var nLogistics = MakeOrUpdateEnvNode("res_logistics_network", "Logistics Network",
                "Server Racks, Storage Disks (1K, 4K), Importers, Exporters, and the wired Storage Terminal. The foundation of automated inventory management.",
