                cost: new[] { (sciT3, 60) },
                unlocks: StorageRecipes("Recipe_UraniumProcessor","Recipe_ReactorCore","Recipe_SteamTurbine","Recipe_PortableReactor","Recipe_WasteReprocessor"),
