        private static VoxelEngine.Items.ItemDefinition advCircuitOrFallback(VoxelEngine.Items.ItemDefinition adv, VoxelEngine.Items.ItemDefinition fallback)
            => adv != null ? adv : fallback;
        private static VoxelEngine.Items.ItemDefinition goldOreOrFallback(VoxelEngine.Items.ItemDefinition g, VoxelEngine.Items.ItemDefinition fallback)
            => g != null ? g : fallback;

        private static void LockRecipe(VoxelEngine.Crafting.RecipeDefinition r)
        {
            if (r == null) return;
            r.unlockedByDefault = false;
            EditorUtility.SetDirty(r);
        }

        private static void RewireExistingRecipe(string assetName, (VoxelEngine.Items.ItemDefinition item, int n)[] inputs)
        {
            var r = FindRecipeByName(assetName);
            if (r == null) return;
            int count = 0;
            foreach (var i in inputs) if (i.item != null && i.n > 0) count++;
            r.inputs = new VoxelEngine.Crafting.RecipeIngredient[count];
            int j = 0;
            foreach (var i in inputs)
            {
                if (i.item == null || i.n <= 0) continue;
                r.inputs[j++] = new VoxelEngine.Crafting.RecipeIngredient { item = i.item, count = i.n };
            }
            EditorUtility.SetDirty(r);
        }

        /// <summary>Creates the head-gated Jack Pump recipe without overwriting a hand-tuned custom recipe.</summary>
        private static VoxelEngine.Crafting.RecipeDefinition EnsureJackPumpRecipe(
            VoxelEngine.Crafting.RecipeRegistry registry,
            VoxelEngine.Items.ItemDefinition jackPump,
            VoxelEngine.Items.ItemDefinition pirateHead,
            VoxelEngine.Items.ItemDefinition steelPlate,
            VoxelEngine.Items.ItemDefinition ironGear,
            VoxelEngine.Items.ItemDefinition circuitBasic,
            VoxelEngine.Items.ItemDefinition circuitAdvanced,
            VoxelEngine.Items.ItemDefinition copperPlate)
        {
            const string recipePath = ASSET_ROOT + "/Recipes/Recipe_Pumpjack.asset";
            var recipe = AssetDatabase.LoadAssetAtPath<VoxelEngine.Crafting.RecipeDefinition>(recipePath);
            bool created = recipe == null;
            if (recipe == null)
            {
                recipe = ScriptableObject.CreateInstance<VoxelEngine.Crafting.RecipeDefinition>();
                AssetDatabase.CreateAsset(recipe, recipePath);
            }

            bool legacy = IsLegacyJackPumpRecipe(recipe, steelPlate, ironGear, circuitBasic);
            if (created || legacy)
            {
                recipe.displayName = "Jack Pump";
                recipe.outputItem = jackPump;
                recipe.outputCount = 1;
                recipe.requiredStation = VoxelEngine.Crafting.StationTier.Assembler;
                recipe.craftSeconds = 90f;
                recipe.inputs = BuildIngredients(
                    (steelPlate, 30),
                    (ironGear, 20),
                    (copperPlate, 12),
                    (circuitBasic, 8),
                    (circuitAdvanced, 4),
                    (pirateHead, 1));
            }
            else
            {
                // Preserve custom numeric balance while making the required relic
                // non-optional on any pre-existing authored Jack Pump recipe.
                recipe.outputItem ??= jackPump;
                if (recipe.craftSeconds <= 0f) recipe.craftSeconds = 90f;
                AppendIngredientIfMissing(recipe, pirateHead, 1);
            }

            recipe.unlockedByDefault = false;
            if (registry != null)
            {
                registry.recipes.RemoveAll(r => r != null && r != recipe && r.name == "Recipe_Pumpjack");
                if (!registry.recipes.Contains(recipe)) registry.recipes.Add(recipe);
            }
            EditorUtility.SetDirty(recipe);
            return recipe;
        }

        private static bool IsLegacyJackPumpRecipe(VoxelEngine.Crafting.RecipeDefinition recipe,
            VoxelEngine.Items.ItemDefinition steelPlate, VoxelEngine.Items.ItemDefinition ironGear,
            VoxelEngine.Items.ItemDefinition circuitBasic)
        {
            if (recipe == null || recipe.inputs == null || recipe.inputs.Length != 3) return false;
            return HasIngredient(recipe, steelPlate, 8)
                && HasIngredient(recipe, ironGear, 6)
                && HasIngredient(recipe, circuitBasic, 2);
        }

        private static bool HasIngredient(VoxelEngine.Crafting.RecipeDefinition recipe,
            VoxelEngine.Items.ItemDefinition item, int count = -1)
        {
            if (recipe?.inputs == null || item == null) return false;
            foreach (var ingredient in recipe.inputs)
                if (ingredient.item == item && (count < 0 || ingredient.count == count)) return true;
            return false;
        }

        private static VoxelEngine.Crafting.RecipeIngredient[] BuildIngredients(
            params (VoxelEngine.Items.ItemDefinition item, int count)[] ingredients)
        {
            var list = new List<VoxelEngine.Crafting.RecipeIngredient>();
            foreach (var entry in ingredients)
                if (entry.item != null && entry.count > 0)
                    list.Add(new VoxelEngine.Crafting.RecipeIngredient { item = entry.item, count = entry.count });
            return list.ToArray();
        }

        private static void AppendIngredientIfMissing(VoxelEngine.Crafting.RecipeDefinition recipe,
            VoxelEngine.Items.ItemDefinition item, int count)
        {
            if (recipe == null || item == null || count <= 0 || HasIngredient(recipe, item)) return;
            var list = new List<VoxelEngine.Crafting.RecipeIngredient>(recipe.inputs ?? System.Array.Empty<VoxelEngine.Crafting.RecipeIngredient>())
            {
                new VoxelEngine.Crafting.RecipeIngredient { item = item, count = count }
            };
            recipe.inputs = list.ToArray();
        }

        /// <summary>
        /// Authors finite crude seeps only on the project's explicit oil-rich planets while
        /// reserving rare infinite Jack Pump nodes for the canonical Planet_Pirate asset.
        /// This is deliberately setup-owned: runtime code consumes the authored booleans and
        /// never infers oil richness from a loose display-name match.
        /// </summary>
        private static void ConfigureCrudeOilWorlds()
        {
            var guids = AssetDatabase.FindAssets("t:PlanetTemplate", new[] { PLANET_FOLDER });
            foreach (var guid in guids)
            {
                string path = AssetDatabase.GUIDToAssetPath(guid);
                var planet = AssetDatabase.LoadAssetAtPath<VoxelEngine.Cosmos.PlanetTemplate>(path);
                if (planet == null || planet.body == null) continue;

                bool legacySeepSettings = planet.body.crudeOilSeepSettingsVersion < 2;
                bool oilRich = TryGetOilRichSeepDefault(path, out float defaultSeepChance);
                if (oilRich)
                {
                    planet.body.enableCrudeOilSeeps = true;
                    // Preserve hand-tuned rates after the first authored distribution pass.
                    // The old generic 12% default is migrated to each world's intended profile.
                    if (planet.body.crudeOilSiteChance <= 0f
                        || (legacySeepSettings && Mathf.Approximately(planet.body.crudeOilSiteChance, 0.12f)))
                        planet.body.crudeOilSiteChance = defaultSeepChance;
                    EnsureCrudeOilSpecialDeposit(planet.body);
                }
                else if (legacySeepSettings)
                {
                    // First distribution pass disables legacy generic crude markers on the
                    // non-oil-rich templates. Later setup runs preserve any deliberate custom
                    // finite-seep flag a designer has authored for a custom world.
                    planet.body.enableCrudeOilSeeps = false;
                }
                planet.body.crudeOilSeepSettingsVersion = 2;

                // Infinite extraction is not a general oil-world feature. It is locked to the
                // exact Planet_Pirate asset, even if another body's display name is edited.
                bool pirate = IsCanonicalPlanet(path, "Planet_Pirate");
                planet.body.isCanonicalPirateJackPumpWorld = pirate;
                if (pirate)
                {
                    bool legacyInfiniteSettings = planet.body.pirateOilNodeSettingsVersion == 0;
                    planet.body.enableInfiniteOilNodes = true;
                    // The old 2.5% default was not actually "very rare" at 96 m cell density;
                    // migrate only that legacy default to the 0.3% rare-node rate.
                    if (planet.body.infiniteOilNodeChance <= 0f
                        || (legacyInfiniteSettings && Mathf.Approximately(planet.body.infiniteOilNodeChance, 0.025f)))
                        planet.body.infiniteOilNodeChance = 0.003f;
                }
                else
                {
                    planet.body.enableInfiniteOilNodes = false;
                }
                planet.body.pirateOilNodeSettingsVersion = 1;
                EditorUtility.SetDirty(planet);
            }
        }

        /// <summary>
        /// Intentional finite-oil distribution. Earth has mature sedimentary basins; Ocean
        /// World has marine basins; Acid and Desolate Worlds hold organic/ancient basin deposits;
        /// Pirate World remains the richest conventional seep world. All other current worlds
        /// retain their distinct non-petroleum resource identity.
        /// </summary>
        private static bool TryGetOilRichSeepDefault(string path, out float chance)
        {
            chance = 0f;
            string asset = Path.GetFileNameWithoutExtension(path);
            switch (asset)
            {
                case "Planet_Earth":
                    chance = 0.08f;
                    return true;
                case "Planet_Water":
                    chance = 0.10f;
                    return true;
                case "Planet_Acid":
                    chance = 0.06f;
                    return true;
                case "Planet_Desolate":
                    chance = 0.05f;
                    return true;
                case "Planet_Pirate":
                    chance = 0.12f;
                    return true;
                default:
                    return false;
            }
        }

        private static bool IsCanonicalPlanet(string path, string assetName)
            => string.Equals(Path.GetFileNameWithoutExtension(path), assetName, System.StringComparison.Ordinal);

        private static void EnsureCrudeOilSpecialDeposit(VoxelEngine.Cosmos.BodySettings body)
        {
            if (body == null) return;
            body.specials ??= new List<VoxelEngine.Cosmos.OreDeposit>();
            foreach (var deposit in body.specials)
                if (deposit.material == VoxelEngine.Materials.MaterialId.CrudeOil) return;

            body.specials.Add(new VoxelEngine.Cosmos.OreDeposit
            {
                material = VoxelEngine.Materials.MaterialId.CrudeOil,
                tier = VoxelEngine.Cosmos.OreTier.Special,
                scale = 0.04f,
                threshold = 0.70f,
                minDepth = 25,
                maxDepth = 90,
                abundance = 1f
            });
        }

        /// <summary>Adds the uncraftable relic head only to Pirate ruin rare rolls, preserving normal loot pools.</summary>
        private static void EnsurePirateJackPumpHeadRuinLoot(VoxelEngine.Items.ItemDefinition head)
        {
            if (head == null) return;
            string pirateRuinFolder = ASSET_ROOT + "/Survival/CelestialRuins";
            foreach (var guid in AssetDatabase.FindAssets("Ruin_Pirate t:Prefab", new[] { pirateRuinFolder }))
            {
                string path = AssetDatabase.GUIDToAssetPath(guid);
                var root = PrefabUtility.LoadPrefabContents(path);
                try
                {
                    foreach (var chest in root.GetComponentsInChildren<VoxelEngine.Exploration.RuinChest>(true))
                    {
                        var rare = new List<VoxelEngine.Items.ItemDefinition>(chest.rareComponents ?? System.Array.Empty<VoxelEngine.Items.ItemDefinition>());
                        if (!rare.Contains(head)) rare.Add(head);
                        chest.rareComponents = rare.ToArray();
                        chest.rareComponentChance = Mathf.Max(chest.rareComponentChance, 0.18f);
                        EditorUtility.SetDirty(chest);
                    }
                    PrefabUtility.SaveAsPrefabAsset(root, path);
                }
                finally
                {
                    PrefabUtility.UnloadPrefabContents(root);
                }
            }
        }

        /// <summary>Builds the default realistic walking-beam visual only when custom visual work is absent.</summary>
