            var visuals = new GameObject("JackPumpVisuals").transform;
            visuals.SetParent(root, false);

            AddJackPumpPart(visuals, "SkidBase", PrimitiveType.Cube, new Vector3(0f, 0.14f, 0f), new Vector3(2.7f, 0.28f, 1.55f), Quaternion.identity, dark);
            AddJackPumpPart(visuals, "Deck", PrimitiveType.Cube, new Vector3(0f, 0.34f, 0f), new Vector3(1.55f, 0.14f, 1.15f), Quaternion.identity, steel);
            AddJackPumpPart(visuals, "MotorHousing", PrimitiveType.Cube, new Vector3(-0.72f, 0.68f, 0.12f), new Vector3(0.62f, 0.50f, 0.62f), Quaternion.identity, dark);
            AddJackPumpPart(visuals, "Gearbox", PrimitiveType.Cylinder, new Vector3(-0.38f, 0.72f, 0.12f), new Vector3(0.38f, 0.20f, 0.38f), Quaternion.Euler(90f, 0f, 0f), brass);
            AddJackPumpPart(visuals, "CrankWheel", PrimitiveType.Cylinder, new Vector3(-0.18f, 0.82f, 0.38f), new Vector3(0.74f, 0.10f, 0.74f), Quaternion.Euler(90f, 0f, 0f), brass);
            AddJackPumpPart(visuals, "Counterweight", PrimitiveType.Cube, new Vector3(-0.43f, 1.03f, 0.38f), new Vector3(0.32f, 0.32f, 0.16f), Quaternion.identity, dark);
            AddJackPumpPart(visuals, "PivotStand", PrimitiveType.Cube, new Vector3(0f, 1.22f, 0f), new Vector3(0.26f, 1.72f, 0.26f), Quaternion.identity, steel);
            AddJackPumpPart(visuals, "WalkingBeam", PrimitiveType.Cube, new Vector3(0.38f, 1.72f, 0f), new Vector3(2.45f, 0.18f, 0.24f), Quaternion.Euler(0f, 0f, -5f), steel);
            AddJackPumpPart(visuals, "HorseHead", PrimitiveType.Sphere, new Vector3(1.56f, 1.61f, 0f), new Vector3(0.42f, 0.34f, 0.42f), Quaternion.identity, dark);
            AddJackPumpPart(visuals, "PolishedRod", PrimitiveType.Cylinder, new Vector3(1.58f, 0.82f, 0f), new Vector3(0.10f, 0.95f, 0.10f), Quaternion.identity, steel);
            AddJackPumpPart(visuals, "Wellhead", PrimitiveType.Cylinder, new Vector3(1.58f, 0.32f, 0f), new Vector3(0.34f, 0.22f, 0.34f), Quaternion.identity, brass);
            AddJackPumpPart(visuals, "OilOutput", PrimitiveType.Cylinder, new Vector3(0.88f, 0.50f, 0.46f), new Vector3(0.12f, 0.72f, 0.12f), Quaternion.Euler(90f, 0f, 0f), oil);
            AddJackPumpPart(visuals, "PipeManifold", PrimitiveType.Cube, new Vector3(0.86f, 0.48f, 0.30f), new Vector3(0.78f, 0.16f, 0.16f), Quaternion.identity, brass);
            AddJackPumpPart(visuals, "FrontBraceL", PrimitiveType.Cube, new Vector3(0.75f, 1.04f, -0.34f), new Vector3(0.12f, 1.45f, 0.12f), Quaternion.Euler(0f, 0f, -18f), steel);
            AddJackPumpPart(visuals, "FrontBraceR", PrimitiveType.Cube, new Vector3(0.75f, 1.04f, 0.34f), new Vector3(0.12f, 1.45f, 0.12f), Quaternion.Euler(0f, 0f, -18f), steel);
        }

        private static GameObject AddJackPumpPart(Transform parent, string partName, PrimitiveType primitive,
            Vector3 localPosition, Vector3 localScale, Quaternion localRotation, Material material)
        {
            var part = GameObject.CreatePrimitive(primitive);
            part.name = partName;
            part.transform.SetParent(parent, false);
            part.transform.localPosition = localPosition;
            part.transform.localRotation = localRotation;
            part.transform.localScale = localScale;
            var collider = part.GetComponent<Collider>();
            if (collider != null) Object.DestroyImmediate(collider);
            var renderer = part.GetComponent<Renderer>();
            if (renderer != null) renderer.sharedMaterial = material;
            return part;
        }

        private static void AppendSmeltingRecipe(string prefabPath, VoxelEngine.Crafting.SmeltingRecipe smRecipe, bool electric = false)
        {
            if (smRecipe == null) return;
            var prefab = AssetDatabase.LoadAssetAtPath<GameObject>(prefabPath);
            if (prefab == null) return;
            var contents = PrefabUtility.LoadPrefabContents(prefabPath);
            try
            {
                if (electric)
                {
                    var furn = contents.GetComponent<VoxelEngine.Crafting.ElectricFurnace>();
                    if (furn != null)
                    {
                        if (furn.knownRecipes == null) furn.knownRecipes = new List<VoxelEngine.Crafting.SmeltingRecipe>();
                        if (!furn.knownRecipes.Contains(smRecipe)) furn.knownRecipes.Add(smRecipe);
                    }
                }
                else
                {
                    var furn = contents.GetComponent<VoxelEngine.Crafting.Furnace>();
                    if (furn != null)
                    {
                        if (furn.knownRecipes == null) furn.knownRecipes = new List<VoxelEngine.Crafting.SmeltingRecipe>();
                        if (!furn.knownRecipes.Contains(smRecipe)) furn.knownRecipes.Add(smRecipe);
                    }
                }
                PrefabUtility.SaveAsPrefabAsset(contents, prefabPath);
            }
            finally { PrefabUtility.UnloadPrefabContents(contents); }
        }

        private static void AppendOilRefineryRecipes(GameObject prefab, List<VoxelEngine.Crafting.ProcessingRecipe> recipes)
        {
            if (prefab == null) return;
            string path = AssetDatabase.GetAssetPath(prefab);
            var contents = PrefabUtility.LoadPrefabContents(path);
            try
            {
                var ref0 = contents.GetComponent<VoxelEngine.Crafting.OilRefinery>();
                if (ref0 != null)
                {
                    if (ref0.knownRecipes == null) ref0.knownRecipes = new List<VoxelEngine.Crafting.ProcessingRecipe>();
                    foreach (var r in recipes)
                        if (r != null && !ref0.knownRecipes.Contains(r))
                            ref0.knownRecipes.Add(r);
                }
                PrefabUtility.SaveAsPrefabAsset(contents, path);
            }
            finally { PrefabUtility.UnloadPrefabContents(contents); }
        }

        private static void AppendChemicalPlantRecipes(GameObject prefab, List<VoxelEngine.Crafting.ProcessingRecipe> recipes)
        {
            if (prefab == null) return;
            string path = AssetDatabase.GetAssetPath(prefab);
            var contents = PrefabUtility.LoadPrefabContents(path);
            try
            {
                var cp = contents.GetComponent<VoxelEngine.Industrial.StationaryChemicalPlant>();
                if (cp != null)
                {
                    if (cp.knownRecipes == null) cp.knownRecipes = new List<VoxelEngine.Crafting.ProcessingRecipe>();
                    foreach (var r in recipes)
                        if (r != null && !cp.knownRecipes.Contains(r))
                            cp.knownRecipes.Add(r);
                }
                PrefabUtility.SaveAsPrefabAsset(contents, path);
            }
            finally { PrefabUtility.UnloadPrefabContents(contents); }
        }

        // ============================================================
        //  STEP 11 - SURVIVAL + INDUSTRIAL LOGISTICS CONTENT
        //  Fills in: Farming, Storage Network, Item Pipes, Quarry,
        //            Gas Processing, Nuclear Fission
        //  Connects to the research nodes already authored in Step 10.
        // ============================================================
        private void BuildSurvivalAndLogisticsContent()
        {
            // -------- Folders --------
            const string ROOT          = ASSET_ROOT + "/Survival";
            const string ITEMS         = ROOT + "/Items";
            const string FARM_PREFABS  = ROOT + "/FarmPrefabs";
            const string FARM_BLOCKS   = ROOT + "/FarmBlocks";
            const string FARM_CROPS    = ROOT + "/Crops";
            const string FARM_RECIPES  = ROOT + "/FarmRecipes";
            const string STORE_PREFABS = ROOT + "/StoragePrefabs";
            const string STORE_BLOCKS  = ROOT + "/StorageBlocks";
            const string STORE_ITEMS   = ROOT + "/StorageItems";
            const string STORE_RECIPES = ROOT + "/StorageRecipes";
            const string NUKE_PREFABS  = ROOT + "/NuclearPrefabs";
            const string NUKE_BLOCKS   = ROOT + "/NuclearBlocks";
            const string NUKE_ITEMS    = ROOT + "/NuclearItems";
            const string NUKE_RECIPES  = ROOT + "/NuclearRecipes";
            const string GAS_PREFABS   = ROOT + "/GasPrefabs";
            const string GAS_BLOCKS    = ROOT + "/GasBlocks";
            const string GAS_RECIPES   = ROOT + "/GasRecipes";
            const string MISC_PREFABS  = ROOT + "/MiscPrefabs";
            const string MISC_BLOCKS   = ROOT + "/MiscBlocks";
            const string MISC_RECIPES  = ROOT + "/MiscRecipes";
            const string MISC_ITEMS    = ROOT + "/MiscItems";

            foreach (var f in new[] {
                ROOT, ITEMS, FARM_PREFABS, FARM_BLOCKS, FARM_CROPS, FARM_RECIPES,
                STORE_PREFABS, STORE_BLOCKS, STORE_ITEMS, STORE_RECIPES,
                NUKE_PREFABS, NUKE_BLOCKS, NUKE_ITEMS, NUKE_RECIPES,
                GAS_PREFABS, GAS_BLOCKS, GAS_RECIPES,
                MISC_PREFABS, MISC_BLOCKS, MISC_RECIPES, MISC_ITEMS,
            }) EnsureFolder(f);

            // -------- Required existing items --------
            string craftItems = ASSET_ROOT + "/Items";
            string industrialItems = ASSET_ROOT + "/Industrial/Items";

            var stone        = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{craftItems}/Item_Stone.asset");
            var ice          = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{craftItems}/Item_Ice.asset");
            var coal         = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{craftItems}/Item_Coal.asset");
            var uraniumOre   = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{craftItems}/Item_Uranium.asset");
            var clay         = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{craftItems}/Item_Clay.asset");
            var woodLog      = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{craftItems}/Item_WoodLog.asset");
            var plank        = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{craftItems}/Item_WoodenPlank.asset");
            var ironIngot    = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{craftItems}/Item_IronIngot.asset");
            var copperIngot  = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{craftItems}/Item_CopperIngot.asset");
            var steelIngot   = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{craftItems}/Item_SteelIngot.asset");

            var ironPlate    = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{industrialItems}/Item_IronPlate.asset");
            var copperPlate  = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{industrialItems}/Item_CopperPlate.asset");
            var steelPlate   = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{industrialItems}/Item_SteelPlate.asset");
            var ironGear     = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{industrialItems}/Item_IronGear.asset");
            var copperWire   = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{industrialItems}/Item_CopperWire.asset");
            var circuit      = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{industrialItems}/Item_Circuit.asset");
            var advCircuit   = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{industrialItems}/Item_AdvCircuit.asset");
            var glass        = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{industrialItems}/Item_Glass.asset");
            var plastic      = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{industrialItems}/Item_Plastic.asset");

            var sciT1 = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ScienceItem>($"{craftItems}/Item_ScienceT1.asset");
            var sciT2 = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ScienceItem>($"{craftItems}/Item_ScienceT2.asset");
            var sciT3 = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ScienceItem>($"{craftItems}/Item_ScienceT3.asset");

            if (ironIngot == null || ironPlate == null || circuit == null || sciT1 == null)
            {
                EditorUtility.DisplayDialog("Voxel Engine",
                    "Run Steps 4 + 7 + 10 first — Step 11 expects the ingots / plates / circuits / science packs to exist.", "OK");
                return;
            }

            var registry = AssetDatabase.LoadAssetAtPath<VoxelEngine.Crafting.RecipeRegistry>($"{ASSET_ROOT}/RecipeRegistry.asset");
            if (registry == null) { EditorUtility.DisplayDialog("Voxel Engine", "Run Step 4 first.", "OK"); return; }

            const string researchFolder = ASSET_ROOT + "/Research";
            const string nodesFolder    = researchFolder + "/Nodes";
            var tree = AssetDatabase.LoadAssetAtPath<VoxelEngine.Research.ResearchTree>(researchFolder + "/ResearchTree.asset");
            if (tree == null) { EditorUtility.DisplayDialog("Voxel Engine", "Run Step 7 first.", "OK"); return; }

            // ============================================================
            //  Generic helpers  (local to Step 11 to keep things readable)
            // ============================================================
            VoxelEngine.Items.ResourceItem MakeRes(string folder, string assetName, string display, string desc, Color tint,
                VoxelEngine.Items.ResourceCategory cat, string uiCategory, int maxStack = 999, float fuelSeconds = 0f)
            {
                string path = $"{folder}/{assetName}.asset";
                var r = GetOrCreateAsset<VoxelEngine.Items.ResourceItem>(path);
                r.itemId = assetName.ToLower(); r.displayName = display; r.description = desc;
                r.iconTint = tint; r.maxStack = maxStack; r.massPerUnit = 1f;
                r.category = uiCategory; r.subcategory = cat; r.fuelSeconds = fuelSeconds;
                EditorUtility.SetDirty(r);
                return r;
            }

            VoxelEngine.Items.BlockItem MakeBlk(string folder, string assetName, string display, string desc, Color tint,
                GameObject prefab, string uiCategory, int hp = 200, int miningTier = 1, int maxStack = 50)
            {
                string path = $"{folder}/{assetName}.asset";
                var b = GetOrCreateAsset<VoxelEngine.Items.BlockItem>(path);
                b.itemId = assetName.ToLower(); b.displayName = display; b.description = desc;
                b.iconTint = tint; b.maxStack = maxStack; b.massPerUnit = 4f;
                b.placedPrefab = prefab; b.gridSize = Vector3Int.one;
                b.allowStacking = true; b.blockHealth = hp; b.miningTier = miningTier;
                b.category = uiCategory;
                EditorUtility.SetDirty(b);
                return b;
            }

            GameObject MakePref(string folder, string name, Color color, Vector3 scale, System.Action<GameObject> configure)
            {
                string path = $"{folder}/{name}.prefab";
                var root = new GameObject(name);
                var cube = GameObject.CreatePrimitive(PrimitiveType.Cube);
                cube.name = "Mesh";
                cube.transform.SetParent(root.transform, false);
                cube.transform.localScale = scale;
                cube.GetComponent<Renderer>().sharedMaterial = MakeColoredMat(folder, $"Mat_{name}", color);
                configure?.Invoke(root);
                var prefab = PrefabUtility.SaveAsPrefabAsset(root, path);
                Object.DestroyImmediate(root);
                return prefab;
            }

            // ════════════════════════════════════════════════════════════
            //  LIFE SUPPORT EQUIPMENT — helmet + oxygen tank foundation
            // ════════════════════════════════════════════════════════════
            var spaceHelmet = GetOrCreateAsset<VoxelEngine.Items.SpaceHelmetItem>($"{MISC_ITEMS}/Equip_SpaceHelmet.asset");
            spaceHelmet.itemId = "space_helmet";
            spaceHelmet.displayName = "Space Helmet";
            spaceHelmet.description = "Sealed helmet for underwater and vacuum life support. Equip with an Oxygen Tank to carry a larger oxygen reserve and slow oxygen drain.";
            spaceHelmet.iconTint = new Color(0.72f, 0.86f, 1.00f);
            spaceHelmet.maxStack = 1;
            spaceHelmet.massPerUnit = 6f;
            spaceHelmet.category = "Equipment";
            spaceHelmet.sealedHelmet = true;
            spaceHelmet.oxygenEfficiency = 0.85f;
            EditorUtility.SetDirty(spaceHelmet);

            var oxygenTank = GetOrCreateAsset<VoxelEngine.Items.OxygenTankItem>($"{MISC_ITEMS}/Equip_OxygenTank.asset");
            oxygenTank.itemId = "oxygen_tank";
            oxygenTank.displayName = "Oxygen Tank";
            oxygenTank.description = "Wearable oxygen reserve. Equip with a sealed Space Helmet to survive longer underwater and in vacuum; oxygen-efficiency armor upgrades further reduce drain.";
            oxygenTank.iconTint = new Color(0.42f, 0.75f, 1.00f);
            oxygenTank.maxStack = 1;
            oxygenTank.massPerUnit = 8f;
            oxygenTank.category = "Equipment";
            oxygenTank.bonusOxygen = 180f;
            oxygenTank.drainMultiplier = 0.55f;
            EditorUtility.SetDirty(oxygenTank);

            AddRecipe(MISC_RECIPES, "Recipe_SpaceHelmet", "Space Helmet", spaceHelmet, 1, VoxelEngine.Crafting.StationTier.Assembler, false,
                ((VoxelEngine.Items.ItemDefinition)steelPlate, 3), ((VoxelEngine.Items.ItemDefinition)glass, 2), ((VoxelEngine.Items.ItemDefinition)copperWire, 4));
            AddRecipe(MISC_RECIPES, "Recipe_OxygenTank", "Oxygen Tank", oxygenTank, 1, VoxelEngine.Crafting.StationTier.Assembler, false,
                ((VoxelEngine.Items.ItemDefinition)steelPlate, 4), ((VoxelEngine.Items.ItemDefinition)copperWire, 4), ((VoxelEngine.Items.ItemDefinition)circuit, 1));

            // ════════════════════════════════════════════════════════════
            //  FARMING — crops, seeds, foods, tools, blocks, recipes
            // ════════════════════════════════════════════════════════════

            // ── Tools (Hoe is just a ToolItem with "Other" type) ──
            string hoePath = $"{ITEMS}/Tool_Hoe.asset";
            var hoe = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ToolItem>(hoePath);
            if (hoe == null)
            {
                hoe = ScriptableObject.CreateInstance<VoxelEngine.Items.ToolItem>();
                AssetDatabase.CreateAsset(hoe, hoePath);
            }
            hoe.itemId        = "hoe";
            hoe.displayName   = "Hoe";
            hoe.description   = "Used in conjunction with Tilled Soil blocks. Future: right-click on dirt to till in-place.";
            hoe.toolType      = VoxelEngine.Items.ToolType.Other;
            hoe.miningTier    = 0;
            hoe.maxDurability = 250;
            hoe.strength      = 1f;
            hoe.fireRate      = 4f;
            hoe.brushRadius   = 0.5f;
            hoe.iconTint      = new Color(0.55f, 0.40f, 0.25f);
            hoe.maxStack      = 1;
            hoe.category      = "Tools";
            EditorUtility.SetDirty(hoe);

            // ── Foods (each crop yields a raw harvest item; cooking yields better food) ──
            var foodWheatRaw = ScriptableObject.CreateInstance<VoxelEngine.Farming.FoodItem>();
            foodWheatRaw.itemId = "wheat";  foodWheatRaw.displayName = "Wheat";  foodWheatRaw.description = "Raw wheat grain. Restores a little hunger when eaten raw. Bake into Bread for 3x the nutrition.";
            foodWheatRaw.iconTint = new Color(0.92f, 0.85f, 0.45f); foodWheatRaw.maxStack = 99; foodWheatRaw.category = "Food";
            foodWheatRaw.hungerRestore = 5f; foodWheatRaw.healthRestore = 0f; foodWheatRaw.staminaRestore = 0f;
            AssetDatabase.CreateAsset(foodWheatRaw, $"{ITEMS}/Food_Wheat.asset");

            var foodCornRaw = ScriptableObject.CreateInstance<VoxelEngine.Farming.FoodItem>();
            foodCornRaw.itemId = "corn"; foodCornRaw.displayName = "Corn"; foodCornRaw.description = "Sweet corn. Edible raw — feeds 8 hunger.";
            foodCornRaw.iconTint = new Color(0.95f, 0.82f, 0.20f); foodCornRaw.maxStack = 99; foodCornRaw.category = "Food";
            foodCornRaw.hungerRestore = 8f;
            AssetDatabase.CreateAsset(foodCornRaw, $"{ITEMS}/Food_Corn.asset");

            var foodCarrotRaw = ScriptableObject.CreateInstance<VoxelEngine.Farming.FoodItem>();
            foodCarrotRaw.itemId = "carrot"; foodCarrotRaw.displayName = "Carrot"; foodCarrotRaw.description = "Crunchy root vegetable. Feeds 10 hunger.";
            foodCarrotRaw.iconTint = new Color(0.95f, 0.55f, 0.20f); foodCarrotRaw.maxStack = 99; foodCarrotRaw.category = "Food";
            foodCarrotRaw.hungerRestore = 10f;
            AssetDatabase.CreateAsset(foodCarrotRaw, $"{ITEMS}/Food_Carrot.asset");

            var foodBread = ScriptableObject.CreateInstance<VoxelEngine.Farming.FoodItem>();
            foodBread.itemId = "bread"; foodBread.displayName = "Bread"; foodBread.description = "Baked from 3 wheat. Restores 25 hunger.";
            foodBread.iconTint = new Color(0.85f, 0.65f, 0.30f); foodBread.maxStack = 99; foodBread.category = "Food";
            foodBread.hungerRestore = 25f;
            AssetDatabase.CreateAsset(foodBread, $"{ITEMS}/Food_Bread.asset");

            var foodStew = ScriptableObject.CreateInstance<VoxelEngine.Farming.FoodItem>();
            foodStew.itemId = "stew"; foodStew.displayName = "Vegetable Stew"; foodStew.description = "Hearty stew from carrots + corn. Restores 35 hunger + 10 health.";
            foodStew.iconTint = new Color(0.85f, 0.40f, 0.20f); foodStew.maxStack = 99; foodStew.category = "Food";
            foodStew.hungerRestore = 35f; foodStew.healthRestore = 10f;
            AssetDatabase.CreateAsset(foodStew, $"{ITEMS}/Food_Stew.asset");

            // ── Seeds ──
            VoxelEngine.Farming.SeedItem MakeSeed(string assetName, string display, Color tint, string desc)
            {
                var s = ScriptableObject.CreateInstance<VoxelEngine.Farming.SeedItem>();
                s.itemId = assetName.ToLower(); s.displayName = display; s.description = desc;
                s.iconTint = tint; s.maxStack = 99; s.category = "Seeds";
                AssetDatabase.CreateAsset(s, $"{ITEMS}/{assetName}.asset");
                return s;
            }
            var seedWheat  = MakeSeed("Seed_Wheat",  "Wheat Seeds",  new Color(0.88f, 0.80f, 0.45f),
                "Plant on a Tilled Soil block. Grows in ~2 minutes when irrigated.");
            var seedCorn   = MakeSeed("Seed_Corn",   "Corn Seeds",   new Color(0.92f, 0.78f, 0.20f),
                "Plant on a Tilled Soil block. Grows in ~3 minutes when irrigated.");
            var seedCarrot = MakeSeed("Seed_Carrot", "Carrot Seeds", new Color(0.95f, 0.55f, 0.25f),
                "Plant on a Tilled Soil block. Grows in ~2 minutes when irrigated.");

            // ── Crop definitions (data) ──
            VoxelEngine.Farming.CropDefinition MakeCrop(string assetName, string display, float growthTime,
                float foodValue, VoxelEngine.Items.ItemDefinition harvest, int harvestAmount,
                VoxelEngine.Farming.SeedItem seed, int seedReturn = 1, bool requiresWater = true)
            {
                var c = ScriptableObject.CreateInstance<VoxelEngine.Farming.CropDefinition>();
                c.cropName = display; c.growthTime = growthTime; c.growthStages = 4;
                c.requiresWater = requiresWater; c.irrigatedSpeedMultiplier = 2f; c.droughtToleranceSec = 30f;
                c.harvestItem = harvest; c.harvestAmount = harvestAmount;
                c.seedItem = seed; c.seedReturnAmount = seedReturn;
                c.foodValue = foodValue;
                c.stageScales = new[] { 0.2f, 0.4f, 0.7f, 1.0f };
                AssetDatabase.CreateAsset(c, $"{FARM_CROPS}/{assetName}.asset");
                return c;
            }
            var cropWheat  = MakeCrop("Crop_Wheat",  "Wheat",  120f, 5f, foodWheatRaw,  3, seedWheat,  1);
            var cropCorn   = MakeCrop("Crop_Corn",   "Corn",   180f, 8f, foodCornRaw,   2, seedCorn,   1);
            var cropCarrot = MakeCrop("Crop_Carrot", "Carrot", 120f, 10f, foodCarrotRaw, 2, seedCarrot, 1);

            // Hook each seed back to its crop.
            seedWheat.crop = cropWheat;   EditorUtility.SetDirty(seedWheat);
            seedCorn.crop  = cropCorn;    EditorUtility.SetDirty(seedCorn);
            seedCarrot.crop = cropCarrot; EditorUtility.SetDirty(seedCarrot);

            // ── Tilled Soil (FarmPlot) prefab ──
            var tilledPrefab = MakePref(FARM_PREFABS, "TilledSoil",
                new Color(0.30f, 0.20f, 0.12f), new Vector3(1f, 0.15f, 1f),
                root => { root.AddComponent<VoxelEngine.Farming.FarmPlot>(); });

            var blockTilled = MakeBlk(FARM_BLOCKS, "Block_TilledSoil", "Tilled Soil",
                "A patch of farmable dirt. RMB with a Seed item to plant. RMB again when fully grown to harvest.",
                new Color(0.30f, 0.20f, 0.12f), tilledPrefab, "Farming", hp: 50);

            // ── Sprinkler prefab ──
            var sprinklerPrefab = MakePref(FARM_PREFABS, "Sprinkler",
                new Color(0.40f, 0.65f, 0.85f), new Vector3(0.4f, 0.6f, 0.4f),
                root =>
                {
                    var pc = root.AddComponent<VoxelEngine.Power.PowerConsumer>();
                    pc.wattsPerSecond = 20f; pc.connectRadius = 1.6f;
                    var s = root.AddComponent<VoxelEngine.Farming.Sprinkler>();
                    s.radius = 8f; s.requiresWaterConnection = true; s.waterConsumption = 2f;
                });
            var blockSprinkler = MakeBlk(FARM_BLOCKS, "Block_Sprinkler", "Sprinkler",
                "Powered automatic irrigation. Irrigates every Tilled Soil within 8 m. ~20 W and needs water pipes connected.",
                new Color(0.40f, 0.65f, 0.85f), sprinklerPrefab, "Farming", hp: 200);

            // ── Harvester prefab ──
            var harvesterPrefab = MakePref(FARM_PREFABS, "Harvester",
                new Color(0.55f, 0.45f, 0.20f), new Vector3(1.2f, 1.0f, 1.2f),
                root =>
                {
                    var pc = root.AddComponent<VoxelEngine.Power.PowerConsumer>();
                    pc.wattsPerSecond = 40f; pc.connectRadius = 1.6f;
                    var h = root.AddComponent<VoxelEngine.Farming.Harvester>();
                    h.scanRadius = 8f; h.scanInterval = 2f; h.autoReplant = true; h.outputSlots = 6;
                });
            var blockHarvester = MakeBlk(FARM_BLOCKS, "Block_Harvester", "Harvester",
                "Automated crop picker. Scans 8 m radius for mature Tilled Soils, harvests them, optionally replants. Push outputs through item pipes. ~40 W.",
                new Color(0.55f, 0.45f, 0.20f), harvesterPrefab, "Farming", hp: 400);

            // ── Farming recipes ──
            AddRecipe(FARM_RECIPES, "Recipe_Hoe", "Hoe", hoe, 1, VoxelEngine.Crafting.StationTier.None, false, ((VoxelEngine.Items.ItemDefinition)woodLog, 2), ((VoxelEngine.Items.ItemDefinition)ironIngot, 1));
            AddRecipe(FARM_RECIPES, "Recipe_TilledSoil", "Tilled Soil", blockTilled, 1, VoxelEngine.Crafting.StationTier.None, false, ((VoxelEngine.Items.ItemDefinition)clay, 1));
            AddRecipe(FARM_RECIPES, "Recipe_Sprinkler", "Sprinkler", blockSprinkler, 1, VoxelEngine.Crafting.StationTier.CraftingBench, false, ((VoxelEngine.Items.ItemDefinition)ironPlate, 2), ((VoxelEngine.Items.ItemDefinition)copperWire, 4));
            AddRecipe(FARM_RECIPES, "Recipe_Harvester", "Harvester", blockHarvester, 1, VoxelEngine.Crafting.StationTier.Assembler, false, ((VoxelEngine.Items.ItemDefinition)ironPlate, 4), ((VoxelEngine.Items.ItemDefinition)ironGear, 4), ((VoxelEngine.Items.ItemDefinition)circuit, 1));

            // ── Static Cryobed (offline-survival foundation) ──
            var cryobedPrefab = MakePref(STORE_PREFABS, "Cryobed_Static",
                new Color(0.28f, 0.62f, 0.82f), new Vector3(2.1f, 0.62f, 0.95f),
                root =>
                {
                    var cb = root.AddComponent<VoxelEngine.Building.Cryobed>();
                    cb.displayName = "Cryobed";
                    cb.oxygenRequired = true;
                    cb.poweredRequired = true;
                    cb.idleWatts = 35f;
                    var power = root.AddComponent<VoxelEngine.Power.PowerConsumer>();
                    power.wattsPerSecond = 35f;
                    power.connectRadius = 1.8f;
                    var light = new GameObject("Generated_StatusLight");
                    light.transform.SetParent(root.transform, false);
                    light.transform.localPosition = new Vector3(0f, 0.42f, -0.48f);
                    var l = light.AddComponent<Light>();
                    l.type = LightType.Point; l.color = new Color(0.45f, 0.85f, 1f); l.intensity = 1.2f; l.range = 3f;
                });
            var blockCryobed = MakeBlk(STORE_BLOCKS, "Block_Cryobed", "Cryobed",
                "Sealed respawn/offline-survival bed foundation. Later life-support passes will require oxygen and power to keep offline Crusaders safe.",
                new Color(0.45f, 0.85f, 1f), cryobedPrefab, "Life Support", hp: 450, miningTier: 2);
            AddRecipe(STORE_RECIPES, "Recipe_Cryobed", "Cryobed", blockCryobed, 1, VoxelEngine.Crafting.StationTier.Assembler, false,
                ((VoxelEngine.Items.ItemDefinition)steelPlate, 6), ((VoxelEngine.Items.ItemDefinition)glass, 4), ((VoxelEngine.Items.ItemDefinition)circuit, 2), ((VoxelEngine.Items.ItemDefinition)copperWire, 6));

            // ── Biomass (compressed organic matter for Biofarm) ──
            var biomass = MakeRes(MISC_ITEMS, "Item_Biomass", "Biomass",
                "Compressed organic matter from crops (wheat/corn/carrot/seed). Fuel for the Biofarm Oxygen Garden. 1 biomass = 45s of slow O₂ production.",
                new Color(0.35f, 0.65f, 0.30f), VoxelEngine.Items.ResourceCategory.Misc, "Farming", maxStack: 200);
            AddRecipe(FARM_RECIPES, "Recipe_Biomass", "Biomass x4", biomass, 4, VoxelEngine.Crafting.StationTier.CraftingBench, false,
                ((VoxelEngine.Items.ItemDefinition)foodWheatRaw, 2), ((VoxelEngine.Items.ItemDefinition)foodCornRaw, 1));

            // ── Static Biofarm (passive oxygen garden — 11.5) ──
            var biofarmPrefab = MakePref(STORE_PREFABS, "Biofarm_Static",
                new Color(0.32f, 0.72f, 0.42f), new Vector3(2.4f, 1.1f, 1.8f),
                root =>
                {
                    var bf = root.AddComponent<VoxelEngine.Building.Biofarm>();
                    bf.powerDraw = 65f;
                    bf.waterConsumptionLps = 0.18f;
                    bf.oxygenPerSecond = 0.55f;
                    bf.secondsPerBiomass = 45f;
                    bf.bufferCapacity = 260f;
                    var power = root.AddComponent<VoxelEngine.Power.PowerConsumer>();
                    power.wattsPerSecond = 65f;
                    power.connectRadius = 2.0f;
                    // Small leafy glow
                    var light = new GameObject("Generated_GrowLight");
                    light.transform.SetParent(root.transform, false);
                    light.transform.localPosition = new Vector3(0f, 0.65f, 0f);
                    var l = light.AddComponent<Light>();
                    l.type = LightType.Point; l.color = new Color(0.35f, 0.85f, 0.45f); l.intensity = 0.9f; l.range = 3.5f;
                });
            var blockBiofarm = MakeBlk(STORE_BLOCKS, "Block_Biofarm", "Biofarm",
                "Passive oxygen garden. Converts water + biomass (wheat/corn/carrot/biomass) into piped O₂ for tanks & cryobeds. Needs power, water pipes from a tank, and biomass via item pipes. Slower than electrolyser but renewable & ideal for offline survival.",
                new Color(0.35f, 0.85f, 0.45f), biofarmPrefab, "Life Support", hp: 380, miningTier: 2);
            AddRecipe(STORE_RECIPES, "Recipe_Biofarm", "Biofarm", blockBiofarm, 1, VoxelEngine.Crafting.StationTier.Assembler, false,
                ((VoxelEngine.Items.ItemDefinition)steelPlate, 8), ((VoxelEngine.Items.ItemDefinition)glass, 6), ((VoxelEngine.Items.ItemDefinition)circuit, 3), ((VoxelEngine.Items.ItemDefinition)copperWire, 6), ((VoxelEngine.Items.ItemDefinition)plastic, 2));

            // ── Ruins & Blueprint Data Cores (4.9.0 — exploration rewards) ──
            // Blueprint cores are FOUND in ruins, not crafted. Unlock wind turbine sub-recipes etc.
            VoxelEngine.Items.BlueprintDataCoreItem MakeBlueprint(string assetName, string display, string targetRecipeAsset, string desc, Color tint)
            {
                string path = $"{MISC_ITEMS}/{assetName}.asset";
                var bp = GetOrCreateAsset<VoxelEngine.Items.BlueprintDataCoreItem>(path);
                bp.itemId = assetName.ToLower();
                bp.displayName = display;
                bp.description = desc;
                bp.iconTint = tint;
                bp.maxStack = 1;
                bp.massPerUnit = 0.5f;
                bp.category = "Blueprints";
                bp.subcategory = VoxelEngine.Items.ResourceCategory.Component;
                bp.targetDisplayName = display.Replace("Damaged Blueprint: ", "");
                bp.targetRecipeAssetName = targetRecipeAsset;
                // Try to resolve targetRecipe asset for direct reference
                var rec = FindRecipeByName(targetRecipeAsset);
                if (rec != null) bp.targetRecipe = rec;
                EditorUtility.SetDirty(bp);
                return bp;
            }

            var bpNacelle = MakeBlueprint("Item_Blueprint_Nacelle_t90", "Damaged Blueprint: Nacelle t90",
                "Recipe_t90_Nacelle", "Rusted data core containing wind turbine nacelle schematics. Right-click to restore. Found in collapsed warehouses.",
                new Color(0.85f, 0.65f, 0.25f));
            var bpGearbox = MakeBlueprint("Item_Blueprint_Gearbox_t90", "Damaged Blueprint: Gearbox t90",
                "Recipe_t90_Gearbox", "Corrupted gearbox blueprint. Right-click to restore. Found in derelict factories.",
                new Color(0.75f, 0.55f, 0.20f));
            var bpBlade = MakeBlueprint("Item_Blueprint_Blade_t90", "Damaged Blueprint: Blade t90",
                "Recipe_t90_Blade", "Wind turbine blade blueprint, partially overgrown. Right-click to restore.",
                new Color(0.80f, 0.70f, 0.30f));
            var bpTower = MakeBlueprint("Item_Blueprint_Tower_t90", "Damaged Blueprint: Tower t90",
                "Recipe_t90_Tower", "Tower segment blueprint from ruined outpost. Right-click to restore.",
                new Color(0.70f, 0.60f, 0.25f));

            // Ruin prefabs — PREMIUM: realistic ruined crusader bases using real building blocks (walls, foundations)
            // that are mineable for resources, with rusted premium materials, collapsed sections, overgrowth.

            // Ruin prefabs — PREMIUM: realistic ruined crusader bases using real building blocks (walls, foundations)
            // that are mineable for resources, with rusted premium materials, collapsed sections, overgrowth.
            // FIXES from user feedback (image.png):
            // - Walls were scattered, not together → now exact module grid (3.75m), no random pos offset for base, only slight rotation tilt for ruined feel
            // - Chest invisible but lootable → now visible chest mesh + glow light
            // - Said steel/iron but looked wood → now uses steel prefabs if available and rusted metallic mats (0.62,0.32,0.18 orange rust, not wood brown)
            // - Too many spawns → now rarer (0.002, 0.0015, 0.0018) and easy numbers to tweak
            GameObject MakeRuinPrefab(string name, Color rustColor, Vector3 size, int minComp, int maxComp)
            {
                string prefabPath = $"{MISC_PREFABS}/{name}.prefab";

                // ── Non-destructive: preserve any hand-tuned loot config / HP from a previous run ──
                ItemDefinition[] keepComponents = null;
                ItemDefinition[] keepFuel = null;
                BlueprintDataCoreItem[] keepBlueprints = null;
                int keepMinComp = minComp;
                int keepMaxComp = maxComp;
                string keepRuinName = null;
                {
                    var existingPrefab = AssetDatabase.LoadAssetAtPath<GameObject>(prefabPath);
                    if (existingPrefab != null)
                    {
                        var prevChest = existingPrefab.GetComponent<VoxelEngine.Exploration.RuinChest>();
                        if (prevChest != null)
                        {
                            if (prevChest.possibleComponents != null && prevChest.possibleComponents.Length > 0) keepComponents = prevChest.possibleComponents;
                            if (prevChest.possibleFuel != null && prevChest.possibleFuel.Length > 0) keepFuel = prevChest.possibleFuel;
                            if (prevChest.possibleBlueprints != null && prevChest.possibleBlueprints.Length > 0) keepBlueprints = prevChest.possibleBlueprints;
                            if (prevChest.minComponents > 0) keepMinComp = prevChest.minComponents;
                            if (prevChest.maxComponents > 0) keepMaxComp = prevChest.maxComponents;
                            if (!string.IsNullOrEmpty(prevChest.ruinName)) keepRuinName = prevChest.ruinName;
                        }
                    }
                }

                var root = new GameObject(name);
                var salvageStone = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{ITEM_FOLDER}/Item_Stone.asset");
                var salvageMetal = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{ITEM_FOLDER}/Item_IronIngot.asset");
                var salvageWood = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{ITEM_FOLDER}/Item_WoodLog.asset");
                if (root == null) { Debug.LogError($"[Ruin] Failed to create root GameObject for {name}"); return null; }

                // ── Derive distinct architectural styles from the ruin name ──
                bool   isFactory       = name.Contains("Factory");
                bool   isBunker        = name.Contains("Bunker");
                int    extent          = isFactory ? 2 : 1;                 // 5×5 grand fortress vs 3×3 outpost
                float  module          = 3.75f;
                float  wallHeight      = isBunker ? module * 0.62f : module; // bunker = squat, thick & fortified
                bool   hasBattlements  = !isBunker;                          // bunkers get a flat reinforced lip, not crenellations
                float  wallThick       = isBunker ? 0.55f : 0.30f;
                float  pillarW         = module * 0.52f;
                float  deckTopY        = 0.62f;
                float  W               = extent * module;
                float  footW           = (extent * 2 + 1) * module;
                // (Root is a plain folder — colliders are per-block; the lootable chest is the visible child inside.)

                // ══════════ PREMIUM PROCEDURAL MATERIALS ══════════
                // Textures are shared across all 3 ruins for GPU batching; per-ruin rust tints come from _BaseColor.
                Texture2D GetRuinTex(string texName, int style)
                {
                    string texPath = $"{MISC_PREFABS}/{texName}.asset";
                    var existing = AssetDatabase.LoadAssetAtPath<Texture2D>(texPath);
                    if (existing != null) return existing;
                    const int size = 128;
                    var texture = new Texture2D(size, size, TextureFormat.RGBA32, false)
                    {
                        name = texName, wrapMode = TextureWrapMode.Repeat, filterMode = FilterMode.Bilinear
                    };
                    var px = new Color[size * size];
                    for (int y = 0; y < size; y++)
                    for (int x = 0; x < size; x++)
                    {
                        float nx = x / (float)size, ny = y / (float)size;
                        float n = Mathf.PerlinNoise(nx * 8f + style * 4.7f, ny * 8f + style * 2.3f) - 0.5f;
                        float pat = n;
                        switch (style)
                        {
                            case 0: // rusted iron plating — vertical corrosion streaks, panel seams, rivets
                                pat = n * 0.30f + Mathf.Sin(ny * 110f + n * 3f) * 0.045f;
                                if (x % 48 < 2 || y % 48 < 2) pat -= 0.13f;
                                int rx = x % 48, ry = y % 48;
                                if ((rx < 4 && ry < 4) || (rx > 44 && ry > 44) || (rx < 4 && ry > 44) || (rx > 44 && ry < 4)) pat += 0.15f;
                                break;
                            case 1: // weathered crusader stone / concrete — mottled with dark fracture lines
                                pat = n * 0.50f + Mathf.PerlinNoise(nx * 22f, ny * 22f) * 0.20f - 0.10f;
                                if (Mathf.PerlinNoise(nx * 4f + 5f, ny * 4f + 5f) < 0.34f) pat -= 0.20f;
                                break;
                            case 2: // moss / overgrowth — clumpy with bare patches
                                pat = (Mathf.PerlinNoise(nx * 10f, ny * 10f) - 0.5f) * 0.6f;
                                if (Mathf.PerlinNoise(nx * 5f, ny * 5f) < 0.42f) pat -= 0.40f;
                                break;
                            case 3: // rotted timber — grain + plank gaps
                                pat = n * 0.18f + Mathf.Sin((ny * 18f + n * 3f) * Mathf.PI) * 0.10f;
                                if (x % 42 < 1) pat -= 0.14f;
                                break;
                            default: // faded cloth banner
                                pat = n * 0.10f - 0.02f;
                                if (y % 14 < 1) pat -= 0.06f;
                                break;
                        }
                        Color c = Color.white * (1f + pat * 0.5f); // neutral greyscale; tint comes from the material
                        c.a = 1f;
                        px[y * size + x] = c;
                    }
                    texture.SetPixels(px);
                    texture.Apply(false, false);
                    AssetDatabase.CreateAsset(texture, texPath);
                    return texture;
                }

                Material MakeRuinMat(string matName, Texture2D tex, Color tint, float metallic, float smoothness)
                {
                    string path = $"{MISC_PREFABS}/{matName}.mat";
                    var existing = AssetDatabase.LoadAssetAtPath<Material>(path);
                    // Upgrade legacy flat materials (no base texture) once; preserve textured mats on later runs.
                    bool isLegacyFlat = existing != null
                        && existing.GetTexture("_BaseMap") == null
                        && existing.GetTexture("_MainTex") == null;
                    if (existing != null && !isLegacyFlat) return existing;
                    if (isLegacyFlat) AssetDatabase.DeleteAsset(path);

                    var sh = Shader.Find("Universal Render Pipeline/Lit") ?? Shader.Find("Standard");
                    var mat = new Material(sh) { name = matName, enableInstancing = true };
                    if (mat.HasProperty("_BaseColor")) mat.SetColor("_BaseColor", tint);
                    else mat.color = tint;
                    if (mat.HasProperty("_BaseMap")) mat.SetTexture("_BaseMap", tex);
                    if (mat.HasProperty("_MainTex")) mat.SetTexture("_MainTex", tex);
                    if (mat.HasProperty("_Metallic")) mat.SetFloat("_Metallic", metallic);
                    if (mat.HasProperty("_Smoothness")) mat.SetFloat("_Smoothness", smoothness);
                    AssetDatabase.CreateAsset(mat, path);
                    return mat;
                }

                string shortName = name.Replace("Ruin_", "");
                var texRust  = GetRuinTex("Tex_Ruin_RustPlate", 0);
                var texStone = GetRuinTex("Tex_Ruin_Stone", 1);
                var texMoss  = GetRuinTex("Tex_Ruin_Moss", 2);
                var texWood  = GetRuinTex("Tex_Ruin_Wood", 3);
                var texCloth = GetRuinTex("Tex_Ruin_Cloth", 4);

                Color rustMain  = rustColor;
                Color rustDark  = rustColor * 0.62f;  rustDark.a  = 1f;
                Color rustLight = rustColor * 1.28f;  rustLight.a = 1f;

                var matRustMain  = MakeRuinMat($"Mat_Ruin_{shortName}_RustMain",  texRust,  rustMain,  0.82f, 0.34f);
                var matRustDark  = MakeRuinMat($"Mat_Ruin_{shortName}_RustDark",  texRust,  rustDark,  0.86f, 0.24f);
                var matRustLight = MakeRuinMat($"Mat_Ruin_{shortName}_RustLight", texRust,  rustLight, 0.70f, 0.40f);
                var matStone     = MakeRuinMat("Mat_Ruin_StoneWeathered", texStone, new Color(0.52f, 0.50f, 0.47f), 0.00f, 0.12f);
                var matStoneDark = MakeRuinMat("Mat_Ruin_StoneDark",       texStone, new Color(0.40f, 0.39f, 0.37f), 0.00f, 0.10f);
                var matMoss      = MakeRuinMat("Mat_Ruin_MossOvergrowth",  texMoss,  new Color(0.30f, 0.42f, 0.24f), 0.00f, 0.18f);
                var matWood      = MakeRuinMat("Mat_Ruin_RotWood",         texWood,  new Color(0.30f, 0.20f, 0.12f), 0.00f, 0.22f);
                var matBanner    = MakeRuinMat("Mat_Ruin_BannerFaded",     texCloth, new Color(0.86f, 0.82f, 0.72f), 0.00f, 0.30f);
                var matChest     = MakeRuinMat("Mat_Ruin_ChestIron",       texRust,  new Color(0.20f, 0.20f, 0.22f), 0.90f, 0.30f);
                var matChestTrim = MakeRuinMat("Mat_Ruin_ChestIronTrim",   texRust,  new Color(0.78f, 0.56f, 0.24f), 0.92f, 0.45f);

                // ── Block helpers ──
                GameObject AddBlock(string childName, Vector3 localPos, Vector3 localScale, Material mat, int hp, Quaternion rot)
                {
                    var go = GameObject.CreatePrimitive(PrimitiveType.Cube);
                    go.name = childName;
                    go.transform.SetParent(root.transform, false);
                    go.transform.localPosition = localPos;
                    go.transform.localRotation = rot;
                    go.transform.localScale = localScale;
                    if (mat != null) { var r = go.GetComponent<Renderer>(); if (r != null) r.sharedMaterial = mat; }
                    var pb = go.GetComponent<VoxelEngine.Building.PlacedBlock>();
                    if (pb == null) pb = go.AddComponent<VoxelEngine.Building.PlacedBlock>();
                    pb.Hp = Mathf.Max(10, hp);
                    if (salvageStone != null || salvageMetal != null)
                    {
                        var rd = go.AddComponent<VoxelEngine.Exploration.RuinBlockDrop>();
                        rd.salvage = (mat == matStone || mat == matStoneDark) ? salvageStone : salvageMetal;
                    }
                    return go;
                }

                GameObject AddDecor(string childName, Vector3 localPos, Vector3 localScale, Material mat, Quaternion rot)
                {
                    var go = GameObject.CreatePrimitive(PrimitiveType.Cube);
                    go.name = childName;
                    go.transform.SetParent(root.transform, false);
                    go.transform.localPosition = localPos;
                    go.transform.localRotation = rot;
                    go.transform.localScale = localScale;
                    if (mat != null) { var r = go.GetComponent<Renderer>(); if (r != null) r.sharedMaterial = mat; }
                    var col = go.GetComponent<Collider>();
                    if (col != null) UnityEngine.Object.DestroyImmediate(col);
                    return go;
                }

                var wallMats = new[] { matRustMain, matRustDark, matRustLight };
                Material WallMat() => wallMats[UnityEngine.Random.Range(0, wallMats.Length)];

                // ══════════ FOUNDATION: stone plinth + paved deck ══════════
                AddBlock("Foundation_Plinth", new Vector3(0f, 0.25f, 0f),
                    new Vector3(footW + 0.9f, 0.5f, footW + 0.9f), matStoneDark, 420, Quaternion.identity);
                AddBlock("Foundation_Deck", new Vector3(0f, 0.56f, 0f),
                    new Vector3(footW, 0.12f, footW), matStone, 380, Quaternion.identity);
                AddDecor("Foundation_Moss", new Vector3(-footW * 0.34f, deckTopY + 0.0f, -footW * 0.34f),
                    new Vector3(footW * 0.42f, 0.05f, footW * 0.42f), matMoss, Quaternion.identity);
                AddDecor("Foundation_Moss2", new Vector3(footW * 0.30f, deckTopY + 0.0f, footW * 0.32f),
                    new Vector3(footW * 0.30f, 0.05f, footW * 0.30f), matMoss, Quaternion.Euler(0f, 35f, 0f));

                // ══════════ CORNER PILLARS (quoins / tower bases) ══════════
                float cornerH = wallHeight * (hasBattlements ? 1.18f : 1.0f);
                float cornerY = deckTopY + cornerH * 0.5f;
                float[] signs = { -1f, 1f };
                foreach (float sx in signs)
                foreach (float sz in signs)
                    AddBlock($"Pillar_{(sx<0?"W":"E")}{(sz<0?"S":"N")}",
                        new Vector3(sx * W, cornerY, sz * W),
                        new Vector3(pillarW, cornerH, pillarW),
                        UnityEngine.Random.value < 0.5f ? matStone : matStoneDark, 360, Quaternion.identity);

                // ══════════ PERIMETER WALLS ══════════
                float wallY = deckTopY + wallHeight * 0.5f;

                void WallPanel(string label, float x, float z, bool alongX, bool ruined)
                {
                    Vector3 full = alongX ? new Vector3(module * 0.99f, wallHeight, wallThick) : new Vector3(wallThick, wallHeight, module * 0.99f);
                    if (ruined)
                    {
                        Vector3 sill = alongX ? new Vector3(module * 0.99f, wallHeight * 0.34f, wallThick) : new Vector3(wallThick, wallHeight * 0.34f, module * 0.99f);
                        AddBlock($"Sill_{label}", new Vector3(x, deckTopY + wallHeight * 0.17f, z), sill, matRustDark, 160, Quaternion.identity);
                        return;
                    }
                    AddBlock($"Wall_{label}", new Vector3(x, wallY, z), full, WallMat(), 280, Quaternion.identity);
                }

                // North & South walls (North center is reserved for the gateway)
                for (int xi = -extent; xi <= extent; xi++)
                {
                    bool gatewayGap = (xi == 0);
                    if (!gatewayGap)
                        WallPanel($"N{xi}", xi * module, W, true, UnityEngine.Random.value < 0.13f);
                    bool collapsed = isFactory && (xi >= -1 && xi <= 0);
                    if (!collapsed)
                        WallPanel($"S{xi}", xi * module, -W, true, UnityEngine.Random.value < 0.13f);
                }
                // East & West walls (skip corners — quoins live there)
                for (int zi = -extent + 1; zi <= extent - 1; zi++)
                {
                    WallPanel($"E{zi}", W, zi * module, false, UnityEngine.Random.value < 0.13f);
                    WallPanel($"W{zi}", -W, zi * module, false, UnityEngine.Random.value < 0.13f);
                }

                // ══════════ FRAMED GATEWAY (crusader portal on the North face) ══════════
                {
                    float postOff = module * 0.32f;
                    AddBlock("DoorPost_L", new Vector3(-postOff, wallY, W), new Vector3(wallThick * 1.4f, wallHeight, wallThick * 1.4f), matStoneDark, 320, Quaternion.identity);
                    AddBlock("DoorPost_R", new Vector3( postOff, wallY, W), new Vector3(wallThick * 1.4f, wallHeight, wallThick * 1.4f), matStoneDark, 320, Quaternion.identity);
                    AddBlock("DoorLintel", new Vector3(0f, deckTopY + wallHeight * 0.92f, W), new Vector3(postOff * 2f + wallThick * 1.4f, wallHeight * 0.20f, wallThick * 1.5f), matRustMain, 280, Quaternion.identity);
                    AddDecor("DoorKeystone", new Vector3(0f, deckTopY + wallHeight * 0.96f, W + wallThick * 0.35f), new Vector3(wallThick * 0.9f, wallHeight * 0.14f, 0.06f), matChestTrim, Quaternion.identity);
                }

                // ══════════ BATTLEMENTS + CORNER TOWER CAPS ══════════
                if (hasBattlements)
                {
                    float merlonH = 0.95f;
                    float merlonY = deckTopY + wallHeight + merlonH * 0.5f;
                    float merlonW = module * 0.46f;

                    void Merlon(string label, float x, float z, bool alongX)
                    {
                        Vector3 full  = alongX ? new Vector3(merlonW, merlonH, wallThick * 1.4f) : new Vector3(wallThick * 1.4f, merlonH, merlonW);
                        float roll = UnityEngine.Random.value;
                        if (roll < 0.20f) return;                                              // missing merlon = open crenel (ruined)
                        if (roll < 0.34f)
                        {
                            Vector3 half = alongX ? new Vector3(merlonW, merlonH * 0.5f, wallThick * 1.4f) : new Vector3(wallThick * 1.4f, merlonH * 0.5f, merlonW);
                            AddBlock($"MerlonHalf_{label}", new Vector3(x, merlonY - merlonH * 0.25f, z), half, matRustDark, 120, Quaternion.identity);
                            return;
                        }
                        AddBlock($"Merlon_{label}", new Vector3(x, merlonY, z), full, WallMat(), 200, Quaternion.identity);
                    }

                    for (int xi = -extent; xi <= extent; xi++)
                    {
                        if (xi == 0) continue; // gateway stays open
                        if (((xi + 1000) & 1) == 0) Merlon($"N{xi}", xi * module, W, true);
                        if (((xi + 1001) & 1) == 0) Merlon($"S{xi}", xi * module, -W, true);
                    }
                    for (int zi = -extent + 1; zi <= extent - 1; zi++)
                    {
                        if (((zi + 1000) & 1) == 0) Merlon($"E{zi}", W, zi * module, false);
                        if (((zi + 1001) & 1) == 0) Merlon($"W{zi}", -W, zi * module, false);
                    }
                    // Iron corbel band running under the battlements (unifying crusader motif)
                    AddDecor("Corbel_N", new Vector3(0f, deckTopY + wallHeight + 0.06f, W), new Vector3(footW, 0.12f, wallThick * 1.5f), matRustDark, Quaternion.identity);
                    AddDecor("Corbel_S", new Vector3(0f, deckTopY + wallHeight + 0.06f, -W), new Vector3(footW, 0.12f, wallThick * 1.5f), matRustDark, Quaternion.identity);
                    AddDecor("Corbel_E", new Vector3(W, deckTopY + wallHeight + 0.06f, 0f), new Vector3(wallThick * 1.5f, 0.12f, footW), matRustDark, Quaternion.identity);
                    AddDecor("Corbel_W", new Vector3(-W, deckTopY + wallHeight + 0.06f, 0f), new Vector3(wallThick * 1.5f, 0.12f, footW), matRustDark, Quaternion.identity);

                    // Tower caps capping the corner quoins
                    foreach (float sx in signs)
                    foreach (float sz in signs)
                        AddBlock($"TowerCap_{(sx<0?"W":"E")}{(sz<0?"S":"N")}",
                            new Vector3(sx * W, deckTopY + cornerH + 0.5f, sz * W),
                            new Vector3(pillarW * 1.08f, 1.0f, pillarW * 1.08f), matStoneDark, 240, Quaternion.identity);
                }
                else
                {
                    // Bunker: flat reinforced roof lip instead of crenellations
                    AddDecor("BunkerLip_N", new Vector3(0f, deckTopY + wallHeight + 0.02f, W), new Vector3(footW, 0.16f, wallThick * 1.8f), matRustDark, Quaternion.identity);
                    AddDecor("BunkerLip_S", new Vector3(0f, deckTopY + wallHeight + 0.02f, -W), new Vector3(footW, 0.16f, wallThick * 1.8f), matRustDark, Quaternion.identity);
                    AddDecor("BunkerLip_E", new Vector3(W, deckTopY + wallHeight + 0.02f, 0f), new Vector3(wallThick * 1.8f, 0.16f, footW), matRustDark, Quaternion.identity);
                    AddDecor("BunkerLip_W", new Vector3(-W, deckTopY + wallHeight + 0.02f, 0f), new Vector3(wallThick * 1.8f, 0.16f, footW), matRustDark, Quaternion.identity);
                    // Bunker also gets a flat roof slab for the squat fortress silhouette
                    AddBlock("BunkerRoof", new Vector3(0f, deckTopY + wallHeight + 0.18f, 0f), new Vector3(footW * 0.92f, 0.2f, footW * 0.92f), matRustMain, 280, Quaternion.identity);
                }

                // ══════════ INTERIOR: broken columns (ruined chapel/cathedral feel) ══════════
                {
                    float colR = extent <= 1 ? module * 0.5f : module;
                    float colH = wallHeight * 0.82f;
                    int spot = 0;
                    foreach (float cx in new float[] { -colR, colR })
                    foreach (float cz in new float[] { -colR, colR })
                    {
                        bool standing = UnityEngine.Random.value < 0.55f;
                        if (standing)
                        {
                            AddBlock($"ColBase_{spot}", new Vector3(cx, deckTopY + 0.1f, cz), new Vector3(0.62f, 0.2f, 0.62f), matStoneDark, 220, Quaternion.identity);
                            AddBlock($"ColShaft_{spot}", new Vector3(cx, deckTopY + 0.2f + colH * 0.5f, cz), new Vector3(0.46f, colH, 0.46f), matStone, 200, Quaternion.identity);
                            AddDecor($"ColCap_{spot}", new Vector3(cx, deckTopY + 0.2f + colH + 0.1f, cz), new Vector3(0.52f, 0.22f, 0.52f), matStone,
                                Quaternion.Euler(UnityEngine.Random.Range(-8f, 8f), UnityEngine.Random.Range(0f, 90f), UnityEngine.Random.Range(-8f, 8f)));
                        }
                        else
                        {
                            // Fallen column lying on the deck, rolled outward from its base
                            Vector3 fall = new Vector3(cx + (cx < 0 ? -0.7f : 0.7f), deckTopY + 0.3f, cz + (cz < 0 ? -0.7f : 0.7f));
                            AddBlock($"ColFallen_{spot}", fall, new Vector3(0.46f, 0.46f, colH), matStone, 200,
                                Quaternion.Euler(0f, UnityEngine.Random.Range(0f, 360f), 90f));
                            AddBlock($"ColStub_{spot}", new Vector3(cx, deckTopY + 0.25f, cz), new Vector3(0.52f, 0.5f, 0.52f), matStoneDark, 200, Quaternion.identity);
                        }
                        spot++;
                    }
                }

                // ══════════ RUBBLE / DEBRIS ══════════
                {
                    int rubbleCount = isFactory ? 9 : isBunker ? 4 : 6;
                    for (int i = 0; i < rubbleCount; i++)
                    {
                        float rx = UnityEngine.Random.Range(-W * 0.8f, W * 0.8f);
                        float rz = UnityEngine.Random.Range(-W * 0.8f, W * 0.8f);
                        if (Mathf.Abs(rx) < 1.3f && Mathf.Abs(rz) < 1.3f) continue; // keep the central dais clear
                        float rs = UnityEngine.Random.Range(0.22f, 0.6f);
                        float rr = UnityEngine.Random.value;
                        Material rm = rr < 0.45f ? matStone : rr < 0.75f ? matRustDark : matMoss;
                        AddBlock($"Rubble_{i}", new Vector3(rx, deckTopY + rs * 0.4f + 0.04f, rz), new Vector3(rs, rs * 0.8f, rs), rm, 80,
                            Quaternion.Euler(UnityEngine.Random.Range(0f, 360f), UnityEngine.Random.Range(0f, 360f), UnityEngine.Random.Range(0f, 360f)));
                    }
                }

                // ══════════ COLLAPSED SECTION (factory only) — fallen wall blocks outside the South face ══════════
                if (isFactory)
                {
                    for (int i = 0; i < 4; i++)
                    {
                        float cx = UnityEngine.Random.Range(-module * 0.9f, module * 0.9f);
                        float cz = -W - UnityEngine.Random.Range(0.2f, 1.7f);
                        float s = UnityEngine.Random.Range(0.5f, 1.1f);
                        AddBlock($"CollapsedBlock_{i}", new Vector3(cx, 0.25f + s * 0.4f, cz), new Vector3(s, s * 0.8f, s),
                            UnityEngine.Random.value < 0.5f ? matRustMain : matStone, 120,
                            Quaternion.Euler(UnityEngine.Random.Range(-25f, 25f), UnityEngine.Random.Range(0f, 360f), UnityEngine.Random.Range(-25f, 25f)));
                    }
                }

                // ══════════ BANNER POLE (crusader standard — non-bunker ruins) ══════════
                if (hasBattlements)
                {
                    float bx = -W + pillarW * 0.5f, bz = -W + pillarW * 0.5f;
                    AddBlock("BannerPole", new Vector3(bx, deckTopY + wallHeight * 0.5f, bz), new Vector3(0.12f, wallHeight, 0.12f), matWood, 120, Quaternion.identity);
                    AddDecor("BannerFinial", new Vector3(bx, deckTopY + wallHeight + 0.12f, bz), new Vector3(0.22f, 0.22f, 0.22f), matChestTrim, Quaternion.identity);
                    var cloth = AddDecor("BannerCloth", new Vector3(bx + 0.4f, deckTopY + wallHeight * 0.74f, bz), new Vector3(0.8f, wallHeight * 0.52f, 0.04f), matBanner, Quaternion.identity);
                    cloth.transform.localRotation = Quaternion.Euler(0f, 90f, UnityEngine.Random.Range(-4f, 4f));
                }

                // ══════════ RELIC CHEST on a stone dais ══════════
                AddDecor("DaisStep", new Vector3(0f, deckTopY + 0.01f, 0f), new Vector3(2.4f, 0.08f, 2.4f), matStone, Quaternion.identity);
                AddBlock("Dais", new Vector3(0f, deckTopY + 0.15f, 0f), new Vector3(1.9f, 0.26f, 1.9f), matStoneDark, 300, Quaternion.identity);

                float chestBaseY = deckTopY + 0.28f;
                var chestGO = new GameObject("RuinChest_Visible");
                chestGO.transform.SetParent(root.transform, false);
                chestGO.transform.localPosition = new Vector3(0f, chestBaseY + 0.36f, 0f);
                chestGO.transform.localScale = new Vector3(1.0f, 0.7f, 0.8f);
                {
                    var chestCol = chestGO.GetComponent<Collider>() as BoxCollider;
                    if (chestCol == null) chestCol = chestGO.AddComponent<BoxCollider>();
                    chestCol.size = new Vector3(1.3f, 1.0f, 1.05f);
                    chestCol.center = Vector3.zero;
                    var chestPB = chestGO.GetComponent<VoxelEngine.Building.PlacedBlock>();
                    if (chestPB == null) chestPB = chestGO.AddComponent<VoxelEngine.Building.PlacedBlock>();
                    chestPB.Hp = 120;
                    var chestDrop = chestGO.AddComponent<VoxelEngine.Exploration.RuinBlockDrop>();
                    chestDrop.salvage = salvageWood;

                    var chestBody = GameObject.CreatePrimitive(PrimitiveType.Cube);
                    chestBody.name = "ChestBody";
                    chestBody.transform.SetParent(chestGO.transform, false);
                    chestBody.transform.localPosition = new Vector3(0f, 0f, 0f);
                    chestBody.transform.localScale = new Vector3(1f, 0.85f, 1f);
                    if (matChest != null) chestBody.GetComponent<Renderer>().sharedMaterial = matChest;

                    var chestLid = GameObject.CreatePrimitive(PrimitiveType.Cube);
                    chestLid.name = "ChestLid";
                    chestLid.transform.SetParent(chestGO.transform, false);
                    chestLid.transform.localPosition = new Vector3(0f, 0.5f, 0f);
                    chestLid.transform.localScale = new Vector3(1.04f, 0.22f, 1.04f);
                    if (matChest != null) chestLid.GetComponent<Renderer>().sharedMaterial = matChest;
                    { var lc = chestLid.GetComponent<Collider>(); if (lc != null) UnityEngine.Object.DestroyImmediate(lc); }

                    foreach (float strapX in new float[] { -0.35f, 0.35f })
                    {
                        var strap = GameObject.CreatePrimitive(PrimitiveType.Cube);
                        strap.name = $"ChestStrap_{strapX}";
                        strap.transform.SetParent(chestGO.transform, false);
                        strap.transform.localPosition = new Vector3(strapX, 0.05f, 0f);
                        strap.transform.localScale = new Vector3(0.12f, 1.0f, 1.04f);
                        if (matChestTrim != null) strap.GetComponent<Renderer>().sharedMaterial = matChestTrim;
                        { var sc = strap.GetComponent<Collider>(); if (sc != null) UnityEngine.Object.DestroyImmediate(sc); }
                    }
                    var lockPlate = GameObject.CreatePrimitive(PrimitiveType.Cube);
                    lockPlate.name = "ChestLock";
                    lockPlate.transform.SetParent(chestGO.transform, false);
                    lockPlate.transform.localPosition = new Vector3(0f, 0.05f, 0.52f);
                    lockPlate.transform.localScale = new Vector3(0.22f, 0.28f, 0.07f);
                    if (matChestTrim != null) lockPlate.GetComponent<Renderer>().sharedMaterial = matChestTrim;
                    { var lc = lockPlate.GetComponent<Collider>(); if (lc != null) UnityEngine.Object.DestroyImmediate(lc); }

                    var chestGlow = new GameObject("ChestGlow");
                    chestGlow.transform.SetParent(chestGO.transform, false);
                    chestGlow.transform.localPosition = new Vector3(0f, 0.5f, 0f);
                    var gl = chestGlow.AddComponent<Light>();
                    gl.type = LightType.Point;
                    gl.color = new Color(1f, 0.78f, 0.22f);
                    gl.intensity = 1.4f;
                    gl.range = 6f;
                    gl.shadows = LightShadows.None;
                }

                // ══════════ LOOT CONFIG (preserved if previously hand-tuned) ══════════
                var comps = new System.Collections.Generic.List<ItemDefinition>();
                if (steelPlate != null) comps.Add(steelPlate);
                if (ironPlate != null) comps.Add(ironPlate);
                if (copperWire != null) comps.Add(copperWire);
                if (circuit != null) comps.Add(circuit);
                if (comps.Count == 0 && ironIngot != null) comps.Add(ironIngot);
                var bps = new System.Collections.Generic.List<BlueprintDataCoreItem>();
                if (bpNacelle != null) bps.Add(bpNacelle);
                if (bpGearbox != null) bps.Add(bpGearbox);
                if (bpBlade != null) bps.Add(bpBlade);
                if (bpTower != null) bps.Add(bpTower);
                var fuel = (coal != null) ? new ItemDefinition[] { coal } : new ItemDefinition[0];

                ItemDefinition[] finalComps = keepComponents ?? comps.ToArray();
                ItemDefinition[] finalFuel = keepFuel ?? fuel;
                BlueprintDataCoreItem[] finalBps = keepBlueprints ?? bps.ToArray();
                string ruinDisplayName = !string.IsNullOrEmpty(keepRuinName) ? keepRuinName : name.Replace("Ruin_", "").Replace("_", " ");

                // (No root RuinChest — open the visible chest inside the ruin to loot it.)

                var childChest = chestGO.GetComponent<VoxelEngine.Exploration.RuinChest>();
                if (childChest == null) childChest = chestGO.AddComponent<VoxelEngine.Exploration.RuinChest>();
                if (childChest != null)
                {
                    childChest.ruinName = ruinDisplayName;
                    childChest.minComponents = keepMinComp;
                    childChest.maxComponents = keepMaxComp;
                    childChest.possibleComponents = finalComps;
                    childChest.possibleFuel = finalFuel;
                    childChest.possibleBlueprints = finalBps;
                }

                // ══════════ BEACON (long-range visibility) ══════════
                var lightGO = new GameObject("RuinBeaconLight");
                lightGO.transform.SetParent(root.transform, false);
                lightGO.transform.localPosition = new Vector3(0f, deckTopY + wallHeight + 1.4f, 0f);
                var beacon = lightGO.AddComponent<Light>();
                beacon.type = LightType.Point;
                beacon.color = new Color(1f, 0.72f, 0.32f, 1f);
                beacon.intensity = 1.8f;
                beacon.range = 22f;
                beacon.shadows = LightShadows.None;

                var prefab = PrefabUtility.SaveAsPrefabAsset(root, prefabPath);
                UnityEngine.Object.DestroyImmediate(root);
                return prefab;
            }


            var ruinWarehouse = MakeRuinPrefab("Ruin_WarehouseSmall", new Color(0.55f,0.38f,0.22f), new Vector3(3f,2f,3f), 2, 4);
            var ruinFactory = MakeRuinPrefab("Ruin_FactoryCollapsed", new Color(0.45f,0.32f,0.20f), new Vector3(4f,2.5f,4f), 3, 5);
            var ruinBunker = MakeRuinPrefab("Ruin_Bunker", new Color(0.40f,0.40f,0.42f), new Vector3(2.5f,1.8f,2.5f), 2, 3);

            // Ruin blocks (placeable decoration, not required for scatter but handy)
            if (ruinWarehouse != null)
            {
                var blockRuinWarehouse = MakeBlk(MISC_BLOCKS, "Block_RuinWarehouse", "Rusted Warehouse Ruin",
                    "Collapsed warehouse from dead civilization. Contains loot and possibly a damaged blueprint core. Spawns rarely in Wasteland/Plains.",
                    new Color(0.55f,0.38f,0.22f), ruinWarehouse, "Ruins", hp: 250, miningTier: 1);
            }
            if (ruinFactory != null)
            {
                var blockRuinFactory = MakeBlk(MISC_BLOCKS, "Block_RuinFactory", "Collapsed Factory Ruin",
                    "Derelict factory, overgrown and rusted. Holds components and blueprint cores.",
                    new Color(0.45f,0.32f,0.20f), ruinFactory, "Ruins", hp: 300, miningTier: 1);
            }

            // No recipes for ruins — they are found, not crafted.

            // Inject ruins into biomes as very rare scatter (non-destructive append)
            try
            {
                var biomeRegistryPath = ASSET_ROOT + "/BiomeRegistry.asset";
                var br = AssetDatabase.LoadAssetAtPath<VoxelEngine.Biomes.BiomeRegistry>(biomeRegistryPath);
                if (br != null)
                {
                    foreach (var biome in br.biomes)
                    {
                        if (biome == null) continue;
                        bool isTarget = biome.biomeName == "Wasteland" || biome.biomeName == "Plains" || biome.biomeName == "Steppes" || biome.biomeName == "Desert" || biome.biomeName == "Forest" || biome.biomeName == "Beach";
                        if (!isTarget) continue;
                        var existing = biome.scatter != null ? new System.Collections.Generic.List<VoxelEngine.Biomes.BiomeDefinition.ScatterEntry>(biome.scatter) : new System.Collections.Generic.List<VoxelEngine.Biomes.BiomeDefinition.ScatterEntry>();
                        // Avoid duplicating ruins if already present
                        bool hasRuin = false;
                        foreach (var e in existing) if (e.prefab != null && e.prefab.name.Contains("Ruin_")) { hasRuin = true; break; }
                        if (hasRuin)
                        {
                            // Re-run: sync existing ruin scatter density to the current rare value.
                            for (int ri = 0; ri < existing.Count; ri++)
                            {
                                var e = existing[ri];
                                if (e.prefab == ruinWarehouse || e.prefab == ruinFactory || e.prefab == ruinBunker)
                                {
                                    e.density = 0.00008f;
                                    existing[ri] = e;
                                }
                            }
                            biome.scatter = existing.ToArray();
                            EditorUtility.SetDirty(biome);
                            continue;
                        }
                        // PREMIUM RARE — easy numbers to tweak (user request: not 0.005(something) confusing)
                        // User said WAYYYY too frequent at 0.0085, then 0.002 still too frequent.
                        // Now VERY RARE: 0.0008 = 0.08% per surface voxel = ~1 ruin per 6-8 chunks.
                        // To make rarer: lower to 0.0004, to make more common: raise to 0.0015
                        // EASY NUMBERS: 0.0008, 0.0005, 0.0006 — simple, readable, no 0.005(x) confusion
                        const float RUIN_DENSITY_WAREHOUSE = 0.00008f; // rare (~1 per 50+ chunks)
                        const float RUIN_DENSITY_FACTORY = 0.00008f;   // rare
                        const float RUIN_DENSITY_BUNKER = 0.00008f;    // rare
                        if (ruinWarehouse != null)
                            existing.Add(new VoxelEngine.Biomes.BiomeDefinition.ScatterEntry { prefab = ruinWarehouse, density = RUIN_DENSITY_WAREHOUSE, minScale = 1.2f, maxScale = 1.6f, minHeight = 0, maxHeight = 9999 });
                        if (ruinFactory != null)
                            existing.Add(new VoxelEngine.Biomes.BiomeDefinition.ScatterEntry { prefab = ruinFactory, density = RUIN_DENSITY_FACTORY, minScale = 1.3f, maxScale = 1.8f, minHeight = 0, maxHeight = 9999 });
                        if (ruinBunker != null)
                            existing.Add(new VoxelEngine.Biomes.BiomeDefinition.ScatterEntry { prefab = ruinBunker, density = RUIN_DENSITY_BUNKER, minScale = 1.1f, maxScale = 1.5f, minHeight = 0, maxHeight = 9999 });
                        biome.scatter = existing.ToArray();
                        EditorUtility.SetDirty(biome);
                    }
                    EditorUtility.SetDirty(br);
                    Debug.Log("[VoxelEngineSetup] Crusader ruins injected/synced — rare density 0.00008 (~1 per 50+ chunks).");
                }
            }
            catch (System.Exception ex) { Debug.LogWarning("[VoxelEngineSetup] Ruins biome injection failed: " + ex.Message); }

            // Cooking recipes — happen at any Furnace (treated like a smelting recipe? simpler as bench recipes here).
            AddRecipe(FARM_RECIPES, "Recipe_Cook_Bread", "Bread", foodBread, 1, VoxelEngine.Crafting.StationTier.Furnace, false, ((VoxelEngine.Items.ItemDefinition)foodWheatRaw, 3));
            AddRecipe(FARM_RECIPES, "Recipe_Cook_Stew", "Vegetable Stew", foodStew, 1, VoxelEngine.Crafting.StationTier.Furnace, false, ((VoxelEngine.Items.ItemDefinition)foodCarrotRaw, 2), ((VoxelEngine.Items.ItemDefinition)foodCornRaw, 1));

            // ════════════════════════════════════════════════════════════
            //  WRENCH — universal network connector tool
            //  LMB on a ConnectionAnchor selects, LMB on a second connects them.
            //  RMB disconnects ALL connections from the clicked anchor.
            //  Shift+RMB cycles a machine face port between None / Input / Output.
            //  Required for advanced wiring: data cables, power cables, port config.
            // ════════════════════════════════════════════════════════════
            string wrenchPath = $"{ITEMS}/Tool_Wrench.asset";
            var wrench = AssetDatabase.LoadAssetAtPath<VoxelEngine.Networks.WrenchTool>(wrenchPath);
            if (wrench == null)
            {
                wrench = ScriptableObject.CreateInstance<VoxelEngine.Networks.WrenchTool>();
                AssetDatabase.CreateAsset(wrench, wrenchPath);
            }
            wrench.itemId        = "wrench";
            wrench.displayName   = "Wrench";
            wrench.description   = "Industrial multi-tool for wiring networks together.\n\n" +
                                   "• LMB anchor → select. LMB second anchor → connect.\n" +
                                   "• RMB anchor → disconnect ALL.\n" +
                                   "• Shift+LMB anchor → disconnect the specific link you clicked.\n" +
                                   "• Shift+RMB machine face → cycle port: None ▸ Input ▸ Output.";
            wrench.toolType      = VoxelEngine.Items.ToolType.Other;
            wrench.miningTier    = 0;
            wrench.maxDurability = 1000;
            wrench.strength      = 0f;
            wrench.fireRate      = 4f;
            wrench.brushRadius   = 0.0f;
            wrench.iconTint      = new Color(0.85f, 0.55f, 0.20f);
            wrench.maxStack      = 1;
            wrench.category      = "Tools";
            EditorUtility.SetDirty(wrench);

            // Recipe: 2 iron plates + 1 iron gear, crafted at the Crafting Bench.
            AddRecipe(MISC_RECIPES, "Recipe_Wrench", "Wrench", wrench, 1, VoxelEngine.Crafting.StationTier.CraftingBench, false, ((VoxelEngine.Items.ItemDefinition)ironPlate, 2), ((VoxelEngine.Items.ItemDefinition)ironGear, 1));

            // ════════════════════════════════════════════════════════════
            //  POWER BUSBAR — clean cable-organization conduit
            //  A fat copper bar with brass tap-sockets that behaves like a
            //  PowerCable but lets the player run one trunk along the
            //  ceiling/floor of a factory with many machine cables snapping
            //  into it. Inherits all topology / wrench / PortConfig logic.
            // ════════════════════════════════════════════════════════════
            var busbarPrefab = MakePref(MISC_PREFABS, "PowerBusbar",
                new Color(0.78f, 0.45f, 0.20f), new Vector3(0.4f, 0.4f, 0.4f),
                root =>
                {
                    var bus = root.AddComponent<VoxelEngine.Power.PowerBusbar>();
                    bus.busAxis       = VoxelEngine.Power.PowerBusbar.BusAxis.X;
                    bus.busLength     = 2f;
                    bus.busRadius     = 0.18f;
                    bus.socketRadius  = 0.24f;
                    bus.socketSpacing = 0.50f;
                    bus.barTint       = new Color(0.78f, 0.45f, 0.20f);
                    bus.socketTint    = new Color(0.95f, 0.80f, 0.35f);
                    bus.connectRadius = 3.5f;
                    bus.gridSize      = 1f;
                });
            var blockBusbar = MakeBlk(MISC_BLOCKS, "Block_PowerBusbar", "Power Busbar",
                "A copper power-distribution bar with brass tap-sockets. Acts as a " +
                "thicker, longer power cable — perfect for running a single trunk " +
                "along the ceiling of a factory and snapping every machine cable into it.",
                new Color(0.78f, 0.45f, 0.20f), busbarPrefab, "Logistics", hp: 250, maxStack: 16);
            AddRecipe(MISC_RECIPES, "Recipe_PowerBusbar", "Power Busbar", blockBusbar, 1, VoxelEngine.Crafting.StationTier.CraftingBench, false, ((VoxelEngine.Items.ItemDefinition)copperPlate, 4), ((VoxelEngine.Items.ItemDefinition)ironPlate, 1));

            // ════════════════════════════════════════════════════════════
            //  ITEM PIPES
            // ════════════════════════════════════════════════════════════
            // Item pipes use the wire-style PipeVisualBuilder. Solid = brushed steel,
            // glass variant exposes a vivid "item stream" inner core so the player
            // can see stacks flowing through the network.
            // Sleeved industrial look: dark steel sleeve along the
            // run + bright AMBER/orange terminal end-blocks at every junction.
            GameObject MakeItemPipePrefab(string assetName, Color shell, Color accent, Color inner, bool glass)
            {
                string path = $"{MISC_PREFABS}/{assetName}.prefab";
                var root = new GameObject(assetName);
                var col  = root.AddComponent<BoxCollider>();
                col.size = new Vector3(0.55f, 0.55f, 0.55f);

                var p = root.AddComponent<VoxelEngine.Transport.ItemPipe>();
                p.connectRadius = 3f; p.bufferSize = 4; p.tickInterval = 0.5f;
                p.isGlass = glass;

                var vb = root.AddComponent<VoxelEngine.Networks.PipeVisualBuilder>();
                vb.shellTint        = shell;
                vb.accentTint       = accent;
                vb.innerMediumTint  = inner;
                vb.isGlass          = glass;
                vb.style            = VoxelEngine.Networks.PipeStyle.Sleeve;
                vb.gridSize         = 1f;

                var prefab = PrefabUtility.SaveAsPrefabAsset(root, path);
                Object.DestroyImmediate(root);
                return prefab;
            }
            // Solid item pipe — dark steel sleeve, amber/orange terminals.
            var pipeItemPrefab      = MakeItemPipePrefab("ItemPipe",
                new Color(0.18f, 0.18f, 0.20f),   // sleeve
                new Color(0.95f, 0.55f, 0.12f),   // amber terminals (BC look)
                new Color(0.95f, 0.75f, 0.25f),
                false);
            // Glass item pipe — frosted shell + warm amber stream visible inside.
            var pipeItemGlassPrefab = MakeItemPipePrefab("ItemPipe_Glass",
                new Color(0.85f, 0.92f, 1.00f),
                new Color(0.95f, 0.55f, 0.12f),
                new Color(0.95f, 0.65f, 0.20f),
                true);

            var blockItemPipe = MakeBlk(MISC_BLOCKS, "Block_ItemPipe", "Item Pipe",
                "Carries item stacks between machines and chests automatically. Tick every 0.5 s.",
                new Color(0.55f, 0.55f, 0.60f), pipeItemPrefab, "Logistics", hp: 100, maxStack: 99);
            var blockItemPipeGlass = MakeBlk(MISC_BLOCKS, "Block_ItemPipe_Glass", "Item Pipe (Glass)",
                "Translucent variant of the Item Pipe — exposes the items flowing through. Same throughput.",
                new Color(0.92f, 0.96f, 1.00f), pipeItemGlassPrefab, "Logistics", hp: 100, maxStack: 99);

            AddRecipe(MISC_RECIPES, "Recipe_ItemPipe", "Item Pipe x4", blockItemPipe, 4, VoxelEngine.Crafting.StationTier.CraftingBench, false, ((VoxelEngine.Items.ItemDefinition)ironPlate, 1));
            AddRecipe(MISC_RECIPES, "Recipe_ItemPipe_Glass", "Item Pipe (Glass) x4", blockItemPipeGlass, 4, VoxelEngine.Crafting.StationTier.CraftingBench, false, ((VoxelEngine.Items.ItemDefinition)ironPlate, 1), ((VoxelEngine.Items.ItemDefinition)glass, 1));

            // ════════════════════════════════════════════════════════════
            //  QUARRY + UPGRADES (Range / Speed / Efficiency)
            // ════════════════════════════════════════════════════════════
            var quarryPrefab = MakePref(MISC_PREFABS, "Quarry",
                new Color(0.35f, 0.35f, 0.40f), new Vector3(2f, 2.4f, 2f),
root =>
                {
                    var pc = root.AddComponent<VoxelEngine.Power.PowerConsumer>();
                    pc.wattsPerSecond = 500f; pc.connectRadius = 2f;
                    var portCfg = root.AddComponent<VoxelEngine.Transport.PortConfig>();
                    portCfg.ports = new VoxelEngine.Transport.PortConfig.FacePort[]
                    {
                        new() { face = VoxelEngine.Transport.CubeFace.PosX, direction = VoxelEngine.Transport.PortDirection.Output, networkType = VoxelEngine.Transport.PortNetworkType.Any,   enabled = true },
                        new() { face = VoxelEngine.Transport.CubeFace.NegX, direction = VoxelEngine.Transport.PortDirection.None,   networkType = VoxelEngine.Transport.PortNetworkType.Any,   enabled = true },
                        new() { face = VoxelEngine.Transport.CubeFace.PosY, direction = VoxelEngine.Transport.PortDirection.None,   networkType = VoxelEngine.Transport.PortNetworkType.Any,   enabled = true },
                        new() { face = VoxelEngine.Transport.CubeFace.NegY, direction = VoxelEngine.Transport.PortDirection.None,   networkType = VoxelEngine.Transport.PortNetworkType.Any,   enabled = true },
                        new() { face = VoxelEngine.Transport.CubeFace.PosZ, direction = VoxelEngine.Transport.PortDirection.None,   networkType = VoxelEngine.Transport.PortNetworkType.Any,   enabled = true },
                        new() { face = VoxelEngine.Transport.CubeFace.NegZ, direction = VoxelEngine.Transport.PortDirection.Input,  networkType = VoxelEngine.Transport.PortNetworkType.Power, enabled = true },
                    };
                    var q = root.AddComponent<VoxelEngine.Transport.Quarry>();
                    q.defaultSize = 16; q.baseMineInterval = 0.5f; q.quarryTier = 3;
                    q.maximumMiningDepth = 64;
                    q.forwardOffset = 2f; q.frameBuildInterval = 0.06f;
                    q.frameColor = new Color(0.18f, 0.19f, 0.22f);
                    q.outputSlots = 6;
                    q.EnsureUpgrades();
                });
            var blockQuarry = MakeBlk(MISC_BLOCKS, "Block_Quarry", "Quarry",
