                                           : family == VoxelEngine.Items.JetpackFamily.Atmospheric ? 35f
                                           : 42f;
                item.autoRechargeThreshold = 0.10f;
                item.chargedCellRefuelMl = 350;
                EditorUtility.SetDirty(item);
                return item;
            }

