            AddGRecipe("Recipe_GGasTank", "Gas Tank", itemGasTank, (steelPlate, 5), (glass, 2), (copperWire, 2));

            var h2o2Pref = MakeGPref<VoxelEngine.GridSystem.GridH2O2Generator>("H2O2Generator_Large", new Color(0.3f, 0.7f, 0.9f), new Vector3(1.5f, 1.5f, 2.0f));
            var itemH2O2 = MakeGItem("GItem_H2O2Generator", "H2/O2 Generator", Color.white, h2o2Pref, VoxelEngine.GridSystem.GridSize.Large, 600, 700);
            AddGRecipe("Recipe_GH2O2Generator", "H2/O2 Generator", itemH2O2, (steelPlate, 8), (circuit, 4), (copperWire, 8));

            var hydrogenEngineGridPref = MakeGPref<VoxelEngine.GridSystem.GridHydrogenEngine>("HydrogenEngine_Large", new Color(0.20f, 0.85f, 0.35f), new Vector3(1.5f, 1.2f, 1.5f),
                e => { e.wattsOutput = 12000f; e.hydrogenPerSecond = 0.75f; e.internalTankCapacity = 250f; e.refillRate = 4f; e.minHydrogenToRun = 0.25f; });
            var itemHydrogenEngineGrid = MakeGItem("GItem_HydrogenEngine", "Hydrogen Engine", Color.white, hydrogenEngineGridPref, VoxelEngine.GridSystem.GridSize.Large, 950, 700);
            AddGRecipe("Recipe_GHydrogenEngine", "Hydrogen Engine", itemHydrogenEngineGrid, (steelPlate, 8), (ironPlate, 4), (circuit, 4), (copperWire, 8));

            // -- 11) Structure / Misc --
            var glassPref = MakeGPref<VoxelEngine.GridSystem.GridGlassBlock>("Glass_Small", new Color(0.7f, 0.85f, 0.95f, 0.5f), new Vector3(0.5f, 0.5f, 0.5f));
            var itemGlassBlk = MakeGItem("GItem_GlassBlock", "Glass Block", Color.white, glassPref, VoxelEngine.GridSystem.GridSize.Small, 40, 120);
            AddGRecipe("Recipe_GGlassBlock", "Glass Block", itemGlassBlk, (glass, 1));

            var demoPref = MakeGPref<VoxelEngine.GridSystem.GridDemolisher>("Demolisher_Large", new Color(0.7f, 0.3f, 0.1f), new Vector3(1.2f, 1.2f, 1.6f), d => { d.damagePerSecond = 50f; d.terrainDPS = 30f; });
            var itemDemo = MakeGItem("GItem_Demolisher", "Demolisher", Color.white, demoPref, VoxelEngine.GridSystem.GridSize.Large, 320, 560);
            AddGRecipe("Recipe_GDemolisher", "Demolisher", itemDemo, (steelPlate, 6), (circuit, 3));

            // -- Piston Block --
            var pistonPref = MakeGPref<VoxelEngine.GridSystem.GridPiston>("Piston_Large", new Color(0.6f, 0.6f, 0.6f), Vector3.one, p => {
                p.targetLength = 5f;
                p.extensionSpeed = 2f;
            });
            // Custom Visuals for Piston (Since GridBlockMeshBuilder is generic)
            var pistonRoot = PrefabUtility.LoadPrefabContents(AssetDatabase.GetAssetPath(pistonPref));
            GameObject basePart = GameObject.CreatePrimitive(PrimitiveType.Cube);
            basePart.name = "Base";
            basePart.transform.SetParent(pistonRoot.transform, false);
            basePart.transform.localScale = new Vector3(0.8f, 0.4f, 0.8f);
            basePart.GetComponent<Renderer>().sharedMaterial = MakeColoredMat(PREFABS + "/Mats", "Mat_PistonBase", new Color(0.4f, 0.4f, 0.4f));

            GameObject headPart = GameObject.CreatePrimitive(PrimitiveType.Cube);
            headPart.name = "Head";
            headPart.transform.SetParent(pistonRoot.transform, false);
            headPart.transform.localScale = new Vector3(0.9f, 0.2f, 0.9f);
            headPart.transform.localPosition = new Vector3(0, 0.2f, 0);
            headPart.GetComponent<Renderer>().sharedMaterial = MakeColoredMat(PREFABS + "/Mats", "Mat_PistonHead", new Color(0.7f, 0.7f, 0.7f));

            PrefabUtility.SaveAsPrefabAsset(pistonRoot, AssetDatabase.GetAssetPath(pistonPref));
            PrefabUtility.UnloadPrefabContents(pistonRoot);

            var itemPiston = MakeGItem("GItem_Piston", "Industrial Piston", Color.white, pistonPref, VoxelEngine.GridSystem.GridSize.Large, 400, 600);
            itemPiston.description = "A powerful hydraulic piston. Pushes and pulls grid blocks above it. Configurable length (0-20m) and speed.";
            AddGRecipe("Recipe_GPiston", "Industrial Piston", itemPiston, (steelPlate, 8), (ironPlate, 4), (copperWire, 8), (circuit, 2));

            // ── 13) Beacon + Ore Detector (utility blocks) ──────────────
            var beaconPref = MakeGPref<VoxelEngine.GridSystem.GridBeacon>("Beacon_Large", new Color(0.3f, 0.8f, 1f), new Vector3(0.5f, 1f, 0.5f),
                b => { b.powerDrawWatts = 10f; b.beamHeight = 200f; b.rotationSpeed = 90f; });
            var itemBeacon = MakeGItem("GItem_Beacon", "Beacon", new Color(0.3f, 0.8f, 1f), beaconPref, VoxelEngine.GridSystem.GridSize.Large, 80, 150);
            AddGRecipe("Recipe_GBeacon", "Beacon", itemBeacon, (ironPlate, 2), (copperWire, 2), (glass, 1));
            if (string.IsNullOrEmpty(itemBeacon.description)) { itemBeacon.description = "Projects a visible vertical light beam into the sky that can be seen from far away. Toggle on/off via the ship terminal. Draws only 10W. Perfect for marking bases, waypoints, or fleet rendezvous points."; EditorUtility.SetDirty(itemBeacon); }

            var oreDetPref = MakeGPref<VoxelEngine.GridSystem.GridOreDetector>("OreDetector_Large", new Color(0.5f, 0.55f, 0.6f), new Vector3(1f, 1.2f, 1f),
                d => { d.powerDrawWatts = 100f; d.scanRadius = 16f; d.maxScanDepth = 30f; d.scanInterval = 2f; });
            var itemOreDet = MakeGItem("GItem_OreDetector", "Ore Detector", new Color(0.5f, 0.55f, 0.6f), oreDetPref, VoxelEngine.GridSystem.GridSize.Large, 200, 400);
            AddGRecipe("Recipe_GOreDetector", "Ore Detector", itemOreDet, (ironPlate, 6), (circuit, 4), (copperWire, 8), (advCircuit, 2));
            if (string.IsNullOrEmpty(itemOreDet.description)) { itemOreDet.description = "Scans the terrain below for ore deposits. Reports detected ore types, depths, and deposit sizes. The rotating parabolic dish sweeps continuously while powered (~100W). Range: 16 blocks radius, 30 blocks deep."; EditorUtility.SetDirty(itemOreDet); }

            // ── Stationary Radar Beacon (world block) ───────────────────
            string radarPrefabPath = ASSET_ROOT + "/GridSystem/Prefabs/StationaryRadarBeacon.prefab";
            EnsureFolder(ASSET_ROOT + "/GridSystem/Prefabs");
            var radarRoot = new GameObject("StationaryRadarBeacon");
            var radarCol = radarRoot.AddComponent<BoxCollider>();
            radarCol.size = new Vector3(2f, 8f, 2f);
            radarCol.center = new Vector3(0, 3f, 0);
            var radarComp = radarRoot.AddComponent<VoxelEngine.GridSystem.StationaryRadarBeacon>();
            radarComp.beamHeight = 150f;
            radarComp.dishRotationSpeed = 45f;
            var radarPrefab = PrefabUtility.SaveAsPrefabAsset(radarRoot, radarPrefabPath);
            Object.DestroyImmediate(radarRoot);

            var radarItem = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.BlockItem>(ASSET_ROOT + "/GridSystem/Items/Block_StationaryRadarBeacon.asset");
            if (radarItem == null)
            {
                radarItem = ScriptableObject.CreateInstance<VoxelEngine.Items.BlockItem>();
                AssetDatabase.CreateAsset(radarItem, ASSET_ROOT + "/GridSystem/Items/Block_StationaryRadarBeacon.asset");
            }
            if (string.IsNullOrEmpty(radarItem.itemId) || radarItem.itemId.StartsWith("block_"))
            {
                radarItem.itemId = "stationary_radar_beacon";
                radarItem.displayName = "Stationary Radar Beacon";
                radarItem.iconTint = new Color(0.3f, 0.85f, 1f);
                radarItem.maxStack = 10; radarItem.massPerUnit = 8f;
                radarItem.placedPrefab = radarPrefab; radarItem.gridSize = Vector3Int.one;
                radarItem.allowStacking = false; radarItem.blockHealth = 400; radarItem.miningTier = 1;
                radarItem.category = "Grid Blocks";
                radarItem.description = "A tall radar tower with a rotating dish and beacon beam. Visible from far away. Place on land to mark your base. Toggle on/off, draws 10W. Looks like a coastal radar station.";
            }
            EditorUtility.SetDirty(radarItem);

            var recRadar = AddGRecipe("Recipe_GStationaryRadarBeacon", "Stationary Radar Beacon", radarItem, (steelPlate, 8), (circuit, 4), (copperWire, 6), (glass, 4));

            // -- 12) Chemical Plant (grid) — shares Chemistry ProcessingRecipes --
            string procFolder = ASSET_ROOT + "/Industrial/ProcessingRecipes";
            var procRefineShared  = AssetDatabase.LoadAssetAtPath<VoxelEngine.Crafting.ProcessingRecipe>($"{procFolder}/Proc_RefineOil.asset");
            var procPlasticShared = AssetDatabase.LoadAssetAtPath<VoxelEngine.Crafting.ProcessingRecipe>($"{procFolder}/Proc_MakePlastic.asset");
            var procChemistry     = AssetDatabase.LoadAssetAtPath<VoxelEngine.Crafting.ProcessingRecipe>($"{procFolder}/Proc_MakeLiquidFuel.asset");
            // Maritime fuel chain recipes (shared with stationary refinery / chem plant).
            var procHeavyFuelShared = AssetDatabase.LoadAssetAtPath<VoxelEngine.Crafting.ProcessingRecipe>($"{procFolder}/Proc_RefineHeavyFuelOil.asset");
            var procMGOShared       = AssetDatabase.LoadAssetAtPath<VoxelEngine.Crafting.ProcessingRecipe>($"{procFolder}/Proc_RefineMGO.asset");
            var procSynthMGOShared  = AssetDatabase.LoadAssetAtPath<VoxelEngine.Crafting.ProcessingRecipe>($"{procFolder}/Proc_SynthesiseMGO.asset");
            var procCoolantShared   = AssetDatabase.LoadAssetAtPath<VoxelEngine.Crafting.ProcessingRecipe>($"{procFolder}/Proc_MarineCoolant.asset");

            var chemPref = MakeGPref<VoxelEngine.GridSystem.GridChemicalPlant>("ChemicalPlant_Large", new Color(0.5f, 0.7f, 0.4f), new Vector3(2.5f, 2.5f, 2.5f),
                cp =>
                {
                    cp.knownRecipes = new System.Collections.Generic.List<VoxelEngine.Crafting.ProcessingRecipe>();
                    if (procChemistry != null) cp.knownRecipes.Add(procChemistry);
                    if (procSynthMGOShared != null) cp.knownRecipes.Add(procSynthMGOShared);
                    if (procCoolantShared != null) cp.knownRecipes.Add(procCoolantShared);
                });
            var itemChem = MakeGItem("GItem_ChemicalPlant", "Ship Chemical Plant", Color.white, chemPref, VoxelEngine.GridSystem.GridSize.Large, 1100, 900);
            AddGRecipe("Recipe_GChemicalPlant", "Ship Chemical Plant", itemChem, (steelPlate, 12), (circuit, 8), (copperWire, 8));

            // -- Recipe parity: grid Refinery uses the SAME ProcessingRecipe assets
            //    as the stationary Oil Refinery (Refine Crude Oil + Synthesise Plastic).
            {
                string refPath = AssetDatabase.GetAssetPath(refineryPref);
                var refContents = PrefabUtility.LoadPrefabContents(refPath);
                try
                {
                    var gr = refContents.GetComponent<VoxelEngine.GridSystem.GridRefinery>();
                    if (gr != null)
                    {
                        gr.knownRecipes = new System.Collections.Generic.List<VoxelEngine.Crafting.ProcessingRecipe>();
                        if (procRefineShared  != null) gr.knownRecipes.Add(procRefineShared);
                        if (procPlasticShared != null) gr.knownRecipes.Add(procPlasticShared);
                        if (procHeavyFuelShared != null) gr.knownRecipes.Add(procHeavyFuelShared);
                        if (procMGOShared       != null) gr.knownRecipes.Add(procMGOShared);
                    }
                    PrefabUtility.SaveAsPrefabAsset(refContents, refPath);
                }
                finally { PrefabUtility.UnloadPrefabContents(refContents); }
            }

            // -- Research Nodes --
            if (tree != null)
            {
                var nShip = FindNodeByName(tree, "res_shipbuilding");
                if (nShip == null)
                {
                    nShip = ScriptableObject.CreateInstance<VoxelEngine.Research.ResearchNode>();
                    nShip.nodeId = "res_shipbuilding";
                    nShip.displayName = "Shipbuilding";
                    nShip.description = "Design and construct functional spacecraft from a full grid block set.";
                    nShip.category = VoxelEngine.Research.ResearchCategory.Environment;
                    nShip.subCategory = VoxelEngine.Research.ResearchSubCategory.Building;
                    nShip.tier = 3; nShip.column = 4;
                    nShip.iconTint = new Color(0.3f, 0.6f, 0.9f);
                    nShip.researchSeconds = 60f;
                    nShip.cost = new[] {
                        new VoxelEngine.Research.ResearchNode.ScienceCost { pack = sciT2, count = 20 },
                        new VoxelEngine.Research.ResearchNode.ScienceCost { pack = sciT3, count = 10 }
                    };
                    var nAdvMfg = FindNodeByName(tree, "res_adv_manufacturing");
                    if (nAdvMfg != null) nShip.prerequisites = new[] { nAdvMfg };
                    AssetDatabase.CreateAsset(nShip, $"{NODES}/res_shipbuilding.asset");
                    tree.nodes.Add(nShip);
                }
                // Everything except the weapon unlocks with Shipbuilding.
                nShip.unlocksRecipes = recipes.FindAll(r => r != null && r != recWeapon && r != recAmmo).ToArray();
                EditorUtility.SetDirty(nShip);

                // Utility blocks: Beacon + Ore Detector (gated after Shipbuilding).
                var nUtil = FindNodeByName(tree, "res_grid_utilities");
                if (nUtil == null)
                {
                    nUtil = ScriptableObject.CreateInstance<VoxelEngine.Research.ResearchNode>();
                    nUtil.nodeId = "res_grid_utilities";
                    nUtil.displayName = "Grid Utilities";
                    nUtil.description = "Navigation and surveying equipment. Unlocks the Beacon (visible sky beam) and the Ore Detector (scans for underground deposits).";
                    nUtil.category = VoxelEngine.Research.ResearchCategory.Environment;
                    nUtil.subCategory = VoxelEngine.Research.ResearchSubCategory.Logistics;
                    nUtil.tier = 3; nUtil.column = 7;
                    nUtil.iconTint = new Color(0.3f, 0.8f, 1f);
                    nUtil.researchSeconds = 50f;
                    nUtil.cost = new[] { new VoxelEngine.Research.ResearchNode.ScienceCost { pack = sciT2, count = 15 } };
                    nUtil.prerequisites = new[] { nShip };
                    AssetDatabase.CreateAsset(nUtil, $"{NODES}/res_grid_utilities.asset");
                    tree.nodes.Add(nUtil);
                }
                nUtil.unlocksRecipes = recipes.FindAll(r => r != null && (r.name.Contains("Beacon") || r.name.Contains("OreDetector") || r.name.Contains("Radar"))).ToArray();
                EditorUtility.SetDirty(nUtil);
                EditorUtility.SetDirty(tree);

                if (recWeapon != null)
                {
                    var nArm = FindNodeByName(tree, "res_ship_weapons");
                    if (nArm == null)
                    {
                        nArm = ScriptableObject.CreateInstance<VoxelEngine.Research.ResearchNode>();
                        nArm.nodeId = "res_ship_weapons";
                        nArm.displayName = "Ship Armament";
                        nArm.description = "Unlocks ship-mounted weapons and defense systems.";
                        nArm.category = VoxelEngine.Research.ResearchCategory.Environment;
                        nArm.subCategory = VoxelEngine.Research.ResearchSubCategory.Military;
                        nArm.tier = 4; nArm.column = 5;
                        nArm.iconTint = new Color(0.9f, 0.25f, 0.2f);
                        nArm.researchSeconds = 90f;
                        nArm.cost = new[] { new VoxelEngine.Research.ResearchNode.ScienceCost { pack = sciT2, count = 30 } };
                        nArm.prerequisites = new[] { nShip };
                        AssetDatabase.CreateAsset(nArm, $"{NODES}/res_ship_weapons.asset");
                        tree.nodes.Add(nArm);
                    }
                    nArm.unlocksRecipes = recAmmo != null ? new[] { recWeapon, recAmmo } : new[] { recWeapon };
                    EditorUtility.SetDirty(nArm);
                }
                EditorUtility.SetDirty(tree);
            }

            EnsureItemPersistenceCatalog();
            if (registry != null) EditorUtility.SetDirty(registry);
            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();
            EditorUtility.DisplayDialog("Grid System",
                $"Step 12 complete — generated {recipes.Count} grid blocks (prefabs + items + recipes) in:\n{GRID_ROOT}\n\n" +
                "• Cockpit, Thruster, Battery (Small + Large + Giant), Armor\n" +
                "• Drill, Grinder, Refinery, Weapon, Demolisher (Large)\n" +
                "• Cargo, Docking Port, 2x2 / 3x3 / 5x5 Wheel Suspensions, Landing Gear\n" +
                "• Solar Panel, Portable Reactor, Hydrogen Engine, Water/Fuel/Gas Tanks, H2/O2 Gen\n" +
                "• Glass Block, Chemical Plant\n\n" +
                "Grid Refinery shares the SAME ProcessingRecipes as the Oil Refinery.\n" +
                "Recipes registered and gated behind Shipbuilding / Ship Armament research.", "OK");
        }


        // ============================================================
        //  STEP 13 - MARITIME PROPULSION CONTENT
        //  All maritime blocks (prefabs + items + recipes) + the
        //  4-tier "Maritime Engineering" research tree.
        // ============================================================
        private void BuildMaritimeContent()
        {
            const string MAR_ROOT  = ASSET_ROOT + "/Maritime";
            const string PREFABS   = MAR_ROOT + "/Prefabs";
            const string ITEMS     = MAR_ROOT + "/Items";
            const string RECIPES   = MAR_ROOT + "/Recipes";
            const string NODES     = ASSET_ROOT + "/Research/Nodes";

            foreach (var f in new[] { MAR_ROOT, PREFABS, ITEMS, RECIPES })
                EnsureFolder(f);

            // -- Dependencies (created by earlier steps) --
            string craftItems = ASSET_ROOT + "/Items";
            string indItems   = ASSET_ROOT + "/Industrial/Items";
            var woodLog     = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{craftItems}/Item_WoodLog.asset");
            var plank       = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{craftItems}/Item_WoodenPlank.asset");
            var ironIngot   = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{craftItems}/Item_IronIngot.asset");
            var copperIngot = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{craftItems}/Item_CopperIngot.asset");
            var steelIngot  = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{craftItems}/Item_SteelIngot.asset");
            var ironPlate   = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{indItems}/Item_IronPlate.asset");
            var steelPlate  = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{indItems}/Item_SteelPlate.asset");
            var copperPlate = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{indItems}/Item_CopperPlate.asset");
            var ironGear    = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{indItems}/Item_IronGear.asset");
            var copperWire  = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{indItems}/Item_CopperWire.asset");
            var circuit     = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{indItems}/Item_Circuit.asset");
            var advCircuit  = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{indItems}/Item_AdvCircuit.asset");
            var glass       = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{indItems}/Item_Glass.asset");
            var lithium     = EnsureLithiumResource();
            var sciT2 = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ScienceItem>($"{craftItems}/Item_ScienceT2.asset");
            var sciT3 = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ScienceItem>($"{craftItems}/Item_ScienceT3.asset");

            if (steelPlate == null || circuit == null)
            {
                EditorUtility.DisplayDialog("Voxel Engine", "Run Steps 4, 6, 7, 10, 12 first.", "OK");
                return;
            }

            var registry = AssetDatabase.LoadAssetAtPath<VoxelEngine.Crafting.RecipeRegistry>($"{ASSET_ROOT}/RecipeRegistry.asset");
            var tree = AssetDatabase.LoadAssetAtPath<VoxelEngine.Research.ResearchTree>($"{ASSET_ROOT}/Research/ResearchTree.asset");

            // -- Helpers (mirror Step 12) --
            float RealMass(string display, VoxelEngine.GridSystem.GridSize size, float authored)
            {
                float scale = size == VoxelEngine.GridSystem.GridSize.Small ? 3.5f : 8.0f;
                float floor = size == VoxelEngine.GridSystem.GridSize.Small ? 180f : 2500f;
                return Mathf.Max(authored * scale, floor);
            }

            VoxelEngine.GridSystem.GridBlockItem MakeMItem(string assetName, string display, Color tint,
                GameObject prefab, VoxelEngine.GridSystem.GridSize size, float mass, float hp)
            {
                string path = $"{ITEMS}/{assetName}.asset";
                bool existed = AssetDatabase.LoadAssetAtPath<VoxelEngine.GridSystem.GridBlockItem>(path) != null;
                var b = AssetDatabase.LoadAssetAtPath<VoxelEngine.GridSystem.GridBlockItem>(path);
                if (b == null) { b = ScriptableObject.CreateInstance<VoxelEngine.GridSystem.GridBlockItem>(); AssetDatabase.CreateAsset(b, path); }
                // Only populate fields on freshly-created items — never overwrite user edits.
                if (!existed)
                {
                    // Derive a clean itemId from the display name: "Heavy Fuel Oil Engine" → "heavy_fuel_oil_engine"
                    b.itemId = display.ToLowerInvariant().Replace(" ", "_").Replace("/", "_").Replace("(", "").Replace(")", "");
                    b.displayName = display; b.iconTint = tint;
                    b.maxStack = 20; b.gridSize = size; b.blockPrefab = prefab;
                    b.blockMass = RealMass(display, size, mass); b.blockHP = hp; b.category = "Maritime";
                }
                else
                {
                    // Light-touch: fix itemId if it's still the old "mitem_" style, but preserve everything else.
                    if (!string.IsNullOrEmpty(b.itemId) && b.itemId.StartsWith("mitem_"))
                        b.itemId = display.ToLowerInvariant().Replace(" ", "_").Replace("/", "_").Replace("(", "").Replace(")", "");
                    if (b.blockPrefab == null) b.blockPrefab = prefab;
                    if (string.IsNullOrEmpty(b.category)) b.category = "Maritime";
                }
                EditorUtility.SetDirty(b);
                return b;
            }

            VoxelEngine.Maritime.MechanicalBeltItem MakeMechanicalBeltItem(string assetName, string display, Color tint)
            {
                string path = $"{ITEMS}/{assetName}.asset";
                bool existed = AssetDatabase.LoadAssetAtPath<VoxelEngine.Maritime.MechanicalBeltItem>(path) != null;
                var belt = AssetDatabase.LoadAssetAtPath<VoxelEngine.Maritime.MechanicalBeltItem>(path);
                if (belt == null)
                {
                    belt = ScriptableObject.CreateInstance<VoxelEngine.Maritime.MechanicalBeltItem>();
                    AssetDatabase.CreateAsset(belt, path);
                }
                // New content gets authored defaults once. Re-running Step 13 preserves
                // player/project balance edits to belt reach, stack count, and mass.
                if (!existed)
                {
                    belt.itemId = "mechanical_belt";
                    belt.displayName = display;
                    belt.description = "A reinforced marine drive belt. Right-click one parallel shaft pulley, then another to route a belt. Insert shafts through the belt run for extra take-off outputs. Shift-right-click a shaft to remove and recover attached belts.";
                    belt.iconTint = tint;
                    belt.maxStack = 20;
                    belt.massPerUnit = 2f;
                    belt.category = "Maritime";
                    belt.minSpanMeters = 0.75f;
                    belt.maxSpanMeters = 20f;
                    belt.maxBeltsPerGrid = 64;
                }
                else
                {
                    if (string.IsNullOrEmpty(belt.itemId)) belt.itemId = "mechanical_belt";
                    if (string.IsNullOrEmpty(belt.category)) belt.category = "Maritime";
                }
                EditorUtility.SetDirty(belt);
                return belt;
            }

            GameObject MakeMPref<T>(string name, Color color, Vector3 scale, VoxelEngine.GridSystem.GridSize size, System.Action<T> config = null) where T : VoxelEngine.GridSystem.GridBlock
            {
                string path = $"{PREFABS}/{name}.prefab";
                bool prefabExists = AssetDatabase.LoadAssetAtPath<GameObject>(path) != null;

                var prefab = GetOrCreatePrefab(path, name, (root) =>
                {
                    EnsureFolder(PREFABS + "/Mats");
                    int matIdx = 0;
                    VoxelEngine.Maritime.MaritimeMeshBuilder.MaterialPersister = (mat, _) =>
                    {
                        string mp = $"{PREFABS}/Mats/{name}_{matIdx++}.mat";
                        var existing = AssetDatabase.LoadAssetAtPath<Material>(mp);
                        if (existing != null) return existing;
                        AssetDatabase.CreateAsset(mat, mp);
                        return AssetDatabase.LoadAssetAtPath<Material>(mp);
                    };
                    try
                    {
                        bool needsMesh = root.transform.childCount == 0;
                        if (!needsMesh)
                        {
                            bool foundMarker = false;
                            int expectedVersion = VoxelEngine.Maritime.MaritimeMeshBuilder.Version;
                            foreach (Transform child in root.transform)
                            {
                                if (child == null || !child.name.StartsWith("__MaritimeMesh_v")) continue;
                                foundMarker = true;
                                if (child.name != $"__MaritimeMesh_v{expectedVersion}") needsMesh = true;
                                break;
                            }
                            if (!foundMarker) needsMesh = true;
                        }

                        bool isNew = !prefabExists;

                        if (needsMesh)
                            VoxelEngine.Maritime.MaritimeMeshBuilder.Build(root, name, size);

                        // Root collider: re-fit ONLY on create / mesh rebuild / when
                        // missing — manual collider edits survive re-runs (non-destructive).
                        // bounds arrive in unscaled asset space while BoxCollider.size is
                        // root-LOCAL: divide out the root scale or it double-applies (the
                        // MGO's 1.2 Y/Z scale used to inflate the hitbox way past the model).
                        var box = root.GetComponent<BoxCollider>();
                        // "Missing" = neither the legacy single box nor the banded
                        // hitbox pair exists — otherwise manual collider edits are
                        // preserved verbatim across Step-13 re-runs.
                        bool colliderMissing = box == null
                            && root.transform.Find("Hitbox_Lower") == null
                            && root.transform.Find("Hitbox_Upper") == null;
                        if (colliderMissing) box = root.AddComponent<BoxCollider>();
                        if (box == null) box = root.GetComponent<BoxCollider>(); // re-fetch after transient add
                        if (isNew || needsMesh || colliderMissing)
                        {
                            float cs = VoxelEngine.GridSystem.GridSizeExt.CellSize(size);
                            var renderers = root.GetComponentsInChildren<Renderer>(true);
                            if (renderers != null && renderers.Length > 0)
                            {
                                Bounds bounds = renderers[0].bounds;
                                for (int i = 1; i < renderers.Length; i++) bounds.Encapsulate(renderers[i].bounds);
                                Vector3 rootScale = root.transform.localScale;
                                Vector3 invScale = new Vector3(
                                    Mathf.Abs(rootScale.x) > 0.0001f ? 1f / rootScale.x : 1f,
                                    Mathf.Abs(rootScale.y) > 0.0001f ? 1f / rootScale.y : 1f,
                                    Mathf.Abs(rootScale.z) > 0.0001f ? 1f / rootScale.z : 1f);
                                box.center = root.transform.InverseTransformPoint(bounds.center);
                                box.size = Vector3.Max(Vector3.Scale(bounds.size * 1.02f, invScale), Vector3.one * (cs * 0.2f));

                                // MGO V12 silhouette: the cylinder heads + gantry make the
                                // TOP considerably wider than the slim crankcase/sea-chest
                                // bottom, so one full-bounds box walled the player ~1m off
                                // the model. Swap it for a two-piece banded hitbox:
                                //   lower band (bottom 55%) slim, upper band full width.
                                // Inside the same non-destructive gate, so hand-tuned
                                // colliders on the prefab survive subsequent Step-13 runs.
                                if (name.Contains("Engine_Giant"))
                                {
                                    Vector3 bCenter = root.transform.InverseTransformPoint(bounds.center);
                                    Vector3 bSize = Vector3.Max(Vector3.Scale(bounds.size * 1.02f, invScale), Vector3.one * (cs * 0.2f));
                                    if (box != null) Object.DestroyImmediate(box);

                                    const float lowerFraction = 0.55f;
                                    Vector3 lowerSize = new(bSize.x * 0.62f, bSize.y * lowerFraction, bSize.z * 0.92f);
                                    Vector3 upperSize = new(bSize.x, bSize.y * (1f - lowerFraction) + bSize.y * 0.04f, bSize.z);
                                    float minY = bCenter.y - bSize.y * 0.5f;
                                    Vector3 lowerCenter = new(bCenter.x, minY + lowerSize.y * 0.5f, bCenter.z);
                                    Vector3 upperCenter = new(bCenter.x, minY + bSize.y - upperSize.y * 0.5f, bCenter.z);

                                    // Find-or-create each band child, then fit its box with
                                    // EXPLICIT Unity null checks: freshly added components can
                                    // come back as dead wrappers during transient editor reloads
                                    // (this tool's own history shows it) — the C# ?? operator
                                    // does NOT honour Unity's object-lifetime semantics, which
                                    // is what threw MissingComponentException at .set_center.
                                    FitBandHitbox(root.transform, "Hitbox_Lower", lowerCenter, lowerSize);
                                    FitBandHitbox(root.transform, "Hitbox_Upper", upperCenter, upperSize);

                                    box = null; // the two bands carry all collision now
                                }
                            }
                            else if (box != null)
                            {
                                box.center = Vector3.zero;
                                box.size = new Vector3(cs, cs, cs);
                            }
                        }

                        var b = root.GetComponent<T>();
                        if (b == null) b = root.AddComponent<T>();

                        if (isNew) config?.Invoke(b);
                    }
                    finally { VoxelEngine.Maritime.MaritimeMeshBuilder.MaterialPersister = null; }
                });
                return prefab;
            }

            var recipes = new System.Collections.Generic.List<VoxelEngine.Crafting.RecipeDefinition>();
            VoxelEngine.Crafting.RecipeDefinition AddMRecipe(string name, string display,
                VoxelEngine.Items.ItemDefinition output, params (VoxelEngine.Items.ItemDefinition item, int n)[] inputs)
            {
                if (output == null) return null;
                string path = $"{RECIPES}/{name}.asset";
                bool existed = AssetDatabase.LoadAssetAtPath<VoxelEngine.Crafting.RecipeDefinition>(path) != null;
                var r = GetOrCreateAsset<VoxelEngine.Crafting.RecipeDefinition>(path);
                // Only populate fields on freshly-created recipes — never overwrite user edits.
                if (!existed)
                {
                    r.displayName = display; r.outputItem = output; r.outputCount = 1;
                    r.requiredStation = VoxelEngine.Crafting.StationTier.Assembler; r.craftSeconds = 4f; r.unlockedByDefault = false;
                    var valid = new System.Collections.Generic.List<VoxelEngine.Crafting.RecipeIngredient>();
                    foreach (var (item, n) in inputs) if (item != null) valid.Add(new VoxelEngine.Crafting.RecipeIngredient { item = item, count = n });
                    r.inputs = valid.ToArray();
                }
                EditorUtility.SetDirty(r);
                if (registry != null && !registry.recipes.Contains(r)) registry.recipes.Add(r);
                recipes.Add(r); return r;
            }

            // Remove stale Encased Chain Drive links from the active recipe registry
            // and research tree. The actual legacy assets are intentionally removed
            // by this breaking-content delivery; this repair also cleans projects
            // that still carry an old asset after a partial update.
            void RemoveEncasedChainDriveCatalogLinks()
            {
                var legacyRecipe = AssetDatabase.LoadAssetAtPath<VoxelEngine.Crafting.RecipeDefinition>(
                    $"{RECIPES}/Recipe_MEncasedChainDrive.asset");

                bool registryChanged = false;
                if (registry != null && registry.recipes != null)
                {
                    for (int i = registry.recipes.Count - 1; i >= 0; i--)
                    {
                        var candidate = registry.recipes[i];
                        // Once the deleted asset imports as a missing reference Unity
                        // presents it as null, so remove both that null and a still-live
                        // legacy reference during partial-update recovery.
                        if (candidate != null && (legacyRecipe == null || candidate != legacyRecipe)) continue;
                        registry.recipes.RemoveAt(i);
                        registryChanged = true;
                    }
                    if (registryChanged) EditorUtility.SetDirty(registry);
                }

                if (tree == null || tree.nodes == null) return;
                bool treeChanged = false;
                foreach (var node in tree.nodes)
                {
                    if (node == null || node.unlocksRecipes == null || node.unlocksRecipes.Length == 0) continue;
                    var retained = new List<VoxelEngine.Crafting.RecipeDefinition>(node.unlocksRecipes.Length);
                    bool nodeChanged = false;
                    foreach (var unlocked in node.unlocksRecipes)
                    {
                        if (unlocked == null || (legacyRecipe != null && unlocked == legacyRecipe))
                        {
                            nodeChanged = true;
                            continue;
                        }
                        if (!retained.Contains(unlocked)) retained.Add(unlocked);
                    }
                    if (!nodeChanged) continue;
                    node.unlocksRecipes = retained.ToArray();
                    EditorUtility.SetDirty(node);
                    treeChanged = true;
                }
                if (treeChanged) EditorUtility.SetDirty(tree);
            }

            VoxelEngine.Crafting.RecipeDefinition EnsureMechanicalBeltRecipe(VoxelEngine.Maritime.MechanicalBeltItem belt)
            {
                var recipe = AddMRecipe("Recipe_MMechanicalBelt", "Mechanical Belt", belt,
                    (ironPlate, 2), (ironGear, 1), (copperWire != null ? copperWire : copperIngot, 2));
                if (recipe == null) return null;

                // Repair only absent/wrong identity links. Existing numeric balance
                // (cost, craft time, output count) is left untouched on reruns.
                bool repaired = false;
                if (recipe.outputItem != belt) { recipe.outputItem = belt; repaired = true; }
                if (string.IsNullOrEmpty(recipe.displayName)) { recipe.displayName = "Mechanical Belt"; repaired = true; }
                if (recipe.outputCount <= 0) { recipe.outputCount = 1; repaired = true; }
                if (recipe.requiredStation != VoxelEngine.Crafting.StationTier.Assembler)
                {
                    recipe.requiredStation = VoxelEngine.Crafting.StationTier.Assembler;
                    repaired = true;
                }
                if (recipe.inputs == null || recipe.inputs.Length == 0)
                {
                    var inputs = new List<VoxelEngine.Crafting.RecipeIngredient>();
                    if (ironPlate != null) inputs.Add(new VoxelEngine.Crafting.RecipeIngredient { item = ironPlate, count = 2 });
                    if (ironGear != null) inputs.Add(new VoxelEngine.Crafting.RecipeIngredient { item = ironGear, count = 1 });
                    var wire = copperWire != null ? copperWire : copperIngot;
                    if (wire != null) inputs.Add(new VoxelEngine.Crafting.RecipeIngredient { item = wire, count = 2 });
                    recipe.inputs = inputs.ToArray();
                    repaired = true;
                }
                if (recipe.unlockedByDefault) { recipe.unlockedByDefault = false; repaired = true; }
                if (repaired) EditorUtility.SetDirty(recipe);
                return recipe;
            }

            void EnsureResearchUnlock(VoxelEngine.Research.ResearchNode node, VoxelEngine.Crafting.RecipeDefinition recipe)
            {
                if (node == null || recipe == null) return;
                var unlocks = new List<VoxelEngine.Crafting.RecipeDefinition>();
                bool repaired = false;
                if (node.unlocksRecipes != null)
                {
                    foreach (var existing in node.unlocksRecipes)
                    {
                        if (existing == null) { repaired = true; continue; }
                        if (unlocks.Contains(existing)) { repaired = true; continue; }
                        unlocks.Add(existing);
                    }
                }
                if (!unlocks.Contains(recipe))
                {
                    unlocks.Add(recipe);
                    repaired = true;
                }
                if (!repaired) return;
                node.unlocksRecipes = unlocks.ToArray();
                EditorUtility.SetDirty(node);
            }

            var SzL = VoxelEngine.GridSystem.GridSize.Large;

            // Set description only if empty (idempotent — preserves user edits).
            void SetDesc(VoxelEngine.Items.ItemDefinition item, string desc)
            {
                if (item != null && string.IsNullOrEmpty(item.description))
                {
                    item.description = desc;
                    EditorUtility.SetDirty(item);
                }
            }

            // The grid liquid tank gains its named liquid ports so LIQUID pipes
            // magnet onto it (and liquid links form through the port rules).
            // NON-DESTRUCTIVE: ports are created only when missing.
            /// <summary>Find-or-create one band of the MGO's two-piece hitbox and fit
            /// its BoxCollider. Every access is null-guarded: Step 13 must never throw
            /// on transiently-stripped components — worst case the band is retried on
            /// the next run instead of aborting the whole content build.</summary>
            void FitBandHitbox(Transform rootTransform, string bandName, Vector3 center, Vector3 size)
            {
                if (rootTransform == null) return;
                var band = rootTransform.Find(bandName);
                if (band == null)
                {
                    var go = new GameObject(bandName);
                    go.transform.SetParent(rootTransform, false);
                    band = go.transform;
                }
                var bandBox = band.GetComponent<BoxCollider>();
                if (bandBox == null) bandBox = band.gameObject.AddComponent<BoxCollider>();
                if (bandBox == null) bandBox = band.GetComponent<BoxCollider>(); // transient re-fetch
                if (bandBox == null)
                {
                    Debug.LogWarning($"[VoxelEngineSetup] Could not fit '{bandName}' on '{rootTransform.name}' this run — retry Step 13 and it will be fitted then.");
                    return;
                }
                bandBox.center = center;
                bandBox.size = size;
            }

            // Classic-network presence on the big grid tank: the classic liquid pipe
            // graph can now link to it (five-lattice-cell cardinal endpoint rule) and
            // content mirrors both ways. Create/link only — never reconfigures an
            // adapter the user touched (non-destructive).
            void EnsureLiquidTankClassicBridge()
            {
                string path = $"{PREFABS}/LiquidTank_Large.prefab";
                var prefab = AssetDatabase.LoadAssetAtPath<GameObject>(path);
                if (prefab == null) return;
                var gridTank = prefab.GetComponent<VoxelEngine.GridSystem.GridLiquidTank>();
                if (gridTank == null) return;

                bool dirty = false;
                var adapter = prefab.GetComponent<VoxelEngine.GridSystem.LiquidTankClassicAdapter>();
                if (adapter == null)
                {
                    adapter = prefab.AddComponent<VoxelEngine.GridSystem.LiquidTankClassicAdapter>();
                    adapter.gridTank = gridTank;
                    adapter.capacityLitres = gridTank.capacity;
                    adapter.liquidType = gridTank.liquidType;
                    dirty = true;
                }
                else if (adapter.gridTank == null)
                {
                    adapter.gridTank = gridTank;
                    dirty = true;
                }
                if (dirty) PrefabUtility.SavePrefabAsset(prefab);
            }

            // Fill heat-seizure repair parts ONLY when the prefab doesn't have any
            // yet — never overwrites spare-part lists the user tuned by hand.
            void EnsureEngineRepairCost(GameObject prefab, params (VoxelEngine.Items.ItemDefinition item, int count)[] parts)
            {
                if (prefab == null) return;
                var engine = prefab.GetComponent<VoxelEngine.Maritime.GridMaritimeEngine>();
                if (engine == null) return;
                if (engine.repairCost != null && engine.repairCost.Length > 0) return;
                var list = new System.Collections.Generic.List<VoxelEngine.Maritime.GridMaritimeEngine.RepairPart>();
                foreach (var part in parts)
                    if (part.item != null)
                        list.Add(new VoxelEngine.Maritime.GridMaritimeEngine.RepairPart { item = part.item, count = part.count });
                if (list.Count == 0) return;
                engine.repairCost = list.ToArray();
                EditorUtility.SetDirty(engine);
                PrefabUtility.SavePrefabAsset(prefab);
            }

