            var turboLargePref = MakeMPref<VoxelEngine.Maritime.GridTurbocharger>("Turbocharger_Large", new Color(0.85f,0.82f,0.70f), Vector3.one * 1.5f, SzL,
                t => { t.tier = VoxelEngine.Maritime.TurboTier.Large; t.boostPerUnit = 0.25f; });
            var itemTurboLarge = MakeMItem("MItem_TurboLarge", "Large Turbocharger", new Color(0.88f,0.85f,0.72f), turboLargePref, SzL, 2400, 4200);
            AddMRecipe("Recipe_MTurboLarge", "Large Turbocharger", itemTurboLarge, (steelPlate, 8), (copperPlate, 6), (advCircuit, 4));

            // Gearbox — free-form ratio (typed number / slider in the panel, 0.25×–20×)
            var gearPref = MakeMPref<VoxelEngine.Maritime.GridGearbox>("Gearbox_Large", new Color(0.55f,0.50f,0.40f), Vector3.one, SzL,
                g => { g.gearRatio = 1.00f; g.maxOutputSpeed = 10000f; });
            var itemGear = MakeMItem("MItem_Gearbox", "Gearbox", new Color(0.55f,0.50f,0.40f), gearPref, SzL, 400, 500);
            AddMRecipe("Recipe_MGearbox", "Gearbox", itemGear, (ironPlate, 6), (ironGear, 8), (steelPlate, 2));

            // Maritime Generator
            var genPref = MakeMPref<VoxelEngine.Maritime.GridMaritimeGenerator>("MaritimeGenerator_Large", new Color(0.30f,0.50f,0.35f), Vector3.one, SzL,
                g => { g.maxRPM = 2400f; g.maxWattOutput = 500000f; g.bufferCapacityWh = 20000f; });
            var itemGen = MakeMItem("MItem_MaritimeGenerator", "Maritime Generator", new Color(0.30f,0.50f,0.35f), genPref, SzL, 3200, 5200);
            AddMRecipe("Recipe_MMaritimeGenerator", "Maritime Generator", itemGen, (ironPlate, 8), (copperWire, 12), (circuit, 4));

            // Electrical Propeller
            var ePropPref = MakeMPref<VoxelEngine.Maritime.GridElectricalPropeller>("EPropeller_Large", new Color(0.40f,0.55f,0.65f), Vector3.one, SzL,
                p => { p.propellerSize = 2f; p.maxRPM = 3000f; p.powerDrawWatts = 2000f; });
            var itemEProp = MakeMItem("MItem_EPropeller", "Electrical Propeller", new Color(0.40f,0.55f,0.65f), ePropPref, SzL, 500, 500);
            AddMRecipe("Recipe_MEPropeller", "Electrical Propeller", itemEProp, (steelPlate, 6), (copperWire, 8), (circuit, 4), (glass, 2));

            // Bilge Pump
            var bilgePref = MakeMPref<VoxelEngine.Maritime.GridBilgePump>("BilgePump_Large", new Color(0.20f,0.30f,0.45f), Vector3.one, SzL,
                b => { b.drainRate = 5f; b.drainRadiusCells = 4f; b.powerDrawWatts = 500f; });
            var itemBilge = MakeMItem("MItem_BilgePump", "Bilge Pump", new Color(0.20f,0.30f,0.45f), bilgePref, SzL, 200, 400);
            AddMRecipe("Recipe_MBilgePump", "Bilge Pump", itemBilge, (ironPlate, 4), (copperWire, 6), (circuit, 2));

            // Marine Water Pump
            var pumpPref = MakeMPref<VoxelEngine.Maritime.GridMarineWaterPump>("MarineWaterPump_Large", new Color(0.15f, 0.35f, 0.55f), Vector3.one, SzL,
                p => { p.pumpRate = 50f; p.bufferCapacity = 100f; p.powerDrawWatts = 200f; p.suctionDepth = 3f; });
            var itemPump = MakeMItem("MItem_MarineWaterPump", "Marine Water Pump", new Color(0.15f, 0.35f, 0.55f), pumpPref, SzL, 150, 350);
            AddMRecipe("Recipe_MMarineWaterPump", "Marine Water Pump", itemPump, (ironPlate, 4), (copperWire, 4), (ironGear, 2));

            // Ship Control Console (modern alternative to Helm)
            var consolePref = MakeMPref<VoxelEngine.Maritime.GridShipConsole>("ShipConsole_Large", new Color(0.15f, 0.18f, 0.22f), Vector3.one, SzL,
                c => { c.interactionRadius = 3f; });
            var itemConsole = MakeMItem("MItem_ShipConsole", "Ship Control Console", new Color(0.15f, 0.18f, 0.22f), consolePref, SzL, 200, 350);
            AddMRecipe("Recipe_MShipConsole", "Ship Control Console", itemConsole, (steelPlate, 6), (circuit, 4), (glass, 2), (copperWire, 4));

            // Helm
            var helmPref = MakeMPref<VoxelEngine.Maritime.GridHelm>("Helm_Large", new Color(0.45f,0.30f,0.15f), Vector3.one, SzL,
                h => { h.interactionRadius = 3f; });
            var itemHelm = MakeMItem("MItem_Helm", "Helm", new Color(0.45f,0.30f,0.15f), helmPref, SzL, 150, 300);
            AddMRecipe("Recipe_MHelm", "Helm", itemHelm, (plank, 6), (ironIngot, 2), (ironGear, 2));

            // ═══════════════════════════════════════════════════════════════
            //  ENGINE UPGRADE MODULES (socketed into engine/generator Module Slots)
            // ═══════════════════════════════════════════════════════════════
            VoxelEngine.Items.EngineModuleItem MakeEngineModule(
                string assetName, string display, Color tint, VoxelEngine.Items.EngineModuleKind kind,
                bool t1, bool t2, bool t3, bool gen,
                float outputBonus, float speedBonus, float fuelMod, float heatBonus,
                float dissipationMul, bool needsCoolant, float waterDraw,
                float smokeSpeedMul, bool dirtySmoke, string desc)
            {
                string path = $"{ITEMS}/{assetName}.asset";
                bool existed = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.EngineModuleItem>(path) != null;
                var m = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.EngineModuleItem>(path);
                if (m == null) { m = ScriptableObject.CreateInstance<VoxelEngine.Items.EngineModuleItem>(); AssetDatabase.CreateAsset(m, path); }
                // Only populate fields on freshly-created modules — never overwrite user edits.
                if (!existed)
                {
                    m.itemId = display.ToLowerInvariant().Replace(" ", "_").Replace("-", "_").Replace("/", "_").Replace("(", "").Replace(")", "");
                    m.displayName = display; m.iconTint = tint; m.category = "Maritime";
                    m.maxStack = 1; // exactly one module of each kind per block
                    m.description = desc;
                    m.moduleKind = kind;
                    m.worksOnTier1 = t1; m.worksOnTier2 = t2; m.worksOnTier3 = t3; m.worksOnGenerator = gen;
                    m.outputPowerBonus = outputBonus; m.speedCapBonus = speedBonus;
                    m.fuelUseModifier = fuelMod; m.heatGenerationBonus = heatBonus;
                    m.dissipationMultiplier = dissipationMul;
                    m.requiresActiveCoolant = needsCoolant; m.waterDrawLitresPerSec = waterDraw;
                    m.exhaustSmokeVelocityMul = smokeSpeedMul; m.dirtyExhaust = dirtySmoke;
                }
                EditorUtility.SetDirty(m);
                return m;
            }

            var itemModuleTurbo = MakeEngineModule("MItem_ModuleTurbo", "High-Flow Turbocharger", new Color(0.90f, 0.55f, 0.15f),
                VoxelEngine.Items.EngineModuleKind.HighFlowTurbocharger,
                t1: true, t2: true, t3: true, gen: false,
                outputBonus: 0.20f, speedBonus: 0.10f, fuelMod: 0.10f, heatBonus: 0.10f,
                dissipationMul: 1f, needsCoolant: false, waterDraw: 0f,
                smokeSpeedMul: 1.5f, dirtySmoke: false,
                desc: "High-flow compressor upgrade (T1/T2/T3 engines). +20% output power, +10% RPM cap per socketed module. Trade-off: +10% fuel use and visibly faster exhaust smoke. Socket into an engine's Module Slots (right-click the engine).");

            var itemModuleEfficiency = MakeEngineModule("MItem_ModuleEfficiency", "Efficiency Tuning Chip", new Color(0.30f, 0.85f, 0.60f),
                VoxelEngine.Items.EngineModuleKind.EfficiencyTuningChip,
                t1: false, t2: true, t3: true, gen: true,
                outputBonus: 0.40f, speedBonus: 0f, fuelMod: -0.15f, heatBonus: 0f,
                dissipationMul: 1f, needsCoolant: true, waterDraw: 0f,
                smokeSpeedMul: 1f, dirtySmoke: false,
                desc: "Precision injection/field tuning (T2/T3 engines + generators). +40% max output power, -15% fuel use. WARNING: unlocks a MANDATORY active-coolant requirement — without continuous coolant flow the block overheats within ~15 seconds.");

            var itemModuleInjectors = MakeEngineModule("MItem_ModuleInjectors", "Overclocked Fuel Injectors", new Color(0.85f, 0.25f, 0.20f),
                VoxelEngine.Items.EngineModuleKind.OverclockedFuelInjectors,
                t1: false, t2: true, t3: true, gen: false,
                outputBonus: 0.30f, speedBonus: 0.15f, fuelMod: 0.20f, heatBonus: 0.50f,
                dissipationMul: 1f, needsCoolant: false, waterDraw: 0f,
                smokeSpeedMul: 1.2f, dirtySmoke: true,
                desc: "Overclocked injection timing (T2/T3 engines). +30% output power, +15% speed cap. Trade-off: +50% heat generation, +20% fuel use, and dirty soot-black exhaust. Pair with a Super-Cooler Radiator Jacket.");

            var itemModuleRadiator = MakeEngineModule("MItem_ModuleRadiator", "Super-Cooler Radiator Jacket", new Color(0.25f, 0.60f, 0.95f),
                VoxelEngine.Items.EngineModuleKind.SuperCoolerRadiatorJacket,
                t1: false, t2: true, t3: true, gen: true,
                outputBonus: 0f, speedBonus: 0f, fuelMod: 0f, heatBonus: 0f,
                dissipationMul: 3f, needsCoolant: false, waterDraw: 2f,
                smokeSpeedMul: 1f, dirtySmoke: false,
                desc: "Water-jacketed radiator sleeve (T2/T3 engines + generators). +200% heat dissipation while running. Requires a CONTINUOUS fresh/sea water supply drawn from connected tanks (2 L/s per jacket) — keep a Marine Water Pump feeding the grid.");

            AddMRecipe("Recipe_MModuleTurbo", "High-Flow Turbocharger", itemModuleTurbo, (steelPlate, 4), (copperPlate, 4), (ironGear, 2), (circuit, 1));
            AddMRecipe("Recipe_MModuleEfficiency", "Efficiency Tuning Chip", itemModuleEfficiency, (advCircuit, 3), (circuit, 2), (copperWire, 6));
            AddMRecipe("Recipe_MModuleInjectors", "Overclocked Fuel Injectors", itemModuleInjectors, (steelPlate, 3), (ironGear, 3), (circuit, 2), (copperWire, 2));
            var itemModuleAip = MakeEngineModule("MItem_ModuleAip", "Closed-Cycle AIP Module", new Color(0.65f, 0.85f, 0.95f),
                VoxelEngine.Items.EngineModuleKind.AirIndependentPropulsionLoop,
                t1: true, t2: true, t3: true, gen: false,
                outputBonus: 0f, speedBonus: 0f, fuelMod: 0.05f, heatBonus: 0f,
                dissipationMul: 1f, needsCoolant: false, waterDraw: 0f,
                smokeSpeedMul: 1f, dirtySmoke: false,
                desc: "Air-Independent Propulsion loop (all engine tiers) — the engine NO LONGER needs an external oxygen supply. Why it works: a magazine of solid chlorate oxygen candles thermally decomposes on demand, releasing chemically-bound O2 (the same reaction that airs submarine crews and space stations); a closed exhaust-recirculation loop with a regenerative CO2 scrubber strips the burn products and returns the un-consumed oxygen fraction to the intake, so the combustion cycle carries its own oxidiser instead of breathing the room. Trade-off: +5% fuel use (chemical oxygen has mass). History: the closed-cycle diesel let hunter submarines run for weeks without surfacing.");

            AddMRecipe("Recipe_MModuleRadiator", "Super-Cooler Radiator Jacket", itemModuleRadiator, (copperPlate, 6), (steelPlate, 3), (glass, 2), (copperWire, 2));
            AddMRecipe("Recipe_MModuleAip", "Closed-Cycle AIP Module", itemModuleAip, (steelPlate, 4), (advCircuit, 2), (copperWire, 4), (glass, 2));

            // Grid tank port markers are authored by Step 12 where the grid tank
            // prefabs are generated. Do not create primitive port objects here — doing
            // so from the maritime pass can leak scene objects when the prefab asset is
            // not opened through PrefabUtility.LoadPrefabContents. Keep only the classic
            // liquid bridge repair here.
            EnsureLiquidTankClassicBridge();

            // ── Item descriptions (only set if empty — preserves user edits) ──
            SetDesc(itemUntWood, "Buoyant starter hull. Absorbs water over time while submerged, gradually increasing mass and sinking the ship lower. Research Tar-Coated Plank for waterproof voyages.");
            SetDesc(itemTar, "100% waterproof hull. Never waterlogs. The reliable mid-game hull material for ocean voyages. Slightly more durable than untreated wood.");
            SetDesc(itemIronHull, "Zero natural buoyancy - sinks! Extremely heavy but with insane HP (5x). Requires massive internal air-pocket chambers to displace enough water to float. Late-game armored warship hull.");
            SetDesc(itemBalsa, "Ultra-light, maximally buoyant, but fragile (0.4x HP). Perfect for lifeboats, buoys, outrigger stabilizers, and floatation aids.");
            SetDesc(itemWheel, "3x3x1 cast-iron waterwheel with oak paddles. DUAL-MODE: Generates torque from water current when stationary, OR produces paddle thrust when driven by a shaft on a moving ship. Place in flowing water.");
            SetDesc(itemShaft, "Drive shaft that transmits rotational torque from an engine to a propeller, gearbox, or generator. If a shaft is disabled or destroyed, the propulsion chain downstream stops. Chain blocks together engine-first.");
            SetDesc(itemRotTransfer, "Rotation Transfer casing. Carries shaft RPM like a drive shaft while visually routing rotation straight, up, or down. Rotate the block while placing to turn the route left/right.");
            SetDesc(itemShaftHousing, "Watertight Shaft Housing. A sealed hull block with a rotating through-shaft, twin compression seals, and direct shaft ports. Use it where a drivetrain crosses the wet hull so the mechanical line remains protected from seawater.");
            SetDesc(itemMechanicalBelt, "Mechanical Belt. Hold it, right-click one parallel shaft pulley, then right-click another shaft on the same ship to install a belt. Place aligned shafts through the belt run to create additional take-off outputs. Shift-right-click a shaft to remove and recover its attached belts.");
            SetDesc(itemShipContainer, "Maritime shipping container storage. Styled like a real intermodal container and carries 5x the mass of a Large Cargo Container.");
            SetDesc(itemPropS, "3-blade cast bronze propeller (detail-scale). Low thrust but highly maneuverable. Consumes shaft torque through its movable Rotation input point 0 mount. Place below the waterline facing the direction you want to push.");
            SetDesc(itemPropL, "4-blade heavy steel industrial propeller. Extreme thrust with a movable Rotation input point 0 mount for shaft/chain-drive alignment. Built for big ship drivetrains and visible cavitation under load.");
            SetDesc(itemExhaust, "Exhaust venting pipe. EVERY engine requires at least one adjacent exhaust pipe or it chokes and produces zero torque. The pipe vents exhaust gas buildup and emits visible smoke particles while engines run.");
            SetDesc(itemEngS, "Crude Inline-4 Engine (starter 1x1x1 large-grid block). FUEL: Wood Logs / Planks / Coal. Chipped blue-green cast-iron block with four open-air pistons, exposed pushrods and an open-frame crankshaft. Produces rotational force into a shaft - not direct electricity. Solid-fuel hopper, 1 Small Turbocharger socket, 2 upgrade-Module slots. Requires an adjacent Exhaust Pipe. Watch the temperature: knocking above 90°C, mechanical failure at 100°C.");
            SetDesc(itemEngM, "Heavy Fuel Oil V8 Engine (~4x2x2 m). FUEL: Heavy Fuel Oil. Faded yellow V-block with glass-paneled inspection windows, a valley intake plenum and steam-heated fuel filters. 3 upgrade-Module slots, 2 turbo flanges. Requires coolant and an adjacent Exhaust Pipe. Watch the temperature: knocking above 90°C, mechanical failure at 100°C.");
            SetDesc(itemEngG, "MGO Marine V12 Engine (~8x4x3 m flagship). FUEL: Marine Gas Oil / MGO. Anodized red/silver precision diesel with armored quartz viewports, gantry walkways, a belt-driven seawater pump and a massive splined PTO shaft. 4 upgrade-Module slots, 4 turbo mounts. Requires coolant and adjacent exhaust. Watch the temperature: knocking above 90°C, mechanical failure at 100°C.");
            SetDesc(itemTurboSmall, "Small Ship Turbocharger. Boosts an engine by +15% torque only when mounted on a named Turbo attachment point. Compact industrial compressor housing for crude and medium ship engines.");
            SetDesc(itemTurboLarge, "Large Ship Turbocharger. Boosts an engine by +25% torque only when mounted on a named Turbo attachment point. Huge industrial compressor for medium and giant ship engines.");
            SetDesc(itemGear, "Industrial 20-speed gearbox. Trades torque for RPM in ALL directions - power can enter from either side and the opposite side automatically becomes the output. 20 selectable ratios (0.25x torque gears to 6.00x speed gears), gear changes apply live. Speed is hard-clamped at 10000 RPM to prevent runaway gearing. Place between an engine and a propeller or shaft generator.");
            SetDesc(itemGen, "Maritime shaft generator. Converts rotational force from a shaft into electricity. More RPM = more power. Best used after a gearbox when gearing up speed into the generator. Contains a small internal battery buffer.");
            SetDesc(itemEProp, "Electrical propeller (2x2x1). Torpedo-shaped bronze pod with a sleek 3-blade propeller. Driven by electricity from the grid (not shaft torque). Medium thrust with fast spin-up. Heavy armored power conduit.");
            SetDesc(itemBilge, "Bilge pump. Consumes electricity to drain waterlogged mass from nearby hull blocks within a 4-cell radius. Essential for surviving hull breaches and mega-storms on untreated-wood ships. Heavy, no buoyancy.");
            SetDesc(itemPump, "Marine Water Pump. Must be placed at or below the waterline to operate. Sucks seawater into an internal buffer, then pushes it into connected Water tanks. Used to supply engine coolant (Water) for HFO and MGO engines. Draws power from the grid.");
            SetDesc(itemConsole, "Ship Control Console — a modern bridge station with twin throttle levers, radar display, and a compact steering wheel. Right-click to enter. Behaves like a cockpit for spaceships and also drives maritime throttle/rudder. V toggles camera, Alt freelook, Exit Cockpit leaves. Tier 3+");
            SetDesc(itemHelm, "Ship's wheel / helm. Right-click to enter a third-person camera view above the helm. W = throttle up, S = throttle down, A/D = steer left/right. V toggles camera, Alt freelook, Exit Cockpit leaves. Drives the ship's MaritimePropulsionSystem (engines + rudder).");


            // ═══════════════════════════════════════════════════════════════
            //  RESEARCH TREE — "Maritime Engineering" (4 tiers)
            // ═══════════════════════════════════════════════════════════════
            if (tree != null)
            {
                // Prereq chain: Shipbuilding must exist (created in Step 12).
                var nShip = FindNodeByName(tree, "res_shipbuilding");

                VoxelEngine.Research.ResearchNode MakeMaritimeNode(
                    string id, string display, string desc, int tier, int col,
                    float seconds, (VoxelEngine.Items.ScienceItem p, int n)[] cost,
                    VoxelEngine.Crafting.RecipeDefinition[] unlocks,
                    VoxelEngine.Research.ResearchNode[] prereqs)
                {
                    string path = $"{NODES}/{id}.asset";
                    bool existed = AssetDatabase.LoadAssetAtPath<VoxelEngine.Research.ResearchNode>(path) != null;
                    var n = AssetDatabase.LoadAssetAtPath<VoxelEngine.Research.ResearchNode>(path);
                    if (n == null) { n = ScriptableObject.CreateInstance<VoxelEngine.Research.ResearchNode>(); AssetDatabase.CreateAsset(n, path); }
                    // Only populate fields on freshly-created nodes — never overwrite user edits.
                    if (!existed)
                    {
                        n.nodeId = id; n.displayName = display; n.description = desc;
                        n.category = VoxelEngine.Research.ResearchCategory.Environment;
                        n.subCategory = VoxelEngine.Research.ResearchSubCategory.Building;
                        n.tier = tier; n.column = col;
                        n.iconTint = new Color(0.2f, 0.5f, 0.8f);
                        n.researchSeconds = seconds;
                        n.cost = new VoxelEngine.Research.ResearchNode.ScienceCost[cost.Length];
                        for (int i = 0; i < cost.Length; i++)
                            n.cost[i] = new VoxelEngine.Research.ResearchNode.ScienceCost { pack = cost[i].p, count = cost[i].n };
                        n.unlocksRecipes = unlocks ?? new VoxelEngine.Crafting.RecipeDefinition[0];
                        n.prerequisites = prereqs ?? new VoxelEngine.Research.ResearchNode[0];
                        n.upgradeKind = VoxelEngine.Research.PlayerUpgradeKind.None;
                        n.maxRanks = 1;
                    }
                    else if (unlocks != null && unlocks.Length > 0)
                    {
                        var merged = new List<VoxelEngine.Crafting.RecipeDefinition>();
                        if (n.unlocksRecipes != null)
                        {
                            for (int i = 0; i < n.unlocksRecipes.Length; i++)
                                if (n.unlocksRecipes[i] != null && !merged.Contains(n.unlocksRecipes[i]))
                                    merged.Add(n.unlocksRecipes[i]);
                        }
                        for (int i = 0; i < unlocks.Length; i++)
                            if (unlocks[i] != null && !merged.Contains(unlocks[i]))
                                merged.Add(unlocks[i]);
                        n.unlocksRecipes = merged.ToArray();
                    }
                    EditorUtility.SetDirty(n);
                    if (!tree.nodes.Contains(n)) tree.nodes.Add(n);
                    return n;
                }

                // Tier 1: Hydro-Mechanics (waterwheel, shafts/belts, sealed hull drives, small propeller, helm)
                var t1 = MakeMaritimeNode("res_maritime_hydromech", "Hydro-Mechanics",
                    "Master water power. Unlocks the Waterwheel, Drive Shaft, Rotation Transfer, Watertight Shaft Housing, Mechanical Belt, Untreated Wood hull, Small Propeller, and the Helm.",
                    1, 6, 40f, new[] { (sciT2, 10) },
                    recipes.FindAll(r => r != null && (r.name.Contains("Waterwheel") || r.name.Contains("DriveShaft") || r.name.Contains("RotationTransfer") || r.name.Contains("ShaftHousing") || r.name.Contains("MechanicalBelt") || r.name.Contains("UntreatedWood") || r.name.Contains("PropSmall") || r.name.Contains("Helm") || r.name.Contains("Exhaust"))).ToArray(),
                    nShip != null ? new[] { nShip } : null);
                // Targeted migration of the setup-generated legacy wording only;
                // custom research descriptions remain untouched.
                if (t1 != null && !string.IsNullOrEmpty(t1.description) && t1.description.Contains("Encased Chain Drive"))
                {
                    t1.description = "Master water power. Unlocks the Waterwheel, Drive Shaft, Rotation Transfer, Watertight Shaft Housing, Mechanical Belt, Untreated Wood hull, Small Propeller, and the Helm.";
                    EditorUtility.SetDirty(t1);
                }
                // Explicit repair: the Mechanical Belt is always gated by Tier 1
                // Hydro-Mechanics, including projects whose node already existed.
                EnsureResearchUnlock(t1, recipeMechanicalBelt);

                // Tier 2: Steam & Internal Combustion (Small Engine, Exhaust, Tar Plank, Balsa, Gearbox)
                var t2 = MakeMaritimeNode("res_maritime_combustion", "Steam & Internal Combustion",
                    "Harness fire. Unlocks the Small Engine, Exhaust Pipe, Tar-Coated Plank, Balsa Wood, and Gearbox.",
                    2, 6, 80f, new[] { (sciT2, 20), (sciT3, 5) },
                    recipes.FindAll(r => r != null && (r.name.Contains("EngineSmall") || r.name.Contains("Exhaust") || r.name.Contains("TarPlank") || r.name.Contains("Balsa") || r.name.Contains("Gearbox"))).ToArray(),
                    new[] { t1 });

                // Tier 3: Heavy Industrial Maritime (Medium Engine, Iron Hull, Shipping Container, Bilge Pump, Generator, E-Propeller)
                var t3 = MakeMaritimeNode("res_maritime_heavy", "Heavy Industrial Maritime",
                    "Steel and steam. Unlocks the Medium Engine, Iron Hull, Shipping Container, Bilge Pump, Maritime Generator, and Electrical Propeller.",
                    3, 6, 120f, new[] { (sciT2, 30), (sciT3, 15) },
                    recipes.FindAll(r => r != null && (r.name.Contains("EngineMedium") || r.name.Contains("IronHull") || r.name.Contains("ShippingContainer") || r.name.Contains("Bilge") || r.name.Contains("Generator") || r.name.Contains("EPropeller"))).ToArray(),
                    new[] { t2 });

                // Tier 4: MSC Loreto-class Propulsion (Giant Diesel, Turbocharger, Large Propeller)
                var t4 = MakeMaritimeNode("res_maritime_loreto", "MSC Loreto-class Propulsion",
                    "The pinnacle of maritime engineering. Unlocks the Giant Diesel Engine, Turbocharger, and Large Propeller.",
                    4, 6, 200f, new[] { (sciT3, 40) },
                    recipes.FindAll(r => r != null && (r.name.Contains("EngineGiant") || r.name.Contains("Turbocharger") || r.name.Contains("PropLarge"))).ToArray(),
                    new[] { t3 });

                // Tier 5: Maritime Performance Tuning (engine/generator upgrade modules)
                MakeMaritimeNode("res_maritime_tuning", "Maritime Performance Tuning",
                    "Push machinery past factory limits. Unlocks the four engine upgrade Module recipes: High-Flow Turbocharger, Efficiency Tuning Chip, Overclocked Fuel Injectors, and Super-Cooler Radiator Jacket. Modules socket into Module Slots on engines and generators - greater power demands greater cooling.",
                    5, 6, 260f, new[] { (sciT3, 60) },
                    recipes.FindAll(r => r != null && r.name.Contains("Module")).ToArray(),
                    new[] { t4 });

                EditorUtility.SetDirty(tree);
            }

            // -- MaritimeSettings asset --
            {
                string settingsPath = $"{MAR_ROOT}/MaritimeSettings.asset";
                var ms = AssetDatabase.LoadAssetAtPath<VoxelEngine.Maritime.MaritimeSettings>(settingsPath);
                if (ms == null)
                {
                    ms = ScriptableObject.CreateInstance<VoxelEngine.Maritime.MaritimeSettings>();
                    AssetDatabase.CreateAsset(ms, settingsPath);
                }
                ms.buoyancyGain = Mathf.Clamp(ms.buoyancyGain <= 0f ? 1.0f : ms.buoyancyGain, 0.85f, 1.15f);
                ms.buoyancyReserve = Mathf.Clamp(ms.buoyancyReserve <= 0f ? 1.6f : ms.buoyancyReserve, 1.35f, 1.75f);
                EditorUtility.SetDirty(ms);
            }

            // Runtime persistence catalog keeps inventory-only equipment assets
            // resolvable on login, including Portable Batteries and H₂ Tanks.
            EnsureItemPersistenceCatalog();
            if (registry != null) EditorUtility.SetDirty(registry);
            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();

            EditorUtility.DisplayDialog("Voxel Engine - Step 13",
                $"Maritime content built!\n\n" +
                $"BLOCKS ({recipes.Count} prefabs + items + recipes):\n" +
                "  Hull: Untreated Wood, Tar Plank, Iron Hull, Balsa Wood\n" +
                "  Propulsion: Waterwheel, Drive Shaft, Rotation Transfer, Watertight Shaft Housing, Mechanical Belt, Small/Large Propeller, Exhaust, Crude Inline-4 / HFO V8 / MGO V12 Engines, Turbocharger, free-ratio Gearbox (0.25×–20×), Generator, E-Propeller, Bilge Pump, Helm\n" +
                "  Modules: High-Flow Turbocharger, Efficiency Tuning Chip, Overclocked Fuel Injectors, Super-Cooler Radiator Jacket\n" +
                "  Storage: Shipping Container (5x Large Cargo capacity)\n\n" +
                "RESEARCH TREE (5-tier Maritime Engineering):\n" +
                "  T1: Hydro-Mechanics\n" +
                "  T2: Steam & Internal Combustion\n" +
                "  T3: Heavy Industrial Maritime\n" +
                "  T4: MSC Loreto-class Propulsion\n" +
                "  T5: Maritime Performance Tuning (upgrade modules)\n\n" +
                "NOTE: v26 rebuilds the Watertight Shaft Housing plus current shaft/gearbox/generator port visuals in place\n" +
                "and engines retain their heat-seizure repair costs (spare parts from their own recipe).\n" +
                "Mesh version auto-upgrades all other prefabs in place.\n" +
                "MaritimeSettings asset created in Maritime/.\n" +
                "All recipes gated behind the research tree.",
                "OK");
        }


        // ============================================================
        //                STEP 14 - FLOODLIGHT CONTENT
        // ============================================================
        private void BuildFloodlightContent()
        {
            const string floodFolder    = ASSET_ROOT + "/Power/Floodlights";
            const string prefabsFolder  = floodFolder + "/Prefabs";
            const string itemsFolder    = floodFolder + "/Items";
            const string recipesFolder  = floodFolder + "/Recipes";

            EnsureFolder(floodFolder);
            EnsureFolder(prefabsFolder);
            EnsureFolder(itemsFolder);
            EnsureFolder(recipesFolder);

            // -- Dependencies --
            string commonItems = ASSET_ROOT + "/Items";
            var ironIngot = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{commonItems}/Item_IronIngot.asset");
            var copperWire = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{commonItems}/Item_CopperWire.asset");
            var glass = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{ASSET_ROOT}/Industrial/Items/Item_Glass.asset");
            if (ironIngot == null || copperWire == null || glass == null)
            {
                EditorUtility.DisplayDialog("Voxel Engine", "Run Steps 4 and 10 (Industrial Content) first.", "OK");
                return;
            }

            var registry = AssetDatabase.LoadAssetAtPath<VoxelEngine.Crafting.RecipeRegistry>($"{ASSET_ROOT}/RecipeRegistry.asset");
            var tree = AssetDatabase.LoadAssetAtPath<VoxelEngine.Research.ResearchTree>($"{ASSET_ROOT}/Research/ResearchTree.asset");

            // -- 1) Stationary Floodlight --
            string statPath = $"{prefabsFolder}/Floodlight_Stationary.prefab";
            var statRoot = new GameObject("Floodlight_Stationary");
            // Base pole
            var pole = GameObject.CreatePrimitive(PrimitiveType.Cylinder);
            pole.transform.SetParent(statRoot.transform, false);
            pole.transform.localScale = new Vector3(0.2f, 2f, 0.2f);
            pole.transform.localPosition = new Vector3(0, 1f, 0);
            pole.GetComponent<Renderer>().sharedMaterial = MakeColoredMat(prefabsFolder, "Mat_FloodPole", new Color(0.4f, 0.4f, 0.45f));
            // Head
            var head = GameObject.CreatePrimitive(PrimitiveType.Cube);
            head.transform.SetParent(statRoot.transform, false);
            head.transform.localScale = new Vector3(0.5f, 0.2f, 0.5f);
            head.transform.localPosition = new Vector3(0, 2f, 0);
            head.GetComponent<Renderer>().sharedMaterial = MakeColoredMat(prefabsFolder, "Mat_FloodHead", new Color(0.6f, 0.6f, 0.65f));
            // Light
            var lightGo = new GameObject("LightSource");
            lightGo.transform.SetParent(head.transform, false);
            lightGo.transform.localPosition = new Vector3(0, -0.11f, 0);
            var light = lightGo.AddComponent<Light>();
            light.type = LightType.Spot;
            light.intensity = 20f;
            light.range = 20f;
            light.spotAngle = 45f;
            light.color = Color.white;

            var statFlood = statRoot.AddComponent<VoxelEngine.Power.Floodlight>();
            statFlood.lightComponent = light;
            var statCons = statRoot.AddComponent<VoxelEngine.Power.PowerConsumer>();
            statCons.wattsPerSecond = 50f;
            statCons.connectRadius = 1.8f;

            var statPrefab = PrefabUtility.SaveAsPrefabAsset(statRoot, statPath);
            Object.DestroyImmediate(statRoot);

            var statItem = MakeBlock(itemsFolder, "Block_Floodlight_Stationary", "Stationary Floodlight", new Color(0.7f, 0.7f, 0.75f), statPrefab, "Power");
            statItem.description = "A powerful outdoor light. Consumes 50 W. Only glows when powered.";

            // -- 2) Grid Floodlight --
            string gridPath = $"{prefabsFolder}/Floodlight_Grid.prefab";
            var gridRoot = GetOrCreatePrefab(gridPath, "Floodlight_Grid", (root) =>
            {
                VoxelEngine.GridSystem.GridBlockMeshBuilder.Build(root, VoxelEngine.GridSystem.GridBlockMeshBuilder.Style.Generic, VoxelEngine.GridSystem.GridSize.Small, new Color(0.6f, 0.6f, 0.65f));
                var lightGo = new GameObject("LightSource");
                lightGo.transform.SetParent(root.transform, false);
                lightGo.transform.localPosition = new Vector3(0, 0.51f, 0);
                var light = lightGo.AddComponent<Light>();
                light.type = LightType.Spot;
                light.intensity = 20f;
                light.range = 20f;
                light.spotAngle = 60f;
                light.color = Color.white;

                var flood = root.AddComponent<VoxelEngine.Power.VoxelLightController>();
                flood.lightComponent = light;
                flood.intensity = 20f;
                var cons = root.AddComponent<VoxelEngine.Power.PowerConsumer>();
                cons.wattsPerSecond = 50f;
                cons.connectRadius = 1.6f;
            });

            var gridItem = MakeBlock(itemsFolder, "Block_Floodlight_Grid", "Grid Floodlight", new Color(0.7f, 0.7f, 0.75f), gridRoot, "Power");
            gridItem.description = "Grid-mountable floodlight. Consumes 50 W. Only glows when powered.";

            // -- 3) LED Strip Light --
            string ledPath = $"{prefabsFolder}/LEDStrip_Stationary.prefab";
            var ledRoot = new GameObject("LEDStrip_Stationary");
            var stripMesh = GameObject.CreatePrimitive(PrimitiveType.Cube);
            stripMesh.transform.SetParent(ledRoot.transform, false);
            stripMesh.transform.localScale = new Vector3(2f, 0.1f, 0.1f);
            stripMesh.GetComponent<Renderer>().sharedMaterial = MakeColoredMat(prefabsFolder, "Mat_LEDStrip", new Color(0.9f, 0.9f, 0.9f));

            var ledLightGo = new GameObject("LEDLight");
            ledLightGo.transform.SetParent(ledRoot.transform, false);
            ledLightGo.transform.localPosition = new Vector3(0, 0.1f, 0);
            var ledLight = ledLightGo.AddComponent<Light>();
            ledLight.type = LightType.Point;
            ledLight.range = 5f;
            ledLight.intensity = 5f;
            ledLight.color = Color.cyan;

            var ledCtrl = ledRoot.AddComponent<VoxelEngine.Power.VoxelLightController>();
            ledCtrl.lightComponent = ledLight;
            ledCtrl.lightColor = Color.cyan;
            ledCtrl.intensity = 5f;
            var ledCons = ledRoot.AddComponent<VoxelEngine.Power.PowerConsumer>();
            ledCons.wattsPerSecond = 10f;
            ledCons.connectRadius = 1.8f;

            var ledPrefab = PrefabUtility.SaveAsPrefabAsset(ledRoot, ledPath);
            Object.DestroyImmediate(ledRoot);

            var ledItem = MakeBlock(itemsFolder, "Block_LEDStrip", "LED Strip Light", new Color(0, 1, 1), ledPrefab, "Power");
            ledItem.description = "A thin LED strip. Low power (10 W). Supports color changes.";

            // -- 4) RGB Light --
            string rgbPath = $"{prefabsFolder}/RGB_Light.prefab";
            var rgbRoot = new GameObject("RGB_Light");
            var rgbMesh = GameObject.CreatePrimitive(PrimitiveType.Cube);
            rgbMesh.transform.SetParent(rgbRoot.transform, false);
            rgbMesh.transform.localScale = new Vector3(0.3f, 0.3f, 0.3f);
            rgbMesh.GetComponent<Renderer>().sharedMaterial = MakeColoredMat(prefabsFolder, "Mat_RGB", Color.white);

            var rgbLightGo = new GameObject("RGBLight");
            rgbLightGo.transform.SetParent(rgbRoot.transform, false);
            var rgbLight = rgbLightGo.AddComponent<Light>();
            rgbLight.type = LightType.Point;
            rgbLight.range = 10f;
            rgbLight.intensity = 15f;
            rgbLight.color = Color.magenta;

            var rgbCtrl = rgbRoot.AddComponent<VoxelEngine.Power.VoxelLightController>();
            rgbCtrl.lightComponent = rgbLight;
            rgbCtrl.lightColor = Color.magenta;
            rgbCtrl.intensity = 15f;
            var rgbCons = rgbRoot.AddComponent<VoxelEngine.Power.PowerConsumer>();
            rgbCons.wattsPerSecond = 20f;
            rgbCons.connectRadius = 1.8f;

            var rgbPrefab = PrefabUtility.SaveAsPrefabAsset(rgbRoot, rgbPath);
            Object.DestroyImmediate(rgbRoot);

            var rgbItem = MakeBlock(itemsFolder, "Block_RGB_Light", "RGB Mood Light", new Color(1, 0, 1), rgbPrefab, "Power");
            rgbItem.description = "Small RGB light. Change colors via the Lighting UI. Consumes 20 W.";

            // -- 5) Recipes --
            VoxelEngine.Crafting.RecipeDefinition AddRec(string name, string display, VoxelEngine.Items.ItemDefinition output, params (VoxelEngine.Items.ItemDefinition item, int n)[] inputs)
            {
                string path = $"{recipesFolder}/{name}.asset";
                var r = GetOrCreateAsset<VoxelEngine.Crafting.RecipeDefinition>(path);
                r.displayName = display; r.outputItem = output; r.outputCount = 1;
                r.requiredStation = VoxelEngine.Crafting.StationTier.Assembler; r.craftSeconds = 4f; r.unlockedByDefault = false;
                var valid = new System.Collections.Generic.List<VoxelEngine.Crafting.RecipeIngredient>();
                foreach (var (item, n) in inputs) if (item != null) valid.Add(new VoxelEngine.Crafting.RecipeIngredient { item = item, count = n });
                r.inputs = valid.ToArray();
                EditorUtility.SetDirty(r);
                if (registry != null && !registry.recipes.Contains(r)) registry.recipes.Add(r);
                return r;
            }

            var recStat = AddRec("Recipe_Floodlight_Stationary", "Stationary Floodlight", statItem, (ironIngot, 2), (copperWire, 4), (glass, 1));
            var recGrid = AddRec("Recipe_Floodlight_Grid", "Grid Floodlight", gridItem, (ironIngot, 2), (copperWire, 4), (glass, 1));
            var recLed  = AddRec("Recipe_LEDStrip", "LED Strip Light", ledItem, (copperWire, 8), (glass, 2));
            var recRgb  = AddRec("Recipe_RGB_Light", "RGB Mood Light", rgbItem, (copperWire, 8), (glass, 1), (ironIngot, 1));

            // -- 6) Research --
            if (tree != null)
            {
                var nElec = FindNodeByName(tree, "res_electricity");
                VoxelEngine.Research.ResearchNode nLighting;
                {
                    string path = $"{ASSET_ROOT}/Research/Nodes/res_floodlighting.asset";
                    nLighting = GetOrCreateAsset<VoxelEngine.Research.ResearchNode>(path);
                    nLighting.nodeId = "res_floodlighting";
                    nLighting.displayName = "Advanced Lighting";
                    nLighting.description = "High-intensity and decorative lighting for industrial sites and ships.";
                    nLighting.category = VoxelEngine.Research.ResearchCategory.Environment;
                    nLighting.subCategory = VoxelEngine.Research.ResearchSubCategory.Production;
                    nLighting.tier = 2; nLighting.column = 8;
                    nLighting.iconTint = new Color(1f, 1f, 0.8f);
                    nLighting.researchSeconds = 40f;
                    nLighting.cost = new[] { new VoxelEngine.Research.ResearchNode.ScienceCost { pack = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ScienceItem>($"{commonItems}/Item_ScienceT1.asset"), count = 10 },
                                            new VoxelEngine.Research.ResearchNode.ScienceCost { pack = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ScienceItem>($"{commonItems}/Item_ScienceT2.asset"), count = 5 } };
                    nLighting.unlocksRecipes = new[] { recStat, recGrid, recLed, recRgb };
                    nLighting.prerequisites = nElec != null ? new[] { nElec } : null;
                    EditorUtility.SetDirty(nLighting);
                    if (!tree.nodes.Contains(nLighting)) tree.nodes.Add(nLighting);
                }
                EditorUtility.SetDirty(tree);
            }

            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();
            EditorUtility.DisplayDialog("Voxel Engine", "Lighting content created!\n\n- Floodlights, LED Strips, RGB Lights\n- Recipes\n- 'Advanced Lighting' research node", "OK");
        }

        // ============================================================
        //                STEP 15 - WIND POWER CONTENT (modular 4.0)
        // ============================================================
        // ============================================================
        //       STEP 17 - FACTORY FOUNDATIONS + HIGH VOLTAGE GRID
        // ============================================================
        private void BuildFactoryFoundationsContent()
        {
            const string FAC_ROOT     = ASSET_ROOT + "/Factory";
            const string FAC_PREFABS  = FAC_ROOT + "/Prefabs";
            const string FAC_MATS     = FAC_PREFABS + "/Materials";
            const string FAC_ITEMS    = FAC_ROOT + "/Items";
            const string FAC_RECIPES  = FAC_ROOT + "/Recipes";
            const string FAC_DEFS     = FAC_ROOT + "/Definitions";
            const string FAC_MRECIPES = FAC_ROOT + "/MachineRecipes";
            const string HV_ROOT      = ASSET_ROOT + "/HighVoltage";
            const string HV_PREFABS   = HV_ROOT + "/Prefabs";
            const string HV_MATS      = HV_PREFABS + "/Materials";
            const string HV_ITEMS     = HV_ROOT + "/Items";
            const string HV_RECIPES   = HV_ROOT + "/Recipes";
            const string GRID_ROOT    = ASSET_ROOT + "/GridSystem";
            const string GRID_PREFABS = GRID_ROOT + "/Prefabs";
            const string GRID_MATS    = GRID_PREFABS + "/Mats";
            const string GRID_ITEMS   = GRID_ROOT + "/Items";
            const string GRID_RECIPES = GRID_ROOT + "/Recipes";
            const string NODES        = ASSET_ROOT + "/Research/Nodes";
            const string RESOURCES    = "Assets/Resources";

            foreach (var f in new[]
            {
                FAC_ROOT, FAC_PREFABS, FAC_MATS, FAC_ITEMS, FAC_RECIPES, FAC_DEFS, FAC_MRECIPES,
                HV_ROOT, HV_PREFABS, HV_MATS, HV_ITEMS, HV_RECIPES,
                GRID_ROOT, GRID_PREFABS, GRID_MATS, GRID_ITEMS, GRID_RECIPES,
                NODES, RESOURCES
            })
            {
                EnsureFolder(f);
            }

            string commonItems = ASSET_ROOT + "/Items";
            string indItems = ASSET_ROOT + "/Industrial/Items";

            var ironOre = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{commonItems}/Item_Iron.asset");
            var copperOre = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{commonItems}/Item_Copper.asset");
            var stone = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{commonItems}/Item_Stone.asset");
            var sand = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{commonItems}/Item_Sand.asset");
            var ironIngot = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{commonItems}/Item_IronIngot.asset");
            var copperIngot = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{commonItems}/Item_CopperIngot.asset");
            var sciT2 = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ScienceItem>($"{commonItems}/Item_ScienceT2.asset");
            var sciT3 = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ScienceItem>($"{commonItems}/Item_ScienceT3.asset");

            var ironPlate = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{indItems}/Item_IronPlate.asset");
            var steelPlate = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{indItems}/Item_SteelPlate.asset");
            var copperPlate = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{indItems}/Item_CopperPlate.asset");
            var copperWire = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{indItems}/Item_CopperWire.asset");
            var circuit = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{indItems}/Item_Circuit.asset");
            var advCircuit = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{indItems}/Item_AdvCircuit.asset");
            var ironGear = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{indItems}/Item_IronGear.asset");
            var glass = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{indItems}/Item_Glass.asset");
            var plastic = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ResourceItem>($"{indItems}/Item_Plastic.asset");

            var registry = AssetDatabase.LoadAssetAtPath<VoxelEngine.Crafting.RecipeRegistry>($"{ASSET_ROOT}/RecipeRegistry.asset");
            var tree = AssetDatabase.LoadAssetAtPath<VoxelEngine.Research.ResearchTree>($"{ASSET_ROOT}/Research/ResearchTree.asset");

            if (registry == null || ironPlate == null || steelPlate == null || copperWire == null || circuit == null || ironGear == null || ironIngot == null || copperIngot == null)
            {
                EditorUtility.DisplayDialog(
                    "Voxel Engine — Step 17",
                    "Step 17 needs the base crafting, power, research, and industrial content first.\n\nRun Steps 4, 6, 7, and 10, then run Step 17 again.",
                    "OK");
                return;
            }

            // Step 17 is deliberately additive. Existing assets and prefab tuning are
            // preserved; this pass only creates missing content and repairs required links.
            int createdAssetCount = 0;
            int createdPrefabCount = 0;
            int createdComponentCount = 0;
            int preservedAssetCount = 0;
            int preservedPrefabCount = 0;
            int repairedLinkCount = 0;
            int removedLegacyVisualCount = 0;
            int retiredRecipeLinkCount = 0;
            var retiredConveyorRecipes = new List<VoxelEngine.Crafting.RecipeDefinition>();

            // 5.3.0 replaces the short-lived separate-variant plan with one radial
            // selector per tier. Retire only registry/research links; preserve any
            // generated assets on disk so user-authored edits are never deleted.
            foreach (string tierKey in new[] { "Basic", "Fast", "Express" })
            {
                foreach (string shapeKey in new[] { "RampUp", "RampDown", "VerticalUp", "VerticalDown" })
                {
                    string path = $"{FAC_RECIPES}/Recipe_Conveyor{tierKey}{shapeKey}.asset";
                    var retired = AssetDatabase.LoadAssetAtPath<VoxelEngine.Crafting.RecipeDefinition>(path);
                    if (retired == null) continue;
                    retiredConveyorRecipes.Add(retired);
                    if (registry.recipes.Remove(retired)) retiredRecipeLinkCount++;
                }
            }

            T GetOrCreateStep17Asset<T>(string path) where T : ScriptableObject
            {
                var mainAsset = AssetDatabase.LoadMainAssetAtPath(path);
                if (mainAsset is T existing)
                {
                    preservedAssetCount++;
                    return existing;
                }

                if (mainAsset != null)
                {
                    Debug.LogError($"[VoxelEngineSetupWindow] Step 17 preserved '{path}' because it is not a {typeof(T).Name}. Resolve the asset-type conflict manually; no asset was deleted.");
                    return null;
                }

                var created = ScriptableObject.CreateInstance<T>();
                AssetDatabase.CreateAsset(created, path);
                createdAssetCount++;
                Debug.Log($"[VoxelEngineSetupWindow] Step 17 created asset: {path}");
                return created;
            }

            void StripMissingScriptsRecursive(GameObject root, string contextPath)
            {
                if (root == null) return;
                int removed = 0;
                foreach (var transform in root.GetComponentsInChildren<Transform>(true))
                    removed += GameObjectUtility.RemoveMonoBehavioursWithMissingScript(transform.gameObject);
                if (removed > 0)
                {
                    repairedLinkCount += removed;
                    Debug.Log($"[VoxelEngineSetupWindow] Step 17 removed {removed} missing script reference(s) from '{contextPath}' before saving.");
                }
            }

            GameObject GetOrCreateStep17Prefab(string path, string name, System.Action<GameObject> ensureMissingContent)
            {
                var mainAsset = AssetDatabase.LoadMainAssetAtPath(path);
                bool existed = mainAsset != null;
                if (existed && !(mainAsset is GameObject))
                {
                    Debug.LogError($"[VoxelEngineSetupWindow] Step 17 preserved '{path}' because it is not a prefab. Resolve the asset-type conflict manually; no asset was deleted.");
                    return null;
                }

                GameObject root = null;
                bool loadedPrefabContents = false;
                try
                {
                    if (existed)
                    {
                        try
                        {
                            root = PrefabUtility.LoadPrefabContents(path);
                            loadedPrefabContents = true;
                        }
                        catch (System.Exception ex)
                        {
                            preservedPrefabCount++;
                            Debug.LogError($"[VoxelEngineSetupWindow] Step 17 could not open '{path}' and left it untouched. Unity said: {ex.Message}");
                            return AssetDatabase.LoadAssetAtPath<GameObject>(path);
                        }
                    }
                    else
                    {
                        root = new GameObject(name);
                    }

                    StripMissingScriptsRecursive(root, path);
                    ensureMissingContent?.Invoke(root);
                    StripMissingScriptsRecursive(root, path);
                    var saved = PrefabUtility.SaveAsPrefabAsset(root, path);
                    if (saved == null)
                    {
                        Debug.LogError($"[VoxelEngineSetupWindow] Step 17 could not save prefab '{path}'. The existing asset was not deleted.");
                        return AssetDatabase.LoadAssetAtPath<GameObject>(path);
                    }

                    if (existed)
                    {
                        preservedPrefabCount++;
                        Debug.Log($"[VoxelEngineSetupWindow] Step 17 preserved prefab tuning and verified links: {path}");
                    }
                    else
                    {
                        createdPrefabCount++;
                        Debug.Log($"[VoxelEngineSetupWindow] Step 17 created prefab: {path}");
                    }
                    return saved;
                }
                finally
                {
                    if (root != null)
                    {
                        if (loadedPrefabContents)
                            PrefabUtility.UnloadPrefabContents(root);
                        else
                            Object.DestroyImmediate(root);
                    }
                }
            }

            Material GetMaterial(string folder, string name, Color color, bool emissive = false)
            {
                EnsureFolder(folder);
                string path = $"{folder}/{name}.mat";
                var mainAsset = AssetDatabase.LoadMainAssetAtPath(path);
                if (mainAsset is Material existing)
                {
                    preservedAssetCount++;
                    return existing;
                }

                if (mainAsset != null)
                {
                    Debug.LogError($"[VoxelEngineSetupWindow] Step 17 preserved '{path}' because it is not a Material. No asset was deleted.");
                    return null;
                }

                var shader = Shader.Find("Universal Render Pipeline/Lit") ?? Shader.Find("Standard");
                if (shader == null)
                {
                    Debug.LogError($"[VoxelEngineSetupWindow] Step 17 could not create '{path}' because no supported lit shader was found.");
                    return null;
                }

                var material = new Material(shader) { name = name, color = color };
                if (material.HasProperty("_BaseColor")) material.SetColor("_BaseColor", color);
                if (emissive)
                {
                    material.EnableKeyword("_EMISSION");
                    if (material.HasProperty("_EmissionColor")) material.SetColor("_EmissionColor", color * 1.5f);
                }
                AssetDatabase.CreateAsset(material, path);
                createdAssetCount++;
                Debug.Log($"[VoxelEngineSetupWindow] Step 17 created material: {path}");
                return material;
            }

            GameObject EnsurePrimitive(GameObject root, string name, PrimitiveType type, Vector3 localPosition, Vector3 localScale, Material material, Vector3 localEuler)
            {
                var existing = root.transform.Find(name);
                if (existing != null)
                {
                    if (existing.GetComponent<MeshFilter>() == null || existing.GetComponent<MeshRenderer>() == null)
                    {
                        Debug.LogWarning($"[VoxelEngineSetupWindow] Step 17 left custom child '{name}' on '{root.name}' untouched even though it is not generated primitive geometry.");
                        return existing.gameObject;
                    }

                    // Generated visual primitives are safe to refresh: this lets the
                    // setup tool non-destructively upgrade prefab looks while keeping
                    // hand-authored children and component values intact.
                    if (name.StartsWith("Generated_", System.StringComparison.Ordinal))
                    {
                        existing.localPosition = localPosition;
                        existing.localRotation = Quaternion.Euler(localEuler);
                        existing.localScale = localScale;
                        var existingRenderer = existing.GetComponent<Renderer>();
                        if (existingRenderer != null && material != null) existingRenderer.sharedMaterial = material;
                        repairedLinkCount++;
                    }
                    return existing.gameObject;
                }

                var child = GameObject.CreatePrimitive(type);
                child.name = name;
                child.transform.SetParent(root.transform, false);
                child.transform.localPosition = localPosition;
                child.transform.localRotation = Quaternion.Euler(localEuler);
                child.transform.localScale = localScale;
                var renderer = child.GetComponent<Renderer>();
                if (renderer != null && material != null) renderer.sharedMaterial = material;
                var collider = child.GetComponent<Collider>();
                if (collider != null) Object.DestroyImmediate(collider);
                return child;
            }

            Light EnsureLight(GameObject root, string name, Vector3 localPosition, LightType type, Color color, float intensity, float range, float spotAngle = 60f)
            {
                var existing = root.transform.Find(name);
                if (existing != null)
                {
                    var existingLight = existing.GetComponent<Light>();
                    if (existingLight != null) return existingLight;

                    existingLight = existing.gameObject.AddComponent<Light>();
                    existingLight.type = type;
                    existingLight.color = color;
                    existingLight.intensity = intensity;
                    existingLight.range = range;
                    existingLight.spotAngle = spotAngle;
                    createdComponentCount++;
                    return existingLight;
                }

                var child = new GameObject(name);
                child.transform.SetParent(root.transform, false);
                child.transform.localPosition = localPosition;
                child.transform.localRotation = Quaternion.identity;
                var light = child.AddComponent<Light>();
                light.type = type;
                light.color = color;
                light.intensity = intensity;
                light.range = range;
                light.spotAngle = spotAngle;
                createdComponentCount++;
                return light;
            }

            BoxCollider EnsureRootCollider(GameObject root, Vector3 size, Vector3 center)
            {
                var existing = root.GetComponent<BoxCollider>();
                if (existing != null)
                {
                    if (existing.size != size || existing.center != center)
                    {
                        existing.size = size;
                        existing.center = center;
                        repairedLinkCount++;
                    }
                    return existing;
                }

                var collider = root.AddComponent<BoxCollider>();
                collider.size = size;
                collider.center = center;
                createdComponentCount++;
                return collider;
            }

            T EnsureStep17Component<T>(GameObject root, System.Action<T> configureDefaults = null) where T : Component
            {
                var existing = root.GetComponent<T>();
                if (existing != null) return existing;

                var created = root.AddComponent<T>();
                configureDefaults?.Invoke(created);
                createdComponentCount++;
                return created;
            }

            List<T> MergeUniqueList<T>(List<T> existing, IEnumerable<T> required) where T : Object
            {
                var merged = existing ?? new List<T>();
                if (required == null) return merged;
                foreach (var entry in required)
                {
                    if (entry != null && !merged.Contains(entry))
                    {
                        merged.Add(entry);
                        repairedLinkCount++;
                    }
                }
                return merged;
            }

            T[] MergeUniqueArray<T>(T[] existing, IEnumerable<T> required) where T : Object
            {
                var merged = new List<T>();
                if (existing != null)
                {
                    foreach (var entry in existing)
                        if (entry != null && !merged.Contains(entry)) merged.Add(entry);
                }
                if (required != null)
                {
                    foreach (var entry in required)
                    {
                        if (entry != null && !merged.Contains(entry))
                        {
                            merged.Add(entry);
                            repairedLinkCount++;
                        }
                    }
                }
                return merged.ToArray();
            }

            VoxelEngine.Items.BlockItem ConfigureBlock(string folder, string assetName, string display, string description, Color tint, GameObject prefab, string category, int health = 200, int miningTier = 1, Vector3Int? gridSize = null)
            {
                string path = $"{folder}/{assetName}.asset";
                bool created = AssetDatabase.LoadMainAssetAtPath(path) == null;
                var item = GetOrCreateStep17Asset<VoxelEngine.Items.BlockItem>(path);
                if (item == null) return null;

                // Identity fields are safe to repair on every setup run. This fixes
                // old assets that were created during failed setup passes and kept
                // the ItemDefinition defaults (for example displaying as Iron Ore).
                if (item.itemId != assetName.ToLowerInvariant()) { item.itemId = assetName.ToLowerInvariant(); repairedLinkCount++; }
                if (item.displayName != display) { item.displayName = display; repairedLinkCount++; }
                if (item.description != description) { item.description = description; repairedLinkCount++; }
                if (item.category != category) { item.category = category; repairedLinkCount++; }
                item.iconTint = tint;

                if (created)
                {
                    item.maxStack = 99;
                    item.massPerUnit = 4f;
                    item.gridSize = gridSize ?? Vector3Int.one;
                    item.allowStacking = true;
                    item.blockHealth = health;
                    item.miningTier = miningTier;
                }

                if (prefab != null && item.placedPrefab != prefab)
                {
                    item.placedPrefab = prefab;
                    repairedLinkCount++;
                    Debug.Log($"[VoxelEngineSetupWindow] Step 17 connected block item '{path}' to '{AssetDatabase.GetAssetPath(prefab)}'.");
                }
                if (gridSize.HasValue && item.gridSize != gridSize.Value)
                {
                    item.gridSize = gridSize.Value;
                    repairedLinkCount++;
                }
                EditorUtility.SetDirty(item);
                return item;
            }

            VoxelEngine.GridSystem.GridBlockItem ConfigureGridItem(string folder, string assetName, string display, string description, Color tint, GameObject prefab, VoxelEngine.GridSystem.GridSize gridSize, float mass, float hp)
            {
                string path = $"{folder}/{assetName}.asset";
                bool created = AssetDatabase.LoadMainAssetAtPath(path) == null;
                var item = GetOrCreateStep17Asset<VoxelEngine.GridSystem.GridBlockItem>(path);
                if (item == null) return null;

                if (created)
                {
                    item.itemId = assetName.ToLowerInvariant();
                    item.displayName = display;
                    item.description = description;
                    item.iconTint = tint;
                    item.maxStack = 99;
                    item.massPerUnit = Mathf.Max(1f, mass * 0.01f);
                    item.category = "Grid";
                    item.gridSize = gridSize;
                    item.blockMass = mass;
                    item.blockHP = hp;
                }

                if (prefab != null && item.blockPrefab != prefab)
                {
                    item.blockPrefab = prefab;
                    repairedLinkCount++;
                    Debug.Log($"[VoxelEngineSetupWindow] Step 17 connected grid item '{path}' to '{AssetDatabase.GetAssetPath(prefab)}'.");
                }
                EditorUtility.SetDirty(item);
                return item;
            }

            VoxelEngine.Items.ResourceItem ConfigureFactoryResource(string assetName, string itemId, string display, string description, Color tint)
            {
                string path = $"{FAC_ITEMS}/{assetName}.asset";
                bool created = AssetDatabase.LoadMainAssetAtPath(path) == null;
                var item = GetOrCreateStep17Asset<VoxelEngine.Items.ResourceItem>(path);
                if (item == null) return null;

                if (created)
                {
                    item.itemId = itemId;
                    item.displayName = display;
                    item.description = description;
                    item.iconTint = tint;
                    item.maxStack = 999;
                    item.massPerUnit = 1f;
                    item.category = "Factory";
                    item.subcategory = VoxelEngine.Items.ResourceCategory.Component;
                    item.fuelSeconds = 0f;
                    EditorUtility.SetDirty(item);
                }
                return item;
            }

            VoxelEngine.Crafting.RecipeDefinition CreateRecipe(VoxelEngine.Crafting.RecipeRegistry recipeRegistry, string folder, string assetName, string display, VoxelEngine.Items.ItemDefinition output, int outputCount, VoxelEngine.Crafting.StationTier station, bool unlocked, params (VoxelEngine.Items.ItemDefinition item, int n)[] inputs)
            {
                string path = $"{folder}/{assetName}.asset";
                var existingRecipe = AssetDatabase.LoadAssetAtPath<VoxelEngine.Crafting.RecipeDefinition>(path);
                if (output == null && existingRecipe == null)
                {
                    Debug.LogError($"[VoxelEngineSetupWindow] Step 17 skipped '{path}' because its required output item is unavailable. Existing assets were left untouched.");
                    return null;
                }

                bool created = AssetDatabase.LoadMainAssetAtPath(path) == null;
                var recipe = GetOrCreateStep17Asset<VoxelEngine.Crafting.RecipeDefinition>(path);
                if (recipe == null) return null;

                if (created)
                {
                    recipe.displayName = display;
                    recipe.outputItem = output;
                    recipe.outputCount = outputCount;
                    recipe.requiredStation = station;
                    recipe.craftSeconds = station switch
                    {
                        VoxelEngine.Crafting.StationTier.None => 0f,
                        VoxelEngine.Crafting.StationTier.CraftingBench => 2f,
                        VoxelEngine.Crafting.StationTier.Furnace => 4f,
                        VoxelEngine.Crafting.StationTier.Assembler => 4f,
                        _ => 0f
                    };
                    recipe.unlockedByDefault = unlocked;
                    var valid = new List<VoxelEngine.Crafting.RecipeIngredient>();
                    foreach (var (item, count) in inputs)
                    {
                        if (item != null && count > 0)
                            valid.Add(new VoxelEngine.Crafting.RecipeIngredient { item = item, count = count });
                    }
                    recipe.inputs = valid.ToArray();
                }
                else if (recipe.outputItem == null && output != null)
                {
                    recipe.outputItem = output;
                    repairedLinkCount++;
                }

                if (recipeRegistry != null && !recipeRegistry.recipes.Contains(recipe))
                {
                    recipeRegistry.recipes.Add(recipe);
                    repairedLinkCount++;
                    EditorUtility.SetDirty(recipeRegistry);
                }
                EditorUtility.SetDirty(recipe);
                return recipe;
            }

            VoxelEngine.Simulation.MachineDefinition ConfigureMachineDefinition(string assetName, string machineId, string display, string description, VoxelEngine.Simulation.MachineCategory category, float activeWatts, float idleWatts, float speedMultiplier, int inputSlots, int outputSlots, int upgradeSlots, Color primary, Color activeColor, GameObject prefab)
            {
                string path = $"{FAC_DEFS}/{assetName}.asset";
                bool created = AssetDatabase.LoadMainAssetAtPath(path) == null;
                var definition = GetOrCreateStep17Asset<VoxelEngine.Simulation.MachineDefinition>(path);
                if (definition == null) return null;

                if (created)
                {
                    definition.machineId = machineId;
                    definition.displayName = display;
                    definition.description = description;
                    definition.category = category;
                    definition.activeWatts = activeWatts;
                    definition.idleWatts = idleWatts;
                    definition.speedMultiplier = speedMultiplier;
                    definition.inputSlots = inputSlots;
                    definition.outputSlots = outputSlots;
                    definition.upgradeSlots = upgradeSlots;
                    definition.primaryColor = primary;
                    definition.activeEmissive = activeColor;
                    definition.idleEmissive = new Color(0.9f, 0.65f, 0.16f);
                }

                if (prefab != null && definition.prefab != prefab)
                {
                    definition.prefab = prefab;
                    repairedLinkCount++;
                }
                EditorUtility.SetDirty(definition);
                return definition;
            }

            VoxelEngine.Simulation.MachineRecipe ConfigureMachineRecipe(string assetName, string display, VoxelEngine.Simulation.MachineRecipeType type, VoxelEngine.Items.ItemDefinition output, int outputCount, float seconds, bool unlocked, VoxelEngine.Items.ItemDefinition byproduct, int byproductCount, float byproductChance, params (VoxelEngine.Items.ItemDefinition item, int n)[] inputs)
            {
                string path = $"{FAC_MRECIPES}/{assetName}.asset";
                var existingRecipe = AssetDatabase.LoadAssetAtPath<VoxelEngine.Simulation.MachineRecipe>(path);
                if (output == null && existingRecipe == null)
                {
                    Debug.LogError($"[VoxelEngineSetupWindow] Step 17 skipped '{path}' because its required output item is unavailable. Existing assets were left untouched.");
                    return null;
                }

                bool created = AssetDatabase.LoadMainAssetAtPath(path) == null;
                var recipe = GetOrCreateStep17Asset<VoxelEngine.Simulation.MachineRecipe>(path);
                if (recipe == null) return null;

                if (created)
                {
                    recipe.displayName = display;
                    recipe.recipeType = type;
                    var validInputs = new List<VoxelEngine.Simulation.MachineRecipeSlot>();
                    foreach (var (item, count) in inputs)
                    {
                        if (item != null && count > 0)
                            validInputs.Add(new VoxelEngine.Simulation.MachineRecipeSlot { item = item, count = count });
                    }
                    recipe.inputs = validInputs.ToArray();
                    recipe.outputItem = output;
                    recipe.outputCount = outputCount;
                    recipe.byproductItem = byproduct;
                    recipe.byproductCount = byproductCount;
                    recipe.byproductChance = byproductChance;
                    recipe.processSeconds = seconds;
                    recipe.unlockedByDefault = unlocked;
                }
                else if (recipe.outputItem == null && output != null)
                {
                    recipe.outputItem = output;
                    repairedLinkCount++;
                }
                EditorUtility.SetDirty(recipe);
                return recipe;
            }

            void AddRecipeUnique(List<VoxelEngine.Crafting.RecipeDefinition> list, VoxelEngine.Crafting.RecipeDefinition recipe)
            {
                if (recipe != null && !list.Contains(recipe)) list.Add(recipe);
            }

            // Step 17 also repairs the legacy coal-generator prefab because it is
            // the first power source players meet and its UI depends on the
            // CoalGeneratorFuel companion component being present.
            var repairedCoalGeneratorPrefab = GetOrCreateStep17Prefab($"{ASSET_ROOT}/Power/Prefabs/Generator_Coal.prefab", "Generator_Coal", root =>
            {
                var generator = EnsureStep17Component<VoxelEngine.Power.PowerGenerator>(root, g =>
                {
                    g.wattsPerSecond = 800f;
                    g.isOn = false;
                    g.connectRadius = 1.8f;
                });
                var fuel = EnsureStep17Component<VoxelEngine.Power.CoalGeneratorFuel>(root);
                var ports = root.GetComponent<VoxelEngine.Transport.PortConfig>();
                if (ports != null) ports.showPortIndicators = false;
                EnsureRootCollider(root, new Vector3(1.5f, 1.5f, 1.5f), Vector3.zero);
            });
            var legacyCoalBlock = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.BlockItem>($"{ASSET_ROOT}/Power/Blocks/Block_Gen_Coal.asset");
            if (legacyCoalBlock != null && repairedCoalGeneratorPrefab != null && legacyCoalBlock.placedPrefab != repairedCoalGeneratorPrefab)
            {
                legacyCoalBlock.placedPrefab = repairedCoalGeneratorPrefab;
                EditorUtility.SetDirty(legacyCoalBlock);
                repairedLinkCount++;
            }

            // ── Data assets ──
            string voltageConfigPath = $"{RESOURCES}/VoltageSystemConfig.asset";
            bool voltageConfigCreated = AssetDatabase.LoadMainAssetAtPath(voltageConfigPath) == null;
            var voltageConfig = GetOrCreateStep17Asset<VoxelEngine.Simulation.VoltageSystemConfig>(voltageConfigPath);
            if (voltageConfig != null && voltageConfigCreated)
            {
                voltageConfig.lvThresholdWatts = 25_000_000f;
                voltageConfig.defaultStepUpLoss = 0.02f;
                voltageConfig.defaultStepDownLoss = 0.02f;
                voltageConfig.hvLineReach = 200f;
                voltageConfig.hvMaxThroughput = float.MaxValue;
                voltageConfig.lvWireReach = 15f;
                voltageConfig.lvPoleMaxConnections = 6;
                voltageConfig.lvColor = new Color(0.22f, 0.78f, 0.42f);
                voltageConfig.hvColor = new Color(0.92f, 0.45f, 0.12f);
                voltageConfig.stepUpAccent = new Color(0.15f, 0.45f, 0.85f);
                voltageConfig.stepDownAccent = new Color(0.92f, 0.60f, 0.12f);
                EditorUtility.SetDirty(voltageConfig);
            }

            var gravel = ConfigureFactoryResource("Item_Gravel", "gravel", "Gravel", "Crushed stone aggregate used by early factory recipes.", new Color(0.45f, 0.45f, 0.42f));

            // ── Conveyor prefabs ──
            GameObject CreateConveyorPrefab(string assetName, VoxelEngine.Simulation.ConveyorSpeed speed, Color accent, int maxItems)
            {
                Color beltColor = speed switch
                {
                    VoxelEngine.Simulation.ConveyorSpeed.Fast => new Color(0.07f, 0.12f, 0.16f),
                    VoxelEngine.Simulation.ConveyorSpeed.Express => new Color(0.18f, 0.11f, 0.05f),
                    _ => new Color(0.045f, 0.05f, 0.055f)
                };

                return GetOrCreateStep17Prefab($"{FAC_PREFABS}/{assetName}.prefab", assetName, root =>
                {
                    var frameMat = GetMaterial(FAC_MATS, "Mat_ConveyorBrushedSteel", new Color(0.42f, 0.43f, 0.40f));
                    var darkFrameMat = GetMaterial(FAC_MATS, "Mat_ConveyorDarkFrame", new Color(0.12f, 0.13f, 0.14f));
                    var beltMat = GetMaterial(FAC_MATS, $"Mat_{assetName}_Belt", beltColor);
                    var accentMat = GetMaterial(FAC_MATS, $"Mat_{assetName}_TierAccent", accent, true);
                    var statusMat = GetMaterial(FAC_MATS, "Mat_ConveyorStatusLine", new Color(0.18f, 0.72f, 0.88f), true);
                    var rollerMat = GetMaterial(FAC_MATS, "Mat_ConveyorRollers", new Color(0.62f, 0.64f, 0.62f));

                    EnsurePrimitive(root, "Generated_FrameLeft", PrimitiveType.Cube, new Vector3(-0.52f, 0.28f, 0f), new Vector3(0.08f, 0.24f, 1.08f), frameMat, Vector3.zero);
                    EnsurePrimitive(root, "Generated_FrameRight", PrimitiveType.Cube, new Vector3(0.52f, 0.28f, 0f), new Vector3(0.08f, 0.24f, 1.08f), frameMat, Vector3.zero);
                    EnsurePrimitive(root, "Generated_BeltSurface", PrimitiveType.Cube, new Vector3(0f, 0.35f, 0f), new Vector3(0.88f, 0.045f, 1.04f), beltMat, Vector3.zero);
                    EnsurePrimitive(root, "Generated_FrontRoller", PrimitiveType.Cylinder, new Vector3(0f, 0.31f, -0.54f), new Vector3(0.13f, 0.46f, 0.13f), rollerMat, new Vector3(0f, 0f, 90f));
                    EnsurePrimitive(root, "Generated_BackRoller", PrimitiveType.Cylinder, new Vector3(0f, 0.31f, 0.54f), new Vector3(0.13f, 0.46f, 0.13f), rollerMat, new Vector3(0f, 0f, 90f));
                    EnsurePrimitive(root, "Generated_MotorBox", PrimitiveType.Cube, new Vector3(-0.72f, 0.22f, -0.34f), new Vector3(0.22f, 0.28f, 0.34f), darkFrameMat, Vector3.zero);
                    EnsurePrimitive(root, "Generated_TierStripeLeft", PrimitiveType.Cube, new Vector3(-0.565f, 0.43f, 0f), new Vector3(0.035f, 0.045f, 0.92f), accentMat, Vector3.zero);
                    EnsurePrimitive(root, "Generated_TierStripeRight", PrimitiveType.Cube, new Vector3(0.565f, 0.43f, 0f), new Vector3(0.035f, 0.045f, 0.92f), accentMat, Vector3.zero);
                    EnsurePrimitive(root, "Generated_StatusLine", PrimitiveType.Cube, new Vector3(0f, 0.405f, -0.08f), new Vector3(0.045f, 0.022f, 0.70f), statusMat, Vector3.zero);
                    EnsurePrimitive(root, "Generated_DirectionArrowLeftA", PrimitiveType.Cube, new Vector3(-0.26f, 0.407f, 0.12f), new Vector3(0.045f, 0.020f, 0.17f), accentMat, new Vector3(0f, 35f, 0f));
                    EnsurePrimitive(root, "Generated_DirectionArrowLeftB", PrimitiveType.Cube, new Vector3(-0.18f, 0.407f, 0.12f), new Vector3(0.045f, 0.020f, 0.17f), accentMat, new Vector3(0f, -35f, 0f));
                    EnsurePrimitive(root, "Generated_DirectionArrowRightA", PrimitiveType.Cube, new Vector3(0.18f, 0.407f, 0.12f), new Vector3(0.045f, 0.020f, 0.17f), accentMat, new Vector3(0f, 35f, 0f));
                    EnsurePrimitive(root, "Generated_DirectionArrowRightB", PrimitiveType.Cube, new Vector3(0.26f, 0.407f, 0.12f), new Vector3(0.045f, 0.020f, 0.17f), accentMat, new Vector3(0f, -35f, 0f));

                    // Explicit visual migration requested for 5.1.13: the old rotated
                    // status square has been superseded by the centered status line.
                    var legacyStatusSquare = root.transform.Find("Generated_Arrow");
                    if (legacyStatusSquare != null)
                    {
                        Object.DestroyImmediate(legacyStatusSquare.gameObject);
                        removedLegacyVisualCount++;
                        Debug.Log($"[VoxelEngineSetupWindow] Step 17 removed legacy conveyor status square from '{assetName}'.");
                    }

                    EnsurePrimitive(root, "Generated_FrontLegLeft", PrimitiveType.Cube, new Vector3(-0.42f, -0.17f, -0.42f), new Vector3(0.06f, 0.58f, 0.06f), frameMat, Vector3.zero);
                    EnsurePrimitive(root, "Generated_FrontLegRight", PrimitiveType.Cube, new Vector3(0.42f, -0.17f, -0.42f), new Vector3(0.06f, 0.58f, 0.06f), frameMat, Vector3.zero);
                    EnsurePrimitive(root, "Generated_BackLegLeft", PrimitiveType.Cube, new Vector3(-0.42f, -0.17f, 0.42f), new Vector3(0.06f, 0.58f, 0.06f), frameMat, Vector3.zero);
                    EnsurePrimitive(root, "Generated_BackLegRight", PrimitiveType.Cube, new Vector3(0.42f, -0.17f, 0.42f), new Vector3(0.06f, 0.58f, 0.06f), frameMat, Vector3.zero);
                    EnsureRootCollider(root, new Vector3(1.22f, 0.68f, 1.12f), new Vector3(0f, 0.14f, 0f));

                    var straightBelt = EnsureStep17Component<VoxelEngine.Simulation.ConveyorBelt>(root, belt =>
                    {
                        belt.speed = speed;
                        belt.shape = VoxelEngine.Simulation.ConveyorShape.Straight;
                        belt.maxItems = maxItems;
                        belt.entryDirection = Vector3.back;
                        belt.exitDirection = Vector3.forward;
                        belt.travelDirection = Vector3.forward;
                        belt.autoShape = true;
                    });
                    if (!straightBelt.autoShape)
                    {
                        straightBelt.autoShape = true;
                        repairedLinkCount++;
                    }

                    EnsureStep17Component<VoxelEngine.Simulation.BeltVisualController>(root, visuals =>
                    {
                        visuals.beltColor = beltColor;
                        visuals.railColor = Color.Lerp(new Color(0.35f, 0.38f, 0.42f), accent, 0.35f);
                        visuals.uvScrollSpeed = speed switch
                        {
                            VoxelEngine.Simulation.ConveyorSpeed.Fast => 3.4f,
                            VoxelEngine.Simulation.ConveyorSpeed.Express => 5.4f,
                            _ => 2.2f
                        };
                    });
                    var statusIndicator = EnsureStep17Component<VoxelEngine.Simulation.FactoryStatusIndicator>(root, indicator =>
                    {
                        indicator.rendererChildName = "Generated_StatusLine";
                        indicator.idleColor = accent;
                        indicator.activeColor = new Color(0.22f, 0.78f, 0.42f);
                        indicator.blockedColor = new Color(0.95f, 0.18f, 0.14f);
                    });
                    if (string.IsNullOrEmpty(statusIndicator.rendererChildName)
                        || statusIndicator.rendererChildName == "Generated_Arrow")
                    {
                        statusIndicator.rendererChildName = "Generated_StatusLine";
                        repairedLinkCount++;
                    }
                });
            }

            var conveyorBasicPrefab = CreateConveyorPrefab("Conveyor_Basic", VoxelEngine.Simulation.ConveyorSpeed.Basic, new Color(0.22f, 0.78f, 0.42f), 8);
            var conveyorFastPrefab = CreateConveyorPrefab("Conveyor_Fast", VoxelEngine.Simulation.ConveyorSpeed.Fast, new Color(0.18f, 0.72f, 0.88f), 10);
            var conveyorExpressPrefab = CreateConveyorPrefab("Conveyor_Express", VoxelEngine.Simulation.ConveyorSpeed.Express, new Color(0.95f, 0.62f, 0.18f), 12);

            var blockConveyorBasic = ConfigureBlock(FAC_ITEMS, "Block_ConveyorBasic", "Basic Conveyor Belt", "Moves item packets at 2 items per second. Snaps to other conveyors and machine ports.", new Color(0.22f, 0.78f, 0.42f), conveyorBasicPrefab, "Factory", 180);
            var blockConveyorFast = ConfigureBlock(FAC_ITEMS, "Block_ConveyorFast", "Fast Conveyor Belt", "Moves item packets at 5 items per second for denser factory lines.", new Color(0.18f, 0.72f, 0.88f), conveyorFastPrefab, "Factory", 200);
            var blockConveyorExpress = ConfigureBlock(FAC_ITEMS, "Block_ConveyorExpress", "Express Conveyor Belt", "Moves item packets at 10 items per second for high-throughput main buses.", new Color(0.95f, 0.62f, 0.18f), conveyorExpressPrefab, "Factory", 220);

            // ── Chute and funnel ──
            var chutePrefab = GetOrCreateStep17Prefab($"{FAC_PREFABS}/Conveyor_Chute.prefab", "Conveyor_Chute", root =>
            {
                var shellMat = GetMaterial(FAC_MATS, "Mat_ChuteHopperShell", new Color(0.72f, 0.74f, 0.72f));
                var rimMat = GetMaterial(FAC_MATS, "Mat_ChuteBoltedRim", new Color(0.52f, 0.54f, 0.52f));
                var throatMat = GetMaterial(FAC_MATS, "Mat_ChuteThroat", new Color(0.12f, 0.13f, 0.14f));
                var accentMat = GetMaterial(FAC_MATS, "Mat_ChuteDownAccent", new Color(0.18f, 0.72f, 0.88f), true);
                EnsurePrimitive(root, "Generated_SquareRim", PrimitiveType.Cube, new Vector3(0f, 0.96f, 0f), new Vector3(1.18f, 0.10f, 1.18f), rimMat, Vector3.zero);
                EnsurePrimitive(root, "Generated_HopperFront", PrimitiveType.Cube, new Vector3(0f, 0.70f, -0.42f), new Vector3(1.02f, 0.54f, 0.08f), shellMat, new Vector3(-12f, 0f, 0f));
                EnsurePrimitive(root, "Generated_HopperBack", PrimitiveType.Cube, new Vector3(0f, 0.70f, 0.42f), new Vector3(1.02f, 0.54f, 0.08f), shellMat, new Vector3(12f, 0f, 0f));
                EnsurePrimitive(root, "Generated_HopperLeft", PrimitiveType.Cube, new Vector3(-0.42f, 0.70f, 0f), new Vector3(0.08f, 0.54f, 1.02f), shellMat, new Vector3(0f, 0f, 12f));
                EnsurePrimitive(root, "Generated_HopperRight", PrimitiveType.Cube, new Vector3(0.42f, 0.70f, 0f), new Vector3(0.08f, 0.54f, 1.02f), shellMat, new Vector3(0f, 0f, -12f));
                EnsurePrimitive(root, "Generated_DropTube", PrimitiveType.Cylinder, new Vector3(0f, 0.20f, 0f), new Vector3(0.34f, 0.34f, 0.34f), throatMat, Vector3.zero);
                EnsurePrimitive(root, "Generated_BottomFlange", PrimitiveType.Cylinder, new Vector3(0f, -0.16f, 0f), new Vector3(0.48f, 0.05f, 0.48f), rimMat, Vector3.zero);
                EnsurePrimitive(root, "Generated_DownArrow", PrimitiveType.Cube, new Vector3(0f, 0.28f, -0.39f), new Vector3(0.14f, 0.34f, 0.035f), accentMat, Vector3.zero);
                EnsureRootCollider(root, new Vector3(1.25f, 1.22f, 1.25f), new Vector3(0f, 0.45f, 0f));
                EnsureStep17Component<VoxelEngine.Simulation.ConveyorChute>(root, chute =>
                {
                    chute.shape = VoxelEngine.Simulation.ChuteShape.Straight;
                    chute.maxItems = 6;
                    chute.slideSpeed = 3.2f;
                });
