                var frameMat = GetMaterial(HV_MATS, "Mat_SubstationSteelFrame", new Color(0.46f, 0.49f, 0.50f));
                var tankMat = GetMaterial(HV_MATS, "Mat_SubstationTransformerTank", new Color(0.66f, 0.70f, 0.69f));
