                EnsurePrimitive(root, "Generated_FrontLens", PrimitiveType.Cylinder, new Vector3(0f, 0.10f, -0.43f), new Vector3(0.30f, 0.035f, 0.30f), lensMat, new Vector3(90f, 0f, 0f));
