            GameObject CreateGridSpotlightPrefab(string assetName, bool largeGrid, bool dualOutput)
            {
                return GetOrCreateStep17Prefab($"{GRID_PREFABS}/{assetName}.prefab", assetName, root =>
                {
                    float scale = largeGrid ? 2.5f : 1f;
                    float spread = dualOutput ? 0.33f * scale : 0f;
                    var shellMat = GetMaterial(GRID_MATS, largeGrid ? "Mat_LargeGridSpotlightShell" : "Mat_SmallGridSpotlightShell", new Color(0.56f, 0.61f, 0.52f));
                    var trimMat = GetMaterial(GRID_MATS, "Mat_GridSpotlightBlackTrim", new Color(0.025f, 0.028f, 0.032f));
                    var grilleMat = GetMaterial(GRID_MATS, "Mat_GridSpotlightGrille", new Color(0.09f, 0.10f, 0.105f));
                    var lensMat = GetMaterial(GRID_MATS, "Mat_GridSpotlightHotLens", new Color(1f, 0.96f, 0.84f), true);
                    var blueStatus = GetMaterial(GRID_MATS, "Mat_GridSpotlightBlueStatus", new Color(0.05f, 0.65f, 1f), true);

                    EnsurePrimitive(root, "Generated_RearBody", PrimitiveType.Cube, new Vector3(0f, 0.00f, 0.08f * scale), new Vector3((dualOutput ? 1.22f : 0.78f) * scale, 0.52f * scale, 0.62f * scale), shellMat, Vector3.zero);
                    EnsurePrimitive(root, "Generated_TopHandle", PrimitiveType.Cube, new Vector3(0f, 0.34f * scale, 0.07f * scale), new Vector3((dualOutput ? 0.92f : 0.48f) * scale, 0.08f * scale, 0.50f * scale), trimMat, Vector3.zero);
                    EnsurePrimitive(root, "Generated_BottomMount", PrimitiveType.Cube, new Vector3(0f, -0.34f * scale, 0.10f * scale), new Vector3((dualOutput ? 0.82f : 0.44f) * scale, 0.10f * scale, 0.46f * scale), trimMat, Vector3.zero);

                    int lamps = dualOutput ? 2 : 1;
                    for (int i = 0; i < lamps; i++)
                    {
                        float x = dualOutput ? (i == 0 ? -spread : spread) : 0f;
                        EnsurePrimitive(root, "Generated_LampCan_" + i, PrimitiveType.Cylinder, new Vector3(x, 0.00f, -0.23f * scale), new Vector3(0.28f * scale, 0.30f * scale, 0.28f * scale), shellMat, new Vector3(90f, 0f, 0f));
                        EnsurePrimitive(root, "Generated_BlackBezel_" + i, PrimitiveType.Cylinder, new Vector3(x, 0.00f, -0.50f * scale), new Vector3(0.34f * scale, 0.045f * scale, 0.34f * scale), trimMat, new Vector3(90f, 0f, 0f));
                        EnsurePrimitive(root, "Generated_HotLens_" + i, PrimitiveType.Cylinder, new Vector3(x, 0.00f, -0.555f * scale), new Vector3(0.27f * scale, 0.025f * scale, 0.27f * scale), lensMat, new Vector3(90f, 0f, 0f));
                        EnsurePrimitive(root, "Generated_GrilleHorizontalA_" + i, PrimitiveType.Cube, new Vector3(x, 0.085f * scale, -0.592f * scale), new Vector3(0.50f * scale, 0.018f * scale, 0.018f * scale), grilleMat, Vector3.zero);
                        EnsurePrimitive(root, "Generated_GrilleHorizontalB_" + i, PrimitiveType.Cube, new Vector3(x, -0.085f * scale, -0.592f * scale), new Vector3(0.50f * scale, 0.018f * scale, 0.018f * scale), grilleMat, Vector3.zero);
                        EnsurePrimitive(root, "Generated_GrilleCenter_" + i, PrimitiveType.Cube, new Vector3(x, 0.00f, -0.596f * scale), new Vector3(0.54f * scale, 0.016f * scale, 0.018f * scale), grilleMat, Vector3.zero);
                        EnsureLight(root, "Generated_Spot_" + i, new Vector3(x, 0.00f, -0.64f * scale), LightType.Spot, Color.white, largeGrid ? 9.5f : 4.8f, largeGrid ? 78f : 34f, dualOutput ? 38f : 42f);
                    }

                    EnsurePrimitive(root, "Generated_StatusPanel", PrimitiveType.Cube, new Vector3((dualOutput ? 0f : 0.32f * scale), -0.12f * scale, -0.57f * scale), new Vector3(0.10f * scale, 0.06f * scale, 0.018f * scale), blueStatus, Vector3.zero);
                    EnsureRootCollider(root, new Vector3((dualOutput ? 1.40f : 0.92f) * scale, 0.82f * scale, 0.98f * scale), new Vector3(0f, 0f, -0.10f * scale));
                    EnsureStep17Component<VoxelEngine.Simulation.GridLightBlock>(root, lightBlock =>
                    {
                        lightBlock.blockName = (largeGrid ? "Structural" : "Detail") + (dualOutput ? " Dual" : "") + " Spotlight";
                        lightBlock.lightColor = Color.white;
                        lightBlock.range = largeGrid ? 78f : 34f;
                        lightBlock.spotAngle = dualOutput ? 38f : 42f;
                        lightBlock.intensity = largeGrid ? 9.5f : 4.8f;
                        lightBlock.lightType = LightType.Spot;
                        lightBlock.wattsDraw = largeGrid ? (dualOutput ? 95f : 65f) : (dualOutput ? 38f : 25f);
                    });
                });
            }

            var largeGridSpotlightPrefab = CreateGridSpotlightPrefab("GridSpotlight_Large", true, false);
            var smallDualSpotlightPrefab = CreateGridSpotlightPrefab("GridSpotlight_DualSmall", false, true);
            var largeDualSpotlightPrefab = CreateGridSpotlightPrefab("GridSpotlight_DualLarge", true, true);
            var largeGridSpotlightItem = ConfigureGridItem(GRID_ITEMS, "GItem_LargeGridSpotlight", "Structural Spotlight", "Structural-scale single-beam spotlight inspired by rugged industrial searchlights. Long range, configurable color/range/intensity, 65 W draw.", new Color(1f, 0.96f, 0.84f), largeGridSpotlightPrefab, VoxelEngine.GridSystem.GridSize.Large, 420f, 520f);
            var smallDualSpotlightItem = ConfigureGridItem(GRID_ITEMS, "GItem_DualGridSpotlightSmall", "Detail Dual Spotlight", "Compact detail-scale dual-output spotlight for the unified Grid with two synchronized beams, 38 W draw.", new Color(1f, 0.96f, 0.84f), smallDualSpotlightPrefab, VoxelEngine.GridSystem.GridSize.Small, 130f, 260f);
            var largeDualSpotlightItem = ConfigureGridItem(GRID_ITEMS, "GItem_DualGridSpotlightLarge", "Structural Dual Spotlight", "Structural-scale dual-output flood spotlight with two synchronized beams for broad ship and base illumination, 95 W draw.", new Color(1f, 0.96f, 0.84f), largeDualSpotlightPrefab, VoxelEngine.GridSystem.GridSize.Large, 520f, 640f);

            GameObject CreateLedStripPrefab(string folder, string matsFolder, string assetName, bool gridVariant)
            {
                return GetOrCreateStep17Prefab($"{folder}/{assetName}.prefab", assetName, root =>
                {
                    var stripMat = GetMaterial(matsFolder, gridVariant ? "Mat_GridLEDStrip" : "Mat_StaticLEDStrip", new Color(0.18f, 0.72f, 0.88f), true);
                    var backingMat = GetMaterial(matsFolder, gridVariant ? "Mat_GridLEDBacking" : "Mat_StaticLEDBacking", new Color(0.08f, 0.09f, 0.10f));
                    bool largeStrip = assetName.IndexOf("Large", System.StringComparison.OrdinalIgnoreCase) >= 0;
                    float stripLength = largeStrip ? 4.5f : 1.8f;
                    float stripWidth = largeStrip ? 0.18f : 0.08f;
                    EnsurePrimitive(root, "Generated_LEDBackplate", PrimitiveType.Cube, new Vector3(0f, 0.02f, 0f), new Vector3(stripLength + 0.18f, 0.05f, stripWidth + 0.10f), backingMat, Vector3.zero);
                    EnsurePrimitive(root, "LEDStripMesh", PrimitiveType.Cube, new Vector3(0f, 0.075f, 0f), new Vector3(stripLength, 0.035f, stripWidth), stripMat, Vector3.zero);
                    int diodeCount = largeStrip ? 18 : 8;
                    for (int d = 0; d < diodeCount; d++)
                    {
                        float t = diodeCount == 1 ? 0.5f : d / (float)(diodeCount - 1);
                        float x = Mathf.Lerp(-stripLength * 0.46f, stripLength * 0.46f, t);
                        EnsurePrimitive(root, "Generated_LEDDiode_" + d, PrimitiveType.Cube, new Vector3(x, 0.105f, 0f), new Vector3(Mathf.Min(0.09f, stripLength / diodeCount * 0.40f), 0.018f, stripWidth * 0.82f), stripMat, Vector3.zero);
                    }
                    EnsureLight(root, "LEDLight", new Vector3(0f, 0.13f, 0f), LightType.Point, new Color(0.18f, 0.72f, 0.88f), largeStrip ? 2.2f : 1.4f, largeStrip ? 8f : 4f);
                    EnsureRootCollider(root, new Vector3(stripLength + 0.22f, 0.18f, stripWidth + 0.12f), new Vector3(0f, 0.05f, 0f));
                    if (gridVariant)
                    {
                        EnsureStep17Component<VoxelEngine.GridSystem.GridBlock>(root, gridBlock =>
                        {
                            gridBlock.blockName = assetName.IndexOf("Large", System.StringComparison.OrdinalIgnoreCase) >= 0 ? "Structural LED Strip" : "Detail LED Strip";
                            gridBlock.BlockMass = assetName.IndexOf("Large", System.StringComparison.OrdinalIgnoreCase) >= 0 ? 90f : 25f;
                            gridBlock.maxHP = assetName.IndexOf("Large", System.StringComparison.OrdinalIgnoreCase) >= 0 ? 180f : 90f;
                        });
                    }
                    EnsureStep17Component<VoxelEngine.Simulation.LEDStrip>(root, strip =>
                    {
                        strip.stripColor = new Color(0.18f, 0.72f, 0.88f);
                        strip.brightness = 1.5f;
                        strip.stripLength = assetName.IndexOf("Large", System.StringComparison.OrdinalIgnoreCase) >= 0 ? 4.5f : 1.8f;
                        strip.segmentCount = assetName.IndexOf("Large", System.StringComparison.OrdinalIgnoreCase) >= 0 ? 18 : 8;
                        strip.stripWidth = assetName.IndexOf("Large", System.StringComparison.OrdinalIgnoreCase) >= 0 ? 0.18f : 0.08f;
                        strip.mode = VoxelEngine.Simulation.LEDMode.Pulse;
                        strip.animSpeed = 1.5f;
                        strip.wattsDraw = assetName.IndexOf("Large", System.StringComparison.OrdinalIgnoreCase) >= 0 ? 12f : 5f;
                    });
                    EnsureStep17Component<VoxelEngine.Power.PowerConsumer>(root, power =>
                    {
                        power.wattsPerSecond = assetName.IndexOf("Large", System.StringComparison.OrdinalIgnoreCase) >= 0 ? 12f : 5f;
                        power.connectRadius = assetName.IndexOf("Large", System.StringComparison.OrdinalIgnoreCase) >= 0 ? 3.0f : 1.5f;
                    });
                });
            }

            var staticLEDStripPrefab = CreateLedStripPrefab(FAC_PREFABS, FAC_MATS, "LEDStrip_Static", false);
            var gridLEDStripPrefab = CreateLedStripPrefab(GRID_PREFABS, GRID_MATS, "LEDStrip_Grid", true);
            var largeGridLEDStripPrefab = CreateLedStripPrefab(GRID_PREFABS, GRID_MATS, "LEDStrip_LargeGrid", true);
            var blockLEDStrip = ConfigureBlock(FAC_ITEMS, "Block_LEDStripFactory", "LED Strip", "Segmented low-profile accent lighting for factory floors, walls, and machines. Runtime length is configurable on the LEDStrip component.", new Color(0.18f, 0.72f, 0.88f), staticLEDStripPrefab, "Factory", 70);
            var gridLEDStripItem = ConfigureGridItem(GRID_ITEMS, "GItem_LEDStrip", "Detail LED Strip", "Detail-scale segmented LED strip with individual diode elements, pulse/blink/chase modes, and configurable runtime length.", new Color(0.18f, 0.72f, 0.88f), gridLEDStripPrefab, VoxelEngine.GridSystem.GridSize.Small, 25f, 90f);
            var largeGridLEDStripItem = ConfigureGridItem(GRID_ITEMS, "GItem_LargeGridLEDStrip", "Structural LED Strip", "Structural-scale segmented LED strip with individual diode elements, higher output, pulse/blink/chase modes, and configurable runtime length.", new Color(0.18f, 0.72f, 0.88f), largeGridLEDStripPrefab, VoxelEngine.GridSystem.GridSize.Large, 90f, 180f);

            GameObject CreateGridDoorPrefab(string assetName, string displayName, string style)
            {
                return GetOrCreateStep17Prefab($"{GRID_PREFABS}/{assetName}.prefab", assetName, root =>
                {
                    // Door visuals are fully setup-generated; clear older generated door pieces so
                    // ugly legacy variants are replaced without touching custom/non-generated children.
                    for (int i = root.transform.childCount - 1; i >= 0; i--)
                    {
                        var child = root.transform.GetChild(i);
                        if (child != null && child.name.StartsWith("Generated_", System.StringComparison.Ordinal))
                            Object.DestroyImmediate(child.gameObject);
                    }

                    const float scale = 2.5f;
                    float z = -scale * 0.48f; // sit on the mounted face/edge of the large-grid cell
                    bool single = style == "Single";
                    bool vault = style == "Vault";
                    bool dual = style == "Double";

                    var frameMat = GetMaterial(GRID_MATS, "Mat_DoorDeepGraphiteFrame", new Color(0.025f, 0.030f, 0.036f));
                    var outerMat = GetMaterial(GRID_MATS, "Mat_DoorBrushedSilverOuter", new Color(0.58f, 0.64f, 0.68f));
                    var orangeMat = GetMaterial(GRID_MATS, "Mat_DoorBurntOrangePanel", new Color(0.72f, 0.28f, 0.16f));
                    var darkPanelMat = GetMaterial(GRID_MATS, "Mat_DoorBlackInsetPanel", new Color(0.055f, 0.060f, 0.070f));
                    var vaultMat = GetMaterial(GRID_MATS, "Mat_DoorVaultSteel", new Color(0.36f, 0.40f, 0.42f));
                    var glassMat = GetMaterial(GRID_MATS, "Mat_GridDoorGlassGlow", new Color(0.18f, 0.72f, 0.88f), true);
                    var statusMat = GetMaterial(GRID_MATS, "Mat_GridDoorStatus", new Color(0.22f, 0.78f, 0.42f), true);
                    var warnMat = GetMaterial(GRID_MATS, "Mat_DoorWarningWhite", new Color(0.92f, 0.94f, 0.90f), true);

                    // Layered industrial frame inspired by the reference bulkhead.
                    // A dark backfill sits behind every variant so no daylight gaps are visible
                    // between closed panels and the frame/seals.
                    EnsurePrimitive(root, "Generated_DoorBackFill", PrimitiveType.Cube, new Vector3(0f, 0f, z - 0.070f * scale), new Vector3(0.001f, 0.001f, 0.001f), frameMat, Vector3.zero);
                    EnsurePrimitive(root, "Generated_OuterFrameTop", PrimitiveType.Cube, new Vector3(0f, 0.48f * scale, z), new Vector3(1.18f * scale, 0.08f * scale, 0.12f * scale), outerMat, Vector3.zero);
                    EnsurePrimitive(root, "Generated_OuterFrameBottom", PrimitiveType.Cube, new Vector3(0f, -0.48f * scale, z), new Vector3(1.18f * scale, 0.08f * scale, 0.12f * scale), outerMat, Vector3.zero);
                    EnsurePrimitive(root, "Generated_OuterFrameLeft", PrimitiveType.Cube, new Vector3(-0.58f * scale, 0f, z), new Vector3(0.08f * scale, 1.04f * scale, 0.12f * scale), outerMat, Vector3.zero);
                    EnsurePrimitive(root, "Generated_OuterFrameRight", PrimitiveType.Cube, new Vector3(0.58f * scale, 0f, z), new Vector3(0.08f * scale, 1.04f * scale, 0.12f * scale), outerMat, Vector3.zero);
                    EnsurePrimitive(root, "Generated_InnerSealTop", PrimitiveType.Cube, new Vector3(0f, 0.39f * scale, z - 0.018f * scale), new Vector3(0.96f * scale, 0.045f * scale, 0.08f * scale), frameMat, Vector3.zero);
                    EnsurePrimitive(root, "Generated_InnerSealBottom", PrimitiveType.Cube, new Vector3(0f, -0.39f * scale, z - 0.018f * scale), new Vector3(0.96f * scale, 0.045f * scale, 0.08f * scale), frameMat, Vector3.zero);
                    EnsurePrimitive(root, "Generated_InnerSealLeft", PrimitiveType.Cube, new Vector3(-0.48f * scale, 0f, z - 0.018f * scale), new Vector3(0.045f * scale, 0.82f * scale, 0.08f * scale), frameMat, Vector3.zero);
                    EnsurePrimitive(root, "Generated_InnerSealRight", PrimitiveType.Cube, new Vector3(0.48f * scale, 0f, z - 0.018f * scale), new Vector3(0.045f * scale, 0.82f * scale, 0.08f * scale), frameMat, Vector3.zero);

                    if (vault)
                    {
                        EnsurePrimitive(root, "Generated_LeftPanel", PrimitiveType.Cube, new Vector3(0f, 0f, z - 0.045f * scale), new Vector3(1.04f * scale, 0.90f * scale, 0.12f * scale), vaultMat, Vector3.zero);
                        EnsurePrimitive(root, "Generated_VaultCore", PrimitiveType.Cylinder, new Vector3(-0.06f * scale, 0.02f * scale, z - 0.105f * scale), new Vector3(0.25f * scale, 0.035f * scale, 0.25f * scale), frameMat, new Vector3(90f, 0f, 0f));
                        EnsurePrimitive(root, "Generated_VaultBarH", PrimitiveType.Cube, new Vector3(-0.06f * scale, 0.02f * scale, z - 0.145f * scale), new Vector3(0.58f * scale, 0.035f * scale, 0.025f * scale), frameMat, Vector3.zero);
                        EnsurePrimitive(root, "Generated_VaultBarV", PrimitiveType.Cube, new Vector3(-0.06f * scale, 0.02f * scale, z - 0.150f * scale), new Vector3(0.035f * scale, 0.48f * scale, 0.025f * scale), frameMat, Vector3.zero);
                        foreach (var x in new[] { -0.38f, 0.38f }) foreach (var y in new[] { -0.32f, 0.32f })
                            EnsurePrimitive(root, "Generated_VaultBolt_" + x + "_" + y, PrimitiveType.Sphere, new Vector3(x * scale, y * scale, z - 0.12f * scale), Vector3.one * 0.045f * scale, outerMat, Vector3.zero);
                    }
                    else if (single)
                    {
                        EnsurePrimitive(root, "Generated_LeftPanel", PrimitiveType.Cube, new Vector3(-0.01f * scale, 0f, z - 0.045f * scale), new Vector3(1.02f * scale, 0.90f * scale, 0.095f * scale), orangeMat, Vector3.zero);
                        EnsurePrimitive(root, "Generated_RightPanel", PrimitiveType.Cube, new Vector3(0.42f * scale, 0f, z - 0.038f * scale), new Vector3(0.001f, 0.001f, 0.001f), orangeMat, Vector3.zero);
                        EnsurePrimitive(root, "Generated_DarkDiagonalInset", PrimitiveType.Cube, new Vector3(0.25f * scale, -0.02f * scale, z - 0.110f * scale), new Vector3(0.34f * scale, 0.74f * scale, 0.030f * scale), darkPanelMat, new Vector3(0f, 0f, -24f));
                        EnsurePrimitive(root, "Generated_AccessPanel", PrimitiveType.Cube, new Vector3(-0.28f * scale, 0.05f * scale, z - 0.10f * scale), new Vector3(0.20f * scale, 0.28f * scale, 0.025f * scale), frameMat, Vector3.zero);
                        EnsurePrimitive(root, "Generated_AccessGlow", PrimitiveType.Cube, new Vector3(-0.28f * scale, 0.05f * scale, z - 0.13f * scale), new Vector3(0.08f * scale, 0.12f * scale, 0.018f * scale), glassMat, Vector3.zero);
                        EnsurePrimitive(root, "Generated_NumberStripe", PrimitiveType.Cube, new Vector3(-0.05f * scale, -0.24f * scale, z - 0.11f * scale), new Vector3(0.38f * scale, 0.045f * scale, 0.018f * scale), warnMat, Vector3.zero);
                    }
                    else if (dual)
                    {
                        EnsurePrimitive(root, "Generated_LeftPanel", PrimitiveType.Cube, new Vector3(-0.255f * scale, 0f, z - 0.045f * scale), new Vector3(0.55f * scale, 0.90f * scale, 0.095f * scale), orangeMat, Vector3.zero);
                        EnsurePrimitive(root, "Generated_RightPanel", PrimitiveType.Cube, new Vector3(0.255f * scale, 0f, z - 0.045f * scale), new Vector3(0.55f * scale, 0.90f * scale, 0.095f * scale), darkPanelMat, Vector3.zero);
                        EnsurePrimitive(root, "Generated_LeftAccessPanel", PrimitiveType.Cube, new Vector3(-0.30f * scale, 0.06f * scale, z - 0.120f * scale), new Vector3(0.17f * scale, 0.25f * scale, 0.030f * scale), frameMat, Vector3.zero);
                        EnsurePrimitive(root, "Generated_LeftAccessGlow", PrimitiveType.Cube, new Vector3(-0.30f * scale, 0.06f * scale, z - 0.150f * scale), new Vector3(0.075f * scale, 0.11f * scale, 0.018f * scale), glassMat, Vector3.zero);
                        EnsurePrimitive(root, "Generated_RightRibA", PrimitiveType.Cube, new Vector3(0.25f * scale, 0.17f * scale, z - 0.120f * scale), new Vector3(0.38f * scale, 0.038f * scale, 0.020f * scale), frameMat, new Vector3(0f, 0f, 24f));
                        EnsurePrimitive(root, "Generated_RightRibB", PrimitiveType.Cube, new Vector3(0.25f * scale, -0.17f * scale, z - 0.120f * scale), new Vector3(0.38f * scale, 0.038f * scale, 0.020f * scale), frameMat, new Vector3(0f, 0f, -24f));
                    }

                    EnsurePrimitive(root, "Generated_LeftGuideRail", PrimitiveType.Cube, new Vector3(-0.505f * scale, 0f, z - 0.105f * scale), new Vector3(0.030f * scale, 0.84f * scale, 0.025f * scale), frameMat, Vector3.zero);
                    EnsurePrimitive(root, "Generated_RightGuideRail", PrimitiveType.Cube, new Vector3(0.505f * scale, 0f, z - 0.105f * scale), new Vector3(0.030f * scale, 0.84f * scale, 0.025f * scale), frameMat, Vector3.zero);
                    EnsurePrimitive(root, "Generated_StatusLine", PrimitiveType.Cube, new Vector3(0f, -0.435f * scale, z - 0.130f * scale), new Vector3(0.44f * scale, 0.022f * scale, 0.018f * scale), statusMat, Vector3.zero);
                    EnsureRootCollider(root, new Vector3(1.18f * scale, 1.06f * scale, 0.22f * scale), new Vector3(0f, 0f, z));
                    EnsureStep17Component<VoxelEngine.GridSystem.GridSlidingDoor>(root, door =>
                    {
                        door.blockName = displayName;
                        door.BlockMass = vault ? 1250f : single ? 390f : 460f;
                        door.maxHP = vault ? 2200f : single ? 520f : 620f;
                        door.slideDistance = vault ? 1.05f * scale : single ? 1.08f * scale : 0.54f * scale;
                        door.slideSpeed = vault ? 3.5f : 8f;
                        door.motionActivated = !vault;
                        door.motionRadius = vault ? 4.5f : 7.5f;
                        door.motionGraceSeconds = vault ? 2.0f : 1.5f;
                        door.idleWatts = vault ? 8f : 4f;
                        door.movingWatts = vault ? 90f : 35f;
                    });
                });
            }

            var largeSingleDoorPrefab = CreateGridDoorPrefab("GridSlidingDoor_LargeSingle", "Structural Sci-Fi Sliding Door", "Single");
            var largeDoubleDoorPrefab = CreateGridDoorPrefab("GridSlidingDoor_LargeDouble", "Structural Double Sliding Door", "Double");
            var heavyVaultDoorPrefab = CreateGridDoorPrefab("GridVaultDoor_Heavy", "Heavy Vault Door", "Vault");
            var largeSingleDoorItem = ConfigureGridItem(GRID_ITEMS, "GItem_LargeGridSlidingDoor", "Structural Sci-Fi Sliding Door", "Structural-scale single sliding door inspired by premium sci-fi bulkhead doors. Motion activation supported.", new Color(0.72f, 0.28f, 0.16f), largeSingleDoorPrefab, VoxelEngine.GridSystem.GridSize.Large, 390f, 520f);
            var largeDoubleDoorItem = ConfigureGridItem(GRID_ITEMS, "GItem_LargeDoubleSlidingDoor", "Structural Double Sliding Door", "Structural-scale double sliding door with two powered panels and motion activation.", new Color(0.18f, 0.72f, 0.88f), largeDoubleDoorPrefab, VoxelEngine.GridSystem.GridSize.Large, 460f, 620f);
            var heavyVaultDoorItem = ConfigureGridItem(GRID_ITEMS, "GItem_HeavyVaultDoor", "Heavy Vault Door", "Massive structural-scale vault door with reinforced steel, slow powered actuation, and very high integrity.", new Color(0.56f, 0.60f, 0.62f), heavyVaultDoorPrefab, VoxelEngine.GridSystem.GridSize.Large, 1250f, 2200f);

            // ── Recipes ──
            var factoryRecipes = new List<VoxelEngine.Crafting.RecipeDefinition>();
            var recConveyorBasic = CreateRecipe(registry, FAC_RECIPES, "Recipe_ConveyorBasic", "Basic Conveyor Belt", blockConveyorBasic, 2, VoxelEngine.Crafting.StationTier.CraftingBench, false, (ironPlate, 2), (ironGear, 1));
            var recConveyorFast = CreateRecipe(registry, FAC_RECIPES, "Recipe_ConveyorFast", "Fast Conveyor Belt", blockConveyorFast, 2, VoxelEngine.Crafting.StationTier.Assembler, false, (ironPlate, 3), (ironGear, 2), (copperWire, 2));
            var recConveyorExpress = CreateRecipe(registry, FAC_RECIPES, "Recipe_ConveyorExpress", "Express Conveyor Belt", blockConveyorExpress, 2, VoxelEngine.Crafting.StationTier.Assembler, false, (steelPlate, 2), (ironGear, 3), (copperWire, 6), (circuit, 1));
            var recChute = CreateRecipe(registry, FAC_RECIPES, "Recipe_ConveyorChute", "Conveyor Chute", blockChute, 2, VoxelEngine.Crafting.StationTier.CraftingBench, false, (ironPlate, 2), (ironGear, 1));
            var recFunnel = CreateRecipe(registry, FAC_RECIPES, "Recipe_Funnel", "Funnel", blockFunnel, 1, VoxelEngine.Crafting.StationTier.CraftingBench, false, (ironPlate, 2), (ironGear, 1));
            var recSplitterMk1 = CreateRecipe(registry, FAC_RECIPES, "Recipe_ConveyorSplitterMk1", "Conveyor Splitter Mk.1", blockSplitterMk1, 1, VoxelEngine.Crafting.StationTier.CraftingBench, false, (ironPlate, 4), (ironGear, 2));
            var recSplitterMk2 = CreateRecipe(registry, FAC_RECIPES, "Recipe_ConveyorSplitterMk2", "Conveyor Splitter Mk.2", blockSplitterMk2, 1, VoxelEngine.Crafting.StationTier.Assembler, false, (ironPlate, 6), (ironGear, 3), (copperWire, 2));
            var recSplitterMk3 = CreateRecipe(registry, FAC_RECIPES, "Recipe_ConveyorSplitterMk3", "Conveyor Splitter Mk.3", blockSplitterMk3, 1, VoxelEngine.Crafting.StationTier.Assembler, false, (steelPlate, 4), (ironGear, 4), (circuit, 2));
            var recCrusher = CreateRecipe(registry, FAC_RECIPES, "Recipe_Crusher", "Crusher", blockCrusher, 1, VoxelEngine.Crafting.StationTier.Assembler, false, (ironPlate, 6), (ironGear, 4), (circuit, 1));
            var recAssemblerMk1 = CreateRecipe(registry, FAC_RECIPES, "Recipe_AssemblerMk1", "Assembler Mk.1", blockAssemblerMk1, 1, VoxelEngine.Crafting.StationTier.Assembler, false, (ironPlate, 8), (ironGear, 4), (circuit, 2));
            var recAssemblerMk2 = CreateRecipe(registry, FAC_RECIPES, "Recipe_AssemblerMk2", "Assembler Mk.2", blockAssemblerMk2, 1, VoxelEngine.Crafting.StationTier.Assembler, false, (steelPlate, 8), (ironGear, 6), (circuit, 4), (copperWire, 6));
            var recAssemblerMk3 = CreateRecipe(registry, FAC_RECIPES, "Recipe_AssemblerMk3", "Assembler Mk.3", blockAssemblerMk3, 1, VoxelEngine.Crafting.StationTier.Assembler, false, (steelPlate, 14), (ironGear, 10), (advCircuit, 4), (copperWire, 12));
            var recElectricFurnace = CreateRecipe(registry, FAC_RECIPES, "Recipe_ElectricFurnace", "Electric Furnace", blockElectricFurnace, 1, VoxelEngine.Crafting.StationTier.Assembler, false, (steelPlate, 4), (circuit, 2), (copperPlate, 2));
            var recGridLight = CreateRecipe(registry, GRID_RECIPES, "Recipe_GridLightBlock", "Detail Spotlight", gridLightItem, 1, VoxelEngine.Crafting.StationTier.Assembler, false, (ironPlate, 1), (copperWire, 2), (glass, 1));
            var recLargeGridSpotlight = CreateRecipe(registry, GRID_RECIPES, "Recipe_LargeGridSpotlight", "Structural Spotlight", largeGridSpotlightItem, 1, VoxelEngine.Crafting.StationTier.Assembler, false, (steelPlate, 3), (copperWire, 6), (glass, 2), (circuit, 1));
            var recSmallDualSpotlight = CreateRecipe(registry, GRID_RECIPES, "Recipe_DualGridSpotlightSmall", "Detail Dual Spotlight", smallDualSpotlightItem, 1, VoxelEngine.Crafting.StationTier.Assembler, false, (ironPlate, 2), (copperWire, 4), (glass, 2), (circuit, 1));
            var recLargeDualSpotlight = CreateRecipe(registry, GRID_RECIPES, "Recipe_DualGridSpotlightLarge", "Structural Dual Spotlight", largeDualSpotlightItem, 1, VoxelEngine.Crafting.StationTier.Assembler, false, (steelPlate, 4), (copperWire, 8), (glass, 4), (circuit, 2));
            var recLEDStrip = CreateRecipe(registry, FAC_RECIPES, "Recipe_LEDStripFactory", "LED Strip", blockLEDStrip, 2, VoxelEngine.Crafting.StationTier.CraftingBench, false, (copperWire, 4), (glass, 1));
            var recGridLEDStrip = CreateRecipe(registry, GRID_RECIPES, "Recipe_GLEDStrip", "Detail LED Strip", gridLEDStripItem, 2, VoxelEngine.Crafting.StationTier.CraftingBench, false, (copperWire, 4), (glass, 1));
            var recLargeGridLEDStrip = CreateRecipe(registry, GRID_RECIPES, "Recipe_LargeGridLEDStrip", "Structural LED Strip", largeGridLEDStripItem, 1, VoxelEngine.Crafting.StationTier.CraftingBench, false, (copperWire, 8), (glass, 2), (ironPlate, 1));
            var recLargeSingleDoor = CreateRecipe(registry, GRID_RECIPES, "Recipe_LargeGridSlidingDoor", "Structural Sci-Fi Sliding Door", largeSingleDoorItem, 1, VoxelEngine.Crafting.StationTier.Assembler, false, (steelPlate, 4), (copperWire, 8), (glass, 3), (circuit, 2));
            var recLargeDoubleDoor = CreateRecipe(registry, GRID_RECIPES, "Recipe_LargeDoubleSlidingDoor", "Structural Double Sliding Door", largeDoubleDoorItem, 1, VoxelEngine.Crafting.StationTier.Assembler, false, (steelPlate, 5), (copperWire, 10), (glass, 4), (circuit, 2));
            var recHeavyVaultDoor = CreateRecipe(registry, GRID_RECIPES, "Recipe_HeavyVaultDoor", "Heavy Vault Door", heavyVaultDoorItem, 1, VoxelEngine.Crafting.StationTier.Assembler, false, (steelPlate, 16), (copperWire, 12), (glass, 2), (circuit, 4));
            var legacySmallDoorRecipe = AssetDatabase.LoadAssetAtPath<VoxelEngine.Crafting.RecipeDefinition>($"{GRID_RECIPES}/Recipe_SmallGridSlidingDoor.asset");
            if (registry != null && legacySmallDoorRecipe != null && registry.recipes.Contains(legacySmallDoorRecipe))
            {
                registry.recipes.Remove(legacySmallDoorRecipe);
                repairedLinkCount++;
            }

            foreach (var recipe in new[]
            {
                recConveyorBasic, recConveyorFast, recConveyorExpress, recChute, recFunnel,
                recSplitterMk1, recSplitterMk2, recSplitterMk3,
                recCrusher, recAssemblerMk1, recAssemblerMk2, recAssemblerMk3, recElectricFurnace,
                recGridLight, recLargeGridSpotlight, recSmallDualSpotlight, recLargeDualSpotlight,
                recLEDStrip, recGridLEDStrip, recLargeGridLEDStrip, recLargeSingleDoor, recLargeDoubleDoor, recHeavyVaultDoor
            })
            {
                AddRecipeUnique(factoryRecipes, recipe);
            }

            var hvRecipes = new List<VoxelEngine.Crafting.RecipeDefinition>();
            var recHVWire = CreateRecipe(registry, HV_RECIPES, "Recipe_HV_Wire", "High Voltage Wire", hvWireItem, 1, VoxelEngine.Crafting.StationTier.Assembler, false, (steelPlate, 4), (copperWire, 20), (circuit, 2));
            var recPowerPole = CreateRecipe(registry, HV_RECIPES, "Recipe_PowerPole", "Power Pole", blockPowerPole, 1, VoxelEngine.Crafting.StationTier.CraftingBench, false, (ironPlate, 3), (copperWire, 2));
            var recLVConnector = CreateRecipe(registry, HV_RECIPES, "Recipe_LVWireConnector", "LV Wire Connector", blockLVConnector, 2, VoxelEngine.Crafting.StationTier.CraftingBench, false, (ironPlate, 1), (copperWire, 2));
            var recHVConnector = CreateRecipe(registry, HV_RECIPES, "Recipe_HVWireConnector", "HV Wire Connector", blockHVConnector, 1, VoxelEngine.Crafting.StationTier.Assembler, false, (steelPlate, 2), (copperWire, 6), (circuit, 1));
            var recLVPowerRelay = CreateRecipe(registry, HV_RECIPES, "Recipe_LVPowerRelay", "LV Power Relay", blockLVPowerRelay, 1, VoxelEngine.Crafting.StationTier.CraftingBench, false, (ironPlate, 2), (copperWire, 4), (circuit, 1));
            var recHVPowerRelay = CreateRecipe(registry, HV_RECIPES, "Recipe_HVPowerRelay", "HV Power Relay", blockHVPowerRelay, 1, VoxelEngine.Crafting.StationTier.Assembler, false, (steelPlate, 2), (copperWire, 8), (circuit, 2));
            var recSubstation = CreateRecipe(registry, HV_RECIPES, "Recipe_Substation", "Electrical Substation", blockSubstation, 1, VoxelEngine.Crafting.StationTier.Assembler, false, (steelPlate, 12), (copperWire, 16), (circuit, 3));
            var recHVTower = CreateRecipe(registry, HV_RECIPES, "Recipe_HVTower", "HV Transmission Tower", blockHVTower, 1, VoxelEngine.Crafting.StationTier.Assembler, false, (steelPlate, 20), (copperWire, 8));
            var recStepUp = CreateRecipe(registry, HV_RECIPES, "Recipe_StepUpTransformer", "Step-Up Transformer", blockStepUp, 1, VoxelEngine.Crafting.StationTier.Assembler, false, (steelPlate, 24), (copperWire, 16), (circuit, 4));
            var recStepDown = CreateRecipe(registry, HV_RECIPES, "Recipe_StepDownTransformer", "Step-Down Transformer", blockStepDown, 1, VoxelEngine.Crafting.StationTier.Assembler, false, (steelPlate, 24), (copperWire, 16), (circuit, 4));

            foreach (var recipe in new[] { recHVWire, recPowerPole, recLVConnector, recHVConnector, recLVPowerRelay, recHVPowerRelay, recSubstation, recHVTower, recStepUp, recStepDown })
            {
                AddRecipeUnique(hvRecipes, recipe);
            }

            var recWireGrLV = FindRecipeByName("Recipe_Wire_Gr_LV");
            var recPipeSc = FindRecipeByName("Recipe_Pipe_Super");
            AddRecipeUnique(hvRecipes, recWireGrLV);
            AddRecipeUnique(hvRecipes, recPipeSc);

            // ── Research ──
            if (tree != null)
            {
                var nElectricity = FindNodeByName(tree, "res_electricity");
                var nAdvancedManufacturing = FindNodeByName(tree, "res_adv_manufacturing");
                var factoryPrerequisites = nAdvancedManufacturing != null
                    ? new[] { nAdvancedManufacturing }
                    : (nElectricity != null ? new[] { nElectricity } : new VoxelEngine.Research.ResearchNode[0]);

                string factoryNodePath = $"{NODES}/res_factory_logistics.asset";
                bool factoryNodeCreated = AssetDatabase.LoadMainAssetAtPath(factoryNodePath) == null;
                var nFactory = GetOrCreateStep17Asset<VoxelEngine.Research.ResearchNode>(factoryNodePath);
                if (nFactory != null)
                {
                    if (factoryNodeCreated)
                    {
                        nFactory.nodeId = "res_factory_logistics";
                        nFactory.displayName = "Factory Logistics";
                        nFactory.description = "Conveyors, chutes, funnels, crushers, assemblers, and compact factory lighting.";
                        nFactory.category = VoxelEngine.Research.ResearchCategory.Environment;
                        nFactory.subCategory = VoxelEngine.Research.ResearchSubCategory.Logistics;
                        nFactory.tier = 3;
                        nFactory.column = 5;
                        nFactory.iconTint = new Color(0.18f, 0.72f, 0.88f);
                        nFactory.researchSeconds = 80f;
                        nFactory.cost = new[]
                        {
                            new VoxelEngine.Research.ResearchNode.ScienceCost { pack = sciT2, count = 25 },
                            new VoxelEngine.Research.ResearchNode.ScienceCost { pack = sciT3, count = 5 }
                        };
                        nFactory.upgradeKind = VoxelEngine.Research.PlayerUpgradeKind.None;
                        nFactory.maxRanks = 1;
                    }
                    nFactory.prerequisites = MergeUniqueArray(nFactory.prerequisites, factoryPrerequisites);
                    if (retiredConveyorRecipes.Count > 0 && nFactory.unlocksRecipes != null)
                    {
                        var keptUnlocks = new List<VoxelEngine.Crafting.RecipeDefinition>();
                        foreach (var unlock in nFactory.unlocksRecipes)
                        {
                            if (unlock == null || retiredConveyorRecipes.Contains(unlock))
                            {
                                if (unlock != null) retiredRecipeLinkCount++;
                                continue;
                            }
                            keptUnlocks.Add(unlock);
                        }
                        nFactory.unlocksRecipes = keptUnlocks.ToArray();
                    }
                    nFactory.unlocksRecipes = MergeUniqueArray(nFactory.unlocksRecipes, factoryRecipes);
                    EditorUtility.SetDirty(nFactory);
                    if (!tree.nodes.Contains(nFactory))
                    {
                        tree.nodes.Add(nFactory);
                        repairedLinkCount++;
                    }
                }

                string hvNodePath = $"{NODES}/res_hv_transmission.asset";
                bool hvNodeCreated = AssetDatabase.LoadMainAssetAtPath(hvNodePath) == null;
                var nHV = GetOrCreateStep17Asset<VoxelEngine.Research.ResearchNode>(hvNodePath);
                if (nHV != null)
                {
                    if (hvNodeCreated)
                    {
                        nHV.nodeId = "res_hv_transmission";
                        nHV.displayName = "High-Voltage Transmission";
                        nHV.description = "Power poles, substations, transformers, and long-span high-voltage towers for large factories.";
                        nHV.category = VoxelEngine.Research.ResearchCategory.Environment;
                        nHV.subCategory = VoxelEngine.Research.ResearchSubCategory.Power;
                        nHV.tier = 4;
                        nHV.column = 6;
                        nHV.iconTint = new Color(0.92f, 0.45f, 0.12f);
                        nHV.researchSeconds = 110f;
                        nHV.cost = new[]
                        {
                            new VoxelEngine.Research.ResearchNode.ScienceCost { pack = sciT2, count = 30 },
                            new VoxelEngine.Research.ResearchNode.ScienceCost { pack = sciT3, count = 15 }
                        };
                        nHV.upgradeKind = VoxelEngine.Research.PlayerUpgradeKind.None;
                        nHV.maxRanks = 1;
                    }
                    nHV.prerequisites = MergeUniqueArray(nHV.prerequisites, nFactory != null ? new[] { nFactory } : factoryPrerequisites);
                    nHV.unlocksRecipes = MergeUniqueArray(nHV.unlocksRecipes, hvRecipes);
                    EditorUtility.SetDirty(nHV);
                    if (!tree.nodes.Contains(nHV))
                    {
                        tree.nodes.Add(nHV);
                        repairedLinkCount++;
                    }
                }

                EditorUtility.SetDirty(tree);
            }

            registry.recipes.RemoveAll(recipe => recipe == null);
            EditorUtility.SetDirty(registry);
            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();

            string setupSummary =
                "Factory Foundations + High-Voltage Grid verified with protected migrations.\n\n" +
                $"Created assets/materials: {createdAssetCount}\n" +
                $"Created prefabs: {createdPrefabCount}\n" +
                $"Created missing components: {createdComponentCount}\n" +
                $"Preserved existing assets/materials: {preservedAssetCount}\n" +
                $"Preserved existing prefabs: {preservedPrefabCount}\n" +
                $"Repaired required links: {repairedLinkCount}\n" +
                $"Retired obsolete variant recipe links: {retiredRecipeLinkCount}\n" +
                $"Removed obsolete generated visuals: {removedLegacyVisualCount}\n\n" +
                "Existing health, power, throughput, recipe costs, research costs, custom visual transforms, materials, and effect tuning were preserved.";
            Debug.Log($"[VoxelEngineSetupWindow] Step 17 complete. Created assets/materials={createdAssetCount}, created prefabs={createdPrefabCount}, created components={createdComponentCount}, preserved assets/materials={preservedAssetCount}, preserved prefabs={preservedPrefabCount}, repaired links={repairedLinkCount}, retired variant recipe links={retiredRecipeLinkCount}, removed legacy visuals={removedLegacyVisualCount}.");
            EditorUtility.DisplayDialog("Voxel Engine — Step 17", setupSummary, "OK");
        }

