        private static T GetOrCreateAsset<T>(string path) where T : ScriptableObject
        {
            var asset = AssetDatabase.LoadAssetAtPath<T>(path);
            if (asset == null)
            {
                if (AssetDatabase.LoadMainAssetAtPath(path) != null) AssetDatabase.DeleteAsset(path);
                asset = ScriptableObject.CreateInstance<T>();
                AssetDatabase.CreateAsset(asset, path);
            }
            return asset;
        }

        /// <summary>
        /// Builds a Resources-visible, additive item catalog used by world persistence.
        /// It prevents inventory-only assets (not referenced by the startup scene) from
        /// resolving to null during login/save restore. Existing catalog references are
        /// retained; missing catalog entries are repaired by scanning every ItemDefinition.
        /// </summary>
        private static void EnsureItemPersistenceCatalog()
        {
            const string resourcesRoot = "Assets/Resources";
            const string catalogFolder = resourcesRoot + "/VoxelEngine";
            const string catalogPath = catalogFolder + "/ItemPersistenceCatalog.asset";
            EnsureFolder(resourcesRoot);
            EnsureFolder(catalogFolder);

            var catalog = GetOrCreateAsset<VoxelEngine.Items.ItemPersistenceCatalog>(catalogPath);
            var merged = new List<VoxelEngine.Items.ItemDefinition>();
            if (catalog.items != null)
            {
                foreach (var existing in catalog.items)
                    if (existing != null && !merged.Contains(existing)) merged.Add(existing);
            }

            var guids = new HashSet<string>(AssetDatabase.FindAssets("t:ItemDefinition"));
            // Explicitly include portable equipment subclasses even in projects where
            // an AssetDatabase base-type query is narrowed by importer/version rules.
            foreach (var filter in new[] { "t:PortableBatteryItem", "t:HydrogenCanisterItem", "t:JetpackItem" })
                foreach (var guid in AssetDatabase.FindAssets(filter)) guids.Add(guid);

            var orderedGuids = new List<string>(guids);
            orderedGuids.Sort((left, right) => string.CompareOrdinal(
                AssetDatabase.GUIDToAssetPath(left), AssetDatabase.GUIDToAssetPath(right)));
            foreach (var guid in orderedGuids)
            {
                string path = AssetDatabase.GUIDToAssetPath(guid);
                var item = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>(path);
                if (item != null && !merged.Contains(item)) merged.Add(item);
            }

            bool changed = catalog.items == null || catalog.items.Count != merged.Count;
            if (!changed && catalog.items != null)
            {
                for (int i = 0; i < merged.Count; i++)
                {
                    if (catalog.items[i] == merged[i]) continue;
                    changed = true;
                    break;
                }
            }
            if (!changed) return;
            catalog.items = merged;
            EditorUtility.SetDirty(catalog);
        }

        private static GameObject GetOrCreatePrefab(string path, string name, System.Action<GameObject> onUpdate)
        {
            GameObject root = null;
            bool loadedPrefabContents = false;

            try
            {
                if (AssetDatabase.LoadMainAssetAtPath(path) != null)
                {
                    try
                    {
                        root = PrefabUtility.LoadPrefabContents(path);
                        loadedPrefabContents = true;
                        // CRITICAL: strip any missing scripts that would prevent saving.
                        // This happens when scripts were renamed/moved between runs.
                        StripMissingScripts(root);
                    }
                    catch (System.Exception ex)
                    {
                        Debug.LogWarning($"[VoxelEngineSetupWindow] Could not load prefab contents at '{path}'. " +
                                         $"The asset will be recreated. Unity said: {ex.Message}");
                        AssetDatabase.DeleteAsset(path);
                    }
                }

                if (root == null)
                    root = new GameObject(name);

                onUpdate?.Invoke(root);

                // NOTE: Do NOT strip again after update — the second strip was removing
                // freshly-added components (AddComponent<T>) when there was any transient
                // script-loading delay, causing hull prefabs to lose their scripts.
                // The first strip on load is sufficient to clean stale references.

                return PrefabUtility.SaveAsPrefabAsset(root, path);
            }
            finally
            {
                if (root != null)
                {
                    if (loadedPrefabContents)
                        PrefabUtility.UnloadPrefabContents(root);
                    else
                        Object.DestroyImmediate(root);
                }
            }
        }

        /// <summary>Recursively remove all missing-script MonoBehaviours from a GameObject hierarchy.</summary>
        private static void StripMissingScripts(GameObject root)
        {
            if (root == null) return;
            foreach (var go in root.GetComponentsInChildren<Transform>(true))
            {
                if (go == null) continue;
                int removed = GameObjectUtility.RemoveMonoBehavioursWithMissingScript(go.gameObject);
                if (removed > 0)
                    Debug.Log($"[VoxelEngineSetupWindow] Removed {removed} missing script(s) from '{go.gameObject.name}'.");
            }
        }
        // ============================================================
        //   STEP 20 - CELESTIAL RUINS (themed variants for other planets)
        // ============================================================
        private void BuildCelestialRuinsContent()
        {
            const string CELEST_PREFABS = ASSET_ROOT + "/Survival/CelestialRuins";
            const string CELEST_BLOCKS  = ASSET_ROOT + "/Survival/CelestialBlocks";
            const string MISC_PREFABS   = ASSET_ROOT + "/Survival/MiscPrefabs"; // shared ruin textures live here
            EnsureFolder(ASSET_ROOT + "/Survival");
            EnsureFolder(CELEST_PREFABS);
            EnsureFolder(CELEST_BLOCKS);

            // ── Loot item resolution (null-safe: only items that exist are added) ──
            ItemDefinition FindItem(string assetNameNoExt)
            {
                var guids = AssetDatabase.FindAssets(assetNameNoExt + " t:ItemDefinition");
                foreach (var g in guids)
                {
                    var p = AssetDatabase.GUIDToAssetPath(g);
                    if (System.IO.Path.GetFileNameWithoutExtension(p) == assetNameNoExt)
                        return AssetDatabase.LoadAssetAtPath<ItemDefinition>(p);
                }
                return null;
            }
            BlueprintDataCoreItem FindBlueprint(string assetNameNoExt)
            {
                var guids = AssetDatabase.FindAssets(assetNameNoExt + " t:BlueprintDataCoreItem");
                foreach (var g in guids)
                {
                    var p = AssetDatabase.GUIDToAssetPath(g);
                    if (System.IO.Path.GetFileNameWithoutExtension(p) == assetNameNoExt)
                        return AssetDatabase.LoadAssetAtPath<BlueprintDataCoreItem>(p);
                }
                return null;
            }

            var ironIngot   = FindItem("Item_IronIngot");
            var copperIngot = FindItem("Item_CopperIngot");
            var steelIngot  = FindItem("Item_SteelIngot");
            var coal        = FindItem("Item_Coal");
            var stone       = FindItem("Item_Stone");
            var copperWire  = FindItem("Item_CopperLVWire");
            var goldWire    = FindItem("Item_GoldLVWire");
            var sciT1       = FindItem("Item_ScienceT1");
            var sciT2       = FindItem("Item_ScienceT2");
            var ironPlate   = FindItem("Item_IronPlate");
            var steelPlate  = FindItem("Item_SteelPlate");
            var circuit     = FindItem("Item_Circuit");
            var plastic     = FindItem("Item_Plastic");
            var glass       = FindItem("Item_Glass");
            var pirateJackPumpHead = FindItem("Item_PirateJackPumpHead");

            var bpNacelle = FindBlueprint("Item_Blueprint_Nacelle_t90");
            var bpGearbox = FindBlueprint("Item_Blueprint_Gearbox_t90");
            var bpBlade   = FindBlueprint("Item_Blueprint_Blade_t90");
            var bpTower   = FindBlueprint("Item_Blueprint_Tower_t90");
            var allBps = new System.Collections.Generic.List<BlueprintDataCoreItem>();
            foreach (var b in new[] { bpNacelle, bpGearbox, bpBlade, bpTower }) if (b != null) allBps.Add(b);

            // Themed loot pools per planet.
            System.Collections.Generic.List<ItemDefinition> LootComps(string theme)
            {
                var l = new System.Collections.Generic.List<ItemDefinition>();
                void Add(params ItemDefinition[] its) { foreach (var i in its) if (i != null) l.Add(i); }
                switch (theme)
                {
                    case "Moon":   Add(steelPlate, ironPlate, copperWire, sciT1, glass); break;            // refined lunar salvage + science
                    case "Mars":   Add(ironIngot, ironPlate, coal, copperIngot, steelPlate); break;        // iron-oxide world
                    case "Venus":  Add(copperIngot, copperWire, circuit, steelPlate, coal); break;         // pressure-smelted salvage
                    case "Acid":   Add(circuit, copperWire, plastic, ironPlate, steelIngot); break;        // bio-corroded tech
                    case "Pirate": Add(steelPlate, ironPlate, copperWire, circuit, goldWire, coal, sciT2); break; // stolen everything
                    case "Greek":  Add(goldWire, copperIngot, steelIngot, ironIngot, sciT2, stone); break; // opulent hoard
                    case "Ice":      Add(copperWire, circuit, ironPlate, sciT1, glass); break;             // cryo salvage
                    case "Water":    Add(copperIngot, copperWire, goldWire, circuit, sciT2); break;        // barnacled salvage
                    case "Desolate": Add(ironIngot, ironPlate, coal, stone); break;                         // scant scrap
                    case "Volcanic": Add(ironIngot, ironPlate, copperIngot, coal, steelIngot); break;      // smelt-rich
                    case "Crystal":  Add(goldWire, copperWire, circuit, sciT2, glass); break;              // luminous salvage
                }
                if (l.Count == 0 && ironIngot != null) l.Add(ironIngot);
                return l;
            }
            ItemDefinition[] LootFuel(string theme)
            {
                if (theme == "Pirate" || theme == "Mars") return coal != null ? new[] { coal } : new ItemDefinition[0];
                return System.Array.Empty<ItemDefinition>();
            }
            BlueprintDataCoreItem[] LootBps(string theme)
            {
                // Greek/Pirate carry the full blueprint set (treasure / stolen caches).
                if (theme == "Pirate" || theme == "Greek") return allBps.ToArray();
                if (allBps.Count > 0) return new[] { allBps[0] };
                return System.Array.Empty<BlueprintDataCoreItem>();
            }

            // ── Procedural ruin textures (styles 0-4 shared with crusader ruins, 5-10 new) ──
            Texture2D GetCelestialTex(string texName, int style)
            {
                string texPath = $"{MISC_PREFABS}/{texName}.asset";
                var existing = AssetDatabase.LoadAssetAtPath<Texture2D>(texPath);
                if (existing != null) return existing;
                const int size = 128;
                var texture = new Texture2D(size, size, TextureFormat.RGBA32, false)
                { name = texName, wrapMode = TextureWrapMode.Repeat, filterMode = FilterMode.Bilinear };
                var px = new Color[size * size];
                for (int y = 0; y < size; y++)
                for (int x = 0; x < size; x++)
                {
                    float nx = x / (float)size, ny = y / (float)size;
                    float n = Mathf.PerlinNoise(nx * 8f + style * 4.7f, ny * 8f + style * 2.3f) - 0.5f;
                    float pat = n;
                    switch (style)
                    {
                        case 0: // rusted iron plating (shared)
                            pat = n * 0.30f + Mathf.Sin(ny * 110f + n * 3f) * 0.045f;
                            if (x % 48 < 2 || y % 48 < 2) pat -= 0.13f;
                            int rx = x % 48, ry = y % 48;
                            if ((rx < 4 && ry < 4) || (rx > 44 && ry > 44) || (rx < 4 && ry > 44) || (rx > 44 && ry < 4)) pat += 0.15f;
                            break;
                        case 1: // weathered stone (shared)
                            pat = n * 0.50f + Mathf.PerlinNoise(nx * 22f, ny * 22f) * 0.20f - 0.10f;
                            if (Mathf.PerlinNoise(nx * 4f + 5f, ny * 4f + 5f) < 0.34f) pat -= 0.20f;
                            break;
                        case 5: // marble — pale with grey veins
                            pat = n * 0.06f;
                            float vein = Mathf.PerlinNoise(nx * 6f, ny * 6f);
                            if (vein > 0.62f || vein < 0.30f) pat -= 0.18f * Mathf.SmoothStep(0.62f, 0.85f, vein);
                            break;
                        case 6: // scrap / patchwork plating — cellular regions + heavy rivets
                            pat = (Mathf.PerlinNoise(nx * 6f, ny * 6f) - 0.5f) * 0.5f;
                            if ((x / 32 + y / 32) % 2 == 0) pat += 0.12f;
                            if (x % 32 < 2 || y % 32 < 2) pat -= 0.18f;
                            int sx = x % 32, sy = y % 32;
                            if ((sx < 3 && sy < 3) || (sx > 29 && sy > 29)) pat += 0.16f;
                            break;
                        case 7: // lunar regolith / crystal — faceted pale speckle
                            pat = (Mathf.PerlinNoise(nx * 14f, ny * 14f) - 0.5f) * 0.30f;
                            if (((int)(nx * 8) + (int)(ny * 8)) % 2 == 0) pat -= 0.10f;
                            pat += (Mathf.PerlinNoise(nx * 40f, ny * 40f) - 0.5f) * 0.10f;
                            break;
                        case 8: // sulfur / corroded brass — pitted crust
                            pat = n * 0.25f;
                            if (Mathf.PerlinNoise(nx * 16f, ny * 16f) < 0.40f) pat -= 0.30f; // pits
                            break;
                        case 9: // bio-acid — bubbly dissolved surface
                            pat = (Mathf.PerlinNoise(nx * 9f, ny * 9f) - 0.5f) * 0.6f;
                            if (Mathf.PerlinNoise(nx * 20f, ny * 20f) > 0.6f) pat += 0.18f; // bubbles
                            if (Mathf.PerlinNoise(nx * 5f, ny * 5f) < 0.38f) pat -= 0.30f;   // dissolved patches
                            break;
                        case 11: // basalt / volcanic — dark rock with glowing magma veins
                            pat = (Mathf.PerlinNoise(nx * 10f, ny * 10f) - 0.5f) * 0.40f;
                            if (Mathf.PerlinNoise(nx * 5f, ny * 5f) > 0.66f) pat += 0.45f;   // magma cracks glow brighter
                            break;
                        case 12: // crystal / geode — faceted luminous prismatic
                            pat = (Mathf.PerlinNoise(nx * 6f, ny * 6f) - 0.5f) * 0.30f;
                            if (((int)(nx * 5) + (int)(ny * 5)) % 2 == 0) pat -= 0.10f;       // facets
                            if (Mathf.PerlinNoise(nx * 18f, ny * 18f) > 0.7f) pat += 0.25f;   // sparkle
                            break;
                        case 13: // ice / glacial — pale cracked crystalline
                            pat = n * 0.16f;
                            if (Mathf.PerlinNoise(nx * 5f, ny * 5f) < 0.36f) pat -= 0.22f;    // fracture lines
                            if (Mathf.PerlinNoise(nx * 26f, ny * 26f) > 0.74f) pat += 0.12f;  // frost sparkle
                            break;
                        default: // martian dust-rock — fine red grain
                            pat = n * 0.40f + (Mathf.PerlinNoise(nx * 30f, ny * 30f) - 0.5f) * 0.18f;
                            if (Mathf.PerlinNoise(nx * 3f, ny * 3f) < 0.34f) pat -= 0.12f;
                            break;
                    }
                    Color c = Color.white * (1f + pat * 0.5f);
                    c.a = 1f;
                    px[y * size + x] = c;
                }
                texture.SetPixels(px);
                texture.Apply(false, false);
                AssetDatabase.CreateAsset(texture, texPath);
                return texture;
            }

            Material MakeCelestialMat(string matName, Texture2D tex, Color tint, float metallic, float smoothness, bool emissive)
            {
                string path = $"{MISC_PREFABS}/{matName}.mat";
                var existing = AssetDatabase.LoadAssetAtPath<Material>(path);
                bool isLegacyFlat = existing != null && existing.GetTexture("_BaseMap") == null && existing.GetTexture("_MainTex") == null;
                if (existing != null && !isLegacyFlat) return existing;
                if (isLegacyFlat) AssetDatabase.DeleteAsset(path);
                var sh = Shader.Find("Universal Render Pipeline/Lit") ?? Shader.Find("Standard");
                var mat = new Material(sh) { name = matName, enableInstancing = true };
                if (mat.HasProperty("_BaseColor")) mat.SetColor("_BaseColor", tint); else mat.color = tint;
                if (mat.HasProperty("_BaseMap")) mat.SetTexture("_BaseMap", tex);
                if (mat.HasProperty("_MainTex")) mat.SetTexture("_MainTex", tex);
                if (mat.HasProperty("_Metallic")) mat.SetFloat("_Metallic", metallic);
                if (mat.HasProperty("_Smoothness")) mat.SetFloat("_Smoothness", smoothness);
                if (emissive)
                {
                    if (mat.HasProperty("_EmissionColor")) mat.SetColor("_EmissionColor", tint);
                    mat.globalIlluminationFlags = MaterialGlobalIlluminationFlags.RealtimeEmissive;
                    mat.EnableKeyword("_EMISSION");
                }
                AssetDatabase.CreateAsset(mat, path);
                return mat;
            }

            // Shared textures (created once, reused across all celestial ruins + crusader ruins)
            var texRust    = GetCelestialTex("Tex_Ruin_RustPlate", 0);
            var texStone   = GetCelestialTex("Tex_Ruin_Stone", 1);
            var texMarble  = GetCelestialTex("Tex_Ruin_Marble", 5);
            var texScrap   = GetCelestialTex("Tex_Ruin_Scrap", 6);
            var texRegolith= GetCelestialTex("Tex_Ruin_Regolith", 7);
            var texSulfur  = GetCelestialTex("Tex_Ruin_Sulfur", 8);
            var texAcid    = GetCelestialTex("Tex_Ruin_Acid", 9);
            var texMartian = GetCelestialTex("Tex_Ruin_Martian", 10);
            var texBasalt  = GetCelestialTex("Tex_Ruin_Basalt", 11);
            var texCrystal = GetCelestialTex("Tex_Ruin_Crystal", 12);
            var texIce     = GetCelestialTex("Tex_Ruin_Ice", 13);

            // ── Theme material bundles ──
            System.Collections.Generic.Dictionary<string, Material> _matCache = new System.Collections.Generic.Dictionary<string, Material>();
            Material TM(string key, Texture2D tex, Color tint, float metallic, float smooth, bool emissive = false)
            {
                if (_matCache.TryGetValue(key, out var m)) return m;
                m = MakeCelestialMat($"Mat_CelestialRuin_{key}", tex, tint, metallic, smooth, emissive);
                _matCache[key] = m;
                return m;
            }

            // Resolve the full material set for a theme.
            var matSet = new System.Collections.Generic.Dictionary<string, System.Collections.Generic.Dictionary<string, Material>>();
            void DefineTheme(string theme,
                Texture2D primTex, Color prim, float primMetal,
                Texture2D stoneTex, Color stoneCol,
                Color accent, Color glow, bool primEmissive = false)
            {
                var d = new System.Collections.Generic.Dictionary<string, Material>();
                d["primary"] = TM(theme + "_Primary", primTex, prim, primMetal, primEmissive ? 0.6f : 0.34f, primEmissive);
                d["primaryDark"] = TM(theme + "_PrimaryDark", primTex, MulA(prim, 0.62f), primMetal, 0.24f, false);
                Color lt = prim * 1.3f; lt.a = 1f;
                d["primaryLight"] = TM(theme + "_PrimaryLight", primTex, lt, Mathf.Max(0f, primMetal - 0.1f), 0.42f, false);
                d["stone"] = TM(theme + "_Stone", stoneTex, stoneCol, 0f, 0.12f, false);
                Color stoneD = stoneCol * 0.7f; stoneD.a = 1f;
                d["stoneDark"] = TM(theme + "_StoneDark", stoneTex, stoneD, 0f, 0.10f, false);
                d["accent"] = TM(theme + "_Accent", primTex, accent, 0.9f, 0.5f, theme == "Pirate" || theme == "Volcanic" || theme == "Crystal");
                d["chest"] = TM(theme + "_Chest", primTex, MulA(prim, 0.5f), 0.9f, 0.3f, false);
                matSet[theme] = d;
            }
            Color MulA(Color c, float f) { c *= f; c.a = 1f; return c; }

            DefineTheme("Moon",   texRegolith, new Color(0.62f,0.64f,0.68f), 0.55f, texRegolith, new Color(0.50f,0.52f,0.55f), new Color(0.80f,0.86f,1.0f), new Color(0.55f,0.75f,1.0f));
            DefineTheme("Mars",   texMartian,  new Color(0.62f,0.34f,0.20f), 0.6f,  texMartian,  new Color(0.55f,0.30f,0.18f), new Color(0.85f,0.45f,0.20f), new Color(1.0f,0.55f,0.25f));
            DefineTheme("Venus",  texSulfur,   new Color(0.72f,0.60f,0.22f), 0.7f,  texSulfur,   new Color(0.50f,0.40f,0.16f), new Color(0.95f,0.72f,0.20f), new Color(1.0f,0.78f,0.30f));
            DefineTheme("Acid",   texAcid,     new Color(0.46f,0.60f,0.28f), 0.5f,  texAcid,     new Color(0.36f,0.44f,0.22f), new Color(0.55f,0.95f,0.35f), new Color(0.45f,1.0f,0.40f));
            DefineTheme("Pirate", texScrap,    new Color(0.44f,0.40f,0.36f), 0.6f,  texScrap,    new Color(0.32f,0.30f,0.28f), new Color(0.95f,0.25f,0.20f), new Color(1.0f,0.35f,0.18f), true);
            DefineTheme("Greek",  texMarble,   new Color(0.90f,0.88f,0.82f), 0.0f,  texMarble,   new Color(0.84f,0.82f,0.76f), new Color(0.92f,0.78f,0.28f), new Color(1.0f,0.86f,0.45f));
            // ── Phase 1 expansion themes ──
            DefineTheme("Ice",      texIce,     new Color(0.74f,0.84f,0.92f), 0.2f,  texIce,      new Color(0.62f,0.74f,0.86f), new Color(0.70f,0.90f,1.00f), new Color(0.60f,0.85f,1.0f));
            DefineTheme("Water",    texAcid,    new Color(0.34f,0.52f,0.58f), 0.4f,  texAcid,     new Color(0.28f,0.42f,0.48f), new Color(0.30f,0.78f,0.82f), new Color(0.35f,0.85f,0.95f));
            DefineTheme("Desolate", texMartian, new Color(0.50f,0.47f,0.42f), 0.5f,  texMartian,  new Color(0.42f,0.40f,0.37f), new Color(0.66f,0.60f,0.46f), new Color(0.80f,0.74f,0.50f));
            DefineTheme("Volcanic", texBasalt,  new Color(0.22f,0.16f,0.16f), 0.3f,  texBasalt,   new Color(0.16f,0.12f,0.12f), new Color(1.00f,0.42f,0.10f), new Color(1.0f,0.45f,0.12f), false);
            DefineTheme("Crystal",  texCrystal, new Color(0.66f,0.58f,0.92f), 0.1f,  texCrystal,  new Color(0.56f,0.48f,0.84f), new Color(0.70f,0.55f,1.00f), new Color(0.70f,0.55f,1.0f));

            // ══════════ THEMED RUIN BUILDER ══════════
            GameObject MakeCelestialRuin(string name, string theme, string archetype, int extent, int minComp, int maxComp)
            {
                var M = matSet[theme];
                var salvageStone = FindItem("Item_Stone");
                var salvageMetal = FindItem("Item_IronIngot");
                var salvageWood = FindItem("Item_WoodLog");
                string prefabPath = $"{CELEST_PREFABS}/{name}.prefab";
                Color beaconColor = theme switch
                {
                    "Moon" => new Color(0.55f, 0.75f, 1.0f),
                    "Mars" => new Color(1.0f, 0.55f, 0.25f),
                    "Venus" => new Color(1.0f, 0.78f, 0.30f),
                    "Acid" => new Color(0.45f, 1.0f, 0.40f),
                    "Pirate" => new Color(1.0f, 0.35f, 0.18f),
                    "Greek" => new Color(1.0f, 0.86f, 0.45f),
                    "Ice" => new Color(0.60f, 0.85f, 1.0f),
                    "Water" => new Color(0.35f, 0.85f, 0.95f),
                    "Desolate" => new Color(0.80f, 0.74f, 0.50f),
                    "Volcanic" => new Color(1.0f, 0.45f, 0.12f),
                    "Crystal" => new Color(0.70f, 0.55f, 1.0f),
                    _ => new Color(1.0f, 0.86f, 0.45f),
                };

                // Non-destructive: preserve hand-tuned loot.
                ItemDefinition[] keepC = null; ItemDefinition[] keepF = null; BlueprintDataCoreItem[] keepB = null;
                int keepMin = minComp, keepMax = maxComp; string keepName = null;
                {
                    var ex = AssetDatabase.LoadAssetAtPath<GameObject>(prefabPath);
                    if (ex != null)
                    {
                        var pc = ex.GetComponent<VoxelEngine.Exploration.RuinChest>();
                        if (pc != null)
                        {
                            if (pc.possibleComponents != null && pc.possibleComponents.Length > 0) keepC = pc.possibleComponents;
                            if (pc.possibleFuel != null && pc.possibleFuel.Length > 0) keepF = pc.possibleFuel;
                            if (pc.possibleBlueprints != null && pc.possibleBlueprints.Length > 0) keepB = pc.possibleBlueprints;
                            if (pc.minComponents > 0) keepMin = pc.minComponents;
                            if (pc.maxComponents > 0) keepMax = pc.maxComponents;
                            if (!string.IsNullOrEmpty(pc.ruinName)) keepName = pc.ruinName;
                        }
                    }
                }

                var root = new GameObject(name);

                // ── Per-variant architecture flags (every ruin gets a distinct silhouette) ──
                float  module        = 3.75f;
                bool   wantTall      = name.Contains("Tower") || name.Contains("Spire") || name.Contains("Citadel");
                bool   wantLow       = name.Contains("Bunker") || name.Contains("Cache") || name.Contains("Vault");
                bool   wantHeavyRuin = name.Contains("Wreck") || name.Contains("Camp") || name.Contains("Dissolved") || name.Contains("Dry") || name.Contains("Ash") || name.Contains("Frontier");
                bool   wantStilts    = name.Contains("Stilt") || name.Contains("Platform");
                bool   wantSunken    = name.Contains("Sunken");
                bool   wantForge     = name.Contains("Forge") || name.Contains("Refinery");
                bool   wantAntenna   = name.Contains("Listening") || name.Contains("Post") || name.Contains("Station");
                bool   wantAltar     = name.Contains("Shrine") || name.Contains("Temple") || name.Contains("Oracle") || name.Contains("Treasury");
                bool   wantShipwreck = name.Contains("Wreck") || name.Contains("Camp");
                bool   wantBanner    = (archetype == "Fortress") && !wantLow && UnityEngine.Random.value < 0.6f;
                bool   wantColumns   = (archetype == "Fortress") && extent >= 2 && !wantLow && UnityEngine.Random.value < 0.6f;

                float  W             = extent * module;
                float  footW         = (extent * 2 + 1) * module;
                float  wallHeight    = (wantLow ? 0.6f : wantTall ? 1.3f : 1.0f) * module;
                float  ruinChance    = wantHeavyRuin ? 0.30f : 0.13f;

                // ── Block helpers ──
                GameObject AddBlock(string childName, Vector3 localPos, Vector3 localScale, Material mat, int hp)
                {
                    var go = GameObject.CreatePrimitive(PrimitiveType.Cube);
                    go.name = childName;
                    go.transform.SetParent(root.transform, false);
                    go.transform.localPosition = localPos;
                    go.transform.localScale = localScale;
                    if (mat != null) { var r = go.GetComponent<Renderer>(); if (r != null) r.sharedMaterial = mat; }
                    var pb = go.GetComponent<VoxelEngine.Building.PlacedBlock>();
                    if (pb == null) pb = go.AddComponent<VoxelEngine.Building.PlacedBlock>();
                    pb.Hp = Mathf.Max(10, hp);
                    if (salvageStone != null || salvageMetal != null)
                    {
                        var rd = go.AddComponent<VoxelEngine.Exploration.RuinBlockDrop>();
                        rd.salvage = (mat == M["stone"] || mat == M["stoneDark"]) ? salvageStone : salvageMetal;
                    }
                    return go;
                }
                GameObject AddBlockRot(string childName, Vector3 localPos, Vector3 localScale, Material mat, int hp, Quaternion rot)
                { var go = AddBlock(childName, localPos, localScale, mat, hp); go.transform.localRotation = rot; return go; }
                GameObject AddDecor(string childName, Vector3 localPos, Vector3 localScale, Material mat, Quaternion rot)
                {
                    var go = GameObject.CreatePrimitive(PrimitiveType.Cube);
                    go.name = childName;
                    go.transform.SetParent(root.transform, false);
                    go.transform.localPosition = localPos; go.transform.localRotation = rot; go.transform.localScale = localScale;
                    if (mat != null) { var r = go.GetComponent<Renderer>(); if (r != null) r.sharedMaterial = mat; }
                    var col = go.GetComponent<Collider>(); if (col != null) UnityEngine.Object.DestroyImmediate(col);
                    return go;
                }
                GameObject AddPrim(string childName, PrimitiveType pt, Vector3 localPos, Vector3 localScale, Material mat, int hp, Quaternion rot)
                {
                    var go = GameObject.CreatePrimitive(pt);
                    go.name = childName;
                    go.transform.SetParent(root.transform, false);
                    go.transform.localPosition = localPos; go.transform.localRotation = rot; go.transform.localScale = localScale;
                    if (mat != null) { var r = go.GetComponent<Renderer>(); if (r != null) r.sharedMaterial = mat; }
                    var pb = go.GetComponent<VoxelEngine.Building.PlacedBlock>();
                    if (pb == null) pb = go.AddComponent<VoxelEngine.Building.PlacedBlock>();
                    pb.Hp = Mathf.Max(10, hp);
                    if (salvageStone != null || salvageMetal != null)
                    {
                        var rd = go.AddComponent<VoxelEngine.Exploration.RuinBlockDrop>();
                        rd.salvage = (mat == M["stone"] || mat == M["stoneDark"]) ? salvageStone : salvageMetal;
                    }
                    return go;
                }

                float deckTopY = 0.62f;
                Material PM() => UnityEngine.Random.value < 0.7f ? M["primary"] : (UnityEngine.Random.value < 0.5f ? M["primaryDark"] : M["primaryLight"]);

                // ── Foundation (shared two-tier plinth) ──
                AddBlock("Foundation_Plinth", new Vector3(0, 0.25f, 0), new Vector3(footW + 0.9f, 0.5f, footW + 0.9f), M["stoneDark"], 420);
                AddBlock("Foundation_Deck", new Vector3(0, 0.56f, 0), new Vector3(footW, 0.12f, footW), M["stone"], 380);
                if (wantStilts)
                {
                    foreach (float sx in new float[] { -1f, -0.35f, 0.35f, 1f })
                    foreach (float sz in new float[] { -1f, -0.35f, 0.35f, 1f })
                        AddBlock($"Stilt_{sx}_{sz}", new Vector3(sx * W, -0.9f, sz * W), new Vector3(0.3f, 2.6f, 0.3f), M["primaryDark"], 200);
                }

                float buildHeight = wallHeight;

                if (archetype == "Temple")
                {
                    float colH = module * 1.05f;
                    float colY = deckTopY + colH * 0.5f;
                    float colR = 0.34f;
                    for (int xi = -extent; xi <= extent; xi++)
                    {
                        AddPrim($"Col_N_{xi}", PrimitiveType.Cylinder, new Vector3(xi * module, colY, W), new Vector3(colR, colH * 0.5f, colR), M["stone"], 240, Quaternion.identity);
                        AddPrim($"Col_S_{xi}", PrimitiveType.Cylinder, new Vector3(xi * module, colY, -W), new Vector3(colR, colH * 0.5f, colR), M["stone"], 240, Quaternion.identity);
                    }
                    for (int zi = -extent + 1; zi <= extent - 1; zi++)
                    {
                        AddPrim($"Col_E_{zi}", PrimitiveType.Cylinder, new Vector3(W, colY, zi * module), new Vector3(colR, colH * 0.5f, colR), M["stone"], 240, Quaternion.identity);
                        AddPrim($"Col_W_{zi}", PrimitiveType.Cylinder, new Vector3(-W, colY, zi * module), new Vector3(colR, colH * 0.5f, colR), M["stone"], 240, Quaternion.identity);
                    }
                    float capY = deckTopY + colH;
                    void CapRow(string side, float edge, bool alongX)
                    {
                        int lo = alongX ? -extent : -extent + 1, hi = alongX ? extent : extent - 1;
                        for (int i = lo; i <= hi; i++)
                        {
                            Vector3 p = alongX ? new Vector3(i * module, capY + 0.08f, edge) : new Vector3(edge, capY + 0.08f, i * module);
                            AddDecor($"Cap_{side}_{i}", p, new Vector3(colR * 1.8f, 0.16f, colR * 1.8f), M["stone"], Quaternion.identity);
                        }
                    }
                    CapRow("N", W, true); CapRow("S", -W, true); CapRow("E", W, false); CapRow("W", -W, false);
                    float entY = capY + 0.22f;
                    AddBlock("Entablature_N", new Vector3(0, entY, W), new Vector3(footW, 0.34f, 0.4f), M["accent"], 260);
                    AddBlock("Entablature_S", new Vector3(0, entY, -W), new Vector3(footW, 0.34f, 0.4f), M["accent"], 260);
                    AddBlock("Entablature_E", new Vector3(W, entY, 0), new Vector3(0.4f, 0.34f, footW), M["accent"], 260);
                    AddBlock("Entablature_W", new Vector3(-W, entY, 0), new Vector3(0.4f, 0.34f, footW), M["accent"], 260);
                    float pedBase = entY + 0.20f, pedHalf = footW * 0.5f;
                    AddBlockRot("Pediment_NL", new Vector3(-pedHalf * 0.5f, pedBase + 0.5f, W), new Vector3(pedHalf, 0.16f, 0.5f), M["stone"], 220, Quaternion.Euler(0, 0, 14f));
                    AddBlockRot("Pediment_NR", new Vector3(pedHalf * 0.5f, pedBase + 0.5f, W), new Vector3(pedHalf, 0.16f, 0.5f), M["stone"], 220, Quaternion.Euler(0, 0, -14f));
                    AddBlockRot("Pediment_SL", new Vector3(-pedHalf * 0.5f, pedBase + 0.5f, -W), new Vector3(pedHalf, 0.16f, 0.5f), M["stone"], 220, Quaternion.Euler(0, 0, 14f));
                    AddBlockRot("Pediment_SR", new Vector3(pedHalf * 0.5f, pedBase + 0.5f, -W), new Vector3(pedHalf, 0.16f, 0.5f), M["stone"], 220, Quaternion.Euler(0, 0, -14f));
                    // Sloped gable roof over the cella (ridge runs along X)
                    AddBlockRot("Roof_N", new Vector3(0, pedBase + W * 0.16f, W * 0.5f), new Vector3(footW, 0.18f, W * 1.0f), M["primary"], 240, Quaternion.Euler(20f, 0, 0));
                    AddBlockRot("Roof_S", new Vector3(0, pedBase + W * 0.16f, -W * 0.5f), new Vector3(footW, 0.18f, W * 1.0f), M["primary"], 240, Quaternion.Euler(-20f, 0, 0));
                    AddBlock("RoofRidge", new Vector3(0, pedBase + W * 0.34f, 0), new Vector3(footW, 0.16f, 0.2f), M["accent"], 220);
                    float cellaH = colH * 0.86f, cellaY = deckTopY + cellaH * 0.5f, cellaW = W * 0.6f;
                    AddBlock("Cella_W", new Vector3(-cellaW, cellaY, 0), new Vector3(0.2f, cellaH, W * 1.2f), M["stoneDark"], 240);
                    AddBlock("Cella_E", new Vector3(cellaW, cellaY, 0), new Vector3(0.2f, cellaH, W * 1.2f), M["stoneDark"], 240);
                    AddBlock("Cella_N", new Vector3(0, cellaY, W * 0.6f), new Vector3(cellaW * 2, cellaH, 0.2f), M["stoneDark"], 240);
                    AddBlock("Cella_S", new Vector3(0, cellaY, -W * 0.6f), new Vector3(cellaW * 2, cellaH, 0.2f), M["stoneDark"], 240);
                    buildHeight = colH + 1.4f;
                }
                else if (archetype == "Dome")
                {
                    float ringY = deckTopY + wallHeight * 0.5f;
                    for (int xi = -extent; xi <= extent; xi++)
                    {
                        if (xi == 0) continue; // airlock opening on +Z
                        AddBlock($"Wall_N_{xi}", new Vector3(xi * module, ringY, W), new Vector3(module * 0.99f, wallHeight, 0.3f), PM(), 260);
                        AddBlock($"Wall_S_{xi}", new Vector3(xi * module, ringY, -W), new Vector3(module * 0.99f, wallHeight, 0.3f), PM(), 260);
                    }
                    for (int zi = -extent + 1; zi <= extent - 1; zi++)
                    {
                        AddBlock($"Wall_E_{zi}", new Vector3(W, ringY, zi * module), new Vector3(0.3f, wallHeight, module * 0.99f), PM(), 260);
                        AddBlock($"Wall_W_{zi}", new Vector3(-W, ringY, zi * module), new Vector3(0.3f, wallHeight, module * 0.99f), PM(), 260);
                    }
                    AddBlock("Airlock_L", new Vector3(-0.9f, ringY, W), new Vector3(0.3f, wallHeight, 0.5f), M["primaryDark"], 280);
                    AddBlock("Airlock_R", new Vector3(0.9f, ringY, W), new Vector3(0.3f, wallHeight, 0.5f), M["primaryDark"], 280);
                    AddBlock("Airlock_Top", new Vector3(0, deckTopY + wallHeight - 0.15f, W), new Vector3(2.1f, 0.3f, 0.5f), M["accent"], 260);
                    float domeBase = deckTopY + wallHeight;
                    float domeRadius = footW * 0.62f;
                    AddPrim("DomeDrum", PrimitiveType.Cylinder, new Vector3(0, domeBase + 0.35f, 0), new Vector3(footW * 0.55f, 0.35f, footW * 0.55f), M["primaryDark"], 240, Quaternion.identity);
                    int capCount = 3; // full dome — drum fills the eaves
                    for (int i = 0; i < capCount; i++)
                    {
                        float frac = 1f - i * 0.28f;
                        Quaternion tilt = wantHeavyRuin ? Quaternion.Euler(UnityEngine.Random.Range(-6f, 6f), 0, UnityEngine.Random.Range(-6f, 6f)) : Quaternion.identity;
                        AddPrim($"DomeCap_{i}", PrimitiveType.Sphere, new Vector3(0, domeBase + i * 0.5f, 0), new Vector3(domeRadius * frac, domeRadius * frac * 0.55f, domeRadius * frac), M["primary"], 280, tilt);
                    }
                    AddPrim("Antenna", PrimitiveType.Cylinder, new Vector3(W * 0.4f, domeBase + wallHeight * 0.6f, -W * 0.4f), new Vector3(0.05f, wallHeight * 0.6f, 0.05f), M["accent"], 160, Quaternion.identity);
                    AddDecor("AntennaTip", new Vector3(W * 0.4f, domeBase + wallHeight * 1.1f, -W * 0.4f), new Vector3(0.16f, 0.16f, 0.16f), M["accent"], Quaternion.identity);
                    if (wantAntenna) // comms array: extra masts
                        for (int i = 0; i < 3; i++)
                            AddPrim($"CommMast_{i}", PrimitiveType.Cylinder, new Vector3(-W * 0.4f + i * 0.5f, domeBase + wallHeight * 0.5f, W * 0.4f), new Vector3(0.04f, wallHeight * 0.9f, 0.04f), M["accent"], 140, Quaternion.Euler(0, 0, UnityEngine.Random.Range(-4f, 4f)));
                    if (theme == "Venus")
                        AddBlockRot("MeltDrip", new Vector3(W * 0.5f, deckTopY + 0.4f, W * 0.5f), new Vector3(0.3f, 0.9f, 0.3f), M["primaryLight"], 120, Quaternion.Euler(12f, 0f, 8f));
                    else if (theme == "Ice")
                        for (int i = 0; i < 4; i++) { float a = i / 4f * Mathf.PI * 2f; AddPrim($"IceSpike_{i}", PrimitiveType.Cube, new Vector3(Mathf.Cos(a) * domeRadius * 0.7f, domeBase + domeRadius * 0.3f, Mathf.Sin(a) * domeRadius * 0.7f), new Vector3(0.3f, 1.4f, 0.3f), M["accent"], 120, Quaternion.Euler(UnityEngine.Random.Range(-10f, 10f), 0f, UnityEngine.Random.Range(-10f, 10f))); }
                    else if (theme == "Crystal")
                        for (int i = 0; i < 5; i++) { float a = i / 5f * Mathf.PI * 2f; AddPrim($"GeodeCluster_{i}", PrimitiveType.Cube, new Vector3(Mathf.Cos(a) * domeRadius * 0.8f, domeBase + domeRadius * 0.4f, Mathf.Sin(a) * domeRadius * 0.8f), new Vector3(0.34f, 1.0f, 0.34f), M["accent"], 120, Quaternion.Euler(UnityEngine.Random.Range(-15f, 15f), UnityEngine.Random.Range(0, 360f), UnityEngine.Random.Range(-15f, 15f))); }
                    else if (theme == "Volcanic")
                        AddDecor("MagmaVent", new Vector3(0, deckTopY + 0.07f, 0), new Vector3(footW * 0.5f, 0.06f, footW * 0.5f), M["accent"], Quaternion.identity);
                    else if (theme == "Water" && wantSunken)
                        AddDecor("AlgaeMat", new Vector3(0, deckTopY + 0.02f, 0), new Vector3(footW * 0.7f, 0.05f, footW * 0.5f), M["accent"], Quaternion.identity);
                    buildHeight = wallHeight + domeRadius * 0.55f * 3f * 0.5f + 1.5f;
                }
                else // Fortress (Mars / Acid / Pirate / Ice / Water / Desolate / Volcanic / Crystal)
                {
                    float wallY = deckTopY + wallHeight * 0.5f;
                    float wallThick = wantLow ? 0.5f : 0.3f;
                    float cornerH = wallHeight * (wantTall ? 2.2f : 1.18f);
                    float cornerY = deckTopY + cornerH * 0.5f;
                    float pillarW = module * 0.5f;
                    float[] sgn = { -1f, 1f };
                    foreach (float sx in sgn) foreach (float sz in sgn)
                        AddBlock($"Pillar_{(sx<0?"W":"E")}{(sz<0?"S":"N")}", new Vector3(sx * W, cornerY, sz * W), new Vector3(pillarW, cornerH, pillarW), M["stone"], 360);

                    void WallPanel(string label, float x, float z, bool alongX)
                    {
                        Vector3 full = alongX ? new Vector3(module * 0.99f, wallHeight, wallThick) : new Vector3(wallThick, wallHeight, module * 0.99f);
                        if (UnityEngine.Random.value < ruinChance)
                        {
                            Vector3 sill = alongX ? new Vector3(module * 0.99f, wallHeight * 0.34f, wallThick) : new Vector3(wallThick, wallHeight * 0.34f, module * 0.99f);
                            AddBlock($"Sill_{label}", new Vector3(x, deckTopY + wallHeight * 0.17f, z), sill, M["primaryDark"], 160);
                            return;
                        }
                        AddBlock($"Wall_{label}", new Vector3(x, wallY, z), full, PM(), 260);
                    }
                    bool collapsedSouth = wantHeavyRuin;
                    for (int xi = -extent; xi <= extent; xi++)
                    {
                        if (xi != 0) WallPanel($"N{xi}", xi * module, W, true);
                        if (!(collapsedSouth && xi >= -1 && xi <= 0)) WallPanel($"S{xi}", xi * module, -W, true);
                    }
                    for (int zi = -extent + 1; zi <= extent - 1; zi++)
                    { WallPanel($"E{zi}", W, zi * module, false); WallPanel($"W{zi}", -W, zi * module, false); }
                    float off = module * 0.32f;
                    AddBlock("Gate_L", new Vector3(-off, wallY, W), new Vector3(wallThick * 1.5f, wallHeight, wallThick * 1.5f), M["stoneDark"], 300);
                    AddBlock("Gate_R", new Vector3(off, wallY, W), new Vector3(wallThick * 1.5f, wallHeight, wallThick * 1.5f), M["stoneDark"], 300);
                    AddBlock("Gate_Top", new Vector3(0, deckTopY + wallHeight * 0.9f, W), new Vector3(off * 2 + wallThick * 1.5f, wallHeight * 0.2f, wallThick * 1.6f), M["accent"], 260);

                    if (!wantLow) // battlements
                    {
                        float mH = 0.85f, mY = deckTopY + wallHeight + mH * 0.5f, mW = module * 0.46f;
                        for (int xi = -extent; xi <= extent; xi++)
                        {
                            if (xi == 0) continue;
                            if (((xi + 1000) & 1) == 0 && UnityEngine.Random.value > 0.2f) AddBlock($"Merlon_N{xi}", new Vector3(xi * module, mY, W), new Vector3(mW, mH, wallThick * 1.4f), PM(), 200);
                            if (((xi + 1001) & 1) == 0 && UnityEngine.Random.value > 0.2f) AddBlock($"Merlon_S{xi}", new Vector3(xi * module, mY, -W), new Vector3(mW, mH, wallThick * 1.4f), PM(), 200);
                        }
                    }

                    // Theme signature accents (unchanged flavour)
                    if (theme == "Mars")
                        for (int i = 0; i < 4; i++) { float dx = UnityEngine.Random.Range(-W * 0.8f, W * 0.8f); AddBlockRot($"DustDrift_{i}", new Vector3(dx, 0.35f, -W - 0.6f), new Vector3(module * 0.8f, 0.7f, 1.4f), M["stone"], 80, Quaternion.Euler(0, UnityEngine.Random.Range(0, 360f), -18f)); }
                    else if (theme == "Acid")
                    {
                        for (int i = 0; i < 5; i++) { float a = i / 5f * Mathf.PI * 2f, rx = Mathf.Cos(a) * (W + 0.6f), rz = Mathf.Sin(a) * (W + 0.6f), sh = UnityEngine.Random.Range(1.6f, 3.2f); AddPrim($"Crystal_{i}", PrimitiveType.Cube, new Vector3(rx, deckTopY + sh * 0.5f, rz), new Vector3(0.3f, sh, 0.3f), M["accent"], 120, Quaternion.Euler(UnityEngine.Random.Range(-12f, 12f), UnityEngine.Random.Range(0, 360f), UnityEngine.Random.Range(-12f, 12f))); }
                        for (int i = 0; i < 4; i++) AddDecor($"SlimeDrip_{i}", new Vector3(UnityEngine.Random.Range(-W, W), deckTopY + wallHeight * 0.5f, W), new Vector3(0.08f, wallHeight * 0.8f, 0.08f), M["accent"], Quaternion.identity);
                    }
                    else if (theme == "Pirate")
                    {
                        AddDecor("NeonSign", new Vector3(0, deckTopY + wallHeight * 0.7f, -W + 0.2f), new Vector3(2.0f, 0.6f, 0.06f), M["accent"], Quaternion.identity);
                        AddDecor("NeonSign2", new Vector3(0, deckTopY + wallHeight * 0.45f, -W + 0.2f), new Vector3(1.2f, 0.18f, 0.06f), M["primaryLight"], Quaternion.identity);
                        AddDecor("Skull", new Vector3(W, deckTopY + wallHeight + 0.4f, W), new Vector3(0.6f, 0.6f, 0.4f), M["stoneDark"], Quaternion.identity);
                        AddDecor("SkullEyeL", new Vector3(W - 0.14f, deckTopY + wallHeight + 0.45f, W + 0.21f), new Vector3(0.14f, 0.16f, 0.06f), M["accent"], Quaternion.identity);
                        AddDecor("SkullEyeR", new Vector3(W + 0.14f, deckTopY + wallHeight + 0.45f, W + 0.21f), new Vector3(0.14f, 0.16f, 0.06f), M["accent"], Quaternion.identity);
                        for (int i = 0; i < 5; i++) AddBlockRot($"Junk_{i}", new Vector3(UnityEngine.Random.Range(-W, W), deckTopY + 0.3f, UnityEngine.Random.Range(-W, W)), new Vector3(0.6f, 0.6f, 0.6f), PM(), 80, Quaternion.Euler(UnityEngine.Random.Range(0, 360f), UnityEngine.Random.Range(0, 360f), UnityEngine.Random.Range(0, 360f)));
                    }
                    else if (theme == "Ice")
                        for (int i = 0; i < 5; i++) AddDecor($"Icicle_{i}", new Vector3(UnityEngine.Random.Range(-W, W), deckTopY + wallHeight * 0.45f, UnityEngine.Random.Range(-W, W)), new Vector3(0.12f, wallHeight * 0.5f, 0.12f), M["primaryLight"], Quaternion.identity);
                    else if (theme == "Volcanic")
                    {
                        for (int i = 0; i < 3; i++) AddDecor($"MagmaVent_{i}", new Vector3(UnityEngine.Random.Range(-W * 0.6f, W * 0.6f), deckTopY + 0.05f, UnityEngine.Random.Range(-W * 0.6f, W * 0.6f)), new Vector3(0.8f, 0.08f, 0.8f), M["accent"], Quaternion.identity);
                        AddDecor("CharScorch", new Vector3(0, deckTopY + wallHeight * 0.5f, W), new Vector3(footW * 0.8f, wallHeight * 0.9f, 0.05f), M["stoneDark"], Quaternion.identity);
                    }
                    else if (theme == "Crystal")
                        for (int i = 0; i < 5; i++) { float a = i / 5f * Mathf.PI * 2f, sh = UnityEngine.Random.Range(1.6f, 3.0f); AddPrim($"Geode_{i}", PrimitiveType.Cube, new Vector3(Mathf.Cos(a) * (W + 0.5f), deckTopY + sh * 0.5f, Mathf.Sin(a) * (W + 0.5f)), new Vector3(0.3f, sh, 0.3f), M["accent"], 120, Quaternion.Euler(UnityEngine.Random.Range(-12f, 12f), UnityEngine.Random.Range(0, 360f), UnityEngine.Random.Range(-12f, 12f))); }
                    else if (theme == "Water")
                        AddDecor("Barnacles", new Vector3(0, deckTopY + wallHeight * 0.3f, W), new Vector3(footW * 0.8f, wallHeight * 0.5f, 0.06f), M["accent"], Quaternion.identity);

                    buildHeight = cornerH + (wantLow ? 0.3f : 1.0f);
                    if (collapsedSouth)
                        for (int i = 0; i < 4; i++) { float cs = UnityEngine.Random.Range(0.5f, 1.0f); AddBlockRot($"Collapse_{i}", new Vector3(UnityEngine.Random.Range(-module, module), 0.3f, -W - UnityEngine.Random.Range(0.3f, 1.7f)), new Vector3(cs, cs * 0.8f, cs), PM(), 120, Quaternion.Euler(UnityEngine.Random.Range(-25f, 25f), UnityEngine.Random.Range(0, 360f), UnityEngine.Random.Range(-25f, 25f))); }

                    // Interior columns (some forts) — a few standing, a few toppled
                    if (wantColumns)
                    {
                        float colR2 = module * 0.7f, colH2 = wallHeight * 0.8f; int spot = 0;
                        foreach (float cx in new float[] { -colR2, colR2 }) foreach (float cz in new float[] { -colR2, colR2 })
                        {
                            if (UnityEngine.Random.value < 0.5f) { AddBlock($"ColBase_{spot}", new Vector3(cx, deckTopY + 0.1f, cz), new Vector3(0.6f, 0.2f, 0.6f), M["stoneDark"], 200); AddBlock($"ColShaft_{spot}", new Vector3(cx, deckTopY + 0.2f + colH2 * 0.5f, cz), new Vector3(0.44f, colH2, 0.44f), M["stone"], 180); }
                            else { AddBlockRot($"ColFallen_{spot}", new Vector3(cx + (cx < 0 ? -0.6f : 0.6f), deckTopY + 0.28f, cz + (cz < 0 ? -0.6f : 0.6f)), new Vector3(0.44f, 0.44f, colH2), M["stone"], 180, Quaternion.Euler(0f, UnityEngine.Random.Range(0, 360f), 90f)); AddBlock($"ColStub_{spot}", new Vector3(cx, deckTopY + 0.25f, cz), new Vector3(0.5f, 0.5f, 0.5f), M["stoneDark"], 180); }
                            spot++;
                        }
                    }

                    // Banner standard
                    if (wantBanner)
                    {
                        float bx = -W + pillarW * 0.5f, bz = -W + pillarW * 0.5f;
                        AddBlock("BannerPole", new Vector3(bx, deckTopY + wallHeight * 0.5f, bz), new Vector3(0.12f, wallHeight, 0.12f), M["primaryDark"], 120);
                        var cloth = AddDecor("BannerCloth", new Vector3(bx + 0.4f, deckTopY + wallHeight * 0.74f, bz), new Vector3(0.8f, wallHeight * 0.52f, 0.04f), M["accent"], Quaternion.identity);
                        cloth.transform.localRotation = Quaternion.Euler(0f, 90f, UnityEngine.Random.Range(-4f, 4f));
                    }
                }

                // ── Per-variant side/centerpiece features (NEW: silhouettes you can tell apart) ──
                if (wantForge) // industrial chimney stack at a back corner
                {
                    float chx = -W + module * 0.5f, chz = -W + module * 0.5f, chH = wallHeight * 1.6f;
                    AddPrim("Chimney", PrimitiveType.Cylinder, new Vector3(chx, deckTopY + chH * 0.5f, chz), new Vector3(0.5f, chH * 0.5f, 0.5f), M["primaryDark"], 200, Quaternion.identity);
                    AddBlock("ChimneyCap", new Vector3(chx, deckTopY + chH, chz), new Vector3(0.7f, 0.25f, 0.7f), M["stoneDark"], 160);
                    AddDecor("ChimneyGlow", new Vector3(chx, deckTopY + chH * 0.25f, chz), new Vector3(0.4f, 0.4f, 0.4f), M["accent"], Quaternion.identity);
                    buildHeight = Mathf.Max(buildHeight, chH + deckTopY);
                }
                if (wantAntenna && archetype != "Dome") // comms mast (domes add their own array above)
                {
                    float ax = W - module * 0.5f, az = -W + module * 0.5f, aH = wallHeight * 2.0f;
                    AddPrim("CommMast", PrimitiveType.Cylinder, new Vector3(ax, deckTopY + aH * 0.5f, az), new Vector3(0.06f, aH * 0.5f, 0.06f), M["accent"], 140, Quaternion.Euler(0, 0, UnityEngine.Random.Range(-3f, 3f)));
                    AddDecor("CommDish", new Vector3(ax, deckTopY + aH * 0.8f, az), new Vector3(0.5f, 0.08f, 0.5f), M["primaryLight"], Quaternion.Euler(-30f, 0, 0));
                    buildHeight = Mathf.Max(buildHeight, aH + deckTopY);
                }
                if (wantShipwreck) // crashed hull beside the compound
                {
                    float hx = W + module * 1.1f, hz = 0f;
                    AddBlockRot("HullKeel", new Vector3(hx, 0.6f, hz), new Vector3(0.6f, 0.6f, module * 2.2f), M["primary"], 160, Quaternion.Euler(0, UnityEngine.Random.Range(-20f, 20f), 22f));
                    AddBlockRot("HullDeck", new Vector3(hx, 1.2f, hz), new Vector3(1.0f, 0.2f, module * 2.0f), M["primaryDark"], 140, Quaternion.Euler(0, UnityEngine.Random.Range(-20f, 20f), 22f));
                    AddPrim("HullNose", PrimitiveType.Sphere, new Vector3(hx, 0.9f, hz + module * 1.1f), new Vector3(0.7f, 0.6f, 0.9f), M["primary"], 140, Quaternion.Euler(0, UnityEngine.Random.Range(-20f, 20f), 22f));
                }

                // ── Central dais / altar + relic chest ──
                if (wantAltar)
                {
                    AddBlock("Altar", new Vector3(0, deckTopY + 0.25f, 0), new Vector3(1.8f, 0.5f, 1.8f), M["stone"], 300);
                    // Cult statue behind the chest
                    AddPrim("StatueBase", PrimitiveType.Cube, new Vector3(0, deckTopY + 0.55f, -0.9f), new Vector3(0.5f, 0.2f, 0.5f), M["stoneDark"], 200, Quaternion.identity);
                    AddPrim("StatueBody", PrimitiveType.Cylinder, new Vector3(0, deckTopY + 1.2f, -0.9f), new Vector3(0.22f, 0.55f, 0.22f), M["accent"], 160, Quaternion.identity);
                    AddPrim("StatueHead", PrimitiveType.Sphere, new Vector3(0, deckTopY + 1.85f, -0.9f), new Vector3(0.26f, 0.26f, 0.26f), M["accent"], 140, Quaternion.identity);
                }
                else
                {
                    AddBlock("Dais", new Vector3(0, deckTopY + 0.15f, 0), new Vector3(1.7f, 0.3f, 1.7f), M["stoneDark"], 300);
                }

                // Rubble (scales with ruin level)
                int rubbleN = wantLow ? 3 : (wantHeavyRuin ? 9 : 6);
                for (int i = 0; i < rubbleN; i++)
                {
                    float rxx = UnityEngine.Random.Range(-W * 0.7f, W * 0.7f), rzz = UnityEngine.Random.Range(-W * 0.7f, W * 0.7f);
                    if (Mathf.Abs(rxx) < 1.3f && Mathf.Abs(rzz) < 1.3f) continue;
                    float rs = UnityEngine.Random.Range(0.22f, 0.55f), rr = UnityEngine.Random.value;
                    Material rm = rr < 0.4f ? M["stone"] : rr < 0.7f ? M["primaryDark"] : M["accent"];
                    AddBlockRot($"Rubble_{i}", new Vector3(rxx, deckTopY + rs * 0.4f + 0.04f, rzz), new Vector3(rs, rs * 0.8f, rs), rm, 80, Quaternion.Euler(UnityEngine.Random.Range(0, 360f), UnityEngine.Random.Range(0, 360f), UnityEngine.Random.Range(0, 360f)));
                }

                float chestY = deckTopY + (wantAltar ? 0.55f : 0.45f);
                var chestGO = new GameObject("RuinChest_Visible");
                chestGO.transform.SetParent(root.transform, false);
                chestGO.transform.localPosition = new Vector3(0, chestY, 0);
                chestGO.transform.localScale = new Vector3(1.0f, 0.7f, 0.8f);
                {
                    var cc = chestGO.AddComponent<BoxCollider>(); cc.size = new Vector3(1.3f, 1.0f, 1.05f);
                    var chestPB = chestGO.GetComponent<VoxelEngine.Building.PlacedBlock>();
                    if (chestPB == null) chestPB = chestGO.AddComponent<VoxelEngine.Building.PlacedBlock>();
                    chestPB.Hp = 120;
                    var chestDrop = chestGO.AddComponent<VoxelEngine.Exploration.RuinBlockDrop>();
                    chestDrop.salvage = salvageWood;
                    var body = GameObject.CreatePrimitive(PrimitiveType.Cube); body.name = "ChestBody";
                    body.transform.SetParent(chestGO.transform, false); body.transform.localScale = new Vector3(1f, 0.85f, 1f);
                    body.GetComponent<Renderer>().sharedMaterial = M["chest"];
                    var lid = GameObject.CreatePrimitive(PrimitiveType.Cube); lid.name = "ChestLid";
                    lid.transform.SetParent(chestGO.transform, false); lid.transform.localPosition = new Vector3(0, 0.5f, 0); lid.transform.localScale = new Vector3(1.04f, 0.22f, 1.04f);
                    lid.GetComponent<Renderer>().sharedMaterial = M["chest"]; { var lc = lid.GetComponent<Collider>(); if (lc != null) UnityEngine.Object.DestroyImmediate(lc); }
                    foreach (float sx in new float[] { -0.35f, 0.35f })
                    { var st = GameObject.CreatePrimitive(PrimitiveType.Cube); st.name = $"Strap_{sx}"; st.transform.SetParent(chestGO.transform, false); st.transform.localPosition = new Vector3(sx, 0.05f, 0); st.transform.localScale = new Vector3(0.12f, 1f, 1.04f); st.GetComponent<Renderer>().sharedMaterial = M["accent"]; { var c = st.GetComponent<Collider>(); if (c != null) UnityEngine.Object.DestroyImmediate(c); } }
                    var glow = new GameObject("ChestGlow"); glow.transform.SetParent(chestGO.transform, false); glow.transform.localPosition = new Vector3(0, 0.5f, 0);
                    var gl = glow.AddComponent<Light>(); gl.type = LightType.Point; gl.color = beaconColor; gl.intensity = 1.5f; gl.range = 6f; gl.shadows = LightShadows.None;
                }

                // ── Loot (preserved if hand-tuned) ──
                ItemDefinition[] finalComps = keepC ?? LootComps(theme).ToArray();
                ItemDefinition[] finalFuel = keepF ?? LootFuel(theme);
                BlueprintDataCoreItem[] finalBps = keepB ?? LootBps(theme);
                string ruinDisplay = !string.IsNullOrEmpty(keepName) ? keepName : name.Replace("Ruin_", "").Replace("_", " ");

                // (Root has no RuinChest — the lootable chest is the visible child inside the ruin.)
                var childChest = chestGO.GetComponent<VoxelEngine.Exploration.RuinChest>();
                if (childChest == null) childChest = chestGO.AddComponent<VoxelEngine.Exploration.RuinChest>();
                childChest.ruinName = ruinDisplay; childChest.minComponents = keepMin; childChest.maxComponents = keepMax;
                childChest.possibleComponents = finalComps; childChest.possibleFuel = finalFuel; childChest.possibleBlueprints = finalBps;
                if (theme == "Pirate" && pirateJackPumpHead != null)
                {
                    childChest.rareComponents = new[] { pirateJackPumpHead };
                    childChest.rareComponentChance = 0.18f;
                }
                else
                {
                    childChest.rareComponents = System.Array.Empty<ItemDefinition>();
                    childChest.rareComponentChance = 0f;
                }

                // Beacon
                var lightGO = new GameObject("RuinBeaconLight"); lightGO.transform.SetParent(root.transform, false);
                lightGO.transform.localPosition = new Vector3(0, deckTopY + buildHeight + 0.6f, 0);
                var beacon = lightGO.AddComponent<Light>(); beacon.type = LightType.Point; beacon.color = beaconColor; beacon.intensity = 1.8f; beacon.range = 22f; beacon.shadows = LightShadows.None;

                return PrefabUtility.SaveAsPrefabAsset(root, prefabPath);
            }


            // ── Generate all 20 themed ruins ──
            var defs = new (string name, string theme, string arch, int extent, int minC, int maxC)[]
            {
                // Moon (3) — pale lunar domes
                ("Ruin_Moon_HabitatDome",  "Moon", "Dome", 1, 2, 3),
                ("Ruin_Moon_Outpost",      "Moon", "Dome", 2, 3, 5),
                ("Ruin_Moon_ListeningPost","Moon", "Dome", 1, 2, 3),
                // Mars (4) — dust-blasted iron fortresses
                ("Ruin_Mars_DustBunker",       "Mars", "Fortress", 1, 2, 3),
                ("Ruin_Mars_Waystation",       "Mars", "Fortress", 1, 2, 4),
                ("Ruin_Mars_Habitat",          "Mars", "Fortress", 2, 3, 5),
                ("Ruin_Mars_FrontierOutpost",  "Mars", "Fortress", 2, 3, 5),
                // Venus (3) — sulfur pressure-domes
                ("Ruin_Venus_PressureDome",  "Venus", "Dome", 1, 2, 3),
                ("Ruin_Venus_SulfurRefinery","Venus", "Dome", 2, 3, 5),
                ("Ruin_Venus_AshCitadel",    "Venus", "Dome", 2, 3, 5),
                // Acid (3) — bio-corroded vaults + crystal spires
                ("Ruin_Acid_CorrodedVault", "Acid", "Fortress", 1, 2, 3),
                ("Ruin_Acid_CrystalSpire",  "Acid", "Fortress", 1, 2, 4),
                ("Ruin_Acid_DissolvedLab",  "Acid", "Fortress", 2, 3, 5),
                // Space Pirate (5) — scrap forts, camps, neon dens, loot caches, junk towers
                ("Ruin_Pirate_ScrapFort",  "Pirate", "Fortress", 2, 3, 6),
                ("Ruin_Pirate_WreckCamp",   "Pirate", "Fortress", 1, 2, 4),
                ("Ruin_Pirate_NeonDen",     "Pirate", "Fortress", 1, 2, 4),
                ("Ruin_Pirate_LootCache",   "Pirate", "Fortress", 1, 3, 5),
                ("Ruin_Pirate_JunkTower",   "Pirate", "Fortress", 1, 2, 4),
                // Greek rich celestial (2) — marble temples
                ("Ruin_Greek_TreasuryTemple","Greek", "Temple", 2, 3, 6),
                ("Ruin_Greek_OracleShrine", "Greek", "Temple", 1, 2, 4),
                // Ice planet (3) — glacial domes + frozen bunkers
                ("Ruin_Ice_GlacialDome",   "Ice", "Dome", 1, 2, 3),
                ("Ruin_Ice_FrozenBunker",  "Ice", "Fortress", 1, 2, 3),
                ("Ruin_Ice_CryoStation",   "Ice", "Dome", 2, 3, 5),
                // Water planet (2) — stilt platforms + sunken domes
                ("Ruin_Water_StiltPlatform","Water", "Fortress", 2, 3, 5),
                ("Ruin_Water_SunkenDome",  "Water", "Dome", 1, 2, 3),
                // Desolate / wasteland planet (1) — crumbled dry outpost
                ("Ruin_Desolate_DryOutpost","Desolate", "Fortress", 2, 2, 4),
                // Volcanic / Inferno planet (4) — obsidian citadels + magma forges + charred domes
                ("Ruin_Volcanic_ObsidianCitadel","Volcanic", "Fortress", 2, 3, 6),
                ("Ruin_Volcanic_MagmaForge", "Volcanic", "Fortress", 2, 3, 5),
                ("Ruin_Volcanic_CharredDome","Volcanic", "Dome", 1, 2, 3),
                ("Ruin_Volcanic_AshKeep",   "Volcanic", "Fortress", 1, 2, 4),
                // Crystal / Prism planet (3) — geode shrines + prism spires + lumina temples
                ("Ruin_Crystal_GeodeShrine","Crystal", "Dome", 1, 2, 3),
                ("Ruin_Crystal_PrismSpire", "Crystal", "Fortress", 1, 2, 4),
                ("Ruin_Crystal_LuminaTemple","Crystal", "Temple", 2, 3, 6),
            };

            int made = 0;
            foreach (var d in defs)
            {
                var prefab = MakeCelestialRuin(d.name, d.theme, d.arch, d.extent, d.minC, d.maxC);
                if (prefab == null) { Debug.LogWarning($"[CelestialRuins] Failed to build {d.name}"); continue; }
                made++;
                // Placeable block item (category "Celestial Ruins") so they can be previewed/placed.
                Color tintColor = d.theme switch
                {
                    "Moon" => new Color(0.62f, 0.64f, 0.68f),
                    "Mars" => new Color(0.62f, 0.34f, 0.20f),
                    "Venus" => new Color(0.72f, 0.60f, 0.22f),
                    "Acid" => new Color(0.46f, 0.60f, 0.28f),
                    "Pirate" => new Color(0.44f, 0.40f, 0.36f),
                    "Greek" => new Color(0.90f, 0.88f, 0.82f),
                    "Ice" => new Color(0.74f, 0.84f, 0.92f),
                    "Water" => new Color(0.34f, 0.52f, 0.58f),
                    "Desolate" => new Color(0.50f, 0.47f, 0.42f),
                    "Volcanic" => new Color(0.22f, 0.16f, 0.16f),
                    "Crystal" => new Color(0.66f, 0.58f, 0.92f),
                    _ => new Color(0.90f, 0.88f, 0.82f),
                };
                string blockPath = $"{CELEST_BLOCKS}/Block_{d.name}.asset";
                var blk = GetOrCreateAsset<VoxelEngine.Items.BlockItem>(blockPath);
                blk.itemId = ("block_" + d.name).ToLower();
                blk.displayName = d.name.Replace("Ruin_", "").Replace("_", " ");
                blk.description = $"{d.theme} ruin. Themed loot + blueprint cores. (Celestial)";
                blk.iconTint = tintColor;
                blk.maxStack = 50; blk.massPerUnit = 4f;
                blk.placedPrefab = prefab; blk.gridSize = Vector3Int.one;
                blk.allowStacking = true; blk.blockHealth = 320; blk.miningTier = 1;
                blk.category = "Celestial Ruins";
                EditorUtility.SetDirty(blk);
            }

            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();
            EditorUtility.DisplayDialog("Voxel Engine — Celestial Ruins",
                $"Built {made} / 33 themed celestial ruin prefabs in:\n{CELEST_PREFABS}\n\n" +
                "Themes: Moon (3), Mars (4), Venus (3), Acid (3), Pirate (5), Greek (2),\n" +
                "Ice (3), Water (2), Desolate (1), Volcanic (4), Crystal (3).\n" +
                "Each ruin has a distinct silhouette (Temple / Dome / Fortress), themed textures, and themed loot.\n\n" +
                "Placeable block items created under: " + CELEST_BLOCKS + "\n\n" +
                "Phase 2 (planet + biome spawning wiring) is a separate step.",
                "OK");
        }

        // ============================================================
        //   STEP 21 - CELESTIAL WORLDS (Phase 2: planets + themed biomes + ruin spawning)
        //   Wires every Phase-1 themed ruin to its own planet so it spawns in-world.
        //   Non-destructive: appends planets to Sol, preserves hand-tuned biome scatter.
        // ============================================================
        private void BuildCelestialWorldsContent()
        {
            const string PLANETS_DIR = ASSET_ROOT + "/Planets";
            const string BIOMES_DIR  = ASSET_ROOT + "/Biomes";
            const string RUINS_DIR   = ASSET_ROOT + "/Survival/CelestialRuins";
            EnsureFolder(PLANETS_DIR);
            EnsureFolder(BIOMES_DIR);

            GameObject LoadRuin(string ruinName)
                => AssetDatabase.LoadAssetAtPath<GameObject>($"{RUINS_DIR}/{ruinName}.prefab");

            // Create/update a themed biome: wide climate window + themed surface + ruin scatter.
            BiomeDefinition MakeThemedBiome(string assetName, string displayName, Color debug, MaterialId surface, float density, params string[] ruinNames)
            {
                string path = $"{BIOMES_DIR}/{assetName}.asset";
                var b = GetOrCreateAsset<BiomeDefinition>(path);
                b.biomeName = displayName;
                b.debugColor = debug;
                b.minTemperature = 0f; b.maxTemperature = 1f;   // wide window → always qualifies on its planet
                b.minHumidity = 0f;    b.maxHumidity = 1f;
                b.priority = 5;
                b.heightAmplitude = 10f; b.heightFrequency = 0.02f; b.ridgedness = 0.1f;
                b.surfaceMaterial = surface; b.surfaceDepth = 1;
                b.subsurfaceMaterial = surface; b.subsurfaceDepth = 5;
                b.allowBeach = false; b.isOceanic = false;
                // Scatter: non-destructive append of this world's themed ruins
                var list = (b.scatter != null) ? new List<BiomeDefinition.ScatterEntry>(b.scatter) : new List<BiomeDefinition.ScatterEntry>();
                foreach (var rn in ruinNames)
                {
                    var ruin = LoadRuin(rn);
                    if (ruin == null) { Debug.LogWarning($"[CelestialWorlds] Ruin prefab not found: {rn} (run Step 20 first)"); continue; }
                    bool has = false;
                    foreach (var e in list) if (e.prefab == ruin) { has = true; break; }
                    if (!has) list.Add(new BiomeDefinition.ScatterEntry { prefab = ruin, density = density, minScale = 1.1f, maxScale = 1.6f, minHeight = 0, maxHeight = 9999 });
                }
                b.scatter = list.ToArray();
                EditorUtility.SetDirty(b);
                return b;
            }

            // Create/update a planet. Non-destructive on ore lists; sets the fields that define the world.
            PlanetTemplate MakePlanet(string assetName, string bodyName, float temp, float oxygen, float gravity, float radiusKm, bool grass, Color displayColor, params BiomeDefinition[] biomes)
            {
                string path = $"{PLANETS_DIR}/Planet_{assetName}.asset";
                var p = GetOrCreateAsset<PlanetTemplate>(path);
                if (p.body == null) p.body = BodySettings.CreateEarthlike();
                p.body.bodyName = bodyName;
                p.body.temperature = temp;
                p.body.oxygenLevel = oxygen;
                p.body.gravity = gravity;
                p.body.radiusKm = radiusKm;
                p.body.waterLevel = 96;
                p.body.enableGrass = grass;
                p.body.mountainScale = 1f;
                p.body.displayColor = displayColor;
                p.body.allowedBiomes = biomes;
                EditorUtility.SetDirty(p);
                return p;
            }

            // ── 11 themed biomes (surface material + ruin scatter) ──
            var bMoon     = MakeThemedBiome("Biome_LunarHighlands", "Lunar Highlands",       new Color(0.60f,0.60f,0.65f), MaterialId.Stone,          0.00008f, "Ruin_Moon_HabitatDome","Ruin_Moon_Outpost","Ruin_Moon_ListeningPost");
            var bMars     = MakeThemedBiome("Biome_MartianDust",    "Martian Dust Plains",    new Color(0.70f,0.40f,0.20f), MaterialId.MartianDust,    0.00008f, "Ruin_Mars_DustBunker","Ruin_Mars_Waystation","Ruin_Mars_Habitat","Ruin_Mars_FrontierOutpost");
            var bVenus    = MakeThemedBiome("Biome_VenusianAsh",    "Venusian Ash Lowlands",  new Color(0.80f,0.70f,0.30f), MaterialId.VenusAsh,       0.00008f, "Ruin_Venus_PressureDome","Ruin_Venus_SulfurRefinery","Ruin_Venus_AshCitadel");
            var bAcid     = MakeThemedBiome("Biome_AcidBog",        "Acid Bog",               new Color(0.40f,0.60f,0.25f), MaterialId.AcidBog,        0.00008f, "Ruin_Acid_CorrodedVault","Ruin_Acid_CrystalSpire","Ruin_Acid_DissolvedLab");
            var bPirate   = MakeThemedBiome("Biome_PirateScrap",    "Pirate Scrap Badlands",  new Color(0.50f,0.45f,0.40f), MaterialId.Clay,           0.00008f, "Ruin_Pirate_ScrapFort","Ruin_Pirate_WreckCamp","Ruin_Pirate_NeonDen","Ruin_Pirate_LootCache","Ruin_Pirate_JunkTower");
            var bGreek    = MakeThemedBiome("Biome_GreekMarble",    "Olympian Marble Hills",     new Color(0.90f,0.88f,0.80f), MaterialId.Sand,           0.00008f, "Ruin_Greek_TreasuryTemple","Ruin_Greek_OracleShrine");
            var bIce      = MakeThemedBiome("Biome_FrozenGlacier",  "Frozen Glacier",         new Color(0.80f,0.90f,1.00f), MaterialId.Ice,            0.00008f, "Ruin_Ice_GlacialDome","Ruin_Ice_FrozenBunker","Ruin_Ice_CryoStation");
            var bWater    = MakeThemedBiome("Biome_OceanShelf",     "Ocean Shelf",            new Color(0.30f,0.50f,0.70f), MaterialId.Sand,           0.00008f, "Ruin_Water_StiltPlatform","Ruin_Water_SunkenDome");
            var bDesolate = MakeThemedBiome("Biome_DesolateWastes", "Desolate Wastes",        new Color(0.60f,0.55f,0.45f), MaterialId.Clay,           0.00008f, "Ruin_Desolate_DryOutpost");
            var bVolcanic = MakeThemedBiome("Biome_VolcanicBasalt", "Volcanic Basalt Plains", new Color(0.20f,0.10f,0.10f), MaterialId.VolcanicBasalt, 0.00008f, "Ruin_Volcanic_ObsidianCitadel","Ruin_Volcanic_MagmaForge","Ruin_Volcanic_CharredDome","Ruin_Volcanic_AshKeep");
            var bCrystal  = MakeThemedBiome("Biome_CrystalGeode",   "Crystal Geode Flats",    new Color(0.60f,0.50f,0.90f), MaterialId.CrystalGeode,   0.00008f, "Ruin_Crystal_GeodeShrine","Ruin_Crystal_PrismSpire","Ruin_Crystal_LuminaTemple");

            // ── Planets (Mars/Venus reconfigured + 8 new worlds) ──
            var pMars     = MakePlanet("Mars",     "Mars",          5f,  0.02f, 0.38f, 6f, false, new Color(0.80f,0.40f,0.18f,1f), bMars);
            var pVenus    = MakePlanet("Venus",    "Venus",         60f, 0.00f, 0.90f, 6f, false, new Color(0.85f,0.70f,0.25f,1f), bVenus);
            var pAcid     = MakePlanet("Acid",     "Acid World",    30f, 0.15f, 0.90f, 6f, false, new Color(0.45f,0.65f,0.30f,1f), bAcid);
            var pPirate   = MakePlanet("Pirate",   "Pirate World",  18f, 0.70f, 0.90f, 7f, false, new Color(0.50f,0.42f,0.32f,1f), bPirate);
            var pGreek    = MakePlanet("Olympus",    "Olympus",   20f, 1.00f, 1.00f, 7f, true,  new Color(0.92f,0.90f,0.78f,1f), bGreek);
            var pIce      = MakePlanet("Ice",      "Ice World",    -30f, 0.10f, 0.50f, 6f, false, new Color(0.80f,0.90f,1.00f,1f), bIce);
            var pWater    = MakePlanet("Water",    "Ocean World",   15f, 1.00f, 1.00f, 7f, false, new Color(0.20f,0.45f,0.75f,1f), bWater);
            var pDesolate = MakePlanet("Desolate", "Desolate World",25f, 0.05f, 0.80f, 6f, false, new Color(0.65f,0.58f,0.45f,1f), bDesolate);
            var pVolcanic = MakePlanet("Volcanic", "Volcanic World",70f, 0.05f, 0.90f, 6f, false, new Color(0.25f,0.10f,0.08f,1f), bVolcanic);
            var pCrystal  = MakePlanet("Crystal",  "Crystal World", 10f, 0.25f, 0.70f, 6f, false, new Color(0.60f,0.50f,0.92f,1f), bCrystal);

            // ── Moon: wire the lunar biome ──
            var moon = AssetDatabase.LoadAssetAtPath<MoonTemplate>($"{PLANETS_DIR}/Moon_Earth.asset");
            if (moon != null)
            {
                moon.body.allowedBiomes = new BiomeDefinition[] { bMoon };
                moon.body.displayColor = new Color(0.70f, 0.70f, 0.72f, 1f);
                EditorUtility.SetDirty(moon);
            }

            // ── Append all themed planets to System_Sol (non-destructive: only add missing) ──
            string sysPath = $"{PLANETS_DIR}/System_Sol.asset";
            // Step 21 owns the complete celestial-system authoring path. A missing System_Sol
            // is created here rather than requiring a separate manual asset step.
            var sys = GetOrCreateAsset<SolarSystemTemplate>(sysPath);
            if (sys != null)
            {
                if (string.IsNullOrWhiteSpace(sys.systemName)) sys.systemName = "Sol System";
                if (sys.sun == null) sys.sun = new SunSettings { displayName = "Sol", sunCount = 1, intensity = 1.3f };
                if (sys.minPlanetSeparationKm <= 0f) sys.minPlanetSeparationKm = 500f;
                if (sys.maxPlanetSeparationKm <= sys.minPlanetSeparationKm) sys.maxPlanetSeparationKm = 10000f;

                var list = (sys.planets != null) ? new List<PlanetTemplate>(sys.planets) : new List<PlanetTemplate>();
                // Preserve existing orbital/seed indices. A legacy null slot is intentionally
                // retained rather than removed (seed tables are index-aligned); CosmicRegistry
                // skips it safely. Only a legacy live Greek template is repaired in place.
                for (int i = 0; i < list.Count; i++)
                {
                    if (list[i] != null && list[i].body != null && list[i].body.bodyName == "Greek")
                        list[i] = pGreek;
                }
                var earth = AssetDatabase.LoadAssetAtPath<PlanetTemplate>($"{PLANETS_DIR}/Planet_Earth.asset");
                if (earth != null && !list.Contains(earth)) list.Insert(0, earth);
                foreach (var p in new[] { pMars, pVenus, pAcid, pPirate, pGreek, pIce, pWater, pDesolate, pVolcanic, pCrystal })
                    if (p != null && !list.Contains(p)) list.Add(p);
                sys.planets = list.ToArray();
                AssetDatabase.DeleteAsset($"{PLANETS_DIR}/Planet_Greek.asset"); // remove legacy asset (renamed to Olympus)
                EditorUtility.SetDirty(sys);
                EnsureSolarSystemRuntimeLinks(sys);
            }

            // Keep the oil-rich seep distribution and Planet_Pirate-only infinite-node
            // configuration setup-owned when this celestial-worlds step is re-run.
            ConfigureCrudeOilWorlds();

            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();
            EditorUtility.DisplayDialog("Voxel Engine — Celestial Worlds (Phase 2)",
                "Themed worlds wired:\n\n" +
                "• 11 themed biomes (Lunar, Martian, Venusian, Acid, Pirate, Greek, Frozen, Ocean, Desolate, Volcanic, Crystal)\n" +
                "• 10 planets configured (Mars/Venus reconfigured + 8 new) with themed terrain + ruin scatter\n" +
                "• Moon wired to the Lunar biome\n" +
                "• All appended to System_Sol\n" +
                "• Runtime CosmosTemplateLibrary + Asteroids_MainBelt repaired automatically\n\n" +
                "New surface materials: Martian Dust, Venus Ash, Acid Bog, Volcanic Basalt, Crystal Geode.\n" +
                "Ruins now spawn on their own world via biome scatter (~0.0006 density).\n\n" +
                "IMPORTANT: re-run Step 1 (Create All Assets) once to register the 5 new materials in the MaterialRegistry, then create/visit a new world to see them.",
                "OK");
        }

        /// <summary>
        /// Step 21 owns the build-safe bridge from the authored System_Sol asset to runtime.
        /// It creates only missing assets/links, preserves any existing belt tuning, removes
        /// null references that cannot render, and never asks designers to hand-author a
        /// Resources registry or asteroid asset.
        /// </summary>
        private void EnsureSolarSystemRuntimeLinks(SolarSystemTemplate system)
        {
            if (system == null) return;

            const string resourcesFolder = "Assets/Resources";
            const string libraryPath = resourcesFolder + "/CosmosTemplateLibrary.asset";
            const string beltPath = ASSET_ROOT + "/Planets/Asteroids_MainBelt.asset";
            EnsureFolder(resourcesFolder);

            int repaired = 0;
            var library = AssetDatabase.LoadAssetAtPath<CosmosTemplateLibrary>(libraryPath);
            if (library == null)
            {
                if (AssetDatabase.LoadMainAssetAtPath(libraryPath) == null)
                {
                    library = ScriptableObject.CreateInstance<CosmosTemplateLibrary>();
                    AssetDatabase.CreateAsset(library, libraryPath);
                    repaired++;
                }
                else
                {
                    Debug.LogError("[CelestialWorlds] Preserved conflicting Resources/CosmosTemplateLibrary.asset; it is not a CosmosTemplateLibrary.");
                }
            }
            if (library != null)
            {
                library.systems ??= new List<SolarSystemTemplate>();
                if (!library.systems.Contains(system))
                {
                    library.systems.Add(system);
                    repaired++;
                }
                EditorUtility.SetDirty(library);
            }

            var belt = AssetDatabase.LoadAssetAtPath<AsteroidFieldTemplate>(beltPath);
            bool createdBelt = false;
            if (belt == null)
            {
                if (AssetDatabase.LoadMainAssetAtPath(beltPath) == null)
                {
                    belt = ScriptableObject.CreateInstance<AsteroidFieldTemplate>();
                    AssetDatabase.CreateAsset(belt, beltPath);
                    createdBelt = true;
                    repaired++;
                }
                else
                {
                    Debug.LogError("[CelestialWorlds] Preserved conflicting Asteroids_MainBelt asset; it is not an AsteroidFieldTemplate.");
                }
            }
            if (belt != null)
            {
                if (belt.settings == null)
                {
                    belt.settings = new AsteroidFieldSettings();
                    createdBelt = true;
                    repaired++;
                }
                // Only a newly-created/missing settings block receives defaults; existing
                // density/resources/sizes remain designer-owned on repeated setup runs.
                if (createdBelt)
                {
                    belt.settings.density = 1f;
                    belt.settings.resourceCount = 3;
                    belt.settings.possibleResources = new[]
                    {
                        MaterialId.Iron, MaterialId.Nickel, MaterialId.Silicon,
                        MaterialId.Platinum, MaterialId.Ice
                    };
                    belt.settings.sizeRangeKm = new Vector2(0.03f, 0.35f);
                    belt.settings.shellRadiusKm = new Vector2(8000f, 12000f);
                }
                if (belt.solarSystem == null)
                {
                    belt.solarSystem = system;
                    repaired++;
                }
                EditorUtility.SetDirty(belt);

                var fields = system.asteroidFields != null
                    ? new List<AsteroidFieldTemplate>(system.asteroidFields)
                    : new List<AsteroidFieldTemplate>();
                int beforeFields = fields.Count;
                fields.RemoveAll(field => field == null);
                if (!fields.Contains(belt)) fields.Add(belt);
                if (fields.Count != beforeFields || system.asteroidFields == null)
                {
                    system.asteroidFields = fields.ToArray();
                    repaired++;
                }
            }

            var planets = system.planets != null
                ? new List<PlanetTemplate>(system.planets)
                : new List<PlanetTemplate>();
            // Do not remove a malformed slot here: system seed tables are index-aligned. Step
            // 21 repairs the known legacy slot in place above, while unrelated custom systems
            // retain their order and are skipped safely by CosmicRegistry until repaired.
            foreach (var planet in planets)
            {
                if (planet == null || planet.body == null || planet.solarSystem != null) continue;
                planet.solarSystem = system;
                EditorUtility.SetDirty(planet);
                repaired++;
            }

            // Repair null bootstrap links in the currently open scene without overwriting an
            // intentionally custom assigned system. Runtime still resolves the Resources library
            // for every scene/build, so no manual scene assignment is required.
            foreach (var bootstrap in Object.FindObjectsByType<CosmosBootstrap>(FindObjectsInactive.Include))
            {
                if (bootstrap == null || bootstrap.solarSystemTemplate != null) continue;
                bootstrap.solarSystemTemplate = system;
                EditorUtility.SetDirty(bootstrap);
                repaired++;
            }

            EditorUtility.SetDirty(system);
            CosmosTemplateLibrary.InvalidateCache();
            Debug.Log("[CelestialWorlds] Runtime System_Sol bridge repaired: " + repaired +
                      " link(s); persistent asteroid belt " + (belt != null ? "ready" : "unavailable") + ".");
        }

        // ============================================================
        //   STEP 22 - COMBAT (Phase 1): damage framework, Iron Sword,
        //   Iron Pistol, and a placeable Training Dummy target.
        // ============================================================
        private void BuildCombatContent()
        {
            const string COMBAT_ROOT  = ASSET_ROOT + "/Combat";
            const string COMBAT_ITEMS  = COMBAT_ROOT + "/Items";
            const string COMBAT_BLOCKS = COMBAT_ROOT + "/Blocks";
            const string COMBAT_PREFABS= COMBAT_ROOT + "/Prefabs";
            EnsureFolder(COMBAT_ROOT);
            EnsureFolder(COMBAT_ITEMS);
            EnsureFolder(COMBAT_BLOCKS);
            EnsureFolder(COMBAT_PREFABS);

            ItemDefinition FindItem(string assetNameNoExt)
            {
                var guids = AssetDatabase.FindAssets(assetNameNoExt + " t:ItemDefinition");
                foreach (var g in guids)
                {
                    var pp = AssetDatabase.GUIDToAssetPath(g);
                    if (System.IO.Path.GetFileNameWithoutExtension(pp) == assetNameNoExt)
                        return AssetDatabase.LoadAssetAtPath<ItemDefinition>(pp);
                }
                return null;
            }
            var ironIngot  = FindItem("Item_IronIngot");
            var steelIngot = FindItem("Item_SteelIngot");
            var ironPlate  = FindItem("Item_IronPlate");
            var copperWire = FindItem("Item_CopperLVWire");
            var stone      = FindItem("Item_Stone");

            // ── Iron Sword (melee) ──
            var sword = GetOrCreateAsset<VoxelEngine.Combat.WeaponItem>($"{COMBAT_ITEMS}/Weapon_IronSword.asset");
            sword.itemId = "iron_sword";
            sword.displayName = "Iron Sword";
            sword.description = "Crusader melee sidearm. Hold LMB to swing. Damages dummies and (future) enemies.";
            sword.toolType = VoxelEngine.Items.ToolType.Sword;
            sword.attackMode = VoxelEngine.Combat.WeaponItem.AttackMode.Melee;
            sword.damage = 40f;
            sword.range = 3f;
            sword.attackCooldown = 0.45f;
            sword.damageType = VoxelEngine.Combat.DamageType.Melee;
            sword.miningTier = 2;
            sword.maxDurability = 500;
            sword.strength = 40f;
            sword.iconTint = new Color(0.82f, 0.84f, 0.9f);
            sword.maxStack = 1;
            sword.category = "Weapons";
            EditorUtility.SetDirty(sword);

            // ── Iron Pistol (ranged, no ammo yet — Phase 1) ──
            var pistol = GetOrCreateAsset<VoxelEngine.Combat.WeaponItem>($"{COMBAT_ITEMS}/Weapon_IronPistol.asset");
            pistol.itemId = "iron_pistol";
            pistol.displayName = "Iron Pistol";
            pistol.description = "Ranged sidearm. Hold LMB to fire (ammo system comes in a later combat phase).";
            pistol.toolType = VoxelEngine.Items.ToolType.Other;
            pistol.attackMode = VoxelEngine.Combat.WeaponItem.AttackMode.Ranged;
            pistol.damage = 28f;
            pistol.range = 70f;
            pistol.attackCooldown = 0.28f;
            pistol.damageType = VoxelEngine.Combat.DamageType.Kinetic;
            pistol.miningTier = 2;
            pistol.maxDurability = 600;
            pistol.iconTint = new Color(0.55f, 0.55f, 0.6f);
            pistol.maxStack = 1;
            pistol.category = "Weapons";
            EditorUtility.SetDirty(pistol);

            // ── Training Dummy (placeable combat target) ──
            string dummyPath = $"{COMBAT_PREFABS}/TrainingDummy.prefab";
            var dummyMat = MakeColoredMat(COMBAT_PREFABS, "Mat_TrainingDummy", new Color(0.55f, 0.40f, 0.25f));
            var dRoot = new GameObject("TrainingDummy");
            var dCube = GameObject.CreatePrimitive(PrimitiveType.Cube);
            dCube.name = "Mesh";
            dCube.transform.SetParent(dRoot.transform, false);
            dCube.transform.localScale = new Vector3(0.7f, 1.8f, 0.5f);
            dCube.transform.localPosition = new Vector3(0f, 0.9f, 0f);
            dCube.GetComponent<Renderer>().sharedMaterial = dummyMat;
            var dPb = dCube.AddComponent<VoxelEngine.Building.PlacedBlock>();
            dPb.Hp = 60;
            dRoot.AddComponent<VoxelEngine.Combat.TrainingDummy>();
            var dummyPrefab = PrefabUtility.SaveAsPrefabAsset(dRoot, dummyPath);
            UnityEngine.Object.DestroyImmediate(dRoot);

            var dummyBlock = GetOrCreateAsset<VoxelEngine.Items.BlockItem>($"{COMBAT_BLOCKS}/Block_TrainingDummy.asset");
            dummyBlock.itemId = "block_training_dummy";
            dummyBlock.displayName = "Training Dummy";
            dummyBlock.description = "Placeable combat target. Swing/shoot it to test weapons — it squashes and respawns.";
            dummyBlock.iconTint = new Color(0.7f, 0.5f, 0.3f);
            dummyBlock.maxStack = 20;
            dummyBlock.massPerUnit = 2f;
            dummyBlock.placedPrefab = dummyPrefab;
            dummyBlock.gridSize = Vector3Int.one;
            dummyBlock.allowStacking = true;
            dummyBlock.blockHealth = 60;
            dummyBlock.miningTier = 1;
            dummyBlock.category = "Combat";
            EditorUtility.SetDirty(dummyBlock);

            // ── Recipes ──
            AddRecipe("Recipe_IronSword", "Iron Sword", sword, 1, VoxelEngine.Crafting.StationTier.Assembler, true,
                (ironPlate, 3), (ironIngot, 2));
            AddRecipe("Recipe_IronPistol", "Iron Pistol", pistol, 1, VoxelEngine.Crafting.StationTier.Assembler, true,
                (ironPlate, 2), (copperWire, 3), (steelIngot, 1));
            AddRecipe("Recipe_TrainingDummy", "Training Dummy", dummyBlock, 1, VoxelEngine.Crafting.StationTier.CraftingBench, true,
                (stone, 4), (ironIngot, 1));

            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();
            EditorUtility.DisplayDialog("Voxel Engine — Combat (Phase 1)",
                "Combat foundation built:\n\n" +
                "• Damage framework: IDamageable + DamageType + Damageable (reusable by enemies, dummies, grid blocks)\n" +
                "• Iron Sword (melee) + Iron Pistol (ranged) — hold LMB to attack\n" +
                "• Training Dummy — placeable target that takes damage and respawns\n" +
                "• Recipes at the Assembler / Crafting Bench\n\n" +
                "Try it: craft a sword, place a Training Dummy, and swing at it (LMB).",
                "OK");
        }

        // ============================================================
        //   STEP 23 - ENEMIES (Combat Phase 2): the Ghoul — first real
        //   hostile creature. Wander/detect/chase/melee, radial-aligned,
        //   Damageable + loot, spawned rarely in home-world biomes.
        // ============================================================
        // ============================================================
        //   STEP 23 - ENEMIES (Combat Phase 2): remade Ghoul + proper
        //   EnemySpawner. Detailed hunched creature; spawns top-level
        //   near the player (not chunk-parented) so radial physics works.
        // ============================================================
        private void BuildEnemyContent()
        {
            EnsureFolder("Assets/Resources");
            EnsureFolder("Assets/Resources/Enemies");
            const string ENEMY_MATS = ASSET_ROOT + "/Enemies";
            EnsureFolder(ENEMY_MATS);

            ItemDefinition FindItem(string assetNameNoExt)
            {
                var guids = AssetDatabase.FindAssets(assetNameNoExt + " t:ItemDefinition");
                foreach (var g in guids)
                {
                    var pp = AssetDatabase.GUIDToAssetPath(g);
                    if (System.IO.Path.GetFileNameWithoutExtension(pp) == assetNameNoExt)
                        return AssetDatabase.LoadAssetAtPath<ItemDefinition>(pp);
                }
                return null;
            }
            var ironIngot = FindItem("Item_IronIngot");
            var stone     = FindItem("Item_Stone");

            var skin     = MakeColoredMat(ENEMY_MATS, "Mat_GhoulSkin",  new Color(0.42f, 0.47f, 0.37f)); // stony grey-green
            var skinDark = MakeColoredMat(ENEMY_MATS, "Mat_GhoulDark",  new Color(0.26f, 0.30f, 0.22f)); // decay
            var bone     = MakeColoredMat(ENEMY_MATS, "Mat_GhoulBone",  new Color(0.82f, 0.80f, 0.68f)); // teeth/claws
            var eye      = MakeColoredMat(ENEMY_MATS, "Mat_GhoulEye",   new Color(0.98f, 0.16f, 0.12f)); // glowing red

            var root = new GameObject("Ghoul");
            GameObject AddPart(string n, Vector3 pos, Vector3 euler, Vector3 scale, Material m)
            {
                var go = GameObject.CreatePrimitive(PrimitiveType.Cube);
                go.name = n; go.transform.SetParent(root.transform, false);
                go.transform.localPosition = pos; go.transform.localEulerAngles = euler; go.transform.localScale = scale;
                go.GetComponent<Renderer>().sharedMaterial = m;
                var col = go.GetComponent<Collider>(); if (col != null) UnityEngine.Object.DestroyImmediate(col);
                return go;
            }

            // ── Hunched, gaunt, lanky ghoul (research-inspired silhouette) ──
            // Splayed clawed legs
            AddPart("ThighL", new Vector3(-0.12f, 0.32f, 0f),    new Vector3(0,0,-7),  new Vector3(0.15f, 0.34f, 0.15f), skin);
            AddPart("ShinL",  new Vector3(-0.15f, 0.04f, 0.02f),  new Vector3(0,0,-4),  new Vector3(0.13f, 0.30f, 0.13f), skin);
            AddPart("FootL",  new Vector3(-0.17f,-0.04f, 0.10f),  new Vector3(-22,0,0), new Vector3(0.13f, 0.07f, 0.26f), skinDark);
            AddPart("ThighR", new Vector3( 0.12f, 0.32f, 0f),     new Vector3(0,0, 7),  new Vector3(0.15f, 0.34f, 0.15f), skin);
            AddPart("ShinR",  new Vector3( 0.15f, 0.04f, 0.02f),  new Vector3(0,0, 4),  new Vector3(0.13f, 0.30f, 0.13f), skin);
            AddPart("FootR",  new Vector3( 0.17f,-0.04f, 0.10f),  new Vector3(-22,0,0), new Vector3(0.13f, 0.07f, 0.26f), skinDark);
            // Hips + hunched gaunt torso
            AddPart("Hips",   new Vector3(0, 0.52f, 0f),          Vector3.zero,        new Vector3(0.34f, 0.22f, 0.26f), skinDark);
            AddPart("Torso",  new Vector3(0, 0.95f, 0.06f),       new Vector3(20,0,0),  new Vector3(0.40f, 0.56f, 0.24f), skin);
            AddPart("Rib1",   new Vector3(0, 1.02f, 0.18f),       new Vector3(20,0,0),  new Vector3(0.30f, 0.04f, 0.04f), skinDark);
            AddPart("Rib2",   new Vector3(0, 0.90f, 0.18f),       new Vector3(20,0,0),  new Vector3(0.30f, 0.04f, 0.04f), skinDark);
            AddPart("Rib3",   new Vector3(0, 0.78f, 0.17f),       new Vector3(20,0,0),  new Vector3(0.28f, 0.04f, 0.04f), skinDark);
            AddPart("Hump",   new Vector3(0, 1.18f,-0.08f),       new Vector3(20,0,0),  new Vector3(0.30f, 0.22f, 0.18f), skinDark);
            // Shoulders + long clawed arms hanging low
            AddPart("ShldrL", new Vector3(-0.24f, 1.18f, 0.04f),  new Vector3(20,0,-12),new Vector3(0.18f, 0.16f, 0.18f), skinDark);
            AddPart("ShldrR", new Vector3( 0.24f, 1.18f, 0.04f),  new Vector3(20,0, 12),new Vector3(0.18f, 0.16f, 0.18f), skinDark);
            AddPart("UpArmL", new Vector3(-0.30f, 0.92f, 0.08f),  new Vector3(12,0,-6), new Vector3(0.12f, 0.36f, 0.12f), skin);
            AddPart("ForArmL",new Vector3(-0.36f, 0.58f, 0.12f),  new Vector3(8,0,-4),  new Vector3(0.11f, 0.38f, 0.11f), skin);
            AddPart("HandL",  new Vector3(-0.40f, 0.34f, 0.16f),  Vector3.zero,        new Vector3(0.12f, 0.12f, 0.13f), skinDark);
            AddPart("ClawL1", new Vector3(-0.40f, 0.24f, 0.26f),  new Vector3(40,0,0),  new Vector3(0.04f, 0.04f, 0.14f), bone);
            AddPart("ClawL2", new Vector3(-0.46f, 0.24f, 0.24f),  new Vector3(40,0,-20),new Vector3(0.04f, 0.04f, 0.14f), bone);
            AddPart("UpArmR", new Vector3( 0.30f, 0.92f, 0.08f),  new Vector3(12,0, 6), new Vector3(0.12f, 0.36f, 0.12f), skin);
            AddPart("ForArmR",new Vector3( 0.36f, 0.58f, 0.12f),  new Vector3(8,0, 4),  new Vector3(0.11f, 0.38f, 0.11f), skin);
            AddPart("HandR",  new Vector3( 0.40f, 0.34f, 0.16f),  Vector3.zero,        new Vector3(0.12f, 0.12f, 0.13f), skinDark);
            AddPart("ClawR1", new Vector3( 0.40f, 0.24f, 0.26f),  new Vector3(40,0,0),  new Vector3(0.04f, 0.04f, 0.14f), bone);
            AddPart("ClawR2", new Vector3( 0.46f, 0.24f, 0.24f),  new Vector3(40,0, 20),new Vector3(0.04f, 0.04f, 0.14f), bone);
            // Neck + elongated muzzle skull + jaw + teeth + glowing eyes
            AddPart("Neck",   new Vector3(0, 1.32f, 0.12f),       new Vector3(24,0,0),  new Vector3(0.15f, 0.16f, 0.15f), skin);
            AddPart("Head",   new Vector3(0, 1.44f, 0.20f),       new Vector3(18,0,0),  new Vector3(0.30f, 0.30f, 0.40f), skin);
            AddPart("Brow",   new Vector3(0, 1.54f, 0.22f),       new Vector3(18,0,0),  new Vector3(0.30f, 0.08f, 0.20f), skinDark);
            AddPart("Jaw",    new Vector3(0, 1.34f, 0.34f),       new Vector3(18,0,0),  new Vector3(0.24f, 0.10f, 0.22f), skinDark);
            AddPart("Teeth1", new Vector3(-0.06f,1.40f, 0.42f),   new Vector3(18,0,0),  new Vector3(0.04f, 0.06f, 0.04f), bone);
            AddPart("Teeth2", new Vector3( 0.00f,1.40f, 0.43f),   new Vector3(18,0,0),  new Vector3(0.04f, 0.07f, 0.04f), bone);
            AddPart("Teeth3", new Vector3( 0.06f,1.40f, 0.42f),   new Vector3(18,0,0),  new Vector3(0.04f, 0.06f, 0.04f), bone);
            AddPart("EyeL",   new Vector3(-0.10f,1.50f, 0.36f),   new Vector3(18,0,0),  new Vector3(0.07f, 0.05f, 0.04f), eye);
            AddPart("EyeR",   new Vector3( 0.10f,1.50f, 0.36f),   new Vector3(18,0,0),  new Vector3(0.07f, 0.05f, 0.04f), eye);
            // Decay patches
            AddPart("PatchL", new Vector3(-0.18f,1.00f, 0.04f),   new Vector3(20,0,0),  new Vector3(0.10f, 0.14f, 0.05f), skinDark);
            AddPart("PatchR", new Vector3( 0.18f,0.92f, 0.04f),   new Vector3(20,0,0),  new Vector3(0.08f, 0.12f, 0.05f), skinDark);

            var cap = root.AddComponent<CapsuleCollider>();
            cap.height = 1.7f; cap.radius = 0.38f; cap.center = new Vector3(0f, 0.85f, 0.04f);
            var rb = root.AddComponent<Rigidbody>();
            rb.useGravity = false; rb.freezeRotation = true;
            var ghoul = root.AddComponent<VoxelEngine.Combat.EnemyGhoul>();
            ghoul.maxHealth = 35f;
            var drops = new System.Collections.Generic.List<VoxelEngine.Items.ItemDefinition>();
            if (ironIngot != null) drops.Add(ironIngot);
            if (stone != null) drops.Add(stone);
            ghoul.drops = drops.ToArray();
            ghoul.minDrops = 1; ghoul.maxDrops = 2;

            // Premium themed health bar (Ghoul theme: sickly green full → dark red low)
            var hbar = root.AddComponent<VoxelEngine.Combat.CreatureHealthBar>();
            hbar.target = ghoul;
            hbar.fillColor = new Color(0.45f, 0.70f, 0.20f);
            hbar.fillColorLow = new Color(0.70f, 0.10f, 0.05f);
            hbar.borderColor = new Color(0.30f, 0.25f, 0.18f, 0.90f);

            // NON-DESTRUCTIVE: never delete or overwrite an existing Ghoul prefab.
            // If the user has built or customized their own (Resources/Enemies/Ghoul), we
            // preserve it exactly and reuse it for the biome scatter. This also stops the
            // recurring "API has changed" prompt that deleting/regenerating the prefab caused.
            const string ghoulPath = "Assets/Resources/Enemies/Ghoul.prefab";
            GameObject prefab;
            if (AssetDatabase.LoadMainAssetAtPath(ghoulPath) != null)
            {
                prefab = AssetDatabase.LoadAssetAtPath<GameObject>(ghoulPath);
                UnityEngine.Object.DestroyImmediate(root); // discard freshly-built scene root
                Debug.Log("[Step 23] Ghoul.prefab already exists — preserving it (not overwritten).");
            }
            else
            {
                prefab = PrefabUtility.SaveAsPrefabAsset(root, ghoulPath);
                UnityEngine.Object.DestroyImmediate(root);
            }

            // Inject Ghoul into home-world biomes for ambient spawning. The ghoul DETACHES from
            // the chunk scatter parent on Awake (EnemyGhoul) so Rigidbody physics works on spheres.
            var br = AssetDatabase.LoadAssetAtPath<VoxelEngine.Biomes.BiomeRegistry>(ASSET_ROOT + "/BiomeRegistry.asset");
            if (br != null)
            {
                foreach (var biome in br.biomes)
                {
                    if (biome == null) continue;
                    if (biome.biomeName != "Wasteland" && biome.biomeName != "Forest" && biome.biomeName != "Desert") continue;
                    var list = (biome.scatter != null)
                        ? new System.Collections.Generic.List<VoxelEngine.Biomes.BiomeDefinition.ScatterEntry>(biome.scatter)
                        : new System.Collections.Generic.List<VoxelEngine.Biomes.BiomeDefinition.ScatterEntry>();
                    list.RemoveAll(e => e.prefab != null && e.prefab.name == "Ghoul");
                    list.Add(new VoxelEngine.Biomes.BiomeDefinition.ScatterEntry { prefab = prefab, density = 0.005f, minScale = 0.9f, maxScale = 1.2f, minHeight = 0, maxHeight = 9999 });
                    biome.scatter = list.ToArray();
                    EditorUtility.SetDirty(biome);
                }
                EditorUtility.SetDirty(br);
            }

            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();
            EditorUtility.DisplayDialog("Voxel Engine — Enemies (Combat Phase 2)",
                "Remade Ghoul + proper spawning:\n\n" +
                "• Detailed hunched ghoul: gaunt ribbed torso, muzzle + jaw + teeth, long clawed arms, splayed clawed feet, glowing red eyes\n" +
                "• Spawns automatically via EnemySpawner near the player (top-level, radial-aligned), capped at 5 alive\n" +
                "• Saved to Resources/Enemies so it loads at runtime\n\n" +
                "Ghouls now appear as you explore. Fight or flee!",
                "OK");
        }

        // ============================================================
        //   STEP 25 - PASSIVE LIVESTOCK (Combat Phase 3c): peaceful
        //   fauna — Cow, Sheep, Pig. Wander + flee AI, radial-aligned,
        //   drop Raw Meat / Hide / Wool. Auto-spawns near the player via
        //   PassiveAnimalSpawner. Non-destructive: existing prefabs are
        //   preserved; re-runnable and idempotent.
        // ============================================================
        private void BuildLivestockContent()
        {
            EnsureFolder("Assets/Resources");
            EnsureFolder("Assets/Resources/Livestock");
            const string FAUNA_ROOT  = ASSET_ROOT + "/Fauna";
            const string FAUNA_ITEMS = FAUNA_ROOT + "/Items";
            const string FAUNA_MATS  = FAUNA_ROOT + "/Materials";
            EnsureFolder(FAUNA_ROOT);
            EnsureFolder(FAUNA_ITEMS);
            EnsureFolder(FAUNA_MATS);

            // ── Animal-product items ────────────────────────────────
            var rawMeat = GetOrCreateAsset<VoxelEngine.Items.ItemDefinition>($"{FAUNA_ITEMS}/Item_RawMeat.asset");
            rawMeat.itemId = "item_raw_meat"; rawMeat.displayName = "Raw Meat";
            rawMeat.description = "Fresh meat harvested from livestock. Cook it at a furnace for safe, filling food.";
            rawMeat.iconTint = new Color(0.80f, 0.34f, 0.30f); rawMeat.maxStack = 40; rawMeat.massPerUnit = 0.5f; rawMeat.category = "Food";
            EditorUtility.SetDirty(rawMeat);

            var hide = GetOrCreateAsset<VoxelEngine.Items.ItemDefinition>($"{FAUNA_ITEMS}/Item_Hide.asset");
            hide.itemId = "item_hide"; hide.displayName = "Animal Hide";
            hide.description = "Tough hide from cattle. A leatherworking and low-tier armor material.";
            hide.iconTint = new Color(0.58f, 0.42f, 0.28f); hide.maxStack = 40; hide.massPerUnit = 0.6f; hide.category = "Resources";
            EditorUtility.SetDirty(hide);

            var wool = GetOrCreateAsset<VoxelEngine.Items.ItemDefinition>($"{FAUNA_ITEMS}/Item_Wool.asset");
            wool.itemId = "item_wool"; wool.displayName = "Wool";
            wool.description = "Soft fleece sheared from sheep. Used for textiles, insulation, and banners.";
            wool.iconTint = new Color(0.92f, 0.90f, 0.82f); wool.maxStack = 64; wool.massPerUnit = 0.2f; wool.category = "Resources";
            EditorUtility.SetDirty(wool);

            // ── Materials ───────────────────────────────────────────
            var cowBody  = MakeColoredMat(FAUNA_MATS, "Mat_CowBody",   new Color(0.46f, 0.30f, 0.18f));
            var cowWhite = MakeColoredMat(FAUNA_MATS, "Mat_CowWhite",  new Color(0.90f, 0.88f, 0.82f));
            var cowDark  = MakeColoredMat(FAUNA_MATS, "Mat_CowDark",   new Color(0.14f, 0.11f, 0.09f));
            var cowPink  = MakeColoredMat(FAUNA_MATS, "Mat_CowPink",   new Color(0.86f, 0.56f, 0.58f));
            var cowHorn  = MakeColoredMat(FAUNA_MATS, "Mat_CowHorn",   new Color(0.88f, 0.82f, 0.66f));

            var woolMat  = MakeColoredMat(FAUNA_MATS, "Mat_Wool",      new Color(0.93f, 0.91f, 0.84f));
            var woolDk   = MakeColoredMat(FAUNA_MATS, "Mat_SheepDark", new Color(0.30f, 0.26f, 0.22f));
            var woolTan  = MakeColoredMat(FAUNA_MATS, "Mat_SheepLeg",  new Color(0.50f, 0.40f, 0.30f));

            var pigBody  = MakeColoredMat(FAUNA_MATS, "Mat_PigBody",   new Color(0.93f, 0.66f, 0.68f));
            var pigDark  = MakeColoredMat(FAUNA_MATS, "Mat_PigDark",   new Color(0.78f, 0.46f, 0.50f));
            var pigHoof  = MakeColoredMat(FAUNA_MATS, "Mat_PigHoof",   new Color(0.26f, 0.20f, 0.18f));
            var eyeBlk   = MakeColoredMat(FAUNA_MATS, "Mat_AnimalEye", new Color(0.05f, 0.05f, 0.05f));

            // ── Build helpers ───────────────────────────────────────
            void AddPart(GameObject root, string n, Vector3 pos, Vector3 euler, Vector3 scale, Material m)
            {
                var go = GameObject.CreatePrimitive(PrimitiveType.Cube);
                go.name = n; go.transform.SetParent(root.transform, false);
                go.transform.localPosition = pos; go.transform.localEulerAngles = euler; go.transform.localScale = scale;
                go.GetComponent<Renderer>().sharedMaterial = m;
                var col = go.GetComponent<Collider>(); if (col != null) UnityEngine.Object.DestroyImmediate(col);
            }

            GameObject FinishAndSave(GameObject root, string prefabPath, VoxelEngine.Fauna.AnimalSpecies species,
                float health, float capH, float capR, Vector3 capC,
                VoxelEngine.Items.ItemDefinition[] dropsArr, int minD, int maxD, Color barFill, Color barLow)
            {
                var cap = root.AddComponent<CapsuleCollider>();
                cap.height = capH; cap.radius = capR; cap.center = capC;
                var rb = root.AddComponent<Rigidbody>();
                rb.useGravity = false; rb.freezeRotation = true;
                var animal = root.AddComponent<VoxelEngine.Fauna.PassiveAnimal>();
                animal.species = species;
                animal.maxHealth = health;
                animal.drops = dropsArr; animal.minDrops = minD; animal.maxDrops = maxD; animal.dropCount = 1;
                var hbar = root.AddComponent<VoxelEngine.Combat.CreatureHealthBar>();
                hbar.target = animal;
                hbar.fillColor = barFill; hbar.fillColorLow = barLow;

                // NON-DESTRUCTIVE: preserve an existing prefab (user may have customized it).
                if (AssetDatabase.LoadMainAssetAtPath(prefabPath) != null)
                {
                    var existing = AssetDatabase.LoadAssetAtPath<GameObject>(prefabPath);
                    UnityEngine.Object.DestroyImmediate(root);
                    return existing;
                }
                var saved = PrefabUtility.SaveAsPrefabAsset(root, prefabPath);
                UnityEngine.Object.DestroyImmediate(root);
                return saved;
            }

            // ── COW (stocky chestnut, white belly, black patches, horns) ──
            var cow = new GameObject("Cow");
            AddPart(cow, "Body",      new Vector3(0f, 0.95f, 0f),      Vector3.zero,              new Vector3(0.85f, 0.78f, 1.6f),  cowBody);
            AddPart(cow, "BackPatch", new Vector3(0f, 1.22f, -0.25f),  Vector3.zero,              new Vector3(0.72f, 0.22f, 0.7f),   cowDark);
            AddPart(cow, "Hump",      new Vector3(0f, 1.25f, 0.45f),   Vector3.zero,              new Vector3(0.68f, 0.22f, 0.55f),  cowBody);
            AddPart(cow, "Belly",     new Vector3(0f, 0.66f, 0.02f),   Vector3.zero,              new Vector3(0.7f, 0.28f, 1.2f),    cowWhite);
            AddPart(cow, "Neck",      new Vector3(0f, 1.05f, 0.78f),   new Vector3(-18f, 0f, 0f),  new Vector3(0.5f, 0.5f, 0.5f),     cowBody);
            AddPart(cow, "Head",      new Vector3(0f, 1.18f, 1.02f),   new Vector3(-12f, 0f, 0f),  new Vector3(0.55f, 0.52f, 0.52f),  cowBody);
            AddPart(cow, "Muzzle",    new Vector3(0f, 1.06f, 1.28f),   new Vector3(-12f, 0f, 0f),  new Vector3(0.44f, 0.34f, 0.2f),   cowPink);
            AddPart(cow, "HornL",     new Vector3(-0.16f, 1.45f, 0.98f), new Vector3(-30f, 0f, -25f), new Vector3(0.07f, 0.16f, 0.07f), cowHorn);
            AddPart(cow, "HornR",     new Vector3(0.16f, 1.45f, 0.98f),  new Vector3(-30f, 0f, 25f),  new Vector3(0.07f, 0.16f, 0.07f), cowHorn);
            AddPart(cow, "EarL",      new Vector3(-0.34f, 1.22f, 0.95f), new Vector3(0f, 0f, -20f),   new Vector3(0.13f, 0.07f, 0.2f),   cowBody);
            AddPart(cow, "EarR",      new Vector3(0.34f, 1.22f, 0.95f),  new Vector3(0f, 0f, 20f),    new Vector3(0.13f, 0.07f, 0.2f),   cowBody);
            AddPart(cow, "EyeL",      new Vector3(-0.16f, 1.28f, 1.22f), Vector3.zero,              new Vector3(0.06f, 0.07f, 0.04f),  eyeBlk);
            AddPart(cow, "EyeR",      new Vector3(0.16f, 1.28f, 1.22f),  Vector3.zero,              new Vector3(0.06f, 0.07f, 0.04f),  eyeBlk);
            AddPart(cow, "LegFL", new Vector3(-0.26f, 0.36f, 0.55f),  Vector3.zero, new Vector3(0.2f, 0.72f, 0.22f), cowBody);
            AddPart(cow, "LegFR", new Vector3(0.26f, 0.36f, 0.55f),   Vector3.zero, new Vector3(0.2f, 0.72f, 0.22f), cowBody);
            AddPart(cow, "LegBL", new Vector3(-0.26f, 0.36f, -0.55f), Vector3.zero, new Vector3(0.2f, 0.72f, 0.22f), cowBody);
            AddPart(cow, "LegBR", new Vector3(0.26f, 0.36f, -0.55f),  Vector3.zero, new Vector3(0.2f, 0.72f, 0.22f), cowBody);
            AddPart(cow, "HoofFL", new Vector3(-0.26f, 0.04f, 0.55f), Vector3.zero, new Vector3(0.22f, 0.1f, 0.24f), cowDark);
            AddPart(cow, "HoofFR", new Vector3(0.26f, 0.04f, 0.55f),  Vector3.zero, new Vector3(0.22f, 0.1f, 0.24f), cowDark);
            AddPart(cow, "HoofBL", new Vector3(-0.26f, 0.04f, -0.55f),Vector3.zero, new Vector3(0.22f, 0.1f, 0.24f), cowDark);
            AddPart(cow, "HoofBR", new Vector3(0.26f, 0.04f, -0.55f), Vector3.zero, new Vector3(0.22f, 0.1f, 0.24f), cowDark);
            AddPart(cow, "Tail",     new Vector3(0f, 1.05f, -0.86f),  new Vector3(20f, 0f, 0f), new Vector3(0.08f, 0.4f, 0.08f),  cowBody);
            AddPart(cow, "TailTuft", new Vector3(0f, 0.82f, -0.95f),  Vector3.zero,            new Vector3(0.12f, 0.12f, 0.12f), cowDark);
            AddPart(cow, "Udder",    new Vector3(0f, 0.55f, -0.35f),  Vector3.zero,            new Vector3(0.36f, 0.24f, 0.42f), cowPink);
            var cowPrefab = FinishAndSave(cow, "Assets/Resources/Livestock/Cow.prefab", VoxelEngine.Fauna.AnimalSpecies.Cow,
                30f, 1.5f, 0.5f, new Vector3(0f, 0.78f, 0f),
                new VoxelEngine.Items.ItemDefinition[] { rawMeat, hide }, 1, 3,
                new Color(0.50f, 0.75f, 0.40f), new Color(0.80f, 0.35f, 0.25f));

            // ── SHEEP (fluffy cream fleece, narrow dark face) ──
            var sheep = new GameObject("Sheep");
            AddPart(sheep, "WoolBody", new Vector3(0f, 0.72f, 0f),      Vector3.zero, new Vector3(0.8f, 0.78f, 1.1f),   woolMat);
            AddPart(sheep, "WoolTop",  new Vector3(0f, 1.02f, 0f),      Vector3.zero, new Vector3(0.7f, 0.3f, 0.95f),    woolMat);
            AddPart(sheep, "WoolL",    new Vector3(-0.42f, 0.74f, 0f),  Vector3.zero, new Vector3(0.22f, 0.55f, 0.85f),  woolMat);
            AddPart(sheep, "WoolR",    new Vector3(0.42f, 0.74f, 0f),   Vector3.zero, new Vector3(0.22f, 0.55f, 0.85f),  woolMat);
            AddPart(sheep, "WoolRump", new Vector3(0f, 0.78f, -0.5f),   Vector3.zero, new Vector3(0.7f, 0.6f, 0.3f),     woolMat);
            AddPart(sheep, "Head",     new Vector3(0f, 0.86f, 0.62f),   new Vector3(-10f, 0f, 0f), new Vector3(0.32f, 0.42f, 0.4f),   woolDk);
            AddPart(sheep, "Snout",    new Vector3(0f, 0.78f, 0.84f),   new Vector3(-10f, 0f, 0f), new Vector3(0.26f, 0.22f, 0.16f),  woolDk);
            AddPart(sheep, "Topknot",  new Vector3(0f, 1.02f, 0.6f),    Vector3.zero, new Vector3(0.34f, 0.2f, 0.36f),   woolMat);
            AddPart(sheep, "EarL", new Vector3(-0.2f, 0.9f, 0.6f), new Vector3(0f, 0f, -15f), new Vector3(0.1f, 0.18f, 0.06f), woolDk);
            AddPart(sheep, "EarR", new Vector3(0.2f, 0.9f, 0.6f),  new Vector3(0f, 0f, 15f),  new Vector3(0.1f, 0.18f, 0.06f), woolDk);
            AddPart(sheep, "EyeL", new Vector3(-0.1f, 0.9f, 0.78f), Vector3.zero, new Vector3(0.05f, 0.06f, 0.04f), eyeBlk);
            AddPart(sheep, "EyeR", new Vector3(0.1f, 0.9f, 0.78f),  Vector3.zero, new Vector3(0.05f, 0.06f, 0.04f), eyeBlk);
            AddPart(sheep, "LegFL", new Vector3(-0.22f, 0.27f, 0.38f),  Vector3.zero, new Vector3(0.12f, 0.5f, 0.12f), woolTan);
            AddPart(sheep, "LegFR", new Vector3(0.22f, 0.27f, 0.38f),   Vector3.zero, new Vector3(0.12f, 0.5f, 0.12f), woolTan);
            AddPart(sheep, "LegBL", new Vector3(-0.22f, 0.27f, -0.38f), Vector3.zero, new Vector3(0.12f, 0.5f, 0.12f), woolTan);
            AddPart(sheep, "LegBR", new Vector3(0.22f, 0.27f, -0.38f),  Vector3.zero, new Vector3(0.12f, 0.5f, 0.12f), woolTan);
            var sheepPrefab = FinishAndSave(sheep, "Assets/Resources/Livestock/Sheep.prefab", VoxelEngine.Fauna.AnimalSpecies.Sheep,
                18f, 1.1f, 0.42f, new Vector3(0f, 0.6f, 0f),
                new VoxelEngine.Items.ItemDefinition[] { rawMeat, wool }, 1, 2,
                new Color(0.60f, 0.80f, 0.55f), new Color(0.80f, 0.40f, 0.30f));

            // ── PIG (pink, flat snout, floppy ears, curly tail) ──
            var pig = new GameObject("Pig");
            AddPart(pig, "Body",    new Vector3(0f, 0.6f, 0f),      Vector3.zero, new Vector3(0.66f, 0.6f, 1.15f), pigBody);
            AddPart(pig, "Belly",   new Vector3(0f, 0.42f, 0f),     Vector3.zero, new Vector3(0.5f, 0.18f, 0.9f),  pigDark);
            AddPart(pig, "Head",    new Vector3(0f, 0.66f, 0.6f),   Vector3.zero, new Vector3(0.5f, 0.5f, 0.45f),  pigBody);
            AddPart(pig, "Snout",   new Vector3(0f, 0.6f, 0.86f),   Vector3.zero, new Vector3(0.36f, 0.3f, 0.12f),  pigDark);
            AddPart(pig, "NostrilL",new Vector3(-0.09f, 0.6f, 0.93f),Vector3.zero,new Vector3(0.05f, 0.06f, 0.03f), eyeBlk);
            AddPart(pig, "NostrilR",new Vector3(0.09f, 0.6f, 0.93f), Vector3.zero,new Vector3(0.05f, 0.06f, 0.03f), eyeBlk);
            AddPart(pig, "EarL", new Vector3(-0.28f, 0.86f, 0.58f), new Vector3(0f, 0f, -30f), new Vector3(0.13f, 0.2f, 0.07f), pigDark);
            AddPart(pig, "EarR", new Vector3(0.28f, 0.86f, 0.58f),  new Vector3(0f, 0f, 30f),  new Vector3(0.13f, 0.2f, 0.07f), pigDark);
            AddPart(pig, "EyeL", new Vector3(-0.15f, 0.78f, 0.74f), Vector3.zero, new Vector3(0.05f, 0.06f, 0.04f), eyeBlk);
            AddPart(pig, "EyeR", new Vector3(0.15f, 0.78f, 0.74f),  Vector3.zero, new Vector3(0.05f, 0.06f, 0.04f), eyeBlk);
            AddPart(pig, "LegFL", new Vector3(-0.2f, 0.28f, 0.4f),  Vector3.zero, new Vector3(0.17f, 0.5f, 0.19f), pigBody);
            AddPart(pig, "LegFR", new Vector3(0.2f, 0.28f, 0.4f),   Vector3.zero, new Vector3(0.17f, 0.5f, 0.19f), pigBody);
            AddPart(pig, "LegBL", new Vector3(-0.2f, 0.28f, -0.4f), Vector3.zero, new Vector3(0.17f, 0.5f, 0.19f), pigBody);
            AddPart(pig, "LegBR", new Vector3(0.2f, 0.28f, -0.4f),  Vector3.zero, new Vector3(0.17f, 0.5f, 0.19f), pigBody);
            AddPart(pig, "HoofFL", new Vector3(-0.2f, 0.05f, 0.4f), Vector3.zero, new Vector3(0.19f, 0.1f, 0.21f), pigHoof);
            AddPart(pig, "HoofFR", new Vector3(0.2f, 0.05f, 0.4f),  Vector3.zero, new Vector3(0.19f, 0.1f, 0.21f), pigHoof);
            AddPart(pig, "HoofBL", new Vector3(-0.2f, 0.05f, -0.4f),Vector3.zero, new Vector3(0.19f, 0.1f, 0.21f), pigHoof);
            AddPart(pig, "HoofBR", new Vector3(0.2f, 0.05f, -0.4f), Vector3.zero, new Vector3(0.19f, 0.1f, 0.21f), pigHoof);
            AddPart(pig, "Tail1", new Vector3(0f, 0.7f, -0.6f),     Vector3.zero,             new Vector3(0.07f, 0.07f, 0.18f), pigBody);
            AddPart(pig, "Tail2", new Vector3(0.06f, 0.78f, -0.68f),new Vector3(0f, 40f, 0f),  new Vector3(0.06f, 0.06f, 0.12f), pigBody);
            var pigPrefab = FinishAndSave(pig, "Assets/Resources/Livestock/Pig.prefab", VoxelEngine.Fauna.AnimalSpecies.Pig,
                16f, 1.0f, 0.42f, new Vector3(0f, 0.55f, 0f),
                new VoxelEngine.Items.ItemDefinition[] { rawMeat }, 1, 2,
                new Color(0.85f, 0.55f, 0.60f), new Color(0.80f, 0.30f, 0.35f));

            // ── Inject livestock into temperate biome scatter (the reliable spawn path —
            //    same mechanism as the Ghoul). PassiveAnimal detaches from the chunk
            //    parent on Awake, so Rigidbody physics stays correct on rotating spheres.
            var livestockPrefabs = new System.Collections.Generic.List<GameObject>();
            if (cowPrefab   != null) livestockPrefabs.Add(cowPrefab);
            if (sheepPrefab != null) livestockPrefabs.Add(sheepPrefab);
            if (pigPrefab   != null) livestockPrefabs.Add(pigPrefab);
            var biomeRegistry = AssetDatabase.LoadAssetAtPath<VoxelEngine.Biomes.BiomeRegistry>(ASSET_ROOT + "/BiomeRegistry.asset");
            if (biomeRegistry != null && livestockPrefabs.Count > 0)
            {
                foreach (var biome in biomeRegistry.biomes)
                {
                    if (biome == null) continue;
                    if (biome.biomeName != "Forest" && biome.biomeName != "Plains" && biome.biomeName != "Steppes") continue;
                    var list = (biome.scatter != null)
                        ? new System.Collections.Generic.List<VoxelEngine.Biomes.BiomeDefinition.ScatterEntry>(biome.scatter)
                        : new System.Collections.Generic.List<VoxelEngine.Biomes.BiomeDefinition.ScatterEntry>();
                    list.RemoveAll(e => e.prefab != null && (e.prefab.name == "Cow" || e.prefab.name == "Sheep" || e.prefab.name == "Pig"));
                    foreach (var pf in livestockPrefabs)
                        list.Add(new VoxelEngine.Biomes.BiomeDefinition.ScatterEntry { prefab = pf, density = 0.004f, minScale = 0.9f, maxScale = 1.15f, minHeight = 0, maxHeight = 9999 });
                    biome.scatter = list.ToArray();
                    EditorUtility.SetDirty(biome);
                }
                EditorUtility.SetDirty(biomeRegistry);
            }

            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();
            EditorUtility.DisplayDialog("Voxel Engine — Passive Livestock (Phase 3c)",
                "Peaceful livestock built:\n\n" +
                "• Cow — stocky chestnut with horns; drops Raw Meat + Hide\n" +
                "• Sheep — fluffy cream fleece; drops Raw Meat + Wool\n" +
                "• Pig — pink with a flat snout; drops Raw Meat\n\n" +
                "They wander the surface, flee when hit, and auto-spawn near the player via PassiveAnimalSpawner.\n" +
                "Saved to Resources/Livestock (existing prefabs preserved). Harvest with weapons for meat, hide, and wool.",
                "OK");
        }

        // ============================================================
        //   STEP 26 - RIDEABLE HORSE (Combat Phase 3d): a mountable
        //   quadruped. Graze/wander when riderless; look + press the
        //   cockpit key to mount, then WASD to ride, Shift to gallop,
        //   Space to jump, F to dismount. Non-destructive: existing
        //   prefabs preserved. Re-runnable. Idempotent.
        // ============================================================
        private void BuildHorseContent()
        {
            EnsureFolder("Assets/Resources");
            EnsureFolder("Assets/Resources/Livestock");
            const string FAUNA_ROOT  = ASSET_ROOT + "/Fauna";
            const string FAUNA_ITEMS = FAUNA_ROOT + "/Items";
            const string FAUNA_MATS  = FAUNA_ROOT + "/Materials";
            EnsureFolder(FAUNA_ROOT);
            EnsureFolder(FAUNA_ITEMS);
            EnsureFolder(FAUNA_MATS);

            // Reuse the livestock product items (created by Step 25; idempotent here).
            var rawMeat = GetOrCreateAsset<VoxelEngine.Items.ItemDefinition>($"{FAUNA_ITEMS}/Item_RawMeat.asset");
            var hide    = GetOrCreateAsset<VoxelEngine.Items.ItemDefinition>($"{FAUNA_ITEMS}/Item_Hide.asset");

            var bodyMat  = MakeColoredMat(FAUNA_MATS, "Mat_HorseBody",  new Color(0.40f, 0.26f, 0.16f)); // bay brown
            var darkMat  = MakeColoredMat(FAUNA_MATS, "Mat_HorseDark",  new Color(0.16f, 0.11f, 0.07f)); // mane/tail/hooves
            var whiteMat = MakeColoredMat(FAUNA_MATS, "Mat_HorseWhite", new Color(0.90f, 0.88f, 0.82f)); // blaze/socks
            var tanMat   = MakeColoredMat(FAUNA_MATS, "Mat_HorseTan",   new Color(0.62f, 0.46f, 0.32f)); // muzzle
            var eyeBlk   = MakeColoredMat(FAUNA_MATS, "Mat_AnimalEye",  new Color(0.05f, 0.05f, 0.05f));

            void AddPart(GameObject root, string n, Vector3 pos, Vector3 euler, Vector3 scale, Material m)
            {
                var go = GameObject.CreatePrimitive(PrimitiveType.Cube);
                go.name = n; go.transform.SetParent(root.transform, false);
                go.transform.localPosition = pos; go.transform.localEulerAngles = euler; go.transform.localScale = scale;
                go.GetComponent<Renderer>().sharedMaterial = m;
                var col = go.GetComponent<Collider>(); if (col != null) UnityEngine.Object.DestroyImmediate(col);
            }

            var root = new GameObject("Horse");
            // ── Body, chest, rump, belly ──
            AddPart(root, "Body",  new Vector3(0f, 1.15f, 0f),    Vector3.zero,            new Vector3(0.72f, 0.72f, 1.85f), bodyMat);
            AddPart(root, "Chest", new Vector3(0f, 1.10f, 0.62f),  Vector3.zero,            new Vector3(0.78f, 0.78f, 0.5f),  bodyMat);
            AddPart(root, "Rump",  new Vector3(0f, 1.18f, -0.62f), Vector3.zero,            new Vector3(0.80f, 0.78f, 0.5f),  bodyMat);
            AddPart(root, "Belly", new Vector3(0f, 0.85f, 0f),     Vector3.zero,            new Vector3(0.58f, 0.30f, 1.4f),  darkMat);
            // ── Neck + head + muzzle + ears + face ──
            AddPart(root, "Neck",   new Vector3(0f, 1.45f, 0.78f), new Vector3(-38f, 0f, 0f), new Vector3(0.46f, 0.78f, 0.46f), bodyMat);
            AddPart(root, "Head",   new Vector3(0f, 1.78f, 0.98f), new Vector3(-15f, 0f, 0f), new Vector3(0.42f, 0.50f, 0.55f), bodyMat);
            AddPart(root, "Muzzle", new Vector3(0f, 1.64f, 1.22f), new Vector3(-10f, 0f, 0f), new Vector3(0.32f, 0.32f, 0.22f), tanMat);
            AddPart(root, "NostrilL", new Vector3(-0.08f, 1.66f, 1.32f), Vector3.zero, new Vector3(0.04f, 0.05f, 0.03f), eyeBlk);
            AddPart(root, "NostrilR", new Vector3( 0.08f, 1.66f, 1.32f), Vector3.zero, new Vector3(0.04f, 0.05f, 0.03f), eyeBlk);
            AddPart(root, "Blaze",  new Vector3(0f, 1.80f, 1.25f), new Vector3(-15f, 0f, 0f), new Vector3(0.06f, 0.34f, 0.04f), whiteMat);
            AddPart(root, "EyeL",   new Vector3(-0.14f, 1.84f, 1.10f), Vector3.zero, new Vector3(0.06f, 0.07f, 0.04f), eyeBlk);
            AddPart(root, "EyeR",   new Vector3( 0.14f, 1.84f, 1.10f), Vector3.zero, new Vector3(0.06f, 0.07f, 0.04f), eyeBlk);
            AddPart(root, "EarL",   new Vector3(-0.13f, 2.04f, 0.93f), new Vector3(0f, 0f, -8f),  new Vector3(0.09f, 0.18f, 0.07f), bodyMat);
            AddPart(root, "EarR",   new Vector3( 0.13f, 2.04f, 0.93f), new Vector3(0f, 0f,  8f),  new Vector3(0.09f, 0.18f, 0.07f), bodyMat);
            AddPart(root, "Forelock", new Vector3(0f, 2.02f, 0.98f), Vector3.zero, new Vector3(0.16f, 0.16f, 0.12f), darkMat);
            // ── Mane (row of tufts along the neck) ──
            AddPart(root, "Mane1", new Vector3(0f, 1.72f, 0.60f), new Vector3(-30f, 0f, 0f), new Vector3(0.16f, 0.24f, 0.12f), darkMat);
            AddPart(root, "Mane2", new Vector3(0f, 1.80f, 0.72f), new Vector3(-30f, 0f, 0f), new Vector3(0.16f, 0.24f, 0.12f), darkMat);
            AddPart(root, "Mane3", new Vector3(0f, 1.88f, 0.84f), new Vector3(-30f, 0f, 0f), new Vector3(0.16f, 0.22f, 0.12f), darkMat);
            AddPart(root, "Mane4", new Vector3(0f, 1.94f, 0.95f), new Vector3(-30f, 0f, 0f), new Vector3(0.15f, 0.20f, 0.12f), darkMat);
            // ── Legs (4) ──
            AddPart(root, "LegFL", new Vector3(-0.22f, 0.55f,  0.60f), Vector3.zero, new Vector3(0.18f, 1.1f, 0.20f), bodyMat);
            AddPart(root, "LegFR", new Vector3( 0.22f, 0.55f,  0.60f), Vector3.zero, new Vector3(0.18f, 1.1f, 0.20f), bodyMat);
            AddPart(root, "LegBL", new Vector3(-0.22f, 0.55f, -0.62f), Vector3.zero, new Vector3(0.18f, 1.1f, 0.20f), bodyMat);
            AddPart(root, "LegBR", new Vector3( 0.22f, 0.55f, -0.62f), Vector3.zero, new Vector3(0.18f, 1.1f, 0.20f), bodyMat);
            // ── White socks (front) + hooves ──
            AddPart(root, "SockFL", new Vector3(-0.22f, 0.20f,  0.60f), Vector3.zero, new Vector3(0.20f, 0.30f, 0.22f), whiteMat);
            AddPart(root, "SockFR", new Vector3( 0.22f, 0.20f,  0.60f), Vector3.zero, new Vector3(0.20f, 0.30f, 0.22f), whiteMat);
            AddPart(root, "HoofFL", new Vector3(-0.22f, 0.06f,  0.60f), Vector3.zero, new Vector3(0.22f, 0.12f, 0.24f), darkMat);
            AddPart(root, "HoofFR", new Vector3( 0.22f, 0.06f,  0.60f), Vector3.zero, new Vector3(0.22f, 0.12f, 0.24f), darkMat);
            AddPart(root, "HoofBL", new Vector3(-0.22f, 0.06f, -0.62f), Vector3.zero, new Vector3(0.22f, 0.12f, 0.24f), darkMat);
            AddPart(root, "HoofBR", new Vector3( 0.22f, 0.06f, -0.62f), Vector3.zero, new Vector3(0.22f, 0.12f, 0.24f), darkMat);
            // ── Tail (flowing tufts from the rump) ──
            AddPart(root, "Tail1", new Vector3(0f, 1.20f, -0.86f), new Vector3( 20f, 0f, 0f), new Vector3(0.16f, 0.50f, 0.12f), darkMat);
            AddPart(root, "Tail2", new Vector3(0f, 0.92f, -0.90f), new Vector3( 35f, 0f, 0f), new Vector3(0.14f, 0.40f, 0.12f), darkMat);
            AddPart(root, "Tail3", new Vector3(0f, 0.70f, -0.86f), new Vector3( 45f, 0f, 0f), new Vector3(0.12f, 0.30f, 0.12f), darkMat);

            var cap = root.AddComponent<CapsuleCollider>();
            cap.height = 1.9f; cap.radius = 0.5f; cap.center = new Vector3(0f, 1.05f, 0f);
            var rb = root.AddComponent<Rigidbody>();
            rb.useGravity = false; rb.freezeRotation = true;
            var horse = root.AddComponent<VoxelEngine.Fauna.RideableAnimal>();
            horse.maxHealth = 45f;
            horse.seatLocalPos = new Vector3(0f, 0.6f, 0f);   // rider eye ~2.25 m (tunable)
            horse.drops = new VoxelEngine.Items.ItemDefinition[] { rawMeat, hide };
            horse.minDrops = 1; horse.maxDrops = 2; horse.dropCount = 1;
            var hbar = root.AddComponent<VoxelEngine.Combat.CreatureHealthBar>();
            hbar.target = horse;
            hbar.fillColor = new Color(0.55f, 0.78f, 0.90f);
            hbar.fillColorLow = new Color(0.80f, 0.35f, 0.25f);

            const string horsePath = "Assets/Resources/Livestock/Horse.prefab";
            GameObject horsePrefab;
            if (AssetDatabase.LoadMainAssetAtPath(horsePath) != null)
            {
                horsePrefab = AssetDatabase.LoadAssetAtPath<GameObject>(horsePath);
                UnityEngine.Object.DestroyImmediate(root);
            }
            else
            {
                horsePrefab = PrefabUtility.SaveAsPrefabAsset(root, horsePath);
                UnityEngine.Object.DestroyImmediate(root);
            }

            // Inject into open-plains biome scatter (reliable spawn path; same as livestock/Ghoul).
            var br = AssetDatabase.LoadAssetAtPath<VoxelEngine.Biomes.BiomeRegistry>(ASSET_ROOT + "/BiomeRegistry.asset");
            if (br != null && horsePrefab != null)
            {
                foreach (var biome in br.biomes)
                {
                    if (biome == null) continue;
                    if (biome.biomeName != "Plains" && biome.biomeName != "Steppes") continue;
                    var list = (biome.scatter != null)
                        ? new System.Collections.Generic.List<VoxelEngine.Biomes.BiomeDefinition.ScatterEntry>(biome.scatter)
                        : new System.Collections.Generic.List<VoxelEngine.Biomes.BiomeDefinition.ScatterEntry>();
                    list.RemoveAll(e => e.prefab != null && e.prefab.name == "Horse");
                    list.Add(new VoxelEngine.Biomes.BiomeDefinition.ScatterEntry { prefab = horsePrefab, density = 0.003f, minScale = 0.95f, maxScale = 1.15f, minHeight = 0, maxHeight = 9999 });
                    biome.scatter = list.ToArray();
                    EditorUtility.SetDirty(biome);
                }
                EditorUtility.SetDirty(br);
            }

            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();
            EditorUtility.DisplayDialog("Voxel Engine — Rideable Horse (Phase 3d)",
                "Rideable horse built:\n\n" +
                "• Premium bay horse: arched neck, mane, flowing tail, blaze + white socks, hooves\n" +
                "• Graze/wander when riderless; radial-aligned (spherical worlds)\n" +
                "• Look at a horse + press H to mount. WASD to ride, Shift to gallop, Space to jump, F to dismount\n\n" +
                "Spawns in Plains/Steppes (biome scatter) + via the livestock spawner. Saved to Resources/Livestock.",
                "OK");
        }

        // ============================================================
        //   STEP 27 - MYTHICAL ENEMY: MANTICORE (Combat Phase 3e). A
        //   lion-bodied predator with a humanoid face and a venomous
        //   scorpion tail. Fires toxic tail spikes at range + claws in
        //   melee; spikes apply an armor-bypassing poison DoT. Radial-
        //   aligned; detaches from the chunk on Awake. Non-destructive.
        //   Re-runnable. Idempotent.
        // ============================================================
        private void BuildManticoreContent()
        {
            EnsureFolder("Assets/Resources");
            EnsureFolder("Assets/Resources/Enemies");
            const string FAUNA_ROOT  = ASSET_ROOT + "/Fauna";
            const string FAUNA_ITEMS = FAUNA_ROOT + "/Items";
            const string FAUNA_MATS  = FAUNA_ROOT + "/Materials";
            EnsureFolder(FAUNA_ROOT);
            EnsureFolder(FAUNA_ITEMS);
            EnsureFolder(FAUNA_MATS);

            // ── Drop items ──
            var venomGland = GetOrCreateAsset<VoxelEngine.Items.ItemDefinition>($"{FAUNA_ITEMS}/Item_VenomGland.asset");
            venomGland.itemId = "item_venom_gland"; venomGland.displayName = "Venom Gland";
            venomGland.description = "A pulsing gland of Manticore venom. Alchemy and toxin-resistance material.";
            venomGland.iconTint = new Color(0.50f, 0.85f, 0.25f); venomGland.maxStack = 20; venomGland.massPerUnit = 0.3f; venomGland.category = "Resources";
            EditorUtility.SetDirty(venomGland);

            var tailSpike = GetOrCreateAsset<VoxelEngine.Items.ItemDefinition>($"{FAUNA_ITEMS}/Item_ManticoreSpike.asset");
            tailSpike.itemId = "item_manticore_spike"; tailSpike.displayName = "Manticore Spike";
            tailSpike.description = "A barbed chitin tail spike. A crafting reagent for armor-piercing gear.";
            tailSpike.iconTint = new Color(0.25f, 0.20f, 0.30f); tailSpike.maxStack = 40; tailSpike.massPerUnit = 0.2f; tailSpike.category = "Resources";
            EditorUtility.SetDirty(tailSpike);

            var armoredHide = GetOrCreateAsset<VoxelEngine.Items.ItemDefinition>($"{FAUNA_ITEMS}/Item_ArmoredHide.asset");
            armoredHide.itemId = "item_armored_hide"; armoredHide.displayName = "Armored Hide";
            armoredHide.description = "Tough plated hide from a Manticore. A high-impact armor and machinery material.";
            armoredHide.iconTint = new Color(0.50f, 0.38f, 0.22f); armoredHide.maxStack = 40; armoredHide.massPerUnit = 0.8f; armoredHide.category = "Resources";
            EditorUtility.SetDirty(armoredHide);

            // ── Materials ──
            var tawny     = MakeColoredMat(FAUNA_MATS, "Mat_ManticoreTawny", new Color(0.62f, 0.48f, 0.26f));
            var tan       = MakeColoredMat(FAUNA_MATS, "Mat_ManticoreTan",   new Color(0.72f, 0.60f, 0.40f));
            var mane      = MakeColoredMat(FAUNA_MATS, "Mat_ManticoreMane",  new Color(0.20f, 0.16f, 0.12f));
            var face      = MakeColoredMat(FAUNA_MATS, "Mat_ManticoreFace",  new Color(0.86f, 0.78f, 0.68f));
            var eye       = MakeColoredMat(FAUNA_MATS, "Mat_ManticoreEye",   new Color(0.95f, 0.20f, 0.10f));
            var chitin    = MakeColoredMat(FAUNA_MATS, "Mat_ManticoreChitin",new Color(0.18f, 0.14f, 0.22f));
            var venom     = MakeColoredMat(FAUNA_MATS, "Mat_ManticoreVenom", new Color(0.55f, 0.90f, 0.25f));
            var wing      = MakeColoredMat(FAUNA_MATS, "Mat_ManticoreWing",  new Color(0.22f, 0.18f, 0.28f));
            var dark      = MakeColoredMat(FAUNA_MATS, "Mat_ManticoreDark",  new Color(0.10f, 0.09f, 0.08f));
            var spikeMat  = MakeColoredMat(FAUNA_MATS, "Mat_ManticoreSpike", new Color(0.22f, 0.18f, 0.28f));

            void AddPart(GameObject root, string n, Vector3 pos, Vector3 euler, Vector3 scale, Material m)
            {
                var go = GameObject.CreatePrimitive(PrimitiveType.Cube);
                go.name = n; go.transform.SetParent(root.transform, false);
                go.transform.localPosition = pos; go.transform.localEulerAngles = euler; go.transform.localScale = scale;
                go.GetComponent<Renderer>().sharedMaterial = m;
                var col = go.GetComponent<Collider>(); if (col != null) UnityEngine.Object.DestroyImmediate(col);
            }

            var root = new GameObject("Manticore");
            // ── Lion body ──
            AddPart(root, "Torso", new Vector3(0f, 0.95f, 0f),    Vector3.zero, new Vector3(0.60f, 0.65f, 1.5f),  tawny);
            AddPart(root, "Chest", new Vector3(0f, 0.92f, 0.55f), Vector3.zero, new Vector3(0.66f, 0.66f, 0.45f), tawny);
            AddPart(root, "Rump",  new Vector3(0f, 0.95f, -0.55f),Vector3.zero, new Vector3(0.66f, 0.66f, 0.45f), tawny);
            AddPart(root, "Belly", new Vector3(0f, 0.70f, 0f),    Vector3.zero, new Vector3(0.50f, 0.25f, 1.1f),  tan);
            // ── Legs (upper + lower + paw) ×4 ──
            AddPart(root, "UpArmL",  new Vector3(-0.24f, 0.55f,  0.5f), Vector3.zero, new Vector3(0.16f, 0.55f, 0.18f), tawny);
            AddPart(root, "LoArmL",  new Vector3(-0.24f, 0.22f,  0.5f), Vector3.zero, new Vector3(0.14f, 0.45f, 0.16f), tawny);
            AddPart(root, "PawFL",   new Vector3(-0.24f, 0.05f,  0.5f), Vector3.zero, new Vector3(0.18f, 0.10f, 0.22f), dark);
            AddPart(root, "UpArmR",  new Vector3( 0.24f, 0.55f,  0.5f), Vector3.zero, new Vector3(0.16f, 0.55f, 0.18f), tawny);
            AddPart(root, "LoArmR",  new Vector3( 0.24f, 0.22f,  0.5f), Vector3.zero, new Vector3(0.14f, 0.45f, 0.16f), tawny);
            AddPart(root, "PawFR",   new Vector3( 0.24f, 0.05f,  0.5f), Vector3.zero, new Vector3(0.18f, 0.10f, 0.22f), dark);
            AddPart(root, "UpLegL",  new Vector3(-0.24f, 0.55f, -0.5f), Vector3.zero, new Vector3(0.16f, 0.55f, 0.18f), tawny);
            AddPart(root, "LoLegL",  new Vector3(-0.24f, 0.22f, -0.5f), Vector3.zero, new Vector3(0.14f, 0.45f, 0.16f), tawny);
            AddPart(root, "PawBL",   new Vector3(-0.24f, 0.05f, -0.5f), Vector3.zero, new Vector3(0.18f, 0.10f, 0.22f), dark);
            AddPart(root, "UpLegR",  new Vector3( 0.24f, 0.55f, -0.5f), Vector3.zero, new Vector3(0.16f, 0.55f, 0.18f), tawny);
            AddPart(root, "LoLegR",  new Vector3( 0.24f, 0.22f, -0.5f), Vector3.zero, new Vector3(0.14f, 0.45f, 0.16f), tawny);
            AddPart(root, "PawBR",   new Vector3( 0.24f, 0.05f, -0.5f), Vector3.zero, new Vector3(0.18f, 0.10f, 0.22f), dark);
            // ── Head + mane + humanoid face ──
            AddPart(root, "Head",    new Vector3(0f, 1.15f, 0.78f), new Vector3(-15f, 0f, 0f), new Vector3(0.40f, 0.42f, 0.45f), tawny);
            AddPart(root, "Mane",    new Vector3(0f, 1.22f, 0.6f),  Vector3.zero,            new Vector3(0.62f, 0.58f, 0.42f), mane);
            AddPart(root, "FacePlate",new Vector3(0f, 1.16f, 1.0f), new Vector3(-15f, 0f, 0f), new Vector3(0.30f, 0.36f, 0.08f), face);
            AddPart(root, "Brow",    new Vector3(0f, 1.30f, 0.99f), new Vector3(-15f, 0f, 0f), new Vector3(0.30f, 0.06f, 0.08f), mane);
            AddPart(root, "EyeL",    new Vector3(-0.09f, 1.22f, 1.05f), new Vector3(-15f, 0f, 0f), new Vector3(0.05f, 0.05f, 0.03f), eye);
            AddPart(root, "EyeR",    new Vector3( 0.09f, 1.22f, 1.05f), new Vector3(-15f, 0f, 0f), new Vector3(0.05f, 0.05f, 0.03f), eye);
            AddPart(root, "Nose",    new Vector3(0f, 1.12f, 1.05f), new Vector3(-15f, 0f, 0f), new Vector3(0.06f, 0.05f, 0.04f), dark);
            AddPart(root, "Mouth",   new Vector3(0f, 1.05f, 1.03f), new Vector3(-15f, 0f, 0f), new Vector3(0.13f, 0.03f, 0.04f), dark);
            AddPart(root, "EarL",    new Vector3(-0.2f, 1.36f, 0.72f), new Vector3(0f, 0f, -10f), new Vector3(0.10f, 0.16f, 0.06f), tawny);
            AddPart(root, "EarR",    new Vector3( 0.2f, 1.36f, 0.72f), new Vector3(0f, 0f,  10f), new Vector3(0.10f, 0.16f, 0.06f), tawny);
            // ── Bat wings (folded on the shoulders) ──
            AddPart(root, "WingL", new Vector3(-0.42f, 1.16f, 0.05f), new Vector3(0f, -10f, 28f),  new Vector3(0.55f, 0.45f, 0.06f), wing);
            AddPart(root, "WingR", new Vector3( 0.42f, 1.16f, 0.05f), new Vector3(0f,  10f, -28f), new Vector3(0.55f, 0.45f, 0.06f), wing);
            // ── Scorpion tail (curved up + forward over the back, stinger aiming ahead) ──
            AddPart(root, "Seg1", new Vector3(0f, 1.08f, -0.72f), new Vector3( 25f, 0f, 0f), new Vector3(0.16f, 0.16f, 0.18f), chitin);
            AddPart(root, "Seg2", new Vector3(0f, 1.30f, -0.88f), new Vector3( 55f, 0f, 0f), new Vector3(0.15f, 0.15f, 0.17f), chitin);
            AddPart(root, "Seg3", new Vector3(0f, 1.55f, -0.74f), new Vector3( 90f, 0f, 0f), new Vector3(0.14f, 0.14f, 0.16f), chitin);
            AddPart(root, "Seg4", new Vector3(0f, 1.62f, -0.45f), new Vector3(120f, 0f, 0f), new Vector3(0.13f, 0.13f, 0.15f), chitin);
            AddPart(root, "Seg5", new Vector3(0f, 1.52f, -0.18f), new Vector3(145f, 0f, 0f), new Vector3(0.12f, 0.12f, 0.14f), chitin);
            AddPart(root, "Stinger", new Vector3(0f, 1.36f, 0.02f), new Vector3(165f, 0f, 0f), new Vector3(0.10f, 0.26f, 0.10f), venom);

            var cap = root.AddComponent<CapsuleCollider>();
            cap.height = 1.6f; cap.radius = 0.5f; cap.center = new Vector3(0f, 0.95f, 0f);
            var rb = root.AddComponent<Rigidbody>();
            rb.useGravity = false; rb.freezeRotation = true;
            var manticore = root.AddComponent<VoxelEngine.Combat.EnemyManticore>();
            manticore.spikeMaterial = spikeMat;
            manticore.drops = new VoxelEngine.Items.ItemDefinition[] { venomGland, tailSpike, armoredHide };
            manticore.minDrops = 1; manticore.maxDrops = 3; manticore.dropCount = 1;
            var hbar = root.AddComponent<VoxelEngine.Combat.CreatureHealthBar>();
            hbar.target = manticore;
            hbar.fillColor = new Color(0.70f, 0.25f, 0.60f);
            hbar.fillColorLow = new Color(0.80f, 0.15f, 0.10f);

            const string manticorePath = "Assets/Resources/Enemies/Manticore.prefab";
            GameObject manticorePrefab;
            if (AssetDatabase.LoadMainAssetAtPath(manticorePath) != null)
            {
                manticorePrefab = AssetDatabase.LoadAssetAtPath<GameObject>(manticorePath);
                UnityEngine.Object.DestroyImmediate(root);
            }
            else
            {
                manticorePrefab = PrefabUtility.SaveAsPrefabAsset(root, manticorePath);
                UnityEngine.Object.DestroyImmediate(root);
            }

            // Inject into desert/wasteland biome scatter (reliable spawn path; same as the Ghoul).
            var br = AssetDatabase.LoadAssetAtPath<VoxelEngine.Biomes.BiomeRegistry>(ASSET_ROOT + "/BiomeRegistry.asset");
            if (br != null && manticorePrefab != null)
            {
                foreach (var biome in br.biomes)
                {
                    if (biome == null) continue;
                    if (biome.biomeName != "Desert" && biome.biomeName != "Wasteland") continue;
                    var list = (biome.scatter != null)
                        ? new System.Collections.Generic.List<VoxelEngine.Biomes.BiomeDefinition.ScatterEntry>(biome.scatter)
                        : new System.Collections.Generic.List<VoxelEngine.Biomes.BiomeDefinition.ScatterEntry>();
                    list.RemoveAll(e => e.prefab != null && e.prefab.name == "Manticore");
                    list.Add(new VoxelEngine.Biomes.BiomeDefinition.ScatterEntry { prefab = manticorePrefab, density = 0.003f, minScale = 0.95f, maxScale = 1.15f, minHeight = 0, maxHeight = 9999 });
                    biome.scatter = list.ToArray();
                    EditorUtility.SetDirty(biome);
                }
                EditorUtility.SetDirty(br);
            }

            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();
            EditorUtility.DisplayDialog("Voxel Engine — Mythical Enemy: Manticore (Phase 3e)",
                "The Manticore is built:\n\n" +
                "• Lion body, humanoid face, bat wings, and a venomous scorpion tail (~35 parts)\n" +
                "• Fires volleys of toxic tail spikes at range + claws in melee\n" +
                "• Spikes apply an armor-bypassing poison DoT (PlayerStats.ApplyPoison)\n" +
                "• Drops Venom Gland, Manticore Spike, Armored Hide\n\n" +
                "Spawns rarely in Desert/Wasteland (biome scatter). Saved to Resources/Enemies.",
                "OK");
        }

        // ============================================================
        //   STEP 28 - MYTHICAL ENEMY: GRIFFIN (Combat Phase 3f). A
        //   heraldic lion-eagle that FLIES — circles overhead then
        //   dive-bombs with its talons. Radial-aware; detaches from
        //   the chunk on Awake. Rarely drops a Griffin Heart. Non-
        //   destructive. Re-runnable. Idempotent.
        // ============================================================
        private void BuildGriffinContent()
        {
            EnsureFolder("Assets/Resources");
            EnsureFolder("Assets/Resources/Enemies");
            const string FAUNA_ROOT  = ASSET_ROOT + "/Fauna";
            const string FAUNA_ITEMS = FAUNA_ROOT + "/Items";
            const string FAUNA_MATS  = FAUNA_ROOT + "/Materials";
            EnsureFolder(FAUNA_ROOT);
            EnsureFolder(FAUNA_ITEMS);
            EnsureFolder(FAUNA_MATS);

            // ── Drop items ──
            var feather = GetOrCreateAsset<VoxelEngine.Items.ItemDefinition>($"{FAUNA_ITEMS}/Item_GriffinFeather.asset");
            feather.itemId = "item_griffin_feather"; feather.displayName = "Griffin Feather";
            feather.description = "A long flight feather from a Griffin. Used in aerial equipment and fletching.";
            feather.iconTint = new Color(0.55f, 0.42f, 0.24f); feather.maxStack = 40; feather.massPerUnit = 0.1f; feather.category = "Resources";
            EditorUtility.SetDirty(feather);

            var talon = GetOrCreateAsset<VoxelEngine.Items.ItemDefinition>($"{FAUNA_ITEMS}/Item_GriffinTalon.asset");
            talon.itemId = "item_griffin_talon"; talon.displayName = "Griffin Talon";
            talon.description = "A curved raptorial talon. A sharp crafting reagent for piercing weapons.";
            talon.iconTint = new Color(0.85f, 0.72f, 0.22f); talon.maxStack = 30; talon.massPerUnit = 0.2f; talon.category = "Resources";
            EditorUtility.SetDirty(talon);

            var heart = GetOrCreateAsset<VoxelEngine.Items.ItemDefinition>($"{FAUNA_ITEMS}/Item_GriffinHeart.asset");
            heart.itemId = "item_griffin_heart"; heart.displayName = "Griffin Heart";
            heart.description = "A rare, still-warm heart of a slain Griffin. Required for advanced aerial research.";
            heart.iconTint = new Color(0.80f, 0.20f, 0.25f); heart.maxStack = 5; heart.massPerUnit = 1.0f; heart.category = "Resources";
            EditorUtility.SetDirty(heart);

            // ── Materials ──
            var eagleBrown = MakeColoredMat(FAUNA_MATS, "Mat_GriffinEagle", new Color(0.50f, 0.36f, 0.20f));
            var eagleDark  = MakeColoredMat(FAUNA_MATS, "Mat_GriffinDark",  new Color(0.30f, 0.22f, 0.14f));
            var lionTawny  = MakeColoredMat(FAUNA_MATS, "Mat_GriffinLion",  new Color(0.62f, 0.48f, 0.26f));
            var lionDark   = MakeColoredMat(FAUNA_MATS, "Mat_GriffinLionDk",new Color(0.20f, 0.16f, 0.12f));
            var gold       = MakeColoredMat(FAUNA_MATS, "Mat_GriffinGold",  new Color(0.85f, 0.70f, 0.20f));
            var eyeGold    = MakeColoredMat(FAUNA_MATS, "Mat_GriffinEye",   new Color(0.95f, 0.80f, 0.20f));

            void AddPart(GameObject root, string n, Vector3 pos, Vector3 euler, Vector3 scale, Material m)
            {
                var go = GameObject.CreatePrimitive(PrimitiveType.Cube);
                go.name = n; go.transform.SetParent(root.transform, false);
                go.transform.localPosition = pos; go.transform.localEulerAngles = euler; go.transform.localScale = scale;
                go.GetComponent<Renderer>().sharedMaterial = m;
                var col = go.GetComponent<Collider>(); if (col != null) UnityEngine.Object.DestroyImmediate(col);
            }

            var root = new GameObject("Griffin");
            // ── Body: eagle chest + lion hindquarters ──
            AddPart(root, "Chest", new Vector3(0f, 1.0f, 0.40f),  Vector3.zero, new Vector3(0.50f, 0.60f, 0.50f), eagleBrown);
            AddPart(root, "Torso", new Vector3(0f, 1.0f, -0.30f), Vector3.zero, new Vector3(0.50f, 0.55f, 0.90f), lionTawny);
            AddPart(root, "Rump",  new Vector3(0f, 1.0f, -0.85f), Vector3.zero, new Vector3(0.50f, 0.50f, 0.40f), lionTawny);
            // ── Eagle head + beak + crest ──
            AddPart(root, "Head",      new Vector3(0f, 1.40f, 0.75f), new Vector3(-12f, 0f, 0f), new Vector3(0.30f, 0.32f, 0.34f), eagleBrown);
            AddPart(root, "BeakUpper", new Vector3(0f, 1.36f, 1.00f), new Vector3(-12f, 0f, 0f), new Vector3(0.10f, 0.10f, 0.20f), gold);
            AddPart(root, "BeakLower", new Vector3(0f, 1.30f, 0.97f), new Vector3(-12f, 0f, 0f), new Vector3(0.08f, 0.05f, 0.12f), gold);
            AddPart(root, "Crest",     new Vector3(0f, 1.56f, 0.70f), new Vector3(-20f, 0f, 0f), new Vector3(0.08f, 0.20f, 0.12f), eagleDark);
            AddPart(root, "EyeL", new Vector3(-0.10f, 1.45f, 0.86f), Vector3.zero, new Vector3(0.04f, 0.04f, 0.03f), eyeGold);
            AddPart(root, "EyeR", new Vector3( 0.10f, 1.45f, 0.86f), Vector3.zero, new Vector3(0.04f, 0.04f, 0.03f), eyeGold);
            // ── Wings (spread from the shoulders) ──
            AddPart(root, "WingLBase",  new Vector3(-0.42f, 1.18f, 0.20f), new Vector3(0f, 0f, 28f),  new Vector3(0.10f, 0.50f, 0.75f), eagleDark);
            AddPart(root, "WingLTip",   new Vector3(-0.85f, 1.32f, 0.05f), new Vector3(0f, 0f, 42f),  new Vector3(0.08f, 0.30f, 0.55f), eagleBrown);
            AddPart(root, "WingLFeather",new Vector3(-0.70f, 0.95f, 0.0f), new Vector3(0f, 0f, 35f),  new Vector3(0.06f, 0.55f, 0.12f), eagleBrown);
            AddPart(root, "WingRBase",  new Vector3( 0.42f, 1.18f, 0.20f), new Vector3(0f, 0f, -28f), new Vector3(0.10f, 0.50f, 0.75f), eagleDark);
            AddPart(root, "WingRTip",   new Vector3( 0.85f, 1.32f, 0.05f), new Vector3(0f, 0f, -42f), new Vector3(0.08f, 0.30f, 0.55f), eagleBrown);
            AddPart(root, "WingRFeather",new Vector3( 0.70f, 0.95f, 0.0f), new Vector3(0f, 0f, -35f), new Vector3(0.06f, 0.55f, 0.12f), eagleBrown);
            // ── Eagle talons (front legs) ──
            AddPart(root, "TalonLegL", new Vector3(-0.16f, 0.55f, 0.40f), Vector3.zero, new Vector3(0.10f, 0.50f, 0.10f), gold);
            AddPart(root, "TalonFootL",new Vector3(-0.16f, 0.22f, 0.40f), Vector3.zero, new Vector3(0.18f, 0.10f, 0.22f), gold);
            AddPart(root, "ClawL1",    new Vector3(-0.22f, 0.16f, 0.50f), new Vector3(40f, 0f, 0f), new Vector3(0.04f, 0.04f, 0.12f), eagleDark);
            AddPart(root, "ClawL2",    new Vector3(-0.10f, 0.14f, 0.52f), new Vector3(40f, 0f, 0f), new Vector3(0.04f, 0.04f, 0.12f), eagleDark);
            AddPart(root, "TalonLegR", new Vector3( 0.16f, 0.55f, 0.40f), Vector3.zero, new Vector3(0.10f, 0.50f, 0.10f), gold);
            AddPart(root, "TalonFootR",new Vector3( 0.16f, 0.22f, 0.40f), Vector3.zero, new Vector3(0.18f, 0.10f, 0.22f), gold);
            AddPart(root, "ClawR1",    new Vector3( 0.22f, 0.16f, 0.50f), new Vector3(40f, 0f, 0f), new Vector3(0.04f, 0.04f, 0.12f), eagleDark);
            AddPart(root, "ClawR2",    new Vector3( 0.10f, 0.14f, 0.52f), new Vector3(40f, 0f, 0f), new Vector3(0.04f, 0.04f, 0.12f), eagleDark);
            // ── Lion hind legs ──
            AddPart(root, "HindLegL", new Vector3(-0.20f, 0.58f, -0.70f), Vector3.zero, new Vector3(0.14f, 0.55f, 0.16f), lionTawny);
            AddPart(root, "HindPawL", new Vector3(-0.20f, 0.22f, -0.70f), Vector3.zero, new Vector3(0.18f, 0.12f, 0.22f), lionDark);
            AddPart(root, "HindLegR", new Vector3( 0.20f, 0.58f, -0.70f), Vector3.zero, new Vector3(0.14f, 0.55f, 0.16f), lionTawny);
            AddPart(root, "HindPawR", new Vector3( 0.20f, 0.22f, -0.70f), Vector3.zero, new Vector3(0.18f, 0.12f, 0.22f), lionDark);
            // ── Tufted tail ──
            AddPart(root, "Tail",     new Vector3(0f, 1.0f, -1.10f), new Vector3(18f, 0f, 0f), new Vector3(0.08f, 0.08f, 0.32f), lionTawny);
            AddPart(root, "TailTuft", new Vector3(0f, 1.10f, -1.38f), Vector3.zero,           new Vector3(0.12f, 0.12f, 0.12f), lionDark);

            var cap = root.AddComponent<CapsuleCollider>();
            cap.height = 1.5f; cap.radius = 0.45f; cap.center = new Vector3(0f, 1.0f, 0f);
            var rb = root.AddComponent<Rigidbody>();
            rb.useGravity = false; rb.freezeRotation = true;
            var griffin = root.AddComponent<VoxelEngine.Combat.EnemyGriffin>();
            griffin.griffinHeart = heart;
            griffin.drops = new VoxelEngine.Items.ItemDefinition[] { feather, talon };
            griffin.minDrops = 1; griffin.maxDrops = 3; griffin.dropCount = 1;
            var hbar = root.AddComponent<VoxelEngine.Combat.CreatureHealthBar>();
            hbar.target = griffin;
            hbar.fillColor = new Color(0.90f, 0.70f, 0.20f);
            hbar.fillColorLow = new Color(0.80f, 0.30f, 0.20f);

            const string griffinPath = "Assets/Resources/Enemies/Griffin.prefab";
            GameObject griffinPrefab;
            if (AssetDatabase.LoadMainAssetAtPath(griffinPath) != null)
            {
                griffinPrefab = AssetDatabase.LoadAssetAtPath<GameObject>(griffinPath);
                UnityEngine.Object.DestroyImmediate(root);
            }
            else
            {
                griffinPrefab = PrefabUtility.SaveAsPrefabAsset(root, griffinPath);
                UnityEngine.Object.DestroyImmediate(root);
            }

            // Inject into mountains/open-plains biome scatter (reliable spawn path; same as the Ghoul).
            var br = AssetDatabase.LoadAssetAtPath<VoxelEngine.Biomes.BiomeRegistry>(ASSET_ROOT + "/BiomeRegistry.asset");
            if (br != null && griffinPrefab != null)
            {
                foreach (var biome in br.biomes)
                {
                    if (biome == null) continue;
                    if (biome.biomeName != "Mountains" && biome.biomeName != "Steppes") continue;
                    var list = (biome.scatter != null)
                        ? new System.Collections.Generic.List<VoxelEngine.Biomes.BiomeDefinition.ScatterEntry>(biome.scatter)
                        : new System.Collections.Generic.List<VoxelEngine.Biomes.BiomeDefinition.ScatterEntry>();
                    list.RemoveAll(e => e.prefab != null && e.prefab.name == "Griffin");
                    list.Add(new VoxelEngine.Biomes.BiomeDefinition.ScatterEntry { prefab = griffinPrefab, density = 0.0025f, minScale = 0.95f, maxScale = 1.15f, minHeight = 0, maxHeight = 9999 });
                    biome.scatter = list.ToArray();
                    EditorUtility.SetDirty(biome);
                }
                EditorUtility.SetDirty(br);
            }

            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();
            EditorUtility.DisplayDialog("Voxel Engine — Mythical Enemy: Griffin (Phase 3f)",
                "The Griffin is built:\n\n" +
                "• Heraldic lion-eagle: eagle head + beak, spread wings, taloned forelegs, lion hindquarters (~30 parts)\n" +
                "• FLIES — circles overhead then dive-bombs with its talons\n" +
                "• Drops Griffin Feathers + Talons; rare Griffin Heart (~20%)\n\n" +
                "Spawns rarely in Mountains/Steppes (biome scatter). Saved to Resources/Enemies.",
                "OK");
        }

        // ============================================================
        //   STEP 29 - MYTHICAL ENEMY: KARKADANN (Combat Phase 3g). A
        //   massive armored horned brute that telegraphs then CHARGES
        //   in a straight line (trample + knockback). Heavy frontal
        //   armor — flank/rear it for full damage. Radial-aligned;
        //   detaches from the chunk on Awake. Non-destructive.
        //   Re-runnable. Idempotent.
        // ============================================================
        private void BuildKarkadannContent()
        {
            EnsureFolder("Assets/Resources");
            EnsureFolder("Assets/Resources/Enemies");
            const string FAUNA_ROOT  = ASSET_ROOT + "/Fauna";
            const string FAUNA_ITEMS = FAUNA_ROOT + "/Items";
            const string FAUNA_MATS  = FAUNA_ROOT + "/Materials";
            EnsureFolder(FAUNA_ROOT);
            EnsureFolder(FAUNA_ITEMS);
            EnsureFolder(FAUNA_MATS);

            // ── Drop items ──
            var hornFragment = GetOrCreateAsset<VoxelEngine.Items.ItemDefinition>($"{FAUNA_ITEMS}/Item_KarkadannHorn.asset");
            hornFragment.itemId = "item_karkadann_horn"; hornFragment.displayName = "Karkadann Horn Fragment";
            hornFragment.description = "A shard of a Karkadann's great horn. A high-impact armor and heavy-machinery material.";
            hornFragment.iconTint = new Color(0.88f, 0.82f, 0.66f); hornFragment.maxStack = 20; hornFragment.massPerUnit = 1.0f; hornFragment.category = "Resources";
            EditorUtility.SetDirty(hornFragment);

            var platedHide = GetOrCreateAsset<VoxelEngine.Items.ItemDefinition>($"{FAUNA_ITEMS}/Item_PlatedHide.asset");
            platedHide.itemId = "item_plated_hide"; platedHide.displayName = "Plated Hide";
            platedHide.description = "Thick armored plates from a Karkadann. The toughest armor and machinery material.";
            platedHide.iconTint = new Color(0.42f, 0.40f, 0.38f); platedHide.maxStack = 30; platedHide.massPerUnit = 1.2f; platedHide.category = "Resources";
            EditorUtility.SetDirty(platedHide);

            // ── Materials ──
            var hideGrey  = MakeColoredMat(FAUNA_MATS, "Mat_KarkadannHide",  new Color(0.46f, 0.43f, 0.40f));
            var hideDark  = MakeColoredMat(FAUNA_MATS, "Mat_KarkadannDark",  new Color(0.26f, 0.24f, 0.22f));
            var plateDark = MakeColoredMat(FAUNA_MATS, "Mat_KarkadannPlate", new Color(0.20f, 0.18f, 0.17f));
            var ivory     = MakeColoredMat(FAUNA_MATS, "Mat_KarkadannHorn",  new Color(0.88f, 0.82f, 0.66f));
            var hoofDark  = MakeColoredMat(FAUNA_MATS, "Mat_KarkadannHoof",  new Color(0.12f, 0.11f, 0.10f));
            var eyeRed    = MakeColoredMat(FAUNA_MATS, "Mat_KarkadannEye",   new Color(0.85f, 0.18f, 0.14f));

            void AddPart(GameObject root, string n, Vector3 pos, Vector3 euler, Vector3 scale, Material m)
            {
                var go = GameObject.CreatePrimitive(PrimitiveType.Cube);
                go.name = n; go.transform.SetParent(root.transform, false);
                go.transform.localPosition = pos; go.transform.localEulerAngles = euler; go.transform.localScale = scale;
                go.GetComponent<Renderer>().sharedMaterial = m;
                var col = go.GetComponent<Collider>(); if (col != null) UnityEngine.Object.DestroyImmediate(col);
            }

            var root = new GameObject("Karkadann");
            // ── Big bulky body ──
            AddPart(root, "Body",  new Vector3(0f, 1.15f, 0f),    Vector3.zero, new Vector3(0.95f, 1.0f, 2.0f),  hideGrey);
            AddPart(root, "Chest", new Vector3(0f, 1.10f, 0.85f), Vector3.zero, new Vector3(1.00f, 1.0f, 0.6f),  hideGrey);
            AddPart(root, "Rump",  new Vector3(0f, 1.20f, -0.9f), Vector3.zero, new Vector3(1.00f, 0.95f, 0.6f), hideGrey);
            AddPart(root, "Belly", new Vector3(0f, 0.70f, 0f),    Vector3.zero, new Vector3(0.80f, 0.40f, 1.6f), hideDark);
            AddPart(root, "Hump",  new Vector3(0f, 1.70f, 0.5f),  Vector3.zero, new Vector3(0.90f, 0.50f, 0.7f), hideDark);
            // ── Spinal armor plates ──
            AddPart(root, "Plate1", new Vector3(0f, 1.75f, 0.10f),  Vector3.zero, new Vector3(0.70f, 0.22f, 0.5f), plateDark);
            AddPart(root, "Plate2", new Vector3(0f, 1.70f, -0.30f), Vector3.zero, new Vector3(0.70f, 0.22f, 0.5f), plateDark);
            AddPart(root, "Plate3", new Vector3(0f, 1.62f, -0.65f), Vector3.zero, new Vector3(0.65f, 0.22f, 0.45f),plateDark);
            // ── Head + great horn ──
            AddPart(root, "Head",   new Vector3(0f, 1.20f, 1.2f),  new Vector3(-10f, 0f, 0f), new Vector3(0.70f, 0.70f, 0.70f), hideGrey);
            AddPart(root, "Snout",  new Vector3(0f, 1.05f, 1.55f), new Vector3(-10f, 0f, 0f), new Vector3(0.50f, 0.40f, 0.40f), hideGrey);
            AddPart(root, "Horn",   new Vector3(0f, 1.62f, 1.30f), new Vector3(-25f, 0f, 0f), new Vector3(0.18f, 0.55f, 0.18f), ivory);
            AddPart(root, "HornTip",new Vector3(0f, 1.92f, 1.45f), new Vector3(-25f, 0f, 0f), new Vector3(0.12f, 0.28f, 0.12f), ivory);
            AddPart(root, "SideHornL", new Vector3(-0.26f, 1.50f, 1.25f), new Vector3(-10f, 0f, -22f), new Vector3(0.10f, 0.32f, 0.10f), ivory);
            AddPart(root, "SideHornR", new Vector3( 0.26f, 1.50f, 1.25f), new Vector3(-10f, 0f,  22f), new Vector3(0.10f, 0.32f, 0.10f), ivory);
            AddPart(root, "EarL", new Vector3(-0.36f, 1.46f, 1.10f), Vector3.zero, new Vector3(0.12f, 0.08f, 0.20f), hideGrey);
            AddPart(root, "EarR", new Vector3( 0.36f, 1.46f, 1.10f), Vector3.zero, new Vector3(0.12f, 0.08f, 0.20f), hideGrey);
            AddPart(root, "EyeL", new Vector3(-0.23f, 1.30f, 1.42f), Vector3.zero, new Vector3(0.06f, 0.06f, 0.04f), eyeRed);
            AddPart(root, "EyeR", new Vector3( 0.23f, 1.30f, 1.42f), Vector3.zero, new Vector3(0.06f, 0.06f, 0.04f), eyeRed);
            // ── Thick legs + hooves ──
            AddPart(root, "LegFL", new Vector3(-0.35f, 0.55f,  0.7f), Vector3.zero, new Vector3(0.28f, 1.1f, 0.32f), hideGrey);
            AddPart(root, "LegFR", new Vector3( 0.35f, 0.55f,  0.7f), Vector3.zero, new Vector3(0.28f, 1.1f, 0.32f), hideGrey);
            AddPart(root, "LegBL", new Vector3(-0.35f, 0.55f, -0.7f), Vector3.zero, new Vector3(0.28f, 1.1f, 0.32f), hideGrey);
            AddPart(root, "LegBR", new Vector3( 0.35f, 0.55f, -0.7f), Vector3.zero, new Vector3(0.28f, 1.1f, 0.32f), hideGrey);
            AddPart(root, "HoofFL", new Vector3(-0.35f, 0.06f,  0.7f), Vector3.zero, new Vector3(0.32f, 0.14f, 0.36f), hoofDark);
            AddPart(root, "HoofFR", new Vector3( 0.35f, 0.06f,  0.7f), Vector3.zero, new Vector3(0.32f, 0.14f, 0.36f), hoofDark);
            AddPart(root, "HoofBL", new Vector3(-0.35f, 0.06f, -0.7f), Vector3.zero, new Vector3(0.32f, 0.14f, 0.36f), hoofDark);
            AddPart(root, "HoofBR", new Vector3( 0.35f, 0.06f, -0.7f), Vector3.zero, new Vector3(0.32f, 0.14f, 0.36f), hoofDark);
            // ── Tail ──
            AddPart(root, "Tail",     new Vector3(0f, 1.10f, -1.25f), new Vector3(20f, 0f, 0f), new Vector3(0.12f, 0.12f, 0.4f),  hideGrey);
            AddPart(root, "TailTuft", new Vector3(0f, 1.0f, -1.55f),  Vector3.zero,            new Vector3(0.16f, 0.16f, 0.16f), hideDark);

            var cap = root.AddComponent<CapsuleCollider>();
            cap.height = 1.9f; cap.radius = 0.7f; cap.center = new Vector3(0f, 1.1f, 0f);
            var rb = root.AddComponent<Rigidbody>();
            rb.useGravity = false; rb.freezeRotation = true;
            var kark = root.AddComponent<VoxelEngine.Combat.EnemyKarkadann>();
            kark.drops = new VoxelEngine.Items.ItemDefinition[] { hornFragment, platedHide };
            kark.minDrops = 1; kark.maxDrops = 3; kark.dropCount = 1;
            var hbar = root.AddComponent<VoxelEngine.Combat.CreatureHealthBar>();
            hbar.target = kark;
            hbar.fillColor = new Color(0.60f, 0.52f, 0.46f);
            hbar.fillColorLow = new Color(0.80f, 0.20f, 0.15f);

            const string path = "Assets/Resources/Enemies/Karkadann.prefab";
            GameObject prefab;
            if (AssetDatabase.LoadMainAssetAtPath(path) != null)
            {
                prefab = AssetDatabase.LoadAssetAtPath<GameObject>(path);
                UnityEngine.Object.DestroyImmediate(root);
            }
            else
            {
                prefab = PrefabUtility.SaveAsPrefabAsset(root, path);
                UnityEngine.Object.DestroyImmediate(root);
            }

            // Inject into open-ground biome scatter (reliable spawn path; same as the Ghoul).
            var br = AssetDatabase.LoadAssetAtPath<VoxelEngine.Biomes.BiomeRegistry>(ASSET_ROOT + "/BiomeRegistry.asset");
            if (br != null && prefab != null)
            {
                foreach (var biome in br.biomes)
                {
                    if (biome == null) continue;
                    if (biome.biomeName != "Steppes" && biome.biomeName != "Desert") continue;
                    var list = (biome.scatter != null)
                        ? new System.Collections.Generic.List<VoxelEngine.Biomes.BiomeDefinition.ScatterEntry>(biome.scatter)
                        : new System.Collections.Generic.List<VoxelEngine.Biomes.BiomeDefinition.ScatterEntry>();
                    list.RemoveAll(e => e.prefab != null && e.prefab.name == "Karkadann");
                    list.Add(new VoxelEngine.Biomes.BiomeDefinition.ScatterEntry { prefab = prefab, density = 0.002f, minScale = 0.95f, maxScale = 1.15f, minHeight = 0, maxHeight = 9999 });
                    biome.scatter = list.ToArray();
                    EditorUtility.SetDirty(biome);
                }
                EditorUtility.SetDirty(br);
            }

            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();
            EditorUtility.DisplayDialog("Voxel Engine — Mythical Enemy: Karkadann (Phase 3g)",
                "The Karkadann is built:\n\n" +
                "• Massive armored brute: bulky body, spinal plates, great horn + side horns (~30 parts)\n" +
                "• Telegraphs (paws the ground) then CHARGES in a straight line — dodge it or get trampled + knocked back\n" +
                "• Heavy FRONTAL ARMOR (60% reduced from the front); flank/rear it, or hit it while it recovers from a missed charge\n" +
                "• Drops Karkadann Horn Fragment + Plated Hide\n\n" +
                "Spawns rarely in Steppes/Desert (biome scatter). Saved to Resources/Enemies.",
                "OK");
        }

        // ============================================================
        //   STEP 30 - MYTHICAL ENEMY: IFRIIT DJINN (Combat Phase 3h).
        //   A high-tier fire spirit caster. Kites, hurls fireballs,
        //   teleport-blinks around you, and raises fire walls (AoE);
        //   ignites an armor-escalating burn. Radial-aligned; detaches
        //   from the chunk on Awake. Non-destructive. Re-runnable.
        // ============================================================
        private void BuildIfritContent()
        {
            EnsureFolder("Assets/Resources");
            EnsureFolder("Assets/Resources/Enemies");
            const string FAUNA_ROOT  = ASSET_ROOT + "/Fauna";
            const string FAUNA_ITEMS = FAUNA_ROOT + "/Items";
            const string FAUNA_MATS  = FAUNA_ROOT + "/Materials";
            EnsureFolder(FAUNA_ROOT);
            EnsureFolder(FAUNA_ITEMS);
            EnsureFolder(FAUNA_MATS);

            // ── Drop items ──
            var ember = GetOrCreateAsset<VoxelEngine.Items.ItemDefinition>($"{FAUNA_ITEMS}/Item_IfritEmber.asset");
            ember.itemId = "item_ifrit_ember"; ember.displayName = "Ifrit Ember";
            ember.description = "A still-burning ember from a slain Ifrit. Required for advanced thermal, fusion, and stellar research.";
            ember.iconTint = new Color(1.0f, 0.45f, 0.10f); ember.maxStack = 10; ember.massPerUnit = 0.4f; ember.category = "Resources";
            EditorUtility.SetDirty(ember);

            var ash = GetOrCreateAsset<VoxelEngine.Items.ItemDefinition>($"{FAUNA_ITEMS}/Item_Ash.asset");
            ash.itemId = "item_ash"; ash.displayName = "Ash";
            ash.description = "Cold ash left by fire creatures. A basic alchemy and absorbent material.";
            ash.iconTint = new Color(0.30f, 0.28f, 0.27f); ash.maxStack = 60; ash.massPerUnit = 0.1f; ash.category = "Resources";
            EditorUtility.SetDirty(ash);

            // ── Materials ──
            var emberCore   = MakeColoredMat(FAUNA_MATS, "Mat_IfritCore",   new Color(0.90f, 0.35f, 0.10f));
            var emberBright = MakeColoredMat(FAUNA_MATS, "Mat_IfritBright", new Color(1.00f, 0.75f, 0.15f));
            var smokeDark   = MakeColoredMat(FAUNA_MATS, "Mat_IfritSmoke",  new Color(0.18f, 0.14f, 0.16f));
            var hornDark    = MakeColoredMat(FAUNA_MATS, "Mat_IfritHorn",   new Color(0.25f, 0.20f, 0.18f));
            var eyeGlow     = MakeColoredMat(FAUNA_MATS, "Mat_IfritEye",    new Color(1.00f, 0.95f, 0.60f));
            var fireballMat = MakeColoredMat(FAUNA_MATS, "Mat_IfritFireball",new Color(1.00f, 0.50f, 0.10f));
            var firewallMat = MakeColoredMat(FAUNA_MATS, "Mat_IfritFirewall",new Color(0.95f, 0.35f, 0.10f));

            void AddPart(GameObject root, string n, Vector3 pos, Vector3 euler, Vector3 scale, Material m)
            {
                var go = GameObject.CreatePrimitive(PrimitiveType.Cube);
                go.name = n; go.transform.SetParent(root.transform, false);
                go.transform.localPosition = pos; go.transform.localEulerAngles = euler; go.transform.localScale = scale;
                go.GetComponent<Renderer>().sharedMaterial = m;
                var col = go.GetComponent<Collider>(); if (col != null) UnityEngine.Object.DestroyImmediate(col);
            }

            var root = new GameObject("Ifrit");
            // ── Body: ember core + wispy base (no legs) ──
            AddPart(root, "Core",    new Vector3(0f, 1.0f, 0f),    Vector3.zero, new Vector3(0.50f, 1.0f, 0.50f), emberCore);
            AddPart(root, "Wisps",   new Vector3(0f, 0.4f, 0f),    Vector3.zero, new Vector3(0.35f, 0.6f, 0.35f), smokeDark);
            AddPart(root, "ChestGlow",new Vector3(0f, 1.1f, 0.05f),Vector3.zero, new Vector3(0.45f, 0.5f, 0.40f), emberBright);
            AddPart(root, "SmokeL",  new Vector3(-0.30f, 0.5f, 0f), Vector3.zero, new Vector3(0.12f, 0.5f, 0.12f), smokeDark);
            AddPart(root, "SmokeR",  new Vector3( 0.30f, 0.5f, 0f), Vector3.zero, new Vector3(0.12f, 0.5f, 0.12f), smokeDark);
            // ── Shoulders + flame arms ──
            AddPart(root, "ShldrL", new Vector3(-0.30f, 1.35f, 0f), Vector3.zero, new Vector3(0.22f, 0.22f, 0.22f), emberCore);
            AddPart(root, "ShldrR", new Vector3( 0.30f, 1.35f, 0f), Vector3.zero, new Vector3(0.22f, 0.22f, 0.22f), emberCore);
            AddPart(root, "ArmL",   new Vector3(-0.42f, 1.0f, 0.05f),Vector3.zero,new Vector3(0.14f, 0.5f, 0.14f),  emberBright);
            AddPart(root, "HandL",  new Vector3(-0.46f, 0.7f, 0.1f), Vector3.zero,new Vector3(0.16f, 0.16f, 0.16f), emberCore);
            AddPart(root, "ArmR",   new Vector3( 0.42f, 1.0f, 0.05f),Vector3.zero,new Vector3(0.14f, 0.5f, 0.14f),  emberBright);
            AddPart(root, "HandR",  new Vector3( 0.46f, 0.7f, 0.1f), Vector3.zero,new Vector3(0.16f, 0.16f, 0.16f), emberCore);
            // ── Neck + head + glowing face ──
            AddPart(root, "Neck",     new Vector3(0f, 1.55f, 0.05f), Vector3.zero, new Vector3(0.22f, 0.25f, 0.22f), emberCore);
            AddPart(root, "Head",     new Vector3(0f, 1.75f, 0.08f), Vector3.zero, new Vector3(0.32f, 0.36f, 0.32f), emberCore);
            AddPart(root, "FaceGlow", new Vector3(0f, 1.76f, 0.22f), Vector3.zero, new Vector3(0.24f, 0.28f, 0.06f), emberBright);
            AddPart(root, "EyeL", new Vector3(-0.09f, 1.81f, 0.23f), Vector3.zero, new Vector3(0.05f, 0.05f, 0.03f), eyeGlow);
            AddPart(root, "EyeR", new Vector3( 0.09f, 1.81f, 0.23f), Vector3.zero, new Vector3(0.05f, 0.05f, 0.03f), eyeGlow);
            // ── Swept-back horns + flame crest ──
            AddPart(root, "HornL",   new Vector3(-0.12f, 2.0f, 0.02f),  new Vector3(20f, 0f, -25f), new Vector3(0.08f, 0.28f, 0.08f), hornDark);
            AddPart(root, "HornR",   new Vector3( 0.12f, 2.0f, 0.02f),  new Vector3(20f, 0f,  25f), new Vector3(0.08f, 0.28f, 0.08f), hornDark);
            AddPart(root, "Crest1",  new Vector3(0f, 2.05f, 0.0f),  new Vector3(-15f, 0f, 0f), new Vector3(0.10f, 0.32f, 0.10f), emberBright);
            AddPart(root, "Crest2",  new Vector3(-0.08f, 2.0f, -0.05f),new Vector3(-25f, 0f, -10f),new Vector3(0.08f, 0.26f, 0.08f), emberBright);
            AddPart(root, "Crest3",  new Vector3( 0.08f, 2.0f, -0.05f),new Vector3(-25f, 0f,  10f),new Vector3(0.08f, 0.26f, 0.08f), emberBright);

            var cap = root.AddComponent<CapsuleCollider>();
            cap.height = 1.7f; cap.radius = 0.4f; cap.center = new Vector3(0f, 1.0f, 0f);
            var rb = root.AddComponent<Rigidbody>();
            rb.useGravity = false; rb.freezeRotation = true;
            var ifrit = root.AddComponent<VoxelEngine.Combat.EnemyIfrit>();
            ifrit.fireballMaterial = fireballMat;
            ifrit.firewallMaterial = firewallMat;
            ifrit.drops = new VoxelEngine.Items.ItemDefinition[] { ember, ash };
            ifrit.minDrops = 1; ifrit.maxDrops = 2; ifrit.dropCount = 1;
            var hbar = root.AddComponent<VoxelEngine.Combat.CreatureHealthBar>();
            hbar.target = ifrit;
            hbar.fillColor = new Color(0.95f, 0.40f, 0.10f);
            hbar.fillColorLow = new Color(0.60f, 0.10f, 0.10f);

            const string path = "Assets/Resources/Enemies/Ifrit.prefab";
            GameObject prefab;
            if (AssetDatabase.LoadMainAssetAtPath(path) != null)
            {
                prefab = AssetDatabase.LoadAssetAtPath<GameObject>(path);
                UnityEngine.Object.DestroyImmediate(root);
            }
            else
            {
                prefab = PrefabUtility.SaveAsPrefabAsset(root, path);
                UnityEngine.Object.DestroyImmediate(root);
            }

            // Inject into hot biome scatter (reliable spawn path; same as the Ghoul).
            var br = AssetDatabase.LoadAssetAtPath<VoxelEngine.Biomes.BiomeRegistry>(ASSET_ROOT + "/BiomeRegistry.asset");
            if (br != null && prefab != null)
            {
                foreach (var biome in br.biomes)
                {
                    if (biome == null) continue;
                    if (biome.biomeName != "Desert" && biome.biomeName != "Wasteland") continue;
                    var list = (biome.scatter != null)
                        ? new System.Collections.Generic.List<VoxelEngine.Biomes.BiomeDefinition.ScatterEntry>(biome.scatter)
                        : new System.Collections.Generic.List<VoxelEngine.Biomes.BiomeDefinition.ScatterEntry>();
                    list.RemoveAll(e => e.prefab != null && e.prefab.name == "Ifrit");
                    list.Add(new VoxelEngine.Biomes.BiomeDefinition.ScatterEntry { prefab = prefab, density = 0.002f, minScale = 0.95f, maxScale = 1.15f, minHeight = 0, maxHeight = 9999 });
                    biome.scatter = list.ToArray();
                    EditorUtility.SetDirty(biome);
                }
                EditorUtility.SetDirty(br);
            }

            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();
            EditorUtility.DisplayDialog("Voxel Engine — Mythical Enemy: Ifrit Djinn (Phase 3h)",
                "The Ifrit Djinn is built:\n\n" +
                "• Fire spirit: ember body, wispy base, flame arms, horned head with a flame crest (~24 parts)\n" +
                "• Kites, hurls fireballs, teleport-blinks around you, and raises fire walls (AoE)\n" +
                "• Ignites an armor-escalating BURN (heavier armor burns hotter)\n" +
                "• Drops Ifrit Ember + Ash\n\n" +
                "Spawns rarely in Desert/Wasteland (biome scatter). Saved to Resources/Enemies.",
                "OK");
        }

        // ============================================================
        //   STEP 31 - MYTHICAL MINI-BOSS: ROC (Combat Phase 3i). A
        //   colossal bird of prey. Circles, dive-bombs with massive
        //   talons, beats its wings for an AoE gust, and ENRAGES
        //   below 50% HP. Guaranteed boss loot (Giant Pinions + Roc
        //   Storm Core). Very rare. Non-destructive. Re-runnable.
        // ============================================================
        private void BuildRocContent()
        {
            EnsureFolder("Assets/Resources");
            EnsureFolder("Assets/Resources/Enemies");
            const string FAUNA_ROOT  = ASSET_ROOT + "/Fauna";
            const string FAUNA_ITEMS = FAUNA_ROOT + "/Items";
            const string FAUNA_MATS  = FAUNA_ROOT + "/Materials";
            EnsureFolder(FAUNA_ROOT);
            EnsureFolder(FAUNA_ITEMS);
            EnsureFolder(FAUNA_MATS);

            // ── Drop items ──
            var pinion = GetOrCreateAsset<VoxelEngine.Items.ItemDefinition>($"{FAUNA_ITEMS}/Item_GiantPinion.asset");
            pinion.itemId = "item_giant_pinion"; pinion.displayName = "Giant Pinion";
            pinion.description = "A colossal flight feather from a Roc. A premium material for advanced flight and weather-control equipment.";
            pinion.iconTint = new Color(0.42f, 0.32f, 0.22f); pinion.maxStack = 20; pinion.massPerUnit = 0.8f; pinion.category = "Resources";
            EditorUtility.SetDirty(pinion);

            var stormCore = GetOrCreateAsset<VoxelEngine.Items.ItemDefinition>($"{FAUNA_ITEMS}/Item_RocStormCore.asset");
            stormCore.itemId = "item_roc_storm_core"; stormCore.displayName = "Roc Storm Core";
            stormCore.description = "A crackling core of wind and sand harvested from a slain Roc. Required by advanced flight and weather-control research.";
            stormCore.iconTint = new Color(0.65f, 0.75f, 0.85f); stormCore.maxStack = 5; stormCore.massPerUnit = 1.5f; stormCore.category = "Resources";
            EditorUtility.SetDirty(stormCore);

            // ── Materials ──
            var bodyDark   = MakeColoredMat(FAUNA_MATS, "Mat_RocBody",   new Color(0.32f, 0.24f, 0.18f));
            var featherDark= MakeColoredMat(FAUNA_MATS, "Mat_RocDark",   new Color(0.26f, 0.20f, 0.15f));
            var featherMid = MakeColoredMat(FAUNA_MATS, "Mat_RocFeather",new Color(0.40f, 0.30f, 0.22f));
            var beakGold   = MakeColoredMat(FAUNA_MATS, "Mat_RocBeak",   new Color(0.80f, 0.65f, 0.20f));
            var eyeGold    = MakeColoredMat(FAUNA_MATS, "Mat_RocEye",    new Color(0.95f, 0.80f, 0.20f));
            var dustMat    = MakeColoredMat(FAUNA_MATS, "Mat_RocDust",   new Color(0.70f, 0.60f, 0.45f));

            void AddPart(GameObject root, string n, Vector3 pos, Vector3 euler, Vector3 scale, Material m)
            {
                var go = GameObject.CreatePrimitive(PrimitiveType.Cube);
                go.name = n; go.transform.SetParent(root.transform, false);
                go.transform.localPosition = pos; go.transform.localEulerAngles = euler; go.transform.localScale = scale;
                go.GetComponent<Renderer>().sharedMaterial = m;
                var col = go.GetComponent<Collider>(); if (col != null) UnityEngine.Object.DestroyImmediate(col);
            }

            var root = new GameObject("Roc");
            // ── Body + chest + tail fan ──
            AddPart(root, "Body",  new Vector3(0f, 1.6f, 0f),    Vector3.zero,           new Vector3(0.7f, 0.8f, 1.2f),  bodyDark);
            AddPart(root, "Chest", new Vector3(0f, 1.5f, 0.5f),   Vector3.zero,           new Vector3(0.7f, 0.7f, 0.5f),  bodyDark);
            AddPart(root, "Tail",  new Vector3(0f, 1.7f, -0.8f),  new Vector3(10f, 0f, 0f),new Vector3(0.10f, 0.5f, 0.8f), featherDark);
            // ── Head + hooked beak + crest ──
            AddPart(root, "Head",      new Vector3(0f, 2.1f, 0.85f), new Vector3(-10f, 0f, 0f), new Vector3(0.40f, 0.40f, 0.45f), bodyDark);
            AddPart(root, "BeakUpper", new Vector3(0f, 2.05f, 1.15f),new Vector3(-10f, 0f, 0f), new Vector3(0.12f, 0.14f, 0.30f), beakGold);
            AddPart(root, "BeakLower", new Vector3(0f, 1.98f, 1.10f),Vector3.zero,             new Vector3(0.10f, 0.06f, 0.18f), beakGold);
            AddPart(root, "Crest",     new Vector3(0f, 2.32f, 0.78f),new Vector3(-25f, 0f, 0f), new Vector3(0.08f, 0.22f, 0.12f), featherDark);
            AddPart(root, "EyeL", new Vector3(-0.14f, 2.18f, 0.98f), Vector3.zero, new Vector3(0.06f, 0.06f, 0.04f), eyeGold);
            AddPart(root, "EyeR", new Vector3( 0.14f, 2.18f, 0.98f), Vector3.zero, new Vector3(0.06f, 0.06f, 0.04f), eyeGold);
            // ── Colossal spread wings ──
            AddPart(root, "WingLBase", new Vector3(-0.8f, 1.80f, 0.10f), new Vector3(0f, 0f, 20f),  new Vector3(0.12f, 0.7f, 1.6f),  featherDark);
            AddPart(root, "WingLMid",  new Vector3(-1.5f, 1.95f, 0.0f),  new Vector3(0f, 0f, 30f),  new Vector3(0.10f, 0.5f, 1.2f),  featherMid);
            AddPart(root, "WingLTip",  new Vector3(-2.2f, 2.10f, -0.1f), new Vector3(0f, 0f, 40f),  new Vector3(0.08f, 0.35f, 0.8f), featherMid);
            AddPart(root, "WingRBase", new Vector3( 0.8f, 1.80f, 0.10f), new Vector3(0f, 0f, -20f), new Vector3(0.12f, 0.7f, 1.6f),  featherDark);
            AddPart(root, "WingRMid",  new Vector3( 1.5f, 1.95f, 0.0f),  new Vector3(0f, 0f, -30f), new Vector3(0.10f, 0.5f, 1.2f),  featherMid);
            AddPart(root, "WingRTip",  new Vector3( 2.2f, 2.10f, -0.1f), new Vector3(0f, 0f, -40f), new Vector3(0.08f, 0.35f, 0.8f), featherMid);
            // ── Massive talons (forelegs) ──
            AddPart(root, "TalonLegL", new Vector3(-0.2f, 0.85f, 0.30f), Vector3.zero, new Vector3(0.14f, 0.85f, 0.14f), bodyDark);
            AddPart(root, "TalonFootL",new Vector3(-0.2f, 0.32f, 0.30f), Vector3.zero, new Vector3(0.24f, 0.12f, 0.30f), beakGold);
            AddPart(root, "ClawL1",    new Vector3(-0.28f, 0.22f, 0.46f),new Vector3(40f, 0f, 0f), new Vector3(0.05f, 0.05f, 0.16f), featherDark);
            AddPart(root, "ClawL2",    new Vector3(-0.12f, 0.20f, 0.48f),new Vector3(40f, 0f, 0f), new Vector3(0.05f, 0.05f, 0.16f), featherDark);
            AddPart(root, "TalonLegR", new Vector3( 0.2f, 0.85f, 0.30f), Vector3.zero, new Vector3(0.14f, 0.85f, 0.14f), bodyDark);
            AddPart(root, "TalonFootR",new Vector3( 0.2f, 0.32f, 0.30f), Vector3.zero, new Vector3(0.24f, 0.12f, 0.30f), beakGold);
            AddPart(root, "ClawR1",    new Vector3( 0.28f, 0.22f, 0.46f),new Vector3(40f, 0f, 0f), new Vector3(0.05f, 0.05f, 0.16f), featherDark);
            AddPart(root, "ClawR2",    new Vector3( 0.12f, 0.20f, 0.48f),new Vector3(40f, 0f, 0f), new Vector3(0.05f, 0.05f, 0.16f), featherDark);

            var cap = root.AddComponent<CapsuleCollider>();
            cap.height = 2.5f; cap.radius = 0.7f; cap.center = new Vector3(0f, 1.5f, 0f);
            var rb = root.AddComponent<Rigidbody>();
            rb.useGravity = false; rb.freezeRotation = true;
            var roc = root.AddComponent<VoxelEngine.Combat.EnemyRoc>();
            roc.dustMaterial = dustMat;
            roc.stormCore = stormCore;
            roc.drops = new VoxelEngine.Items.ItemDefinition[] { pinion };
            roc.minDrops = 2; roc.maxDrops = 4; roc.dropCount = 1;
            var hbar = root.AddComponent<VoxelEngine.Combat.CreatureHealthBar>();
            hbar.target = roc;
            hbar.fillColor = new Color(0.90f, 0.30f, 0.15f);
            hbar.fillColorLow = new Color(0.50f, 0.10f, 0.10f);

            const string path = "Assets/Resources/Enemies/Roc.prefab";
            GameObject prefab;
            if (AssetDatabase.LoadMainAssetAtPath(path) != null)
            {
                prefab = AssetDatabase.LoadAssetAtPath<GameObject>(path);
                UnityEngine.Object.DestroyImmediate(root);
            }
            else
            {
                prefab = PrefabUtility.SaveAsPrefabAsset(root, path);
                UnityEngine.Object.DestroyImmediate(root);
            }

            // Very rare mini-boss spawn (reliable scatter path; same as the Ghoul).
            var br = AssetDatabase.LoadAssetAtPath<VoxelEngine.Biomes.BiomeRegistry>(ASSET_ROOT + "/BiomeRegistry.asset");
            if (br != null && prefab != null)
            {
                foreach (var biome in br.biomes)
                {
                    if (biome == null) continue;
                    if (biome.biomeName != "Mountains" && biome.biomeName != "Steppes") continue;
                    var list = (biome.scatter != null)
                        ? new System.Collections.Generic.List<VoxelEngine.Biomes.BiomeDefinition.ScatterEntry>(biome.scatter)
                        : new System.Collections.Generic.List<VoxelEngine.Biomes.BiomeDefinition.ScatterEntry>();
                    list.RemoveAll(e => e.prefab != null && e.prefab.name == "Roc");
                    list.Add(new VoxelEngine.Biomes.BiomeDefinition.ScatterEntry { prefab = prefab, density = 0.0008f, minScale = 0.95f, maxScale = 1.15f, minHeight = 0, maxHeight = 9999 });
                    biome.scatter = list.ToArray();
                    EditorUtility.SetDirty(biome);
                }
                EditorUtility.SetDirty(br);
            }

            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();
            EditorUtility.DisplayDialog("Voxel Engine — Mythical Mini-Boss: Roc (Phase 3i)",
                "The Roc mini-boss is built:\n\n" +
                "• Colossal bird of prey: huge spread wings, hooked beak, massive talons (~28 parts)\n" +
                "• FLIES — circles overhead, dive-bombs with huge talons, beats wings for an AoE gust (damage + knockback + dust ring)\n" +
                "• ENRAGES below 50% HP (faster, shorter cooldowns); 350 HP\n" +
                "• Drops Giant Pinions + a guaranteed Roc Storm Core\n\n" +
                "Spawns VERY rarely in Mountains/Steppes (biome scatter). Saved to Resources/Enemies.",
                "OK");
        }

        // ============================================================
        //   STEP 32 - MYTHICAL ENEMY: BASILISK (Combat Phase 3j). A
        //   large serpentine beast with a PETRIFYING GAZE (forward cone
        //   that slows you — circle-strafe to break it) and a venomous
        //   bite. Radial-aligned; detaches from the chunk on Awake.
        //   Non-destructive. Re-runnable. Idempotent.
        // ============================================================
        private void BuildBasiliskContent()
        {
            EnsureFolder("Assets/Resources");
            EnsureFolder("Assets/Resources/Enemies");
            const string FAUNA_ROOT  = ASSET_ROOT + "/Fauna";
            const string FAUNA_ITEMS = FAUNA_ROOT + "/Items";
            const string FAUNA_MATS  = FAUNA_ROOT + "/Materials";
            EnsureFolder(FAUNA_ROOT);
            EnsureFolder(FAUNA_ITEMS);
            EnsureFolder(FAUNA_MATS);

            // ── Drop items ──
            var scale = GetOrCreateAsset<VoxelEngine.Items.ItemDefinition>($"{FAUNA_ITEMS}/Item_BasiliskScale.asset");
            scale.itemId = "item_basilisk_scale"; scale.displayName = "Basilisk Scale";
            scale.description = "A shimmering scale from a Basilisk. A resilient material for toxin-resistant armor.";
            scale.iconTint = new Color(0.40f, 0.52f, 0.28f); scale.maxStack = 30; scale.massPerUnit = 0.4f; scale.category = "Resources";
            EditorUtility.SetDirty(scale);

            var eye = GetOrCreateAsset<VoxelEngine.Items.ItemDefinition>($"{FAUNA_ITEMS}/Item_PetrifiedEye.asset");
            eye.itemId = "item_petrified_eye"; eye.displayName = "Petrified Eye";
            eye.description = "A fossilized Basilisk eye that still holds a trace of its gaze. A prized alchemy and relic reagent.";
            eye.iconTint = new Color(0.95f, 0.82f, 0.18f); eye.maxStack = 10; eye.massPerUnit = 0.3f; eye.category = "Resources";
            EditorUtility.SetDirty(eye);

            // ── Materials ──
            var scaleBody = MakeColoredMat(FAUNA_MATS, "Mat_BasiliskBody", new Color(0.40f, 0.50f, 0.28f));
            var bellyDark = MakeColoredMat(FAUNA_MATS, "Mat_BasiliskBelly",new Color(0.28f, 0.32f, 0.20f));
            var crestRed  = MakeColoredMat(FAUNA_MATS, "Mat_BasiliskCrest",new Color(0.80f, 0.20f, 0.18f));
            var eyeGlow   = MakeColoredMat(FAUNA_MATS, "Mat_BasiliskEye",  new Color(1.00f, 0.85f, 0.15f));
            var fangPale  = MakeColoredMat(FAUNA_MATS, "Mat_BasiliskFang", new Color(0.85f, 0.82f, 0.70f));

            void AddPart(GameObject root, string n, Vector3 pos, Vector3 euler, Vector3 scale2, Material m)
            {
                var go = GameObject.CreatePrimitive(PrimitiveType.Cube);
                go.name = n; go.transform.SetParent(root.transform, false);
                go.transform.localPosition = pos; go.transform.localEulerAngles = euler; go.transform.localScale = scale2;
                go.GetComponent<Renderer>().sharedMaterial = m;
                var col = go.GetComponent<Collider>(); if (col != null) UnityEngine.Object.DestroyImmediate(col);
            }

            var root = new GameObject("Basilisk");
            // ── Long sinuous body (segmented, tapering to a tail) ──
            AddPart(root, "Seg1", new Vector3(0f, 0.70f, 0.70f),  Vector3.zero, new Vector3(0.50f, 0.50f, 0.60f), scaleBody);
            AddPart(root, "Seg2", new Vector3(0f, 0.65f, 0.20f),  Vector3.zero, new Vector3(0.50f, 0.50f, 0.60f), scaleBody);
            AddPart(root, "Seg3", new Vector3(0f, 0.60f, -0.30f), Vector3.zero, new Vector3(0.48f, 0.48f, 0.60f), scaleBody);
            AddPart(root, "Seg4", new Vector3(0f, 0.55f, -0.80f), Vector3.zero, new Vector3(0.44f, 0.44f, 0.60f), scaleBody);
            AddPart(root, "Seg5", new Vector3(0f, 0.50f, -1.30f), Vector3.zero, new Vector3(0.38f, 0.38f, 0.55f), scaleBody);
            AddPart(root, "Seg6", new Vector3(0f, 0.46f, -1.75f), Vector3.zero, new Vector3(0.30f, 0.30f, 0.50f), scaleBody);
            AddPart(root, "TailTip", new Vector3(0f, 0.42f, -2.10f), Vector3.zero, new Vector3(0.20f, 0.20f, 0.40f), scaleBody);
            AddPart(root, "Belly", new Vector3(0f, 0.42f, -0.30f), Vector3.zero, new Vector3(0.36f, 0.18f, 2.2f), bellyDark);
            // ── Dorsal crest spikes ──
            AddPart(root, "Crest1", new Vector3(0f, 0.95f, 0.50f), new Vector3(-15f, 0f, 0f), new Vector3(0.06f, 0.22f, 0.10f), crestRed);
            AddPart(root, "Crest2", new Vector3(0f, 0.92f, 0.00f), new Vector3(-15f, 0f, 0f), new Vector3(0.06f, 0.24f, 0.10f), crestRed);
            AddPart(root, "Crest3", new Vector3(0f, 0.88f, -0.50f),new Vector3(-15f, 0f, 0f), new Vector3(0.06f, 0.22f, 0.10f), crestRed);
            AddPart(root, "Crest4", new Vector3(0f, 0.84f, -1.00f),new Vector3(-15f, 0f, 0f), new Vector3(0.06f, 0.20f, 0.10f), crestRed);
            // ── Head + frill + snout + fangs ──
            AddPart(root, "Head",   new Vector3(0f, 0.85f, 1.05f), new Vector3(-6f, 0f, 0f), new Vector3(0.45f, 0.45f, 0.55f), scaleBody);
            AddPart(root, "Frill",  new Vector3(0f, 1.06f, 0.92f), new Vector3(-10f, 0f, 0f),new Vector3(0.52f, 0.34f, 0.08f), crestRed);
            AddPart(root, "Snout",  new Vector3(0f, 0.78f, 1.38f), Vector3.zero,            new Vector3(0.32f, 0.28f, 0.30f), scaleBody);
            AddPart(root, "Jaw",    new Vector3(0f, 0.70f, 1.32f), Vector3.zero,            new Vector3(0.30f, 0.10f, 0.25f), bellyDark);
            AddPart(root, "FangL",  new Vector3(-0.08f, 0.70f, 1.46f), new Vector3(15f, 0f, 0f), new Vector3(0.04f, 0.13f, 0.04f), fangPale);
            AddPart(root, "FangR",  new Vector3( 0.08f, 0.70f, 1.46f), new Vector3(15f, 0f, 0f), new Vector3(0.04f, 0.13f, 0.04f), fangPale);
            AddPart(root, "EyeL",   new Vector3(-0.17f, 0.93f, 1.16f), Vector3.zero, new Vector3(0.07f, 0.07f, 0.04f), eyeGlow);
            AddPart(root, "EyeR",   new Vector3( 0.17f, 0.93f, 1.16f), Vector3.zero, new Vector3(0.07f, 0.07f, 0.04f), eyeGlow);
            // ── Four small clawed legs ──
            AddPart(root, "LegFL", new Vector3(-0.28f, 0.30f, 0.55f), Vector3.zero, new Vector3(0.10f, 0.55f, 0.12f), scaleBody);
            AddPart(root, "PawFL", new Vector3(-0.28f, 0.06f, 0.55f), Vector3.zero, new Vector3(0.14f, 0.10f, 0.16f), bellyDark);
            AddPart(root, "LegFR", new Vector3( 0.28f, 0.30f, 0.55f), Vector3.zero, new Vector3(0.10f, 0.55f, 0.12f), scaleBody);
            AddPart(root, "PawFR", new Vector3( 0.28f, 0.06f, 0.55f), Vector3.zero, new Vector3(0.14f, 0.10f, 0.16f), bellyDark);
            AddPart(root, "LegBL", new Vector3(-0.26f, 0.30f, -0.55f),Vector3.zero, new Vector3(0.10f, 0.55f, 0.12f), scaleBody);
            AddPart(root, "PawBL", new Vector3(-0.26f, 0.06f, -0.55f),Vector3.zero, new Vector3(0.14f, 0.10f, 0.16f), bellyDark);
            AddPart(root, "LegBR", new Vector3( 0.26f, 0.30f, -0.55f),Vector3.zero, new Vector3(0.10f, 0.55f, 0.12f), scaleBody);
            AddPart(root, "PawBR", new Vector3( 0.26f, 0.06f, -0.55f),Vector3.zero, new Vector3(0.14f, 0.10f, 0.16f), bellyDark);

            var cap = root.AddComponent<CapsuleCollider>();
            cap.height = 2.4f; cap.radius = 0.45f; cap.center = new Vector3(0f, 0.6f, -0.3f);
            var rb = root.AddComponent<Rigidbody>();
            rb.useGravity = false; rb.freezeRotation = true;
            var basilisk = root.AddComponent<VoxelEngine.Combat.EnemyBasilisk>();
            basilisk.drops = new VoxelEngine.Items.ItemDefinition[] { scale, eye };
            basilisk.minDrops = 1; basilisk.maxDrops = 2; basilisk.dropCount = 1;
            var hbar = root.AddComponent<VoxelEngine.Combat.CreatureHealthBar>();
            hbar.target = basilisk;
            hbar.fillColor = new Color(0.50f, 0.70f, 0.30f);
            hbar.fillColorLow = new Color(0.70f, 0.20f, 0.20f);

            const string path = "Assets/Resources/Enemies/Basilisk.prefab";
            GameObject prefab;
            if (AssetDatabase.LoadMainAssetAtPath(path) != null)
            {
                prefab = AssetDatabase.LoadAssetAtPath<GameObject>(path);
                UnityEngine.Object.DestroyImmediate(root);
            }
            else
            {
                prefab = PrefabUtility.SaveAsPrefabAsset(root, path);
                UnityEngine.Object.DestroyImmediate(root);
            }

            // Inject into forest/open-ground biome scatter (reliable spawn path; same as the Ghoul).
            var br = AssetDatabase.LoadAssetAtPath<VoxelEngine.Biomes.BiomeRegistry>(ASSET_ROOT + "/BiomeRegistry.asset");
            if (br != null && prefab != null)
            {
                foreach (var biome in br.biomes)
                {
                    if (biome == null) continue;
                    if (biome.biomeName != "Forest" && biome.biomeName != "Steppes") continue;
                    var list = (biome.scatter != null)
                        ? new System.Collections.Generic.List<VoxelEngine.Biomes.BiomeDefinition.ScatterEntry>(biome.scatter)
                        : new System.Collections.Generic.List<VoxelEngine.Biomes.BiomeDefinition.ScatterEntry>();
                    list.RemoveAll(e => e.prefab != null && e.prefab.name == "Basilisk");
                    list.Add(new VoxelEngine.Biomes.BiomeDefinition.ScatterEntry { prefab = prefab, density = 0.0025f, minScale = 0.95f, maxScale = 1.15f, minHeight = 0, maxHeight = 9999 });
                    biome.scatter = list.ToArray();
                    EditorUtility.SetDirty(biome);
                }
                EditorUtility.SetDirty(br);
            }

            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();
            EditorUtility.DisplayDialog("Voxel Engine — Mythical Enemy: Basilisk (Phase 3j)",
                "The Basilisk is built:\n\n" +
                "• Large serpentine beast: segmented body + tail, dorsal crest, frilled head, fangs, glowing eyes (~30 parts)\n" +
                "• PETRIFYING GAZE — forward cone that slows you (turn toward stone); circle-strafe to break it\n" +
                "• Venomous bite applies poison\n" +
                "• Drops Basilisk Scale + (rare) Petrified Eye\n\n" +
                "Spawns rarely in Forest/Steppes (biome scatter). Saved to Resources/Enemies.",
                "OK");
        }

        // ============================================================
        //   STEP 33 - PLAYER WEAPONS (Combat Phase 3k): a throwable
        //   GRENADE (Explosive AoE, chain reactions, consumable) and
        //   an IRON RIFLE (long-range semi-auto). Non-destructive.
        //   Re-runnable. Idempotent.
        // ============================================================
        private void BuildExplosiveContent()
        {
            const string COMBAT_ROOT  = ASSET_ROOT + "/Combat";
            const string COMBAT_ITEMS = COMBAT_ROOT + "/Items";
            const string COMBAT_MATS  = COMBAT_ROOT + "/Materials";
            EnsureFolder(COMBAT_ROOT);
            EnsureFolder(COMBAT_ITEMS);
            EnsureFolder(COMBAT_MATS);

            ItemDefinition FindItem(string assetNameNoExt)
            {
                var guids = AssetDatabase.FindAssets(assetNameNoExt + " t:ItemDefinition");
                foreach (var g in guids)
                {
                    var pp = AssetDatabase.GUIDToAssetPath(g);
                    if (System.IO.Path.GetFileNameWithoutExtension(pp) == assetNameNoExt)
                        return AssetDatabase.LoadAssetAtPath<ItemDefinition>(pp);
                }
                return null;
            }
            var ironPlate  = FindItem("Item_IronPlate");
            var coal       = FindItem("Item_Coal");
            var steelIngot = FindItem("Item_SteelIngot");
            var copperWire = FindItem("Item_CopperLVWire");

            // ── Ammo (bullets) — consumed by ranged weapons. ──
            var bullets = GetOrCreateAsset<VoxelEngine.Items.ItemDefinition>($"{COMBAT_ITEMS}/Item_Bullets.asset");
            bullets.itemId = "item_bullets"; bullets.displayName = "Bullets";
            bullets.description = "Standard ammunition for ranged weapons (pistol, rifle).";
            bullets.iconTint = new Color(0.78f, 0.70f, 0.30f); bullets.maxStack = 99; bullets.massPerUnit = 0.05f; bullets.category = "Combat";
            EditorUtility.SetDirty(bullets);

            var explosionMat = MakeColoredMat(COMBAT_MATS, "Mat_Explosion", new Color(1.0f, 0.45f, 0.10f));

            // ── Grenade (throwable explosive, consumable) ──
            var grenade = GetOrCreateAsset<VoxelEngine.Combat.WeaponItem>($"{COMBAT_ITEMS}/Weapon_Grenade.asset");
            grenade.itemId = "weapon_grenade"; grenade.displayName = "Grenade";
            grenade.description = "Throwable explosive. Lob it (LMB) and duck — blasts every creature in a radius, and chain-detonates other grenades.";
            grenade.attackMode = VoxelEngine.Combat.WeaponItem.AttackMode.Thrown;
            grenade.damageType = VoxelEngine.Combat.DamageType.Explosive;
            grenade.damage = 0f;                  // explosionDamage is used instead
            grenade.attackCooldown = 0.8f;
            grenade.explosionRadius = 5f;
            grenade.explosionDamage = 80f;
            grenade.voxelDamageRadius = 2.5f;
            grenade.fuseTime = 1.6f;
            grenade.throwForce = 13f;
            grenade.explosionMaterial = explosionMat;
            grenade.iconTint = new Color(0.32f, 0.46f, 0.22f);
            grenade.maxStack = 8; grenade.massPerUnit = 0.5f; grenade.category = "Combat";
            EditorUtility.SetDirty(grenade);

            // ── Iron Rifle (long-range semi-auto) ──
            var rifle = GetOrCreateAsset<VoxelEngine.Combat.WeaponItem>($"{COMBAT_ITEMS}/Weapon_Rifle.asset");
            rifle.itemId = "weapon_rifle"; rifle.displayName = "Iron Rifle";
            rifle.description = "Long-range semi-auto kinetic rifle. Reach flyers and bosses the pistol can't.";
            rifle.attackMode = VoxelEngine.Combat.WeaponItem.AttackMode.Ranged;
            rifle.damageType = VoxelEngine.Combat.DamageType.Kinetic;
            rifle.damage = 45f;
            rifle.range = 50f;
            rifle.attackCooldown = 0.35f;
            rifle.iconTint = new Color(0.42f, 0.42f, 0.44f);
            rifle.maxStack = 1; rifle.massPerUnit = 4f; rifle.category = "Combat";
            rifle.ammoItem = bullets;
            // Wire ammo onto the existing Iron Pistol too (created by Step 22).
            var pistolItem = FindItem("Weapon_IronPistol");
            if (pistolItem is VoxelEngine.Combat.WeaponItem pistol) { pistol.ammoItem = bullets; EditorUtility.SetDirty(pistol); }
            EditorUtility.SetDirty(rifle);

            // ── Recipes ──
            AddRecipe("Recipe_Grenade", "Grenade", grenade, 1, VoxelEngine.Crafting.StationTier.Assembler, true,
                (ironPlate, 2), (coal, 2));
            AddRecipe("Recipe_Rifle", "Iron Rifle", rifle, 1, VoxelEngine.Crafting.StationTier.Assembler, true,
                (ironPlate, 4), (steelIngot, 3), (copperWire, 3));
            AddRecipe("Recipe_Bullets", "Bullets", bullets, 8, VoxelEngine.Crafting.StationTier.Assembler, true,
                (ironPlate, 1), (coal, 1));

            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();
            EditorUtility.DisplayDialog("Voxel Engine — Player Weapons (Phase 3k)",
                "Player weapons built:\n\n" +
                "• Grenade — throwable explosive (LMB to lob). Radial-gravity arc, fuse, AoE blast, chain reactions. Consumable (stack of 8). Craft at the Assembler.\n" +
                "• Iron Rifle — long-range (50 m) semi-auto kinetic weapon. Reach flyers and bosses. Craft at the Assembler.\n" +
                "• Bullets — ammo for the pistol + rifle (spent per shot). Craft at the Assembler. Both guns now require ammo.\n\n" +
                "Hold either in your hotbar and press LMB. The grenade is spent per throw; the rifle auto-fires while held.",
                "OK");
        }

        // ============================================================
        //   STEP 34 - POWDER KEG (big bomb). A placeable high-yield
        //   explosive: place it, it fuses (~5s) and detonates in a big
        //   mushroom-cloud blast (creature/player/block damage + a voxel
        //   crater + camera shake). Shoot it / catch it in a blast to
        //   set it off early (chain reactions). Non-destructive.
        //   Re-runnable. Idempotent.
        // ============================================================
        private void BuildPowderKegContent()
        {
            const string COMBAT_ROOT  = ASSET_ROOT + "/Combat";
            const string COMBAT_ITEMS = COMBAT_ROOT + "/Items";
            const string COMBAT_BLOCKS= COMBAT_ROOT + "/Blocks";
            const string COMBAT_PREFABS=COMBAT_ROOT + "/Prefabs";
            const string COMBAT_MATS  = COMBAT_ROOT + "/Materials";
            EnsureFolder(COMBAT_ROOT);
            EnsureFolder(COMBAT_ITEMS);
            EnsureFolder(COMBAT_BLOCKS);
            EnsureFolder(COMBAT_PREFABS);
            EnsureFolder(COMBAT_MATS);

            ItemDefinition FindItem(string assetNameNoExt)
            {
                var guids = AssetDatabase.FindAssets(assetNameNoExt + " t:ItemDefinition");
                foreach (var g in guids)
                {
                    var pp = AssetDatabase.GUIDToAssetPath(g);
                    if (System.IO.Path.GetFileNameWithoutExtension(pp) == assetNameNoExt)
                        return AssetDatabase.LoadAssetAtPath<ItemDefinition>(pp);
                }
                return null;
            }
            var plank     = FindItem("Item_WoodenPlank");
            var coal      = FindItem("Item_Coal");
            var ironIngot = FindItem("Item_IronIngot");

            var kegWood   = MakeColoredMat(COMBAT_MATS, "Mat_KegWood", new Color(0.42f, 0.27f, 0.14f));
            var metal     = MakeColoredMat(COMBAT_MATS, "Mat_KegMetal",new Color(0.30f, 0.30f, 0.32f));
            var fuseGlow  = MakeColoredMat(COMBAT_MATS, "Mat_KegFuse", new Color(1.0f, 0.55f, 0.12f));
            var labelDark = MakeColoredMat(COMBAT_MATS, "Mat_KegLabel",new Color(0.12f, 0.10f, 0.08f));
            // Reuse the orange explosion material (created by Step 33; idempotent here).
            var explosionMat = MakeColoredMat(COMBAT_MATS, "Mat_Explosion", new Color(1.0f, 0.45f, 0.10f));

            void AddPart(GameObject root, string n, Vector3 pos, Vector3 euler, Vector3 scale, Material m)
            {
                var go = GameObject.CreatePrimitive(PrimitiveType.Cube);
                go.name = n; go.transform.SetParent(root.transform, false);
                go.transform.localPosition = pos; go.transform.localEulerAngles = euler; go.transform.localScale = scale;
                go.GetComponent<Renderer>().sharedMaterial = m;
                var col = go.GetComponent<Collider>(); if (col != null) UnityEngine.Object.DestroyImmediate(col);
            }

            var root = new GameObject("PowderKeg");
            // ── Barrel body + top/bottom ──
            AddPart(root, "Body",   new Vector3(0f, 0.5f, 0f),  Vector3.zero, new Vector3(0.8f, 1.0f, 0.8f), kegWood);
            AddPart(root, "Top",    new Vector3(0f, 1.0f, 0f),  Vector3.zero, new Vector3(0.74f, 0.14f, 0.74f), kegWood);
            AddPart(root, "Bottom", new Vector3(0f, 0.1f, 0f),  Vector3.zero, new Vector3(0.74f, 0.14f, 0.74f), kegWood);
            // ── Metal bands ──
            AddPart(root, "BandTop", new Vector3(0f, 0.82f, 0f), Vector3.zero, new Vector3(0.86f, 0.10f, 0.86f), metal);
            AddPart(root, "BandBot", new Vector3(0f, 0.28f, 0f), Vector3.zero, new Vector3(0.86f, 0.10f, 0.86f), metal);
            // ── Bung + glowing fuse + danger label ──
            AddPart(root, "Bung",   new Vector3(0f, 1.09f, 0f),  Vector3.zero, new Vector3(0.16f, 0.06f, 0.16f), metal);
            AddPart(root, "Fuse",   new Vector3(0f, 1.22f, 0f),  Vector3.zero, new Vector3(0.05f, 0.22f, 0.05f), fuseGlow);
            AddPart(root, "Label",  new Vector3(0f, 0.55f, 0.41f),Vector3.zero, new Vector3(0.22f, 0.22f, 0.02f), labelDark);

            var cap = root.AddComponent<CapsuleCollider>();
            cap.height = 1.2f; cap.radius = 0.5f; cap.center = new Vector3(0f, 0.55f, 0f);
            var keg = root.AddComponent<VoxelEngine.Combat.ExplosiveBlock>();
            keg.fuse = 5f;
            keg.explosionRadius = 12f;
            keg.explosionDamage = 250f;
            keg.voxelDamageRadius = 4f;
            keg.explosionMaterial = explosionMat;

            const string kegPath = ASSET_ROOT + "/Combat/Prefabs/PowderKeg.prefab";
            GameObject kegPrefab;
            if (AssetDatabase.LoadMainAssetAtPath(kegPath) != null)
            {
                kegPrefab = AssetDatabase.LoadAssetAtPath<GameObject>(kegPath);
                UnityEngine.Object.DestroyImmediate(root);
            }
            else
            {
                kegPrefab = PrefabUtility.SaveAsPrefabAsset(root, kegPath);
                UnityEngine.Object.DestroyImmediate(root);
            }

            var block = GetOrCreateAsset<VoxelEngine.Items.BlockItem>($"{COMBAT_BLOCKS}/Block_PowderKeg.asset");
            block.itemId = "block_powder_keg"; block.displayName = "Powder Keg";
            block.description = "Placeable high-yield explosive. Fuses ~5 s after placement, then a massive blast. Shoot it (or catch it in a blast) to set it off early. Chain-reacts with other explosives.";
            block.iconTint = new Color(0.42f, 0.27f, 0.14f);
            block.maxStack = 16; block.massPerUnit = 3f;
            block.placedPrefab = kegPrefab;
            block.gridSize = Vector3Int.one;
            block.allowStacking = true;
            block.blockHealth = 40;
            block.miningTier = 1;
            block.category = "Combat";
            EditorUtility.SetDirty(block);

            AddRecipe("Recipe_PowderKeg", "Powder Keg", block, 1, VoxelEngine.Crafting.StationTier.Assembler, true,
                (plank, 4), (coal, 6), (ironIngot, 3));

            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();
            EditorUtility.DisplayDialog("Voxel Engine — Powder Keg (big bomb)",
                "The Powder Keg is built:\n\n" +
                "• Placeable wooden barrel of explosives (~9 parts) with a glowing fuse\n" +
                "• Fuses ~5 s after placement → big mushroom-cloud blast (radius 12, damage 250) + large voxel crater + camera shake\n" +
                "• Shoot it, or catch it in a grenade/keg blast, to detonate it early (chain reactions)\n" +
                "• Craft at the Assembler (plank + coal + iron)\n\n" +
                "Place it, step back, and watch the mushroom cloud.",
                "OK");
        }

        // ============================================================
        //   STEP 35 - TSAR BOMB (huge bomb, ~10x the Powder Keg).
        //   Placeable; fuses then a GINORMOUS mushroom-cloud blast +
        //   large crater. Shoot/chain to detonate early. Non-destructive.
        // ============================================================
        private void BuildTsarBombContent()
        {
            const string COMBAT_ROOT  = ASSET_ROOT + "/Combat";
            const string COMBAT_ITEMS = COMBAT_ROOT + "/Items";
            const string COMBAT_BLOCKS= COMBAT_ROOT + "/Blocks";
            const string COMBAT_PREFABS=COMBAT_ROOT + "/Prefabs";
            const string COMBAT_MATS  = COMBAT_ROOT + "/Materials";
            EnsureFolder(COMBAT_ROOT); EnsureFolder(COMBAT_ITEMS); EnsureFolder(COMBAT_BLOCKS); EnsureFolder(COMBAT_PREFABS); EnsureFolder(COMBAT_MATS);

            ItemDefinition FindItem(string n)
            {
                var guids = AssetDatabase.FindAssets(n + " t:ItemDefinition");
                foreach (var g in guids) { var pp = AssetDatabase.GUIDToAssetPath(g); if (System.IO.Path.GetFileNameWithoutExtension(pp) == n) return AssetDatabase.LoadAssetAtPath<ItemDefinition>(pp); }
                return null;
            }
            var steelIngot = FindItem("Item_SteelIngot");
            var ironPlate  = FindItem("Item_IronPlate");
            var coal       = FindItem("Item_Coal");

            var steelBody = MakeColoredMat(COMBAT_MATS, "Mat_TsarBody", new Color(0.36f, 0.38f, 0.41f));
            var darkSteel = MakeColoredMat(COMBAT_MATS, "Mat_TsarDark", new Color(0.20f, 0.21f, 0.23f));
            var redTip    = MakeColoredMat(COMBAT_MATS, "Mat_TsarRed",  new Color(0.80f, 0.15f, 0.10f));
            var explosionMat = MakeColoredMat(COMBAT_MATS, "Mat_Explosion", new Color(1.0f, 0.45f, 0.10f));

            void AddPart(GameObject root, string n, Vector3 pos, Vector3 euler, Vector3 scale, Material m)
            {
                var go = GameObject.CreatePrimitive(PrimitiveType.Cube);
                go.name = n; go.transform.SetParent(root.transform, false);
                go.transform.localPosition = pos; go.transform.localEulerAngles = euler; go.transform.localScale = scale;
                go.GetComponent<Renderer>().sharedMaterial = m;
                var col = go.GetComponent<Collider>(); if (col != null) UnityEngine.Object.DestroyImmediate(col);
            }

            var root = new GameObject("TsarBomb");
            AddPart(root, "Body",   new Vector3(0f, 0.85f, 0f), Vector3.zero, new Vector3(1.1f, 1.4f, 1.1f), steelBody);
            AddPart(root, "Collar", new Vector3(0f, 1.4f, 0f),  Vector3.zero, new Vector3(1.2f, 0.2f, 1.2f), darkSteel);
            AddPart(root, "Nose",   new Vector3(0f, 1.75f, 0f), Vector3.zero, new Vector3(0.5f, 0.6f, 0.5f),  redTip);
            AddPart(root, "NoseBand",new Vector3(0f, 1.5f, 0f), Vector3.zero, new Vector3(0.6f, 0.1f, 0.6f),  darkSteel);
            AddPart(root, "BandMid",new Vector3(0f, 0.95f, 0f), Vector3.zero, new Vector3(1.18f, 0.15f, 1.18f), darkSteel);
            AddPart(root, "Base",   new Vector3(0f, 0.15f, 0f), Vector3.zero, new Vector3(1.0f, 0.2f, 1.0f),   darkSteel);
            AddPart(root, "Stripe", new Vector3(0f, 1.1f, 0.56f),Vector3.zero,new Vector3(0.6f, 0.18f, 0.02f), redTip);
            AddPart(root, "Fin1", new Vector3(0.62f, 0.35f, 0f), new Vector3(0f, 0f, 25f), new Vector3(0.1f, 0.45f, 0.4f), darkSteel);
            AddPart(root, "Fin2", new Vector3(-0.62f, 0.35f, 0f),new Vector3(0f, 0f, -25f),new Vector3(0.1f, 0.45f, 0.4f), darkSteel);
            AddPart(root, "Fin3", new Vector3(0f, 0.35f, 0.62f), new Vector3(25f, 0f, 0f), new Vector3(0.4f, 0.45f, 0.1f), darkSteel);
            AddPart(root, "Fin4", new Vector3(0f, 0.35f, -0.62f),new Vector3(-25f, 0f, 0f),new Vector3(0.4f, 0.45f, 0.1f), darkSteel);

            var cap = root.AddComponent<CapsuleCollider>();
            cap.height = 1.9f; cap.radius = 0.7f; cap.center = new Vector3(0f, 0.85f, 0f);
            var bomb = root.AddComponent<VoxelEngine.Combat.ExplosiveBlock>();
            bomb.fuse = 7f; bomb.explosionRadius = 40f; bomb.explosionDamage = 2500f; bomb.voxelDamageRadius = 8f;
            bomb.explosionMaterial = explosionMat;

            const string path = ASSET_ROOT + "/Combat/Prefabs/TsarBomb.prefab";
            GameObject prefab;
            if (AssetDatabase.LoadMainAssetAtPath(path) != null) { prefab = AssetDatabase.LoadAssetAtPath<GameObject>(path); UnityEngine.Object.DestroyImmediate(root); }
            else { prefab = PrefabUtility.SaveAsPrefabAsset(root, path); UnityEngine.Object.DestroyImmediate(root); }

            var block = GetOrCreateAsset<VoxelEngine.Items.BlockItem>($"{COMBAT_BLOCKS}/Block_TsarBomb.asset");
            block.itemId = "block_tsar_bomb"; block.displayName = "Tsar Bomb";
            block.description = "Ginormous placeable explosive. ~10× the Powder Keg. Fuses ~7 s, then a colossal mushroom-cloud blast + huge crater. Stand very far back.";
            block.iconTint = new Color(0.36f, 0.38f, 0.41f);
            block.maxStack = 4; block.massPerUnit = 12f;
            block.placedPrefab = prefab; block.gridSize = Vector3Int.one; block.allowStacking = true; block.blockHealth = 80; block.miningTier = 2; block.category = "Combat";
            EditorUtility.SetDirty(block);

            AddRecipe("Recipe_TsarBomb", "Tsar Bomb", block, 1, VoxelEngine.Crafting.StationTier.Assembler, true,
                (steelIngot, 8), (ironPlate, 8), (coal, 12));

            AssetDatabase.SaveAssets(); AssetDatabase.Refresh();
            EditorUtility.DisplayDialog("Voxel Engine — Tsar Bomb",
                "The Tsar Bomb is built:\n\n• Huge steel bomb (~12 parts), ~10× the Powder Keg\n• Radius 40, damage 2500, big voxel crater, giant mushroom cloud\n• Fuses ~7 s; shoot/chain to detonate early\n• Craft at the Assembler (steel + iron plate + coal)", "OK");
        }

        // ============================================================
        //   STEP 36 - ANTIMATTER BOMB (the ultimate explosive, ~40x
        //   the Tsar). Runs a "star-death" sequence: core sphere
        //   EXPANDS slowly → CONTRACTS fast → blinding WHITE GLOW →
        //   MASSIVE detonation. Placeable; fuses or chains. Non-
        //   destructive. Re-runnable. Idempotent.
        // ============================================================
        private void BuildAntimatterBombContent()
        {
            const string COMBAT_ROOT  = ASSET_ROOT + "/Combat";
            const string COMBAT_ITEMS = COMBAT_ROOT + "/Items";
            const string COMBAT_BLOCKS= COMBAT_ROOT + "/Blocks";
            const string COMBAT_PREFABS=COMBAT_ROOT + "/Prefabs";
            const string COMBAT_MATS  = COMBAT_ROOT + "/Materials";
            EnsureFolder(COMBAT_ROOT); EnsureFolder(COMBAT_ITEMS); EnsureFolder(COMBAT_BLOCKS); EnsureFolder(COMBAT_PREFABS); EnsureFolder(COMBAT_MATS);

            ItemDefinition FindItem(string n)
            {
                var guids = AssetDatabase.FindAssets(n + " t:ItemDefinition");
                foreach (var g in guids) { var pp = AssetDatabase.GUIDToAssetPath(g); if (System.IO.Path.GetFileNameWithoutExtension(pp) == n) return AssetDatabase.LoadAssetAtPath<ItemDefinition>(pp); }
                return null;
            }
            var advCircuit = FindItem("Item_AdvancedCircuit");
            var steelPlate = FindItem("Item_SteelPlate");
            var goldWire   = FindItem("Item_GoldLVWire");

            var cageMat  = MakeColoredMat(COMBAT_MATS, "Mat_AntiCage", new Color(0.30f, 0.32f, 0.36f));
            var strutMat = MakeColoredMat(COMBAT_MATS, "Mat_AntiStrut",new Color(0.42f, 0.44f, 0.50f));
            var coreMat  = MakeColoredMat(COMBAT_MATS, "Mat_AntiCore", new Color(0.55f, 0.30f, 0.95f)); // containment violet
            var blastMat = MakeColoredMat(COMBAT_MATS, "Mat_AntiBlast",new Color(0.75f, 0.85f, 1.0f));  // white-blue blast

            void AddPart(GameObject root, string n, Vector3 pos, Vector3 euler, Vector3 scale, Material m)
            {
                var go = GameObject.CreatePrimitive(PrimitiveType.Cube);
                go.name = n; go.transform.SetParent(root.transform, false);
                go.transform.localPosition = pos; go.transform.localEulerAngles = euler; go.transform.localScale = scale;
                go.GetComponent<Renderer>().sharedMaterial = m;
                var col = go.GetComponent<Collider>(); if (col != null) UnityEngine.Object.DestroyImmediate(col);
            }

            var root = new GameObject("AntimatterBomb");
            // Glowing containment core
            var core = GameObject.CreatePrimitive(PrimitiveType.Sphere);
            core.name = "Core"; core.transform.SetParent(root.transform, false);
            core.transform.localPosition = new Vector3(0f, 0.65f, 0f); core.transform.localScale = Vector3.one * 0.45f;
            core.GetComponent<Renderer>().sharedMaterial = coreMat;
            var ccol = core.GetComponent<Collider>(); if (ccol != null) UnityEngine.Object.DestroyImmediate(ccol);
            // Containment cage: 4 vertical struts + top/bottom plates + a mid band
            AddPart(root, "StrutFL", new Vector3(-0.45f, 0.65f, 0.45f), Vector3.zero, new Vector3(0.07f, 1.0f, 0.07f), strutMat);
            AddPart(root, "StrutFR", new Vector3( 0.45f, 0.65f, 0.45f), Vector3.zero, new Vector3(0.07f, 1.0f, 0.07f), strutMat);
            AddPart(root, "StrutBL", new Vector3(-0.45f, 0.65f,-0.45f), Vector3.zero, new Vector3(0.07f, 1.0f, 0.07f), strutMat);
            AddPart(root, "StrutBR", new Vector3( 0.45f, 0.65f,-0.45f), Vector3.zero, new Vector3(0.07f, 1.0f, 0.07f), strutMat);
            AddPart(root, "TopPlate", new Vector3(0f, 1.16f, 0f), Vector3.zero, new Vector3(1.0f, 0.08f, 1.0f), cageMat);
            AddPart(root, "Base",    new Vector3(0f, 0.14f, 0f), Vector3.zero, new Vector3(1.0f, 0.15f, 1.0f), cageMat);
            AddPart(root, "MidBand", new Vector3(0f, 0.65f, 0f), Vector3.zero, new Vector3(1.0f, 0.06f, 1.0f), strutMat);

            var cap = root.AddComponent<CapsuleCollider>();
            cap.height = 1.4f; cap.radius = 0.65f; cap.center = new Vector3(0f, 0.65f, 0f);
            var bomb = root.AddComponent<VoxelEngine.Combat.AntimatterBomb>();
            bomb.fuse = 8f; bomb.explosionRadius = 80f; bomb.explosionDamage = 30000f; bomb.voxelDamageRadius = 10f;
            bomb.coreMaterial = coreMat; bomb.explosionMaterial = blastMat;

            const string path = ASSET_ROOT + "/Combat/Prefabs/AntimatterBomb.prefab";
            GameObject prefab;
            if (AssetDatabase.LoadMainAssetAtPath(path) != null) { prefab = AssetDatabase.LoadAssetAtPath<GameObject>(path); UnityEngine.Object.DestroyImmediate(root); }
            else { prefab = PrefabUtility.SaveAsPrefabAsset(root, path); UnityEngine.Object.DestroyImmediate(root); }

            var block = GetOrCreateAsset<VoxelEngine.Items.BlockItem>($"{COMBAT_BLOCKS}/Block_AntimatterBomb.asset");
            block.itemId = "block_antimatter_bomb"; block.displayName = "Antimatter Bomb";
            block.description = "The ultimate explosive. ~40× a Tsar. Runs a star-death sequence — core swells, collapses to a point, blinding white glow, then a MASSIVE detonation. Do NOT be anywhere nearby.";
            block.iconTint = new Color(0.55f, 0.30f, 0.95f);
            block.maxStack = 1; block.massPerUnit = 30f;
            block.placedPrefab = prefab; block.gridSize = Vector3Int.one; block.allowStacking = true; block.blockHealth = 120; block.miningTier = 3; block.category = "Combat";
            EditorUtility.SetDirty(block);

            AddRecipe("Recipe_AntimatterBomb", "Antimatter Bomb", block, 1, VoxelEngine.Crafting.StationTier.Assembler, true,
                (advCircuit, 4), (steelPlate, 12), (goldWire, 8));

            AssetDatabase.SaveAssets(); AssetDatabase.Refresh();
            EditorUtility.DisplayDialog("Voxel Engine — Antimatter Bomb",
                "The Antimatter Bomb is built:\n\n• Glowing violet core in a containment cage (~9 parts)\n• Star-death sequence: EXPAND slowly → CONTRACT fast → WHITE GLOW → MASSIVE blast (radius 80, damage 30000)\n• Fuses ~8 s; shoot/chain to trigger early\n• Craft at the Assembler (advanced circuit + steel plate + gold wire) — very expensive", "OK");
        }

        // ============================================================
        //   STEP 37 - AUTO TURRET. A placeable automated defense
        //   that targets hostile creatures (Ghouls, Manticores,
        //   Griffins, etc.) and fires hitscan shots. Reload with
        //   Bullets (RMB). Non-destructive. Re-runnable. Idempotent.
        // ============================================================
        private void BuildTurretContent()
        {
            const string COMBAT_ROOT  = ASSET_ROOT + "/Combat";
            const string COMBAT_ITEMS = COMBAT_ROOT + "/Items";
            const string COMBAT_BLOCKS= COMBAT_ROOT + "/Blocks";
            const string COMBAT_PREFABS=COMBAT_ROOT + "/Prefabs";
            const string COMBAT_MATS  = COMBAT_ROOT + "/Materials";
            EnsureFolder(COMBAT_ROOT); EnsureFolder(COMBAT_ITEMS); EnsureFolder(COMBAT_BLOCKS); EnsureFolder(COMBAT_PREFABS); EnsureFolder(COMBAT_MATS);

            ItemDefinition FindItem(string n)
            {
                var guids = AssetDatabase.FindAssets(n + " t:ItemDefinition");
                foreach (var g in guids) { var pp = AssetDatabase.GUIDToAssetPath(g); if (System.IO.Path.GetFileNameWithoutExtension(pp) == n) return AssetDatabase.LoadAssetAtPath<ItemDefinition>(pp); }
                return null;
            }
            var ironPlate = FindItem("Item_IronPlate");
            var circuit   = FindItem("Item_Circuit");
            var copperWire= FindItem("Item_CopperLVWire");

            var body      = MakeColoredMat(COMBAT_MATS, "Mat_TurretBody", new Color(0.36f, 0.38f, 0.42f));
            var dark      = MakeColoredMat(COMBAT_MATS, "Mat_TurretDark", new Color(0.20f, 0.21f, 0.24f));
            var gun       = MakeColoredMat(COMBAT_MATS, "Mat_TurretGun",  new Color(0.28f, 0.28f, 0.30f));

            void AddPart(GameObject parent, string n, Vector3 pos, Vector3 euler, Vector3 scale, Material m)
            {
                var go = GameObject.CreatePrimitive(PrimitiveType.Cube);
                go.name = n; go.transform.SetParent(parent.transform, false);
                go.transform.localPosition = pos; go.transform.localEulerAngles = euler; go.transform.localScale = scale;
                go.GetComponent<Renderer>().sharedMaterial = m;
                var col = go.GetComponent<Collider>(); if (col != null) UnityEngine.Object.DestroyImmediate(col);
            }

            var root = new GameObject("Turret");
            AddPart(root, "Base",   new Vector3(0f, 0.15f, 0f), Vector3.zero, new Vector3(0.8f, 0.3f, 0.8f),  body);
            AddPart(root, "Pillar", new Vector3(0f, 0.6f, 0f),  Vector3.zero, new Vector3(0.25f, 0.6f, 0.25f), dark);
            AddPart(root, "Collar", new Vector3(0f, 0.9f, 0f),  Vector3.zero, new Vector3(0.35f, 0.1f, 0.35f), dark);

            // Rotating head (the turret yaw-tracks its target).
            var headGo = new GameObject("Head");
            headGo.transform.SetParent(root.transform, false);
            headGo.transform.localPosition = new Vector3(0f, 1.0f, 0f);
            AddPart(headGo, "HeadBody", new Vector3(0f, 0f, 0f),     Vector3.zero, new Vector3(0.45f, 0.35f, 0.45f), gun);
            AddPart(headGo, "Barrel",   new Vector3(0f, 0.05f, 0.3f),Vector3.zero, new Vector3(0.14f, 0.14f, 0.6f),  dark);
            AddPart(headGo, "Sight",    new Vector3(0f, 0.16f, 0.1f),Vector3.zero, new Vector3(0.06f, 0.06f, 0.1f),   body);

            var muzzleGo = new GameObject("Muzzle");
            muzzleGo.transform.SetParent(headGo.transform, false);
            muzzleGo.transform.localPosition = new Vector3(0f, 0.05f, 0.65f);

            var cap = root.AddComponent<CapsuleCollider>();
            cap.height = 1.4f; cap.radius = 0.4f; cap.center = new Vector3(0f, 0.6f, 0f);
            var turret = root.AddComponent<VoxelEngine.Combat.Turret>();
            turret.head = headGo.transform;
            turret.muzzle = muzzleGo.transform;

            const string path = ASSET_ROOT + "/Combat/Prefabs/Turret.prefab";
            GameObject prefab;
            if (AssetDatabase.LoadMainAssetAtPath(path) != null) { prefab = AssetDatabase.LoadAssetAtPath<GameObject>(path); UnityEngine.Object.DestroyImmediate(root); }
            else { prefab = PrefabUtility.SaveAsPrefabAsset(root, path); UnityEngine.Object.DestroyImmediate(root); }

            var block = GetOrCreateAsset<VoxelEngine.Items.BlockItem>($"{COMBAT_BLOCKS}/Block_Turret.asset");
            block.itemId = "block_turret"; block.displayName = "Auto Turret";
            block.description = "Automated defense turret. Scans for hostile creatures and fires hitscan shots. Reload it by holding Bullets and pressing RMB.";
            block.iconTint = new Color(0.36f, 0.38f, 0.42f);
            block.maxStack = 10; block.massPerUnit = 5f;
            block.placedPrefab = prefab; block.gridSize = Vector3Int.one; block.allowStacking = true; block.blockHealth = 80; block.miningTier = 1; block.category = "Combat";
            EditorUtility.SetDirty(block);

            AddRecipe("Recipe_Turret", "Auto Turret", block, 1, VoxelEngine.Crafting.StationTier.Assembler, true,
                (ironPlate, 6), (circuit, 2), (copperWire, 4));

            AssetDatabase.SaveAssets(); AssetDatabase.Refresh();
            EditorUtility.DisplayDialog("Voxel Engine — Auto Turret",
                "The Auto Turret is built:\n\n• Placeable defense turret (base + pillar + rotating head with barrel)\n• Auto-targets hostile creatures (Ghouls, Manticores, Griffins, Roc, etc.) in range + line of sight\n• Fires hitscan shots with tracer + muzzle flash\n• 80 HP; reload by holding Bullets + RMB\n• Craft at the Assembler (iron plate + circuit + copper wire)", "OK");
        }

        // ============================================================
        //   STEP 38 - HEAVY ARTILLERY: CANNON (howitzer). Auto-targets
        //   by faction filter; fires arcing explosive shells. Reload
        //   with Bullets (RMB). Targeting UI shown when looking at it.
        //   Non-destructive. Re-runnable. Idempotent.
        // ============================================================
        private void BuildArtilleryCannonContent()
        {
            const string COMBAT_ROOT  = ASSET_ROOT + "/Combat";
            const string COMBAT_ITEMS = COMBAT_ROOT + "/Items";
            const string COMBAT_BLOCKS= COMBAT_ROOT + "/Blocks";
            const string COMBAT_PREFABS=COMBAT_ROOT + "/Prefabs";
            const string COMBAT_MATS  = COMBAT_ROOT + "/Materials";
            EnsureFolder(COMBAT_ROOT); EnsureFolder(COMBAT_ITEMS); EnsureFolder(COMBAT_BLOCKS); EnsureFolder(COMBAT_PREFABS); EnsureFolder(COMBAT_MATS);

            ItemDefinition FindItem(string n)
            {
                var guids = AssetDatabase.FindAssets(n + " t:ItemDefinition");
                foreach (var g in guids) { var pp = AssetDatabase.GUIDToAssetPath(g); if (System.IO.Path.GetFileNameWithoutExtension(pp) == n) return AssetDatabase.LoadAssetAtPath<ItemDefinition>(pp); }
                return null;
            }
            var ironPlate  = FindItem("Item_IronPlate");
            var steelIngot = FindItem("Item_SteelIngot");
            var circuit    = FindItem("Item_Circuit");
            var copperWire = FindItem("Item_CopperLVWire");
            var coal       = FindItem("Item_Coal");

            var body       = MakeColoredMat(COMBAT_MATS, "Mat_ArtilleryBody", new Color(0.32f, 0.34f, 0.16f));
            var dark       = MakeColoredMat(COMBAT_MATS, "Mat_ArtilleryDark", new Color(0.18f, 0.18f, 0.16f));
            var barrel     = MakeColoredMat(COMBAT_MATS, "Mat_ArtilleryBarrel",new Color(0.22f, 0.22f, 0.24f));
            var shellMat   = MakeColoredMat(COMBAT_MATS, "Mat_Shell",         new Color(0.25f, 0.25f, 0.28f));
            var explosionMat = MakeColoredMat(COMBAT_MATS, "Mat_Explosion",   new Color(1.0f, 0.45f, 0.10f));

            void AddPart(GameObject parent, string n, Vector3 pos, Vector3 euler, Vector3 scale, Material m)
            {
                var go = GameObject.CreatePrimitive(PrimitiveType.Cube);
                go.name = n; go.transform.SetParent(parent.transform, false);
                go.transform.localPosition = pos; go.transform.localEulerAngles = euler; go.transform.localScale = scale;
                go.GetComponent<Renderer>().sharedMaterial = m;
                var col = go.GetComponent<Collider>(); if (col != null) UnityEngine.Object.DestroyImmediate(col);
            }
            void AddCyl(GameObject parent, string n, Vector3 pos, Vector3 euler, Vector3 scale, Material m)
            {
                var go = GameObject.CreatePrimitive(PrimitiveType.Cylinder);
                go.name = n; go.transform.SetParent(parent.transform, false);
                go.transform.localPosition = pos; go.transform.localEulerAngles = euler; go.transform.localScale = scale;
                go.GetComponent<Renderer>().sharedMaterial = m;
                var col = go.GetComponent<Collider>(); if (col != null) UnityEngine.Object.DestroyImmediate(col);
            }

            var root = new GameObject("ArtilleryCannon");
            // Carriage base + split trails
            AddPart(root, "Base",   new Vector3(0f, 0.1f, 0f),    Vector3.zero, new Vector3(0.9f, 0.2f, 1.2f), body);
            AddPart(root, "TrailL", new Vector3(-0.35f, 0.1f, -0.8f),new Vector3(15,0,-15), new Vector3(0.15f, 0.12f, 0.8f), body);
            AddPart(root, "TrailR", new Vector3( 0.35f, 0.1f, -0.8f),new Vector3(15,0, 15), new Vector3(0.15f, 0.12f, 0.8f), body);
            // Wheels
            AddCyl(root, "WheelL", new Vector3(-0.5f, 0.2f, 0f), new Vector3(0,0,90), new Vector3(0.35f, 0.06f, 0.35f), dark);
            AddCyl(root, "WheelR", new Vector3( 0.5f, 0.2f, 0f), new Vector3(0,0,90), new Vector3(0.35f, 0.06f, 0.35f), dark);

            // Rotating head (breech + long barrel + recoil + sight)
            var headGo = new GameObject("Head");
            headGo.transform.SetParent(root.transform, false);
            headGo.transform.localPosition = new Vector3(0f, 0.45f, 0.1f);
            AddPart(headGo, "Breech",  new Vector3(0f, 0f, 0f),     Vector3.zero, new Vector3(0.4f, 0.35f, 0.4f), barrel);
            AddPart(headGo, "Barrel",  new Vector3(0f, 0.05f, 0.8f),Vector3.zero, new Vector3(0.18f, 0.18f, 1.4f), barrel);
            AddPart(headGo, "Recoil",  new Vector3(0f, 0.18f, 0.5f),Vector3.zero, new Vector3(0.1f, 0.1f, 0.9f), dark);
            AddPart(headGo, "Sight",   new Vector3(0f, 0.22f, 0.1f),Vector3.zero, new Vector3(0.06f, 0.06f, 0.1f), dark);
            var muzzleGo = new GameObject("Muzzle");
            muzzleGo.transform.SetParent(headGo.transform, false);
            muzzleGo.transform.localPosition = new Vector3(0f, 0.05f, 1.55f);

            var cap = root.AddComponent<CapsuleCollider>();
            cap.height = 1.5f; cap.radius = 0.5f; cap.center = new Vector3(0f, 0.5f, 0f);
            var art = root.AddComponent<VoxelEngine.Combat.Artillery>();
            art.variant = VoxelEngine.Combat.ArtilleryVariant.Cannon;
            art.range = 70f; art.fireCooldown = 2.5f; art.damage = 60f; art.explosionRadius = 8f; art.shellSpeed = 35f;
            art.shellMat = shellMat; art.explosionMat = explosionMat;
            art.head = headGo.transform; art.muzzle = muzzleGo.transform;

            const string path = ASSET_ROOT + "/Combat/Prefabs/ArtilleryCannon.prefab";
            GameObject prefab;
            if (AssetDatabase.LoadMainAssetAtPath(path) != null) { prefab = AssetDatabase.LoadAssetAtPath<GameObject>(path); UnityEngine.Object.DestroyImmediate(root); }
            else { prefab = PrefabUtility.SaveAsPrefabAsset(root, path); UnityEngine.Object.DestroyImmediate(root); }

            var block = GetOrCreateAsset<VoxelEngine.Items.BlockItem>($"{COMBAT_BLOCKS}/Block_ArtilleryCannon.asset");
            block.itemId = "block_artillery_cannon"; block.displayName = "Heavy Cannon";
            block.description = "Heavy howitzer artillery. Auto-targets by faction filter, fires arcing explosive shells (loaded via the magazine). RMB to open the defense panel.";
            block.iconTint = new Color(0.32f, 0.34f, 0.16f);
            block.maxStack = 4; block.massPerUnit = 20f;
            block.placedPrefab = prefab; block.gridSize = Vector3Int.one; block.allowStacking = true; block.blockHealth = 200; block.miningTier = 2; block.category = "Combat";
            EditorUtility.SetDirty(block);

            AddRecipe("Recipe_ArtilleryCannon", "Heavy Cannon", block, 1, VoxelEngine.Crafting.StationTier.Assembler, true,
                (ironPlate, 10), (steelIngot, 5), (circuit, 3), (copperWire, 6));


            // ── Artillery shells (items loaded into the magazine) ──
            var shellStd = GetOrCreateAsset<VoxelEngine.Items.ItemDefinition>($"{COMBAT_ITEMS}/Item_ShellStandard.asset");
            shellStd.itemId = "item_shell_standard"; shellStd.displayName = "Standard Shell";
            shellStd.description = "Standard artillery shell. Direct blast on impact.";
            shellStd.iconTint = new Color(0.30f, 0.30f, 0.32f); shellStd.maxStack = 20; shellStd.massPerUnit = 2f; shellStd.category = "Combat";
            EditorUtility.SetDirty(shellStd);

            var shellExp = GetOrCreateAsset<VoxelEngine.Items.ItemDefinition>($"{COMBAT_ITEMS}/Item_ShellExplosive.asset");
            shellExp.itemId = "item_shell_explosive"; shellExp.displayName = "Explosive Shell";
            shellExp.description = "High-explosive artillery shell. 1.5x bigger blast + voxel crater.";
            shellExp.iconTint = new Color(0.80f, 0.30f, 0.10f); shellExp.maxStack = 20; shellExp.massPerUnit = 2.5f; shellExp.category = "Combat";
            EditorUtility.SetDirty(shellExp);

            var shellSct = GetOrCreateAsset<VoxelEngine.Items.ItemDefinition>($"{COMBAT_ITEMS}/Item_ShellScatter.asset");
            shellSct.itemId = "item_shell_scatter"; shellSct.displayName = "Scatter Shell";
            shellSct.description = "Cluster artillery shell. Bursts into sub-munitions over an area.";
            shellSct.iconTint = new Color(0.30f, 0.50f, 0.80f); shellSct.maxStack = 20; shellSct.massPerUnit = 2.5f; shellSct.category = "Combat";
            EditorUtility.SetDirty(shellSct);

            AddRecipe("Recipe_ShellStandard", "Standard Shell", shellStd, 4, VoxelEngine.Crafting.StationTier.Assembler, true,
                (ironPlate, 2), (coal, 1));
            AddRecipe("Recipe_ShellExplosive", "Explosive Shell", shellExp, 2, VoxelEngine.Crafting.StationTier.Assembler, true,
                (ironPlate, 3), (coal, 2), (steelIngot, 1));
            AddRecipe("Recipe_ShellScatter", "Scatter Shell", shellSct, 2, VoxelEngine.Crafting.StationTier.Assembler, true,
                (ironPlate, 2), (circuit, 1), (copperWire, 2));

AssetDatabase.SaveAssets(); AssetDatabase.Refresh();
            EditorUtility.DisplayDialog("Voxel Engine — Heavy Cannon Artillery",
                "The Heavy Cannon is built:\n\n• Howitzer on a split-trail carriage with wheels + long barrel (~12 parts)\n• Auto-targets by faction (Enemies/Players/Passive — configurable when looking at it)\n• Fires arcing explosive shells (damage 60, blast radius 8)\n• 200 HP; reload with Bullets (RMB)\n• Craft at the Assembler (iron + steel + circuit + copper wire)", "OK");
        }

        private void BuildArtilleryMinigunContent()
        {
            const string COMBAT_ROOT  = ASSET_ROOT + "/Combat";
            const string COMBAT_ITEMS = COMBAT_ROOT + "/Items";
            const string COMBAT_BLOCKS= COMBAT_ROOT + "/Blocks";
            const string COMBAT_PREFABS=COMBAT_ROOT + "/Prefabs";
            const string COMBAT_MATS  = COMBAT_ROOT + "/Materials";
            EnsureFolder(COMBAT_ROOT); EnsureFolder(COMBAT_ITEMS); EnsureFolder(COMBAT_BLOCKS); EnsureFolder(COMBAT_PREFABS); EnsureFolder(COMBAT_MATS);

            ItemDefinition FindItem(string n)
            {
                var guids = AssetDatabase.FindAssets(n + " t:ItemDefinition");
                foreach (var g in guids) { var pp = AssetDatabase.GUIDToAssetPath(g); if (System.IO.Path.GetFileNameWithoutExtension(pp) == n) return AssetDatabase.LoadAssetAtPath<ItemDefinition>(pp); }
                return null;
            }
            var ironPlate = FindItem("Item_IronPlate");
            var circuit   = FindItem("Item_Circuit");
            var copperWire= FindItem("Item_CopperLVWire");

            var body    = MakeColoredMat(COMBAT_MATS, "Mat_MinigunBody", new Color(0.28f, 0.28f, 0.30f));
            var dark    = MakeColoredMat(COMBAT_MATS, "Mat_MinigunDark", new Color(0.18f, 0.18f, 0.20f));
            var barrel  = MakeColoredMat(COMBAT_MATS, "Mat_MinigunBarrel",new Color(0.22f, 0.22f, 0.24f));

            void AddPart(GameObject parent, string n, Vector3 pos, Vector3 euler, Vector3 scale, Material m)
            {
                var go = GameObject.CreatePrimitive(PrimitiveType.Cube);
                go.name = n; go.transform.SetParent(parent.transform, false);
                go.transform.localPosition = pos; go.transform.localEulerAngles = euler; go.transform.localScale = scale;
                go.GetComponent<Renderer>().sharedMaterial = m;
                var col = go.GetComponent<Collider>(); if (col != null) UnityEngine.Object.DestroyImmediate(col);
            }

            var root = new GameObject("ArtilleryMinigun");
            AddPart(root, "Base",   new Vector3(0f, 0.1f, 0f), Vector3.zero, new Vector3(0.6f, 0.2f, 0.6f), body);
            AddPart(root, "Pillar", new Vector3(0f, 0.45f, 0f),Vector3.zero, new Vector3(0.18f, 0.5f, 0.18f), dark);
            AddPart(root, "Collar", new Vector3(0f, 0.72f, 0f),Vector3.zero, new Vector3(0.3f, 0.1f, 0.3f), dark);

            var headGo = new GameObject("Head");
            headGo.transform.SetParent(root.transform, false);
            headGo.transform.localPosition = new Vector3(0f, 0.85f, 0f);
            AddPart(headGo, "Body",    new Vector3(0f, 0f, 0f),      Vector3.zero, new Vector3(0.3f, 0.25f, 0.3f), body);
            AddPart(headGo, "AmmoBox", new Vector3(0f, 0.12f, -0.12f),Vector3.zero, new Vector3(0.25f, 0.18f, 0.12f), dark);
            AddPart(headGo, "Motor",   new Vector3(0f, 0f, -0.08f),  Vector3.zero, new Vector3(0.16f, 0.16f, 0.1f), dark);
            AddPart(headGo, "Sight",   new Vector3(0f, 0.14f, 0.04f),Vector3.zero, new Vector3(0.04f, 0.04f, 0.08f), body);
            // 6 barrels in a hexagon
            for (int i = 0; i < 6; i++)
            {
                float a = i * Mathf.PI / 3f;
                AddPart(headGo, "Barrel" + i,
                    new Vector3(Mathf.Cos(a) * 0.06f, Mathf.Sin(a) * 0.06f, 0.18f),
                    Vector3.zero, new Vector3(0.03f, 0.03f, 0.35f), barrel);
            }
            var muzzleGo = new GameObject("Muzzle");
            muzzleGo.transform.SetParent(headGo.transform, false);
            muzzleGo.transform.localPosition = new Vector3(0f, 0f, 0.4f);

            var cap = root.AddComponent<CapsuleCollider>();
            cap.height = 1.0f; cap.radius = 0.3f; cap.center = new Vector3(0f, 0.5f, 0f);
            var art = root.AddComponent<VoxelEngine.Combat.Artillery>();
            art.variant = VoxelEngine.Combat.ArtilleryVariant.Minigun;
            art.range = 50f; art.fireCooldown = 0.08f; art.minigunDamage = 6f;
            art.head = headGo.transform; art.muzzle = muzzleGo.transform;

            const string path = ASSET_ROOT + "/Combat/Prefabs/ArtilleryMinigun.prefab";
            GameObject prefab;
            if (AssetDatabase.LoadMainAssetAtPath(path) != null) { prefab = AssetDatabase.LoadAssetAtPath<GameObject>(path); UnityEngine.Object.DestroyImmediate(root); }
            else { prefab = PrefabUtility.SaveAsPrefabAsset(root, path); UnityEngine.Object.DestroyImmediate(root); }

            var block = GetOrCreateAsset<VoxelEngine.Items.BlockItem>($"{COMBAT_BLOCKS}/Block_ArtilleryMinigun.asset");
            block.itemId = "block_artillery_minigun"; block.displayName = "Minigun Turret";
            block.description = "Rapid-fire 6-barrel minigun turret. Uses Bullets (load into magazine). Auto-targets by faction filter.";
            block.iconTint = new Color(0.28f, 0.28f, 0.30f);
            block.maxStack = 4; block.massPerUnit = 15f;
            block.placedPrefab = prefab; block.gridSize = Vector3Int.one; block.allowStacking = true; block.blockHealth = 150; block.miningTier = 2; block.category = "Combat";
            EditorUtility.SetDirty(block);

            AddRecipe("Recipe_ArtilleryMinigun", "Minigun Turret", block, 1, VoxelEngine.Crafting.StationTier.Assembler, true,
                (ironPlate, 8), (circuit, 4), (copperWire, 8));

            AssetDatabase.SaveAssets(); AssetDatabase.Refresh();
            EditorUtility.DisplayDialog("Voxel Engine — Minigun Turret",
                "The Minigun Turret is built:\n\n• 6-barrel Gatling-style turret (~14 parts)\n• Rapid-fire hitscan (12 shots/sec, 6 dmg each)\n• Uses Bullets (load into magazine via the defense panel)\n• Auto-targets by faction\n• Craft at the Assembler", "OK");
        }

        private void BuildArtilleryGustavContent()
        {
            const string COMBAT_ROOT  = ASSET_ROOT + "/Combat";
            const string COMBAT_ITEMS = COMBAT_ROOT + "/Items";
            const string COMBAT_BLOCKS= COMBAT_ROOT + "/Blocks";
            const string COMBAT_PREFABS=COMBAT_ROOT + "/Prefabs";
            const string COMBAT_MATS  = COMBAT_ROOT + "/Materials";
            EnsureFolder(COMBAT_ROOT); EnsureFolder(COMBAT_ITEMS); EnsureFolder(COMBAT_BLOCKS); EnsureFolder(COMBAT_PREFABS); EnsureFolder(COMBAT_MATS);

            ItemDefinition FindItem(string n)
            {
                var guids = AssetDatabase.FindAssets(n + " t:ItemDefinition");
                foreach (var g in guids) { var pp = AssetDatabase.GUIDToAssetPath(g); if (System.IO.Path.GetFileNameWithoutExtension(pp) == n) return AssetDatabase.LoadAssetAtPath<ItemDefinition>(pp); }
                return null;
            }
            var steelPlate = FindItem("Item_SteelPlate");
            var advCircuit = FindItem("Item_AdvancedCircuit");
            var steelIngot = FindItem("Item_SteelIngot");

            var railMat   = MakeColoredMat(COMBAT_MATS, "Mat_GustavRail", new Color(0.25f, 0.24f, 0.22f));
            var steelMat  = MakeColoredMat(COMBAT_MATS, "Mat_GustavSteel",new Color(0.30f, 0.30f, 0.33f));
            var barrelMat = MakeColoredMat(COMBAT_MATS, "Mat_GustavBarrel",new Color(0.20f, 0.20f, 0.23f));
            var shellMat  = MakeColoredMat(COMBAT_MATS, "Mat_Shell",      new Color(0.25f, 0.25f, 0.28f));
            var explosionMat = MakeColoredMat(COMBAT_MATS, "Mat_Explosion", new Color(1.0f, 0.45f, 0.10f));

            void AddPart(GameObject parent, string n, Vector3 pos, Vector3 euler, Vector3 scale, Material m)
            {
                var go = GameObject.CreatePrimitive(PrimitiveType.Cube);
                go.name = n; go.transform.SetParent(parent.transform, false);
                go.transform.localPosition = pos; go.transform.localEulerAngles = euler; go.transform.localScale = scale;
                go.GetComponent<Renderer>().sharedMaterial = m;
                var col = go.GetComponent<Collider>(); if (col != null) UnityEngine.Object.DestroyImmediate(col);
            }

            var root = new GameObject("ArtilleryGustav");
            // Massive railway flatcar
            AddPart(root, "Flatcar", new Vector3(0f, 0.6f, 0f),   Vector3.zero, new Vector3(3.0f, 0.4f, 8.0f), railMat);
            AddPart(root, "FrontBogie", new Vector3(0f, 0.2f, 2.5f),Vector3.zero,new Vector3(2.0f, 0.5f, 1.5f), steelMat);
            AddPart(root, "RearBogie",  new Vector3(0f, 0.2f, -2.5f),Vector3.zero,new Vector3(2.0f, 0.5f, 1.5f), steelMat);
            AddPart(root, "Rail",       new Vector3(0f, 0.1f, 0f), Vector3.zero, new Vector3(1.5f, 0.1f, 9.0f), railMat);
            // Trunnion mount
            AddPart(root, "Trunnion", new Vector3(0f, 1.3f, 0f),  Vector3.zero, new Vector3(1.5f, 0.9f, 1.2f), steelMat);

            var headGo = new GameObject("Head");
            headGo.transform.SetParent(root.transform, false);
            headGo.transform.localPosition = new Vector3(0f, 1.8f, 0f);
            // Breech (massive)
            AddPart(headGo, "Breech",    new Vector3(0f, 0f, -0.6f), Vector3.zero, new Vector3(1.0f, 1.0f, 0.8f), steelMat);
            // Colossal barrel (800mm — the largest gun ever built)
            AddPart(headGo, "BarrelBase",new Vector3(0f, 0f, 0.2f),  Vector3.zero, new Vector3(0.7f, 0.7f, 1.0f), barrelMat);
            AddPart(headGo, "Barrel",    new Vector3(0f, 0f, 3.8f),  Vector3.zero, new Vector3(0.5f, 0.5f, 6.0f), barrelMat);
            AddPart(headGo, "BarrelTip", new Vector3(0f, 0f, 7.0f),  Vector3.zero, new Vector3(0.55f, 0.55f, 0.3f), barrelMat);
            // Lifting frame
            AddPart(headGo, "FrameL", new Vector3(-0.7f, 0.8f, 1.0f), Vector3.zero, new Vector3(0.1f, 1.5f, 0.1f), steelMat);
            AddPart(headGo, "FrameR", new Vector3( 0.7f, 0.8f, 1.0f), Vector3.zero, new Vector3(0.1f, 1.5f, 0.1f), steelMat);
            var muzzleGo = new GameObject("Muzzle");
            muzzleGo.transform.SetParent(headGo.transform, false);
            muzzleGo.transform.localPosition = new Vector3(0f, 0f, 7.3f);

            var cap = root.AddComponent<CapsuleCollider>();
            cap.height = 3.0f; cap.radius = 1.5f; cap.center = new Vector3(0f, 1.5f, 0f);
            var art = root.AddComponent<VoxelEngine.Combat.Artillery>();
            art.variant = VoxelEngine.Combat.ArtilleryVariant.Gustav;
            art.range = 120f; art.fireCooldown = 12f; art.damage = 500f; art.explosionRadius = 30f; art.shellSpeed = 25f;
            art.shellMat = shellMat; art.explosionMat = explosionMat;
            art.head = headGo.transform; art.muzzle = muzzleGo.transform;

            const string path = ASSET_ROOT + "/Combat/Prefabs/ArtilleryGustav.prefab";
            GameObject prefab;
            if (AssetDatabase.LoadMainAssetAtPath(path) != null) { prefab = AssetDatabase.LoadAssetAtPath<GameObject>(path); UnityEngine.Object.DestroyImmediate(root); }
            else { prefab = PrefabUtility.SaveAsPrefabAsset(root, path); UnityEngine.Object.DestroyImmediate(root); }

            var block = GetOrCreateAsset<VoxelEngine.Items.BlockItem>($"{COMBAT_BLOCKS}/Block_ArtilleryGustav.asset");
            block.itemId = "block_artillery_gustav"; block.displayName = "Schwerer Gustav";
            block.description = "The largest gun ever built. Colossal 800mm railway gun. Fires massive shells that level a huge area. Load shells via the magazine.";
            block.iconTint = new Color(0.25f, 0.24f, 0.22f);
            block.maxStack = 1; block.massPerUnit = 100f;
            block.placedPrefab = prefab; block.gridSize = new Vector3Int(3, 3, 7); block.allowStacking = false; block.blockHealth = 500; block.miningTier = 3; block.category = "Combat";
            EditorUtility.SetDirty(block);

            AddRecipe("Recipe_ArtilleryGustav", "Schwerer Gustav", block, 1, VoxelEngine.Crafting.StationTier.Assembler, true,
                (steelPlate, 30), (advCircuit, 5), (steelIngot, 15));

            AssetDatabase.SaveAssets(); AssetDatabase.Refresh();
            EditorUtility.DisplayDialog("Voxel Engine — Schwerer Gustav",
                "The SCHWERER GUSTAV is built:\n\n• Colossal 800mm railway gun on a flatcar (~14 parts)\n• Range 120m, damage 500, explosion radius 30\n• Slow fire rate (12s reload) — each shell is devastating\n• Load shells via the magazine (Standard / Explosive / Scatter)\n• 500 HP. Craft at the Assembler (steel plate + advanced circuit + steel ingot)", "OK");
        }

        // ============================================================
        //   STEP 41 - FLAMETHROWER TURRET. Close-range area denial.
        //   Continuous cone of fire + ground fire patches. Fuelled by
        //   Flame Canisters (preferred) or Coal (weaker). Uses the
        //   shared defense panel. Non-destructive. Re-runnable.
        // ============================================================
        private void BuildFlamethrowerTurretContent()
        {
            const string COMBAT_ROOT   = ASSET_ROOT + "/Combat";
            const string COMBAT_ITEMS  = COMBAT_ROOT + "/Items";
            const string COMBAT_BLOCKS = COMBAT_ROOT + "/Blocks";
            const string COMBAT_PREFABS= COMBAT_ROOT + "/Prefabs";
            const string COMBAT_MATS   = COMBAT_ROOT + "/Materials";
            EnsureFolder(COMBAT_ROOT); EnsureFolder(COMBAT_ITEMS); EnsureFolder(COMBAT_BLOCKS); EnsureFolder(COMBAT_PREFABS); EnsureFolder(COMBAT_MATS);

            ItemDefinition FindItem(string n)
            {
                var guids = AssetDatabase.FindAssets(n + " t:ItemDefinition");
                foreach (var g in guids) { var pp = AssetDatabase.GUIDToAssetPath(g); if (System.IO.Path.GetFileNameWithoutExtension(pp) == n) return AssetDatabase.LoadAssetAtPath<ItemDefinition>(pp); }
                return null;
            }
            var ironPlate  = FindItem("Item_IronPlate");
            var steelIngot = FindItem("Item_SteelIngot");
            var circuit    = FindItem("Item_Circuit");
            var copperWire = FindItem("Item_CopperLVWire");
            var coal       = FindItem("Item_Coal");

            var body   = MakeColoredMat(COMBAT_MATS, "Mat_FlameTurretBody",  new Color(0.38f, 0.22f, 0.14f));
            var dark   = MakeColoredMat(COMBAT_MATS, "Mat_FlameTurretDark",  new Color(0.18f, 0.16f, 0.14f));
            var tank   = MakeColoredMat(COMBAT_MATS, "Mat_FlameTurretTank",  new Color(0.55f, 0.18f, 0.10f));
            var nozzle = MakeColoredMat(COMBAT_MATS, "Mat_FlameTurretNozzle",new Color(0.25f, 0.25f, 0.28f));
            var flame  = MakeColoredMat(COMBAT_MATS, "Mat_FlameSpray",       new Color(1.0f, 0.45f, 0.12f));
            var ground = MakeColoredMat(COMBAT_MATS, "Mat_GroundFire",       new Color(1.0f, 0.35f, 0.08f));

            void AddPart(GameObject parent, string n, Vector3 pos, Vector3 euler, Vector3 scale, Material m)
            {
                var go = GameObject.CreatePrimitive(PrimitiveType.Cube);
                go.name = n; go.transform.SetParent(parent.transform, false);
                go.transform.localPosition = pos; go.transform.localEulerAngles = euler; go.transform.localScale = scale;
                go.GetComponent<Renderer>().sharedMaterial = m;
                var col = go.GetComponent<Collider>(); if (col != null) UnityEngine.Object.DestroyImmediate(col);
            }
            void AddCyl(GameObject parent, string n, Vector3 pos, Vector3 euler, Vector3 scale, Material m)
            {
                var go = GameObject.CreatePrimitive(PrimitiveType.Cylinder);
                go.name = n; go.transform.SetParent(parent.transform, false);
                go.transform.localPosition = pos; go.transform.localEulerAngles = euler; go.transform.localScale = scale;
                go.GetComponent<Renderer>().sharedMaterial = m;
                var col = go.GetComponent<Collider>(); if (col != null) UnityEngine.Object.DestroyImmediate(col);
            }

            var root = new GameObject("FlamethrowerTurret");
            // Wide base + dual fuel tanks
            AddPart(root, "Base",     new Vector3(0f, 0.12f, 0f), Vector3.zero, new Vector3(0.95f, 0.24f, 0.95f), body);
            AddPart(root, "Pillar",   new Vector3(0f, 0.55f, 0f), Vector3.zero, new Vector3(0.28f, 0.55f, 0.28f), dark);
            AddCyl (root, "TankL",    new Vector3(-0.38f, 0.55f, -0.15f), Vector3.zero, new Vector3(0.28f, 0.35f, 0.28f), tank);
            AddCyl (root, "TankR",    new Vector3( 0.38f, 0.55f, -0.15f), Vector3.zero, new Vector3(0.28f, 0.35f, 0.28f), tank);
            AddPart(root, "HoseL",    new Vector3(-0.25f, 0.85f, 0.05f), new Vector3(0,0,35), new Vector3(0.06f, 0.06f, 0.35f), dark);
            AddPart(root, "HoseR",    new Vector3( 0.25f, 0.85f, 0.05f), new Vector3(0,0,-35), new Vector3(0.06f, 0.06f, 0.35f), dark);
            AddPart(root, "Warning",  new Vector3(0f, 0.28f, 0.48f), Vector3.zero, new Vector3(0.25f, 0.12f, 0.04f), flame);

            // Rotating head with dual nozzles
            var headGo = new GameObject("Head");
            headGo.transform.SetParent(root.transform, false);
            headGo.transform.localPosition = new Vector3(0f, 0.95f, 0.05f);
            AddPart(headGo, "HeadBody",  new Vector3(0f, 0f, 0f),      Vector3.zero, new Vector3(0.5f, 0.32f, 0.45f), body);
            AddPart(headGo, "Shield",    new Vector3(0f, 0.05f, 0.28f), Vector3.zero, new Vector3(0.55f, 0.28f, 0.08f), dark);
            AddCyl (headGo, "NozzleL",   new Vector3(-0.12f, 0.02f, 0.45f), new Vector3(90,0,0), new Vector3(0.12f, 0.28f, 0.12f), nozzle);
            AddCyl (headGo, "NozzleR",   new Vector3( 0.12f, 0.02f, 0.45f), new Vector3(90,0,0), new Vector3(0.12f, 0.28f, 0.12f), nozzle);
            AddPart(headGo, "PilotLight",new Vector3(0f, 0.12f, 0.55f), Vector3.zero, new Vector3(0.06f, 0.06f, 0.06f), flame);

            var muzzleGo = new GameObject("Muzzle");
            muzzleGo.transform.SetParent(headGo.transform, false);
            muzzleGo.transform.localPosition = new Vector3(0f, 0.02f, 0.75f);

            var cap = root.AddComponent<CapsuleCollider>();
            cap.height = 1.5f; cap.radius = 0.5f; cap.center = new Vector3(0f, 0.65f, 0f);
            var ft = root.AddComponent<VoxelEngine.Combat.FlamethrowerTurret>();
            ft.range = 11f; ft.coneHalfAngle = 28f; ft.tickInterval = 0.18f;
            ft.damagePerTick = 7f; ft.burnDps = 5f; ft.burnDuration = 2.5f;
            ft.fuelSecondsPerCanister = 8f; ft.coalSecondsBonus = 2.5f;
            ft.flameMat = flame; ft.groundFireMat = ground;
            ft.head = headGo.transform; ft.muzzle = muzzleGo.transform;

            const string path = ASSET_ROOT + "/Combat/Prefabs/FlamethrowerTurret.prefab";
            GameObject prefab;
            if (AssetDatabase.LoadMainAssetAtPath(path) != null) { prefab = AssetDatabase.LoadAssetAtPath<GameObject>(path); UnityEngine.Object.DestroyImmediate(root); }
            else { prefab = PrefabUtility.SaveAsPrefabAsset(root, path); UnityEngine.Object.DestroyImmediate(root); }

            var block = GetOrCreateAsset<VoxelEngine.Items.BlockItem>($"{COMBAT_BLOCKS}/Block_FlamethrowerTurret.asset");
            block.itemId = "block_flamethrower_turret"; block.displayName = "Flamethrower Turret";
            block.description = "Close-range area-denial turret. Sprays a continuous cone of fire and leaves ground-fire patches. Load Flame Canisters (or Coal) via the defense panel (RMB).";
            block.iconTint = new Color(0.85f, 0.35f, 0.12f);
            block.maxStack = 4; block.massPerUnit = 8f;
            block.placedPrefab = prefab; block.gridSize = Vector3Int.one; block.allowStacking = true; block.blockHealth = 100; block.miningTier = 2; block.category = "Combat";
            EditorUtility.SetDirty(block);

            // Flame Canister ammo item
            var canister = GetOrCreateAsset<VoxelEngine.Items.ItemDefinition>($"{COMBAT_ITEMS}/Item_FlameCanister.asset");
            canister.itemId = "item_flame_canister"; canister.displayName = "Flame Canister";
            canister.description = "Pressurized flammable fuel canister. Feeds Flamethrower Turrets (~8 s of continuous fire each).";
            canister.iconTint = new Color(0.90f, 0.40f, 0.12f); canister.maxStack = 20; canister.massPerUnit = 1.5f; canister.category = "Combat";
            EditorUtility.SetDirty(canister);

            AddRecipe("Recipe_FlamethrowerTurret", "Flamethrower Turret", block, 1, VoxelEngine.Crafting.StationTier.Assembler, true,
                (ironPlate, 8), (steelIngot, 3), (circuit, 2), (copperWire, 4));
            AddRecipe("Recipe_FlameCanister", "Flame Canister", canister, 4, VoxelEngine.Crafting.StationTier.Assembler, true,
                (ironPlate, 1), (coal, 3));

            AssetDatabase.SaveAssets(); AssetDatabase.Refresh();
            EditorUtility.DisplayDialog("Voxel Engine — Flamethrower Turret",
                "The Flamethrower Turret is built:\n\n" +
                "• Dual-nozzle turret with fuel tanks (~14 parts)\n" +
                "• Continuous cone of fire (range ~11 m) + lingering ground fire\n" +
                "• Fuelled by Flame Canisters (8 s each) or Coal (weaker)\n" +
                "• Auto-targets by faction via the defense panel (RMB)\n" +
                "• 100 HP. Craft at the Assembler\n" +
                "• Also crafts Flame Canisters (iron plate + coal)", "OK");
        }

        // ============================================================
        //   STEP 42 - MORTAR TURRET. Indirect high-arc fire over walls
        //   and terrain. Explosive / Smoke / Illumination shells loaded
        //   via the defense panel. No LOS required. Non-destructive.
        // ============================================================
        private void BuildMortarTurretContent()
        {
            const string COMBAT_ROOT   = ASSET_ROOT + "/Combat";
            const string COMBAT_ITEMS  = COMBAT_ROOT + "/Items";
            const string COMBAT_BLOCKS = COMBAT_ROOT + "/Blocks";
            const string COMBAT_PREFABS= COMBAT_ROOT + "/Prefabs";
            const string COMBAT_MATS   = COMBAT_ROOT + "/Materials";
            EnsureFolder(COMBAT_ROOT); EnsureFolder(COMBAT_ITEMS); EnsureFolder(COMBAT_BLOCKS); EnsureFolder(COMBAT_PREFABS); EnsureFolder(COMBAT_MATS);

            ItemDefinition FindItem(string n)
            {
                var guids = AssetDatabase.FindAssets(n + " t:ItemDefinition");
                foreach (var g in guids) { var pp = AssetDatabase.GUIDToAssetPath(g); if (System.IO.Path.GetFileNameWithoutExtension(pp) == n) return AssetDatabase.LoadAssetAtPath<ItemDefinition>(pp); }
                return null;
            }
            var ironPlate  = FindItem("Item_IronPlate");
            var steelIngot = FindItem("Item_SteelIngot");
            var circuit    = FindItem("Item_Circuit");
            var copperWire = FindItem("Item_CopperLVWire");
            var coal       = FindItem("Item_Coal");

            var body   = MakeColoredMat(COMBAT_MATS, "Mat_MortarBody",   new Color(0.30f, 0.32f, 0.22f));
            var dark   = MakeColoredMat(COMBAT_MATS, "Mat_MortarDark",   new Color(0.18f, 0.18f, 0.16f));
            var tube   = MakeColoredMat(COMBAT_MATS, "Mat_MortarTube",   new Color(0.24f, 0.24f, 0.26f));
            var shell  = MakeColoredMat(COMBAT_MATS, "Mat_MortarShell",  new Color(0.28f, 0.30f, 0.22f));
            var boom   = MakeColoredMat(COMBAT_MATS, "Mat_Explosion",    new Color(1.0f, 0.45f, 0.10f));
            var smoke  = MakeColoredMat(COMBAT_MATS, "Mat_MortarSmoke",  new Color(0.45f, 0.45f, 0.42f));
            var flare  = MakeColoredMat(COMBAT_MATS, "Mat_MortarFlare",  new Color(1.0f, 0.92f, 0.55f));

            void AddPart(GameObject parent, string n, Vector3 pos, Vector3 euler, Vector3 scale, Material m)
            {
                var go = GameObject.CreatePrimitive(PrimitiveType.Cube);
                go.name = n; go.transform.SetParent(parent.transform, false);
                go.transform.localPosition = pos; go.transform.localEulerAngles = euler; go.transform.localScale = scale;
                go.GetComponent<Renderer>().sharedMaterial = m;
                var col = go.GetComponent<Collider>(); if (col != null) UnityEngine.Object.DestroyImmediate(col);
            }
            void AddCyl(GameObject parent, string n, Vector3 pos, Vector3 euler, Vector3 scale, Material m)
            {
                var go = GameObject.CreatePrimitive(PrimitiveType.Cylinder);
                go.name = n; go.transform.SetParent(parent.transform, false);
                go.transform.localPosition = pos; go.transform.localEulerAngles = euler; go.transform.localScale = scale;
                go.GetComponent<Renderer>().sharedMaterial = m;
                var col = go.GetComponent<Collider>(); if (col != null) UnityEngine.Object.DestroyImmediate(col);
            }

            var root = new GameObject("MortarTurret");
            AddPart(root, "BasePlate", new Vector3(0f, 0.06f, 0f), Vector3.zero, new Vector3(0.9f, 0.12f, 0.9f), body);
            AddPart(root, "BipodL",    new Vector3(-0.35f, 0.35f, 0.15f), new Vector3(0, 0, 25), new Vector3(0.08f, 0.7f, 0.08f), dark);
            AddPart(root, "BipodR",    new Vector3( 0.35f, 0.35f, 0.15f), new Vector3(0, 0,-25), new Vector3(0.08f, 0.7f, 0.08f), dark);
            AddPart(root, "Trail",     new Vector3(0f, 0.12f, -0.45f), new Vector3(15, 0, 0), new Vector3(0.12f, 0.08f, 0.7f), body);
            AddPart(root, "AmmoBox",   new Vector3(0.45f, 0.25f, -0.1f), Vector3.zero, new Vector3(0.28f, 0.22f, 0.35f), dark);

            var headGo = new GameObject("Head");
            headGo.transform.SetParent(root.transform, false);
            headGo.transform.localPosition = new Vector3(0f, 0.55f, 0.05f);
            headGo.transform.localEulerAngles = new Vector3(-55f, 0f, 0f);
            AddCyl (headGo, "Tube",       new Vector3(0f, 0f, 0.45f), new Vector3(90, 0, 0), new Vector3(0.22f, 0.55f, 0.22f), tube);
            AddCyl (headGo, "Breech",     new Vector3(0f, 0f, -0.15f), new Vector3(90, 0, 0), new Vector3(0.28f, 0.18f, 0.28f), body);
            AddPart(headGo, "Sight",      new Vector3(0.12f, 0.12f, 0.1f), Vector3.zero, new Vector3(0.05f, 0.08f, 0.12f), dark);
            AddPart(headGo, "MuzzleRing", new Vector3(0f, 0f, 1.05f), Vector3.zero, new Vector3(0.26f, 0.26f, 0.06f), dark);

            var muzzleGo = new GameObject("Muzzle");
            muzzleGo.transform.SetParent(headGo.transform, false);
            muzzleGo.transform.localPosition = new Vector3(0f, 0f, 1.15f);

            var cap = root.AddComponent<CapsuleCollider>();
            cap.height = 1.3f; cap.radius = 0.45f; cap.center = new Vector3(0f, 0.5f, 0f);
            var mt = root.AddComponent<VoxelEngine.Combat.MortarTurret>();
            mt.range = 55f; mt.minRange = 8f; mt.fireCooldown = 3.2f;
            mt.damage = 45f; mt.explosionRadius = 7f; mt.shellSpeed = 22f; mt.lobHeight = 18f;
            mt.shellMat = shell; mt.explosionMat = boom; mt.smokeMat = smoke; mt.flareMat = flare;
            mt.head = headGo.transform; mt.muzzle = muzzleGo.transform;

            const string path = ASSET_ROOT + "/Combat/Prefabs/MortarTurret.prefab";
            GameObject prefab;
            if (AssetDatabase.LoadMainAssetAtPath(path) != null) { prefab = AssetDatabase.LoadAssetAtPath<GameObject>(path); UnityEngine.Object.DestroyImmediate(root); }
            else { prefab = PrefabUtility.SaveAsPrefabAsset(root, path); UnityEngine.Object.DestroyImmediate(root); }

            var block = GetOrCreateAsset<VoxelEngine.Items.BlockItem>($"{COMBAT_BLOCKS}/Block_MortarTurret.asset");
            block.itemId = "block_mortar_turret"; block.displayName = "Mortar Turret";
            block.description = "Indirect-fire mortar. Lobs Explosive, Smoke, or Illumination shells over walls and terrain (no LOS needed). Load shells via the defense panel (RMB).";
            block.iconTint = new Color(0.30f, 0.32f, 0.22f);
            block.maxStack = 4; block.massPerUnit = 10f;
            block.placedPrefab = prefab; block.gridSize = Vector3Int.one; block.allowStacking = true; block.blockHealth = 120; block.miningTier = 2; block.category = "Combat";
            EditorUtility.SetDirty(block);

            var shExp = GetOrCreateAsset<VoxelEngine.Items.ItemDefinition>($"{COMBAT_ITEMS}/Item_MortarExplosive.asset");
            shExp.itemId = "item_mortar_explosive"; shExp.displayName = "Mortar Shell (Explosive)";
            shExp.description = "High-explosive mortar round. Lobs over walls; detonates on impact with a modest crater.";
            shExp.iconTint = new Color(0.80f, 0.35f, 0.12f); shExp.maxStack = 20; shExp.massPerUnit = 1.8f; shExp.category = "Combat";
            EditorUtility.SetDirty(shExp);

            var shSmoke = GetOrCreateAsset<VoxelEngine.Items.ItemDefinition>($"{COMBAT_ITEMS}/Item_MortarSmoke.asset");
            shSmoke.itemId = "item_mortar_smoke"; shSmoke.displayName = "Mortar Shell (Smoke)";
            shSmoke.description = "Smoke mortar round. Deploys a lingering smoke cloud for cover and marking.";
            shSmoke.iconTint = new Color(0.55f, 0.55f, 0.52f); shSmoke.maxStack = 20; shSmoke.massPerUnit = 1.5f; shSmoke.category = "Combat";
            EditorUtility.SetDirty(shSmoke);

            var shIllum = GetOrCreateAsset<VoxelEngine.Items.ItemDefinition>($"{COMBAT_ITEMS}/Item_MortarIllum.asset");
            shIllum.itemId = "item_mortar_illum"; shIllum.displayName = "Mortar Shell (Illumination)";
            shIllum.description = "Illumination mortar round. Deploys a bright falling flare that lights the battlefield.";
            shIllum.iconTint = new Color(1.0f, 0.92f, 0.55f); shIllum.maxStack = 20; shIllum.massPerUnit = 1.5f; shIllum.category = "Combat";
            EditorUtility.SetDirty(shIllum);

            AddRecipe("Recipe_MortarTurret", "Mortar Turret", block, 1, VoxelEngine.Crafting.StationTier.Assembler, true,
                (ironPlate, 8), (steelIngot, 4), (circuit, 2), (copperWire, 4));
            AddRecipe("Recipe_MortarExplosive", "Mortar Shell (Explosive)", shExp, 4, VoxelEngine.Crafting.StationTier.Assembler, true,
                (ironPlate, 2), (coal, 2));
            AddRecipe("Recipe_MortarSmoke", "Mortar Shell (Smoke)", shSmoke, 4, VoxelEngine.Crafting.StationTier.Assembler, true,
                (ironPlate, 1), (coal, 1), (copperWire, 1));
            AddRecipe("Recipe_MortarIllum", "Mortar Shell (Illumination)", shIllum, 4, VoxelEngine.Crafting.StationTier.Assembler, true,
                (ironPlate, 1), (circuit, 1), (copperWire, 2));

            AssetDatabase.SaveAssets(); AssetDatabase.Refresh();
            EditorUtility.DisplayDialog("Voxel Engine — Mortar Turret",
                "The Mortar Turret is built:\n\n" +
                "• Bipod mortar with elevating tube (~12 parts)\n" +
                "• Indirect high-arc fire (range ~8–55 m, no LOS needed)\n" +
                "• Shells: Explosive / Smoke / Illumination\n" +
                "• Auto-targets by faction via the defense panel (RMB)\n" +
                "• 120 HP. Craft at the Assembler\n" +
                "• Also crafts all three mortar shell types", "OK");
        }

        // ============================================================
        //   STEP 43 - GIANT SHELL TURRET. Slow siege gun for bosses
        //   and fortified positions. Fires factory-built Giant Shells
        //   one at a time. Prefers high-HP targets. Non-destructive.
        // ============================================================
        private void BuildGiantShellTurretContent()
        {
            const string COMBAT_ROOT   = ASSET_ROOT + "/Combat";
            const string COMBAT_ITEMS  = COMBAT_ROOT + "/Items";
            const string COMBAT_BLOCKS = COMBAT_ROOT + "/Blocks";
            const string COMBAT_PREFABS= COMBAT_ROOT + "/Prefabs";
            const string COMBAT_MATS   = COMBAT_ROOT + "/Materials";
            EnsureFolder(COMBAT_ROOT); EnsureFolder(COMBAT_ITEMS); EnsureFolder(COMBAT_BLOCKS); EnsureFolder(COMBAT_PREFABS); EnsureFolder(COMBAT_MATS);

            ItemDefinition FindItem(string n)
            {
                var guids = AssetDatabase.FindAssets(n + " t:ItemDefinition");
                foreach (var g in guids) { var pp = AssetDatabase.GUIDToAssetPath(g); if (System.IO.Path.GetFileNameWithoutExtension(pp) == n) return AssetDatabase.LoadAssetAtPath<ItemDefinition>(pp); }
                return null;
            }
            var ironPlate  = FindItem("Item_IronPlate");
            var steelPlate = FindItem("Item_SteelPlate");
            var steelIngot = FindItem("Item_SteelIngot");
            var circuit    = FindItem("Item_Circuit");
            var advCircuit = FindItem("Item_AdvancedCircuit");
            var coal       = FindItem("Item_Coal");

            var body   = MakeColoredMat(COMBAT_MATS, "Mat_GiantShellBody",   new Color(0.28f, 0.26f, 0.22f));
            var dark   = MakeColoredMat(COMBAT_MATS, "Mat_GiantShellDark",   new Color(0.16f, 0.15f, 0.14f));
            var barrel = MakeColoredMat(COMBAT_MATS, "Mat_GiantShellBarrel", new Color(0.22f, 0.22f, 0.24f));
            var shell  = MakeColoredMat(COMBAT_MATS, "Mat_GiantShellRound",  new Color(0.32f, 0.30f, 0.26f));
            var boom   = MakeColoredMat(COMBAT_MATS, "Mat_Explosion",        new Color(1.0f, 0.45f, 0.10f));

            void AddPart(GameObject parent, string n, Vector3 pos, Vector3 euler, Vector3 scale, Material m)
            {
                var go = GameObject.CreatePrimitive(PrimitiveType.Cube);
                go.name = n; go.transform.SetParent(parent.transform, false);
                go.transform.localPosition = pos; go.transform.localEulerAngles = euler; go.transform.localScale = scale;
                go.GetComponent<Renderer>().sharedMaterial = m;
                var col = go.GetComponent<Collider>(); if (col != null) UnityEngine.Object.DestroyImmediate(col);
            }
            void AddCyl(GameObject parent, string n, Vector3 pos, Vector3 euler, Vector3 scale, Material m)
            {
                var go = GameObject.CreatePrimitive(PrimitiveType.Cylinder);
                go.name = n; go.transform.SetParent(parent.transform, false);
                go.transform.localPosition = pos; go.transform.localEulerAngles = euler; go.transform.localScale = scale;
                go.GetComponent<Renderer>().sharedMaterial = m;
                var col = go.GetComponent<Collider>(); if (col != null) UnityEngine.Object.DestroyImmediate(col);
            }

            var root = new GameObject("GiantShellTurret");
            AddPart(root, "Base",      new Vector3(0f, 0.2f, 0f),  Vector3.zero, new Vector3(1.6f, 0.4f, 1.6f), body);
            AddPart(root, "Skirt",     new Vector3(0f, 0.45f, 0f), Vector3.zero, new Vector3(1.3f, 0.15f, 1.3f), dark);
            AddCyl (root, "Ring",      new Vector3(0f, 0.6f, 0f),  Vector3.zero, new Vector3(1.1f, 0.12f, 1.1f), body);
            AddPart(root, "BraceL",    new Vector3(-0.7f, 0.5f, -0.5f), new Vector3(0, 20, 0), new Vector3(0.15f, 0.5f, 0.8f), dark);
            AddPart(root, "BraceR",    new Vector3( 0.7f, 0.5f, -0.5f), new Vector3(0,-20, 0), new Vector3(0.15f, 0.5f, 0.8f), dark);
            AddPart(root, "ShellRack", new Vector3(0.85f, 0.55f, 0.2f), Vector3.zero, new Vector3(0.35f, 0.5f, 0.7f), dark);

            var headGo = new GameObject("Head");
            headGo.transform.SetParent(root.transform, false);
            headGo.transform.localPosition = new Vector3(0f, 0.95f, 0f);
            AddPart(headGo, "Cradle",     new Vector3(0f, 0f, -0.1f), Vector3.zero, new Vector3(0.7f, 0.55f, 0.8f), body);
            AddPart(headGo, "Breech",     new Vector3(0f, 0.05f, -0.55f), Vector3.zero, new Vector3(0.55f, 0.5f, 0.5f), dark);
            AddCyl (headGo, "Barrel",     new Vector3(0f, 0.08f, 1.1f), new Vector3(90, 0, 0), new Vector3(0.38f, 1.3f, 0.38f), barrel);
            AddCyl (headGo, "BarrelTip",  new Vector3(0f, 0.08f, 2.5f), new Vector3(90, 0, 0), new Vector3(0.42f, 0.18f, 0.42f), dark);
            AddPart(headGo, "RecoilRail", new Vector3(0f, 0.35f, 0.6f), Vector3.zero, new Vector3(0.12f, 0.12f, 1.4f), dark);
            AddPart(headGo, "Sight",      new Vector3(0.2f, 0.35f, 0.1f), Vector3.zero, new Vector3(0.08f, 0.1f, 0.15f), body);

            var muzzleGo = new GameObject("Muzzle");
            muzzleGo.transform.SetParent(headGo.transform, false);
            muzzleGo.transform.localPosition = new Vector3(0f, 0.08f, 2.75f);

            var cap = root.AddComponent<CapsuleCollider>();
            cap.height = 2.2f; cap.radius = 0.85f; cap.center = new Vector3(0f, 0.9f, 0f);
            var gt = root.AddComponent<VoxelEngine.Combat.GiantShellTurret>();
            gt.range = 90f; gt.fireCooldown = 8f; gt.damage = 280f; gt.explosionRadius = 14f;
            gt.shellSpeed = 42f; gt.aimConeDegrees = 8f; gt.aimSpeed = 1.4f;
            gt.shellMat = shell; gt.explosionMat = boom;
            gt.head = headGo.transform; gt.muzzle = muzzleGo.transform;

            const string path = ASSET_ROOT + "/Combat/Prefabs/GiantShellTurret.prefab";
            GameObject prefab;
            if (AssetDatabase.LoadMainAssetAtPath(path) != null) { prefab = AssetDatabase.LoadAssetAtPath<GameObject>(path); UnityEngine.Object.DestroyImmediate(root); }
            else { prefab = PrefabUtility.SaveAsPrefabAsset(root, path); UnityEngine.Object.DestroyImmediate(root); }

            var block = GetOrCreateAsset<VoxelEngine.Items.BlockItem>($"{COMBAT_BLOCKS}/Block_GiantShellTurret.asset");
            block.itemId = "block_giant_shell_turret"; block.displayName = "Giant Shell Turret";
            block.description = "Siege turret for bosses and fortified positions. Slow aim, devastating single shells. Load Giant Shells via the defense panel (RMB). Prefers high-HP targets.";
            block.iconTint = new Color(0.28f, 0.26f, 0.22f);
            block.maxStack = 2; block.massPerUnit = 35f;
            block.placedPrefab = prefab; block.gridSize = new Vector3Int(2, 2, 2); block.allowStacking = false; block.blockHealth = 280; block.miningTier = 3; block.category = "Combat";
            EditorUtility.SetDirty(block);

            var giantShell = GetOrCreateAsset<VoxelEngine.Items.ItemDefinition>($"{COMBAT_ITEMS}/Item_GiantShell.asset");
            giantShell.itemId = "item_giant_shell"; giantShell.displayName = "Giant Shell";
            giantShell.description = "Factory-built heavy siege shell. One round levels a wide area — load into a Giant Shell Turret.";
            giantShell.iconTint = new Color(0.35f, 0.32f, 0.25f); giantShell.maxStack = 10; giantShell.massPerUnit = 8f; giantShell.category = "Combat";
            EditorUtility.SetDirty(giantShell);

            AddRecipe("Recipe_GiantShellTurret", "Giant Shell Turret", block, 1, VoxelEngine.Crafting.StationTier.Assembler, true,
                (steelPlate != null ? steelPlate : ironPlate, 16),
                (steelIngot, 10),
                (advCircuit != null ? advCircuit : circuit, 4),
                (ironPlate, 8));
            AddRecipe("Recipe_GiantShell", "Giant Shell", giantShell, 2, VoxelEngine.Crafting.StationTier.Assembler, true,
                (steelIngot, 3), (ironPlate, 4), (coal, 3));

            AssetDatabase.SaveAssets(); AssetDatabase.Refresh();
            EditorUtility.DisplayDialog("Voxel Engine — Giant Shell Turret",
                "The Giant Shell Turret is built:\n\n" +
                "• Massive siege gun on a traverse ring (~14 parts)\n" +
                "• Slow tracking, range ~90 m, damage 280, blast radius 14\n" +
                "• Fires factory-built Giant Shells one at a time\n" +
                "• Prefers bosses / high-HP targets when several are in range\n" +
                "• 280 HP. Craft at the Assembler\n" +
                "• Also crafts Giant Shells (steel + iron + coal)", "OK");
        }

        // ============================================================
        //   STEP 44 - ANTI-AIR TURRET. Fast dual-barrel flak for aerial
        //   threats (Griffin, Roc, high-altitude). Proximity fuse rounds.
        //   Non-destructive. Re-runnable. Idempotent.
        // ============================================================
        private void BuildAntiAirTurretContent()
        {
            const string COMBAT_ROOT   = ASSET_ROOT + "/Combat";
            const string COMBAT_ITEMS  = COMBAT_ROOT + "/Items";
            const string COMBAT_BLOCKS = COMBAT_ROOT + "/Blocks";
            const string COMBAT_PREFABS= COMBAT_ROOT + "/Prefabs";
            const string COMBAT_MATS   = COMBAT_ROOT + "/Materials";
            EnsureFolder(COMBAT_ROOT); EnsureFolder(COMBAT_ITEMS); EnsureFolder(COMBAT_BLOCKS); EnsureFolder(COMBAT_PREFABS); EnsureFolder(COMBAT_MATS);

            ItemDefinition FindItem(string n)
            {
                var guids = AssetDatabase.FindAssets(n + " t:ItemDefinition");
                foreach (var g in guids) { var pp = AssetDatabase.GUIDToAssetPath(g); if (System.IO.Path.GetFileNameWithoutExtension(pp) == n) return AssetDatabase.LoadAssetAtPath<ItemDefinition>(pp); }
                return null;
            }
            var ironPlate  = FindItem("Item_IronPlate");
            var steelIngot = FindItem("Item_SteelIngot");
            var circuit    = FindItem("Item_Circuit");
            var copperWire = FindItem("Item_CopperLVWire");
            var coal       = FindItem("Item_Coal");

            var body   = MakeColoredMat(COMBAT_MATS, "Mat_AABody",   new Color(0.25f, 0.32f, 0.38f));
            var dark   = MakeColoredMat(COMBAT_MATS, "Mat_AADark",   new Color(0.14f, 0.16f, 0.18f));
            var barrel = MakeColoredMat(COMBAT_MATS, "Mat_AABarrel", new Color(0.20f, 0.22f, 0.26f));
            var round  = MakeColoredMat(COMBAT_MATS, "Mat_AARound",  new Color(0.55f, 0.90f, 1.0f));
            var boom   = MakeColoredMat(COMBAT_MATS, "Mat_Explosion",new Color(1.0f, 0.45f, 0.10f));
            var tracer = MakeColoredMat(COMBAT_MATS, "Mat_AATracer", new Color(0.45f, 0.95f, 1.0f));

            void AddPart(GameObject parent, string n, Vector3 pos, Vector3 euler, Vector3 scale, Material m)
            {
                var go = GameObject.CreatePrimitive(PrimitiveType.Cube);
                go.name = n; go.transform.SetParent(parent.transform, false);
                go.transform.localPosition = pos; go.transform.localEulerAngles = euler; go.transform.localScale = scale;
                go.GetComponent<Renderer>().sharedMaterial = m;
                var col = go.GetComponent<Collider>(); if (col != null) UnityEngine.Object.DestroyImmediate(col);
            }
            void AddCyl(GameObject parent, string n, Vector3 pos, Vector3 euler, Vector3 scale, Material m)
            {
                var go = GameObject.CreatePrimitive(PrimitiveType.Cylinder);
                go.name = n; go.transform.SetParent(parent.transform, false);
                go.transform.localPosition = pos; go.transform.localEulerAngles = euler; go.transform.localScale = scale;
                go.GetComponent<Renderer>().sharedMaterial = m;
                var col = go.GetComponent<Collider>(); if (col != null) UnityEngine.Object.DestroyImmediate(col);
            }

            var root = new GameObject("AntiAirTurret");
            AddPart(root, "Base",    new Vector3(0f, 0.12f, 0f), Vector3.zero, new Vector3(1.0f, 0.24f, 1.0f), body);
            AddCyl (root, "Pedestal",new Vector3(0f, 0.5f, 0f),  Vector3.zero, new Vector3(0.35f, 0.35f, 0.35f), dark);
            AddPart(root, "Radar",   new Vector3(0f, 0.95f, -0.25f), Vector3.zero, new Vector3(0.5f, 0.08f, 0.5f), body);
            AddPart(root, "Dish",    new Vector3(0f, 1.05f, -0.25f), Vector3.zero, new Vector3(0.35f, 0.06f, 0.2f), tracer);

            var headGo = new GameObject("Head");
            headGo.transform.SetParent(root.transform, false);
            headGo.transform.localPosition = new Vector3(0f, 0.85f, 0.05f);
            AddPart(headGo, "HeadBody", new Vector3(0f, 0f, 0f), Vector3.zero, new Vector3(0.55f, 0.35f, 0.45f), body);
            // Dual barrels
            AddCyl (headGo, "BarrelL", new Vector3(-0.12f, 0.05f, 0.55f), new Vector3(90,0,0), new Vector3(0.1f, 0.55f, 0.1f), barrel);
            AddCyl (headGo, "BarrelR", new Vector3( 0.12f, 0.05f, 0.55f), new Vector3(90,0,0), new Vector3(0.1f, 0.55f, 0.1f), barrel);
            AddPart(headGo, "Mantlet", new Vector3(0f, 0.05f, 0.25f), Vector3.zero, new Vector3(0.4f, 0.25f, 0.12f), dark);
            AddPart(headGo, "Sight",   new Vector3(0f, 0.22f, 0.1f), Vector3.zero, new Vector3(0.08f, 0.08f, 0.12f), tracer);

            var muzzleGo = new GameObject("Muzzle");
            muzzleGo.transform.SetParent(headGo.transform, false);
            muzzleGo.transform.localPosition = new Vector3(0f, 0.05f, 1.15f);

            var cap = root.AddComponent<CapsuleCollider>();
            cap.height = 1.5f; cap.radius = 0.5f; cap.center = new Vector3(0f, 0.65f, 0f);
            var aa = root.AddComponent<VoxelEngine.Combat.AntiAirTurret>();
            aa.range = 55f; aa.fireCooldown = 0.28f; aa.damage = 14f; aa.proximityRadius = 3.2f;
            aa.shellSpeed = 55f; aa.aimSpeed = 9f; aa.preferAerialOnly = true;
            aa.shellMat = round; aa.explosionMat = boom; aa.tracerMat = tracer;
            aa.head = headGo.transform; aa.muzzle = muzzleGo.transform;

            const string path = ASSET_ROOT + "/Combat/Prefabs/AntiAirTurret.prefab";
            GameObject prefab;
            if (AssetDatabase.LoadMainAssetAtPath(path) != null) { prefab = AssetDatabase.LoadAssetAtPath<GameObject>(path); UnityEngine.Object.DestroyImmediate(root); }
            else { prefab = PrefabUtility.SaveAsPrefabAsset(root, path); UnityEngine.Object.DestroyImmediate(root); }

            var block = GetOrCreateAsset<VoxelEngine.Items.BlockItem>($"{COMBAT_BLOCKS}/Block_AntiAirTurret.asset");
            block.itemId = "block_anti_air_turret"; block.displayName = "Anti-Air Turret";
            block.description = "Fast dual-barrel flak turret. Prefers aerial targets (Griffin, Roc, high-altitude). Fires proximity-burst AA Rounds. Configure via the defense panel (RMB).";
            block.iconTint = new Color(0.25f, 0.45f, 0.55f);
            block.maxStack = 4; block.massPerUnit = 12f;
            block.placedPrefab = prefab; block.gridSize = Vector3Int.one; block.allowStacking = true; block.blockHealth = 140; block.miningTier = 2; block.category = "Combat";
            EditorUtility.SetDirty(block);

            var aaRounds = GetOrCreateAsset<VoxelEngine.Items.ItemDefinition>($"{COMBAT_ITEMS}/Item_AARounds.asset");
            aaRounds.itemId = "item_aa_rounds"; aaRounds.displayName = "AA Rounds";
            aaRounds.description = "Proximity-fuse anti-air rounds for the Anti-Air Turret. Burst near flyers.";
            aaRounds.iconTint = new Color(0.45f, 0.9f, 1.0f); aaRounds.maxStack = 50; aaRounds.massPerUnit = 0.4f; aaRounds.category = "Combat";
            EditorUtility.SetDirty(aaRounds);

            AddRecipe("Recipe_AntiAirTurret", "Anti-Air Turret", block, 1, VoxelEngine.Crafting.StationTier.Assembler, true,
                (ironPlate, 10), (steelIngot, 4), (circuit, 3), (copperWire, 6));
            AddRecipe("Recipe_AARounds", "AA Rounds", aaRounds, 10, VoxelEngine.Crafting.StationTier.Assembler, true,
                (ironPlate, 1), (copperWire, 2), (coal, 1));

            AssetDatabase.SaveAssets(); AssetDatabase.Refresh();
            EditorUtility.DisplayDialog("Voxel Engine — Anti-Air Turret",
                "The Anti-Air Turret is built:\n\n" +
                "• Dual-barrel flak turret with radar dish (~12 parts)\n" +
                "• Fast tracking, range ~55 m, proximity-burst flak\n" +
                "• Prefers aerial targets (Griffin / Roc / high altitude)\n" +
                "• Aerial-Only toggle on the defense panel\n" +
                "• Uses AA Rounds (Bullets also accepted as fallback)\n" +
                "• 140 HP. Craft at the Assembler", "OK");
        }

        // ============================================================
        //   STEP 45 - ENERGY / RELIC TURRET. Late-tier electrical beam
        //   defense. Charged Cells + Relic Capacitors. Non-destructive.
        // ============================================================
        private void BuildEnergyRelicTurretContent()
        {
            const string COMBAT_ROOT   = ASSET_ROOT + "/Combat";
            const string COMBAT_ITEMS  = COMBAT_ROOT + "/Items";
            const string COMBAT_BLOCKS = COMBAT_ROOT + "/Blocks";
            const string COMBAT_PREFABS= COMBAT_ROOT + "/Prefabs";
            const string COMBAT_MATS   = COMBAT_ROOT + "/Materials";
            EnsureFolder(COMBAT_ROOT); EnsureFolder(COMBAT_ITEMS); EnsureFolder(COMBAT_BLOCKS); EnsureFolder(COMBAT_PREFABS); EnsureFolder(COMBAT_MATS);

            ItemDefinition FindItem(string n)
            {
                var guids = AssetDatabase.FindAssets(n + " t:ItemDefinition");
                foreach (var g in guids) { var pp = AssetDatabase.GUIDToAssetPath(g); if (System.IO.Path.GetFileNameWithoutExtension(pp) == n) return AssetDatabase.LoadAssetAtPath<ItemDefinition>(pp); }
                return null;
            }
            var ironPlate  = FindItem("Item_IronPlate");
            var steelPlate = FindItem("Item_SteelPlate");
            var steelIngot = FindItem("Item_SteelIngot");
            var circuit    = FindItem("Item_Circuit");
            var advCircuit = FindItem("Item_AdvancedCircuit");
            var goldWire   = FindItem("Item_GoldLVWire");
            var copperWire = FindItem("Item_CopperLVWire");

            var body   = MakeColoredMat(COMBAT_MATS, "Mat_EnergyBody",   new Color(0.18f, 0.20f, 0.28f));
            var dark   = MakeColoredMat(COMBAT_MATS, "Mat_EnergyDark",   new Color(0.10f, 0.11f, 0.14f));
            var accent = MakeColoredMat(COMBAT_MATS, "Mat_EnergyAccent", new Color(0.35f, 0.75f, 0.95f));
            var relic  = MakeColoredMat(COMBAT_MATS, "Mat_RelicCrystal", new Color(0.70f, 0.40f, 1.0f));
            var beam   = MakeColoredMat(COMBAT_MATS, "Mat_EnergyBeam",   new Color(0.45f, 0.90f, 1.0f));

            void AddPart(GameObject parent, string n, Vector3 pos, Vector3 euler, Vector3 scale, Material m)
            {
                var go = GameObject.CreatePrimitive(PrimitiveType.Cube);
                go.name = n; go.transform.SetParent(parent.transform, false);
                go.transform.localPosition = pos; go.transform.localEulerAngles = euler; go.transform.localScale = scale;
                go.GetComponent<Renderer>().sharedMaterial = m;
                var col = go.GetComponent<Collider>(); if (col != null) UnityEngine.Object.DestroyImmediate(col);
            }
            void AddCyl(GameObject parent, string n, Vector3 pos, Vector3 euler, Vector3 scale, Material m)
            {
                var go = GameObject.CreatePrimitive(PrimitiveType.Cylinder);
                go.name = n; go.transform.SetParent(parent.transform, false);
                go.transform.localPosition = pos; go.transform.localEulerAngles = euler; go.transform.localScale = scale;
                go.GetComponent<Renderer>().sharedMaterial = m;
                var col = go.GetComponent<Collider>(); if (col != null) UnityEngine.Object.DestroyImmediate(col);
            }
            void AddSphere(GameObject parent, string n, Vector3 pos, Vector3 scale, Material m)
            {
                var go = GameObject.CreatePrimitive(PrimitiveType.Sphere);
                go.name = n; go.transform.SetParent(parent.transform, false);
                go.transform.localPosition = pos; go.transform.localScale = scale;
                go.GetComponent<Renderer>().sharedMaterial = m;
                var col = go.GetComponent<Collider>(); if (col != null) UnityEngine.Object.DestroyImmediate(col);
            }

            var root = new GameObject("EnergyRelicTurret");
            AddPart(root, "Base",     new Vector3(0f, 0.12f, 0f), Vector3.zero, new Vector3(1.05f, 0.24f, 1.05f), body);
            AddCyl (root, "Pillar",   new Vector3(0f, 0.55f, 0f), Vector3.zero, new Vector3(0.32f, 0.4f, 0.32f), dark);
            AddPart(root, "Ring",     new Vector3(0f, 0.85f, 0f), Vector3.zero, new Vector3(0.7f, 0.08f, 0.7f), accent);
            AddPart(root, "CellBay",  new Vector3(0.45f, 0.4f, -0.15f), Vector3.zero, new Vector3(0.28f, 0.35f, 0.4f), dark);

            var headGo = new GameObject("Head");
            headGo.transform.SetParent(root.transform, false);
            headGo.transform.localPosition = new Vector3(0f, 1.05f, 0f);
            AddPart(headGo, "HeadBody", new Vector3(0f, 0f, 0f), Vector3.zero, new Vector3(0.55f, 0.4f, 0.5f), body);
            AddCyl (headGo, "Emitter",  new Vector3(0f, 0.05f, 0.45f), new Vector3(90,0,0), new Vector3(0.18f, 0.35f, 0.18f), accent);
            AddPart(headGo, "FinsL",    new Vector3(-0.28f, 0.1f, 0.05f), new Vector3(0,0,15), new Vector3(0.06f, 0.35f, 0.25f), dark);
            AddPart(headGo, "FinsR",    new Vector3( 0.28f, 0.1f, 0.05f), new Vector3(0,0,-15), new Vector3(0.06f, 0.35f, 0.25f), dark);

            // Spinning relic crystal (child of head so it aims with the barrel).
            var crystalGo = new GameObject("Crystal");
            crystalGo.transform.SetParent(headGo.transform, false);
            crystalGo.transform.localPosition = new Vector3(0f, 0.35f, -0.05f);
            AddSphere(crystalGo, "Core", Vector3.zero, Vector3.one * 0.28f, relic);
            AddPart(crystalGo, "ShardA", new Vector3(0f, 0.18f, 0f), new Vector3(0,0,45), new Vector3(0.08f, 0.25f, 0.08f), accent);
            AddPart(crystalGo, "ShardB", new Vector3(0f, -0.18f, 0f), new Vector3(0,0,-45), new Vector3(0.08f, 0.25f, 0.08f), accent);

            var muzzleGo = new GameObject("Muzzle");
            muzzleGo.transform.SetParent(headGo.transform, false);
            muzzleGo.transform.localPosition = new Vector3(0f, 0.05f, 0.85f);

            var cap = root.AddComponent<CapsuleCollider>();
            cap.height = 1.7f; cap.radius = 0.55f; cap.center = new Vector3(0f, 0.75f, 0f);
            var et = root.AddComponent<VoxelEngine.Combat.EnergyRelicTurret>();
            et.range = 48f; et.fireCooldown = 0.55f; et.cellDamage = 28f; et.relicDamage = 70f;
            et.aimSpeed = 5.5f; et.beamMat = beam; et.coreMat = relic; et.muzzleMat = accent;
            et.head = headGo.transform; et.muzzle = muzzleGo.transform; et.crystal = crystalGo.transform;

            const string path = ASSET_ROOT + "/Combat/Prefabs/EnergyRelicTurret.prefab";
            GameObject prefab;
            if (AssetDatabase.LoadMainAssetAtPath(path) != null) { prefab = AssetDatabase.LoadAssetAtPath<GameObject>(path); UnityEngine.Object.DestroyImmediate(root); }
            else { prefab = PrefabUtility.SaveAsPrefabAsset(root, path); UnityEngine.Object.DestroyImmediate(root); }

            var block = GetOrCreateAsset<VoxelEngine.Items.BlockItem>($"{COMBAT_BLOCKS}/Block_EnergyRelicTurret.asset");
            block.itemId = "block_energy_relic_turret"; block.displayName = "Energy / Relic Turret";
            block.description = "Late-tier electrical beam turret. Consumes Charged Cells (standard) or Relic Capacitors (heavy charged shot). Configure via the defense panel (RMB).";
            block.iconTint = new Color(0.45f, 0.55f, 0.95f);
            block.maxStack = 2; block.massPerUnit = 18f;
            block.placedPrefab = prefab; block.gridSize = Vector3Int.one; block.allowStacking = true; block.blockHealth = 180; block.miningTier = 3; block.category = "Combat";
            EditorUtility.SetDirty(block);

            var cell = GetOrCreateAsset<VoxelEngine.Items.ItemDefinition>($"{COMBAT_ITEMS}/Item_ChargedCell.asset");
            cell.itemId = "item_charged_cell"; cell.displayName = "Charged Cell";
            cell.description = "Compact energy cell for the Energy / Relic Turret. Standard electrical beam shot.";
            cell.iconTint = new Color(0.4f, 0.85f, 1f); cell.maxStack = 40; cell.massPerUnit = 0.6f; cell.category = "Combat";
            EditorUtility.SetDirty(cell);

            var capItem = GetOrCreateAsset<VoxelEngine.Items.ItemDefinition>($"{COMBAT_ITEMS}/Item_RelicCapacitor.asset");
            capItem.itemId = "item_relic_capacitor"; capItem.displayName = "Relic Capacitor";
            capItem.description = "Exotic relic capacitor. Feeds a heavier charged beam from the Energy / Relic Turret.";
            capItem.iconTint = new Color(0.75f, 0.4f, 1f); capItem.maxStack = 20; capItem.massPerUnit = 1.2f; capItem.category = "Combat";
            EditorUtility.SetDirty(capItem);

            AddRecipe("Recipe_EnergyRelicTurret", "Energy / Relic Turret", block, 1, VoxelEngine.Crafting.StationTier.Assembler, true,
                (steelPlate != null ? steelPlate : ironPlate, 12),
                (advCircuit != null ? advCircuit : circuit, 4),
                (goldWire != null ? goldWire : copperWire, 8),
                (steelIngot, 6));
            AddRecipe("Recipe_ChargedCell", "Charged Cell", cell, 8, VoxelEngine.Crafting.StationTier.Assembler, true,
                (circuit, 1), (copperWire != null ? copperWire : goldWire, 2), (ironPlate, 1));
            AddRecipe("Recipe_RelicCapacitor", "Relic Capacitor", capItem, 2, VoxelEngine.Crafting.StationTier.Assembler, true,
                (advCircuit != null ? advCircuit : circuit, 2),
                (goldWire != null ? goldWire : copperWire, 4),
                (steelIngot, 2));

            AssetDatabase.SaveAssets(); AssetDatabase.Refresh();
            EditorUtility.DisplayDialog("Voxel Engine — Energy / Relic Turret",
                "The Energy / Relic Turret is built:\n\n" +
                "• Crystal-core beam turret with spinning relic (~14 parts)\n" +
                "• Hitscan Electrical damage (cells 28 / relic capacitors 70)\n" +
                "• Range ~48 m, glowing beam + impact sparks\n" +
                "• Load Charged Cells or Relic Capacitors via the defense panel\n" +
                "• 180 HP. Craft at the Assembler", "OK");
        }

        // ============================================================
        //   STEP 46 - PAINT TOOL. Cosmetic finishes for static + grid
        //   blocks. LMB paint, RMB cycle, Shift+RMB clear. Saves with
        //   the world. Non-destructive. Re-runnable.
        // ============================================================
        private void BuildPaintToolContent()
        {
            const string ITEMS = ASSET_ROOT + "/Items";
            const string TOOLS = ASSET_ROOT + "/Tools";
            EnsureFolder(ITEMS); EnsureFolder(TOOLS);

            ItemDefinition FindItem(string n)
            {
                var guids = AssetDatabase.FindAssets(n + " t:ItemDefinition");
                foreach (var g in guids)
                {
                    var pp = AssetDatabase.GUIDToAssetPath(g);
                    if (System.IO.Path.GetFileNameWithoutExtension(pp) == n)
                        return AssetDatabase.LoadAssetAtPath<ItemDefinition>(pp);
                }
                return null;
            }
            var ironIngot  = FindItem("Item_IronIngot");
            var ironPlate  = FindItem("Item_IronPlate");
            var copperWire = FindItem("Item_CopperLVWire");

            var tool = GetOrCreateAsset<VoxelEngine.Items.PaintToolItem>($"{TOOLS}/Tool_Paint.asset");
            tool.itemId = "tool_paint";
            tool.displayName = "Paint Tool";
            tool.description = "Apply cosmetic finishes to placed blocks and grid blocks. LMB paints, RMB cycles finish, Shift+RMB clears. Cosmetic only — saves with the world.";
            tool.iconTint = new Color(0.85f, 0.55f, 0.25f);
            tool.maxStack = 1;
            tool.massPerUnit = 1.5f;
            tool.category = "Tools";
            tool.toolType = VoxelEngine.Items.ToolType.Other;
            tool.fireRate = 6f;
            tool.strength = 1f;
            tool.maxDurability = 0; // infinite for MVP cosmetics
            tool.defaultFinish = VoxelEngine.Building.PaintFinishId.IndustrialGrey;
            EditorUtility.SetDirty(tool);

            AddRecipe("Recipe_PaintTool", "Paint Tool", tool, 1, VoxelEngine.Crafting.StationTier.CraftingBench, true,
                (ironIngot != null ? ironIngot : ironPlate, 2),
                (ironPlate, 1),
                (copperWire, 2));

            AssetDatabase.SaveAssets(); AssetDatabase.Refresh();
            EditorUtility.DisplayDialog("Voxel Engine — Paint Tool",
                "The Paint Tool is ready:\\n\\n" +
                "• Craft at the Crafting Bench (iron + copper wire)\\n" +
                "• 15 finishes: matte/metal/rust/chrome/hazard/crusader colours\\n" +
                "• LMB = paint looked-at static or grid block\\n" +
                "• RMB = cycle finish · Shift+RMB = clear · Scroll = cycle\\n" +
                "• Cosmetic only — saved with the world (additive)\\n" +
                "• HUD swatch appears while the tool is held", "OK");
        }

        // ============================================================
        //   STEP 47 - JETPACK FUEL ACCOUNTING. Sets capacity/drain on
        //   jetpack families and authors Hydrogen Cells. Non-destructive.
        // ============================================================
        private void BuildJetpackFuelContent()
        {
            const string ITEMS = ASSET_ROOT + "/GridSystem/Items";
            const string COMBAT_ITEMS = ASSET_ROOT + "/Combat/Items";
            EnsureFolder(ITEMS);
            EnsureFolder(COMBAT_ITEMS);

            ItemDefinition FindItem(string n)
            {
                var guids = AssetDatabase.FindAssets(n + " t:ItemDefinition");
                foreach (var g in guids)
                {
                    var pp = AssetDatabase.GUIDToAssetPath(g);
                    if (System.IO.Path.GetFileNameWithoutExtension(pp) == n)
                        return AssetDatabase.LoadAssetAtPath<ItemDefinition>(pp);
                }
                return null;
            }

            void TuneJetpack(string assetName, int capMl, float drainMl, float boostDrainMl)
            {
                var path = $"{ITEMS}/{assetName}.asset";
                var pack = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.JetpackItem>(path);
                if (pack == null)
                    pack = FindItem(assetName) as VoxelEngine.Items.JetpackItem;
                if (pack == null) return;
                pack.fuelCapacityMl = capMl;
                pack.drainMlPerSecond = drainMl;
                pack.boostDrainMlPerSecond = boostDrainMl;
                pack.autoRechargeThreshold = 0.10f;
                pack.chargedCellRefuelMl = 350;
                pack.usesHydrogen = pack.family == VoxelEngine.Items.JetpackFamily.HydrogenBoost
                                 || pack.family == VoxelEngine.Items.JetpackFamily.Hybrid;
                pack.usesPower = pack.family == VoxelEngine.Items.JetpackFamily.Atmospheric
                              || pack.family == VoxelEngine.Items.JetpackFamily.Hybrid;
                EditorUtility.SetDirty(pack);
            }

            TuneJetpack("Equip_JetpackHydrogenBoost", 800, 32f, 55f);
            TuneJetpack("Equip_JetpackAtmospheric", 1000, 22f, 35f);
            TuneJetpack("Equip_JetpackHybrid", 1200, 26f, 42f);

            var steelPlate = FindItem("Item_SteelPlate");
            var copperWire = FindItem("Item_CopperLVWire");
            var ironPlate  = FindItem("Item_IronPlate");

            var h2can = GetOrCreateAsset<VoxelEngine.Items.HydrogenCanisterItem>($"{ITEMS}/Item_PortableHydrogenTank.asset");
            h2can.itemId = VoxelEngine.Items.HydrogenCanisterItem.ItemId;
            h2can.displayName = "Portable Hydrogen Tank";
            h2can.description = "Refillable hydrogen tank (metric ml). RMB a world Hydrogen Gas Tank to fill. H₂/Hybrid jetpacks auto-recharge from inventory tanks at ≤10% fuel.";
            h2can.iconTint = new Color(0.35f, 0.85f, 1f);
            h2can.maxStack = 1;
            h2can.massPerUnit = 6f;
            h2can.category = "Equipment";
            h2can.capacityMl = 2000;
            h2can.fillRateMlPerUse = 250f;
            EditorUtility.SetDirty(h2can);
            AddRecipe("Recipe_PortableHydrogenTank", "Portable Hydrogen Tank", h2can, 1, VoxelEngine.Crafting.StationTier.Assembler, true,
                (steelPlate != null ? steelPlate : ironPlate, 3), (copperWire, 4));

            // Ensure Charged Cell exists for atmospheric/hybrid (authored by Energy Turret step too).
            var cell = GetOrCreateAsset<VoxelEngine.Items.ItemDefinition>($"{COMBAT_ITEMS}/Item_ChargedCell.asset");
            if (string.IsNullOrEmpty(cell.itemId)) cell.itemId = "item_charged_cell";
            if (string.IsNullOrEmpty(cell.displayName)) cell.displayName = "Charged Cell";
            if (string.IsNullOrEmpty(cell.description))
                cell.description = "Compact energy cell. Feeds Atmospheric/Hybrid jetpacks and Energy/Relic turrets.";
            cell.iconTint = new Color(0.4f, 0.85f, 1f);
            if (cell.maxStack < 2) cell.maxStack = 40;
            cell.category = string.IsNullOrEmpty(cell.category) ? "Combat" : cell.category;
            EditorUtility.SetDirty(cell);

            AssetDatabase.SaveAssets(); AssetDatabase.Refresh();
            EditorUtility.DisplayDialog("Voxel Engine — Jetpack Fuel",
                "Jetpack fuel accounting is ready:\n\n" +
                "• Hydrogen Boost / Atmospheric / Hybrid capacity + drain tuned (ml)\n" +
                "• Portable Hydrogen Tank — RMB a Hydrogen Gas Tank to fill\n" +
                "• H₂/Hybrid packs auto-recharge from inventory tanks at ≤10% fuel\n" +
                "• Charged Cells feed Atmospheric / Hybrid power side\n" +
                "• Portable Battery — rechargeable power bank for jetpacks (fill from Battery blocks)\n" +
                "• Jetpack Bay shows fuel bar (ONLINE / LOW / DRY)", "OK");

            // ===== Portable Battery (new step inside 47 — non-destructive) =====
            EnsureFolder(ITEMS);
            var battery = GetOrCreateAsset<VoxelEngine.Items.PortableBatteryItem>($"{ITEMS}/Item_PortableBattery.asset");
            battery.itemId = VoxelEngine.Items.PortableBatteryItem.ItemId;
            battery.displayName = "Portable Battery";
            battery.description = "Rechargeable power bank for Atmospheric / Hybrid jetpacks. Fill from a world Battery block (RMB). Jetpacks draw charge from inventory batteries the same way they draw H₂ from tanks.";
            battery.iconTint = new Color(0.45f, 0.75f, 0.95f);
            battery.maxStack = 1;
            battery.massPerUnit = 7f;
            battery.category = "Equipment";
            battery.capacityMl = 3000;
            battery.fillRateMlPerUse = 300f;
            EditorUtility.SetDirty(battery);
            AddRecipe("Recipe_PortableBattery", "Portable Battery", battery, 1, VoxelEngine.Crafting.StationTier.Assembler, true,
                (ironPlate != null ? ironPlate : steelPlate, 4),
                (copperWire, 3));

            EnsureItemPersistenceCatalog();
            AssetDatabase.SaveAssets();
        }
























        // ============================================================
        //   STEP 48 - ARMOR STATIONS + TIMED ARMOR UPGRADES
        //
        //   All content is created/repaired through this wizard. Existing
        //   asset values and custom prefab children are preserved; only missing
        //   generated content and required links are added.
        // ============================================================
        private void BuildArmorStationsAndUpgrades()
        {
            const string armorFolder = ASSET_ROOT + "/Combat/Armor";
            const string armorStationFolder = ASSET_ROOT + "/Combat/ArmorStation";
            const string upgradeStationFolder = ASSET_ROOT + "/Combat/ArmorUpgradeStation";
            const string upgradeModuleFolder = ASSET_ROOT + "/Combat/ArmorUpgrades";
            const string blockFolder = ASSET_ROOT + "/Blocks";
            const string recipeFolder = ASSET_ROOT + "/Recipes";
            const string researchFolder = ASSET_ROOT + "/Research";
            const string researchNodeFolder = researchFolder + "/Nodes";
            const string itemFolder = ASSET_ROOT + "/Items";

            EnsureFolder(armorFolder);
            EnsureFolder(armorStationFolder);
            EnsureFolder(upgradeStationFolder);
            EnsureFolder(upgradeModuleFolder);
            EnsureFolder(blockFolder);
            EnsureFolder(recipeFolder);
            EnsureFolder(researchFolder);
            EnsureFolder(researchNodeFolder);

            int createdAssets = 0;
            int repairedLinks = 0;
            int preservedAssets = 0;

            T GetOrCreateSafeAsset<T>(string path, out bool created) where T : ScriptableObject
            {
                created = false;
                var typed = AssetDatabase.LoadAssetAtPath<T>(path);
                if (typed != null)
                {
                    preservedAssets++;
                    return typed;
                }

                var conflicting = AssetDatabase.LoadMainAssetAtPath(path);
                if (conflicting != null)
                {
                    Debug.LogError($"[VoxelEngineSetupWindow] Step 48 preserved '{path}' because it is not a {typeof(T).Name}. Resolve the asset-type conflict manually.");
                    return null;
                }

                var folder = Path.GetDirectoryName(path)?.Replace("\\", "/");
                if (!string.IsNullOrEmpty(folder)) EnsureFolder(folder);
                typed = ScriptableObject.CreateInstance<T>();
                AssetDatabase.CreateAsset(typed, path);
                created = true;
                createdAssets++;
                Debug.Log($"[VoxelEngineSetupWindow] Step 48 created asset: {path}");
                return typed;
            }

            ItemDefinition FindItem(string assetName)
            {
                var guids = AssetDatabase.FindAssets(assetName + " t:ItemDefinition");
                foreach (var guid in guids)
                {
                    var path = AssetDatabase.GUIDToAssetPath(guid);
                    if (Path.GetFileNameWithoutExtension(path) != assetName) continue;
                    var item = AssetDatabase.LoadAssetAtPath<ItemDefinition>(path);
                    if (item != null) return item;
                }
                return null;
            }

            Material EnsureMaterial(string folder, string assetName, Color color, bool emissive)
            {
                string path = $"{folder}/{assetName}.mat";
                var material = AssetDatabase.LoadAssetAtPath<Material>(path);
                if (material != null)
                {
                    preservedAssets++;
                    return material;
                }

                if (AssetDatabase.LoadMainAssetAtPath(path) != null)
                {
                    Debug.LogError($"[VoxelEngineSetupWindow] Step 48 preserved '{path}' because it is not a Material.");
                    return null;
                }

                var shader = Shader.Find("Universal Render Pipeline/Lit") ?? Shader.Find("Standard");
                if (shader == null)
                {
                    Debug.LogError($"[VoxelEngineSetupWindow] Step 48 could not create '{path}' because no supported lit shader was found.");
                    return null;
                }

                material = new Material(shader) { name = assetName };
                material.color = color;
                if (material.HasProperty("_BaseColor")) material.SetColor("_BaseColor", color);
                if (material.HasProperty("_Metallic")) material.SetFloat("_Metallic", emissive ? 0.2f : 0.78f);
                if (material.HasProperty("_Smoothness")) material.SetFloat("_Smoothness", emissive ? 0.42f : 0.58f);
                if (emissive)
                {
                    material.EnableKeyword("_EMISSION");
                    if (material.HasProperty("_EmissionColor")) material.SetColor("_EmissionColor", color * 1.8f);
                }
                AssetDatabase.CreateAsset(material, path);
                createdAssets++;
                return material;
            }

            GameObject EnsureGeneratedPrimitive(
                Transform parent,
                string name,
                PrimitiveType type,
                Vector3 localPosition,
                Vector3 localEuler,
                Vector3 localScale,
                Material material)
            {
                var existing = parent.Find(name);
                GameObject part;
                bool wasCreated = existing == null;
                if (wasCreated)
                {
                    part = GameObject.CreatePrimitive(type);
                    part.name = name;
                    part.transform.SetParent(parent, false);
                    var collider = part.GetComponent<Collider>();
                    if (collider != null) UnityEngine.Object.DestroyImmediate(collider);
                    createdAssets++;
                }
                else
                {
                    part = existing.gameObject;
                    if (part.GetComponent<MeshFilter>() == null || part.GetComponent<MeshRenderer>() == null)
                    {
                        Debug.LogWarning($"[VoxelEngineSetupWindow] Step 48 left custom child '{name}' on '{parent.name}' untouched because it is not generated mesh geometry.");
                        return part;
                    }
                    repairedLinks++;
                }

                // Generated parts are authored only when missing. On later runs,
                // preserve the designer's transforms and materials instead of
                // resetting visual work that may have been customized in Unity.
                if (wasCreated)
                {
                    part.transform.localPosition = localPosition;
                    part.transform.localRotation = Quaternion.Euler(localEuler);
                    part.transform.localScale = localScale;
                }
                var renderer = part.GetComponent<Renderer>();
                if (renderer != null && material != null && (wasCreated || renderer.sharedMaterial == null))
                    renderer.sharedMaterial = material;
                return part;
            }

            Transform EnsureGeneratedEmpty(Transform parent, string name, Vector3 localPosition, Vector3 localEuler)
            {
                var existing = parent.Find(name);
                if (existing == null)
                {
                    var child = new GameObject(name);
                    child.transform.SetParent(parent, false);
                    existing = child.transform;
                    existing.localPosition = localPosition;
                    existing.localRotation = Quaternion.Euler(localEuler);
                    existing.localScale = Vector3.one;
                    createdAssets++;
                }
                else
                {
                    repairedLinks++;
                }

                return existing;
            }

            Light EnsureGeneratedLight(Transform parent, string name, Vector3 localPosition, Color color, float intensity, float range)
            {
                var child = parent.Find(name);
                bool wasCreated = child == null;
                if (wasCreated)
                {
                    child = new GameObject(name).transform;
                    child.SetParent(parent, false);
                    child.localPosition = localPosition;
                    child.localRotation = Quaternion.identity;
                    createdAssets++;
                }
                else
                {
                    repairedLinks++;
                }

                var light = child.GetComponent<Light>();
                if (light == null)
                {
                    light = child.gameObject.AddComponent<Light>();
                    light.type = LightType.Point;
                    light.color = color;
                    light.intensity = intensity;
                    light.range = range;
                    light.shadows = LightShadows.None;
                    createdAssets++;
                }
                return light;
            }

            void EnsureRootCollider(GameObject root, Vector3 center, Vector3 size)
            {
                if (root.GetComponent<Collider>() != null) return;
                var collider = root.AddComponent<BoxCollider>();
                collider.center = center;
                collider.size = size;
                createdAssets++;
            }

            GameObject GetOrCreateFeaturePrefab(string path, string defaultName, System.Action<GameObject> ensureContent)
            {
                var mainAsset = AssetDatabase.LoadMainAssetAtPath(path);
                if (mainAsset != null && !(mainAsset is GameObject))
                {
                    Debug.LogError($"[VoxelEngineSetupWindow] Step 48 preserved '{path}' because it is not a prefab. No asset was removed.");
                    return null;
                }

                bool existed = mainAsset is GameObject;
                GameObject root = null;
                bool loadedContents = false;
                try
                {
                    if (existed)
                    {
                        try
                        {
                            root = PrefabUtility.LoadPrefabContents(path);
                            loadedContents = true;
                        }
                        catch (System.Exception ex)
                        {
                            Debug.LogError($"[VoxelEngineSetupWindow] Step 48 could not open '{path}' and left it untouched. Unity said: {ex.Message}");
                            return AssetDatabase.LoadAssetAtPath<GameObject>(path);
                        }
                    }
                    else
                    {
                        root = new GameObject(defaultName);
                    }

                    ensureContent?.Invoke(root);
                    var saved = PrefabUtility.SaveAsPrefabAsset(root, path);
                    if (saved == null)
                    {
                        Debug.LogError($"[VoxelEngineSetupWindow] Step 48 could not save prefab '{path}'. Existing content was left untouched.");
                        return AssetDatabase.LoadAssetAtPath<GameObject>(path);
                    }

                    if (existed) preservedAssets++;
                    else createdAssets++;
                    return saved;
                }
                finally
                {
                    if (root != null)
                    {
                        if (loadedContents) PrefabUtility.UnloadPrefabContents(root);
                        else UnityEngine.Object.DestroyImmediate(root);
                    }
                }
            }

            var armorSteel = EnsureMaterial(armorStationFolder, "Mat_ArmorStation", new Color(0.23f, 0.29f, 0.31f), false);
            var armorDark = EnsureMaterial(armorStationFolder, "Mat_ArmorStationDark", new Color(0.055f, 0.07f, 0.085f), false);
            var armorBrass = EnsureMaterial(armorStationFolder, "Mat_ArmorStationBrass", new Color(0.57f, 0.39f, 0.16f), false);
            var armorGlow = EnsureMaterial(armorStationFolder, "Mat_ArmorStationGlow", new Color(0.12f, 0.80f, 0.92f), true);

            var upgradeSteel = EnsureMaterial(upgradeStationFolder, "Mat_ArmorUpgradeAnvil", new Color(0.22f, 0.24f, 0.27f), false);
            var upgradeDark = EnsureMaterial(upgradeStationFolder, "Mat_ArmorUpgradeDark", new Color(0.04f, 0.045f, 0.055f), false);
            var upgradeBrass = EnsureMaterial(upgradeStationFolder, "Mat_ArmorUpgradeBrass", new Color(0.66f, 0.43f, 0.16f), false);
            var upgradeGlow = EnsureMaterial(upgradeStationFolder, "Mat_ArmorUpgradeGlow", new Color(1f, 0.27f, 0.06f), true);

            var armorStationPrefab = GetOrCreateFeaturePrefab(
                $"{armorStationFolder}/ArmorStation.prefab",
                "ArmorStation",
                root =>
                {
                    var station = root.GetComponent<VoxelEngine.Combat.ArmorStation>();
                    if (station == null) station = root.AddComponent<VoxelEngine.Combat.ArmorStation>();
                    station.tier = VoxelEngine.Crafting.StationTier.ArmorStation;
                    station.exclusiveRecipes = true;
                    if (string.IsNullOrWhiteSpace(station.displayName)) station.displayName = "Armor Station";

                    EnsureRootCollider(root, new Vector3(0f, 0.95f, 0f), new Vector3(2.35f, 1.9f, 1.45f));
                    var parent = root.transform;
                    EnsureGeneratedPrimitive(parent, "Generated_Base", PrimitiveType.Cube, new Vector3(0f, 0.16f, 0f), Vector3.zero, new Vector3(2.3f, 0.32f, 1.35f), armorDark);
                    EnsureGeneratedPrimitive(parent, "Generated_Workbench", PrimitiveType.Cube, new Vector3(0f, 0.82f, 0f), Vector3.zero, new Vector3(2.12f, 0.18f, 1.18f), armorSteel);
                    EnsureGeneratedPrimitive(parent, "Generated_BackCabinet", PrimitiveType.Cube, new Vector3(0f, 1.42f, -0.46f), Vector3.zero, new Vector3(1.96f, 1.05f, 0.18f), armorDark);
                    EnsureGeneratedPrimitive(parent, "Generated_LeftPillar", PrimitiveType.Cube, new Vector3(-0.92f, 1.37f, -0.22f), Vector3.zero, new Vector3(0.16f, 1.34f, 0.22f), armorSteel);
                    EnsureGeneratedPrimitive(parent, "Generated_RightPillar", PrimitiveType.Cube, new Vector3(0.92f, 1.37f, -0.22f), Vector3.zero, new Vector3(0.16f, 1.34f, 0.22f), armorSteel);
                    EnsureGeneratedPrimitive(parent, "Generated_TorsoDisplay", PrimitiveType.Cube, new Vector3(0f, 1.37f, -0.28f), Vector3.zero, new Vector3(0.64f, 0.70f, 0.13f), armorSteel);
                    EnsureGeneratedPrimitive(parent, "Generated_Shoulders", PrimitiveType.Cube, new Vector3(0f, 1.72f, -0.27f), Vector3.zero, new Vector3(0.98f, 0.16f, 0.18f), armorBrass);
                    EnsureGeneratedPrimitive(parent, "Generated_Helmet", PrimitiveType.Sphere, new Vector3(0f, 2.00f, -0.27f), Vector3.zero, new Vector3(0.42f, 0.39f, 0.18f), armorSteel);
                    EnsureGeneratedPrimitive(parent, "Generated_Visor", PrimitiveType.Cube, new Vector3(0f, 2.00f, -0.47f), Vector3.zero, new Vector3(0.28f, 0.08f, 0.035f), armorGlow);
                    EnsureGeneratedPrimitive(parent, "Generated_LeftToolRack", PrimitiveType.Cube, new Vector3(-0.68f, 1.30f, 0.20f), new Vector3(0f, 0f, -15f), new Vector3(0.18f, 0.78f, 0.18f), armorBrass);
                    EnsureGeneratedPrimitive(parent, "Generated_RightToolRack", PrimitiveType.Cube, new Vector3(0.68f, 1.30f, 0.20f), new Vector3(0f, 0f, 15f), new Vector3(0.18f, 0.78f, 0.18f), armorBrass);
                    EnsureGeneratedPrimitive(parent, "Generated_StatusStrip", PrimitiveType.Cube, new Vector3(0f, 0.93f, 0.61f), Vector3.zero, new Vector3(1.35f, 0.06f, 0.025f), armorGlow);
                    EnsureGeneratedLight(parent, "Generated_StatusLight", new Vector3(0f, 1.32f, 0.20f), new Color(0.12f, 0.80f, 0.92f), 1.1f, 3.2f);
                });

            var armorUpgradeStationPrefab = GetOrCreateFeaturePrefab(
                $"{upgradeStationFolder}/ArmorUpgradeStation.prefab",
                "ArmorUpgradeStation",
                root =>
                {
                    var station = root.GetComponent<VoxelEngine.Combat.ArmorUpgradeStation>();
                    if (station == null) station = root.AddComponent<VoxelEngine.Combat.ArmorUpgradeStation>();
                    if (station.baseUpgradeSeconds <= 0f)
                    {
                        station.baseUpgradeSeconds = VoxelEngine.Combat.ArmorUpgradeStation.DefaultBaseUpgradeSeconds;
                        repairedLinks++;
                    }

                    EnsureRootCollider(root, new Vector3(0f, 0.72f, 0f), new Vector3(1.72f, 1.45f, 1.05f));
                    var parent = root.transform;
                    EnsureGeneratedPrimitive(parent, "Generated_Foot", PrimitiveType.Cube, new Vector3(0f, 0.12f, 0f), Vector3.zero, new Vector3(1.55f, 0.24f, 0.92f), upgradeDark);
                    EnsureGeneratedPrimitive(parent, "Generated_Base", PrimitiveType.Cube, new Vector3(0f, 0.34f, 0f), Vector3.zero, new Vector3(0.88f, 0.26f, 0.56f), upgradeSteel);
                    EnsureGeneratedPrimitive(parent, "Generated_Waist", PrimitiveType.Cube, new Vector3(0f, 0.58f, 0f), Vector3.zero, new Vector3(0.48f, 0.42f, 0.40f), upgradeSteel);
                    EnsureGeneratedPrimitive(parent, "Generated_Face", PrimitiveType.Cube, new Vector3(0f, 0.86f, 0f), Vector3.zero, new Vector3(1.18f, 0.18f, 0.56f), upgradeSteel);
                    EnsureGeneratedPrimitive(parent, "Generated_Horn", PrimitiveType.Cylinder, new Vector3(0f, 0.87f, 0.48f), new Vector3(90f, 0f, 0f), new Vector3(0.26f, 0.50f, 0.26f), upgradeSteel);
                    EnsureGeneratedPrimitive(parent, "Generated_BrassBand", PrimitiveType.Cube, new Vector3(0f, 0.45f, -0.30f), Vector3.zero, new Vector3(0.66f, 0.08f, 0.055f), upgradeBrass);
                    EnsureGeneratedPrimitive(parent, "Generated_ForgeCore", PrimitiveType.Cube, new Vector3(0f, 0.40f, 0.31f), Vector3.zero, new Vector3(0.36f, 0.16f, 0.04f), upgradeGlow);

                    // Keep the hammer head above the anvil face at rest; the runtime
                    // station animation then drops it straight onto the work surface.
                    var hammerRestPosition = new Vector3(0f, 1.92f, 0f);
                    var hammerPivot = EnsureGeneratedEmpty(parent, "Generated_HammerPivot", hammerRestPosition, Vector3.zero);
                    var legacyHammerPosition = new Vector3(-0.48f, 1.38f, 0.08f);
                    if ((hammerPivot.localPosition - legacyHammerPosition).sqrMagnitude < 0.0004f)
                    {
                        hammerPivot.localPosition = hammerRestPosition;
                        hammerPivot.localRotation = Quaternion.identity;
                        repairedLinks++;
                    }
                    EnsureGeneratedPrimitive(hammerPivot, "Generated_HammerHandle", PrimitiveType.Cylinder, new Vector3(0f, -0.36f, 0f), Vector3.zero, new Vector3(0.065f, 0.38f, 0.065f), upgradeBrass);
                    EnsureGeneratedPrimitive(hammerPivot, "Generated_HammerHead", PrimitiveType.Cube, new Vector3(0f, -0.73f, 0f), Vector3.zero, new Vector3(0.34f, 0.18f, 0.20f), upgradeDark);
                    EnsureGeneratedPrimitive(hammerPivot, "Generated_HammerPeen", PrimitiveType.Cylinder, new Vector3(0f, -0.73f, 0.18f), new Vector3(90f, 0f, 0f), new Vector3(0.10f, 0.20f, 0.10f), upgradeDark);
                    var forgeLight = EnsureGeneratedLight(parent, "Generated_ForgeLight", new Vector3(0f, 0.82f, 0.28f), new Color(1f, 0.36f, 0.08f), 0.45f, 3.8f);
                    station.ConfigureVisuals(hammerPivot, forgeLight);
                });

            VoxelEngine.Items.BlockItem EnsureStationBlock(
                string assetName,
                string displayName,
                string description,
                Color tint,
                GameObject prefab)
            {
                var block = GetOrCreateSafeAsset<VoxelEngine.Items.BlockItem>($"{blockFolder}/{assetName}.asset", out bool wasCreated);
                if (block == null) return null;

                if (wasCreated)
                {
                    block.itemId = assetName.ToLowerInvariant();
                    block.displayName = displayName;
                    block.description = description;
                    block.iconTint = tint;
                    block.maxStack = 20;
                    block.massPerUnit = 10f;
                    block.gridSize = Vector3Int.one;
                    block.allowStacking = true;
                    block.blockHealth = 240;
                    block.miningTier = 2;
                    block.category = "Stations";
                }
                else
                {
                    if (string.IsNullOrWhiteSpace(block.itemId)) { block.itemId = assetName.ToLowerInvariant(); repairedLinks++; }
                    if (string.IsNullOrWhiteSpace(block.displayName)) { block.displayName = displayName; repairedLinks++; }
                    if (string.IsNullOrWhiteSpace(block.description)) { block.description = description; repairedLinks++; }
                    if (string.IsNullOrWhiteSpace(block.category)) { block.category = "Stations"; repairedLinks++; }
                    if (block.maxStack <= 0) { block.maxStack = 20; repairedLinks++; }
                    if (block.massPerUnit <= 0f) { block.massPerUnit = 10f; repairedLinks++; }
                    if (block.blockHealth <= 0) { block.blockHealth = 240; repairedLinks++; }
                    if (block.iconTint.a <= 0f) block.iconTint = tint;
                }

                if (block.placedPrefab == null && prefab != null)
                {
                    block.placedPrefab = prefab;
                    repairedLinks++;
                }
                else if (block.placedPrefab != null && prefab != null && block.placedPrefab != prefab)
                {
                    Debug.LogWarning($"[VoxelEngineSetupWindow] Step 48 preserved custom prefab link on '{assetName}'. Assign '{prefab.name}' manually only if that link was unintended.");
                }

                EditorUtility.SetDirty(block);
                return block;
            }

            var armorStationBlock = EnsureStationBlock(
                "Block_ArmorStation",
                "Armor Station",
                "A premium armory workbench for crafting Crusader armor, upgrade modules, and the Armor Upgrade Station.",
                new Color(0.20f, 0.68f, 0.78f),
                armorStationPrefab);
            var armorUpgradeStationBlock = EnsureStationBlock(
                "Block_ArmorUpgradeStation",
                "Armor Upgrade Station",
                "An anvil workstation that installs one armor upgrade module at a time. Tier 1 takes 30 seconds; higher tiers take longer.",
                new Color(0.92f, 0.52f, 0.16f),
                armorUpgradeStationPrefab);

            VoxelEngine.Combat.ArmorItem EnsureArmor(
                string assetName,
                string displayName,
                string description,
                int tier,
                float reduction,
                Color tint)
            {
                var armor = GetOrCreateSafeAsset<VoxelEngine.Combat.ArmorItem>($"{armorFolder}/{assetName}.asset", out bool wasCreated);
                if (armor == null) return null;

                if (wasCreated)
                {
                    armor.itemId = assetName.ToLowerInvariant();
                    armor.displayName = displayName;
                    armor.description = description;
                    armor.tier = tier;
                    armor.damageReduction = reduction;
                    armor.iconTint = tint;
                    armor.maxStack = 1;
                    armor.massPerUnit = 2f + tier;
                    armor.category = "Armor";
                }
                else
                {
                    if (string.IsNullOrWhiteSpace(armor.itemId)) { armor.itemId = assetName.ToLowerInvariant(); repairedLinks++; }
                    if (string.IsNullOrWhiteSpace(armor.displayName)) { armor.displayName = displayName; repairedLinks++; }
                    if (string.IsNullOrWhiteSpace(armor.description)) { armor.description = description; repairedLinks++; }
                    if (armor.tier <= 0) { armor.tier = tier; repairedLinks++; }
                    if (armor.damageReduction <= 0f) { armor.damageReduction = reduction; repairedLinks++; }
                    if (armor.maxStack <= 0) { armor.maxStack = 1; repairedLinks++; }
                    if (armor.massPerUnit <= 0f) { armor.massPerUnit = 2f + tier; repairedLinks++; }
                    if (string.IsNullOrWhiteSpace(armor.category)) { armor.category = "Armor"; repairedLinks++; }
                }

                EditorUtility.SetDirty(armor);
                return armor;
            }

            var initiateArmor = EnsureArmor("Armor_InitiateGambeson", "Initiate's Gambeson",
                "Quilted cloth of the newly sworn. Better than nothing — barely.", 1, 0.08f, new Color(0.50f, 0.45f, 0.38f));
            var squireArmor = EnsureArmor("Armor_SquireLeather", "Squire's Leather",
                "Boiled leather over padded gambeson. A squire's first real protection.", 2, 0.15f, new Color(0.35f, 0.25f, 0.15f));
            var knightArmor = EnsureArmor("Armor_KnightChainmail", "Knight's Chainmail",
                "Full chain hauberk under a tabard. The mark of a true Crusader Knight.", 3, 0.25f, new Color(0.70f, 0.72f, 0.75f));
            var templarArmor = EnsureArmor("Armor_TemplarPlate", "Templar's Plate",
                "Steel plate with heraldic surcoat. The Templar stands where others fall.", 4, 0.38f, new Color(0.85f, 0.85f, 0.88f));
            var paladinArmor = EnsureArmor("Armor_PaladinBulwark", "Paladin's Bulwark",
                "Blessed reinforced plate with gold relic trim. Worn by the Order's finest.", 5, 0.50f, new Color(0.88f, 0.80f, 0.30f));
            var stellarArmor = EnsureArmor("Armor_StellarArchon", "Stellar Archon Plate",
                "Sealed void-metal armor with glowing energy relays. Worthy of the strongest Crusaders.", 6, 0.62f, new Color(0.22f, 0.20f, 0.28f));

            var recipeRegistry = AssetDatabase.LoadAssetAtPath<VoxelEngine.Crafting.RecipeRegistry>($"{ASSET_ROOT}/RecipeRegistry.asset");
            if (recipeRegistry == null)
                Debug.LogWarning("[VoxelEngineSetupWindow] Step 48 could not find RecipeRegistry.asset. Recipes were authored but must be registered after Step 4.");

            VoxelEngine.Crafting.RecipeIngredient[] MakeIngredients(params (ItemDefinition item, int count)[] inputs)
            {
                var ingredients = new List<VoxelEngine.Crafting.RecipeIngredient>();
                foreach (var (item, count) in inputs)
                    if (item != null && count > 0)
                        ingredients.Add(new VoxelEngine.Crafting.RecipeIngredient { item = item, count = count });
                return ingredients.ToArray();
            }

            VoxelEngine.Crafting.RecipeDefinition EnsureRecipe(
                string assetName,
                string displayName,
                ItemDefinition output,
                VoxelEngine.Crafting.StationTier requiredStation,
                params (ItemDefinition item, int count)[] defaultInputs)
            {
                var recipe = GetOrCreateSafeAsset<VoxelEngine.Crafting.RecipeDefinition>($"{recipeFolder}/{assetName}.asset", out bool wasCreated);
                if (recipe == null) return null;

                if (wasCreated)
                {
                    recipe.displayName = displayName;
                    recipe.outputItem = output;
                    recipe.outputCount = 1;
                    recipe.requiredStation = requiredStation;
                    recipe.craftSeconds = 0f;
                    recipe.unlockedByDefault = false;
                    recipe.inputs = MakeIngredients(defaultInputs);
                }
                else
                {
                    if (string.IsNullOrWhiteSpace(recipe.displayName)) { recipe.displayName = displayName; repairedLinks++; }
                    if (recipe.outputItem == null) { recipe.outputItem = output; repairedLinks++; }
                    if (recipe.outputCount <= 0) { recipe.outputCount = 1; repairedLinks++; }
                    if (recipe.requiredStation != requiredStation) { recipe.requiredStation = requiredStation; repairedLinks++; }
                    if (recipe.inputs == null || recipe.inputs.Length == 0)
                    {
                        recipe.inputs = MakeIngredients(defaultInputs);
                        repairedLinks++;
                    }
                    // This research-gated content must not leak into the default list.
                    if (recipe.unlockedByDefault) { recipe.unlockedByDefault = false; repairedLinks++; }
                }

                if (recipeRegistry != null)
                {
                    if (recipeRegistry.recipes == null) recipeRegistry.recipes = new List<VoxelEngine.Crafting.RecipeDefinition>();
                    if (!recipeRegistry.recipes.Contains(recipe))
                    {
                        recipeRegistry.recipes.Add(recipe);
                        repairedLinks++;
                    }
                }
                EditorUtility.SetDirty(recipe);
                return recipe;
            }

            var woodLog = FindItem("Item_WoodLog");
            var plank = FindItem("Item_WoodenPlank");
            var ironIngot = FindItem("Item_IronIngot");
            var steelIngot = FindItem("Item_SteelIngot");
            var ironPlate = FindItem("Item_IronPlate");
            var steelPlate = FindItem("Item_SteelPlate");
            var copperWire = FindItem("Item_CopperLVWire");
            var goldWire = FindItem("Item_GoldLVWire");
            var circuit = FindItem("Item_Circuit");
            var advancedCircuit = FindItem("Item_AdvancedCircuit") ?? FindItem("Item_AdvCircuit");

            var structuralMetal = steelPlate ?? steelIngot ?? ironPlate ?? ironIngot;
            var electronicPart = circuit ?? ironPlate ?? ironIngot;
            var wirePart = copperWire ?? goldWire ?? ironIngot;

            var armorStationRecipe = EnsureRecipe("Recipe_ArmorStation", "Armor Station", armorStationBlock,
                VoxelEngine.Crafting.StationTier.Assembler,
                (structuralMetal, 4), (electronicPart, 2), (wirePart, 2));
            var armorUpgradeStationRecipe = EnsureRecipe("Recipe_ArmorUpgradeStation", "Armor Upgrade Station", armorUpgradeStationBlock,
                VoxelEngine.Crafting.StationTier.ArmorStation,
                (structuralMetal, 5), (electronicPart, 2), (wirePart, 2));

            var allArmorRecipes = new List<VoxelEngine.Crafting.RecipeDefinition>
            {
                armorStationRecipe,
                armorUpgradeStationRecipe,
                EnsureRecipe("Recipe_Armor_InitiateGambeson", "Initiate's Gambeson", initiateArmor,
                    VoxelEngine.Crafting.StationTier.ArmorStation, (woodLog, 4), (plank, 4)),
                EnsureRecipe("Recipe_Armor_SquireLeather", "Squire's Leather", squireArmor,
                    VoxelEngine.Crafting.StationTier.ArmorStation, (woodLog, 2), (ironIngot, 3)),
                EnsureRecipe("Recipe_Armor_KnightChainmail", "Knight's Chainmail", knightArmor,
                    VoxelEngine.Crafting.StationTier.ArmorStation, (ironIngot, 5), (copperWire, 3)),
                EnsureRecipe("Recipe_Armor_TemplarPlate", "Templar's Plate", templarArmor,
                    VoxelEngine.Crafting.StationTier.ArmorStation, (ironPlate, 5), (steelIngot, 3), (copperWire, 4)),
                EnsureRecipe("Recipe_Armor_PaladinBulwark", "Paladin's Bulwark", paladinArmor,
                    VoxelEngine.Crafting.StationTier.ArmorStation, (steelPlate, 8), (circuit, 3), (copperWire, 6)),
                EnsureRecipe("Recipe_Armor_StellarArchon", "Stellar Archon Plate", stellarArmor,
                    VoxelEngine.Crafting.StationTier.ArmorStation, (steelPlate, 12), (advancedCircuit, 4), (goldWire, 6)),
            };

            Color ModuleTint(VoxelEngine.Combat.ArmorUpgradeKind kind)
            {
                return kind switch
                {
                    VoxelEngine.Combat.ArmorUpgradeKind.HeatTolerance => new Color(1f, 0.40f, 0.16f),
                    VoxelEngine.Combat.ArmorUpgradeKind.RadiationShielding => new Color(0.48f, 0.95f, 0.34f),
                    VoxelEngine.Combat.ArmorUpgradeKind.OxygenEfficiency => new Color(0.28f, 0.78f, 1f),
                    VoxelEngine.Combat.ArmorUpgradeKind.FallImpact => new Color(0.93f, 0.70f, 0.22f),
                    VoxelEngine.Combat.ArmorUpgradeKind.Mobility => new Color(0.66f, 0.42f, 1f),
                    _ => new Color(0.45f, 0.85f, 1f),
                };
            }

            (ItemDefinition item, int baseCount)[] ModuleIngredients(VoxelEngine.Combat.ArmorUpgradeKind kind)
            {
                return kind switch
                {
                    VoxelEngine.Combat.ArmorUpgradeKind.HeatTolerance => new[] { (structuralMetal, 2), (wirePart, 1) },
                    VoxelEngine.Combat.ArmorUpgradeKind.RadiationShielding => new[] { (structuralMetal, 2), (electronicPart, 1) },
                    VoxelEngine.Combat.ArmorUpgradeKind.OxygenEfficiency => new[] { (wirePart, 2), (structuralMetal, 1) },
                    VoxelEngine.Combat.ArmorUpgradeKind.FallImpact => new[] { (structuralMetal, 3) },
                    VoxelEngine.Combat.ArmorUpgradeKind.Mobility => new[] { (electronicPart, 2), (structuralMetal, 2) },
                    _ => System.Array.Empty<(ItemDefinition item, int baseCount)>(),
                };
            }

            int ScaleModuleCost(int baseCount, int tier)
            {
                return Mathf.Max(1, Mathf.RoundToInt(baseCount * (1f + (tier - 1) * 0.5f)));
            }

            VoxelEngine.Combat.ArmorUpgradeItem EnsureModule(
                VoxelEngine.Combat.ArmorUpgradeKind kind,
                int tier)
            {
                string assetName = $"Item_ArmorUpgrade_{kind}_{tier}";
                var module = GetOrCreateSafeAsset<VoxelEngine.Combat.ArmorUpgradeItem>($"{upgradeModuleFolder}/{assetName}.asset", out bool wasCreated);
                if (module == null) return null;

                module.kind = kind;
                module.tier = tier;
                module.isHazmat = false;
                if (wasCreated)
                {
                    module.itemId = assetName.ToLowerInvariant();
                    module.displayName = $"{VoxelEngine.Combat.ArmorUpgradeKindInfo.DisplayName(kind)} Module (T{tier})";
                    module.description = VoxelEngine.Combat.ArmorUpgradeKindInfo.Description(kind);
                    module.iconTint = ModuleTint(kind);
                    module.maxStack = 1;
                    module.massPerUnit = 1.5f;
                    module.category = "Armor Upgrades";
                }
                else
                {
                    if (string.IsNullOrWhiteSpace(module.itemId)) { module.itemId = assetName.ToLowerInvariant(); repairedLinks++; }
                    if (string.IsNullOrWhiteSpace(module.displayName)) { module.displayName = $"{VoxelEngine.Combat.ArmorUpgradeKindInfo.DisplayName(kind)} Module (T{tier})"; repairedLinks++; }
                    if (string.IsNullOrWhiteSpace(module.description)) { module.description = VoxelEngine.Combat.ArmorUpgradeKindInfo.Description(kind); repairedLinks++; }
                    if (module.maxStack <= 0) { module.maxStack = 1; repairedLinks++; }
                    if (module.massPerUnit <= 0f) { module.massPerUnit = 1.5f; repairedLinks++; }
                    if (string.IsNullOrWhiteSpace(module.category)) { module.category = "Armor Upgrades"; repairedLinks++; }
                }
                EditorUtility.SetDirty(module);
                return module;
            }

            var moduleRecipes = new List<VoxelEngine.Crafting.RecipeDefinition>();
            foreach (VoxelEngine.Combat.ArmorUpgradeKind kind in System.Enum.GetValues(typeof(VoxelEngine.Combat.ArmorUpgradeKind)))
            {
                foreach (int tier in new[] { 1, 2, 3, 4, 5 })
                {
                    var module = EnsureModule(kind, tier);
                    var baseIngredients = ModuleIngredients(kind);
                    var ingredients = new List<(ItemDefinition item, int count)>();
                    foreach (var (item, baseCount) in baseIngredients)
                        ingredients.Add((item, ScaleModuleCost(baseCount, tier)));

                    var recipe = EnsureRecipe($"Recipe_ArmorUpgrade_{kind}_{tier}",
                        module != null ? module.DefaultDisplayName : $"{VoxelEngine.Combat.ArmorUpgradeKindInfo.DisplayName(kind)} Module (T{tier})",
                        module,
                        VoxelEngine.Crafting.StationTier.ArmorStation,
                        ingredients.ToArray());
                    if (recipe != null) moduleRecipes.Add(recipe);
                }
            }

            var hazmatModule = GetOrCreateSafeAsset<VoxelEngine.Combat.ArmorUpgradeItem>($"{upgradeModuleFolder}/Item_HazmatModule.asset", out bool hazmatCreated);
            if (hazmatModule != null)
            {
                hazmatModule.kind = VoxelEngine.Combat.ArmorUpgradeKind.HeatTolerance;
                hazmatModule.tier = 1;
                hazmatModule.isHazmat = true;
                if (hazmatCreated)
                {
                    hazmatModule.itemId = "item_hazmat_module";
                    hazmatModule.displayName = "Hazmat Module";
                    hazmatModule.description = "Applies a permanent Hazmat seal that grants full radiation immunity to one armor piece.";
                    hazmatModule.iconTint = new Color(0.55f, 0.95f, 0.35f);
                    hazmatModule.maxStack = 1;
                    hazmatModule.massPerUnit = 2f;
                    hazmatModule.category = "Armor Upgrades";
                }
                else
                {
                    if (string.IsNullOrWhiteSpace(hazmatModule.itemId)) { hazmatModule.itemId = "item_hazmat_module"; repairedLinks++; }
                    if (string.IsNullOrWhiteSpace(hazmatModule.displayName)) { hazmatModule.displayName = "Hazmat Module"; repairedLinks++; }
                    if (string.IsNullOrWhiteSpace(hazmatModule.description)) { hazmatModule.description = "Applies a permanent Hazmat seal that grants full radiation immunity to one armor piece."; repairedLinks++; }
                    if (hazmatModule.maxStack <= 0) { hazmatModule.maxStack = 1; repairedLinks++; }
                    if (hazmatModule.massPerUnit <= 0f) { hazmatModule.massPerUnit = 2f; repairedLinks++; }
                    if (string.IsNullOrWhiteSpace(hazmatModule.category)) { hazmatModule.category = "Armor Upgrades"; repairedLinks++; }
                }
                EditorUtility.SetDirty(hazmatModule);
            }

            var hazmatRecipe = EnsureRecipe("Recipe_HazmatModule", "Hazmat Module", hazmatModule,
                VoxelEngine.Crafting.StationTier.ArmorStation,
                (advancedCircuit ?? circuit ?? electronicPart, 1),
                (structuralMetal, 3),
                (goldWire ?? copperWire ?? wirePart, 1));
            if (hazmatRecipe != null) moduleRecipes.Add(hazmatRecipe);

            var researchTree = GetOrCreateSafeAsset<VoxelEngine.Research.ResearchTree>($"{researchFolder}/ResearchTree.asset", out bool createdResearchTree);
            if (researchTree != null)
            {
                if (researchTree.nodes == null) researchTree.nodes = new List<VoxelEngine.Research.ResearchNode>();

                VoxelEngine.Research.ResearchNode FindNode(string nodeId)
                {
                    foreach (var node in researchTree.nodes)
                        if (node != null && node.nodeId == nodeId) return node;

                    var guids = AssetDatabase.FindAssets(nodeId + " t:ResearchNode");
                    foreach (var guid in guids)
                    {
                        var node = AssetDatabase.LoadAssetAtPath<VoxelEngine.Research.ResearchNode>(AssetDatabase.GUIDToAssetPath(guid));
                        if (node != null && node.nodeId == nodeId) return node;
                    }
                    return null;
                }

                var researchNode = GetOrCreateSafeAsset<VoxelEngine.Research.ResearchNode>($"{researchNodeFolder}/res_armor_station.asset", out bool createdResearchNode);
                if (researchNode != null)
                {
                    var scienceT2 = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ScienceItem>($"{itemFolder}/Item_ScienceT2.asset");
                    var scienceT3 = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ScienceItem>($"{itemFolder}/Item_ScienceT3.asset");
                    var advancedManufacturing = FindNode("res_adv_manufacturing");

                    if (createdResearchNode)
                    {
                        researchNode.nodeId = "res_armor_station";
                        researchNode.displayName = "Armor Stations";
                        researchNode.description = "Unlocks the Armor Station, the anvil-style Armor Upgrade Station, all Crusader armor tiers, upgrade modules, and the Hazmat seal.";
                        researchNode.category = VoxelEngine.Research.ResearchCategory.Environment;
                        researchNode.subCategory = VoxelEngine.Research.ResearchSubCategory.Production;
                        researchNode.tier = 4;
                        researchNode.column = 4;
                        researchNode.iconTint = new Color(0.45f, 0.85f, 1f);
                        researchNode.researchSeconds = 90f;
                        var costs = new List<VoxelEngine.Research.ResearchNode.ScienceCost>();
                        if (scienceT2 != null) costs.Add(new VoxelEngine.Research.ResearchNode.ScienceCost { pack = scienceT2, count = 20 });
                        if (scienceT3 != null) costs.Add(new VoxelEngine.Research.ResearchNode.ScienceCost { pack = scienceT3, count = 10 });
                        researchNode.cost = costs.ToArray();
                        researchNode.prerequisites = advancedManufacturing != null
                            ? new[] { advancedManufacturing }
                            : System.Array.Empty<VoxelEngine.Research.ResearchNode>();
                        researchNode.upgradeKind = VoxelEngine.Research.PlayerUpgradeKind.None;
                        researchNode.maxRanks = 1;
                    }
                    else
                    {
                        if (string.IsNullOrWhiteSpace(researchNode.nodeId)) { researchNode.nodeId = "res_armor_station"; repairedLinks++; }
                        if (string.IsNullOrWhiteSpace(researchNode.displayName)) { researchNode.displayName = "Armor Stations"; repairedLinks++; }
                        if (string.IsNullOrWhiteSpace(researchNode.description)) { researchNode.description = "Unlocks armor fabrication, timed upgrades, and Hazmat sealing."; repairedLinks++; }
                        if (researchNode.tier <= 0) { researchNode.tier = 4; repairedLinks++; }
                        if (researchNode.maxRanks <= 0) { researchNode.maxRanks = 1; repairedLinks++; }
                        if ((researchNode.prerequisites == null || researchNode.prerequisites.Length == 0) && advancedManufacturing != null)
                        {
                            researchNode.prerequisites = new[] { advancedManufacturing };
                            repairedLinks++;
                        }
                    }

                    var mergedUnlocks = new List<VoxelEngine.Crafting.RecipeDefinition>();
                    if (researchNode.unlocksRecipes != null)
                        foreach (var existing in researchNode.unlocksRecipes)
                            if (existing != null && !mergedUnlocks.Contains(existing)) mergedUnlocks.Add(existing);
                    foreach (var recipe in allArmorRecipes)
                        if (recipe != null && !mergedUnlocks.Contains(recipe)) mergedUnlocks.Add(recipe);
                    foreach (var recipe in moduleRecipes)
                        if (recipe != null && !mergedUnlocks.Contains(recipe)) mergedUnlocks.Add(recipe);
                    researchNode.unlocksRecipes = mergedUnlocks.ToArray();

                    if (!researchTree.nodes.Contains(researchNode))
                    {
                        researchTree.nodes.Add(researchNode);
                        repairedLinks++;
                    }
                    EditorUtility.SetDirty(researchNode);
                    EditorUtility.SetDirty(researchTree);
                }
            }

            if (recipeRegistry != null) EditorUtility.SetDirty(recipeRegistry);
            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();

            string summary =
                "Armor stations and timed upgrades are ready.\n\n" +
                "• Armor Station: dedicated armor and module crafting\n" +
                "• Armor Upgrade Station: premium anvil workflow\n" +
                "• Installation duration: T1 30s, T2 60s, T3 90s, T4 120s, T5/Hazmat 150s\n" +
                "• Armor tier gates capacity: T1→1 slot/T1 modules through T6→6 slots/T5 modules; Hazmat requires T5+\n" +
                "• Upgrade progress and installed modules persist through save/load\n\n" +
                $"Step 48 summary — generated elements/assets: {createdAssets}, repaired links: {repairedLinks}, preserved existing assets: {preservedAssets}.\n" +
                "Run this step a second time to verify the non-destructive path.";
            Debug.Log($"[VoxelEngineSetupWindow] {summary.Replace("\n", " ")}");
            EditorUtility.DisplayDialog("Voxel Engine — Armor Stations", summary, "OK");
        }

        // ============================================================
        //   STEP 24 - CRUSADER ARMOR (6 tiers): from Initiate's Gambeson
        //   to the ultimate Stellar Archon Plate. Each tier reduces more
        //   incoming damage. Equip via RMB in the hotbar.
        // ============================================================
        private void BuildArmorContent()
        {
            const string ARMOR_FOLDER = ASSET_ROOT + "/Combat/Armor";
            EnsureFolder(ARMOR_FOLDER);

            ItemDefinition FindItem(string assetNameNoExt)
            {
                var guids = AssetDatabase.FindAssets(assetNameNoExt + " t:ItemDefinition");
                foreach (var g in guids)
                {
                    var pp = AssetDatabase.GUIDToAssetPath(g);
                    if (System.IO.Path.GetFileNameWithoutExtension(pp) == assetNameNoExt)
                        return AssetDatabase.LoadAssetAtPath<ItemDefinition>(pp);
                }
                return null;
            }
            var woodLog    = FindItem("Item_WoodLog");
            var plank      = FindItem("Item_WoodenPlank");
            var ironIngot  = FindItem("Item_IronIngot");
            var steelIngot = FindItem("Item_SteelIngot");
            var ironPlate  = FindItem("Item_IronPlate");
            var steelPlate = FindItem("Item_SteelPlate");
            var copperWire = FindItem("Item_CopperLVWire");
            var goldWire   = FindItem("Item_GoldLVWire");
            var circuit    = FindItem("Item_Circuit");
            var advCircuit = FindItem("Item_AdvancedCircuit") ?? FindItem("Item_AdvCircuit");

            VoxelEngine.Combat.ArmorItem MakeArmor(string assetName, string display, string desc, int tier, float reduction, Color tint)
            {
                string path = $"{ARMOR_FOLDER}/{assetName}.asset";
                bool existed = AssetDatabase.LoadAssetAtPath<VoxelEngine.Combat.ArmorItem>(path) != null;
                var armor = GetOrCreateAsset<VoxelEngine.Combat.ArmorItem>(path);
                if (!existed)
                {
                    armor.itemId = assetName.ToLowerInvariant();
                    armor.displayName = display;
                    armor.description = desc;
                    armor.tier = tier;
                    armor.damageReduction = reduction;
                    armor.iconTint = tint;
                    armor.maxStack = 1;
                    armor.massPerUnit = 2f + tier;
                    armor.category = "Armor";
                }
                else
                {
                    // Only repair missing identity data. Existing armor balance,
                    // descriptions, icons, tint, and mass remain designer-owned.
                    if (string.IsNullOrWhiteSpace(armor.itemId)) armor.itemId = assetName.ToLowerInvariant();
                    if (string.IsNullOrWhiteSpace(armor.displayName)) armor.displayName = display;
                    if (string.IsNullOrWhiteSpace(armor.description)) armor.description = desc;
                    if (armor.tier <= 0) armor.tier = tier;
                    if (armor.damageReduction <= 0f) armor.damageReduction = reduction;
                    if (armor.maxStack <= 0) armor.maxStack = 1;
                    if (armor.massPerUnit <= 0f) armor.massPerUnit = 2f + tier;
                    if (string.IsNullOrWhiteSpace(armor.category)) armor.category = "Armor";
                }
                EditorUtility.SetDirty(armor);
                return armor;
            }

            // ── 6 Tiers of Crusader Armor ──
            var t1 = MakeArmor("Armor_InitiateGambeson", "Initiate's Gambeson",
                "Quilted cloth of the newly sworn. Better than nothing — barely.",
                1, 0.08f, new Color(0.50f, 0.45f, 0.38f));
            var t2 = MakeArmor("Armor_SquireLeather", "Squire's Leather",
                "Boiled leather over padded gambeson. A squire's first real protection.",
                2, 0.15f, new Color(0.35f, 0.25f, 0.15f));
            var t3 = MakeArmor("Armor_KnightChainmail", "Knight's Chainmail",
                "Full chain hauberk under a tabard. The mark of a true Crusader Knight.",
                3, 0.25f, new Color(0.70f, 0.72f, 0.75f));
            var t4 = MakeArmor("Armor_TemplarPlate", "Templar's Plate",
                "Steel plate with heraldic surcoat. The Templar stands where others fall.",
                4, 0.38f, new Color(0.85f, 0.85f, 0.88f));
            var t5 = MakeArmor("Armor_PaladinBulwark", "Paladin's Bulwark",
                "Blessed reinforced plate with gold relic trim. Worn by the Order's finest.",
                5, 0.50f, new Color(0.88f, 0.80f, 0.30f));
            var t6 = MakeArmor("Armor_StellarArchon", "Stellar Archon Plate",
                "Sealed void-metal armour with glowing energy relays. Worthy of the strongest Crusaders — the pinnacle of the Order.",
                6, 0.62f, new Color(0.22f, 0.20f, 0.28f));

            // Step 48 owns recipe creation and all station/research wiring. Step 24
            // only repairs already-present armor recipe gating so rerunning this
            // legacy armor-definition step never overwrites recipe inputs or timing.
            foreach (var recipeName in new[]
            {
                "Recipe_Armor_InitiateGambeson",
                "Recipe_Armor_SquireLeather",
                "Recipe_Armor_KnightChainmail",
                "Recipe_Armor_TemplarPlate",
                "Recipe_Armor_PaladinBulwark",
                "Recipe_Armor_StellarArchon"
            })
            {
                var recipe = FindRecipeByName(recipeName);
                if (recipe == null) continue;
                recipe.requiredStation = VoxelEngine.Crafting.StationTier.ArmorStation;
                recipe.unlockedByDefault = false;
                EditorUtility.SetDirty(recipe);
            }

            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();
            EditorUtility.DisplayDialog("Voxel Engine — Crusader Armor (6 Tiers)",
                "Built/repaired 6 tiers of Crusader armor:\n\n" +
                "1. Initiate's Gambeson (8% reduction)\n" +
                "2. Squire's Leather (15%)\n" +
                "3. Knight's Chainmail (25%)\n" +
                "4. Templar's Plate (38%)\n" +
                "5. Paladin's Bulwark (50%)\n" +
                "6. Stellar Archon Plate (62%)\n\n" +
                "Armor recipes are now reserved for the Armor Station. Run Step 48 to generate or repair both armor stations, upgrade modules, research links, and timed anvil installation.\n" +
                "Equip: put armor in your hotbar, select it, and press RMB. Old armor returns to your inventory with installed upgrades intact.",
                "OK");
        }


        // ============================================================
        //   STEP 49 - ATMOSPHERE + SPACE PROFILES
        //   Initializes only bodies that do not yet carry a profile. The
        //   runtime has a legacy fallback, but this authors the intended
        //   thin/toxic/airless distinctions through the setup workflow.
        // ============================================================
        private void BuildAtmosphereSpaceProfiles()
        {
            const int ProfileVersion = 1;
            int initialized = 0;
            int preserved = 0;

            void Initialize(BodySettings body, UnityEngine.Object owner)
            {
                if (body == null || owner == null) return;

                // A prior setup run or a hand-authored non-zero profile owns these values.
                bool hasExplicitValues = body.surfaceAtmosphereDensity > 0.0001f
                    || body.atmosphereHeightRadiusFraction > 0.0001f
                    || body.atmosphereScaleHeightRadiusFraction > 0.0001f;
                if (body.atmosphereProfileVersion >= ProfileVersion || hasExplicitValues)
                {
                    if (body.atmosphereProfileVersion < ProfileVersion)
                    {
                        body.atmosphereProfileVersion = ProfileVersion;
                        EditorUtility.SetDirty(owner);
                    }
                    preserved++;
                    return;
                }

                string name = (body.bodyName ?? string.Empty).ToLowerInvariant();
                float density;
                float heightFraction;
                float scaleFraction;

                if (name.Contains("moon") || name.Contains("lunar"))
                {
                    density = 0f;
                    heightFraction = 0f;
                    scaleFraction = 0f;
                }
                else if (name.Contains("venus"))
                {
                    // Dense but non-breathable pressure atmosphere.
                    density = 2.40f;
                    heightFraction = 0.90f;
                    scaleFraction = 0.22f;
                }
                else if (name.Contains("mars"))
                {
                    density = 0.025f;
                    heightFraction = 0.48f;
                    scaleFraction = 0.09f;
                }
                else if (name.Contains("volcan"))
                {
                    density = 1.10f;
                    heightFraction = 0.70f;
                    scaleFraction = 0.16f;
                }
                else if (name.Contains("acid"))
                {
                    density = 0.55f;
                    heightFraction = 0.66f;
                    scaleFraction = 0.14f;
                }
                else if (name.Contains("ice") || name.Contains("frozen"))
                {
                    density = 0.18f;
                    heightFraction = 0.56f;
                    scaleFraction = 0.11f;
                }
                else if (name.Contains("desolate"))
                {
                    density = 0.06f;
                    heightFraction = 0.38f;
                    scaleFraction = 0.07f;
                }
                else if (name.Contains("crystal"))
                {
                    density = 0.35f;
                    heightFraction = 0.58f;
                    scaleFraction = 0.12f;
                }
                else
                {
                    // Earth-like and other existing oxygen worlds retain their previous
                    // practical density through a profile that scales with runtime radius.
                    density = body.HasOxygen ? 1.225f * Mathf.Clamp01(body.oxygenLevel) : 0f;
                    heightFraction = density > 0.0001f ? 0.62f : 0f;
                    scaleFraction = density > 0.0001f ? 0.15f : 0f;
                }

                body.surfaceAtmosphereDensity = density;
                body.atmosphereHeightRadiusFraction = heightFraction;
                body.atmosphereScaleHeightRadiusFraction = scaleFraction;
                body.atmosphereProfileVersion = ProfileVersion;
                EditorUtility.SetDirty(owner);
                initialized++;
            }

            foreach (string guid in AssetDatabase.FindAssets("t:PlanetTemplate"))
            {
                string path = AssetDatabase.GUIDToAssetPath(guid);
                var planet = AssetDatabase.LoadAssetAtPath<PlanetTemplate>(path);
                if (planet != null) Initialize(planet.body, planet);
            }
            foreach (string guid in AssetDatabase.FindAssets("t:MoonTemplate"))
            {
                string path = AssetDatabase.GUIDToAssetPath(guid);
                var moon = AssetDatabase.LoadAssetAtPath<MoonTemplate>(path);
                if (moon != null) Initialize(moon.body, moon);
            }

            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();
            EditorUtility.DisplayDialog("Voxel Engine — Atmosphere + Space Profiles",
                "Atmosphere profiles initialized:\n\n" +
                "• " + initialized + " bodies initialized\n" +
                "• " + preserved + " existing profiles preserved\n\n" +
                "Atmospheric thrust, aerodynamic drag, jetpack environment checks, life support, and cockpit altitude now share one profile-driven transition.\n\n" +
                "Run this step again after adding celestial templates; initialized profile values remain untouched.",
                "OK");
        }

        // ============================================================
        //   STEP 50 - WARP DRIVE (real-space travel)
        //   Item + prefab + recipe + research, fully non-destructive.
        //   The Warp Drive is the ONLY warp in the game: an expensive,
        //   chargeable grid block gated behind research.
        // ============================================================
        private void BuildWarpDriveContent()
        {
            const string GRID_ROOT = ASSET_ROOT + "/GridSystem";
            const string ITEMS     = GRID_ROOT + "/Items";
            const string PREFABS   = GRID_ROOT + "/Prefabs";
            const string RECIPES   = GRID_ROOT + "/Recipes";
            const string NODES     = ASSET_ROOT + "/Research/Nodes";
            foreach (var f in new[] { GRID_ROOT, ITEMS, PREFABS, RECIPES }) EnsureFolder(f);

            // ── Dependencies (existing setup-owned assets, never recreated) ──
            string craftItems = ASSET_ROOT + "/Items";
            string indItems   = ASSET_ROOT + "/Industrial/Items";
            var steelPlate  = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{indItems}/Item_SteelPlate.asset");
            var advCircuit  = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{indItems}/Item_AdvCircuit.asset");
            var uraniumOre  = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{craftItems}/Item_Uranium.asset");
            var lithium     = EnsureLithiumResource();
            var sciT2       = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{craftItems}/Item_ScienceT2.asset");
            var sciT3       = AssetDatabase.LoadAssetAtPath<VoxelEngine.Items.ItemDefinition>($"{craftItems}/Item_ScienceT3.asset");

            // ── Prefab (non-destructive: existing drive tuning is preserved) ──
            string prefabPath = $"{PREFABS}/WarpDrive_Large.prefab";
            var warpPrefab = GetOrCreatePrefab(prefabPath, "WarpDrive_Large", (root) =>
            {
                var drive = root.GetComponent<VoxelEngine.GridSystem.GridWarpDrive>();
                if (drive == null) drive = root.AddComponent<VoxelEngine.GridSystem.GridWarpDrive>();

                // Connect identity fields ALWAYS; only tune numbers when they are at their
                // script defaults so designer balance tweaks survive re-runs.
                drive.blockName = "Warp Drive";
                if (drive.chargeSeconds <= 0f) drive.chargeSeconds = 45f;
                if (drive.powerDrawWatts <= 0f) drive.powerDrawWatts = 45000f;
                if (drive.cooldownSeconds <= 0f) drive.cooldownSeconds = 180f;
                if (drive.jumpRangeKm <= 0f) drive.jumpRangeKm = 2500f;
                if (drive.arrivalAltitudeKm <= 0f) drive.arrivalAltitudeKm = 90f;

                // Visual: industrial drive housing + glowing core. Rebuilt ONLY when the
                // prefab has no visual yet — designer-customised visuals survive re-runs.
                if (root.transform.childCount == 0 && root.GetComponent<MeshFilter>() == null)
                {
                    var core = GameObject.CreatePrimitive(PrimitiveType.Cube);
                    core.name = "Core";
                    core.transform.SetParent(root.transform, false);
                    core.transform.localScale = new Vector3(0.55f, 0.55f, 0.55f);
                    UnityEngine.Object.DestroyImmediate(core.GetComponent<Collider>());
                    var coreMat = MakeColoredMat(PREFABS + "/Mats", "Mat_WarpDriveCore", new Color(0.30f, 0.55f, 0.95f, 1f));
                    core.GetComponent<Renderer>().sharedMaterial = coreMat;

                    var ring = GameObject.CreatePrimitive(PrimitiveType.Cylinder);
                    ring.name = "Coil";
                    ring.transform.SetParent(root.transform, false);
                    ring.transform.localRotation = Quaternion.Euler(90f, 0f, 0f);
                    ring.transform.localScale = new Vector3(0.9f, 0.12f, 0.9f);
                    UnityEngine.Object.DestroyImmediate(ring.GetComponent<Collider>());
                    ring.GetComponent<Renderer>().sharedMaterial =
                        MakeColoredMat(PREFABS + "/Mats", "Mat_WarpDriveCoil", new Color(0.75f, 0.78f, 0.85f, 1f));
                }

                var bcol = root.GetComponent<BoxCollider>();
                if (bcol == null) bcol = root.AddComponent<BoxCollider>();
                bcol.size = Vector3.one * VoxelEngine.GridSystem.GridSizeExt.CellSize(VoxelEngine.GridSystem.GridSize.Large);
            });

            // ── Item (non-destructive) ──
            string itemPath = $"{ITEMS}/GItem_WarpDrive.asset";
            var item = AssetDatabase.LoadAssetAtPath<VoxelEngine.GridSystem.GridBlockItem>(itemPath);
            if (item == null)
            {
                item = ScriptableObject.CreateInstance<VoxelEngine.GridSystem.GridBlockItem>();
                AssetDatabase.CreateAsset(item, itemPath);
            }
            item.itemId = "gitem_warpdrive";
            item.displayName = "Warp Drive";
            item.description = "The ONLY warp in the game. Charges over 45 seconds under a heavy power load, then jumps the ship to the aimed planet's orbit (or a fixed 2500 km ahead). Requires vacuum, a pilot, and Warp Drive research. Build real rockets for honest interplanetary flight — this is the expensive shortcut.";
            item.iconTint = new Color(0.30f, 0.55f, 0.95f);
            item.maxStack = 20;
            item.gridSize = VoxelEngine.GridSystem.GridSize.Large;
            item.blockPrefab = warpPrefab;
            item.blockMass = 2600f;
            item.blockHP = 2600f;
            item.category = "Grid Blocks";
            EditorUtility.SetDirty(item);

            // ── Recipe (non-destructive append) ──
            string recipePath = $"{RECIPES}/Recipe_GWarpDrive.asset";
            var recipe = GetOrCreateAsset<VoxelEngine.Crafting.RecipeDefinition>(recipePath);
            recipe.displayName = "Warp Drive";
            recipe.outputItem = item;
            recipe.outputCount = 1;
            recipe.requiredStation = VoxelEngine.Crafting.StationTier.Assembler;
            recipe.craftSeconds = 30f;
            recipe.unlockedByDefault = false;
            var inputs = new System.Collections.Generic.List<VoxelEngine.Crafting.RecipeIngredient>();
            if (steelPlate != null) inputs.Add(new VoxelEngine.Crafting.RecipeIngredient { item = steelPlate, count = 40 });
            if (advCircuit != null) inputs.Add(new VoxelEngine.Crafting.RecipeIngredient { item = advCircuit, count = 12 });
            if (uraniumOre != null) inputs.Add(new VoxelEngine.Crafting.RecipeIngredient { item = uraniumOre, count = 8 });
            if (lithium != null)    inputs.Add(new VoxelEngine.Crafting.RecipeIngredient { item = lithium, count = 6 });
            recipe.inputs = inputs.ToArray();
            EditorUtility.SetDirty(recipe);

            var recipeRegistry = AssetDatabase.LoadAssetAtPath<VoxelEngine.Crafting.RecipeRegistry>($"{ASSET_ROOT}/RecipeRegistry.asset");
            if (recipeRegistry != null && !recipeRegistry.recipes.Contains(recipe))
            {
                recipeRegistry.recipes.Add(recipe);
                EditorUtility.SetDirty(recipeRegistry);
            }

            // ── Research (non-destructive: only creates the node if missing) ──
            var tree = AssetDatabase.LoadAssetAtPath<VoxelEngine.Research.ResearchTree>($"{ASSET_ROOT}/Research/ResearchTree.asset");
            if (tree != null)
            {
                var node = FindNodeByName(tree, "res_warpdrive");
                if (node == null)
                {
                    node = ScriptableObject.CreateInstance<VoxelEngine.Research.ResearchNode>();
                    node.nodeId = "res_warpdrive";
                    node.displayName = "Warp Drive";
                    node.description = "Unlocks the Warp Drive grid block — the only warp in the game. Charges under heavy power, then jumps the ship to the aimed planet's orbit. Expensive, gated, and never free.";
                    node.category = VoxelEngine.Research.ResearchCategory.Environment;
                    node.subCategory = VoxelEngine.Research.ResearchSubCategory.Building;
                    node.tier = 7;
                    node.column = 6;
                    node.iconTint = new Color(0.30f, 0.55f, 0.95f);
                    node.researchSeconds = 900f;
                    node.cost = new[]
                    {
                        new VoxelEngine.Research.ResearchNode.ScienceCost { pack = sciT2 as VoxelEngine.Items.ScienceItem, count = 120 },
                        new VoxelEngine.Research.ResearchNode.ScienceCost { pack = sciT3 as VoxelEngine.Items.ScienceItem, count = 60 },
                    };
                    var shipbuilding = FindNodeByName(tree, "res_shipbuilding");
                    if (shipbuilding != null) node.prerequisites = new[] { shipbuilding };
                    AssetDatabase.CreateAsset(node, $"{NODES}/res_warpdrive.asset");
                    tree.nodes.Add(node);
                }
                node.unlocksRecipes = new VoxelEngine.Crafting.RecipeDefinition[] { recipe };
                EditorUtility.SetDirty(node);
                EditorUtility.SetDirty(tree);
                VoxelEngine.Research.ResearchRecipeLinker.Register("res_warpdrive", recipe);
            }

            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();
            EditorUtility.DisplayDialog("Voxel Engine — Warp Drive",
                "Warp Drive wired (non-destructive):\n\n" +
                "• Prefab: " + prefabPath + "\n" +
                "• Item: GItem_WarpDrive (Grid Blocks)\n" +
                "• Recipe: 40 Steel Plate + 12 Advanced Circuit + 8 Uranium Ore + 6 Lithium @ Assembler\n" +
                "• Research: Warp Drive (tier 7) after Shipbuilding\n\n" +
                "In-game: place it on a ship, fly to space, press [N] in the cockpit to charge (45 s, 45 kW), then press [N] again to jump to the aimed planet — or 2500 km straight ahead. It is the ONLY warp in the game; everything else is real flight.",
                "OK");
        }

    }
}
#endif
